# ── Structured JSON Formatter ─────────────────────────────────────────────────
class StructuredFormatter(logging.Formatter):
    """Format logs as JSON for machine-readable structured logging."""
    
    def format(self, record: logging.LogRecord) -> str:
        log_data = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
            "module": record.module,
            "function": record.funcName,
            "line": record.lineno,
        }
        
        # Add exception info if present
        if record.exc_info and record.exc_info[0] is not None:
            log_data["exception"] = {
                "type": record.exc_info[0].__name__,
                "message": str(record.exc_info[1]),
                "traceback": traceback.format_exception(*record.exc_info),
            }
        
        # Add custom fields if present
        if hasattr(record, "context"):
            log_data["context"] = record.context
        
        if hasattr(record, "user_id"):
            log_data["user_id"] = record.user_id
        
        if hasattr(record, "chat_id"):
            log_data["chat_id"] = record.chat_id
        
        return json.dumps(log_data, ensure_ascii=False, default=str)


# ── ANSI color codes ──────────────────────────────────────────────────────────
class _Color:
    RESET = "\033[0m"
    BOLD = "\033[1m"
    DIM = "\033[2m"
    RED = "\033[91m"
    GREEN = "\033[92m"
    YELLOW = "\033[93m"
    CYAN = "\033[96m"
    GREY = "\033[90m"
    BOLD_RED = "\033[1;91m"

_LEVEL_STYLE = {
    "DEBUG":    (_Color.DIM + _Color.CYAN,    "◆"),
    "INFO":     (_Color.GREEN,                 "✓"),
    "WARNING":  (_Color.YELLOW,                "⚠"),
    "ERROR":    (_Color.RED,                   "✗"),
    "CRITICAL": (_Color.BOLD_RED,              "☠"),
}


# ── Human-Readable Formatter (for development) ────────────────────────────────
class HumanReadableFormatter(logging.Formatter):
    """Format logs in a clean human-readable way for development/console output."""

    def _short_name(self, name: str) -> str:
        parts = name.split(".")
        if len(parts) <= 2:
            return name
        return ".".join(parts[-2:])

    def format(self, record: logging.LogRecord) -> str:
        ts = self.formatTime(record, self.datefmt)[11:]  # HH:MM:SS only
        level_name = record.levelname
        color, icon = _LEVEL_STYLE.get(level_name, (_Color.RESET, "?"))
        short = self._short_name(record.name)
        msg = record.getMessage()

        if record.exc_info and record.exc_info[0] is not None:
            tb = "".join(traceback.format_exception(*record.exc_info))
            tb_indent = tb.replace("\n", "\n" + " " * 21)
            return (
                f"{_Color.GREY}{ts}{_Color.RESET} "
                f"{color}{icon}{_Color.RESET} "
                f"{_Color.DIM}{short:<20}{_Color.RESET} "
                f"{color}{msg}{_Color.RESET}\n"
                f"{'':>21}{_Color.DIM}{tb_indent}{_Color.RESET}"
            )

        return (
            f"{_Color.GREY}{ts}{_Color.RESET} "
            f"{color}{icon}{_Color.RESET} "
            f"{_Color.DIM}{short:<20}{_Color.RESET} "
            f"{msg}"
        )


# ── Error Tracker ─────────────────────────────────────────────────────────────
class ErrorTracker:
    """
    Track and deduplicate errors to prevent alert fatigue.
    Groups similar errors and only alerts on new patterns.
    """
    
    def __init__(self, max_entries: int = 1000):
        self._errors: Dict[str, Dict[str, Any]] = {}
        self._max_entries = max_entries
        self._lock = threading.Lock()

    
    def _error_key(self, error_type: str, module: str) -> str:
        return f"{module}:{error_type}"
    
    def record_error(
        self,
        error: Exception,
        context: Optional[Dict[str, Any]] = None,
        user_id: Optional[int] = None,
        chat_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        """
        Record an error and return tracking info.
        Returns dict with is_new (bool) and count.
        """
        error_type = type(error).__name__
        module = context.get("module", "unknown") if context else "unknown"
        key = self._error_key(error_type, module)
        
        with self._lock:
            if key in self._errors:
                self._errors[key]["count"] += 1
                self._errors[key]["last_seen"] = datetime.now(timezone.utc).isoformat()
                return {"is_new": False, "count": self._errors[key]["count"]}
            
            # Cap entries
            if len(self._errors) >= self._max_entries:
                # Remove oldest entry
                oldest_key = min(self._errors.keys(), key=lambda k: self._errors[k]["first_seen"])
                del self._errors[oldest_key]
            
            self._errors[key] = {
                "error_type": error_type,
                "module": module,
                "message": str(error),
                "context": context or {},
                "user_id": user_id,
                "chat_id": chat_id,
                "count": 1,
                "first_seen": datetime.now(timezone.utc).isoformat(),
                "last_seen": datetime.now(timezone.utc).isoformat(),
            }
            
            return {"is_new": True, "count": 1}

    
    def get_summary(self) -> Dict[str, Any]:
        """Get summary of tracked errors."""
        with self._lock:
            return {
                "total_unique_errors": len(self._errors),
                "total_occurrences": sum(e["count"] for e in self._errors.values()),
                "top_errors": sorted(
                    self._errors.values(),
                    key=lambda x: x["count"],
                    reverse=True,
                )[:10],
            }

    
    def clear(self) -> None:
        """Clear all tracked errors."""
        with self._lock:
            self._errors.clear()



# Global error tracker instance
ERROR_TRACKER = ErrorTracker()
_LOG_LISTENER: Optional[logging.handlers.QueueListener] = None


def _default_log_level(level: int) -> int:
    env_level = os.getenv("ANYY_LOG_LEVEL")
    if env_level:
        return getattr(logging, env_level.upper(), level)
    if "pytest" in sys.modules or os.getenv("PYTEST_CURRENT_TEST"):
        return logging.WARNING
    return level


# ── Logging Setup ─────────────────────────────────────────────────────────────
def setup_logging(
    level: int = logging.INFO,
    structured: bool = False,
    log_file: Optional[str] = None,
) -> None:
    """
    Configure application-wide logging.
    
    Args:
        level: Logging level (DEBUG, INFO, WARNING, ERROR)
        structured: Use JSON structured format (for production)
        log_file: Optional log file path
    """
    global _LOG_LISTENER
    if _LOG_LISTENER is not None:
        try:
            _LOG_LISTENER.stop()
        except Exception:
            logging.getLogger(__name__).error("Unexpected error", exc_info=True)
        _LOG_LISTENER = None

    # Clear existing handlers
    root_logger = logging.getLogger()
    root_logger.handlers.clear()
    
    # Set level - always enable DEBUG for comprehensive logging including HTTP requests
    # This ensures httpx HTTP request/response logs are visible
    debug_enabled = os.getenv("DEBUG", "0") == "1"
    root_logger.setLevel(logging.DEBUG if debug_enabled else _default_log_level(level))
    
    # Choose formatter
    formatter = StructuredFormatter() if structured else HumanReadableFormatter(
        fmt=None,  # We override format() completely
        datefmt="%Y-%m-%d %H:%M:%S",
    )
    
    listener_handlers = []

    # Console handler
    console_handler = logging.StreamHandler(sys.stdout)
    console_level_name = os.getenv("ANYY_CONSOLE_LOG_LEVEL", logging.getLevelName(level))
    console_handler.setLevel(getattr(logging, str(console_level_name).upper(), level))
    console_handler.setFormatter(formatter)
    listener_handlers.append(console_handler)
    
    # File handler (optional)
    if log_file:
        Path(log_file).parent.mkdir(parents=True, exist_ok=True)
        file_handler = logging.FileHandler(log_file, encoding="utf-8")
        file_handler.setLevel(logging.DEBUG)  # Log everything to file
        file_handler.setFormatter(formatter)
        listener_handlers.append(file_handler)

    log_queue: queue.SimpleQueue = queue.SimpleQueue()
    queue_handler = logging.handlers.QueueHandler(log_queue)
    queue_handler.setLevel(logging.DEBUG)
    root_logger.addHandler(queue_handler)
    _LOG_LISTENER = logging.handlers.QueueListener(
        log_queue,
        *listener_handlers,
        respect_handler_level=True,
    )
    _LOG_LISTENER.start()
    
    # Configure httpx logging — INFO shows API calls cleanly without raw TCP noise
    httpx_logger = logging.getLogger("httpx")
    httpx_logger.setLevel(logging.INFO)
    httpx_logger.propagate = True

    # ── Bot Token Masking Filter ──
    # Replaces the real bot token with a fake one in all httpx log output
    # so it never appears in console or log files, even in DEBUG mode
    _bot_token_re = _re.compile(r'bot\d{8,12}:[A-Za-z0-9_-]{35,}', _re.IGNORECASE)

    class _BotTokenMaskFilter(logging.Filter):
        def filter(self, record: logging.LogRecord) -> bool:
            try:
                msg = str(record.getMessage())
                if _bot_token_re.search(msg):
                    masked = _bot_token_re.sub('bot9999999999:FAKE_TOKEN_HIDDEN', msg)
                    record.msg = masked
                    record.args = ()
            except Exception:
                logger.warning("Exception in filter", exc_info=True)
            return True

    _tok_filter = _BotTokenMaskFilter()
    httpx_logger.addFilter(_tok_filter)
    root_logger.addFilter(_tok_filter)

    # Silence raw httpcore TCP/TLS noise (connect_tcp, start_tls, send_request_headers etc)
    for _noisy in ("httpcore", "httpcore.connection", "httpcore.http11", "httpcore.http2",
                   "httpx.client", "httpx.http11"):
        logging.getLogger(_noisy).setLevel(logging.WARNING)
        logging.getLogger(_noisy).propagate = True

    logging.getLogger("telegram").setLevel(logging.WARNING)
    logging.getLogger("apscheduler").setLevel(logging.ERROR)
    logging.getLogger("werkzeug").setLevel(logging.ERROR)
    logging.getLogger("pymongo").setLevel(logging.WARNING)
    logging.getLogger("urllib3").setLevel(logging.WARNING)
    logging.getLogger("asyncio").setLevel(logging.WARNING)


# ── Convenience Functions ────────────────────────────────────────────────────
def get_logger(name: str) -> logging.Logger:
    """
    Get a logger instance for a module.
    
    Usage:
        logger = get_logger(__name__)
        logger.info("Something happened", extra={"user_id": 123})
    """
    return logging.getLogger(name)


def log_error(
    error: Exception,
    logger: Optional[logging.Logger] = None,
    context: Optional[Dict[str, Any]] = None,
    user_id: Optional[int] = None,
    chat_id: Optional[int] = None,
    silent: bool = False,
) -> Dict[str, Any]:
    """
    Log an error with context and track it.
    
    Args:
        error: The exception that occurred
        logger: Logger to use (creates one from context if not provided)
        context: Additional context about the error
        user_id: User ID if relevant
        chat_id: Chat ID if relevant
        silent: Don't log to console, just track
    
    Returns:
        Dict with error tracking info
    """
    if logger is None:
        module = context.get("module", "unknown") if context else "unknown"
        logger = get_logger(module)
    
    # Track error
    tracking_info = ERROR_TRACKER.record_error(
        error, context=context, user_id=user_id, chat_id=chat_id
    )
    
    # Log error (unless silent and not new)
    if not (silent and not tracking_info["is_new"]):
        log_method = logger.error if tracking_info["is_new"] else logger.warning
        
        extra = {
            "context": context or {},
            "user_id": user_id,
            "chat_id": chat_id,
        }
        
        if tracking_info["is_new"]:
            log_method(
                f"⚠️ NEW ERROR: {type(error).__name__}: {error} "
                f"(count: {tracking_info['count']})",
                exc_info=error,
                extra=extra,
            )
        else:
            log_method(
                f"⚠️ RECURRING ERROR: {type(error).__name__} "
                f"(count: {tracking_info['count']})",
                extra=extra,
            )
    
    return tracking_info


def log_command_execution(
    command: str,
    user_id: int,
    chat_id: int,
    chat_type: str,
    duration_ms: Optional[float] = None,
    success: bool = True,
    error: Optional[Exception] = None,
) -> None:
    """Log command execution with metrics."""
    logger = get_logger("commands")
    
    extra = {
        "context": {
            "command": command,
            "chat_type": chat_type,
            "duration_ms": duration_ms,
            "success": success,
        },
        "user_id": user_id,
        "chat_id": chat_id,
    }
    
    if success:
        logger.info(
            f"✅ {command} executed by {user_id} in {chat_type} ({chat_id})",
            extra=extra,
        )
    else:
        logger.error(
            f"⚠️ {command} failed for {user_id} in {chat_type} ({chat_id}): {error}",
            exc_info=error,
            extra=extra,
        )


