@atexit.register
def _stop_log_listener() -> None:
    global _LOG_LISTENER
    if _LOG_LISTENER is not None:
        try:
            _LOG_LISTENER.stop()
        except Exception:
            logger.warning("Exception in _stop_log_listener", exc_info=True)
        _LOG_LISTENER = None

