def validate_runtime_config() -> None:
    """Validate that all required configuration is present."""
    missing = []
    
    # Essential bot configuration
    if not BOT_TOKEN:
        missing.append("BOT_TOKEN")
    if not OWNER_ID:
        missing.append("OWNER_ID")
    if not BOT_USERNAME:
        missing.append("BOT_USERNAME")
    
    # Database configuration. MongoDB is disabled by default (TiDB-only store);
    # only require Mongo URIs when MongoDB is explicitly enabled.
    if MONGO_ENABLED and not ANYY_LOCAL_DEVICE and not MONGO_USE_LOCAL and not MONGO_URI_SLOTS:
        missing.append("MONGO_URI_SLOTS")

    if missing:
        # Never crash on missing config during import/compile — just warn
        # The bot will handle missing config gracefully at runtime via .env
        error_msg = f"Missing runtime config (will use .env at runtime): {', '.join(missing)}"
        try:
            logger.warning(error_msg)
        except Exception:
            pass
        return
    
    # Additional warnings for optional but recommended configurations
    import warnings as pywarnings
    if not GROQ_API_KEY:
        pywarnings.warn("GROQ_API_KEY is empty - AI features may be limited", RuntimeWarning)
    if not DEEPSEEK_API_KEY:
        pywarnings.warn("DEEPSEEK_API_KEY is empty - DeepSeek AI features disabled", RuntimeWarning)
    if not GEMINI_API_KEY:
        pywarnings.warn("GEMINI_API_KEY is empty - Gemini AI features disabled", RuntimeWarning)
    if not CLOUDFLARE_SECRET_KEY:
        pywarnings.warn("CLOUDFLARE_SECRET_KEY is empty - Web verification disabled", RuntimeWarning)

