# ═══ MODULE: database.limit_manager ═══

import os
import time
import json
import threading
from datetime import datetime, date
from typing import Any, Optional

logger = get_logger(__name__)

# ── Free Tier Limits ──────────────────────────────────────────────
# TiDB Serverless Free: 50M RU/month per cluster × 5 clusters
TIDB_MONTHLY_RU = 250_000_000
TIDB_DAILY_RU = TIDB_MONTHLY_RU // 30  # 8,333,333
TIDB_SUSTAINED_RU_PER_SEC = TIDB_DAILY_RU // 86400  # ~96
# MongoDB Atlas M0 Free: 512 MB storage per cluster
MONGO_FREE_STORAGE_MB = 512
MONGO_SAFE_PCT = 88  # Start throttling at 88% (was 94%)
MONGO_CRITICAL_PCT = 95  # Emergency mode at 95%

# ── Tier thresholds for adaptive behavior ─────────────────────────
BUDGET_TIERS = [
    ("critical", 0.98, 2.0),    # >98% used = heavy throttle, emergency mode
    ("tight", 0.90, 0.5),       # >90% used = moderate throttle
    ("warn", 0.80, 0.1),        # >80% used = light throttle
    ("normal", 0.0, 0.0),       # <80% used = no throttle
]


class BudgetTracker:
    def __init__(self):
        self._daily_used: int = 0
        self._daily_date: str = ""
        self._lock = threading.RLock()
        self._persist_key = "__budget_tracker__"
        self._load()

    def _load(self):
        try:
            raw = get_setting(self._persist_key, "")
            if raw:
                parts = str(raw).split("|")
                if len(parts) == 3:
                    d, u, m = parts
                    today = date.today().isoformat()
                    if d == today:
                        self._daily_date = d
                        self._daily_used = int(u)
        except Exception:
            pass

    def _save(self):
        try:
            save_setting(self._persist_key, f"{self._daily_date}|{self._daily_used}|{int(time.time())}")
        except Exception:
            pass

    def record_ru(self, amount: int) -> dict:
        with self._lock:
            today = date.today().isoformat()
            if self._daily_date != today:
                self._daily_date = today
                self._daily_used = 0
            self._daily_used += amount
            used = self._daily_used
            if self._daily_used % 2000 < amount:
                self._save()
        pct = used / max(TIDB_DAILY_RU, 1)
        tier = "normal"
        throttle = 0.0
        for t_name, t_pct, t_delay in BUDGET_TIERS:
            if pct >= t_pct:
                tier = t_name
                throttle = t_delay
                break
        return {"tier": tier, "used_ru": used, "daily_budget": TIDB_DAILY_RU, "pct": round(pct * 100, 1), "throttle_sec": throttle}

    def status(self) -> dict:
        with self._lock:
            pct = self._daily_used / max(TIDB_DAILY_RU, 1)
            tier = "normal"
            for t_name, t_pct, _ in BUDGET_TIERS:
                if pct >= t_pct:
                    tier = t_name
                    break
            return {
                "date": self._daily_date,
                "used_ru": self._daily_used,
                "daily_budget": TIDB_DAILY_RU,
                "pct": round(pct * 100, 1),
                "tier": tier,
                "remaining_ru": max(0, TIDB_DAILY_RU - self._daily_used),
                "sustained_ru_per_sec": TIDB_SUSTAINED_RU_PER_SEC,
            }

    @property
    def is_emergency(self) -> bool:
        with self._lock:
            return self._daily_used >= TIDB_DAILY_RU * 0.98

    @property
    def remaining_ru(self) -> int:
        with self._lock:
            return max(0, TIDB_DAILY_RU - self._daily_used)


class MongoStorageTracker:
    def __init__(self):
        self._lock = threading.RLock()

    def per_slot_status(self) -> list[dict]:
        slots = []
        for slot in _mongo_slots:
            usage_pct = slot.get("usage_percent", 0) or 0
            limit_mb = slot.get("limit_mb", MONGO_FREE_STORAGE_MB) or MONGO_FREE_STORAGE_MB
            tier = "normal"
            if usage_pct >= MONGO_CRITICAL_PCT:
                tier = "critical"
            elif usage_pct >= MONGO_SAFE_PCT:
                tier = "tight"
            elif usage_pct >= MONGO_SAFE_PCT - 10:
                tier = "warn"
            slots.append({
                "slot_id": slot.get("slot_id"),
                "ok": slot.get("ok", False),
                "usage_percent": usage_pct,
                "usage_mb": round((slot.get("usage_bytes", 0) or 0) / (1024 * 1024), 1),
                "limit_mb": limit_mb,
                "tier": tier,
                "full": slot.get("full", False),
                "category": slot.get("category", "general"),
            })
        return slots

    def should_skip_write(self, slot_id: int) -> bool:
        for s in self.per_slot_status():
            if s["slot_id"] == slot_id and s["tier"] == "critical":
                return True
        return False

    def best_slot_for_write(self, purpose: str = "users") -> Optional[int]:
        for slot in _writable_mongo_slots_for_purpose(purpose):
            usage = slot.get("usage_percent", 0) or 0
            if usage < MONGO_SAFE_PCT:
                return slot.get("slot_id")
        return None


# ── Global instances ──────────────────────────────────────────────
_budget = BudgetTracker()
_mongo_tracker = MongoStorageTracker()


def get_budget() -> BudgetTracker:
    return _budget


def get_mongo_tracker() -> MongoStorageTracker:
    return _mongo_tracker


# ── Adaptive operation helpers ────────────────────────────────────

def should_skip_noncritical_write() -> bool:
    """Skip non-critical writes (log/analytics) when budget is tight."""
    return _budget.is_emergency


def should_use_lightweight_query() -> bool:
    """Use column-pruned SELECTs and skip _c blob when budget is tight."""
    return _budget.remaining_ru < TIDB_DAILY_RU * 0.15


def write_priority_level() -> str:
    """Returns 'high', 'normal', or 'low' based on remaining budget.
    'low' means only essential user data writes should proceed."""
    if _budget.is_emergency:
        return "low"
    pct = _budget.status()["pct"]
    if pct > 90:
        return "low"
    if pct > 75:
        return "normal"
    return "high"


def optimize_ru_cost(current_ru: int) -> int:
    """Reduce RU cost estimate when budget is tight (penalize expensive ops)."""
    status = _budget.status()
    pct = status["pct"]
    if pct > 95:
        return int(current_ru * 3)
    if pct > 85:
        return int(current_ru * 2)
    if pct > 70:
        return int(current_ru * 1.3)
    return current_ru


# ── Full limit report ─────────────────────────────────────────────

def full_limit_report() -> dict:
    budget_status = _budget.status()
    mongo_slots = _mongo_tracker.per_slot_status()

    mongo_critical = [s for s in mongo_slots if s["tier"] == "critical"]
    mongo_tight = [s for s in mongo_slots if s["tier"] == "tight"]

    return {
        "timestamp": time.time(),
        "tidb": {
            "daily_ru_used": budget_status["used_ru"],
            "daily_ru_budget": budget_status["daily_budget"],
            "pct": budget_status["pct"],
            "tier": budget_status["tier"],
            "remaining_ru": budget_status["remaining_ru"],
            "sustained_ru_per_sec": budget_status["sustained_ru_per_sec"],
        },
        "mongo": {
            "slots": mongo_slots,
            "critical_count": len(mongo_critical),
            "tight_count": len(mongo_tight),
            "safe_pct": MONGO_SAFE_PCT,
            "critical_pct": MONGO_CRITICAL_PCT,
        },
        "write_priority": write_priority_level(),
    }

