# ── Progressive TiDB Cluster Scaling ─────────────────────────────────
# Start with 1 cluster. When a cluster reaches capacity threshold,
# a new cluster is provisioned and users are migrated.
# TiDB Cloud Starter (free tier) limits per instance:
#   - Row storage (OLTP): 5 GiB
#   - Columnar storage (OLAP): 5 GiB
#   - Total: 10 GiB per instance
#   - Max 5 free instances per organization
TIDB_STORAGE_THRESHOLD_PCT = 90          # Scale at 90% of 5 GiB = 4.5 GiB
TIDB_ROW_STORAGE_LIMIT_MB = 5 * 1024     # 5 GiB = 5120 MiB (free tier row limit)
TIDB_COL_STORAGE_LIMIT_MB = 5 * 1024     # 5 GiB = 5120 MiB (free tier columnar limit)
TIDB_TOTAL_STORAGE_LIMIT_MB = 10 * 1024  # 10 GiB total per instance
TIDB_RU_THRESHOLD_PCT = 80               # RU budget threshold
TIDB_RU_BUDGET_PER_CLUSTER = 50_000_000  # 50M RU/month free tier
TIDB_MIN_USERS_PER_CLUSTER = 50000       # Minimum users before allowing new cluster
TIDB_MAX_FREE_CLUSTERS = 5               # Free tier max per org
TIDB_MAX_PAID_CLUSTERS = 10              # Hard cap if paid

TIDB_INITIAL_CLUSTERS = 1

TIDB_SLOTS = []  # Populated dynamically from tidb_config.json

# Credentials loaded from env — never hardcode secrets in source
_SSL = {
    "ssl_verify_cert": True,
    "ssl_verify_identity": True,
    "ssl_ca": "",
}

# Base credentials template (per-cluster overrides via env)
TIDB_CREDENTIALS_TEMPLATE = {
    "host": TIDB_HOST,
    "port": TIDB_PORT,
    "user": TIDB_USER,
    "password": TIDB_PASSWORD,
    "database": TIDB_DATABASE,
    **_SSL,
} if TIDB_HOST else {}

# Cluster registry: persisted to tidb_config.json
# Structure:
# {
#   "clusters": {
#     "tidb_c1": {
#       "host": "...", "port": 4000, "user": "...", "password": "...", "database": "anyybot",
#       "storage_limit_mb": 512,
#       "ru_budget": 1000000,
#       "created_at": 1234567890,
#       "status": "active|filling|full|migrating|decommissioned"
#     }
#   },
#   "user_cluster_map": { "7038720965": "tidb_c1", ... },
#   "next_cluster_id": 2
# }
_tidb_cluster_registry: dict = {}
_tidb_registry_lock = threading.RLock()

def _load_tidb_registry() -> dict:
    """Load cluster registry from persistent config file."""
    global _tidb_cluster_registry
    try:
        with open(TIDB_CONFIG_FILE, "r") as f:
            _tidb_cluster_registry = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        _tidb_cluster_registry = {"clusters": {}, "user_cluster_map": {}, "next_cluster_id": 1}
    return _tidb_cluster_registry

def _save_tidb_registry():
    """Persist cluster registry to config file."""
    try:
        # Ensure data directory exists
        Path(TIDB_CONFIG_FILE).parent.mkdir(parents=True, exist_ok=True)
        with _tidb_registry_lock:
            with open(TIDB_CONFIG_FILE, "w") as f:
                json.dump(_tidb_cluster_registry, f, indent=2)
    except Exception as e:
        logger.error(f"Failed to save TiDB registry: {e}")

def _init_tidb_registry():
    """Initialize registry: create first cluster if empty."""
    _load_tidb_registry()
    with _tidb_registry_lock:
        if not _tidb_cluster_registry.get("clusters"):
            # Create initial cluster from env
            cid = 1
            cluster_name = f"tidb_c{cid}"
            _tidb_cluster_registry["clusters"][cluster_name] = {
                "host": TIDB_HOST,
                "port": TIDB_PORT,
                "user": TIDB_USER,
                "password": TIDB_PASSWORD,
                "database": TIDB_DATABASE,
                "row_storage_limit_mb": TIDB_ROW_STORAGE_LIMIT_MB,
                "col_storage_limit_mb": TIDB_COL_STORAGE_LIMIT_MB,
                "ru_budget": TIDB_RU_BUDGET_PER_CLUSTER,
                "created_at": int(time.time()),
                "status": "active",
            }
            _tidb_cluster_registry["user_cluster_map"] = {}
            _tidb_cluster_registry["next_cluster_id"] = 2
            _save_tidb_registry()
            logger.info(f"[TiDB] Initialized registry with first cluster: {cluster_name}")
    # Build TIDB_SLOTS from active clusters
    global TIDB_SLOTS
    TIDB_SLOTS = [name for name, c in _tidb_cluster_registry.get("clusters", {}).items()
                  if c.get("status") in ("active", "filling")]
    # Build TIDB_CREDENTIALS from registry
    global TIDB_CREDENTIALS
    TIDB_CREDENTIALS = {}
    for name, c in _tidb_cluster_registry.get("clusters", {}).items():
        if c.get("status") in ("active", "filling"):
            TIDB_CREDENTIALS[name] = {
                "host": c["host"],
                "port": c["port"],
                "user": c["user"],
                "password": c["password"],
                "database": c["database"],
                **_SSL,
            }

# Initialize registry on module load
_init_tidb_registry()

