def _sanitize_uid(uid: str) -> int:
    """Convert uid to int, stripping any non-numeric prefix like 'user:'."""
    if isinstance(uid, int):
        return uid
    s = str(uid).strip()
    if s.startswith("user:"):
        s = s[5:]
    elif s.startswith("User:"):
        s = s[5:]
    # Take last colon-separated part
    s = s.split(":")[-1]
    return int(s)


