# Thread local for per-thread connections
# ── RU Budget & Rate Limiting ────────────────────────────────────
# TiDB Serverless free tier: 50M RU/month per cluster, 250M for 5 clusters
MONTHLY_RU_BUDGET = 250_000_000
DAILY_RU_BUDGET = MONTHLY_RU_BUDGET // 30  # ≈ 8,333,333 RU/day
# Sustained budget: 8.33M / 86400s ≈ 96 RU/s
# Safe burst allows 3x sustained for short peaks (288 RU/s)
# This prevents exhausting monthly budget in hours
SUSTAINED_RU_PER_SECOND = int(DAILY_RU_BUDGET // 86400) or 1  # ~96
MAX_RU_PER_SECOND = SUSTAINED_RU_PER_SECOND * 3  # ~288 — safe burst

RU_COST = {
    "select": 3,
    "insert": 8,
    "update": 6,
    "delete": 4,
    "bulk_insert_500": 400,
    "transaction": 15,
}

# ── Lock-free RU throttle ─────────────────────────────────────────
# Instead of a sliding window with a global lock, we use atomic counters
# that reset every second with a background check. This eliminates lock
# contention on every single DB operation (~100k+ calls/day).
_ru_current_window: int = 0
_ru_window_start: float = time.time()
_ru_lock_free_lock = threading.Lock()

def _ru_throttle(estimated_ru: int = 1):
    """Adaptive throttling with lock-free counter + background reset."""
    global _ru_current_window, _ru_window_start
    now = time.time()
    budget = get_budget()
    cost = optimize_ru_cost(estimated_ru)

    # Lock-free counter with periodic reset (rare contention)
    if now - _ru_window_start > 1.0:
        with _ru_lock_free_lock:
            if now - _ru_window_start > 1.0:
                _ru_current_window = 0
                _ru_window_start = now
    _ru_current_window += cost

    throttled = False
    if _ru_current_window > MAX_RU_PER_SECOND:
        sleep_time = min(0.2, 0.01 * (_ru_current_window / (SUSTAINED_RU_PER_SECOND or 1)))
        time.sleep(sleep_time)
        throttled = True

    result = budget.record_ru(cost)
    if result["throttle_sec"] > 0:
        time.sleep(min(0.5, result["throttle_sec"]))
        throttled = True

    return throttled


_thread_local = threading.local()


class TiDBSlot:
    __slots__ = ("name", "host", "port", "user", "password", "database",
                 "ok", "error", "usage_bytes", "usage_percent",
                 "_ssl_verify_cert", "_ssl_verify_identity", "_ssl_ca")

    def __init__(self, name: str, creds: dict):
        self.name = name
        self.host = creds["host"]
        self.port = int(creds["port"])
        self.user = creds["user"]
        self.password = creds["password"]
        self.database = creds["database"]
        self._ssl_verify_cert = creds.get("ssl_verify_cert", True)
        self._ssl_verify_identity = creds.get("ssl_verify_identity", True)
        self._ssl_ca = creds.get("ssl_ca", "")
        self.ok = False
        self.error = ""
        self.usage_bytes = 0
        self.usage_percent = 0

    def connect(self) -> Any | None:
        if not _HAVE_PYMYSQL:
            return None
        try:
            conn = pymysql.connect(
                host=self.host,
                port=self.port,
                user=self.user,
                password=self.password,
                database=self.database,
                charset="utf8mb4",
                connect_timeout=5,
                read_timeout=10,
                write_timeout=10,
                cursorclass=pymysql.cursors.DictCursor,
                ssl_verify_cert=self._ssl_verify_cert,
                ssl_verify_identity=self._ssl_verify_identity,
                ssl_ca=self._ssl_ca or None,
            )
            self.ok = True
            self.error = ""
            return conn
        except Exception as e:
            logger.warning("Exception: %s", str(e))
            self.error = str(e)
            self.ok = False
            return None

    def get_conn(self) -> Any | None:
        if not _HAVE_PYMYSQL:
            return None
        conn_key = f"_tidb_conn_{self.name}"
        conn = getattr(_thread_local, conn_key, None)
        if conn is None:
            conn = self.connect()
            if conn:
                setattr(_thread_local, conn_key, conn)
        else:
            try:
                conn.ping(reconnect=True)
            except Exception:
                try:
                    conn.close()
                except Exception:
                    logger.warning("Exception in get_conn", exc_info=True)
                conn = self.connect()
                if conn:
                    setattr(_thread_local, conn_key, conn)
        return conn

    def close_conn(self):
        conn_key = f"_tidb_conn_{self.name}"
        conn = getattr(_thread_local, conn_key, None)
        if conn:
            try:
                conn.close()
            except Exception:
                logger.warning("Exception in close_conn", exc_info=True)
            delattr(_thread_local, conn_key)


class TiDBPool:
    def __init__(self):
        self._slots: dict[str, TiDBSlot] = {}
        self._ordered: list[TiDBSlot] = []
        self._lock = threading.RLock()
        self._initialized = False

    def init(self):
        if self._initialized:
            return
        with self._lock:
            if self._initialized:
                return
            # Build slots from current active clusters in registry
            _load_tidb_registry()
            for name, c in _tidb_cluster_registry.get("clusters", {}).items():
                if c.get("status") in ("active", "filling"):
                    creds = {
                        "host": c["host"],
                        "port": c["port"],
                        "user": c["user"],
                        "password": c["password"],
                        "database": c["database"],
                        **_SSL,
                    }
                    slot = TiDBSlot(name, creds)
                    self._slots[name] = slot
                    self._ordered.append(slot)
            self._initialized = True
            self.warmup()

    def refresh_slots(self):
        """Rebuild slots from registry (call after cluster add/remove)."""
        with self._lock:
            self._slots.clear()
            self._ordered.clear()
            _load_tidb_registry()
            for name, c in _tidb_cluster_registry.get("clusters", {}).items():
                if c.get("status") in ("active", "filling"):
                    creds = {
                        "host": c["host"],
                        "port": c["port"],
                        "user": c["user"],
                        "password": c["password"],
                        "database": c["database"],
                        **_SSL,
                    }
                    slot = TiDBSlot(name, creds)
                    self._slots[name] = slot
                    self._ordered.append(slot)
            self.warmup()

    @property
    def slots(self) -> list[TiDBSlot]:
        return list(self._ordered)

    def health_check(self):
        def _ping(slot):
            try:
                conn = slot.get_conn()
                if conn:
                    with conn.cursor() as cur:
                        cur.execute("SELECT 1")
                    slot.ok = True
                    slot.error = ""
                else:
                    slot.ok = False
            except Exception as e:
                slot.ok = False
                slot.error = str(e)

        ex = _SLOT_EXECUTOR
        for _ in ex.map(_ping, list(self._ordered)):
            pass

    def ensure_recovered(self):
        if not self._initialized:
            self.init()
        if self._ordered and not any(s.ok for s in self._ordered):
            try:
                self.health_check()
            except Exception:
                pass

    def slot_by_modulo(self, uid: str) -> TiDBSlot | None:
        """Route user to their assigned cluster from registry.
        Falls back to consistent hashing for new users not yet assigned."""
        _load_tidb_registry()
        user_map = _tidb_cluster_registry.get("user_cluster_map", {})
        assigned = user_map.get(str(uid))
        
        if assigned and assigned in self._slots:
            slot = self._slots[assigned]
            if slot.ok:
                return slot
            # Assigned slot unhealthy — will fall through to find healthy
        
        # New user or assigned slot down: find healthy slot via consistent hashing
        if not self._ordered:
            return None
        try:
            idx = _sanitize_uid(uid) % len(self._ordered)
            primary = self._ordered[idx]
            if primary.ok:
                # Assign new user to this cluster
                self._assign_user_to_cluster(uid, primary.name)
                return primary
            # Fallback: find next healthy slot
            for i in range(len(self._ordered)):
                candidate = self._ordered[(idx + i) % len(self._ordered)]
                if candidate.ok:
                    self._assign_user_to_cluster(uid, candidate.name)
                    return candidate
            # All unhealthy — probe
            try:
                self.health_check()
            except Exception:
                pass
            return primary
        except (ValueError, ZeroDivisionError):
            return self._ordered[0] if self._ordered else None
        except Exception:
            logger.warning("Exception in slot_by_modulo", exc_info=True)
            return self._ordered[0] if self._ordered else None

    def _assign_user_to_cluster(self, uid: str, cluster_name: str):
        """Persist user→cluster assignment in registry."""
        _load_tidb_registry()
        with _tidb_registry_lock:
            user_map = _tidb_cluster_registry.setdefault("user_cluster_map", {})
            if user_map.get(str(uid)) != cluster_name:
                user_map[str(uid)] = cluster_name
                _save_tidb_registry()

    def slot_by_name(self, name: str) -> TiDBSlot | None:
        return self._slots.get(name)

    def close_all(self):
        for slot in self._ordered:
            slot.close_conn()


# ─── TiDB Capacity Monitoring & Auto-Scaling ─────────────────────────

def _get_cluster_stats(cluster_name: str) -> dict | None:
    """Get storage usage and user count for a cluster."""
    slot = get_pool().slot_by_name(cluster_name)
    if not slot or not slot.ok:
        return None
    try:
        conn = slot.get_conn()
        if not conn:
            return None
        with conn.cursor() as cur:
            # Storage usage - separate row and columnar
            cur.execute("""
                SELECT 
                    ROUND(SUM(CASE WHEN ENGINE='InnoDB' THEN data_length + index_length ELSE 0 END) / 1024 / 1024, 2) AS row_size_mb,
                    ROUND(SUM(CASE WHEN ENGINE='TiFlash' THEN data_length + index_length ELSE 0 END) / 1024 / 1024, 2) AS col_size_mb,
                    COUNT(*) AS user_count
                FROM information_schema.tables 
                WHERE table_schema = DATABASE() AND table_name = 'users'
            """)
            row = cur.fetchone()
            if row:
                return {
                    "row_size_mb": float(row.get("row_size_mb", 0) or 0),
                    "col_size_mb": float(row.get("col_size_mb", 0) or 0),
                    "user_count": int(row.get("user_count", 0) or 0),
                }
    except Exception as e:
        logger.warning(f"Failed to get stats for {cluster_name}: {e}")
    return None


def _check_cluster_capacity(cluster_name: str) -> dict:
    """Check if cluster is approaching capacity limits."""
    cluster = _tidb_cluster_registry.get("clusters", {}).get(cluster_name)
    if not cluster:
        return {"needs_scaling": False}
    
    stats = _get_cluster_stats(cluster_name)
    if not stats:
        return {"needs_scaling": False}
    
    row_limit = cluster.get("row_storage_limit_mb", TIDB_ROW_STORAGE_LIMIT_MB)
    col_limit = cluster.get("col_storage_limit_mb", TIDB_COL_STORAGE_LIMIT_MB)
    
    row_pct = (stats["row_size_mb"] / row_limit) * 100 if row_limit > 0 else 0
    col_pct = (stats["col_size_mb"] / col_limit) * 100 if col_limit > 0 else 0
    
    # Scale if either row or columnar storage hits threshold
    needs_scaling = row_pct >= TIDB_STORAGE_THRESHOLD_PCT or col_pct >= TIDB_STORAGE_THRESHOLD_PCT
    user_count = stats["user_count"]
    
    return {
        "needs_scaling": needs_scaling,
        "row_pct": row_pct,
        "col_pct": col_pct,
        "row_size_mb": stats["row_size_mb"],
        "col_size_mb": stats["col_size_mb"],
        "row_limit_mb": row_limit,
        "col_limit_mb": col_limit,
        "user_count": user_count,
    }


def _provision_new_cluster() -> str | None:
    """Create a new TiDB cluster entry in registry (requires manual TiDB Cloud provisioning)."""
    _load_tidb_registry()
    with _tidb_registry_lock:
        clusters = _tidb_cluster_registry.get("clusters", {})
        # Count free vs paid clusters
        free_count = sum(1 for c in clusters.values() 
                         if c.get("status") in ("active", "filling") and not c.get("paid", False))
        total_count = sum(1 for c in clusters.values() if c.get("status") in ("active", "filling", "pending"))
        
        if free_count >= TIDB_MAX_FREE_CLUSTERS and total_count >= TIDB_MAX_PAID_CLUSTERS:
            logger.warning(f"[TiDB] Max clusters reached (free={TIDB_MAX_FREE_CLUSTERS}, total={TIDB_MAX_PAID_CLUSTERS})")
            return None
        
        next_id = _tidb_cluster_registry.get("next_cluster_id", 1)
        new_name = f"tidb_c{next_id}"
        is_paid = free_count >= TIDB_MAX_FREE_CLUSTERS
        
        # New cluster needs manual provisioning in TiDB Cloud
        clusters[new_name] = {
            "host": "",  # Must be filled after provisioning
            "port": 4000,
            "user": "",
            "password": "",
            "database": TIDB_DATABASE,
            "row_storage_limit_mb": TIDB_ROW_STORAGE_LIMIT_MB,
            "col_storage_limit_mb": TIDB_COL_STORAGE_LIMIT_MB,
            "ru_budget": TIDB_RU_BUDGET_PER_CLUSTER,
            "created_at": int(time.time()),
            "status": "pending",  # Waiting for manual provisioning
            "paid": is_paid,
        }
        _tidb_cluster_registry["next_cluster_id"] = next_id + 1
        _save_tidb_registry()
        
        logger.warning(f"[TiDB] Provisioned new cluster entry: {new_name} (status=pending, paid={is_paid})")
        logger.warning(f"[TiDB] ACTION REQUIRED: Provision cluster in TiDB Cloud, then update {new_name} credentials in registry")
        
        # Update global slots list
        global TIDB_SLOTS, TIDB_CREDENTIALS
        TIDB_SLOTS = [name for name, c in clusters.items() if c.get("status") in ("active", "filling")]
        
        return new_name


def _migrate_users_to_cluster(source_cluster: str, target_cluster: str, user_count: int) -> int:
    """Migrate users from source to target cluster.
    Returns number of users migrated."""
    if source_cluster == target_cluster:
        return 0
    
    source_slot = get_pool().slot_by_name(source_cluster)
    target_slot = get_pool().slot_by_name(target_cluster)
    if not source_slot or not target_slot:
        return 0
    
    try:
        # Get users assigned to source cluster
        _load_tidb_registry()
        user_map = _tidb_cluster_registry.get("user_cluster_map", {})
        users_to_migrate = [
            uid for uid, c in user_map.items() 
            if c == source_cluster
        ][:user_count]
        
        if not users_to_migrate:
            return 0
        
        # Mark target cluster as filling
        _tidb_cluster_registry["clusters"][target_cluster]["status"] = "filling"
        _save_tidb_registry()
        
        migrated = 0
        for uid in users_to_migrate:
            try:
                # Read from source
                source_conn = source_slot.get_conn()
                target_conn = target_slot.get_conn()
                if not source_conn or not target_conn:
                    continue
                
                uid_int = _sanitize_uid(uid)
                
                # Copy user data
                with source_conn.cursor() as cur:
                    cur.execute("SELECT * FROM users WHERE user_id=%s", (uid_int,))
                    row = cur.fetchone()
                    if not row:
                        continue
                
                # Insert into target
                with target_conn.cursor() as cur:
                    cols = [k for k in row.keys() if k != "user_id"]
                    vals = [row[c] for c in cols]
                    placeholders = ", ".join(["%s"] * (len(cols) + 1))
                    col_names = ", ".join(["user_id"] + cols)
                    cur.execute(
                        f"INSERT INTO users ({col_names}) VALUES ({placeholders}) "
                        f"ON DUPLICATE KEY UPDATE {', '.join(f'{c}=VALUES({c})' for c in cols)}",
                        [uid_int] + vals
                    )
                target_conn.commit()
                
                # Update user's cluster assignment
                with _tidb_registry_lock:
                    _tidb_cluster_registry["user_cluster_map"][str(uid)] = target_cluster
                    _save_tidb_registry()
                
                # Delete from source (after successful target write)
                with source_conn.cursor() as cur:
                    cur.execute("DELETE FROM users WHERE user_id=%s", (uid_int,))
                source_conn.commit()
                
                migrated += 1
                
            except Exception as e:
                logger.error(f"Failed to migrate user {uid}: {e}")
                continue
        
        logger.info(f"[TiDB] Migrated {migrated} users from {source_cluster} to {target_cluster}")
        
        # If source cluster now empty, mark for decommission
        remaining = sum(1 for c in _tidb_cluster_registry.get("user_cluster_map", {}).values() 
                        if c == source_cluster)
        if remaining == 0:
            _tidb_cluster_registry["clusters"][source_cluster]["status"] = "decommissioned"
            _save_tidb_registry()
            # Refresh pool slots
            get_pool().refresh_slots()
        
        return migrated
        
    except Exception as e:
        logger.error(f"Migration failed: {e}")
        return 0


def _auto_scale_tidb() -> None:
    """Background task: check cluster capacity and trigger scaling."""
    _load_tidb_registry()
    clusters = _tidb_cluster_registry.get("clusters", {})
    
    for name, cluster in clusters.items():
        if cluster.get("status") not in ("active", "filling"):
            continue
        
        capacity = _check_cluster_capacity(name)
        if capacity.get("needs_scaling"):
            logger.warning(f"[TiDB] Cluster {name} at {capacity['storage_pct']:.1f}% capacity — scaling needed")
            
            # Check if there's a pending cluster ready
            pending = [n for n, c in clusters.items() if c.get("status") == "pending"]
            if pending:
                target = pending[0]
                # Provision credentials for pending cluster (admin must have updated them)
                if clusters[target].get("host") and clusters[target].get("user"):
                    clusters[target]["status"] = "filling"
                    _save_tidb_registry()
                    get_pool().refresh_slots()
                    
                    # Migrate users
                    _migrate_users_to_cluster(name, target, 1000)  # Batch size
                else:
                    logger.warning(f"[TiDB] Pending cluster {target} not ready (missing credentials)")
            else:
                # Provision new cluster
                _provision_new_cluster()


# Background auto-scaler
_tidb_autoscale_task: Optional[asyncio.Task] = None

async def _periodic_tidb_autoscale(interval: float = 300.0):  # 5 minutes
    """Periodically check cluster capacity and scale if needed."""
    while True:
        try:
            await asyncio.sleep(interval)
            _auto_scale_tidb()
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"TiDB autoscale error: {e}")

def start_tidb_autoscale_task(interval: float = 300.0):
    global _tidb_autoscale_task
    if _tidb_autoscale_task is not None and not _tidb_autoscale_task.done():
        return
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            _tidb_autoscale_task = asyncio.create_task(_periodic_tidb_autoscale(interval))
            logger.info(f"[TiDB] Auto-scaler started ({interval}s interval)")
    except RuntimeError:
        pass


_tidb_pool = TiDBPool()


def get_pool() -> TiDBPool:
    if not _tidb_pool._initialized:
        _tidb_pool.init()
    return _tidb_pool


_schema_initialized_slots: set[str] = set()
_migrations_done: set[str] = set()
_schema_init_lock = threading.Lock()


def _is_expected_schema_error(exc: Exception) -> bool:
    """True for MySQL/TiDB 'already exists' errors (1060 column, 1061 index)."""
    code = getattr(exc, "args", (None,))[0] if getattr(exc, "args", None) else None
    if code in (1060, 1061, 1826):
        return True
    text = str(exc).lower()
    return "duplicate column" in text or "duplicate key name" in text or "already exists" in text


def init_schema():
    pool = get_pool()
    for slot in pool.slots:
        if slot.name in _schema_initialized_slots:
            continue
        with _schema_init_lock:
            if slot.name in _schema_initialized_slots:
                continue
            try:
                conn = slot.get_conn()
                if not conn:
                    continue
                with conn.cursor() as cur:
                    cur.execute(USER_TABLE_SQL)
                    for idx_sql in USER_INDEXES_SQL:
                        try:
                            cur.execute(idx_sql)
                        except Exception as exc:
                            if _is_expected_schema_error(exc):
                                logger.debug("[schema] index already exists: %s", idx_sql)
                            else:
                                logger.warning("Exception in init_schema", exc_info=True)
                    cur.execute(SETTINGS_TABLE_SQL)
                    cur.execute(STICKERS_TABLE_SQL)
                    cur.execute(RUNTIME_TABLE_SQL)
                    cur.execute(CHATS_TABLE_SQL)
                    cur.execute(RECOVERY_TABLE_SQL)
                    # Add missing columns for schema migration (idempotent)
                    for col_sql in _MIGRATION_COLS:
                        if col_sql in _migrations_done:
                            continue
                        try:
                            cur.execute(col_sql)
                        except Exception as exc:
                            # Column likely already exists — mark done to avoid retry cost.
                            # A full traceback here on EVERY boot was pure noise.
                            if _is_expected_schema_error(exc):
                                logger.debug("[schema] column already present: %s", col_sql)
                            else:
                                logger.warning("Failed to execute migration: %s", col_sql, exc_info=True)
                        _migrations_done.add(col_sql)
                conn.commit()
                slot.ok = True
                _schema_initialized_slots.add(slot.name)
                logger.info(f"TiDB schema initialized on {slot.name}")
            except Exception as e:
                slot.ok = False
                slot.error = str(e)

_MIGRATION_COLS = [
    "ALTER TABLE users ADD COLUMN username VARCHAR(255) DEFAULT NULL AFTER created_at",
    "ALTER TABLE users ADD COLUMN first_name VARCHAR(255) DEFAULT NULL AFTER username",
    "ALTER TABLE users ADD COLUMN is_bot TINYINT(1) NOT NULL DEFAULT 0 AFTER first_name",
]


def _user_to_row(data: dict) -> dict:
    row = {
        "user_id": int(data.get("user_id", 0) or 0),
        "balance": int(data.get("balance", 0) or 0),
        "rp": int(data.get("rp", 0) or 0),
        "level": int(data.get("level", 1) or 1),
        "captures": int(data.get("captures", 0) or 0),
        "total_redeem_earned": int(data.get("total_redeem_earned", 0) or 0),
        "premium_until": int(data.get("premium_until", 0) or 0),
        "banned": 1 if data.get("banned") else 0,
        "daily_income": int(data.get("daily_income", 0) or 0),
        "weekly_income": int(data.get("weekly_income", 0) or 0),
        "daily_captures": int(data.get("daily_captures", 0) or 0),
        "weekly_captures": int(data.get("weekly_captures", 0) or 0),
        "daily_redeem": int(data.get("daily_redeem", 0) or 0),
        "weekly_redeem": int(data.get("weekly_redeem", 0) or 0),
        "lifetime_income": int(data.get("lifetime_income", 0) or 0),
        "last_seen": int(data.get("last_seen", 0) or 0),
        "updated_at": int(data.get("updated_at", 0) or 0),
        "created_at": int(data.get("created_at", 0) or 0),
        "username": str(data.get("username", ""))[:255] if data.get("username") else None,
        "first_name": str(data.get("first_name", ""))[:255] if data.get("first_name") else None,
        "is_bot": 1 if data.get("is_bot") else 0,
        "_data_epoch": int(data.get("_data_epoch", 0) or 0),
    }
    all_fields = dict(data)
    all_fields.pop("user_id", None)
    for k in list(USER_COLUMNS_NO_BLOB):
        all_fields.pop(k, None)
    if all_fields:
        try:
            if msgpack is None:
                # Fallback to json if msgpack not available (for compile checks)
                import json as _json
                row["_c"] = zlib.compress(_json.dumps(all_fields).encode())
            else:
                row["_c"] = zlib.compress(msgpack.packb(all_fields, use_bin_type=True))
        except Exception as exc:
            logger.warning(f"User blob compression failed for uid={row.get('user_id')}: {exc!r}")
            row["_c"] = None
    else:
        row["_c"] = None
    return row


def _cols_user() -> str:
    return ", ".join(sorted(USER_COLUMNS))


def _placeholders_user() -> str:
    return ", ".join(["%s"] * len(USER_COLUMNS))


def _update_set_user() -> str:
    cols = sorted(c for c in USER_COLUMNS if c != "user_id")
    return ", ".join(f"{c}=%s" for c in cols)


def _slot_id(uid: str) -> int:
    try:
        return _sanitize_uid(uid) % 5
    except (ValueError, TypeError):
        return 0


def tidb_get_user(uid: str) -> dict:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return {}
    _ru_throttle(RU_COST["select"])
    try:
        conn = slot.get_conn()
        if not conn:
            return {}
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
            row = cur.fetchone()
        if row:
            return _row_to_user_dict(dict(row))
        # Fallback: scan all slots for duplicates (shard misrouting, e.g., hoshi 7237803221)
        for fb in pool.slots:
            if fb.name == slot.name or not fb.ok:
                continue
            try:
                conn2 = fb.get_conn()
                if not conn2:
                    continue
                with conn2.cursor() as cur2:
                    cur2.execute("SELECT * FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
                    row2 = cur2.fetchone()
                    if row2:
                        return _row_to_user_dict(dict(row2))
            except Exception:
                continue
        return {}
    except Exception as e:
        logger.warning("Exception in tidb_get_user", exc_info=True)
        slot.error = str(e)
        logger.debug(f"tidb_get_user failed on {slot.name}: {e}")
        return {}


def tidb_save_user(uid: str, data: dict) -> bool:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return False
    _ru_throttle(RU_COST["insert"])
    row = _user_to_row(data)
    row["user_id"] = _sanitize_uid(uid)
    cols = sorted(USER_COLUMNS)
    vals = [row.get(c) for c in cols]
    upsert_sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) ON DUPLICATE KEY UPDATE "
    upsert_sql += ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
    try:
        conn = slot.get_conn()
        if not conn:
            return False
        with conn.cursor() as cur:
            cur.execute(upsert_sql, vals)
        conn.commit()
        return True
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.ok = False
        slot.error = str(e)
        logger.debug(f"tidb_save_user failed on {slot.name}: {e}")
        return False


def _row_to_user_dict(row: dict) -> dict:
    data = {}
    user_id = row.get("user_id", None)
    if user_id:
        data["user_id"] = str(user_id)
    blob = row.get("_c", None)
    for k, v in row.items():
        if k in ("user_id", "_c") or v is None:
            continue
        data[k] = v
    if blob:
        try:
            if msgpack is None:
                import json as _json
                try:
                    blob_data = _json.loads(zlib.decompress(blob).decode())
                except Exception:
                    blob_data = {}
            else:
                blob_data = msgpack.unpackb(zlib.decompress(blob), raw=False)
            if isinstance(blob_data, dict):
                # Apply blob FIRST, then let column values override (columns are always fresh)
                for k, v in blob_data.items():
                    if k not in data:
                        data[k] = v
        except Exception:
            logger.warning("Exception in _row_to_user_dict", exc_info=True)
    return data


def tidb_atomic_update(uid: str, inc_fields: dict = None, set_fields: dict = None) -> dict:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    # Retry transient slot unavailability (shard blip) — previously returned {}
    # immediately and dropped the write, causing credits like loot to vanish
    # while the victim's deduction persisted. Recover and re-acquire.
    slot = None
    for _attempt in range(3):
        slot = pool.slot_by_modulo(str(uid))
        if slot and slot.ok:
            break
        logger.warning("tidb_atomic_update: slot unavailable (attempt %d) for %s — recovering", _attempt + 1, uid)
        try:
            pool.ensure_recovered()
        except Exception:
            pass
        pool = get_pool()
    if not slot or not slot.ok:
        return {}
    uid_int = _sanitize_uid(uid)
    ordered = pool.slots
    is_modulo_slot = bool(ordered) and ordered[uid_int % len(ordered)].name == slot.name

    # Failover guard: writes routed to a NON-modulo slot must never INSERT a
    # user copy there (creates cross-slot duplicates). Fall through to the
    # caller's relay/cache fallback instead.
    def _may_insert() -> bool:
        return is_modulo_slot

    inc_fields = inc_fields or {}
    set_fields = dict(set_fields) if set_fields else {}
    now = int(time.time())

    # Fast path: pure SET without increments (no transaction needed)
    if not inc_fields and set_fields:
        set_fields["updated_at"] = now
        set_cols = [k for k in set_fields if k in USER_COLUMNS_NO_BLOB]
        # Check if ALL set_fields are TiDB columns — if any go to _c blob, use general path
        has_blob_fields = any(k not in USER_COLUMNS_NO_BLOB for k in set_fields if k != "updated_at")
        if set_cols and not has_blob_fields:
            set_sql = ", ".join(f"{c}=%s" for c in set_cols)
            vals = [set_fields[c] for c in set_cols] + [uid_int]
            try:
                conn = slot.get_conn()
                if not conn:
                    return {}
                with conn.cursor() as cur:
                    cur.execute(f"UPDATE users SET {set_sql} WHERE user_id=%s", vals)
                    if cur.rowcount == 0:
                        if not _may_insert():
                            return {}
                        # User doesn't exist — verify with SELECT before inserting defaults
                        cur.execute("SELECT user_id FROM users WHERE user_id=%s", (uid_int,))
                        if not cur.fetchone():
                            # Truly new user — safe to insert with defaults
                            data = {"user_id": uid}
                            data["balance"] = 200
                            data["captures"] = 0
                            data["rp"] = 0
                            data["level"] = 1
                            data["daily_income"] = 0
                            data["weekly_income"] = 0
                            data["daily_captures"] = 0
                            data["weekly_captures"] = 0
                            data["daily_redeem"] = 0
                            data["weekly_redeem"] = 0
                            data["lifetime_income"] = 0
                            data["premium_until"] = 0
                            data["banned"] = 0
                            data["total_redeem_earned"] = 0
                            data["created_at"] = now
                            data.update(set_fields)
                            data["updated_at"] = now
                            row_out = _user_to_row(data)
                            row_out["user_id"] = uid_int
                            cols = sorted(USER_COLUMNS)
                            vals = [row_out.get(c) for c in cols]
                            upsert_sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) ON DUPLICATE KEY UPDATE "
                            upsert_sql += ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
                            cur.execute(upsert_sql, vals)
                        else:
                            # User exists but UPDATE didn't affect rows — retry the UPDATE
                            cur.execute(f"UPDATE users SET {set_sql} WHERE user_id=%s", vals)
                conn.commit()
                _ru_throttle(RU_COST["update"])
                return tidb_get_user(uid)
            except Exception as e:
                logger.warning("tidb_atomic_update SET-only failed: %s", str(e))
                slot.ok = False
                slot.error = str(e)
                return {}



    # Fast path: single-column increment without SET (atomic UPDATE col = col + val)
    if inc_fields and not set_fields and len(inc_fields) == 1:
        col, val = next(iter(inc_fields.items()))
        if col in USER_COLUMNS_NO_BLOB:
            try:
                conn = slot.get_conn()
                if not conn:
                    return {}
                with conn.cursor() as cur:
                    cur.execute(
                        f"UPDATE users SET {col}={col}+%s, updated_at=%s WHERE user_id=%s",
                        (int(val or 0), now, uid_int)
                    )
                    if cur.rowcount == 0:
                        if not _may_insert():
                            return {}
                        # Verify user doesn't exist before inserting defaults
                        cur.execute("SELECT user_id FROM users WHERE user_id=%s", (uid_int,))
                        if not cur.fetchone():
                            data = {"user_id": str(uid_int), "balance": 200, "captures": 0, "rp": 0,
                                    "level": 1, "daily_income": 0, "weekly_income": 0,
                                    "daily_captures": 0, "weekly_captures": 0,
                                    "daily_redeem": 0, "weekly_redeem": 0,
                                    "lifetime_income": 0, "premium_until": 0,
                                    "banned": 0, "total_redeem_earned": 0, "created_at": now}
                            data[col] = int(val or 0)
                            data["updated_at"] = now
                            row_out = _user_to_row(data)
                            row_out["user_id"] = uid_int
                            cols = sorted(USER_COLUMNS)
                            vals = [row_out.get(c) for c in cols]
                            upsert_sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) ON DUPLICATE KEY UPDATE "
                            upsert_sql += ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
                            cur.execute(upsert_sql, vals)
                        else:
                            # User exists, retry the increment
                            cur.execute(
                                f"UPDATE users SET {col}={col}+%s, updated_at=%s WHERE user_id=%s",
                                (int(val or 0), now, uid_int)
                            )
                    # Sync level when RP changes — TiDB fast path doesn't recalc level
                    if col == "rp":
                        cur.execute("SELECT rp FROM users WHERE user_id=%s", (uid_int,))
                        row = cur.fetchone()
                        if row:
                            import sys as _sys
                            _main_mod = _sys.modules.get("__main__")
                            get_level_progress = getattr(_main_mod, "get_level_progress", None)
                            new_level, _, _ = get_level_progress(int(row["rp"]))
                            cur.execute("UPDATE users SET level=%s WHERE user_id=%s", (new_level, uid_int))
                conn.commit()
                _ru_throttle(RU_COST["update"])
                return tidb_get_user(uid)
            except Exception as e:
                logger.warning("tidb_atomic_update single-inc failed: %s", str(e))
                slot.ok = False
                slot.error = str(e)
                return {}

    # Fast path: pure multi-column increments (atomic UPDATE, no transaction)
    if inc_fields and not set_fields and len(inc_fields) > 1 and all(
        k in USER_COLUMNS_NO_BLOB for k in inc_fields
    ):
        try:
            conn = slot.get_conn()
            if not conn:
                return {}
            cols_sql = ", ".join(f"{k}={k}+%s" for k in inc_fields)
            vals = [int(inc_fields[k] or 0) for k in inc_fields]
            with conn.cursor() as cur:
                cur.execute(
                    f"UPDATE users SET {cols_sql}, updated_at=%s WHERE user_id=%s",
                    vals + [now, uid_int]
                )
                if cur.rowcount == 0:
                    if not _may_insert():
                        return {}
                    cur.execute("SELECT user_id FROM users WHERE user_id=%s", (uid_int,))
                    if not cur.fetchone():
                        data = {"user_id": str(uid_int), "balance": 200, "captures": 0, "rp": 0,
                                "level": 1, "daily_income": 0, "weekly_income": 0,
                                "daily_captures": 0, "weekly_captures": 0,
                                "daily_redeem": 0, "weekly_redeem": 0,
                                "lifetime_income": 0, "premium_until": 0,
                                "banned": 0, "total_redeem_earned": 0, "created_at": now}
                        for k, v in inc_fields.items():
                            data[k] = int(data.get(k, 0) or 0) + int(v or 0)
                        data["updated_at"] = now
                        row_out = _user_to_row(data)
                        row_out["user_id"] = uid_int
                        cols = sorted(USER_COLUMNS)
                        vals2 = [row_out.get(c) for c in cols]
                        upsert_sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) ON DUPLICATE KEY UPDATE "
                        upsert_sql += ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
                        cur.execute(upsert_sql, vals2)
                    else:
                        cur.execute(
                            f"UPDATE users SET {cols_sql}, updated_at=%s WHERE user_id=%s",
                            vals + [now, uid_int]
                        )
                if "rp" in inc_fields:
                    cur.execute("SELECT rp FROM users WHERE user_id=%s", (uid_int,))
                    row = cur.fetchone()
                    if row:
                        from game.profile import get_level_progress
                        new_level, _, _ = get_level_progress(int(row["rp"]))
                        cur.execute("UPDATE users SET level=%s WHERE user_id=%s", (new_level, uid_int))
            conn.commit()
            _ru_throttle(RU_COST["update"])
            return tidb_get_user(uid)
        except Exception as e:
            logger.warning("tidb_atomic_update multi-inc failed: %s", str(e))
            slot.ok = False
            slot.error = str(e)
            return {}

    # General path: mixed inc+set requires transaction
    # Failover guard: don't create duplicates in wrong shard (same as fast paths)
    if not is_modulo_slot:
        return {}
    _ru_throttle(RU_COST.get("transaction", 15))
    conn = None
    try:
        conn = slot.get_conn()
        if not conn:
            return {}

        conn.begin()

        with conn.cursor() as cur:
            cur.execute("SELECT * FROM users WHERE user_id=%s FOR UPDATE", (uid_int,))
            row = cur.fetchone()

            if row:
                data = _row_to_user_dict(dict(row))
            else:
                # New user: start with default values
                data = {"user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                        "level": 1, "daily_income": 0, "weekly_income": 0,
                        "daily_captures": 0, "weekly_captures": 0,
                        "daily_redeem": 0, "weekly_redeem": 0,
                        "lifetime_income": 0, "premium_until": 0,
                        "banned": 0, "total_redeem_earned": 0, "created_at": now}

            for k, v in inc_fields.items():
                data[k] = int(data.get(k, 0) or 0) + int(v or 0)
            data.update(set_fields)
            data["updated_at"] = now
            if "rp" in inc_fields and "level" not in set_fields:
                import sys as _sys
                _main_mod = _sys.modules.get("__main__")
                get_level_progress = getattr(_main_mod, "get_level_progress", None)
                data["level"], _, _ = get_level_progress(int(data.get("rp", 0) or 0))

            row_out = _user_to_row(data)
            row_out["user_id"] = uid_int
            cols = sorted(USER_COLUMNS)
            vals = [row_out.get(c) for c in cols]
            upsert_sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))}) ON DUPLICATE KEY UPDATE "
            upsert_sql += ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
            cur.execute(upsert_sql, vals)

        conn.commit()
        return data
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                logger.warning("Exception: %s", str(e))
        slot.ok = False
        slot.error = str(e)
        logger.debug(f"tidb_atomic_update failed on {slot.name}: {e}")
        return {}


def tidb_update_fields(uid: str, set_fields: dict) -> bool:
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return False
    if not set_fields:
        return True
    set_fields = dict(set_fields)  # copy to avoid mutating caller's dict
    set_fields["updated_at"] = int(time.time())
    set_cols = [k for k in set_fields if k in USER_COLUMNS_NO_BLOB]
    has_blob_fields = any(k not in USER_COLUMNS_NO_BLOB for k in set_fields if k != "updated_at")
    if has_blob_fields:
        # Fields like saved_until go to _c blob — need full row read/write
        # Fall through to return False so caller uses update_user_atomic
        return False
    if not set_cols:
        return True
    set_sql = ", ".join(f"{c}=%s" for c in set_cols)
    vals = [set_fields[c] for c in set_cols] + [_sanitize_uid(uid)]
    try:
        conn = slot.get_conn()
        if not conn:
            return False
        with conn.cursor() as cur:
            cur.execute(f"UPDATE users SET {set_sql} WHERE user_id=%s", vals)
        conn.commit()
        return True
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.ok = False
        slot.error = str(e)
        return False


def tidb_try_deduct_balance(uid: str, amount: int) -> bool:
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return False
    if amount <= 0:
        return True
    _ru_throttle(RU_COST["update"])
    uid_int = _sanitize_uid(uid)

    try:
        conn = slot.get_conn()
        if not conn:
            return False
        with conn.cursor() as cur:
            cur.execute("UPDATE users SET balance=balance-%s, updated_at=%s WHERE user_id=%s AND balance>=%s",
                        (amount, int(time.time()), uid_int, amount))
            affected = cur.rowcount
        conn.commit()
        if affected > 0:
            return True
        return False
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.ok = False
        slot.error = str(e)
        return False


def tidb_leaderboard(sort_key: str, limit: int = 10, banned: bool = False) -> list:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    _ru_throttle(RU_COST["select"])
    if sort_key not in LEADERBOARD_SORT_COLUMNS:
        sort_key = "balance"
    merged: dict[str, dict] = {}
    now_ts = int(time.time())

    # Only select columns needed for display (reduce data transfer by ~60%)
    select_cols = f"user_id, {sort_key}, balance, premium_until, username, first_name, is_bot, _c"

    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                if banned:
                    cur.execute(
                        f"SELECT {select_cols} FROM users ORDER BY {sort_key} DESC LIMIT %s",
                        (limit,)
                    )
                else:
                    cur.execute(
                        f"SELECT {select_cols} FROM users WHERE banned=0 AND is_bot=0 ORDER BY {sort_key} DESC LIMIT %s",
                        (limit,)
                    )
                rows = cur.fetchall()
                for row in rows:
                    data = dict(row)
                    uid = str(data.get("user_id", ""))
                    if uid in merged:
                        continue
                    merged[uid] = data
        except Exception as e:
            slot.ok = False
            slot.error = str(e)
            logger.debug(f"tidb_leaderboard failed on {slot.name}: {e}")

    rows = sorted(merged.values(), key=lambda r: int(r.get(sort_key, 0) or 0), reverse=True)[:limit]
    result = []
    for data in rows:
        uid = str(data.get("user_id", "") or "")
        username = data.get("username") or ""
        first_name = data.get("first_name") or ""
        # Priority: @username > first_name > display_name from blob > "User"
        if username:
            label = f"@{username}"
        elif first_name:
            label = first_name
        else:
            label = ""
            blob = data.get("_c")
            if blob:
                try:
                    blob_data = msgpack.unpackb(zlib.decompress(blob), raw=False)
                    if isinstance(blob_data, dict):
                        label = blob_data.get("display_name") or blob_data.get("first_name") or ""
                except Exception:
                    pass
            if not label:
                label = f"User{uid[-4:]}"
        value = int(data.get(sort_key, 0) or 0)
        balance_val = int(data.get("balance", 0) or 0)
        premium_until = int(data.get("premium_until", 0) or 0)
        badge = "⭐" if premium_until > now_ts else "👤"
        result.append({"user_id": uid, "label": label, "value": value, "balance": balance_val, "badge": badge})
    return result


def tidb_get_global_rank(uid: str) -> int:
    # Use ultra-light balance (1 RU vs 3 RU) to save 66% cost
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    balance = tidb_get_balance(uid)
    # If balance is 0, check if user actually exists (could be 0 or missing)
    # Use light check to distinguish missing (rank 0) vs 0 balance (rank last)
    if balance == 0:
        # Verify user exists via light, if not exists return 0
        data = tidb_get_user_light(uid)
        if not data:
            return 0
        balance = int(data.get("balance", 0) or 0)

    def _count_slot(slot):
        if not slot.ok:
            return 0
        try:
            conn = slot.get_conn()
            if not conn:
                return 0
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) AS cnt FROM users WHERE balance>%s AND banned=0", (balance,))
                row = cur.fetchone()
            slot.ok = True
            return int(row.get("cnt", 0) or 0) if row else 0
        except Exception as e:
            slot.ok = False
            slot.error = str(e)
            return 0

    total_above = 0
    ex = _SLOT_EXECUTOR
    for cnt in ex.map(_count_slot, list(pool.slots)):
        total_above += cnt
    return total_above + 1


def tidb_bulk_save(users_data: list[tuple[str, dict]]) -> int:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    _ru_throttle(RU_COST["bulk_insert_500"])
    by_slot: dict[str, list] = {}
    for uid, data in users_data:
        # Full-row save carries ABSOLUTE final values (they already include any
        # coalesced net deltas we merged into the cache). Drop those pending
        # deltas so the delta buffer never re-applies them on top of the
        # absolute row (would double-subtract Aman's -5-2=-7 and then write -7
        # again on top of the already-correct absolute balance).
        tidb_consume_balance_delta(str(uid))
        tidb_consume_increment(str(uid))
        slot = pool.slot_by_modulo(str(uid))
        if slot:
            by_slot.setdefault(slot.name, []).append((uid, data))

    total = 0
    for slot_name, slot_users in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            cols = sorted(USER_COLUMNS)
            placeholders = ", ".join(["%s"] * len(cols))
            upsert_extra = ", ".join(f"{c}=VALUES({c})" for c in cols if c != "user_id")
            sql = f"INSERT INTO users ({', '.join(cols)}) VALUES ({placeholders}) ON DUPLICATE KEY UPDATE {upsert_extra}"

            batch = []
            for uid, data in slot_users:
                try:
                    uid_int = _sanitize_uid(uid)
                except (ValueError, TypeError):
                    continue
                if not isinstance(data, dict):
                    continue
                row = _user_to_row(data)
                row["user_id"] = uid_int
                batch.append([row.get(c) for c in cols])

            with conn.cursor() as cur:
                cur.executemany(sql, batch)
            conn.commit()
            total += len(slot_users)
        except Exception as e:
            slot.ok = False
            slot.error = str(e)
            logger.warning("tidb_bulk_save failed on %s", slot.name, exc_info=True)
    return total


def tidb_count_users() -> int:
    pool = get_pool()
    pool.ensure_recovered()
    pool = get_pool()
    _ru_throttle(RU_COST["select"])
    total = 0
    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) AS cnt FROM users")
                row = cur.fetchone()
                if row:
                    total += int(row.get("cnt", 0) or 0)
        except Exception as e:
            logger.warning("Exception: %s", str(e))
    return total


def tidb_list_all_users(batch_size: int = 0) -> list[tuple[str, dict]]:
    pool = get_pool()

    def _fetch_slot(slot):
        rows_out: list[tuple[str, dict]] = []
        if not slot.ok:
            return rows_out
        try:
            conn = slot.get_conn()
            if not conn:
                return rows_out
            with conn.cursor() as cur:
                if batch_size > 0:
                    offset = 0
                    while True:
                        cur.execute("SELECT * FROM users LIMIT %s OFFSET %s", (batch_size, offset))
                        rows = cur.fetchall()
                        if not rows:
                            break
                        for row in rows:
                            data = _row_to_user_dict(dict(row))
                            uid = data.get("user_id", "")
                            if uid:
                                rows_out.append((uid, data))
                        if len(rows) < batch_size:
                            break
                        offset += len(rows)
                else:
                    cur.execute("SELECT * FROM users")
                    rows = cur.fetchall()
                    for row in rows:
                        data = _row_to_user_dict(dict(row))
                        uid = data.get("user_id", "")
                        if uid:
                            rows_out.append((uid, data))
        except Exception as e:
            slot.error = str(e)
        return rows_out

    results: list[tuple[str, dict]] = []
    ex = _SLOT_EXECUTOR
    for part in ex.map(_fetch_slot, list(pool.slots)):
        results.extend(part)
    return results


