def _sticker_encode(value: Any) -> str:
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    except Exception:
        logger.warning("Exception in _sticker_encode", exc_info=True)
        return str(value)


def _sticker_decode(raw: Any, default: Any = None) -> Any:
    if raw is None:
        return default
    if isinstance(raw, (dict, list, int, float, bool)):
        return raw
    try:
        return json.loads(raw)
    except Exception:
        logger.warning("Exception in _sticker_decode", exc_info=True)
        return default


