def tidb_get_registered_chats() -> list[dict]:
    """Read registered chats from all TiDB slots (written by tidb_register_chat)."""
    pool = get_pool()
    results: list[dict] = []
    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                cur.execute("SELECT chat_id, chat_data FROM chats")
                for row in cur.fetchall():
                    cid = row.get("chat_id") if isinstance(row, dict) else row[0]
                    raw = row.get("chat_data") if isinstance(row, dict) else row[1]
                    try:
                        data = json.loads(raw) if raw else {}
                    except Exception:
                        data = {}
                    if not isinstance(data, dict):
                        data = {}
                    data.setdefault("_id", cid)
                    data.setdefault("chat_id", cid)
                    results.append(data)
            conn.close()
        except Exception:
            logger.debug("tidb_get_registered_chats slot %s failed", slot.name, exc_info=True)
    return results


