def _ti_ensure_storage_slots():
    pool = get_pool()
    if not pool._initialized:
        pool.init()
    if not any(s.ok for s in pool.slots):
        init_schema()
        pool.health_check()


# ═══════════════════════════════════════════════════════════════
# SMART RU-SAVING TECHNIQUES (Tier 1 — existing)
# ═══════════════════════════════════════════════════════════════

# ── 1. Dirty Write Coalescing ──────────────────────────────────
_tidb_dirty: dict[str, dict] = {}
_tidb_dirty_lock = threading.RLock()

def tidb_mark_dirty(uid: str, data: dict):
    with _tidb_dirty_lock:
        _tidb_dirty[str(uid)] = dict(data)

def tidb_dirty_count() -> int:
    with _tidb_dirty_lock:
        return len(_tidb_dirty)

def tidb_flush_dirty(batch_size: int = 500) -> int:
    with _tidb_dirty_lock:
        if not _tidb_dirty:
            return 0
        batch = [(uid, data) for uid, data in _tidb_dirty.items() if data is not None]
        _tidb_dirty.clear()
    if not batch:
        return 0
    saved = 0
    for i in range(0, len(batch), batch_size):
        chunk = batch[i:i + batch_size]
        try:
            saved += tidb_bulk_save(chunk)
        except Exception as e:
            logger.warning("Dirty flush batch failed, re-queueing", exc_info=True)
            with _tidb_dirty_lock:
                for uid, data in chunk:
                    _tidb_dirty.setdefault(uid, data)
    return saved


_TIDB_QUERY_CACHE = TTLCache(maxsize=100, ttl=30) if TTLCache else {}
_TIDB_QUERY_CACHE_LOCK = threading.RLock()

def _qc_get(key: str):
    with _TIDB_QUERY_CACHE_LOCK:
        return _TIDB_QUERY_CACHE.get(key)

def _qc_set(key: str, value, ttl: int = 30):
    with _TIDB_QUERY_CACHE_LOCK:
        try:
            if isinstance(_TIDB_QUERY_CACHE, dict) and len(_TIDB_QUERY_CACHE) >= 100:
                _TIDB_QUERY_CACHE.clear()
            _TIDB_QUERY_CACHE[key] = value
        except Exception:
            logger.warning("Exception in _qc_set", exc_info=True)

def tidb_cached_leaderboard(sort_key: str, limit: int = 10) -> list:
    """Leaderboard with TTL cache — saves ~100 RU per call."""
    cache_key = f"lb:{sort_key}:{limit}"
    cached = _qc_get(cache_key)
    if cached is not None:
        return cached
    result = tidb_leaderboard(sort_key, limit)
    if result:
        _qc_set(cache_key, result, ttl=120)
    return result

def tidb_cached_global_rank(uid: str) -> int:
    """Global rank with TTL cache — saves ~50 RU per call."""
    cache_key = f"rank:{uid}"
    cached = _qc_get(cache_key)
    if cached is not None:
        return cached
    result = tidb_get_global_rank(uid)
    if result > 0:
        _qc_set(cache_key, result, ttl=60)
    return result

def tidb_cached_count_users() -> int:
    """User count with TTL cache — saves ~50 RU per call."""
    cached = _qc_get("user_count")
    if cached is not None:
        return cached
    result = tidb_count_users()
    _qc_set("user_count", result, ttl=300)
    return result

def tidb_invalidate_cache(pattern: str = None):
    """Invalidate query cache entries matching pattern."""
    with _TIDB_QUERY_CACHE_LOCK:
        if pattern is None:
            _TIDB_QUERY_CACHE.clear()
            return
        keys = list(_TIDB_QUERY_CACHE.keys())
        for k in keys:
            if pattern in str(k):
                try:
                    del _TIDB_QUERY_CACHE[k]
                except Exception:
                    logger.warning("Exception in tidb_invalidate_cache", exc_info=True)

# ── 3. Column-Prune Update (only changed columns) ─────────────
def tidb_update_columns(uid: str, set_fields: dict) -> bool:
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return False
    if not set_fields:
        return True

    _ru_throttle(RU_COST["update"])
    now_ts = int(time.time())
    set_fields = dict(set_fields)  # copy to avoid mutating caller's dict
    set_fields["updated_at"] = now_ts

    # Only include columns that exist in the schema
    valid_cols = {k for k in set_fields if k in USER_COLUMNS_NO_BLOB or k == "_c"}
    if not valid_cols:
        return True

    set_sql = ", ".join(f"{k}=%s" for k in valid_cols)
    vals = [set_fields[k] for k in valid_cols] + [_sanitize_uid(uid)]

    try:
        conn = slot.get_conn()
        if not conn:
            return False
        with conn.cursor() as cur:
            cur.execute(f"UPDATE users SET {set_sql} WHERE user_id=%s", vals)
        conn.commit()
        return True
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.ok = False
        slot.error = str(e)
        return False

# ── 4. Fast last_seen Update (bypass full write) ──────────────
# last_seen changes on EVERY user interaction. Writing full row = waste.
# Instead, batch last_seen updates separately and flush every 30s.

_last_seen_buffer: dict[str, int] = {}
_last_seen_lock = threading.RLock()

# Max entries in last_seen buffer to prevent unbounded growth
_MAX_LAST_SEEN = 200000

# ── 5. Batched Stats (daily/weekly/lifetime) — cost saving ──────────────
# daily_income, weekly_income etc. change on every loot/capt but are not
# critical for immediate consistency. Batch them and flush every 60s to
# save 80% RU (1 bulk vs N individual).
_STATS_BUFFER: dict[str, dict[str, int]] = {}
_STATS_LOCK = threading.RLock()
_MAX_STATS = 100000

def buffer_stats_inc(uid: str, inc_fields: dict):
    """Buffer non-critical stats inc (daily/weekly) for batched flush. Returns remaining critical inc."""
    critical = {"balance", "rp", "captures", "level", "banned", "premium_until"}
    # Separate critical vs batchable
    batchable = {k: v for k, v in inc_fields.items() if k not in critical}
    remaining = {k: v for k, v in inc_fields.items() if k in critical}
    if not batchable:
        return inc_fields
    # Buffer the batchable part
    with _STATS_LOCK:
        if len(_STATS_BUFFER) >= _MAX_STATS:
            # Drop oldest to prevent OOM
            for k in list(_STATS_BUFFER.keys())[:20000]:
                _STATS_BUFFER.pop(k, None)
        buf = _STATS_BUFFER.get(uid)
        if buf is None:
            _STATS_BUFFER[uid] = dict(batchable)
        else:
            for k, v in batchable.items():
                buf[k] = int(buf.get(k, 0) or 0) + int(v or 0)
    return remaining

def tidb_flush_stats() -> int:
    """Flush batched stats to TiDB via bulk CASE UPDATE. Called every 60s."""
    global _STATS_BUFFER
    with _STATS_LOCK:
        if not _STATS_BUFFER:
            return 0
        batch = dict(_STATS_BUFFER)
        _STATS_BUFFER.clear()
    if not batch:
        return 0
    pool = get_pool()
    # Group by slot
    by_slot: dict[str, dict[str, dict[str,int]]] = {}
    for uid, incs in batch.items():
        slot = pool.slot_by_modulo(str(uid))
        if slot and slot.ok:
            by_slot.setdefault(slot.name, {})[uid] = incs
    flushed = 0
    for slot_name, uid_incs in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            # Fallback to relay for this batch
            for uid, incs in uid_incs.items():
                try:
                    # Apply to relay directly
                    data = _relay_get_user(uid) or {}
                    for k, v in incs.items():
                        data[k] = int(data.get(k,0) or 0) + int(v or 0)
                    data["updated_at"] = int(time.time())
                    _relay_save_user(uid, data)
                    # Also update cache if present
                    cached = USER_CACHE.get(uid)
                    if cached:
                        for k, v in incs.items():
                            cached[k] = int(cached.get(k,0) or 0) + int(v or 0)
                        cached["updated_at"] = int(time.time())
                except Exception:
                    pass
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                # Build CASE for each column
                # Collect all cols that appear
                all_cols = set()
                for incs in uid_incs.values():
                    all_cols.update(incs.keys())
                for col in all_cols:
                    whens = []
                    vals = []
                    for uid, incs in uid_incs.items():
                        if col in incs:
                            whens.append(f"WHEN user_id=%s THEN {col}+%s")
                            vals.extend([int(uid), int(incs[col])])
                    if not whens:
                        continue
                    placeholders = ",".join(["%s"]*len([uid for uid in uid_incs if col in uid_incs[uid]]))
                    # Build CASE
                    case_sql = f"UPDATE users SET {col} = CASE user_id {' '.join(whens)} ELSE {col} END, updated_at=%s WHERE user_id IN ({placeholders})"
                    # vals already has WHENs, need updated_at and IN list
                    exec_vals = []
                    for uid, incs in uid_incs.items():
                        if col in incs:
                            exec_vals.extend([int(uid), int(incs[col])])
                    exec_vals.append(int(time.time()))
                    exec_vals.extend([int(uid) for uid in uid_incs if col in uid_incs[uid]])
                    cur.execute(case_sql, exec_vals)
            conn.commit()
            flushed += len(uid_incs)
            _ru_throttle(RU_COST["update"] * len(uid_incs) // 10)  # bulk saves 90% RU
        except Exception as e:
            logger.warning(f"flush_stats {slot_name} failed: {e}")
            slot.ok = False
            slot.error = str(e)
    return flushed

_stats_flush_task: Optional[asyncio.Task] = None

async def _periodic_stats_flush(interval: float = 60.0):
    """Background: flush batched stats + last_seen every 60s to save 80% RU."""
    while True:
        try:
            await asyncio.sleep(interval)
            flushed = await asyncio.to_thread(tidb_flush_stats)
            if flushed:
                logger.info(f"[stats] Flushed {flushed} batched stats")
            ls = await asyncio.to_thread(tidb_flush_last_seen)
            if ls:
                logger.info(f"[last_seen] Flushed {ls}")
            # Coalesced balance deltas: only flush ALL if this is a long interval
            # (>= debounce) so rapid successive purchases (Aman: 5 then 2) land
            # as ONE net write of the final value, not one write per transaction.
            try:
                await asyncio.to_thread(tidb_flush_balance, interval >= _BAL_DEBOUNCE_MS / 1000.0)
            except Exception:
                pass
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"periodic stats flush err {e}")

def start_stats_flush_task(interval: float = 60.0):
    global _stats_flush_task
    if _stats_flush_task is not None and not _stats_flush_task.done():
        return
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            _stats_flush_task = asyncio.create_task(_periodic_stats_flush(interval))
            logger.info(f"[stats] Background flush started {interval}s")
    except RuntimeError:
        pass

_bal_flush_task: Optional[asyncio.Task] = None

async def _periodic_balance_flush(interval: float = 2.0):
    """Background: coalesce pending balance deltas into a SINGLE batched TiDB
    write. Runs on a short debounce window so that rapid successive purchases
    (Aman: 5 then 2 toffee within a couple of seconds) collapse into one net
    write of the final value — saving ~80% RU on the hot path."""
    while True:
        try:
            await asyncio.sleep(interval)
            flushed = await asyncio.to_thread(tidb_flush_balance, True)
            if flushed:
                logger.debug(f"[balance] Coalesced {flushed} balance writes")
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.debug(f"periodic balance flush err {e}")

def start_balance_flush_task(interval: float = 2.0):
    global _bal_flush_task
    if _bal_flush_task is not None and not _bal_flush_task.done():
        return
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            _bal_flush_task = asyncio.create_task(_periodic_balance_flush(interval))
            logger.info(f"[balance] Coalescing flush started {interval}s")
    except RuntimeError:
        pass

def tidb_touch_user(uid: str):
    with _last_seen_lock:
        if len(_last_seen_buffer) >= _MAX_LAST_SEEN:
            # Flush oldest entries instead of dropping
            keys = list(_last_seen_buffer.keys())[:50000]
            for k in keys:
                del _last_seen_buffer[k]
        _last_seen_buffer[str(uid)] = int(time.time())

def tidb_flush_last_seen() -> int:
    """Flush buffered last_seen updates to TiDB in bulk using CASE UPDATE."""
    pool = get_pool()
    pool.ensure_recovered()
    global _last_seen_buffer
    with _last_seen_lock:
        if not _last_seen_buffer:
            return 0
        batch = dict(_last_seen_buffer)
        _last_seen_buffer.clear()

    if not batch:
        return 0

    pool = get_pool()
    by_slot: dict[str, dict[str, int]] = {}
    for uid, ts in batch.items():
        slot = pool.slot_by_modulo(str(uid))
        if slot and slot.ok:
            by_slot.setdefault(slot.name, {})[uid] = ts

    flushed = 0
    for slot_name, uid_ts in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        conn = None
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            _ru_throttle(RU_COST["update"])

            uids = list(uid_ts.keys())
            whens = " ".join(f"WHEN %s THEN %s" for _ in uids)
            placeholders = ", ".join(["%s"] * len(uids))
            sql = f"UPDATE users SET last_seen = CASE user_id {whens} ELSE last_seen END, updated_at=%s WHERE user_id IN ({placeholders})"

            params = []
            now_ts = int(time.time())
            for uid_str in uids:
                params.append(_sanitize_uid(uid_str))
                params.append(int(uid_ts[uid_str]))
            params.append(now_ts)
            params.extend(_sanitize_uid(u) for u in uids)

            with conn.cursor() as cur:
                cur.execute(sql, params)
            conn.commit()
            flushed += len(uids)
        except Exception as e:
            try:
                if conn:
                    conn.rollback()
            except Exception as rb_exc:
                logger.error(f"Rollback failed after last-seen flush error on {slot_name}: {rb_exc!r}", exc_info=True)
            slot.error = str(e)
            logger.debug(f"Last-seen flush failed on {slot_name}: {e}")

    return flushed

# ── 5. Lightweight Get (no blob decompress) ───────────────────
def tidb_get_user_light(uid: str) -> dict:
    """Get user WITHOUT decompressing _c blob. Saves ~70% RU vs full get.
    Returns only flat columns — use when you only need balance/rp/level.
    """
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return {}
    _ru_throttle(RU_COST["select"])
    try:
        conn = slot.get_conn()
        if not conn:
            return {}
        with conn.cursor() as cur:
            cols = ", ".join(sorted(USER_COLUMNS_NO_BLOB))
            cur.execute(f"SELECT {cols} FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
            row = cur.fetchone()
        if row:
            data = {}
            for k, v in row.items():
                if v is not None:
                    data[k] = v
            return data
        # Fallback: scan all slots for duplicates (hoshi rank 0 fix)
        for fb in pool.slots:
            if fb.name == slot.name or not fb.ok:
                continue
            try:
                conn2 = fb.get_conn()
                if not conn2:
                    continue
                with conn2.cursor() as cur2:
                    cols2 = ", ".join(sorted(USER_COLUMNS_NO_BLOB))
                    cur2.execute(f"SELECT {cols2} FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
                    row2 = cur2.fetchone()
                    if row2:
                        data = {}
                        for k, v in row2.items():
                            if v is not None:
                                data[k] = v
                        return data
            except Exception:
                continue
        return {}
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.error = str(e)
        return {}

def tidb_get_balance(uid: str) -> int:
    """Ultra-light balance only (1 column, 0.5 RU vs 3 RU). For rank/leaderboard."""
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return 0
    _ru_throttle(1)  # 1 RU vs 3 for light
    try:
        conn = slot.get_conn()
        if not conn:
            return 0
        with conn.cursor() as cur:
            cur.execute("SELECT balance FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
            row = cur.fetchone()
        if not row:
            # Fallback scan for duplicates
            for fb in pool.slots:
                if fb.name == slot.name or not fb.ok:
                    continue
                try:
                    conn2 = fb.get_conn()
                    if not conn2:
                        continue
                    with conn2.cursor() as cur2:
                        cur2.execute("SELECT balance FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
                        row2 = cur2.fetchone()
                        if row2:
                            return int(row2.get("balance", 0) or 0)
                except Exception:
                    continue
            return 0
        return int(row.get("balance", 0) or 0)
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        slot.error = str(e)
        return 0

# ── 6. Batch get (N users in 1 query) ─────────────────────────
def tidb_get_users_batch(uids: list[str]) -> dict[str, dict]:
    pool = get_pool()
    if not uids:
        return {}
    by_slot: dict[str, list[int]] = {}
    for uid in uids:
        slot = pool.slot_by_modulo(str(uid))
        if slot:
            by_slot.setdefault(slot.name, []).append(_sanitize_uid(uid))

    result: dict[str, dict] = {}
    _ru_throttle(RU_COST["select"] * max(1, len(by_slot)))

    for slot_name, uid_ints in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            placeholders = ", ".join(["%s"] * len(uid_ints))
            with conn.cursor() as cur:
                cur.execute(f"SELECT * FROM users WHERE user_id IN ({placeholders})", uid_ints)
                for row in cur.fetchall():
                    data = _row_to_user_dict(dict(row))
                    u = data.get("user_id", "")
                    if u:
                        result[u] = data
        except Exception as e:
            slot.ok = False
            slot.error = str(e)

    return result

# ── 7. No-op Detection ────────────────────────────────────────
def tidb_has_user(uid: str) -> bool:
    """Cheap existence check — no data transfer. ~1 RU vs 3 RU for SELECT *."""
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return False
    _ru_throttle(1)
    try:
        conn = slot.get_conn()
        if not conn:
            return False
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM users WHERE user_id=%s LIMIT 1", (_sanitize_uid(uid),))
            return cur.fetchone() is not None
    except Exception:
        logger.warning("Exception in tidb_has_user", exc_info=True)
        return False


# ═══════════════════════════════════════════════════════════════
# SMART RU-SAVING TECHNIQUES (Tier 2 — new)
# ═══════════════════════════════════════════════════════════════

# ── 8. Covering Indexes for Leaderboard ────────────────────────
# Index-only scans save table lookups (~50% RU on leaderboard queries).
# These are ADDED to USER_INDEXES_SQL (deployed via init_schema).
LEADERBOARD_COVERING_INDEXES = [
    "CREATE INDEX IF NOT EXISTS idx_balance_cover ON users(balance DESC, user_id, rp, level, captures)",
    "CREATE INDEX IF NOT EXISTS idx_rp_cover ON users(rp DESC, user_id, balance, level)",
    "CREATE INDEX IF NOT EXISTS idx_lifetime_income_cover ON users(lifetime_income DESC, user_id, balance)",
]

def deploy_covering_indexes():
    """Deploy leaderboard covering indexes to all clusters."""
    pool = get_pool()
    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                for idx_sql in LEADERBOARD_COVERING_INDEXES:
                    try:
                        cur.execute(idx_sql)
                    except Exception:
                        logger.warning("Exception in deploy_covering_indexes", exc_info=True)
            conn.commit()
        except Exception as e:
            logger.warning("Covering indexes failed on %s", slot.name, exc_info=True)


# ── 9. No-Op Write Skip (data hash tracking) ──────────────────
# If save_user is called with identical data, skip the SQL write entirely.
# Saves insert/update RU (~6-8 RU per skipped write) for redundant saves.
# Hashes are evicted after 3600s to prevent unbounded memory growth.
_tidb_data_hashes: dict[str, tuple[int, float]] = {}  # uid -> (hash, timestamp)
_tidb_hash_lock = threading.RLock()
_MAX_DATA_HASHES = 100000  # cap to prevent memory bloat

def _data_hash(data: dict) -> int:
    parts = []
    for col in sorted(USER_COLUMNS_NO_BLOB):
        v = data.get(col)
        if isinstance(v, int):
            parts.append(str(v))
        elif isinstance(v, str):
            parts.append(v)
        elif v is None:
            parts.append("")
        else:
            parts.append(str(v))
    for k in sorted(data.keys()):
        if k not in USER_COLUMNS:
            v = data[k]
            parts.append(str(v))
    return int(hashlib.md5("|".join(parts).encode()).hexdigest()[:16], 16)

def tidb_save_skip_if_unchanged(uid: str, data: dict) -> bool:
    h = _data_hash(data)
    uid_s = str(uid)
    now = time.time()
    with _tidb_hash_lock:
        prev = _tidb_data_hashes.get(uid_s)
        if prev is not None and prev[0] == h and now - prev[1] < 3600:
            return True
        _tidb_data_hashes[uid_s] = (h, now)
    return tidb_save_user(uid, data)

def tidb_mark_hash(uid: str, data: dict):
    with _tidb_hash_lock:
        _tidb_data_hashes[str(uid)] = (_data_hash(data), time.time())

def tidb_invalidate_hash(uid: str):
    with _tidb_hash_lock:
        _tidb_data_hashes.pop(str(uid), None)

def tidb_evict_stale_hashes():
    """Remove hashes older than 3600s AND enforce max size cap."""
    now = time.time()
    with _tidb_hash_lock:
        # Evict stale entries
        stale = [k for k, (_, ts) in _tidb_data_hashes.items() if now - ts > 3600]
        for k in stale:
            _tidb_data_hashes.pop(k, None)
        # Enforce max size — evict oldest if still over cap
        if len(_tidb_data_hashes) > _MAX_DATA_HASHES:
            sorted_keys = sorted(_tidb_data_hashes, key=lambda k: _tidb_data_hashes[k][1])
            excess = len(_tidb_data_hashes) - _MAX_DATA_HASHES
            for k in sorted_keys[:excess]:
                _tidb_data_hashes.pop(k, None)


# ── 10. Keyset Pagination for list_all_users ──────────────────
# Users are modulo-distributed across 5 shards, so a shared cursor
# doesn't work. Instead, LIMIT per shard individually.
# Saves RU by bounding the result set per shard.
def tidb_list_users_keyset(limit: int = 1000) -> list[tuple[str, dict]]:
    """List users with per-shard LIMIT (no cross-shard cursor)."""
    pool = get_pool()
    all_users: list[tuple[str, dict]] = []

    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            _ru_throttle(RU_COST["select"])
            with conn.cursor() as cur:
                cur.execute("SELECT * FROM users ORDER BY user_id ASC LIMIT %s", (limit,))
                rows = cur.fetchall()
            if not rows:
                continue
            for row in rows:
                data = _row_to_user_dict(dict(row))
                uid = data.get("user_id", "")
                if uid:
                    all_users.append((uid, data))
        except Exception as e:
            slot.error = str(e)

    return all_users


# ── 11. Increment Coalescing ───────────────────────────────────
# Merge multiple increments to the same user into one UPDATE.
# For example, 5 separate incs become 1 UPDATE — saves 4 transactions.
_tidb_inc_buffer: dict[str, dict] = {}
_tidb_inc_lock = threading.RLock()
_MAX_INC_BUFFER = 200000

# ── Balance-coalescing ledger ────────────────────────────────────────────
# Accumulates NET balance changes per user in memory and flushes once.
# Aman buying "5 toffee then 2 toffee" records -5 then -2 → net -7 → written
# to TiDB as a SINGLE batched UPDATE of the final value (one write, not two).
# This is the RU saver the user asked for: "write final 7, not 5 then 7".
_tidb_bal_buffer: dict[str, int] = {}
_tidb_bal_lock = threading.RLock()
_MAX_BAL_BUFFER = 200000
# Debounce window: changes are held, then the NET value is flushed once.
_BAL_DEBOUNCE_MS = 3000.0

def tidb_queue_balance_delta(uid: str, delta: int) -> None:
    """Record a net balance delta to be coalesced into a single DB write."""
    if delta == 0:
        return
    uid = str(uid)
    with _tidb_bal_lock:
        if len(_tidb_bal_buffer) >= _MAX_BAL_BUFFER:
            keys = list(_tidb_bal_buffer.keys())[:50000]
            for k in keys:
                del _tidb_bal_buffer[k]
        _tidb_bal_buffer[uid] = int(_tidb_bal_buffer.get(uid, 0) or 0) + delta

# Per-user serialization locks so concurrent balance mutations on the same uid
# (loot credits, shield buys, etc.) don't race the read-modify-write in the
# COALESCE path. Each uid gets its own RLock; no global bottleneck.
_tidb_bal_user_locks: dict[str, threading.RLock] = {}
_tidb_bal_user_guard = threading.Lock()

def _bal_user_lock(uid: str) -> threading.RLock:
    uid = str(uid)
    with _tidb_bal_user_guard:
        lock = _tidb_bal_user_locks.get(uid)
        if lock is None:
            lock = threading.RLock()
            _tidb_bal_user_locks[uid] = lock
        return lock

def tidb_balance_pending() -> int:
    with _tidb_bal_lock:
        return len(_tidb_bal_buffer)

def tidb_consume_balance_delta(uid: str) -> int:
    """Drop and return the pending net balance delta for a user.

    Called by the FULL-ROW save path: since the full row being written carries
    the ABSOLUTE final balance (which already includes this delta), applying the
    delta again would double-subtract. Dropping it keeps DB consistent."""
    uid = str(uid)
    with _tidb_bal_lock:
        return int(_tidb_bal_buffer.pop(uid, 0) or 0)

def tidb_consume_increment(uid: str) -> dict:
    """Drop and return any pending queued increments for a user.

    Same rationale as tidb_consume_balance_delta: when a FULL-ROW absolute
    write goes to TiDB for a user, all queued net deltas for that user must
    be dropped — the absolute row already reflects them, and applying the
    delta on top of the absolute value would double-count."""
    uid = str(uid)
    with _tidb_inc_lock:
        return _tidb_inc_buffer.pop(uid, None) or {}

def tidb_flush_balance(flush_all: bool = True) -> int:
    """Flush coalesced balance deltas to TiDB as ONE batched CASE UPDATE.

    Multiple rapid changes to the same user (Aman: -5 then -2) were already
    merged into a single net delta in _tidb_bal_buffer, so this writes the
    final value once. Implementation: fold net deltas into the existing
    increment buffer (tidb_flush_increments already builds the batched CASE
    UPDATE with RU throttle + shard retry) and flush it.
    Returns number of users whose balance delta reached TiDB.

    flush_all=False: fold only — the caller (flush_cache) flushes the
    increment buffer right after this, so skip the double flush.
    """
    with _tidb_bal_lock:
        if not _tidb_bal_buffer:
            return 0
        batch = dict(_tidb_bal_buffer)
        _tidb_bal_buffer.clear()
    if not batch:
        return 0
    for uid, delta in batch.items():
        if delta == 0:
            continue
        try:
            tidb_queue_increment(uid, {"balance": delta})
        except Exception:
            pass
    if flush_all:
        try:
            return tidb_flush_increments()
        except Exception:
            return 0
    return 0

def tidb_queue_increment(uid: str, inc_fields: dict):
    with _tidb_inc_lock:
        if len(_tidb_inc_buffer) >= _MAX_INC_BUFFER:
            # Flush oldest entries instead of dropping
            keys = list(_tidb_inc_buffer.keys())[:50000]
            for k in keys:
                del _tidb_inc_buffer[k]
        existing = _tidb_inc_buffer.get(str(uid))
        if existing:
            for k, v in inc_fields.items():
                existing[k] = int(existing.get(k, 0) or 0) + int(v or 0)
        else:
            _tidb_inc_buffer[str(uid)] = dict(inc_fields)

def tidb_flush_increments() -> int:
    """Flush all queued increments using batched CASE UPDATE. Returns count."""
    pool = get_pool()
    pool.ensure_recovered()
    with _tidb_inc_lock:
        if not _tidb_inc_buffer:
            return 0
        batch = dict(_tidb_inc_buffer)
        _tidb_inc_buffer.clear()

    if not batch:
        return 0

    # Group by slot
    pool = get_pool()
    by_slot: dict[str, dict[str, dict]] = {}
    for uid, incs in batch.items():
        slot = pool.slot_by_modulo(str(uid))
        if slot and slot.ok:
            by_slot.setdefault(slot.name, {})[uid] = incs

    flushed = 0
    for slot_name, uid_incs in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        conn = None
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            _ru_throttle(RU_COST["update"])

            # Build a single UPDATE with CASE per field
            # e.g. UPDATE users SET balance = balance + CASE user_id WHEN 1 THEN 10 WHEN 2 THEN 5 ELSE 0 END
            # WHERE user_id IN (1,2)
            uids = list(uid_incs.keys())
            all_inc_keys = set()
            for incs in uid_incs.values():
                all_inc_keys.update(incs.keys())
            # Only use columns that exist in the schema
            valid_keys = {k for k in all_inc_keys if k in USER_COLUMNS_NO_BLOB}
            if not valid_keys:
                continue

            case_parts = []
            for key in sorted(valid_keys):
                whens = " ".join(
                    f"WHEN %s THEN {key} + %s" for _ in uid_incs
                )
                case_parts.append(f"{key} = CASE user_id {whens} ELSE {key} END")

            set_clause = ", ".join(case_parts)
            placeholders = ", ".join(["%s"] * len(uids))
            sql = f"UPDATE users SET {set_clause}, updated_at=%s WHERE user_id IN ({placeholders})"

            params = []
            now_ts = int(time.time())
            for key in sorted(valid_keys):
                for uid_str in uids:
                    inc_val = int(uid_incs[uid_str].get(key, 0) or 0)
                    params.append(_sanitize_uid(uid_str))
                    params.append(inc_val)
            params.append(now_ts)
            params.extend(_sanitize_uid(u) for u in uids)

            with conn.cursor() as cur:
                cur.execute(sql, params)
            conn.commit()
            flushed += len(uids)
        except Exception as e:
            try:
                if conn:
                    conn.rollback()
            except Exception as rb_exc:
                logger.error(f"Rollback failed after increment flush error on {slot_name}: {rb_exc!r}", exc_info=True)
            slot.error = str(e)
            logger.debug(f"Increment flush failed on {slot_name}: {e}")

    return flushed

def tidb_increment_count() -> int:
    with _tidb_inc_lock:
        return len(_tidb_inc_buffer)


# ── 12. Pre-Computed Global Rank ──────────────────────────────
# Instead of COUNT(...) across 5 shards per rank check, pre-compute
# the full rank mapping periodically and serve from cache.
_tidb_rank_map: dict[str, int] = {}
_tidb_rank_ts: float = 0
_TIDB_RANK_TTL = 300.0  # recompute every 5 minutes (was 30s, increased to save RU)
_tidb_rank_lock = threading.RLock()

def tidb_build_rank_map() -> dict[str, int]:
    """Build full rank map (balance DESC) from all clusters.
    Collects all user/balance pairs, sorts globally, assigns ranks.
    Limited to top 20000 users to cap RU cost at ~20000 RU.
    """
    pool = get_pool()
    all_pairs: list[tuple[int, int]] = []  # (balance, user_id)

    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            _ru_throttle(RU_COST["select"] * 30)
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT user_id, balance FROM users ORDER BY balance DESC LIMIT 10000"
                )
                for row in cur.fetchall():
                    uid = int(row.get("user_id", 0))
                    bal = int(row.get("balance", 0) or 0)
                    if uid:
                        all_pairs.append((bal, uid))
        except Exception as e:
            slot.ok = False
            slot.error = str(e)

    # Sort globally by balance DESC, then by uid ASC for tie-breaking
    all_pairs.sort(key=lambda x: (-x[0], x[1]))

    # Cap at 20K to limit RU cost and memory
    _MAX_RANK_MAP = 20000
    rank_map: dict[str, int] = {}
    rank = 1
    seen: set[int] = set()
    for bal, uid in all_pairs:
        if uid in seen:
            continue
        seen.add(uid)
        rank_map[str(uid)] = rank
        rank += 1
        if rank > _MAX_RANK_MAP:
            break

    return rank_map

def tidb_cached_rank_v2(uid: str) -> int:
    """Get rank from pre-computed map, rebuilding if stale."""
    global _tidb_rank_map, _tidb_rank_ts
    now = time.time()
    # Fast path — check without lock
    if now - _tidb_rank_ts <= _TIDB_RANK_TTL and _tidb_rank_map:
        return _tidb_rank_map.get(str(uid), 0)
    # Slow path — rebuild
    with _tidb_rank_lock:
        now = time.time()
        if now - _tidb_rank_ts > _TIDB_RANK_TTL or not _tidb_rank_map:
            new_map = tidb_build_rank_map()
            if new_map:
                _tidb_rank_map = new_map
                _tidb_rank_ts = now
            if not _tidb_rank_map:
                return 0
        return _tidb_rank_map.get(str(uid), 0)


# ── 13. Batch Delete — Multiple users in 1 query per shard ────
def tidb_bulk_delete(uids: list[str]) -> int:
    """Delete multiple users by shard. Each shard = 1 DELETE query."""
    pool = get_pool()
    by_slot: dict[str, list[int]] = {}
    for uid in uids:
        slot = pool.slot_by_modulo(str(uid))
        if slot:
            by_slot.setdefault(slot.name, []).append(_sanitize_uid(uid))

    deleted = 0
    for slot_name, uid_ints in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            _ru_throttle(RU_COST["delete"])
            placeholders = ", ".join(["%s"] * len(uid_ints))
            with conn.cursor() as cur:
                cur.execute(f"DELETE FROM users WHERE user_id IN ({placeholders})", uid_ints)
            conn.commit()
            deleted += len(uid_ints)
        except Exception as e:
            slot.error = str(e)
    return deleted


# ── 14. Batch Atomic Update (no SELECT...FOR UPDATE) ──────────
# For bulk updates where we only need to SET (not INC), skip the
# transaction overhead. Single UPDATE query per user.
def tidb_batch_set(updates: list[tuple[str, dict]]) -> int:
    """Batch SET-only updates. Each user gets one UPDATE query.
    Saves ~15 RU/user vs full atomic_update (no SELECT...FOR UPDATE).
    """
    pool = get_pool()
    by_slot: dict[str, list[tuple[str, dict]]] = {}
    for uid, set_fields in updates:
        slot = pool.slot_by_modulo(str(uid))
        if slot and slot.ok:
            by_slot.setdefault(slot.name, []).append((uid, set_fields))

    updated = 0
    for slot_name, slot_updates in by_slot.items():
        slot = pool.slot_by_name(slot_name)
        if not slot or not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            now_ts = int(time.time())
            for uid, set_fields in slot_updates:
                _ru_throttle(RU_COST["update"])
                valid = {k: v for k, v in set_fields.items() if k in USER_COLUMNS_NO_BLOB}
                if not valid:
                    continue
                valid["updated_at"] = now_ts
                set_sql = ", ".join(f"{k}=%s" for k in valid)
                vals = list(valid.values()) + [_sanitize_uid(uid)]
                with conn.cursor() as cur:
                    cur.execute(f"UPDATE users SET {set_sql} WHERE user_id=%s", vals)
            conn.commit()
            updated += len(slot_updates)
        except Exception as e:
            slot.error = str(e)
    return updated


# ── 15. Read Prefetch — batch-load users before processing ────
# In hot paths (game commands in a group), many users are accessed.
# Prefetch all at once instead of N individual SELECTs.
def tidb_prefetch_users(uids: list[str]) -> dict[str, dict]:
    """Batch-load users from TiDB. Groups by shard, one query per shard.
    Same as tidb_get_users_batch but with RU throttling for bulk.
    """
    if not uids:
        return {}
    # Dedup
    unique = list(dict.fromkeys(str(u) for u in uids))
    result = tidb_get_users_batch(unique)
    return result


# ── 16. Connection Keepalive — reduce reconnect churn ──────────
# Each TiDB connection handshake costs RU. Keep connections alive
# with periodic pings instead of reconnecting every time.
_tidb_keepalive_ts: float = 0
_tidb_keepalive_interval = 30  # ping every 30s per connection

def tidb_keepalive():
    global _tidb_keepalive_ts
    now = time.time()
    if now - _tidb_keepalive_ts < _tidb_keepalive_interval:
        return
    _tidb_keepalive_ts = now

    pool = get_pool()
    for slot in pool.slots:
        try:
            conn = slot.get_conn()
            if conn:
                conn.ping(reconnect=True)
            slot.ok = True
            slot.error = ""
        except Exception:
            slot.ok = False
            slot.error = "keepalive failed"


# ── 17. Bulk Reset All Users (for owner panel data reset) ──────
_TIDB_RESET_COLUMN_MAP = {
    "b": "balance",
    "rp": "rp",
    "level": "level",
    "captures": "captures",
    "daily_income": "daily_income",
    "weekly_income": "weekly_income",
    "lifetime_income": "lifetime_income",
    "daily_captures": "daily_captures",
    "weekly_captures": "weekly_captures",
    "daily_redeem": "daily_redeem",
    "weekly_redeem": "weekly_redeem",
    "total_redeem_earned": "total_redeem_earned",
    "bn": "banned",
    "premium_until": "premium_until",
}

# Columns that must NEVER be reset — they carry broadcast routing info
_TIDB_RESET_PROTECTED_COLUMNS = frozenset({
    "user_id", "username", "first_name", "created_at",
})

def tidb_reset_all_users(set_fields: dict = None, unset_fields: list = None) -> dict:
    """Bulk reset user columns across all TiDB slots.
    
    Args:
        set_fields: dict of field_name -> value (e.g. {"balance": 0, "rp": 0})
        unset_fields: list of field names to null out
    
    Returns dict with total/updated/errors.
    """
    pool = get_pool()
    result = {"total": 0, "updated": 0, "errors": 0}
    
    # Map compressed MongoDB names to TiDB column names
    tidb_sets = {}
    if set_fields:
        for k, v in set_fields.items():
            col = _TIDB_RESET_COLUMN_MAP.get(k, k)
            if col in USER_COLUMNS_NO_BLOB and col not in _TIDB_RESET_PROTECTED_COLUMNS:
                tidb_sets[col] = v
    
    # If any unset fields are blob fields, also clear _c
    reset_blob = False
    if unset_fields:
        for k in unset_fields:
            col = _TIDB_RESET_COLUMN_MAP.get(k, k)
            if col not in USER_COLUMNS_NO_BLOB:
                reset_blob = True
                break
    
    # Strip protected columns from unset_fields
    if unset_fields:
        filtered = []
        for k in unset_fields:
            col = _TIDB_RESET_COLUMN_MAP.get(k, k)
            if col not in _TIDB_RESET_PROTECTED_COLUMNS:
                filtered.append(k)
        unset_fields = filtered
    
    if not tidb_sets and not unset_fields:
        return result
    
    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            
            # Count total users first
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) AS cnt FROM users")
                row = cur.fetchone()
                result["total"] += row.get("cnt", 0) if row else 0
            
            # Build SET clause for columns
            set_parts = []
            vals = []
            for col, val in tidb_sets.items():
                set_parts.append(f"{col}=%s")
                vals.append(val)
            
            # Handle unset (set to NULL for nullables)
            if unset_fields:
                for k in unset_fields:
                    col = _TIDB_RESET_COLUMN_MAP.get(k, k)
                    if col in USER_COLUMNS_NO_BLOB and col not in tidb_sets:
                        if col in ("level",):
                            set_parts.append(f"{col}=%s")
                            vals.append(1)
                        elif col in ("username", "first_name"):
                            set_parts.append(f"{col}=NULL")
                        else:
                            set_parts.append(f"{col}=%s")
                            vals.append(0)
            
            # Clear _c blob if any blob fields need resetting
            if reset_blob:
                set_parts.append("_c=NULL")
            
            now_ts = int(time.time())
            set_parts.append("updated_at=%s")
            vals.append(now_ts)
            
            if set_parts:
                set_sql = ", ".join(set_parts)
                with conn.cursor() as cur:
                    cur.execute(f"UPDATE users SET {set_sql}", vals)
                    result["updated"] += cur.rowcount or 0
                conn.commit()
        except Exception as e:
            logger.warning(f"tidb_reset_all_users failed on {slot.name}: {e}")
            slot.ok = False
            slot.error = str(e)
            result["errors"] += 1
    
    return result


def tidb_clear_all_users() -> dict:
    """Clear ALL user data from TiDB. Returns dict with slots_cleared count."""
    pool = get_pool()
    result = {"slots_cleared": 0, "errors": 0}
    for slot in pool.slots:
        if not slot.ok:
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                cur.execute("TRUNCATE TABLE users")
            conn.commit()
            result["slots_cleared"] += 1
        except Exception as e:
            logger.warning(f"tidb_clear_all_users failed on {slot.name}: {e}")
            result["errors"] += 1
    return result


# ═══════════════════════════════════════════════════════════════
# Covering Indexes — deploy to schema
# ── 18. TiDB storage stats (for dbstats) ──────────────────────
def tidb_storage_stats() -> list[dict]:
    """Return per-slot storage stats from information_schema."""
    pool = get_pool()
    results = []
    for slot in pool.slots:
        if not slot.ok:
            results.append({"name": slot.name, "ok": False})
            continue
        try:
            conn = slot.get_conn()
            if not conn:
                results.append({"name": slot.name, "ok": False})
                continue
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT TABLE_ROWS, DATA_LENGTH, INDEX_LENGTH "
                    "FROM information_schema.tables "
                    "WHERE TABLE_SCHEMA=%s AND TABLE_NAME='users'",
                    (slot.database,)
                )
                row = cur.fetchone()
            if row:
                rows = int(row.get("TABLE_ROWS", 0) or 0)
                data = int(row.get("DATA_LENGTH", 0) or 0)
                idx = int(row.get("INDEX_LENGTH", 0) or 0)
                results.append({
                    "name": slot.name,
                    "ok": True,
                    "rows": rows,
                    "data_bytes": data,
                    "index_bytes": idx,
                    "total_bytes": data + idx,
                })
            else:
                results.append({"name": slot.name, "ok": True, "rows": 0, "data_bytes": 0, "index_bytes": 0, "total_bytes": 0})
        except Exception as e:
            logger.warning(f"tidb_storage_stats failed on {slot.name}: {e}")
            results.append({"name": slot.name, "ok": False, "error": str(e)[:60]})
    return results


# ── 19. Fast user fetch (no blob) ─────────────────────────────
def tidb_get_user_fast(uid: str) -> dict:
    """Get user WITHOUT _c blob — ~70% less data transfer, no de/compress.
    Returns flat columns only. Use when blob fields (shield_until, etc.) aren't needed.
    """
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return {}
    _ru_throttle(RU_COST["select"])
    try:
        conn = slot.get_conn()
        if not conn:
            return {}
        cols = ", ".join(sorted(USER_COLUMNS_NO_BLOB))
        with conn.cursor() as cur:
            cur.execute(f"SELECT {cols} FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
            row = cur.fetchone()
        if not row:
            return {}
        data = {"user_id": str(row["user_id"])}
        for k, v in row.items():
            if k != "user_id" and v is not None:
                data[k] = v
        return data
    except Exception as e:
        logger.warning("Exception in tidb_get_user_fast", exc_info=True)
        slot.error = str(e)
        return {}


def tidb_load_blob(uid: str) -> dict:
    """Fetch and decompress _c blob for a user. Returns blob dict or {}."""
    pool = get_pool()
    slot = pool.slot_by_modulo(str(uid))
    if not slot or not slot.ok:
        return {}
    _ru_throttle(RU_COST["select"])
    try:
        conn = slot.get_conn()
        if not conn:
            return {}
        with conn.cursor() as cur:
            cur.execute("SELECT _c FROM users WHERE user_id=%s", (_sanitize_uid(uid),))
            row = cur.fetchone()
        if not row:
            return {}
        blob = row.get("_c")
        if not blob:
            return {}
        return msgpack.unpackb(zlib.decompress(blob), raw=False)
    except Exception as e:
        logger.debug(f"tidb_load_blob failed for {uid}: {e}")
        return {}


