import os
import time
import json
import threading
from pathlib import Path
from datetime import datetime, timedelta
from typing import Any, Optional

logger = get_logger(__name__)

DATA_DIR = Path("data")
RELAY_DB_FILE = DATA_DIR / "relay_store.sqlite3"

HEALTH_CHECK_INTERVAL = 300


class StorageForecaster:
    def __init__(self, history_minutes: int = 60):
        self._history: list[dict] = []
        self._history_minutes = history_minutes
        self._lock = threading.RLock()

    def record_snapshot(self, slots: list[dict]) -> None:
        now = time.time()
        cutoff = now - self._history_minutes * 60
        with self._lock:
            for slot in slots:
                self._history.append({
                    "ts": now,
                    "slot_id": slot.get("slot_id"),
                    "usage_percent": slot.get("usage_percent", 0),
                    "usage_bytes": slot.get("usage_bytes", 0),
                })
            self._history[:] = [h for h in self._history if h["ts"] > cutoff]

    def forecast_full_date(self, slot_id: int) -> str | None:
        with self._lock:
            points = [h for h in self._history if h["slot_id"] == slot_id]
        if len(points) < 3:
            return None
        points.sort(key=lambda p: p["ts"])
        first, last = points[0], points[-1]
        elapsed = last["ts"] - first["ts"]
        if elapsed <= 0:
            return None
        growth_per_sec = (last["usage_percent"] - first["usage_percent"]) / elapsed
        if growth_per_sec <= 0:
            return None
        remaining = (100 - last["usage_percent"]) / growth_per_sec
        if remaining > 365 * 86400:
            return None
        forecast_ts = last["ts"] + remaining
        return datetime.fromtimestamp(forecast_ts).isoformat()

    def growth_rate_per_hour(self, slot_id: int) -> float:
        with self._lock:
            points = [h for h in self._history if h["slot_id"] == slot_id]
        if len(points) < 3:
            return 0.0
        points.sort(key=lambda p: p["ts"])
        first, last = points[0], points[-1]
        elapsed = last["ts"] - first["ts"]
        if elapsed <= 0:
            return 0.0
        return (last["usage_percent"] - first["usage_percent"]) / (elapsed / 3600)


_forecaster = StorageForecaster()


class DBChecker:
    @staticmethod
    def relay_health() -> dict:
        try:
            db_path = Path(RELAY_DB_FILE)
            size = db_path.stat().st_size if db_path.exists() else 0
            wal_path = db_path.with_suffix(".sqlite3-wal")
            wal_size = wal_path.stat().st_size if wal_path.exists() else 0
            return {
                "ok": True,
                "size_bytes": size,
                "wal_size_bytes": wal_size,
                "path": str(db_path),
            }
        except Exception as e:
            return {"ok": False, "error": str(e)}

    @staticmethod
    def cache_analytics() -> dict:
        total = len(USER_CACHE)
        dirty = sum(len(s) for s in USER_CACHE._dirty)
        shard_sizes = [len(c) for c in USER_CACHE._caches]
        return {
            "total_users": total,
            "dirty_users": dirty,
            "dirty_pct": round(dirty / max(total, 1) * 100, 1),
            "shards": len(USER_CACHE._caches),
            "shard_sizes": shard_sizes[:10],
            "last_flush_ts": USER_CACHE._last_flush_ts,
            "warmup_done": USER_CACHE._warmup_done,
        }

    @staticmethod
    def tidb_health() -> dict:
        if not _use_tidb():
            return {"ok": False, "enabled": False, "reason": "TiDB not enabled or unavailable"}
        try:
            pool = get_pool()
            slots_info = []
            for slot in pool.slots:
                slots_info.append({
                    "name": slot.name,
                    "ok": slot.ok,
                    "error": slot.error or "",
                })
            return {
                "ok": any(s["ok"] for s in slots_info),
                "enabled": True,
                "slots": slots_info,
                "user_count": tidb_count_users(),
            }
        except Exception as e:
            return {"ok": False, "enabled": True, "error": str(e)}

    @staticmethod
    def mongo_health() -> dict:
        slots_info = []
        for slot in _mongo_slots:
            slots_info.append({
                "slot_id": slot.get("slot_id"),
                "ok": slot.get("ok", False),
                "full": slot.get("full", False),
                "usage_percent": slot.get("usage_percent", 0),
                "usage_bytes": slot.get("usage_bytes", 0),
                "limit_mb": slot.get("limit_mb", 512),
                "category": slot.get("category", "general"),
                "source": slot.get("source", "config"),
                "error": slot.get("error", "") or "",
            })
        return {
            "ok": any(s["ok"] for s in slots_info),
            "slots": slots_info,
            "healthy_count": sum(1 for s in slots_info if s["ok"]),
            "full_count": sum(1 for s in slots_info if s["full"]),
        }

    @staticmethod
    def consistency_spot_check(sample_size: int = 20) -> list[dict]:
        if not _use_tidb_for("users"):
            return []
        try:
            mongo_slot = _writable_mongo_slots_for_purpose("users")
            if not mongo_slot:
                return []
            results = []
            cursor = mongo_slot[0]["users"].find({}, {"_id": 1}).limit(sample_size)
            uids = [str(doc["_id"]) for doc in cursor if doc.get("_id")]
            for uid in uids[:sample_size]:
                tidb_data = tidb_get_user(uid)
                user_data = get_user(uid)
                issues = []
                for key in ("balance", "rp", "level", "banned"):
                    tv = tidb_data.get(key)
                    uv = user_data.get(key)
                    if tv is not None and uv is not None and int(tv) != int(uv):
                        issues.append({"field": key, "tidb": tv, "mongo": uv})
                results.append({
                    "uid": uid,
                    "in_tidb": bool(tidb_data),
                    "in_mongo": bool(user_data),
                    "issues": issues,
                    "healthy": len(issues) == 0,
                })
            return results
        except Exception as e:
            logger.warning("Consistency check failed", exc_info=True)
            return []


class DBRepair:
    @staticmethod
    def repair_stale_cache() -> int:
        epoch = _current_data_epoch()
        if epoch <= 0:
            return 0
        evicted = 0
        for sid in range(USER_CACHE._shard_count):
            with USER_CACHE._locks[sid]:
                to_remove = []
                for uid in USER_CACHE._caches[sid]:
                    ts = USER_CACHE._timestamps[sid].get(uid, 0)
                    data = USER_CACHE._caches[sid].get(uid)
                    if data and data.get("_data_epoch", 0) < epoch:
                        to_remove.append(uid)
                for uid in to_remove:
                    USER_CACHE._caches[sid].pop(uid, None)
                    USER_CACHE._dirty[sid].discard(uid)
                    USER_CACHE._timestamps[sid].pop(uid, None)
                    USER_CACHE._access_orders[sid].pop(uid, None)
                    evicted += 1
        return evicted

    @staticmethod
    def repair_orphaned_relay(limit: int = 1000) -> int:
        relay_users = list(_relay_iter_users(limit))
        if not relay_users:
            return 0
        orphaned: list[tuple[str, dict]] = []
        redundant: list[str] = []
        for uid, data in relay_users:
            if _use_tidb_for("users"):
                try:
                    existing = tidb_get_user(uid)
                except Exception:
                    existing = None
                if existing:
                    # TiDB is authoritative — stale relay copy must not overwrite it
                    redundant.append(uid)
                    continue
            orphaned.append((uid, data))
        if redundant:
            _relay_delete_users(redundant)
        if not orphaned:
            return 0
        saved = bulk_save_users(orphaned)
        if saved >= len(orphaned):
            _relay_delete_users([uid for uid, _ in orphaned])
            return saved
        return 0

    @staticmethod
    def repair_tidb_inconsistencies(sample_uid: str | None = None) -> dict:
        if not _use_tidb_for("users"):
            return {"repaired": 0}
        try:
            mongo_slot = _writable_mongo_slots_for_purpose("users")
            if not mongo_slot:
                return {"repaired": 0}
            uids: list[str] = []
            if sample_uid:
                uids = [sample_uid]
            else:
                cursor = mongo_slot[0]["users"].find({}, {"_id": 1}).limit(50)
                uids = [str(doc["_id"]) for doc in cursor if doc.get("_id")]
            repaired = 0
            for uid in uids:
                tidb_data = tidb_get_user(uid)
                if tidb_data:
                    continue
                mongo_data = get_user(uid)
                if not mongo_data:
                    continue
                ok = tidb_save_user(uid, mongo_data)
                if ok:
                    repaired += 1
            return {"repaired": repaired, "checked": len(uids)}
        except Exception as e:
            logger.warning("TiDB inconsistency repair failed", exc_info=True)
            return {"repaired": 0, "error": str(e)}


def full_health_report() -> dict:
    checker = DBChecker()
    relay = checker.relay_health()
    cache = checker.cache_analytics()
    tidb = checker.tidb_health()
    mongo = checker.mongo_health()
    consistency = checker.consistency_spot_check(10)

    storage = get_storage_status()
    limits = full_limit_report()

    for slot in mongo.get("slots", []):
        _forecaster.record_snapshot([slot])

    forecast = {}
    for slot in mongo.get("slots", []):
        sid = slot.get("slot_id")
        if sid:
            fdate = _forecaster.forecast_full_date(sid)
            growth = _forecaster.growth_rate_per_hour(sid)
            if fdate or growth:
                forecast[str(sid)] = {"forecast_full": fdate or "stable", "growth_pct_per_hour": round(growth, 3)}

    return {
        "timestamp": time.time(),
        "storage_mode": storage.get("mode", "unknown"),
        "relay": relay,
        "cache": cache,
        "tidb": tidb,
        "mongo": mongo,
        "consistency_spot_check": consistency,
        "forecast": forecast,
        "limits": limits,
        "alerts": storage.get("alerts", []),
    }


def auto_heal(dry_run: bool = False) -> dict:
    """Run all auto-repair routines. Returns summary dict."""
    actions = {}

    evicted = DBRepair.repair_stale_cache()
    actions["stale_cache_evicted"] = evicted

    orphaned = DBRepair.repair_orphaned_relay(500)
    actions["orphaned_relay_synced"] = orphaned

    tidb_fix = DBRepair.repair_tidb_inconsistencies()
    actions["tidb_inconsistencies_repaired"] = tidb_fix.get("repaired", 0)

    # Proactive limit enforcement
    try:
        limits = full_limit_report()
        actions["budget_tier"] = limits["tidb"]["tier"]
        actions["write_priority"] = limits["write_priority"]
        if limits["mongo"]["critical_count"] > 0:
            logger.warning(f"Mongo critical slots: {limits['mongo']['critical_count']}")
        if limits["tidb"]["pct"] > 90:
            logger.warning(f"TiDB RU budget at {limits['tidb']['pct']}% — throttling active")
        if should_skip_noncritical_write():
            actions["noncritical_writes_skipped"] = True
    except Exception as exc:
        logger.debug(f"Limit check failed: {exc}")

    if evicted or orphaned or tidb_fix.get("repaired"):
        logger.info(f"Auto-heal: stale={evicted}, relay_orphans={orphaned}, tidb_fixes={tidb_fix.get('repaired', 0)}")
    return actions


def quick_health_summary() -> str:
    """Lightweight health summary string (no DB pings — fast)."""
    parts = []
    try:
        rh = DBChecker.relay_health()
        parts.append(f"Relay={'OK' if rh.get('ok') else 'ISSUE'}")
    except Exception:
        parts.append("Relay=ERR")
    try:
        mh = DBChecker.mongo_health()
        ok_count = sum(1 for s in mh.get("slots", []) if s.get("ok"))
        parts.append(f"Mongo={ok_count}/{len(mh.get('slots', []))}")
    except Exception:
        parts.append("Mongo=ERR")
    try:
        th = DBChecker.tidb_health()
        parts.append(f"TiDB={'OK' if th.get('ok') else 'N/A'}")
    except Exception:
        parts.append("TiDB=ERR")
    try:
        ca = DBChecker.cache_analytics()
        parts.append(f"Cache={ca.get('total_users', '?')} users")
    except Exception:
        parts.append("Cache=ERR")
    return " | ".join(parts)

