# ============================================================================
# PREMIUM UTILITIES
# ============================================================================

_premium_cache: dict[int, tuple[bool, float]] = {}  # uid -> (is_premium, expiry)
_PREMIUM_CACHE_TTL = 300  # 5 minutes

def is_premium(uid: int) -> bool:
    """Check if user has active premium. Cached for 5 minutes."""
    now = time.time()
    cached = _premium_cache.get(uid)
    if cached and cached[1] > now:
        return cached[0]
    user = get_user(uid)
    result = bool(user and user.get("premium_until", 0) > now)
    _premium_cache[uid] = (result, now + _PREMIUM_CACHE_TTL)
    # Evict old entries periodically
    if len(_premium_cache) > 10000:
        for k, v in list(_premium_cache.items()):
            if v[1] < now:
                _premium_cache.pop(k, None)
    return result


def premium_badge(uid: int) -> str:
    """Get premium badge emoji."""
    return "⭐" if is_premium(uid) else "👤"


def premium_days_left(uid: int) -> int:
    """Get days left in premium."""
    user = get_user(uid) or {}
    remaining = int(user.get("premium_until", 0) - time.time())
    return max(0, remaining // 86400)


def premium__fmt(seconds: int) -> str:
    """Format seconds into human-readable time."""
    if seconds <= 0:
        return "0d 0h 0m"
    return f"{seconds//86400}d {(seconds%86400)//3600}h {(seconds%3600)//60}m"


