async def addpremium(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Add premium to a user (owner only)."""
    if update.effective_user.id != OWNER_ID:
        await update.effective_message.reply_text("Owner only.")
        return
    
    msg = update.effective_message
    if msg.reply_to_message and msg.reply_to_message.from_user and ctx.args:
        try:
            days = int((ctx.args or [""])[0].replace("d", ""))
            uid = msg.reply_to_message.from_user.id
        except ValueError:
            await msg.reply_text("Usage: /addpremium [days] [id]")
            return
    elif ctx.args and len(ctx.args) >= 2:
        try:
            days = int(ctx.args[0].replace("d", ""))
            uid = int(ctx.args[1])
        except ValueError:
            await msg.reply_text("Usage: /addpremium [days] [id]")
            return
    else:
        await msg.reply_text(
            "Usage: /addpremium [days] [id]  or reply + /addpremium 30"
        )
        return
    
    user = await asyncio.to_thread(get_user, uid) or {}
    expiry = max(int(time.time()), user.get("premium_until", 0)) + days * 86400
    await asyncio.to_thread(update_user_atomic, uid, set_fields={"premium_until": expiry})
    # Invalidate the premium cache so the change takes effect immediately
    import sys as _sys
    _main_mod = _sys.modules.get("__main__")
    invalidate_premium_cache = getattr(_main_mod, "invalidate_premium_cache", None)
    invalidate_premium_cache(uid)
    
    try:
        await ctx.bot.send_message(
            uid,
            (
                f"⭐ Congratulations, you purchased premium for <b>{days} day(s)</b>.\n\n"
                "Your premium features are now active.\n\n"
                f"{BUY_TEXT}"
            ),
            parse_mode="HTML",
        )
    except Exception as e:
        logger.debug(f"Notification failed: {e}")
    await msg.reply_html(f"⭐ Premium added to <code>{uid}</code> for <b>{days}d</b>.")


def _get_target(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> tuple:
    """Extract target user ID from reply or command args."""
    msg = update.effective_message
    if msg and msg.reply_to_message and msg.reply_to_message.from_user:
        uid = msg.reply_to_message.from_user.id
        return (uid, msg.reply_to_message.from_user.first_name or "")
    if ctx.args:
        try:
            raw = ctx.args[0].strip()
            uid = int(raw.replace("@id", "", 1))
            return (uid, raw)
        except (ValueError, IndexError):
            logger.warning("(ValueError|IndexError) in _get_target")
    return (None, None)


