async def backupid_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """
    /backupid — Premium backup linking system (2 categories)

    Categories:
    🔗 Generate Code — creates link code for second account
    🔓 Redeem Code   — links to a code from first account

    24h Ping-Pong Block Rules:
    1. After linking, BOTH accounts blocked for 24h
    2. Account A uses bot → Account B blocked for 24h more
    3. Account B uses bot → Account A blocked for 24h more
    4. After 24h with no usage by either → both freed, can export
    5. One account → one linked code at a time
    6. Code stays constant until delinked
    """
    user = update.effective_user
    query = update.callback_query
    msg = update.effective_message

    if not user:
        return

    data = await asyncio.to_thread(get_user, user.id) or {}
    now = time.time()

    prem = data.get("premium_until", 0)
    if prem <= now:
        if query:
            await query.answer("⭐ Premium required!", show_alert=True)
        elif msg:
            await msg.reply_text(
                "⭐ Backup Link is a premium-only feature.\n"
                "💎 Get premium at /buy to unlock this!"
            )
        return

    # ── CALLBACK QUERIES ──────────────────────────────────────────
    if query:
        await query.answer()
        action = query.data

        if action == "bup_generate":
            # Check if user is blocked
            block_until = data.get("backup_block_until", 0)
            if block_until > now:
                remaining = int(block_until - now)
                h, m = divmod(remaining // 60, 60)
                await query.answer(f"⛔ Blocked! Wait {h}h {m}m", show_alert=True)
                return

            link_code = data.get("backup_link_code", "")
            if not link_code:
                alphabet = string.ascii_uppercase + string.digits
                link_code = ''.join(secrets.choice(alphabet) for _ in range(10))
                await asyncio.to_thread(update_user_atomic, str(user.id), set_fields={
                    "backup_link_code": link_code,
                    "backup_link_created_at": now,
                })
            await query.edit_message_text(
                "🔗 <b>Link Code Generated</b>\n\n"
                f"<code>{link_code}</code>\n\n"
                "📋 Share this code with your second account.\n"
                "Second account must use <b>/linkback {code}</b>",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("📋 Copy Code", callback_data="bup_copy_gen")],
                    [InlineKeyboardButton("🔙 Back", callback_data="bup_back")],
                ]))
            return

        elif action == "bup_redeem":
            # Show code input screen
            await query.edit_message_text(
                "🔓 <b>Redeem a Link Code</b>\n\n"
                "Enter the 10-character code from the first account.\n\n"
                "⚠️ After redeeming, both accounts are <b>blocked for 24h</b>.\n"
                "Use <code>/linkback CODE</code> to redeem.",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🔙 Back", callback_data="bup_back")],
                ]))
            return

        elif action == "bup_delink":
            linked_code = data.get("backup_linked_code", "")
            link_code = data.get("backup_link_code", "")

            # Clear from global map
            if linked_code:
                raw = await asyncio.to_thread(_gs, "linked_backup_codes", {})
                if linked_code in raw:
                    del raw[linked_code]
                    await asyncio.to_thread(_ss, "linked_backup_codes", raw)

            # Clear user fields
            await asyncio.to_thread(update_user_atomic, str(user.id), set_fields={
                "backup_link_code": "",
                "backup_link_created_at": 0,
                "backup_linked_code": "",
                "backup_linked_at": 0,
                "backup_block_until": 0,
                "backup_linked_by": 0,
            })

            await query.answer("✅ Delinked!", show_alert=True)
            data2 = await asyncio.to_thread(get_user, user.id) or {}
            await _send_backup_menu(msg, user.id, data2, now)
            return

        elif action == "bup_refresh":
            data2 = await asyncio.to_thread(get_user, user.id) or {}
            await _send_backup_menu(msg, user.id, data2, now)
            return

        elif action == "bup_back":
            data2 = await asyncio.to_thread(get_user, user.id) or {}
            await _send_backup_menu(msg, user.id, data2, now)
            return

        elif action == "bup_copy_gen":
            data2 = await asyncio.to_thread(get_user, user.id) or {}
            code = data2.get("backup_link_code", "")
            if code:
                await query.answer(f"Code: {code}", show_alert=True)
            return

    # ── COMMAND HANDLER ─────────────────────────────────────────────
    if msg:
        await _send_backup_menu(msg, user.id, data, now)


async def _send_backup_menu(msg, uid: int, data: dict, now: float) -> None:
    """Send the backup menu with Generate / Redeem / Delink buttons."""
    link_code = data.get("backup_link_code", "")
    linked_code = data.get("backup_linked_code", "")
    linked_at = data.get("backup_linked_at", 0)
    linked_by = data.get("backup_linked_by", 0)
    block_until = data.get("backup_block_until", 0)
    last_used_at = data.get("backup_last_used_at", 0)

    # Check block status
    is_blocked = block_until > now
    remaining = max(0, int(block_until - now)) if is_blocked else 0
    h, m = divmod(remaining // 60, 60)

    # Determine status display
    if linked_code:
        raw = await asyncio.to_thread(_gs, "linked_backup_codes", {})
        link_data = raw.get(linked_code, {})
        expires_at = link_data.get("expires_at", 0)
        rem_exp = max(0, int(expires_at - now))
        eh, em = divmod(rem_exp // 60, 60)

        status = (
            f"🔗 <b>Linked to code:</b> <code>{linked_code}</code>\n"
            f"🆔 Linked by user: <code>{linked_by}</code>\n"
            f"⏰ Export window: <b>{eh}h {em}m</b>"
        )
        if is_blocked:
            status += f"\n\n⛔ <b>BLOCKED</b> — Wait <b>{h}h {m}m</b> to use linking"
        else:
            status += f"\n\n✅ <b>Export ready</b> — Use <code>/mybackup {linked_code}</code>"
    elif link_code:
        status = (
            f"📤 <b>Your Generate Code:</b> <code>{link_code}</code>\n"
            f"⚠️ Not yet linked.\n"
            f"Share with second account → <code>/linkback {link_code}</code>"
        )
        if is_blocked:
            status += f"\n\n⛔ <b>BLOCKED</b> — Wait <b>{h}h {m}m</b>"
    else:
        status = (
            "⚠️ No code generated yet.\n"
            "Tap <b>Generate Code</b> to create one."
        )
        if is_blocked:
            status += f"\n\n⛔ <b>BLOCKED</b> — Wait <b>{h}h {m}m</b>"

    # Block indicator in keyboard
    if is_blocked:
        status += f"\n\n⛔ You are blocked. <b>{h}h {m}m</b> remaining."

    text = (
        "🔑 <b>Backup Link System</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"{status}\n\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        "<b>Rules:</b>\n"
        "1️⃣ <b>Generate Code</b> → Account A creates code\n"
        "2️⃣ <b>Redeem Code</b> → Account B links to it\n"
        "3️⃣ After linking → only ONE account blocked at a time\n"
        "4️⃣ Account A blocked → Account B is FREE to use bot\n"
        "5️⃣ Account B uses bot → Account A gets blocked 24h\n"
        "6️⃣ When neither uses for 24h → both free → export with <code>/mybackup CODE</code>"
    )

    await msg.reply_html(text, reply_markup=InlineKeyboardMarkup([
        [InlineKeyboardButton("🔗 Generate Code", callback_data="bup_generate"),
         InlineKeyboardButton("🔓 Redeem Code", callback_data="bup_redeem")],
        [InlineKeyboardButton("🔓 Delink", callback_data="bup_delink")],
        [InlineKeyboardButton("🔄 Refresh", callback_data="bup_refresh")],
    ]))


# ── /linkback — second account redeems a code ────────────────────────────────
async def linkback_command(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Second account redeems code from first account.
    After linking → both accounts BLOCKED for 24h (ping-pong system).
    If A uses bot → B gets blocked again 24h.
    If B uses bot → A gets blocked again 24h.
    If neither uses for 24h → both freed, can export.
    """
    user = update.effective_user
    if not user:
        return

    msg = update.effective_message
    if not ctx.args:
        await msg.reply_text(
            "⚠️ Usage: <code>/linkback CODE</code>\n\n"
            "Use the 10-char code from Account A's /backupid",
            parse_mode="HTML"
        )
        return

    code = ctx.args[0].strip().upper()
    if len(code) != 10:
        await msg.reply_text("⚠️ Code must be exactly 10 characters.")
        return

    now = time.time()
    data = await asyncio.to_thread(get_user, user.id) or {}

    prem = data.get("premium_until", 0)
    if prem <= now:
        await msg.reply_text("⭐ Premium required. Get it at /buy")
        return

    # Check if this account itself is blocked
    self_block = data.get("backup_block_until", 0)
    if self_block > now:
        remaining = int(self_block - now)
        h, m = divmod(remaining // 60, 60)
        await msg.reply_html(
            f"⛔ <b>Account Blocked!</b>\n\n"
            f"Wait <b>{h}h {m}m</b> before redeeming another code.\n"
            f"Reason: Linked account used the bot recently."
        )
        return

    raw = await asyncio.to_thread(_gs, "linked_backup_codes", {})
    link_data = raw.get(code)

    # FIX: Default first_uid to 0 to prevent UnboundLocalError when code is new (link_data is None)
    first_uid = 0

    if link_data:
        # Code already redeemed
        first_uid = link_data.get("linked_uid", 0)
        first_time = link_data.get("linked_at", 0)

        # 24h window check
        if now - first_time < 86400 and first_uid:
            if str(first_uid) == str(user.id):
                await msg.reply_text("⚠️ You already linked this code.")
            else:
                await msg.reply_html(
                    "⚠️ <b>Code already linked by another account!</b>\n\n"
                    "This code was redeemed by an account within 24h.\n"
                    "You cannot use it.\n\n"
                    "Ask Account A to <b>delink</b> and generate a new code."
                )
            return

    # ── PERFORM THE LINK ─────────────────────────────────────────
    raw[code] = {
        "linked_uid": user.id,
        "linked_at": int(now),
        "expires_at": int(now) + 86400,
    }
    await asyncio.to_thread(_ss, "linked_backup_codes", raw)

    # Set on Account B (redeemer)
    await asyncio.to_thread(update_user_atomic, str(user.id), set_fields={
        "backup_linked_code": code,
        "backup_linked_at": int(now),
        "backup_linked_by": first_uid or 0,
        "backup_block_until": 0,   # B starts FREE
        "backup_last_used_at": 0,
    })

    # Block Account A only (B is free, only A blocked)
    if first_uid:
        await asyncio.to_thread(update_user_atomic, str(first_uid), set_fields={
            "backup_block_until": int(now) + 86400,
        })

    h, m = 24, 0
    await msg.reply_html(
        f"✅ <b>Code Redeemed Successfully!</b>\n\n"
        f"🔗 Code: <code>{code}</code>\n"
        f"👤 Linked to your account: <code>{user.id}</code>\n\n"
        f"⛔ <b>Account A is BLOCKED for 24h</b>\n"
        f"⏰ Account A blocked for: <b>{h}h {m}m</b>\n\n"
        "✅ You (Account B) are <b>FREE to use</b> the bot.\n\n"
        "⚠️ <b>Ping-Pong Rule:</b>\n"
        "• If YOU (Account B) use the bot → Account A blocked again 24h\n"
        "• Account A stays FREE while you're using (only one blocked at a time)\n"
        "• When neither uses for 24h → both free, export with <code>/mybackup {code}</code>"
    )


# ── /mybackup — export using linked code ──────────────────────────────────────
async def mybackup_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Export user data using linked backup code.
    Only works when block has expired (both accounts were free for 24h).
    """
    msg = update.effective_message
    if not msg:
        return

    uid = str(update.effective_user.id)
    now = int(time.time())

    if not context.args:
        await msg.reply_text(
            "⚠️ <code>/mybackup CODE</code>\n"
            "Use the linked code after /linkback.\n"
            "⚠️ Both accounts must be unblocked to export.",
            parse_mode="HTML"
        )
        return

    code = context.args[0].strip().upper()
    user_data = await asyncio.to_thread(get_user, uid)

    if not user_data:
        await msg.reply_text("⚠️ No account data found.")
        return

    # Check block status
    block_until = user_data.get("backup_block_until", 0)
    if block_until > now:
        h, m = divmod((block_until - now) // 60, 60)
        await msg.reply_html(
            f"⛔ <b>Cannot Export — Blocked!</b>\n\n"
            f"⏰ Wait: <b>{h}h {m}m</b>\n\n"
            "Reason: Your linked account used the bot recently.\n"
            "When block expires, you can export."
        )
        return

    # Verify linked code matches
    linked_code = user_data.get("backup_linked_code", "")
    if linked_code != code:
        await msg.reply_text(
            "⚠️ This code is not linked to your account.\n"
            "Use <code>/linkback CODE</code> first."
        )
        return

    # Check link expiry in global map
    raw = await asyncio.to_thread(_gs, "linked_backup_codes", {})
    link_data = raw.get(code, {})
    expires_at = link_data.get("expires_at", 0)
    if expires_at and now > expires_at:
        await msg.reply_text(
            "⚠️ Link expired. Use <code>/backupid</code> to generate a new code."
        )
        return

    # ── Export ─────────────────────────────────────────────────────
    payload = {
        "_id": uid,
        "exported_at": now,
        "linked_code": code,
        "exported_by": "linked_backup",
        **{k: v for k, v in user_data.items() if not k.startswith("_")},
    }
    json_bytes = json.dumps(payload, indent=2, ensure_ascii=False).encode("utf-8")

    import tempfile
    tmp_path = None
    try:
        def write_file(data: bytes) -> str:
            fd, tmp_path = tempfile.mkstemp(suffix=".json", prefix="anyy_backup_")
            os.write(fd, data)
            os.close(fd)
            return tmp_path
        loop = asyncio.get_running_loop()
        tmp_path = await loop.run_in_executor(None, lambda: write_file(json_bytes))
    except Exception:
        logger.warning("Exception in write_file")
        await msg.reply_text("⚠️ Failed to create backup file.")
        return

    try:
        with open(tmp_path, "rb") as f:
            await msg.reply_document(
                document=f,
                filename=f"anyy_backup_{uid}.json",
                caption=f"✅ <b>Backup Exported</b>\n"
                        f"🆔 User: <code>{uid}</code>\n"
                        f"🔗 Linked code: <code>{code}</code>",
                parse_mode="HTML",
            )
    except Exception:
        await msg.reply_text("⚠️ Failed to send backup file.")
    finally:
        try:
            os.unlink(tmp_path)
        except Exception:
            logger.error("Unexpected error", exc_info=True)


# ============================================================
# BACKUP LINK SYSTEM v2.0
# Simple 2-account linking with ping-pong block
#
# Flow:
# Account A → /backupid → Generate Code → share with B
# Account B → /linkback CODE → A blocked 24h (B is FREE)
# If B uses bot → A blocked 24h more (ping-pong, only ONE blocked)
# Neither uses 24h → both free → /mybackup CODE
# ============================================================

async def premiumlist_command(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Owner-only command to list all active premium users."""
    user = update.effective_user
    if user.id != OWNER_ID:
        await update.effective_message.reply_text("Owner only.")
        return
    msg = update.effective_message
    try:
        all_users = await asyncio.to_thread(list_all_users)
        now = int(time.time())
        premium_users = []
        for uid, data in all_users:
            prem_until = data.get("premium_until", 0)
            if prem_until > now:
                premium_users.append({
                    "id": uid,
                    "name": data.get("display_name") or data.get("first_name") or "Unknown",
                    "days": (prem_until - now) // 86400,
                })

        premium_users.sort(key=lambda x: x["days"], reverse=True)

        if not premium_users:
            return await msg.reply_html("💎 <b>Pʀᴇᴍɪᴜᴍ Usᴇʀs</b>\n\nNo active premium users.")

        text = f"💎 <b>Pʀᴇᴍɪᴜᴍ Usᴇʀs</b>\n👥 Total: <b>{len(premium_users)}</b>\n\n"
        for i, u in enumerate(premium_users[:50], 1):
            text += f"{i}. <code>{u['id']}</code> — {html.escape(str(u['name']))[:20]} (<b>{u['days']}d</b>)\n"
        if len(premium_users) > 50:
            text += f"\n... and {len(premium_users) - 50} more."
        await msg.reply_html(text)
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error: {html.escape(str(exc))}")

