# ═══ MODULE: game.optimize ═══

# =========================================
# ⚡ GAME OPTIMIZE — game/optimize.py
# Shared fast-path utilities for game commands.
# Eliminates per-command DB hits for gameoff/premium checks.
# =========================================
import asyncio
import time
import threading
from typing import Optional


logger = get_logger(__name__)


# ── Game-off cache ────────────────────────────────────────────────────────────
# gameoff_<chat_id> is checked on EVERY game command. Cache it for 30s.
_GAMEOFF_CACHE: dict[int, tuple[float, bool]] = {}
_GAMEOFF_TTL = 30.0
_GAMEOFF_MAX = 50_000
_gameoff_lock = threading.Lock()


def is_game_off_cached(chat_id: int) -> bool:
    """
    Returns True if games are disabled in this chat.
    Caches the result for 30s; falls back to DB on miss.
    Synchronous — wrap in asyncio.to_thread if needed.
    """
    now = time.time()
    cached = _GAMEOFF_CACHE.get(chat_id)
    if cached is not None:
        ts, val = cached
        if now - ts < _GAMEOFF_TTL:
            return val
    try:
        val = bool(get_setting(f"gameoff_{chat_id}", ""))
    except Exception:
        val = False
    with _gameoff_lock:
        if len(_GAMEOFF_CACHE) >= _GAMEOFF_MAX:
            sorted_keys = sorted(_GAMEOFF_CACHE, key=lambda k: _GAMEOFF_CACHE[k][0])
            for k in sorted_keys[:_GAMEOFF_MAX // 4]:
                _GAMEOFF_CACHE.pop(k, None)
        _GAMEOFF_CACHE[chat_id] = (now, val)
    return val


def invalidate_gameoff_cache(chat_id: int) -> None:
    """Call when /gameon or /gameoff is used, to refresh immediately."""
    _GAMEOFF_CACHE.pop(chat_id, None)


async def is_game_off_cached_async(chat_id: int) -> bool:
    """Async wrapper — runs DB lookup in thread only on cache miss."""
    now = time.time()
    cached = _GAMEOFF_CACHE.get(chat_id)
    if cached is not None and now - cached[0] < _GAMEOFF_TTL:
        return cached[1]
    # Cache miss — do the DB lookup in a thread
    return await asyncio.to_thread(is_game_off_cached, chat_id)


# ── Premium cache ─────────────────────────────────────────────────────────────
# premium.is_premium already has its own 5-min cache. We add a thin
# outer cache here so the very common case (premium check on every
# game command) doesn't even hit the function call + dict lookup
# inside premium.is_premium.
_PREMIUM_CACHE: dict[int, tuple[float, bool]] = {}
_PREMIUM_TTL = 300.0
_PREMIUM_MAX = 50_000
_premium_lock = threading.Lock()


def is_premium_cached(uid: int) -> bool:
    """
    Cached premium check (5 min TTL). Backed by premium.is_premium,
    which itself has a 5-min cache, so this is a 2-level cache.
    """
    now = time.time()
    cached = _PREMIUM_CACHE.get(uid)
    if cached is not None:
        ts, val = cached
        if now - ts < _PREMIUM_TTL:
            return val
    try:
        val = bool(is_premium(uid))
    except Exception:
        val = False
    with _premium_lock:
        if len(_PREMIUM_CACHE) >= _PREMIUM_MAX:
            sorted_keys = sorted(_PREMIUM_CACHE, key=lambda k: _PREMIUM_CACHE[k][0])
            for k in sorted_keys[:_PREMIUM_MAX // 4]:
                _PREMIUM_CACHE.pop(k, None)
        _PREMIUM_CACHE[uid] = (now, val)
    return val


def invalidate_premium_cache(uid: int) -> None:
    """Call when premium status changes (e.g. after /addpremium)."""
    _PREMIUM_CACHE.pop(uid, None)
    # Also invalidate the inner premium.is_premium cache
    try:
        _premium_cache.pop(uid, None)
    except Exception:
        pass


async def is_premium_cached_async(uid: int) -> bool:
    """Async wrapper — runs is_premium in a thread only on cache miss."""
    now = time.time()
    cached = _PREMIUM_CACHE.get(uid)
    if cached is not None and now - cached[0] < _PREMIUM_TTL:
        return cached[1]
    return await asyncio.to_thread(is_premium_cached, uid)


# ── Stats ─────────────────────────────────────────────────────────────────────
def optimize_stats() -> dict:
    return {
        "gameoff_cache_size": len(_GAMEOFF_CACHE),
        "premium_cache_size": len(_PREMIUM_CACHE),
    }

