# ============================================================================
# MESSAGE DEDUPLICATION
# ============================================================================

class MessageDeduplicator:
    """Prevent sending duplicate messages."""

    def __init__(self, ttl: int = 5):
        self._seen: Dict[str, float] = {}
        self._ttl = ttl
        self._lock = threading.Lock()

    def is_duplicate(self, message: str, user_id: int) -> bool:
        """Check if message is duplicate."""
        key = f"{user_id}:{message}"
        with self._lock:
            if key in self._seen:
                if time.time() - self._seen[key] < self._ttl:
                    return True
            self._seen[key] = time.time()
            return False


    def clear(self):
        """Clear deduplication cache."""
        with self._lock:
            self._seen.clear()


message_deduplicator = MessageDeduplicator(ttl=5)

# ============================================================================
# PERFORMANCE MONITORING
# ============================================================================

class PerformanceMonitor:
    """Track and log performance metrics."""

    def __init__(self):
        self._start_times = {}
        self._metrics = {}
        self._lock = threading.RLock()

    def start(self, operation: str):
        """Start timing an operation."""
        with self._lock:
            self._start_times[operation] = time.time()

    def end(self, operation: str):
        """End timing and record metric."""
        with self._lock:
            if operation in self._start_times:
                duration = time.time() - self._start_times[operation]
                if operation not in self._metrics:
                    self._metrics[operation] = []
                self._metrics[operation].append(duration)
                # Trim to last 1000 entries to prevent memory leak
                if len(self._metrics[operation]) > 1000:
                    self._metrics[operation] = self._metrics[operation][-1000:]
                del self._start_times[operation]

                # Log if slow
                if duration > 2.0:
                    logger.warning(f"[Perf] Slow operation: {operation} took {duration:.2f}s")

                return duration
            return None

    def get_avg(self, operation: str) -> float:
        """Get average duration for operation."""
        with self._lock:
            if operation in self._metrics:
                return sum(self._metrics[operation]) / len(self._metrics[operation])
            return 0.0
    
    def get_stats(self) -> Dict[str, Any]:
        """Get overall performance statistics."""
        with self._lock:
            stats = {}
            for op, durations in self._metrics.items():
                if durations:
                    stats[op] = {
                        "avg": sum(durations) / len(durations),
                        "min": min(durations),
                        "max": max(durations),
                        "count": len(durations),
                    }
            return stats

perf_monitor = PerformanceMonitor()

# ============================================================================
# COMMAND PRIORITY QUEUE - Process important commands first under load
# ============================================================================

class CommandPriorityQueue:
    """
    Priority queue for commands under heavy load.
    Ensures critical commands are processed first.
    """
    
    def __init__(self):
        self._high_priority = None
        self._normal_priority = None
        self._low_priority = None
        self._priority_map: Dict[str, int] = {
            # High priority - Economy (money involved)
            "capt": 0, "capture": 0, "cp": 0,
            "loot": 0,
            "send": 0, "transfer": 0,
            "paybounty": 0, "pb": 0,
            "shield": 0, "safe": 0, "save": 0,
            "dailygift": 0, "claim": 0, "giftdaily": 0,
            "redeem": 0,
            
            # Normal priority - Games
            "guessgame": 1, "leaveguessgame": 1,
            "xogame": 1,
            
            # Low priority - Fun
            "truth": 2, "dare": 2, "riddle": 2, "puzzle": 2,
            "looks": 2, "iq": 2, "stupidmeter": 2,
            "loveone": 2, "lovers": 2,
            "slap": 2, "slaps": 2, "smash": 2,
            "bites": 2, "kiss": 2,
            "translate": 2,
        }
        
    def _init_queues(self):
        if self._high_priority is None:
            self._high_priority = asyncio.Queue()
            self._normal_priority = asyncio.Queue()
            self._low_priority = asyncio.Queue()
    
    async def enqueue(self, command: str, handler, *args, **kwargs):
        """Add command to appropriate priority queue."""
        self._init_queues()
        priority = self._priority_map.get(command, 1)  # Default normal
        item = (handler, args, kwargs)
        
        if priority == 0:
            await self._high_priority.put(item)
        elif priority == 1:
            await self._normal_priority.put(item)
        else:
            await self._low_priority.put(item)
    
    async def dequeue(self) -> Optional[tuple]:
        """Get next command (high priority first)."""
        self._init_queues()
        try:
            # Try high priority first
            return self._high_priority.get_nowait()
        except asyncio.QueueEmpty:
            pass

        try:
            # Then normal priority
            return self._normal_priority.get_nowait()
        except asyncio.QueueEmpty:
            pass

        try:
            # Finally low priority
            return self._low_priority.get_nowait()
        except asyncio.QueueEmpty:
            return None

# Global command priority queue
command_priority_queue = CommandPriorityQueue()

# ============================================================================
# INITIALIZATION
# ============================================================================

async def init_performance_optimizations():
    """Initialize all performance optimizations."""
    global _cache_cleanup_task
    await batch_processor.start()
    
    async def cache_cleanup_loop():
        while True:
            try:
                await asyncio.sleep(300)  # Every 5 mins
                user_cache.cleanup_expired()
                chat_cache.cleanup_expired()
                ai_cache.cleanup_expired()
            except Exception:
                logger.error("[Perf] Cache cleanup error", exc_info=True)
                await asyncio.sleep(60)  # Back off on error
    
    _cache_cleanup_task = asyncio.create_task(cache_cleanup_loop(), name="cache-cleanup")
    
    logger.info("[Perf] Performance optimizations initialized")
    logger.info(f"[Perf] LRU Cache: {user_data_cache.stats()}")

async def shutdown_performance_optimizations():
    """Shutdown performance optimizations cleanly."""
    global _cache_cleanup_task
    await batch_processor.stop()
    if _cache_cleanup_task is not None and not _cache_cleanup_task.done():
        _cache_cleanup_task.cancel()
        try:
            await asyncio.wait_for(_cache_cleanup_task, timeout=3.0)
        except (asyncio.CancelledError, asyncio.TimeoutError):
            logger.warning("(CancelledError|TimeoutError) in shutdown_performance_optimizations", exc_info=True)
        except Exception:
            logger.warning("Exception in shutdown_performance_optimizations")
    logger.info("[Perf] Performance optimizations shutdown")

