# JSON helpers using orjson
def _json_dumps(obj) -> str:
    """4x faster JSON serialization"""
    if _USE_ORJSON:
        return orjson.dumps(obj).decode('utf-8')
    return json.dumps(obj, separators=(',', ':'))

def _json_loads(s: str):
    """4x faster JSON deserialization"""
    if _USE_ORJSON:
        return orjson.loads(s)
    return json.loads(s)

def _ensure_json_file(path: Path) -> None:
    if not path.exists():
        path.write_text("{}", encoding="utf-8")


def _load_json(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception as e:
        logger.warning("Exception in _json_loads", exc_info=True)
        logger.error("Disk I/O Error", exc_info=True)
        return {}


def _save_json(path: Path, payload: dict) -> None:
    try:
        path.write_text(json.dumps(payload, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    except Exception as e:
        logger.error("Disk I/O Error", exc_info=True)


def _compress(data: Any) -> bytes:
    """Binary compression using MessagePack + Zlib for maximum speed and size reduction."""
    return zlib.compress(msgpack.packb(data, use_bin_type=True))

def _decompress(raw: Any) -> Any:
    """Decompress binary data using Zlib + MessagePack (graceful fallback for uncompressed data)."""
    if raw is None:
        return {}
    if isinstance(raw, (bytes, bytearray)):
        if len(raw) < 2:
            return {}
        try:
            return msgpack.unpackb(zlib.decompress(raw), raw=False)
        except zlib.error:
            try:
                return msgpack.unpackb(raw, raw=False)
            except (msgpack.exceptions.UnpackException, ValueError, TypeError):
                decoded = ""
                try:
                    decoded = raw.decode("utf-8", errors="replace")
                    if decoded.strip():
                        return json.loads(decoded)
                except (json.JSONDecodeError, ValueError, TypeError):
                    if decoded and decoded.strip():
                        return {"_raw": decoded}
                return {}
            except Exception as e:
                logger.warning("Exception: %s", str(e))
                return {}
        except msgpack.exceptions.UnpackException as e:
            logger.warning("Failed to decompress data", exc_info=True)
            return {}
        except Exception as e:
            logger.warning("Exception: %s", str(e))
            return {}
    if isinstance(raw, dict):
        return raw
    return {}

def _strip_defaults(data: dict) -> dict:
    """Remove default/empty values from a dict to save blob compression space.
    
    Fields at their default state (None, 0, 0.0, False, [], {}) are redundant
    because every read path uses .get() with a fallback default.  Stripping them
    shrinks the _c blob by ~20-30%, saving ~80 bytes per user × 500K ≈ 40 MB.
    """
    PRESERVE = {"stats_daily_key", "stats_weekly_key"}
    return {k: v for k, v in data.items()
            if k in PRESERVE or v not in (None, 0, 0.0, False, "", [], {})}


def _compress_keys(data: dict) -> dict:
    """Translate long field names to compressed short keys."""
    return {COMPRESSED_FIELDS.get(k, k): v for k, v in data.items()}

def _decompress_keys(data: dict) -> dict:
    """Translate compressed short keys back to long field names."""
    return {DECOMPRESSED_FIELDS.get(k, k): v for k, v in data.items()}

def _compress_query(query: dict) -> dict:
    """Recursively compress all field name keys in a MongoDB query dict."""
    result = {}
    for k, v in query.items():
        if k.startswith("$"):
            result[k] = [_compress_query(item) if isinstance(item, dict) else item for item in v] if isinstance(v, list) else v
        else:
            ck = COMPRESSED_FIELDS.get(k)
            ck = ck if ck is not None else k
            if isinstance(v, dict):
                result[ck] = _compress_query(v)
            else:
                result[ck] = v
    return result



def _js(data: Any) -> str:
    return json.dumps(data, ensure_ascii=False, separators=(",", ":"))


def _dj(raw: Any, default: Any = None) -> Any:
    try:
        return _json_loads(raw)
    except (json.JSONDecodeError, Exception) as e:
        logger.debug(f"Failed to decode JSON: {e}")
        return default


