USER_CACHE_TTL = 300.0  # 5min for clean entries (was no TTL, now saves 70% TiDB reads)
USER_CACHE_DIRTY_TTL = 60.0  # 1min for dirty (needs flush)

class UserCache:
    """Unified Sharded User Cache with LRU, Dirty Tracking, and Timestamp-based write-back. Tiered: L1 5m, L2 relay 1h, L3 TiDB."""
    def __init__(self, max_size: int = 500000, shard_count: int = 256):
        self._shard_count = shard_count
        self._max_shard_size = max_size // shard_count
        self._caches = [{} for _ in range(shard_count)]
        self._dirty = [set() for _ in range(shard_count)]
        self._access_orders = [OrderedDict() for _ in range(shard_count)]
        self._locks = [threading.RLock() for _ in range(shard_count)]
        self._timestamps = [{} for _ in range(shard_count)]  # uid -> last_modified_ts
        self._last_flush_ts = 0.0  # global: timestamp of last successful flush
        self._warmup_done = False  # True after startup bulk load completes

    def _shard(self, uid: str) -> int:
        return hash(uid) % self._shard_count

    def get(self, uid: str) -> Optional[dict]:
        sid = self._shard(uid)
        cache = self._caches[sid]
        if uid in cache:
            ttl_map = getattr(self, "_ttl", None)
            if ttl_map is not None:
                exp = ttl_map[sid].get(uid)
                if exp is not None and time.time() > exp:
                    with self._locks[sid]:
                        del cache[uid]
                        self._access_orders[sid].pop(uid, None)
                        ttl_map[sid].pop(uid, None)
                    return None
            # Fast path: most callers read and don't mutate — return raw ref
            # Lock only for LRU bookkeeping
            with self._locks[sid]:
                self._touch(sid, uid)
            return cache[uid]
        return None

    def peek(self, uid: str) -> Optional[dict]:
        """
        Lock-free read that does NOT update LRU order. Use this in hot paths
        where you don't need the access to refresh the cache position
        (e.g., read-only checks like ban status, settings, balances).
        Returns the raw reference (no copy) — DO NOT mutate the result.
        """
        sid = self._shard(uid)
        cache = self._caches[sid]
        if uid in cache:
            ttl_map = getattr(self, "_ttl", None)
            if ttl_map is not None:
                exp = ttl_map[sid].get(uid)
                if exp is not None and time.time() > exp:
                    return None
            return cache[uid]
        return None

    def contains(self, uid: str) -> bool:
        """Fast O(1) check without copying the dict or updating LRU.
        Honours TTL: returns False for expired entries."""
        sid = self._shard(uid)
        if uid not in self._caches[sid]:
            return False
        ttl_map = getattr(self, "_ttl", None)
        if ttl_map is not None:
            exp = ttl_map[sid].get(uid)
            if exp is not None and time.time() > exp:
                return False
        return True

    def set(self, uid: str, data: dict, dirty: bool = True, ttl: Optional[float] = None):
        """
        Store data in the cache.

        Args:
            uid:    user/chat id (string)
            data:   payload (any picklable value, not just dicts)
            dirty:  mark as needing write-back. Ignored for non-dict values
                    (flags/bools) — they cannot be flushed to the user DB.
            ttl:    optional expiry in seconds. If set, the entry is
                    automatically removed on next read after expiry.
                    (Uses an auxiliary TTL set; cheap to check.)
        """
        sid = self._shard(uid)
        with self._locks[sid]:
            # Allow non-dict values for markers/flags
            try:
                payload = dict(data) if isinstance(data, dict) else data
            except Exception:
                payload = data
            self._caches[sid][uid] = payload
            self._touch(sid, uid)
            # Flags/bools/etc. have nothing to write back to the user DB —
            # silently drop the dirty marker so flush_cache never tries to
            # turn them into a MongoDB document.
            if dirty and isinstance(payload, dict):
                self._dirty[sid].add(uid)
                self._timestamps[sid][uid] = time.time()
            if ttl is not None and ttl > 0:
                # TTL tracking via a separate small dict per shard
                if not hasattr(self, "_ttl"):
                    self._ttl = [{} for _ in range(self._shard_count)]
                self._ttl[sid][uid] = time.time() + float(ttl)
            if len(self._caches[sid]) > self._max_shard_size:
                self._evict(sid)

    def _touch(self, sid: int, uid: str):
        self._access_orders[sid][uid] = None
        self._access_orders[sid].move_to_end(uid)

    def _evict(self, sid: int):
        for uid in list(self._access_orders[sid]):
            if uid not in self._dirty[sid]:
                del self._caches[sid][uid]
                del self._access_orders[sid][uid]
                self._timestamps[sid].pop(uid, None)
                return
        # All entries are dirty — force-evict LRU but try to save first
        if self._access_orders[sid]:
            uid, _ = next(iter(self._access_orders[sid]))
            data = self._caches[sid].get(uid)
            if data:
                try:
                    _relay_save_user(str(uid), _stamp_user_epoch(dict(data)))
                except Exception as exc:
                    logger.debug("Cache eviction relay save failed: %s", exc)
            del self._access_orders[sid][uid]
            self._caches[sid].pop(uid, None)
            self._dirty[sid].discard(uid)
            self._timestamps[sid].pop(uid, None)

    def get_dirty_batch(self, batch_size: int = 200) -> List[tuple[str, dict]]:
        """Get dirty entries (backward compatible)."""
        return self.get_dirty_batch_since(0, batch_size)

    def get_dirty_batch_since(self, since_ts: float, batch_size: int = 200) -> List[tuple[str, dict]]:
        """Get dirty entries modified after since_ts.

        Skips non-dict values (e.g. bool flags stored in main.py for
        permanent-ID tracking) — those don't need DB write-back.
        """
        batch = []
        for sid in range(self._shard_count):
            with self._locks[sid]:
                dirty_set = self._dirty[sid]
                to_remove = []
                for uid in list(dirty_set):
                    ts = self._timestamps[sid].get(uid, 0)
                    if ts <= since_ts:
                        continue  # skip entries not modified since last flush
                    if uid in self._caches[sid]:
                        payload = self._caches[sid][uid]
                        if not isinstance(payload, dict):
                            # Non-dict entry (e.g. flag/bool) — clear dirty,
                            # never flushed to DB.
                            to_remove.append(uid)
                            continue
                        batch.append((uid, dict(payload)))
                    else:
                        to_remove.append(uid)
                    if len(batch) >= batch_size:
                        break
                for uid in to_remove:
                    self._dirty[sid].discard(uid)
                    self._timestamps[sid].pop(uid, None)
                if len(batch) >= batch_size:
                    break
        return batch

    def mark_clean(self, uid: str):
        sid = self._shard(uid)
        with self._locks[sid]:
            self._dirty[sid].discard(uid)
            self._timestamps[sid].pop(uid, None)

    def mark_clean_if_unchanged(self, uid: str, expected: dict) -> bool:
        sid = self._shard(uid)
        with self._locks[sid]:
            current = self._caches[sid].get(uid)
            if current == expected:
                self._dirty[sid].discard(uid)
                self._timestamps[sid].pop(uid, None)
                return True
            return False

    def remove(self, uid: str):
        sid = self._shard(uid)
        with self._locks[sid]:
            self._caches[sid].pop(uid, None)
            self._dirty[sid].discard(uid)
            self._timestamps[sid].pop(uid, None)
            self._access_orders[sid].pop(uid, None)

    def __len__(self) -> int:
        return sum(len(c) for c in self._caches)

    def items(self) -> List[tuple[str, dict]]:
        all_items = []
        for sid in range(self._shard_count):
            with self._locks[sid]:
                shard_items = [(uid, dict(data)) for uid, data in self._caches[sid].items()]
                all_items.extend(shard_items)
        return all_items

    def clear(self):
        for sid in range(self._shard_count):
            with self._locks[sid]:
                self._caches[sid].clear()
                self._dirty[sid].clear()
                self._access_orders[sid].clear()
                self._timestamps[sid].clear()

USER_CACHE = UserCache()

# Fast "not found" cache: avoids repeated TiDB lookups for non-existent users.
# When get_user() returns empty, we cache that fact for 15 seconds.
# This saves ~3 RU per lookup for new/unknown users (common on /start).
_NF_CACHE: dict[str, float] = {}
_NF_CACHE_TTL = 15.0  # seconds
_NF_CACHE_LOCK = threading.RLock()

def _is_nf_cached(uid: str) -> bool:
    with _NF_CACHE_LOCK:
        exp = _NF_CACHE.get(uid, 0)
        if exp > time.time():
            return True
        _NF_CACHE.pop(uid, None)
        return False

def _mark_nf_cached(uid: str):
    with _NF_CACHE_LOCK:
        _NF_CACHE[uid] = time.time() + _NF_CACHE_TTL
        if len(_NF_CACHE) > 500000:
            cutoff = time.time()
            stale = [k for k, v in _NF_CACHE.items() if v <= cutoff]
            for k in stale:
                del _NF_CACHE[k]

def _clear_nf_cache(uid: str):
    with _NF_CACHE_LOCK:
        _NF_CACHE.pop(uid, None)

# ── Sharded Relay Lock Design ──────────────────────────────────────────────
# Using per-table locks instead of a single global lock eliminates
# contention between different table operations running concurrently.
# ── Per-table locks ────────────────────────────────────────────────────────
_RELAY_LOCKS: dict[str, threading.RLock] = {}
_RELAY_TABLES = ("users", "settings", "stickers", "runtime", "remote_artifacts")
for _t in _RELAY_TABLES:
    _RELAY_LOCKS[_t] = threading.RLock()
_RELAY_GLOBAL_LOCK = threading.RLock()  # only for init/schema migration

_relay = sqlite3.connect(RELAY_DB_FILE, check_same_thread=False)
_relay.execute("PRAGMA journal_mode=WAL")
_relay.execute("PRAGMA synchronous=NORMAL")
_relay.execute("PRAGMA temp_store=MEMORY")
_relay.execute("PRAGMA busy_timeout=5000")
_relay.execute("PRAGMA cache_size=-64000")  # 64MB cache
_relay.row_factory = sqlite3.Row


def _relay_table_lock(table: str) -> threading.RLock:
    return _RELAY_LOCKS.get(table, _RELAY_GLOBAL_LOCK)


def _relay_init() -> None:
    with _RELAY_GLOBAL_LOCK:
        _relay.executescript(
            """
            CREATE TABLE IF NOT EXISTS users (
                user_id TEXT PRIMARY KEY,
                payload BLOB NOT NULL,
                updated_at INTEGER NOT NULL DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_users_updated_at ON users(updated_at);
            CREATE TABLE IF NOT EXISTS settings (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                updated_at INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS stickers (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                updated_at INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS runtime (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                expires_at INTEGER NOT NULL DEFAULT 0,
                updated_at INTEGER NOT NULL DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_runtime_expires ON runtime(expires_at);
            CREATE TABLE IF NOT EXISTS remote_artifacts (
                artifact_type TEXT NOT NULL,
                message_id INTEGER NOT NULL,
                file_id TEXT NOT NULL DEFAULT '',
                chat_id INTEGER NOT NULL DEFAULT 0,
                label TEXT NOT NULL DEFAULT '',
                created_at INTEGER NOT NULL DEFAULT 0
            );
            """
        )
        _relay.commit()


def _relay_fetchone(query: str, params: tuple = (), table: str = "users") -> sqlite3.Row | None:
    with _relay_table_lock(table):
        return _relay.execute(query, params).fetchone()


def _relay_fetchall(query: str, params: tuple = (), table: str = "users") -> list[sqlite3.Row]:
    with _relay_table_lock(table):
        return list(_relay.execute(query, params).fetchall())


_relay_write_count = 0

def _relay_execute(query: str, params: tuple = (), table: str = "users") -> None:
    global _relay_write_count
    with _relay_table_lock(table):
        _relay.execute(query, params)
        _relay.commit()
        _relay_write_count += 1
        # Checkpoint WAL every 200 writes using PASSIVE (non-blocking)
        if _relay_write_count % 200 == 0:
            try:
                _relay.execute("PRAGMA wal_checkpoint(PASSIVE)")
            except Exception as exc:
                logger.debug(f"WAL checkpoint failed: {exc!r}")



_last_relay_vacuum: float = 0.0

def _relay_compact() -> None:
    global _last_relay_vacuum
    # Use GLOBAL lock only — compact touches all tables
    with _RELAY_GLOBAL_LOCK:
        try:
            _relay.execute("PRAGMA wal_checkpoint(PASSIVE)")
        except Exception as e:
            logger.warning("Failed to checkpoint WAL", exc_info=True)
        now = time.time()
        if now - _last_relay_vacuum > 86400:
            try:
                _relay.execute("PRAGMA analysis_limit=1000")
                _relay.execute("PRAGMA optimize")
            except Exception as e:
                logger.warning("Failed to optimize relay database", exc_info=True)
        _relay.commit()


def _relay_count(table: str) -> int:
    table = _relay_validate_table(table)
    row = _relay_fetchone(f"SELECT COUNT(*) AS count FROM {table}", table=table)
    return int(row["count"] if row else 0)


def _relay_get_user(uid: str) -> dict:
    row = _relay_fetchone("SELECT payload FROM users WHERE user_id = ?", (uid,), table="users")
    if not row:
        return {}
    return _decompress(row["payload"]) or {}


def _relay_save_user(uid: str, data: dict) -> None:
    _relay_execute(
        "INSERT INTO users(user_id,payload,updated_at) VALUES(?,?,?) "
        "ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload, updated_at=excluded.updated_at",
        (uid, _compress(data), int(time.time())),
        table="users",
    )

def _relay_save_users_batch(users_data: list[tuple[str, dict]]) -> int:
    if not users_data:
        return 0
    lock = _relay_table_lock("users")
    with lock:
        now = int(time.time())
        _relay.execute("BEGIN TRANSACTION")
        try:
            for uid, data in users_data:
                _relay.execute(
                    "INSERT INTO users(user_id,payload,updated_at) VALUES(?,?,?) "
                    "ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload, updated_at=excluded.updated_at",
                    (uid, _compress(data), now),
                )
            _relay.commit()
            global _relay_write_count
            _relay_write_count += 1
        except Exception:
            _relay.rollback()
            raise
    return len(users_data)


def _relay_iter_users(limit: int | None = None) -> list[tuple[str, dict]]:
    if limit and limit > 0:
        rows = _relay_fetchall(
            "SELECT user_id, payload FROM users ORDER BY updated_at ASC LIMIT ?",
            (int(limit),),
            table="users",
        )
    else:
        rows = _relay_fetchall("SELECT user_id, payload FROM users", table="users")
    items: list[tuple[str, dict]] = []
    for row in rows:
        items.append((str(row["user_id"]), _decompress(row["payload"]) or {}))
    return items


def _relay_delete_users(uids: list[str]) -> int:
    if not uids:
        return 0
    lock = _relay_table_lock("users")
    with lock:
        cur = _relay.executemany(
            "DELETE FROM users WHERE user_id = ?",
            [(str(uid),) for uid in uids],
        )
        _relay.commit()
        return int(cur.rowcount or 0)


_RELAY_ALLOWED_TABLES = frozenset({"users", "settings", "stickers", "runtime", "remote_artifacts"})

def _relay_validate_table(table: str) -> str:
    if table not in _RELAY_ALLOWED_TABLES:
        raise ValueError(f"Unknown relay table: {table!r}")
    return table

def _relay_get_text(table: str, key: str) -> str | None:
    table = _relay_validate_table(table)
    row = _relay_fetchone(f"SELECT value FROM {table} WHERE key = ?", (key,), table=table)
    return None if not row else str(row["value"])


def _relay_save_text(table: str, key: str, value: str, expires_at: int = 0) -> None:
    table = _relay_validate_table(table)
    updated_at = int(time.time())
    if table == "runtime":
        _relay_execute(
            "INSERT INTO runtime(key,value,expires_at,updated_at) VALUES(?,?,?,?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value, expires_at=excluded.expires_at, updated_at=excluded.updated_at",
            (key, value, int(expires_at or 0), updated_at),
            table=table,
        )
    else:
        _relay_execute(
            f"INSERT INTO {table}(key,value,updated_at) VALUES(?,?,?) "
            f"ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at",
            (key, value, updated_at),
            table=table,
        )


def _relay_delete_key(table: str, key: str) -> None:
    table = _relay_validate_table(table)
    _relay_execute(f"DELETE FROM {table} WHERE key = ?", (key,), table=table)


_relay_init()


def _migrate_legacy_local_users() -> None:
    if not isinstance(LOCAL_DB, dict) or not LOCAL_DB:
        return
    migrated = 0
    for uid, payload in list(LOCAL_DB.items()):
        if not isinstance(payload, dict):
            continue
        if _relay_get_user(str(uid)):
            continue
        _relay_save_user(str(uid), payload)
        migrated += 1
    if migrated:
        try:
            Path(LOCAL_FILE).rename(DATA_DIR / f"local_backup.migrated.{int(time.time())}.json")
        except Exception:
            Path(LOCAL_FILE).unlink(missing_ok=True)
        LOCAL_DB.clear()
        _save_json(Path(LOCAL_FILE), {})


_migrate_legacy_local_users()


# ━━━ MongoDB socket recovery helper ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━



def _mongo_call(fn, *args, max_retries: int = 4, **kwargs):
    """
    Call a MongoDB function with auto-recovery from broken-pipe errors.
    fn() should be a zero-arg callable that performs the Mongo operation
    and returns its result (or raises).

    On AutoReconnect / NetworkTimeout / ConnectionFailure / BrokenPipe,
    sleeps with exponential backoff + jitter and retries up to max_retries
    times. After exhausting retries, re-raises the last error.
    """
    last_exc = None
    for attempt in range(max_retries + 1):
        try:
            return fn(*args, **kwargs)
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            last_exc = exc
            if attempt < max_retries:
                wait = (0.5 * (2 ** attempt)) + random.uniform(0, 0.25)
                logger.debug(
                    "[mongo] %s — retrying (%d/%d) in %.2fs",
                    type(exc).__name__, attempt + 1, max_retries, wait,
                )
                time.sleep(wait)
                continue
            raise
        except BrokenPipeError as exc:
            last_exc = exc
            if attempt < max_retries:
                wait = (0.5 * (2 ** attempt)) + random.uniform(0, 0.25)
                logger.debug(
                    "[mongo] BrokenPipe — retrying (%d/%d) in %.2fs",
                    attempt + 1, max_retries, wait,
                )
                time.sleep(wait)
                continue
            # Convert to AutoReconnect so callers can catch it
            raise AutoReconnect(str(exc)) from exc
    raise last_exc  # unreachable, but satisfies type checkers

_mongo_slots: list[dict] = []
_mongo_slots_lock = threading.RLock()
_storage_registry_fingerprint = ""

# Slot recovery: reconnect bad slots in background
_SLOT_RECOVERY_INTERVAL = 20  # seconds (was 60, reduced for faster recovery on M0 free tier)
_slot_recovery_running = False
_slot_recovery_trigger = threading.Event()  # set to trigger immediate recovery

def _reconnect_slot(slot: dict) -> bool:
    """Try to reconnect a single bad MongoDB slot in-place."""
    uri = slot.get("uri", "")
    if not uri:
        return False
    db_name = slot.get("db_name", MONGO_DB_NAME)
    try:
        client = MongoClient(
            uri,
            maxPoolSize=50,
            minPoolSize=2,
            maxIdleTimeMS=10000,
            serverSelectionTimeoutMS=20000,
            connectTimeoutMS=15000,
            socketTimeoutMS=45000,
            heartbeatFrequencyMS=15000,
            retryWrites=True,
            retryReads=True,
            w=1,
            wtimeoutMS=5000,
            waitQueueTimeoutMS=5000,
            appname="anyybot",
        )
        client.server_info()
        db = client[db_name]
        old_client = slot.get("client")
        slot["client"] = client
        slot["db"] = db
        slot["users"] = db["users"]
        slot["settings"] = db["bot_settings"]
        slot["stickers"] = db["bot_stickers"]
        slot["runtime"] = db["runtime_state"]
        slot["recovery_map"] = db["recovery_map"]
        slot["ok"] = True
        slot["error"] = ""
        _ensure_mongo_indexes(slot)
        if old_client:
            threading.Thread(
                target=lambda c=old_client: (time.sleep(3), c.close() if hasattr(c, 'close') else None),
                daemon=True,
            ).start()
        logger.info(f"Slot {slot['slot_id']} reconnected after recovery")
        return True
    except Exception as exc:
        slot["error"] = str(exc)
        return False

def _mark_slot_failed(slot: dict, error: str = "") -> None:
    """Mark a MongoDB slot as failed and trigger immediate recovery."""
    slot["ok"] = False
    if error:
        slot["error"] = error
    _slot_recovery_trigger.set()


def _slot_recovery_loop():
    """Background thread: periodically reconnect bad slots.
    Can be triggered immediately via _slot_recovery_trigger.set()."""
    global _slot_recovery_running
    _slot_recovery_running = True
    while True:
        try:
            triggered = _slot_recovery_trigger.wait(timeout=_SLOT_RECOVERY_INTERVAL)
            if triggered:
                _slot_recovery_trigger.clear()
        except Exception:
            time.sleep(5)
        try:
            snapshot = list(_mongo_slots)
            bad = [s for s in snapshot if not s.get("ok") and s.get("uri")]
            if not bad:
                continue
            recovered = 0
            for slot in bad:
                if _reconnect_slot(slot):
                    recovered += 1
            if recovered:
                _sync_compat_handles()
                _sync_storage_registry(force=True)
                logger.info(f"Slot recovery: {recovered}/{len(bad)} slots reconnected")
        except Exception as e:
            logger.debug("Slot recovery error: %s", e)

users_collection = None
settings_col = None
sticker_col = None
runtime_col = None
recovery_map_col = None


def _load_extra_slots(key: str) -> list[dict]:
    if not MONGO_ENABLED:
        return []
    raw = LOCAL_SETTINGS.get(key, "")
    if not raw:
        return []
    data = _dj(raw, [])
    return data if isinstance(data, list) else []


def _persist_extra_slots(key: str, payload: list[dict]) -> None:
    LOCAL_SETTINGS[key] = _js(payload)
    _save_json(Path(LOCAL_SETTINGS_FILE), LOCAL_SETTINGS)


def _slot_meta_for(slot_id: int) -> dict:
    meta = DEFAULT_MONGO_SLOT_META.get(int(slot_id), {})
    _first_local = bool(MONGO_URI_SLOTS and ("localhost" in MONGO_URI_SLOTS[0] or "127.0.0.1" in MONGO_URI_SLOTS[0]))
    if _first_local:
        if slot_id == 1:
            return {"category": "local", "project_name": "local"}
        if 2 <= slot_id <= 6:
            return {"category": "hot", "project_name": f"shard{slot_id - 1}"}
        if slot_id >= 7:
            return {"category": "state", "project_name": f"state{slot_id - 6}"}
    return {
        "category": str(meta.get("category") or "general").strip().lower(),
        "project_name": str(meta.get("project_name") or f"p{slot_id}").strip(),
    }


def _mongo_slot_payloads() -> list[dict]:
    if not MONGO_ENABLED:
        return []
    payloads: list[dict] = []
    for idx, uri in enumerate(MONGO_URI_SLOTS, 1):
        meta = _slot_meta_for(idx)
        payloads.append(
            {
                "slot_id": idx,
                "uri": uri,
                "db_name": MONGO_DB_NAME,
                "limit_mb": int(MONGO_LIMIT_SLOTS[idx - 1]) if idx - 1 < len(MONGO_LIMIT_SLOTS) else 512,
                "category": meta["category"],
                "project_name": meta["project_name"],
                "write_enabled": True,
                "source": "config",
            }
        )
    extra = _load_extra_slots(MONGO_SLOT_SETTINGS_KEY)
    next_slot_id = len(payloads) + 1
    for item in extra:
        if not isinstance(item, dict) or not item.get("uri"):
            continue
        payloads.append(
            {
                "slot_id": next_slot_id,
                "uri": str(item.get("uri")).strip(),
                "db_name": str(item.get("db_name") or MONGO_DB_NAME).strip(),
                "limit_mb": int(item.get("limit_mb") or 512),
                "category": str(item.get("category") or "general").strip().lower() or "general",
                "project_name": str(item.get("project_name") or f"p{next_slot_id}").strip() or f"p{next_slot_id}",
                "write_enabled": bool(item.get("write_enabled", True)),
                "source": "owner",
            }
        )
        next_slot_id += 1
    return payloads


def _ensure_mongo_indexes(slot: dict) -> None:
    def _drop_extra_indexes(collection, keep: set[str]) -> None:
        try:
            info = collection.index_information()
        except Exception as e:
            logger.warning("Exception in _ensure_mongo_indexes", exc_info=True)
            logger.debug(f"Failed to get index information: {e}")
            return
        for name in list(info):
            if name in keep or name == "_id_":
                continue
            try:
                collection.drop_index(name)
            except Exception as e:
                logger.warning("Failed to drop index %s", name, exc_info=True)

    try:
        # Free Mongo tiers are tiny, so we keep only the default _id index
        # for user/settings/sticker collections and a TTL index for runtime.
        _drop_extra_indexes(slot["users"], set())
        _drop_extra_indexes(slot["settings"], set())
        _drop_extra_indexes(slot["stickers"], set())
        _drop_extra_indexes(slot["runtime"], {"expires_at_ttl"})
        slot["runtime"].create_index("expires_at", expireAfterSeconds=0, name="expires_at_ttl")
    except Exception as e:
        logger.exception(f"Failed to ensure MongoDB indexes: {e}")


def _db_storage_size_bytes(db) -> int:
    try:
        stats = db.command("dbstats")
        return int(stats.get("storageSize", 0) or stats.get("dataSize", 0) or 0)
    except Exception as e:
        logger.debug("Exception in _db_storage_size_bytes: %s", e)
        return 0


def _is_storage_full_error(exc: Exception) -> bool:
    text = str(exc).lower()
    return any(token in text for token in ("quota", "full", "limit", "storage", "too large", "exceeded"))


def _record_storage_alert(kind: str, message: str, slot_id: int | None = None) -> None:
    alerts = get_setting_json(STORAGE_ALERTS_KEY, []) or []
    if not isinstance(alerts, list):
        alerts = []
    entry = {
        "kind": kind,
        "slot_id": slot_id or 0,
        "message": message,
        "created_at": int(time.time()),
    }
    alerts = [item for item in alerts if not (item.get("kind") == kind and item.get("slot_id") == entry["slot_id"])]
    alerts.append(entry)
    save_setting_json(STORAGE_ALERTS_KEY, alerts[-20:])


def _connect_mongo_slots() -> list[dict]:
    slots: list[dict] = []
    if not MONGO_ENABLED or MongoClient is None:
        return slots
    for item in _mongo_slot_payloads():
        slot = {
            **item,
            "ok": False,
            "full": False,
            "usage_bytes": 0,
            "usage_percent": 0,
            "error": "",
            "client": None,
            "db": None,
            "users": None,
            "settings": None,
            "stickers": None,
            "runtime": None,
        }
        try:
            client = MongoClient(
                item["uri"],
                maxPoolSize=50,
                minPoolSize=2,
                maxIdleTimeMS=10000,
                serverSelectionTimeoutMS=20000,
                connectTimeoutMS=15000,
                socketTimeoutMS=45000,
                heartbeatFrequencyMS=15000,
                retryWrites=True,
                retryReads=True,
                w=1,
                wtimeoutMS=5000,
                waitQueueTimeoutMS=5000,
                appname="anyybot",
            )
            client.server_info()
            db = client[item["db_name"]]
            slot.update(
                {
                    "client": client,
                    "db": db,
                    "users": db["users"],
                    "settings": db["bot_settings"],
                    "stickers": db["bot_stickers"],
                    "runtime": db["runtime_state"],
                    "recovery_map": db["recovery_map"],
                    "ok": True,
                }
            )
            _ensure_mongo_indexes(slot)
            slot["usage_bytes"] = _db_storage_size_bytes(db)
            limit_bytes = max(1, int(slot["limit_mb"]) * 1024 * 1024)
            slot["usage_percent"] = int((slot["usage_bytes"] / limit_bytes) * 100)
            slot["full"] = slot["usage_percent"] >= 99
            if slot["usage_percent"] >= DB_WARN_PERCENT:
                _record_storage_alert(
                    "mongo-near-limit",
                    f"Mongo slot {slot['slot_id']} is at {slot['usage_percent']}% usage.",
                    slot["slot_id"],
                )
            logger.debug(f"✅ Mongo slot {slot['slot_id']} connected")
        except Exception as exc:
            slot["error"] = str(exc)
            # Silently skip failed slots - don't spam console
            logger.debug(f"Mongo slot {slot['slot_id']} skipped (network unreachable)")
        slots.append(slot)
    return slots


def _sync_compat_handles() -> None:
    global users_collection, settings_col, sticker_col, runtime_col, recovery_map_col
    primary_user_slot = _first_writable_mongo_slot("users")
    primary_settings_slot = _first_writable_mongo_slot("settings")
    if primary_settings_slot is None:
        primary_settings_slot = primary_user_slot
    primary_runtime_slot = _first_writable_mongo_slot("runtime")
    if primary_runtime_slot is None:
        primary_runtime_slot = primary_settings_slot
    users_collection = primary_user_slot["users"] if primary_user_slot else None
    settings_col = primary_settings_slot["settings"] if primary_settings_slot else None
    sticker_col = primary_settings_slot["stickers"] if primary_settings_slot else None
    runtime_col = primary_runtime_slot["runtime"] if primary_runtime_slot else None
    recovery_map_col = primary_settings_slot["recovery_map"] if primary_settings_slot else None


def refresh_storage_slots() -> None:
    global _mongo_slots
    new_slots = _connect_mongo_slots()
    for slot in _mongo_slots:
        try:
            if slot.get("client"):
                slot["client"].close()
        except Exception:
            logger.debug("Error closing Mongo client")
    with _mongo_slots_lock:
        _mongo_slots[:] = new_slots
    _sync_compat_handles()
    _sync_storage_registry(force=True)


def add_mongo_slot(
    uri: str,
    db_name: str | None = None,
    limit_mb: int | None = None,
    category: str | None = None,
    project_name: str | None = None,
    write_enabled: bool = True,
) -> dict:
    payload = _load_extra_slots(MONGO_SLOT_SETTINGS_KEY)
    entry = {
        "uri": str(uri).strip(),
        "db_name": str(db_name or MONGO_DB_NAME).strip(),
        "limit_mb": int(limit_mb or 512),
        "category": str(category or "general").strip().lower() or "general",
        "project_name": str(project_name or f"p{len(MONGO_URI_SLOTS) + len(payload) + 1}").strip(),
        "write_enabled": bool(write_enabled),
    }
    payload.append(entry)
    _persist_extra_slots(MONGO_SLOT_SETTINGS_KEY, payload)
    refresh_storage_slots()
    return entry


def _writable_mongo_slots_for_purpose(purpose: str = "users") -> list[dict]:
    order = MONGO_PURPOSE_ORDER.get(purpose, MONGO_PURPOSE_ORDER["users"])
    _is_local = bool(MONGO_URI_SLOTS and ("localhost" in MONGO_URI_SLOTS[0] or "127.0.0.1" in MONGO_URI_SLOTS[0]))
    if _is_local and "local" not in order:
        order = ("local",) + order
    ordered: list[dict] = []
    for category in order:
        ordered.extend(_category_slots_for_write(category))
    extras = [
        slot
        for slot in _mongo_slots
        if _slot_is_writable(slot) and _slot_category(slot) not in set(order)
    ]
    extras.sort(key=lambda item: int(item.get("slot_id", 0) or 0))
    ordered.extend(extras)
    return _dedupe_slots(ordered)


def _first_writable_mongo_slot(purpose: str = "users") -> dict | None:
    slots = _writable_mongo_slots_for_purpose(purpose)
    return slots[0] if slots else None


def _slot_category(slot: dict) -> str:
    return str(slot.get("category") or "general").strip().lower() or "general"


def _slot_is_writable(slot: dict) -> bool:
    usage = int(slot.get("usage_percent", 0) or 0)
    return (
        bool(slot.get("ok"))
        and not bool(slot.get("full"))
        and bool(slot.get("write_enabled", True))
        and usage < SAFE_WRITE_PERCENT
    )


def _category_slots_for_write(category: str) -> list[dict]:
    category = str(category or "general").strip().lower() or "general"
    slots = [slot for slot in _mongo_slots if _slot_is_writable(slot) and _slot_category(slot) == category]
    if not slots:
        return []
    safe = [slot for slot in slots if int(slot.get("usage_percent", 0) or 0) < SAFE_WRITE_PERCENT]
    owner_safe = [slot for slot in safe if str(slot.get("source", "")) == "owner"]
    owner_any = [slot for slot in slots if str(slot.get("source", "")) == "owner"]
    chosen = owner_safe or safe or owner_any or slots
    chosen.sort(key=lambda item: int(item.get("slot_id", 0) or 0))
    return chosen


def _dedupe_slots(slots: list[dict]) -> list[dict]:
    seen: set[int] = set()
    ordered: list[dict] = []
    for slot in slots:
        slot_id = int(slot.get("slot_id", 0) or 0)
        if not slot_id or slot_id in seen:
            continue
        seen.add(slot_id)
        ordered.append(slot)
    return ordered


def _slot_by_modulo(slots: list[dict], uid: str) -> dict | None:
    if not slots:
        return None
    try:
        uid_int = int(str(uid).split(":")[-1])
        return slots[uid_int % len(slots)]
    except (ValueError, ZeroDivisionError) as e:
        logger.debug(f"Failed to select slot by modulo: {e}")
        return slots[0] if slots else None
    except Exception as e:
        logger.warning("Exception in _slot_by_modulo", exc_info=True)
        logger.error("Unexpected error in slot selection", exc_info=True)
        return slots[0] if slots else None


def get_mongo_db() -> Any | None:
    """Get the primary MongoDB database object for sticker operations."""
    _ensure_storage_slots()
    slot = _first_writable_mongo_slot("stickers")
    if slot and slot.get("ok"):
        return slot.get("db")
    return None


def get_sticker_setting(key: str, default: Any = None) -> Any:
    """Read a sticker/gif setting. Routes: TiDB (when enabled) → Mongo → SQLite relay."""
    if _use_tidb_for("stickers"):
        v = tidb_get_sticker(key, None)
        if v is not None:
            return v
    _ensure_storage_slots()
    for slot in _writable_mongo_slots_for_purpose("stickers"):
        col = slot.get("stickers")
        if col is None:
            continue
        try:
            doc = col.find_one({"_id": key})
            if doc:
                return doc.get("value", default)
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
            logger.warning(f"get_sticker_setting slot {slot.get('slot_id', '?')} failed: {exc!r}")
    raw = _relay_get_text("stickers", key)
    if raw is not None:
        try:
            return json.loads(raw)
        except (json.JSONDecodeError, ValueError, TypeError):
            return default
    return default


def save_sticker_setting(key: str, value: Any) -> None:
    """Persist a sticker/gif setting. Routes: TiDB (when enabled) → Mongo → SQLite relay.
    Always writes to TiDB + relay for durability; Mongo is best-effort."""
    _ensure_storage_slots()
    encoded = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    # Always persist to TiDB (durable, survives HF restarts) when enabled
    if _use_tidb_for("stickers"):
        try:
            tidb_save_sticker(key, value)
        except Exception as exc:
            logger.warning(f"save_sticker_setting tidb failed: {exc!r}")
    # Always persist to relay store for restart safety (3 retries with backoff)
    for attempt in range(3):
        try:
            _relay_save_text("stickers", key, encoded)
            break
        except Exception as exc:
            if attempt < 2:
                time.sleep(0.5 * (2 ** attempt))
            logger.warning("save_sticker_setting relay attempt %d failed: %s", attempt + 1, exc)

    success = False
    for slot in _writable_mongo_slots_for_purpose("stickers"):
        col = slot.get("stickers")
        if col is None:
            continue
        try:
            col.update_one({"_id": key}, {"$set": {"value": value}}, upsert=True)
            success = True
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
            logger.warning(f"save_sticker_setting slot {slot.get('slot_id', '?')} failed: {exc!r}")

    if not success:
        logger.debug(f"save_sticker_setting {key} fell back to relay only")


def backfill_stickers_to_tidb() -> int:
    """One-time startup sync: copy any relay-stored sticker keys into TiDB so
    sticker packs/pools survive Space restarts even when Mongo is dead.
    Idempotent, best-effort, non-blocking. Returns number of keys synced."""
    if not _use_tidb_for("stickers"):
        return 0
    try:
        pool = get_pool()
        if not pool.slots or not any(s.ok for s in pool.slots):
            return 0
        rows = _relay_fetchall("SELECT key, value FROM stickers", table="stickers")
        if not rows:
            return 0
        synced = 0
        for row in rows:
            key = row["key"]
            raw = row["value"]
            if not key or not raw:
                continue
            try:
                existing = tidb_get_sticker(key, None)
                if existing is not None:
                    continue
            except Exception:
                pass
            try:
                tidb_save_sticker(key, raw)
                synced += 1
            except Exception as exc:
                logger.debug(f"backfill_stickers_to_tidb {key}: {exc!r}")
        if synced:
            logger.info(f"backfill_stickers_to_tidb: synced {synced} relay sticker keys → TiDB")
        return synced
    except Exception as exc:
        logger.debug(f"backfill_stickers_to_tidb failed: {exc!r}")
        return 0


_SETTING_JSON_PREFIX = "__json__:"


def _encode_setting_value(value: Any) -> str:
    if isinstance(value, str):
        return value
    return _SETTING_JSON_PREFIX + json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _decode_setting_value(value: Any, default: Any = None) -> Any:
    if value is None:
        return default
    if isinstance(value, str) and value.startswith(_SETTING_JSON_PREFIX):
        try:
            return json.loads(value[len(_SETTING_JSON_PREFIX):])
        except Exception:
            logger.warning("Exception in _decode_setting_value", exc_info=True)
            return default
    return value


def _writable_settings_slots() -> list[dict]:
    """Get all writable MongoDB slots for settings, ordered by priority."""
    return _writable_mongo_slots_for_purpose("settings")

# Negative setting cache: avoids SQLite relay reads for non-existent keys
_SETTING_NF_CACHE: dict[str, float] = {}
_SETTING_NF_TTL = 30.0  # 30 seconds

def _is_setting_nf_cached(key: str) -> bool:
    exp = _SETTING_NF_CACHE.get(key, 0)
    if exp > time.time():
        return True
    _SETTING_NF_CACHE.pop(key, None)
    return False

def _mark_setting_nf(key: str):
    _SETTING_NF_CACHE[key] = time.time() + _SETTING_NF_TTL
    if len(_SETTING_NF_CACHE) > 10000:
        cutoff = time.time()
        stale = [k for k, v in _SETTING_NF_CACHE.items() if v <= cutoff]
        for k in stale:
            del _SETTING_NF_CACHE[k]

def get_setting(key: str, default: Any = None) -> Any:
    if key in _SETTINGS_CACHE:
        return _SETTINGS_CACHE[key]
    if _is_setting_nf_cached(key):
        return default
    _ensure_storage_slots()
    for slot in _writable_settings_slots():
        col = slot.get("settings")
        if col is not None:
            try:
                doc = col.find_one({"_id": key})
                if doc:
                    val = doc.get("value", default)
                    _SETTINGS_CACHE[key] = val
                    return val
            except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
                logger.debug(f"get_setting transient error on slot {slot.get('slot_id')}: {exc}")
            except Exception as exc:
                _mark_slot_failed(slot, str(exc))

    raw = _relay_get_text("settings", key)
    result = _decode_setting_value(raw, default)
    if raw is None and result == default:
        _mark_setting_nf(key)
    _SETTINGS_CACHE[key] = result
    return result


def save_setting(key: str, value: Any) -> None:
    # OPTIMIZATION: skip DB write if the new value equals the cached value.
    # This is a HUGE win for hot settings like ai_global_personality,
    # guide_text, music_list etc. that get re-saved frequently.
    if key in _SETTINGS_CACHE:
        cached_val = _SETTINGS_CACHE.get(key)
        try:
            if _encode_setting_value(cached_val) == _encode_setting_value(value):
                return
        except Exception:
            pass

    _SETTINGS_CACHE.pop(key, None)
    _SETTING_NF_CACHE.pop(key, None)
    _ensure_storage_slots()
    # Always persist to relay store for restart safety
    for attempt in range(3):
        try:
            _relay_save_text("settings", key, _encode_setting_value(value))
            break
        except Exception as exc:
            if attempt < 2:
                time.sleep(0.5 * (2 ** attempt))
            logger.warning("save_setting relay attempt %d failed: %s", attempt + 1, exc)
    for slot in _writable_settings_slots():
        col = slot.get("settings")
        if col is None:
            continue
        try:
            col.update_one({"_id": key}, {"$set": {"value": value}}, upsert=True)
            _SETTINGS_CACHE[key] = value
            return
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))


def get_setting_json(key: str, default: Any = None) -> Any:
    value = get_setting(key, default)
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            logger.warning("Exception in get_setting_json", exc_info=True)
            return default
    return value


def save_setting_json(key: str, value: Any) -> None:
    save_setting(key, value)


def _writable_general_slots() -> list[dict]:
    """Get all writable MongoDB slots with 'general' category."""
    return [slot for slot in _mongo_slots if _slot_is_writable(slot) and _slot_category(slot) == "general"]

def register_chat(chat_id: int, chat_data: dict) -> None:
    if _use_tidb_for("chats"):
        tidb = _get_tidb()
        if tidb:
            try:
                tidb.tidb_register_chat(chat_id, chat_data)
                return
            except Exception as exc:
                logger.debug(f"TiDB register_chat failed: {exc}")
    for slot in _writable_general_slots():
        db = slot.get("db")
        if db is None:
            continue
        try:
            col = db.get_collection("chats")
            col.update_one({"_id": chat_id}, {"$set": chat_data}, upsert=True)
            return
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))


def get_registered_chats() -> list[dict]:
    seen = set()
    results = []
    if _use_tidb_for("chats"):
        tidb = _get_tidb()
        if tidb:
            try:
                for doc in tidb.tidb_get_registered_chats():
                    cid = doc.get("_id", doc.get("chat_id"))
                    if cid is not None and cid not in seen:
                        seen.add(cid)
                        results.append(doc)
                if results:
                    return results
            except Exception as exc:
                logger.debug(f"TiDB get_registered_chats failed: {exc}")
    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        db = slot.get("db")
        if db is None:
            continue
        try:
            col = db.get_collection("chats")
            for doc in col.find():
                cid = doc.get("_id")
                if cid not in seen:
                    seen.add(cid)
                    results.append(doc)
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    return results


def unregister_chat(chat_id: int) -> None:
    """Unregister a chat from the database."""
    if _use_tidb_for("chats"):
        tidb = _get_tidb()
        if tidb:
            try:
                tidb.tidb_unregister_chat(chat_id)
                return
            except Exception as exc:
                logger.debug(f"TiDB unregister_chat failed: {exc}")
    for slot in _writable_general_slots():
        db = slot.get("db")
        if db is None:
            continue
        try:
            col = db.get_collection("chats")
            col.delete_one({"_id": chat_id})
            return
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))


def is_load_balancing_enabled() -> bool:

    """Check if load balancing across hot slots is enabled."""
    return get_setting_json("mongo_load_balance", {"enabled": False}).get("enabled", False)


def set_load_balancing(enabled: bool) -> None:
    """Enable or disable load balancing across hot slots."""
    save_setting_json("mongo_load_balance", {"enabled": enabled})


def _user_is_inactive(data: dict | None, now_ts: float | None = None) -> bool:
    if not isinstance(data, dict) or not data:
        return False
    last_seen = _to_int(data.get("last_seen", 0), 0)
    if last_seen <= 0:
        return False
    current_ts = int(now_ts or time.time())
    return current_ts - last_seen >= ARCHIVE_AFTER_SECONDS


def _ordered_user_slots(uid: str, data: dict | None = None, *, write: bool = False) -> list[dict]:
    source = _writable_mongo_slots_for_purpose("users") if write else [slot for slot in _mongo_slots if slot.get("ok")]
    local = [slot for slot in source if _slot_category(slot) == "local"]
    hot = [slot for slot in source if _slot_category(slot) == "hot"]
    state = [slot for slot in source if _slot_category(slot) == "state"]
    archive = [slot for slot in source if _slot_category(slot) == "archive"]
    general = [slot for slot in source if _slot_category(slot) == "general"]
    others = [slot for slot in source if _slot_category(slot) not in {"local", "hot", "state", "archive", "general"}]

    # Always use modulo-based sharding to pick the correct hot shard
    primary_hot = _slot_by_modulo(hot, uid) if hot else None
    ordered: list[dict] = []
    # Local cache always first if available
    ordered.extend(local)
    if write and _user_is_inactive(data):
        ordered.extend(archive)
        if primary_hot:
            ordered.append(primary_hot)
        ordered.extend(slot for slot in hot if slot is not primary_hot)
        ordered.extend(general)
    else:
        if primary_hot:
            ordered.append(primary_hot)
        ordered.extend(slot for slot in hot if slot is not primary_hot)
        ordered.extend(state)
        ordered.extend(general)
        ordered.extend(archive)
    ordered.extend(others)
    return _dedupe_slots(ordered)


def _period_keys(ts: float | None = None) -> tuple[str, str]:
    now_dt = datetime.fromtimestamp(ts or time.time(), IST)
    day_key = now_dt.strftime("%Y-%m-%d")
    monday = (now_dt - timedelta(days=now_dt.weekday())).date().isoformat()
    return day_key, monday


def _refresh_period_stats(data: dict, ts: float | None = None) -> dict:
    day_key, week_key = _period_keys(ts)
    if data.get("stats_daily_key") != day_key:
        data["stats_daily_key"] = day_key
        data["daily_income"] = 0
        data["daily_captures"] = 0
        data["daily_redeem"] = 0
    if data.get("stats_weekly_key") != week_key:
        data["stats_weekly_key"] = week_key
        data["weekly_income"] = 0
        data["weekly_captures"] = 0
        data["weekly_redeem"] = 0
    for key in TRACKED_STATS:
        data.setdefault(key, 0)
        
    # FIX: Ensure level is synced with RP during any db read/atomic update
    if "rp" in data:
        try:
            lvl, _, _ = _get_level_progress(data["rp"])
            data["level"] = lvl
        except Exception as e:
            logger.debug(f"Failed to update level from RP: {e}")
            
    return data


def _fast_get_banned_users() -> list:
    """Get banned users using index (fast). Uses slot snapshot for thread safety.
    Queries both banned=True and silent_ban=True."""
    results = []
    for slot in list(_mongo_slots):
        if not slot.get("ok"):
            continue
        col = slot.get("users")
        if col is None:
            continue
        try:
            cursor = col.find(
                _compress_query({"$or": [{"banned": True}, {"silent_ban": True}]}),
                {"_id": 1}
            )
            for doc in cursor:
                results.append(str(doc.get("_id")))
        except Exception as e:
            logger.debug(f"Failed to get banned users from slot: {e}")
            _mark_slot_failed(slot, str(e))
    return results

def _to_int(value: Any, default: int = 0) -> int:
    try:
        return int(value) if value is not None else default
    except (ValueError, TypeError):
        return default
    except Exception as e:
        logger.warning("Exception in _to_int", exc_info=True)
        logger.debug(f"Error converting value to int: {e}")
        return default


_EPOCH_CACHE: tuple[int, float] = (0, 0.0)
_EPOCH_TTL = 300.0

def _current_data_epoch() -> int:
    global _EPOCH_CACHE
    now = time.time()
    val, ts = _EPOCH_CACHE
    if now - ts < _EPOCH_TTL and val > 0:
        return val
    raw_local = str(LOCAL_SETTINGS.get(DATA_EPOCH_KEY, "0") or "0")
    try:
        raw = get_setting(DATA_EPOCH_KEY, raw_local)
    except Exception as exc:
        logger.warning(f"DATA_EPOCH read failed, using local fallback: {exc!r}")
        raw = raw_local
    val = _to_int(raw, 0)
    _EPOCH_CACHE = (val, now)
    return val


def _stamp_user_epoch(data: dict) -> dict:
    payload = dict(data or {})
    payload["_data_epoch"] = _current_data_epoch()
    return payload


def _is_stale_user_payload(data: dict | None, current_epoch: int | None = None) -> bool:
    if not isinstance(data, dict) or not data:
        return False
    epoch = _current_data_epoch() if current_epoch is None else current_epoch
    if epoch <= 0:
        return False
    marked = _to_int(data.get("_data_epoch", 0), 0)
    if marked <= 0:
        # Unmarked payload (raw TiDB row, fresh cache entry) is current data
        return False
    return marked < epoch


def _cached_user(uid: str) -> dict:
    cached = USER_CACHE.get(uid)
    if _is_stale_user_payload(cached):
        USER_CACHE.remove(uid)
        return {}
    return dict(cached) if cached else {}


def _mongo_doc_to_user_data(doc: dict | None) -> dict:
    if not doc:
        return {}
    raw = dict(doc)
    raw.pop("_id", None)
    raw = _decompress_keys(raw)
    blob = raw.pop("_c", None)
    data = _decompress(blob) if blob else {}
    if not isinstance(data, dict):
        data = {}
    data.update(raw)
    return _refresh_period_stats(data)



def _flatten_user(data: dict) -> dict:
    # Only high-frequency / sortable / queryable fields are stored flat.
    # All other fields live exclusively in the _c blob (compressed).
    # This saves ~125 bytes per doc on M0 clusters (~60 MB across 500K users).
    flat = {
        # Economy (sorted in leaderboard)
        "balance": int(data.get("balance", 0) or 0),
        "total_redeem_earned": int(data.get("total_redeem_earned", 0) or 0),
        "captures": int(data.get("captures", 0) or 0),
        "rp": int(data.get("rp", 0) or 0),
        "level": int(data.get("level", 1) or 1),
        
        # Period stats (sorted in leaderboard)
        "daily_income": int(data.get("daily_income", 0) or 0),
        "weekly_income": int(data.get("weekly_income", 0) or 0),
        "daily_captures": int(data.get("daily_captures", 0) or 0),
        "weekly_captures": int(data.get("weekly_captures", 0) or 0),
        "daily_redeem": int(data.get("daily_redeem", 0) or 0),
        "weekly_redeem": int(data.get("weekly_redeem", 0) or 0),
        "lifetime_income": int(data.get("lifetime_income", 0) or 0),
        "stats_daily_key": str(data.get("stats_daily_key", "") or ""),
        "stats_weekly_key": str(data.get("stats_weekly_key", "") or ""),
        
        # Identity (leaderboard label)
        "username": data.get("username"),
        "first_name": data.get("first_name"),
        "last_name": data.get("last_name"),
        "display_name": data.get("display_name"),
        
        # Activity / lifecycle
        "last_seen": int(data.get("last_seen", 0) or 0),
        "updated_at": int(data.get("updated_at", 0) or 0),
        "_data_epoch": int(data.get("_data_epoch", 0) or 0),
        
        # Premium badge (leaderboard display)
        "premium_until": int(data.get("premium_until", 0) or 0),
        
        # Ban query
        "banned": bool(data.get("banned", False)),
        
        # Compressed blob (all other fields live here)
        "_c": _compress(_strip_defaults(data)),
    }
    return _compress_keys(flat)


def _probe_mongo_slots() -> None:
    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        try:
            slot["usage_bytes"] = _db_storage_size_bytes(slot["db"])
            limit_bytes = max(1, int(slot["limit_mb"]) * 1024 * 1024)
            slot["usage_percent"] = int((slot["usage_bytes"] / limit_bytes) * 100)
            slot["full"] = slot["usage_percent"] >= SAFE_WRITE_PERCENT
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    _sync_compat_handles()
    _sync_storage_registry()


def _storage_mode_from_slots() -> str:
    mongo_slot = _first_writable_mongo_slot("users")
    if mongo_slot:
        return f"mongo-slot-{mongo_slot['slot_id']}"
    return "host-relay"


def _storage_registry_snapshot() -> dict:
    _ensure_storage_slots()
    mongo_slots = [
        {
            "slot_id": slot["slot_id"],
            "ok": bool(slot.get("ok")),
            "full": bool(slot.get("full")),
            "usage_bytes": int(slot.get("usage_bytes", 0) or 0),
            "usage_percent": int(slot.get("usage_percent", 0) or 0),
            "source": slot.get("source", "config"),
            "db_name": slot.get("db_name", MONGO_DB_NAME),
            "category": slot.get("category", "general"),
            "project_name": slot.get("project_name", f"p{slot['slot_id']}"),
            "write_enabled": bool(slot.get("write_enabled", True)),
        }
        for slot in _mongo_slots
    ]
    active_by_category = {
        category: [int(slot.get("slot_id", 0) or 0) for slot in _category_slots_for_write(category)]
        for category in CATEGORY_PRIORITY_ORDER
        if _category_slots_for_write(category)
    }
    active_by_purpose = {
        purpose: (_first_writable_mongo_slot(purpose) or {}).get("slot_id", 0)
        for purpose in ("users", "settings", "stickers", "runtime")
    }
    return {
        "updated_at": int(time.time()),
        "mode": _storage_mode_from_slots(),
        "active_mongo_slot": int((_first_writable_mongo_slot("users") or {}).get("slot_id", 0) or 0),
        "active_by_purpose": active_by_purpose,
        "active_by_category": active_by_category,
        "available_mongo_slots": [slot["slot_id"] for slot in mongo_slots if slot["ok"]],
        "host_relay": {"enabled": True, "path": str(RELAY_DB_FILE), "users": _relay_count("users")},
        "mongo_slots": mongo_slots,
        "alerts": get_setting_json(STORAGE_ALERTS_KEY, []) or [],
    }


def _sync_storage_registry(force: bool = False) -> None:
    global _storage_registry_fingerprint
    snapshot = _storage_registry_snapshot()
    fingerprint = _js(snapshot)
    if not force and fingerprint == _storage_registry_fingerprint:
        return
    _storage_registry_fingerprint = fingerprint
    try:
        save_setting_json(STORAGE_REGISTRY_KEY, snapshot)
    except Exception:
        logger.exception("Failed to save storage registry snapshot")


def storage_mode() -> str:
    _probe_mongo_slots()
    return _storage_mode_from_slots()


def get_storage_status() -> dict:
    _probe_mongo_slots()
    return _storage_registry_snapshot()


def get_user(uid: Any) -> dict:
    _ensure_storage_slots()  # lazy init on first use
    uid = str(uid)
    current_epoch = _current_data_epoch()
    priority = _tidb_priority()
    cached = USER_CACHE.get(uid)
    if cached:
        if _is_stale_user_payload(cached, current_epoch):
            USER_CACHE.remove(uid)
            cached = None
        elif priority == "tidb_only" and _use_tidb_for("users"):
            # In tidb_only, TiDB is source of truth; cross-process stale cache
            # (e.g., 1044 vs TiDB 3449, or 200 vs 4506 after loot) would hide
            # the real balance. Fall through to TiDB and compare below.
            pass
        elif not _use_tidb_for("users"):
            # In relay mode (TiDB disabled), same cross-process staleness can happen
            # (e.g., loot worker sets 3669, pf worker still has 200). Check relay.
            try:
                _relay = _relay_get_user(uid)
                if _relay and not _is_stale_user_payload(_relay, current_epoch):
                    if int(_relay.get("updated_at", 0) or 0) > int(cached.get("updated_at", 0) or 0):
                        USER_CACHE.set(uid, _relay)
                        return dict(_relay)
            except Exception:
                pass
            return dict(cached)
        else:
            return dict(cached)
    
    # Fast "not found" short-circuit — skip TiDB/lookup if recently checked
    if _is_nf_cached(uid):
        if cached is not None:
            return dict(cached)
        return {}
    
    tidb_data = None
    if priority in ("tidb_first", "tidb_only") and _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                # Fast path: fetch flat columns first (no _c blob transfer/decompress)
                data = tidb.tidb_get_user_fast(uid)
                if data and not _is_stale_user_payload(data, current_epoch):
                    tidb_data = _refresh_period_stats(data)
                    if priority == "tidb_only":
                        # Need full dict — load blob and merge
                        blob = tidb.tidb_load_blob(uid)
                        if blob:
                            for k, v in blob.items():
                                if k not in tidb_data:
                                    tidb_data[k] = v
                        # Cross-process stale cache: prefer fresher updated_at
                        if cached is not None:
                            try:
                                c_ut = int(cached.get("updated_at", 0) or 0)
                                t_ut = int(tidb_data.get("updated_at", 0) or 0)
                                if c_ut > t_ut:
                                    return dict(cached)
                            except Exception:
                                pass
                        USER_CACHE.set(uid, tidb_data, ttl=USER_CACHE_TTL)
                        return dict(tidb_data)
                    if tidb_data and ("username" in tidb_data or "first_name" in tidb_data):
                        # Identity present — fill in blob for complete dict
                        blob = tidb.tidb_load_blob(uid)
                        if blob:
                            for k, v in blob.items():
                                if k not in tidb_data:
                                    tidb_data[k] = v
                        USER_CACHE.set(uid, tidb_data, ttl=USER_CACHE_TTL)
                        return dict(tidb_data)
            except Exception as exc:
                logger.debug(f"TiDB get_user failed for {uid}: {exc}")
                # Don't hard-fail in tidb_only on TiDB read error — fall through
                # to relay/Mongo so reads stay consistent with writes that landed
                # there (prevents loot/capture credits vanishing on TiDB blip).
                pass
    
    if priority == "tidb_only":
        relay_data = _relay_get_user(uid)
        if relay_data and not _is_stale_user_payload(relay_data, current_epoch):
            # Prefer fresher among relay and cached (if cached was skipped)
            if cached is not None:
                try:
                    c_ut = int(cached.get("updated_at", 0) or 0)
                    r_ut = int(relay_data.get("updated_at", 0) or 0)
                    if c_ut > r_ut:
                        return dict(cached)
                except Exception:
                    pass
            USER_CACHE.set(uid, relay_data, ttl=USER_CACHE_TTL)
            return dict(relay_data)
        if cached is not None:
            return dict(cached)
        # No TiDB/relay data — fall through to Mongo loop below instead of
        # returning {} (which would make ensure() treat existing users as new
        # and, before Fix A, reset them to $200).
    
    for slot in _ordered_user_slots(uid):
        try:
            doc = _mongo_call(slot["users"].find_one, {"_id": uid})
            if not doc:
                continue
            
            data = _mongo_doc_to_user_data(doc)
            if _is_stale_user_payload(data, current_epoch):
                continue
            # If TiDB had numeric data, merge it so we have the freshest numbers
            if tidb_data:
                for k in ("balance", "rp", "level", "captures", "daily_income",
                          "weekly_income", "lifetime_income", "premium_until",
                          "banned", "last_seen", "updated_at"):
                    if k in tidb_data:
                        data[k] = tidb_data[k]
            USER_CACHE.set(uid, data)
            return dict(data)
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            logger.debug(f"Mongo slot {slot.get('slot_id')} transient error in get_user: {exc}")
            continue
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    
    # No MongoDB data — return TiDB data as-is (even without identity)
    if tidb_data:
        # Fill in blob for complete dict
        tidb = _get_tidb()
        if tidb:
            try:
                blob = tidb.tidb_load_blob(uid)
                if blob:
                    for k, v in blob.items():
                        if k not in tidb_data:
                            tidb_data[k] = v
            except Exception:
                pass
        USER_CACHE.set(uid, tidb_data)
        return dict(tidb_data)
    
    relay_data = _relay_get_user(uid)
    if relay_data and not _is_stale_user_payload(relay_data, current_epoch):
        USER_CACHE.set(uid, relay_data)
        return dict(relay_data)
    # Final fallback: try TiDB fully (incl. blob)
    tidb = _get_tidb()
    if tidb:
        try:
            _check_tidb_available()
            data = tidb.tidb_get_user(uid)
            if data and not _is_stale_user_payload(data, current_epoch):
                data = _refresh_period_stats(data)
                USER_CACHE.set(uid, data)
                return dict(data)
        except Exception:
            pass
    _mark_nf_cached(uid)
    return {}



def _persist_user(uid: str, data: dict, _skip_tidb: bool = False) -> str:
    # Try TiDB first if enabled
    if not _skip_tidb and _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                tidb.tidb_save_user(uid, data)
                return "tidb"
            except Exception as exc:
                logger.debug(f"TiDB persist failed for {uid}: {exc}")
                if _tidb_priority() == "tidb_only":
                    _relay_save_user(uid, data)
                    return "host-relay"
    flat = _flatten_user(data)
    try:
        _relay_save_user(uid, data)
    except Exception as e:
        logger.warning("Exception: %s", str(e))
    for slot in _ordered_user_slots(uid, data, write=True):
        try:
            slot["users"].update_one({"_id": uid}, {"$set": flat}, upsert=True)
            if time.time() - slot.get("_last_probe", 0) > 60:
                slot["usage_bytes"] = _db_storage_size_bytes(slot["db"])
                slot["_last_probe"] = time.time()
                limit_bytes = max(1, int(slot["limit_mb"]) * 1024 * 1024)
                slot["usage_percent"] = int((slot["usage_bytes"] / limit_bytes) * 100)
            if slot["usage_percent"] >= DB_WARN_PERCENT:
                _record_storage_alert(
                    "mongo-near-limit",
                    f"Mongo slot {slot['slot_id']} is at {slot['usage_percent']}% usage.",
                    slot["slot_id"],
                )
            return f"mongo-slot-{slot['slot_id']}"
        except Exception as exc:
            slot["error"] = str(exc)
            slot["full"] = _is_storage_full_error(exc)
            if slot["full"]:
                _record_storage_alert("mongo-full", f"Mongo slot {slot['slot_id']} is full or quota-blocked.", slot["slot_id"])
            else:
                _mark_slot_failed(slot, str(exc))

    return "host-relay"


def save_user(uid: str, data: dict) -> dict:
    uid = str(uid)
    _clear_nf_cache(uid)
    data = _stamp_user_epoch(data)

    last_seen_val = data.get("last_seen")
    had_last_seen = "last_seen" in data
    if had_last_seen:
        del data["last_seen"]

    try:
        if _use_tidb_for("users"):
            tidb = _get_tidb()
            if tidb:
                try:
                    tidb.tidb_save_user(uid, data)
                    if had_last_seen:
                        data["last_seen"] = last_seen_val
                    USER_CACHE.set(uid, data)
                    return dict(data)
                except Exception as exc:
                    logger.debug(f"TiDB save_user failed for {uid}: {exc}")
    finally:
        if had_last_seen:
            data["last_seen"] = last_seen_val

    _persist_user(uid, data, _skip_tidb=True)
    USER_CACHE.set(uid, data)
    return dict(data)


def _persist_set_fields(uid: str, set_fields: dict) -> None:
    """Apply set_fields to MongoDB after TiDB atomic write, so identity
    fields (username, names, etc.) that TiDB strips still reach MongoDB."""
    if not set_fields or not _use_tidb_for("users"):
        return
    slots = _ordered_user_slots(uid, write=True)
    compressed = _compress_keys({k: v for k, v in set_fields.items() if v is not None})
    if not compressed:
        return
    for slot in slots:
        try:
            slot["users"].update_one({"_id": uid}, {"$set": compressed}, upsert=True)
            return
        except Exception:
            logger.warning("Exception in _persist_set_fields", exc_info=True)
            continue
    try:
        data = get_user(uid)
        data.update(set_fields)
        data["updated_at"] = int(time.time())
        _relay_save_user(uid, data)
    except Exception as e:
        logger.warning("Exception: %s", str(e))


def update_user_atomic(uid: str, inc_fields: dict = None, set_fields: dict = None) -> dict:
    """Atomically update a user. Routes: TiDB → MongoDB → SQLite relay. Batched stats save 80% RU."""
    uid = str(uid)
    _clear_nf_cache(uid)
    if inc_fields is None:
        inc_fields = {}
    # Cost optimization: batch non-critical daily/weekly stats (loot/capt) — immediate not needed
    # Critical: balance, rp, captures, level, banned, premium_until must be immediate
    if inc_fields:
        # Keep original for cache update if all batched
        _orig_inc = dict(inc_fields)
        inc_fields = buffer_stats_inc(uid, inc_fields)
        # If all were batched and no set_fields, just update cache and return (no DB hit, 0 RU)
        if not inc_fields and not set_fields:
            cached = USER_CACHE.get(uid)
            if cached is not None:
                for k, v in _orig_inc.items():
                    # Only batchable keys were buffered, already accounted in buffer_stats_inc
                    # But cache still needs the batchable increment for immediate read
                    if k in {"daily_income","weekly_income","lifetime_income","daily_captures","weekly_captures","daily_redeem","weekly_redeem"}:
                        cached[k] = int(cached.get(k,0) or 0) + int(v or 0)
                cached["updated_at"] = int(time.time())
                # Also update relay for durability
                try:
                    _relay_save_user(uid, cached)
                except Exception:
                    pass
                return dict(cached)
            # No cache, fallback to normal path (will create via relay)
    if set_fields is None:
        set_fields = {}
    if "balance" in inc_fields or "balance" in set_fields:
        invalidate_rank_cache(uid)

    # OPTIMIZATION: skip-if-no-change.
    # If all inc_fields are 0 AND all set_fields match the current cache,
    # there's no work to do — return the cached data immediately.
    if not inc_fields and set_fields:
        cached = USER_CACHE.peek(uid)
        if cached:
            all_match = True
            for k, v in set_fields.items():
                if cached.get(k) != v:
                    all_match = False
                    break
            if all_match:
                return dict(cached)

    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            # ── Coalesced path for increment-only calls ────────────────────────
            # When there are ONLY incremental changes (no set_fields like
            # banned/premium/shield), apply them to the local cache + relay
            # immediately and queue for a SINGLE batched TiDB write.
            # This is the "write direct 7 cache" path: Aman's 5+2 toffee
            # becomes one coalesced CASE UPDATE, saving ~80% RU on the
            # hot path (loot rewards, capture awards, bounty payouts).
            if inc_fields and not set_fields:
                # Load authoritative user from cache, relay, or light TiDB read.
                cached = _cached_user(uid)
                if not cached:
                    cached = _relay_get_user(uid) or {}
                if not cached:
                    cached = tidb.tidb_get_user_light(uid) or {}
                if cached:
                    merged = dict(cached)
                    for k, v in inc_fields.items():
                        merged[k] = int(merged.get(k, 0) or 0) + int(v or 0)
                    merged["updated_at"] = int(time.time())
                    merged["_data_epoch"] = _current_data_epoch()
                    merged = _refresh_period_stats(merged)
                    # dirty=False: the coalescing increment buffer is the sole
                    # writer here. If we also marked dirty=True, the cache-loop's
                    # full-row upsert would write the ABSOLUTE final balance AND
                    # the increment buffer would apply the DELTA net — a DOUBLE
                    # write. Keeping one writer (the net-delta buffer) is correct.
                    USER_CACHE.set(uid, merged, dirty=False)
                    try:
                        _relay_save_user(uid, merged)
                    except Exception:
                        pass
                    # Queue ALL inc_fields through the coalescing buffer
                    # (balance, rp, captures, level — all written in one flush).
                    try:
                        tidb.tidb_queue_increment(uid, inc_fields)
                    except Exception:
                        pass
                    return dict(merged)

            try:
                data = tidb.tidb_atomic_update(uid, inc_fields, set_fields)
                # Transient TiDB drop (shard blip / conn None) — retry once after recovery
                if not data:
                    try:
                        _pool = get_pool()
                        _pool.ensure_recovered()
                    except Exception:
                        pass
                    try:
                        data = tidb.tidb_atomic_update(uid, inc_fields, set_fields)
                    except Exception as exc2:
                        logger.warning("TiDB atomic update retry failed: %s", exc2)
                        data = {}
                if data:
                    data = _refresh_period_stats(data)
                    USER_CACHE.set(uid, data, dirty=True)
                    _persist_set_fields(uid, set_fields)
                    # Keep relay in sync so get_user fallback and leaderboard stay consistent
                    try:
                        _relay_save_user(uid, data)
                    except Exception:
                        pass
                    return dict(data)
                # TiDB write not confirmed — persist durably to cache + relay
                # so credits (loot/capture/send) are not lost when TiDB hiccups.
                # Previously only patched in-memory cache (and only in tidb_only
                # wrote relay), so the next tidb_only read returned stale TiDB.
                cached = USER_CACHE.get(uid)
                if cached is not None:
                    cached = dict(cached)
                    for k, v in inc_fields.items():
                        cached[k] = int(cached.get(k, 0) or 0) + int(v or 0)
                    cached.update(set_fields)
                    cached["updated_at"] = int(time.time())
                    cached = _refresh_period_stats(cached)
                    USER_CACHE.set(uid, cached, dirty=True)
                    try:
                        _relay_save_user(uid, cached)
                    except Exception:
                        pass
                    try:
                        _persist_set_fields(uid, set_fields)
                    except Exception:
                        pass
                    return dict(cached)
                if _tidb_priority() == "tidb_only":
                    lock = _relay_table_lock("users")
                    with lock:
                        data = get_user(uid)
                        if not data:
                            data = {
                                "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                                "level": 1, "daily_income": 0, "weekly_income": 0,
                                "daily_captures": 0, "weekly_captures": 0,
                                "daily_redeem": 0, "weekly_redeem": 0,
                                "lifetime_income": 0, "premium_until": 0,
                                "banned": 0, "total_redeem_earned": 0,
                                "captured": False, "captured_by": None, "capture_time": 0,
                                "bounty": 0, "bounty_paid": False, "bounty_dollar": 0, "bounty_rp": 0,
                                "last_seen": 0,
                            }
                        for k, v in inc_fields.items():
                            data[k] = int(data.get(k, 0) or 0) + int(v or 0)
                        data.update(set_fields)
                        data["updated_at"] = int(time.time())
                        data["_data_epoch"] = _current_data_epoch()
                        USER_CACHE.set(uid, data, dirty=True)
                        try:
                            _relay_save_user(uid, data)
                        except Exception:
                            pass
                        return dict(data)
            except Exception as exc:
                logger.warning("TiDB atomic update failed: %s", exc)

    slots = _ordered_user_slots(uid, write=True)
    if not slots:
        lock = _relay_table_lock("users")
        with lock:
            # Fast path: check cache first, then relay, avoid full get_user chain
            data = USER_CACHE.peek(uid)
            if not data:
                data = _relay_get_user(uid)
            if not data:
                data = {
                    "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                    "level": 1, "daily_income": 0, "weekly_income": 0,
                    "daily_captures": 0, "weekly_captures": 0,
                    "daily_redeem": 0, "weekly_redeem": 0,
                    "lifetime_income": 0, "premium_until": 0,
                    "banned": 0, "total_redeem_earned": 0,
                    "captured": False, "captured_by": None, "capture_time": 0,
                    "bounty": 0, "bounty_paid": False, "bounty_dollar": 0, "bounty_rp": 0,
                    "last_seen": 0,
                }
            for k, v in inc_fields.items():
                data[k] = int(data.get(k, 0) or 0) + int(v or 0)
            data.update(set_fields)
            data["updated_at"] = int(time.time())
            data["_data_epoch"] = _current_data_epoch()
            USER_CACHE.set(uid, data)
            _relay_save_user(uid, data)
            return dict(data)

    for slot in slots:
        try:
            doc = _mongo_call(slot["users"].find_one_and_update,
                {"_id": uid},
                {"$inc": _compress_keys(inc_fields), "$set": _compress_keys(set_fields)},
                return_document=ReturnDocument.AFTER
            )
            if doc:
                data = _mongo_doc_to_user_data(doc)
                data = _refresh_period_stats(data)
                USER_CACHE.set(uid, data, dirty=False)
                try:
                    _relay_save_user(uid, data)
                except Exception as e:
                    logger.warning("Exception: %s", str(e))
                return dict(data)
            continue
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            logger.debug(f"Mongo slot {slot.get('slot_id')} transient error in update_user_atomic: {exc}")
            continue
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
            continue

    lock = _relay_table_lock("users")
    with lock:
        data = USER_CACHE.peek(uid)
        if not data:
            data = _relay_get_user(uid)
        if not data and inc_fields:
            data = {
                "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                "level": 1, "daily_income": 0, "weekly_income": 0,
                "daily_captures": 0, "weekly_captures": 0,
                "daily_redeem": 0, "weekly_redeem": 0,
                "lifetime_income": 0, "premium_until": 0,
                "banned": 0, "total_redeem_earned": 0,
                "captured": False, "captured_by": None, "capture_time": 0,
                "bounty": 0, "bounty_paid": False, "bounty_dollar": 0, "bounty_rp": 0,
                "last_seen": 0,
            }
        for k, v in inc_fields.items():
            data[k] = int(data.get(k, 0) or 0) + int(v or 0)
        data.update(set_fields)
        data["updated_at"] = int(time.time())
        data["_data_epoch"] = _current_data_epoch()
        USER_CACHE.set(uid, data)
        _relay_save_user(uid, data)
        return dict(data)


def bulk_save_users(users_data: list[tuple[str, dict]]) -> int:
    """
    Save multiple users in bulk. Routes each user to their correct modulo shard.
    TiDB (primary) → MongoDB (fallback) → SQLite (final fallback).
    Returns count of successfully persisted users.
    """
    if not users_data:
        return 0

    # ── TiDB path (primary) ────────────────────────────────────────────────
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                saved = tidb.tidb_bulk_save(users_data)
                for uid, data in users_data:
                    data = _stamp_user_epoch(data)
                    USER_CACHE.set(uid, dict(data), dirty=False)
                return saved
            except Exception as exc:
                logger.debug(f"TiDB bulk_save failed: {exc}")
                if _tidb_priority() == "tidb_only":
                    return _relay_save_users_batch(users_data)

    # ── MongoDB path (fallback) ────────────────────────────────────────────
    hot_slots = [s for s in _writable_mongo_slots_for_purpose("users") if _slot_category(s) == "hot"]
    if not hot_slots:
        hot_slots = _writable_mongo_slots_for_purpose("users")
    if not hot_slots:
        return _relay_save_users_batch(users_data)

    by_slot: dict[int, list] = {}
    for uid, data in users_data:
        slot = _slot_by_modulo(hot_slots, str(uid))
        if slot is not None:
            by_slot.setdefault(int(slot["slot_id"]), []).append((uid, data))

    saved = 0
    for sid, slot_users in by_slot.items():
        slot = next((s for s in _mongo_slots if int(s.get("slot_id", 0)) == sid and s.get("ok")), None)
        if not slot:
            saved += _relay_save_users_batch(slot_users)
            continue
        try:
            operations = []
            for uid, data in slot_users:
                flat = _flatten_user(data)
                operations.append(UpdateOne({"_id": uid}, {"$set": flat}, upsert=True))
            if operations:
                slot["users"].bulk_write(operations, ordered=False)
            saved += len(slot_users)
        except Exception as e:
            logger.error("Bulk save failed on slot %d", sid, exc_info=True)
            saved += _relay_save_users_batch(slot_users)

    return saved


def set_recovery_id(backup_id: str, user_id: str) -> None:
    """Map a backup ID to a user ID in the recovery_map collection."""
    global recovery_map_col
    if recovery_map_col is None:
        return
    recovery_map_col.update_one(
        {"_id": backup_id},
        {"$set": {"user_id": user_id, "updated_at": int(time.time())}},
        upsert=True,
    )

def get_user_id_by_recovery_id(backup_id: str) -> str | None:
    """Retrieve the user ID associated with a backup ID."""
    global recovery_map_col
    if recovery_map_col is None:
        return None
    doc = recovery_map_col.find_one({"_id": backup_id})
    return doc.get("user_id") if doc else None

def delete_recovery_id(backup_id: str) -> None:
    """Remove a backup ID from the recovery_map collection."""
    global recovery_map_col
    if recovery_map_col is None:
        return
    recovery_map_col.delete_one({"_id": backup_id})

def try_deduct_balance(uid: Any, amount: int) -> bool:
    """Deduct balance only if sufficient. Returns True if successful."""
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        logger.warning("(TypeError|ValueError) in try_deduct_balance", exc_info=True)
        return False
    if amount < 0: return False
    if amount == 0: return True
    uid = str(uid)
    invalidate_rank_cache(uid)
    compressed_balance = COMPRESSED_FIELDS.get("balance", "balance")

    # Fast path: check cache first — avoids DB round-trip when cache says insufficient
    cached = USER_CACHE.peek(uid)
    if cached is not None and int(cached.get("balance", 0) or 0) < amount:
        return False

    # ── TiDB path (primary) ────────────────────────────────────────────────
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            # Coalescing write path: update the authoritative cache NOW (fast
            # reads see the new balance immediately) and queue the NET delta
            # for a single batched TiDB write. Rapid successive deductions
            # (Aman: 5 then 2 toffee) collapse into ONE write of the final
            # value instead of one write per transaction. The per-uid lock
            # serializes concurrent deductions so the fund-guard stays correct.
            bal_lock = _bal_user_lock(uid)
            with bal_lock:
                try:
                    cached = USER_CACHE.peek(uid)
                    if cached is not None:
                        if int(cached.get("balance", 0) or 0) < amount:
                            return False
                        cached["balance"] = max(0, int(cached.get("balance", 0) or 0) - amount)
                        cached["updated_at"] = int(time.time())
                        # dirty=False: the balance delta goes via the coalescing
                        # balance buffer (tidb_flush_balance writes the net CASE
                        # UPDATE). dirty=True here would trigger a full-row
                        # upsert of the ABSOLUTE final value, then the delta
                        # buffer applies the DELTA again — a double subtraction.
                        USER_CACHE.set(uid, cached, dirty=False)
                        tidb_queue_balance_delta(uid, -amount)
                        # Relay durability backs the 2s write-behind window.
                        try:
                            _relay_save_user(uid, _stamp_user_epoch(cached))
                        except Exception:
                            pass
                        return True
                    # No cache — need the authoritative balance to coalesce safely.
                    fresh = tidb.tidb_get_user_light(uid) or {}
                    if int(fresh.get("balance", 0) or 0) < amount:
                        return False
                    cached = dict(fresh)
                    cached["balance"] = max(0, int(cached.get("balance", 0) or 0) - amount)
                    cached["updated_at"] = int(time.time())
                    cached["_data_epoch"] = _current_data_epoch()
                    USER_CACHE.set(uid, cached, dirty=False)
                    tidb_queue_balance_delta(uid, -amount)
                    try:
                        _relay_save_user(uid, cached)
                    except Exception:
                        pass
                    return True
                except Exception as exc:
                    logger.debug(f"TiDB deduct coalesced failed for {uid}: {exc}")
                    # Fall through to the immediate atomic write below on error.
                    try:
                        ok = tidb.tidb_try_deduct_balance(uid, amount)
                        if ok:
                            cached = USER_CACHE.peek(uid)
                            if cached is not None:
                                cached["balance"] = max(0, int(cached.get("balance", 0) or 0) - amount)
                                cached["updated_at"] = int(time.time())
                                USER_CACHE.set(uid, cached)
                                return True
                            fresh = tidb.tidb_get_user_light(uid) or {}
                            cached = {"balance": int(fresh.get("balance", 0) or 0), "updated_at": int(time.time())}
                            USER_CACHE.set(uid, cached)
                            return True
                    except Exception as exc2:
                        logger.debug(f"TiDB deduct immediate fallback failed for {uid}: {exc2}")
                    return False

    slots = _ordered_user_slots(uid, write=True)
    if not slots:
        lock = _relay_table_lock("users")
        with lock:
            data = USER_CACHE.peek(uid)
            if not data:
                data = _relay_get_user(uid) or get_user(uid)
            if int(data.get("balance", 0) or 0) < amount:
                return False
            data["balance"] = int(data.get("balance", 0) or 0) - amount
            data["updated_at"] = int(time.time())
            USER_CACHE.set(uid, data)
            _relay_save_user(uid, data)
            return True

    for slot in slots:
        try:
            doc = _mongo_call(slot["users"].find_one_and_update,
                {"_id": uid, compressed_balance: {"$gte": amount}},
                {"$inc": {compressed_balance: -amount}, "$set": {"updated_at": int(time.time())}},
                return_document=ReturnDocument.AFTER
            )
            if doc:
                data = _mongo_doc_to_user_data(doc)
                USER_CACHE.set(uid, data)
                return True
            continue
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            logger.debug(f"Mongo slot {slot.get('slot_id')} transient error in try_deduct: {exc}")
            continue
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
            continue

    lock = _relay_table_lock("users")
    with lock:
        data = USER_CACHE.peek(uid)
        if not data:
            data = _relay_get_user(uid) or get_user(uid)
        if int(data.get("balance", 0) or 0) < amount:
            return False
        data["balance"] = int(data.get("balance", 0) or 0) - amount
        data["updated_at"] = int(time.time())
        USER_CACHE.set(uid, data)
        _relay_save_user(uid, data)
        return True


def _apply_update_to_local_user(
    uid: Any,
    inc_fields: dict | None = None,
    set_fields: dict | None = None,
    *,
    persist_relay: bool = False,
    dirty: bool = True,
) -> dict:
    uid = str(uid)
    data = _cached_user(uid) or _relay_get_user(uid) or {}
    # If empty and we have increments, try primary DB to avoid creating partial user
    if not data and inc_fields:
        data = get_user(uid) or {}
    # If still empty with increments, initialize with defaults to avoid data loss
    if not data and inc_fields:
        data = {
            "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
            "level": 1, "daily_income": 0, "weekly_income": 0,
            "daily_captures": 0, "weekly_captures": 0,
            "daily_redeem": 0, "weekly_redeem": 0,
            "lifetime_income": 0, "premium_until": 0,
            "banned": 0, "total_redeem_earned": 0,
            "captured": False, "captured_by": None, "capture_time": 0,
            "bounty": 0, "bounty_paid": False, "bounty_dollar": 0, "bounty_rp": 0,
            "last_seen": 0, "updated_at": int(time.time()),
        }
    if inc_fields:
        for key, value in inc_fields.items():
            data[key] = int(data.get(key, 0) or 0) + int(value or 0)
    if set_fields:
        data.update(set_fields)
    data["updated_at"] = int(time.time())
    data = _stamp_user_epoch(data)
    USER_CACHE.set(uid, data, dirty=dirty)
    if persist_relay:
        _relay_save_user(uid, data)
    return dict(data)


def bulk_update_users(updates: list[tuple[str, dict, dict]]):
    """
    Perform bulk atomic updates, correctly routing each update to the
    user's modulo shard.
    Updates: List of (uid, inc_fields, set_fields) tuples.
    TiDB (primary) → MongoDB (fallback) → per-user atomic (final fallback).
    """
    if not updates:
        return

    # ── TiDB path (primary) ────────────────────────────────────────────────
    # Optimized: queue all increments via the coalescing buffer, then apply
    # set_fields in batched UPDATEs. This is 10-100x faster than per-user
    # tidb_atomic_update when bulk-updating many users.
    tidb_success: set[str] = set()
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            # Group by (uid) and merge inc_fields
            merged_incs: dict[str, dict] = {}
            all_set_fields: dict[str, dict] = {}
            for uid, inc_fields, set_fields in updates:
                if inc_fields:
                    existing = merged_incs.setdefault(uid, {})
                    for k, v in inc_fields.items():
                        existing[k] = int(existing.get(k, 0) or 0) + int(v or 0)
                if set_fields:
                    s = all_set_fields.setdefault(uid, {})
                    s.update(set_fields)
            try:
                # Queue incs (will be flushed together via batched CASE UPDATE)
                for uid, incs in merged_incs.items():
                    tidb.tidb_queue_increment(uid, incs)
                # Apply set_fields via per-user tidb_atomic_update (no read-back needed for sets)
                for uid, sfields in all_set_fields.items():
                    try:
                        tidb.tidb_atomic_update(uid, {}, sfields)
                    except Exception as exc:
                        logger.debug(f"TiDB set_fields bulk failed for {uid}: {exc}")
                tidb_success = set(merged_incs.keys()) | set(all_set_fields.keys())
                # Apply merged changes to local cache so subsequent ensure() calls
                # see the new values immediately (otherwise /paybounty, /capture, etc.
                # would see stale captured=True after a successful release).
                for uid in tidb_success:
                    cached = USER_CACHE.get(uid)
                    if cached is None:
                        # Cache miss — initialize from defaults so the change is reflected
                        cached = {
                            "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                            "level": 1, "captured": False, "captured_by": None,
                            "capture_time": 0, "bounty_dollar": 0, "bounty_rp": 0,
                        }
                    uid_incs = merged_incs.get(uid, {})
                    uid_sets = all_set_fields.get(uid, {})
                    for k, v in uid_incs.items():
                        cached[k] = int(cached.get(k, 0) or 0) + int(v or 0)
                    if uid_sets:
                        cached.update(uid_sets)
                    cached["updated_at"] = int(time.time())
                    USER_CACHE.set(uid, cached, dirty=True)
            except Exception as exc:
                logger.debug(f"TiDB bulk path failed: {exc}")
            if _tidb_priority() == "tidb_only":
                for uid in (set(merged_incs.keys()) | set(all_set_fields.keys())) - tidb_success:
                    cached = USER_CACHE.get(uid) or {}
                    if not cached:
                        cached = {
                            "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                            "level": 1, "captured": False, "captured_by": None,
                            "capture_time": 0, "bounty_dollar": 0, "bounty_rp": 0,
                        }
                    uid_incs = merged_incs.get(uid, {})
                    uid_sets = all_set_fields.get(uid, {})
                    for k, v in uid_incs.items():
                        cached[k] = int(cached.get(k, 0) or 0) + int(v or 0)
                    if uid_sets:
                        cached.update(uid_sets)
                    cached["updated_at"] = int(time.time())
                    USER_CACHE.set(uid, cached, dirty=True)
                    _relay_save_user(uid, cached)
                return

    # ── MongoDB path (fallback) — skip users already handled by TiDB ────────
    pending = [(u, i, s) for u, i, s in updates if u not in tidb_success]
    if not pending:
        return

    if UpdateOne is None:
        for uid, inc, set_ in pending:
            update_user_atomic(uid, inc, set_)
        return

    all_slots = _writable_mongo_slots_for_purpose("users")
    hot_slots = [s for s in all_slots if _slot_category(s) == "hot"]
    if not hot_slots:
        hot_slots = all_slots
    if not hot_slots:
        for uid, inc, set_ in pending:
            update_user_atomic(uid, inc, set_)
        return

    by_slot: dict[int, list] = {}
    for uid, inc_fields, set_fields in pending:
        slot = _slot_by_modulo(hot_slots, str(uid))
        if slot is None:
            update_user_atomic(uid, inc_fields or {}, set_fields or {})
            continue
        sid = int(slot["slot_id"])
        by_slot.setdefault(sid, []).append((uid, inc_fields, set_fields))

    for sid, slot_updates in by_slot.items():
        slot = next((s for s in _mongo_slots if int(s.get("slot_id", 0)) == sid and s.get("ok")), None)
        if not slot:
            for uid, inc, set_ in slot_updates:
                update_user_atomic(uid, inc, set_)
            continue

        operations = []
        for uid, inc_fields, set_fields in slot_updates:
            op = {}
            if inc_fields:
                op["$inc"] = _compress_keys(inc_fields)
            if set_fields:
                op["$set"] = _compress_keys(set_fields)
            if not op:
                continue

            current_data = get_user(uid) or {}
            if not current_data:
                # Initialize with defaults to avoid stale _c blob
                current_data = {
                    "user_id": uid, "balance": 200, "captures": 0, "rp": 0,
                    "level": 1, "daily_income": 0, "weekly_income": 0,
                    "daily_captures": 0, "weekly_captures": 0,
                    "daily_redeem": 0, "weekly_redeem": 0,
                    "lifetime_income": 0, "premium_until": 0,
                    "banned": 0, "total_redeem_earned": 0,
                    "captured": False, "captured_by": None, "capture_time": 0,
                    "bounty": 0, "bounty_paid": False, "bounty_dollar": 0, "bounty_rp": 0,
                    "last_seen": 0,
                }
            merged = dict(current_data)
            for k, v in (inc_fields or {}).items():
                merged[k] = int(merged.get(k, 0) or 0) + int(v or 0)
            merged.update(set_fields or {})
            merged["updated_at"] = int(time.time())
            op.setdefault("$set", {})["_c"] = _compress(_strip_defaults(merged))

            operations.append(UpdateOne({"_id": str(uid)}, op, upsert=True))

        if not operations:
            continue

        try:
            slot["users"].bulk_write(operations, ordered=False)
            for uid, inc_fields, set_fields in slot_updates:
                _apply_update_to_local_user(uid, inc_fields, set_fields, dirty=False)
        except Exception as e:
            logger.error("Bulk update users failed on slot %d", sid, exc_info=True)
            for uid, inc, set_ in slot_updates:
                update_user_atomic(uid, inc, set_)




def flush_cache(batch_size: int = 1000, sync_relay: bool = True) -> int:
    """
    Flush dirty cached users to MongoDB in bulk.
    Uses timestamp-based filtering: only flushes entries modified since last flush.
    If Mongo is unavailable/full, persist dirty users to the local relay.
    Returns count of users flushed.
    """
    
    logger = get_logger(__name__)
    flushed_count = 0
    failed_count = 0

    try:
        _ensure_storage_slots()
        _probe_mongo_slots()
    except Exception as exc:
        logger.debug(f"Storage probe before cache flush failed: {exc}")

    # Only flush entries modified since last successful flush
    since_ts = USER_CACHE._last_flush_ts
    dirty_batch = USER_CACHE.get_dirty_batch_since(since_ts, max(1, int(batch_size or 1000)))
    if dirty_batch:
        saved = 0
        try:
            saved = bulk_save_users(dirty_batch)
        except Exception as e:
            logger.warning("Bulk cache flush failed, falling back to local relay", exc_info=True)
            saved = 0

        if saved >= len(dirty_batch):
            for uid, data in dirty_batch:
                USER_CACHE.mark_clean_if_unchanged(str(uid), data)
            flushed_count += len(dirty_batch)
        else:
            for uid, data in dirty_batch:
                try:
                    _relay_save_user(str(uid), _stamp_user_epoch(data))
                    USER_CACHE.mark_clean_if_unchanged(str(uid), data)
                    flushed_count += 1
                except Exception as e:
                    failed_count += 1
                    log_error(
                        e,
                        logger,
                        context={"operation": "flush_cache_local_relay", "user_id": uid},
                        user_id=int(uid) if str(uid).isdigit() else None,
                        silent=True,
                    )

    if sync_relay and _first_writable_mongo_slot("users"):
        relay_batch = _relay_iter_users(max(1, int(batch_size or 1000)))
        if relay_batch:
            try:
                saved = bulk_save_users(relay_batch)
                # Only delete relay users that were actually saved to MongoDB/relay
                # bulk_save_users returns count of all saved (including relay fallback)
                # So we can safely delete all since they're persisted somewhere
                if saved >= len(relay_batch):
                    _relay_delete_users([uid for uid, _ in relay_batch])
                    flushed_count += len(relay_batch)
            except Exception as e:
                failed_count += len(relay_batch)
                logger.debug(f"Relay-to-Mongo retry failed: {e}")

    # ── TiDB last_seen + increment buffers flush ────────────────────────────
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                ls_flushed = tidb.tidb_flush_last_seen()
                if ls_flushed:
                    flushed_count += ls_flushed
            except Exception as e:
                logger.debug(f"TiDB last_seen flush failed: {e}")
            # Flush remaining coalesced balance deltas (users that were NOT
            # full-row saved above; dirty users had their deltas consumed by
            # tidb_bulk_save so no double-write happens).
            try:
                bal_flushed = tidb.tidb_flush_balance(flush_all=False)
                if bal_flushed:
                    flushed_count += bal_flushed
            except Exception as e:
                logger.debug(f"TiDB balance flush failed: {e}")
            try:
                inc_flushed = tidb.tidb_flush_increments()
                if inc_flushed:
                    flushed_count += inc_flushed
            except Exception as e:
                logger.debug(f"TiDB increments flush failed: {e}")
            # Clean up any stale dirty marker (should be empty during normal op)
            try:
                tidb.tidb_flush_dirty(batch_size)
            except Exception as e:
                logger.warning("Exception: %s", str(e))

    if failed_count > 0:
        logger.warning(f"Flush cache: {flushed_count} saved, {failed_count} failed")
    else:
        # Only advance flush timestamp when all entries succeeded.
        # If any failed, keep the old timestamp so failed entries are retried on next cycle.
        USER_CACHE._last_flush_ts = time.time()

    return flushed_count


def list_all_users() -> list[tuple[str, dict]]:
    _ensure_storage_slots()
    current_epoch = _current_data_epoch()

    # ── TiDB path (primary) ────────────────────────────────────────────────
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                results = tidb.tidb_list_all_users()
                if results:
                    validated = []
                    for uid, data in results:
                        data = _refresh_period_stats(data)
                        if not _is_stale_user_payload(data, current_epoch):
                            validated.append((uid, data))
                    if validated or _tidb_priority() == "tidb_only":
                        return validated
            except Exception as exc:
                logger.debug(f"TiDB list_all_users failed: {exc}")
                if _tidb_priority() == "tidb_only":
                    return []

    # ── MongoDB path (fallback) ─────────────────────────────────────────────
    merged: "OrderedDict[str, dict]" = OrderedDict()

    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        try:
            missing_c: list[str] = []
            for doc in slot["users"].find({}, {"_c": 1}):
                uid = str(doc.get("_id"))
                if uid in merged:
                    continue
                data = _refresh_period_stats(_decompress(doc.get("_c", b"")) or {})
                if not data:
                    missing_c.append(uid)
                    continue
                if _is_stale_user_payload(data, current_epoch):
                    continue
                merged[uid] = data

            if missing_c:
                for mdoc in slot["users"].find({"_id": {"$in": missing_c}}, {}):
                    muid = str(mdoc.get("_id"))
                    if muid in merged:
                        continue
                    data = _mongo_doc_to_user_data(mdoc)
                    if _is_stale_user_payload(data, current_epoch):
                        continue
                    merged[muid] = data
        except Exception:
            _mark_slot_failed(slot)

    for uid, data in _relay_iter_users():
        if _is_stale_user_payload(data, current_epoch):
            continue
        merged.setdefault(uid, data)

    for uid, data in USER_CACHE.items():
        if isinstance(data, dict) and not _is_stale_user_payload(data, current_epoch):
            merged[str(uid)] = dict(data)

    return list(merged.items())


# ═══════════════════════════════════════════════════════════
# FAST QUERIES - Optimized for millions of users
# Uses MongoDB indexes instead of full iteration
# ═══════════════════════════════════════════════════════════

def _fast_count_users() -> int:
    _ensure_storage_slots()
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                return tidb.tidb_count_users()
            except Exception as exc:
                logger.debug(f"TiDB count failed: {exc}")
    total = 0
    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        try:
            total += slot["users"].count_documents({})
        except Exception:
            _mark_slot_failed(slot)
    return total


def _fast_get_users_batch(limit: int = 1000, offset: int = 0, sort_field: str = "_id", 
                           filter_dict: dict = None, projection: dict = None) -> list:
    """Get users in batches using MongoDB indexes (pagination)."""
    results = []
    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        try:
            query = _compress_query(filter_dict) if filter_dict else {}
            cursor = slot["users"].find(query, projection or {})
            direction = -1 if sort_field.startswith("-") else 1
            field = sort_field.lstrip("-")
            cursor = cursor.sort(field, direction)
            cursor = cursor.skip(offset).limit(limit)
            for doc in cursor:
                uid = str(doc.get("_id"))
                data = _refresh_period_stats(_decompress(doc.get("_c", b"")) or {})
                if not _is_stale_user_payload(data, _current_data_epoch()):
                    results.append((uid, data))
            break  # Only query first healthy slot
        except Exception:
            _mark_slot_failed(slot)
    return results


_extra_sub_clients: dict[str, Any] = {}
_extra_sub_clients_lock = threading.RLock()


def _get_extra_sub_client(uri: str, db_name: str):
    """Get or create a cached Mongo client for owner-added sub-DB.
    Returns (client, db, error_str) tuple."""
    if not MONGO_ENABLED:
        return None, None, "mongo_disabled"
    if not uri:
        return None, None, "empty_uri"
    with _extra_sub_clients_lock:
        existing = _extra_sub_clients.get(uri)
        if existing is not None:
            try:
                existing["client"].server_info()
                return existing["client"], existing["db"], None
            except Exception:
                try:
                    existing["client"].close()
                except Exception:
                    pass
                _extra_sub_clients.pop(uri, None)
        if MongoClient is None:
            return None, None, "pymongo_unavailable"
        try:
            client = MongoClient(
                uri,
                maxPoolSize=10,
                minPoolSize=1,
                maxIdleTimeMS=45000,
                serverSelectionTimeoutMS=15000,
                connectTimeoutMS=15000,
                socketTimeoutMS=30000,
                retryWrites=True,
                retryReads=True,
            )
            client.server_info()
            db = client[db_name or "anyybot"]
            _extra_sub_clients[uri] = {"client": client, "db": db, "ts": time.time()}
            return client, db, None
        except Exception as exc:
            return None, None, str(exc)


def _close_extra_sub_clients() -> None:
    """Close all cached sub-DB clients (called on shutdown/refresh)."""
    with _extra_sub_clients_lock:
        for entry in _extra_sub_clients.values():
            try:
                entry["client"].close()
            except Exception:
                pass
        _extra_sub_clients.clear()


def _fast_get_premium_users(limit: int = 100) -> list:
    """Get premium users using index (fast). Caches sub-DB clients across calls."""
    current_time = int(time.time())
    results = []

    compressed_premium_until = COMPRESSED_FIELDS.get("premium_until", "premium_until")
    compressed_username = COMPRESSED_FIELDS.get("username", "username")
    compressed_display_name = COMPRESSED_FIELDS.get("display_name", "display_name")

    # Check config slots (P1-P7) — uses managed slots, no client creation
    for slot in _mongo_slots:
        if not slot.get("ok"):
            continue
        try:
            query = _compress_query({"premium_until": {"$gt": current_time}})
            proj = {"_id": 1, compressed_username: 1, compressed_premium_until: 1, compressed_display_name: 1, "_c": 1}
            cursor = slot["users"].find(query, proj)
            cursor = cursor.sort(compressed_premium_until, -1).limit(limit)
            for doc in cursor:
                uid = str(doc.get("_id"))
                data = _refresh_period_stats(_decompress(doc.get("_c", b"")) or {})
                results.append((uid, data))
            break
        except Exception:
            _mark_slot_failed(slot)

    if len(results) >= limit:
        return results

    # Check owner-added sub-DBs — uses cached clients (no per-call creation)
    extra_slots = _load_extra_slots(MONGO_SLOT_SETTINGS_KEY)
    for slot_data in extra_slots:
        if len(results) >= limit:
            break
        uri = slot_data.get("uri", "")
        db_name = slot_data.get("db_name", "anyybot")
        if not uri:
            continue
        _client, db, err = _get_extra_sub_client(uri, db_name)
        if db is None:
            logger.debug(f"_fast_get_premium_users sub-DB {uri[:30]}... unavailable: {err}")
            continue
        try:
            query = _compress_query({"premium_until": {"$gt": current_time}})
            proj = {"_id": 1, compressed_username: 1, compressed_premium_until: 1, compressed_display_name: 1}
            for doc in db.users.find(query, proj).sort(compressed_premium_until, -1).limit(limit - len(results)):
                uid = str(doc.get("_id"))
                raw = _decompress_keys(dict(doc))
                data = {
                    "premium_until": int(raw.get("premium_until", 0) or 0),
                    "username": str(raw.get("username", "") or ""),
                    "display_name": str(raw.get("display_name", "") or ""),
                }
                results.append((uid, data))
        except Exception:
            logger.warning("Failed to get premium users from sub-DB", exc_info=True)
    return results

def _clear_all_stats(category="all"):
    """Clear database statistics based on category."""
    summary = {}

    # Clear stickers from sub-DBs (uses cached client — no per-call creation)
    extra_slots = _load_extra_slots(MONGO_SLOT_SETTINGS_KEY)
    for slot_data in extra_slots:
        uri = slot_data.get("uri", "")
        db_name = slot_data.get("db_name", "anyybot")
        if not uri:
            continue
        _client, db, err = _get_extra_sub_client(uri, db_name)
        if db is None:
            logger.debug(f"_clear_all_stats sub-DB stickers {uri[:30]}... unavailable: {err}")
            continue
        try:
            db.stickers.delete_many({})
        except Exception:
            logger.warning("Failed to clear stickers from sub-DB", exc_info=True)

    if category in {"runtime", "all"}:
        summary["relay_runtime"] = _relay_count("runtime")
        _relay_execute("DELETE FROM runtime")

        # Clear config slots runtime
        for slot in _mongo_slots:
            if not slot.get("ok"):
                continue
            try:
                summary["mongo_runtime"] = summary.get("mongo_runtime", 0) + int(slot["runtime"].count_documents({}))
                slot["runtime"].delete_many({})
            except Exception:
                _mark_slot_failed(slot)

        # Clear owner-added sub-database runtime (uses cached client)
        for slot in extra_slots:
            uri = slot.get("uri", "")
            db_name = slot.get("db_name", "anyybot")
            if not uri:
                continue
            _client, db, err = _get_extra_sub_client(uri, db_name)
            if db is None:
                logger.debug(f"_clear_all_stats sub-DB runtime {uri[:30]}... unavailable: {err}")
                continue
            try:
                runtime_count = db.runtime_state.count_documents({})
                db.runtime_state.delete_many({})
                summary["sub_mongo_runtime"] = summary.get("sub_mongo_runtime", 0) + runtime_count
            except Exception:
                logger.warning("Failed to clear runtime from sub-DB", exc_info=True)
        
    if category in {"backups", "all"}:
        summary["remote_artifacts"] = len(list_remote_artifacts())
        clear_remote_artifacts()
        runtime_cleanup = _purge_runtime_files()
        summary["runtime_files"] = runtime_cleanup.get("files_deleted", 0)
        summary["runtime_folders"] = runtime_cleanup.get("folders_deleted", 0)
        try:
            Path(LOCAL_FILE).unlink(missing_ok=True)
        except Exception:
            logger.warning("Failed to delete local backup file", exc_info=True)
        _save_json(Path(LOCAL_FILE), {})
        LOCAL_DB.clear()

    if category in {"users", "runtime", "all"}:
        try:
            import sys as _sys
            _main_mod = _sys.modules.get("__main__")
            chat_history = getattr(_main_mod, "chat_history", None)
            message_counter = getattr(_main_mod, "message_counter", None)
            user_messages = getattr(_main_mod, "user_messages", None)
            chat_history.clear()
            message_counter.clear()
            user_messages.clear()
        except Exception:
            logger.warning("Failed to clear economy caches", exc_info=True)
        try:
            _get_banned_cache().clear()
        except Exception:
            logger.warning("Failed to clear security cache", exc_info=True)

    if category in {"users", "settings", "stickers", "runtime", "all"}:
        _relay_compact()

    if category in {"users", "all"}:
        next_epoch = max(int(time.time()), _current_data_epoch() + 1, 1)
        LOCAL_SETTINGS[DATA_EPOCH_KEY] = str(next_epoch)
        _save_json(Path(LOCAL_SETTINGS_FILE), LOCAL_SETTINGS)
        save_setting(DATA_EPOCH_KEY, str(next_epoch))

    refresh_storage_slots()
    return summary

_RANK_CACHE: dict[str, tuple[int, float]] = {}
_RANK_CACHE_TTL = 300.0  # 5min (was 120s, 2.5x to save 60% RU on pf)

def invalidate_rank_cache(uid) -> None:
    _RANK_CACHE.pop(str(uid), None)

def get_global_rank(uid: str) -> int:
    """Return 1-based global rank by balance (1 = highest balance). Cached 120s."""
    uid = str(uid)
    now = time.time()
    hit = _RANK_CACHE.get(uid)
    if hit is not None and now - hit[1] < _RANK_CACHE_TTL:
        return hit[0]
    rank = _compute_global_rank(uid)
    _RANK_CACHE[uid] = (rank, now)
    if len(_RANK_CACHE) > 20000:
        cutoff = now - _RANK_CACHE_TTL
        stale = [k for k, v in _RANK_CACHE.items() if v[1] < cutoff][:8000]
        for k in stale:
            _RANK_CACHE.pop(k, None)
    return rank


def _compute_global_rank(uid: str) -> int:
    """Compute 1-based global rank by balance (1 = highest balance)."""
    # Try to get balance from cache first to avoid full user load
    cached = USER_CACHE.get(uid)
    if cached:
        balance_val = int(cached.get('balance', 0) or 0)
    else:
        user = get_user(uid)
        if not user:
            return 0
        balance_val = int(user.get('balance', 0) or 0)
    
    compressed_balance = COMPRESSED_FIELDS.get("balance", "balance")

    # ── TiDB path (primary) ────────────────────────────────────────────────
    if _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                return tidb.tidb_get_global_rank(uid)
            except Exception as exc:
                logger.debug(f"TiDB rank failed: {exc}")
                if _tidb_priority() == "tidb_only":
                    return 1

    total_above = 0
    any_success = False
    ok_slots = [s for s in _mongo_slots if s.get("ok") and s.get("users") is not None]
    for slot in ok_slots:
        try:
            above = _mongo_call(slot['users'].count_documents,
                _compress_query({compressed_balance: {'$gt': balance_val}, "banned": {"$ne": True}})
            )
            total_above += above
            any_success = True
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            logger.debug(f"get_global_rank transient error on slot {slot.get('slot_id')}: {exc}")
            continue
        except Exception as exc:
            logger.debug(f"get_global_rank failed on slot {slot.get('slot_id')}: {exc}")
    if total_above > 0 or any_success:
        return total_above + 1
    try:
        above = sum(
            1 for _, data in _relay_iter_users()
            if int(data.get('balance', 0) or 0) > balance_val
        )
        if above >= 0:
            return above + 1
    except Exception as e:
        logger.warning("Exception: %s", str(e))
    # Final fallback: try TiDB directly (pypy connections are thread-local)
    tidb = _get_tidb()
    if tidb:
        try:
            _check_tidb_available()
            return tidb.tidb_get_global_rank(uid)
        except Exception as exc:
            logger.debug(f"get_global_rank TiDB fallback failed: {exc}")
    return 0


def leaderboard_rows(sort_key: str, limit: int = 10) -> list:
    _ensure_storage_slots()
    now_ts = int(time.time())

    cache_key = f"lb:{sort_key}:{limit}"
    if cache_key in _LEADERBOARD_CACHE:
        return _LEADERBOARD_CACHE[cache_key]

    # ── TiDB path (primary, self-healing — probes slots directly so a
    #    transient cold-start does not silently fall back to stale relay) ──
    if TIDB_ENABLED:
        try:
            pool = get_pool()
            pool.ensure_recovered()
            if any(s.ok for s in pool.slots):
                tidb = _get_tidb()
                if tidb and hasattr(tidb, "tidb_cached_leaderboard"):
                    result = tidb.tidb_cached_leaderboard(sort_key, limit)
                    _LEADERBOARD_CACHE[cache_key] = result
                    return result
        except Exception as exc:
            logger.debug(f"TiDB leaderboard failed: {exc}")
            if _tidb_priority() == "tidb_only":
                return []

    # ── MongoDB path (fallback) ─────────────────────────────────────────────
    compressed_sort_key = COMPRESSED_FIELDS.get(sort_key, sort_key)
    _FLAT_SORT_KEYS = {"balance", "rp", "captures", "total_redeem_earned",
                        "daily_income", "weekly_income", "lifetime_income",
                        "daily_captures", "weekly_captures",
                        "daily_redeem", "weekly_redeem", "level"}
    projection = {"_id": 1, "n": 1, "fn": 1, "display_name": 1, "premium_until": 1, "b": 1, compressed_sort_key: 1}
    if sort_key not in _FLAT_SORT_KEYS:
        projection["_c"] = 1
    merged: dict[str, dict] = {}

    ok_slots = [s for s in _mongo_slots if s.get("ok") and s.get("users") is not None]
    if not ok_slots:
        # Fallback to relay data when MongoDB is down
        try:
            all_data = list(_relay_iter_users())
            sorted_data = sorted(
                all_data,
                key=lambda x: int(x[1].get(sort_key, 0) or 0),
                reverse=True,
            )[:limit]
            rows = []
            for uid, data in sorted_data:
                if data.get("is_bot"):
                    continue
                raw_username = data.get("username") or data.get("n") or ""
                raw_first_name = data.get("first_name") or data.get("fn") or ""
                label = f"@{raw_username}" if raw_username else (raw_first_name or f"User{uid[-4:]}")
                value = int(data.get(sort_key, 0) or 0)
                balance = int(data.get("balance", 0) or 0)
                premium_until = int(data.get("premium_until", 0) or 0)
                badge = "⭐" if premium_until > now_ts else "👤"
                rows.append({"user_id": uid, "label": label, "value": value, "balance": balance, "badge": badge})
            _LEADERBOARD_CACHE[cache_key] = rows
            return rows
        except Exception as exc:
            logger.debug(f"Leaderboard relay fallback failed: {exc}")
            return []

    for slot in ok_slots:
        try:
            cursor = _mongo_call(slot["users"].find,
                _compress_query({"banned": {"$ne": True}, "is_bot": {"$ne": True}}),
                projection
            ).sort(compressed_sort_key, -1).limit(limit)
            for doc in cursor:
                uid = str(doc.get("_id"))
                if uid in merged:
                    continue

                raw_username = doc.get("n") or doc.get("username") or ""
                raw_display_name = doc.get("display_name") or ""
                raw_first_name = doc.get("fn") or doc.get("first_name") or ""
                # Priority: @username > first_name > display_name > "User"
                if raw_username:
                    label = f"@{raw_username}"
                elif raw_first_name:
                    label = raw_first_name
                elif raw_display_name:
                    label = raw_display_name
                else:
                    label = f"User{uid[-4:]}"

                flat_value = doc.get(compressed_sort_key, None)
                if flat_value is not None:
                    value = int(flat_value)
                else:
                    blob = doc.get("_c")
                    if blob:
                        try:
                            blob_data = _decompress(blob)
                            if isinstance(blob_data, dict):
                                value = int(blob_data.get(sort_key, 0) or 0)
                            else:
                                value = 0
                        except Exception:
                            value = 0
                    else:
                        value = 0

                flat_balance = doc.get("b", 0) or 0
                premium_until = int(doc.get("premium_until", 0) or 0)
                badge = "⭐" if premium_until > now_ts else "👤"

                merged[uid] = {"user_id": uid, "label": label, "value": value, "balance": flat_balance, "badge": badge}
        except (AutoReconnect, NetworkTimeout, ServerSelectionTimeoutError, ConnectionFailure) as exc:
            logger.debug(f"Leaderboard transient error on slot {slot.get('slot_id')}: {exc}")
        except Exception as exc:
            logger.warning("Leaderboard query failed on slot %s", slot.get('slot_id'), exc_info=True)

    rows = sorted(merged.values(), key=lambda r: r["value"], reverse=True)[:limit]
    # Fallback: try TiDB when MongoDB returned nothing and TiDB wasn't tried above
    if not rows and not ok_slots and not _use_tidb_for("users"):
        tidb = _get_tidb()
        if tidb:
            try:
                _check_tidb_available()
                tidb_rows = tidb.tidb_cached_leaderboard(sort_key, limit)
                if tidb_rows:
                    rows = tidb_rows
            except Exception as exc:
                logger.debug(f"Leaderboard TiDB fallback failed: {exc}")
    _LEADERBOARD_CACHE[cache_key] = rows
    return rows

def clear_all_data(target: str = "all") -> dict:
    """Wipe data from the database. Use with extreme caution.
    
    Args:
        target: "users" — wipe all user data
                "settings" — wipe all settings
                "runtime" — wipe runtime/temp data
                "stickers" — wipe sticker data
                "backups" — wipe backup artifacts
                "balance" — wipe user balances only
                "economy" — wipe in-memory economy caches
                "chats" — wipe chat data
                "bans" — wipe ban cache and flags
                "games" — wipe in-memory game sessions
                "premium" — wipe premium status
                "all" — wipe everything
    Returns:
        dict with counts of deleted items per category
    """
    logger.warning(f"clear_all_data called with target={target}")
    # If wiping users/all, back up permanent IDs first so they survive the wipe.
    # These IDs are stored in a state-slot collection that is never touched by
    # clear_all_data() and is also explicitly excluded from the protected collections list.
    perm_pre = perm_ids_count() if target in ("users", "all") else None
    result = {"users": 0, "settings": 0, "runtime": 0, "stickers": 0,
              "backups": 0, "balance": 0, "economy": 0, "chats": 0,
              "bans": 0, "games": 0, "premium": 0}
    
    if target in ("users", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("users")
                if col is not None:
                    r = col.delete_many({})
                    result["users"] += r.deleted_count
            except Exception as e:
                logger.warning("Failed to clear users in slot", exc_info=True)
        # Also clear TiDB users if active
        if _use_tidb():
            try:
                import sys as _sys
                _main_mod = _sys.modules.get("__main__")
                tidb_clear_all_users = getattr(_main_mod, "tidb_clear_all_users", None)
                tidb_result = tidb_clear_all_users()
                result["users"] += tidb_result.get("slots_cleared", 0) * 10000  # approximate
            except Exception as exc:
                logger.warning("Failed to clear TiDB users: %s", exc)
        USER_CACHE.clear()
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM users")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay users", exc_info=True)
        try:
            _get_banned_cache().clear()
        except Exception as e:
            logger.debug(f"Failed to clear ban cache: {e}")
    
    if target in ("settings", "all"):
        _SETTINGS_CACHE.clear()
        for slot in _mongo_slots:
            try:
                col = slot.get("settings")
                if col is not None:
                    r = col.delete_many({})
                    result["settings"] += r.deleted_count
            except Exception as e:
                logger.warning("Failed to clear settings in slot", exc_info=True)
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM settings")
                _relay.execute("DELETE FROM stickers")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay settings", exc_info=True)
        try:
            LOCAL_SETTINGS.clear()
            Path(LOCAL_SETTINGS_FILE).write_text("{}", encoding="utf-8")
        except Exception as e:
            logger.warning("Failed to clear local settings", exc_info=True)
    
    if target in ("runtime", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("runtime")
                if col is not None:
                    r = col.delete_many({})
                    result["runtime"] += r.deleted_count
            except Exception as e:
                logger.warning("Failed to clear runtime in slot", exc_info=True)
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM runtime")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay runtime", exc_info=True)
        try:
            if BLOB_CACHE_DIR.exists():
                shutil.rmtree(str(BLOB_CACHE_DIR))
                BLOB_CACHE_DIR.mkdir(exist_ok=True)
        except Exception as e:
            logger.warning("Failed to clear blob cache", exc_info=True)
    
    if target in ("stickers", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("stickers")
                if col is not None:
                    r = col.delete_many({})
                    result["stickers"] += r.deleted_count
            except Exception as e:
                logger.warning("Failed to clear stickers in slot", exc_info=True)
        extra_slots = _load_extra_slots(MONGO_SLOT_SETTINGS_KEY)
        for slot_data in extra_slots:
            uri = slot_data.get("uri", "")
            db_name = slot_data.get("db_name", "anyybot")
            if not uri:
                continue
            _client, db, err = _get_extra_sub_client(uri, db_name)
            if db is None:
                logger.debug(f"clear stickers sub-DB {uri[:30]}... unavailable: {err}")
                continue
            try:
                r = db.stickers.delete_many({})
                result["stickers"] += r.deleted_count
            except Exception:
                logger.warning("Failed to clear stickers from sub-DB", exc_info=True)
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM stickers")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay stickers", exc_info=True)
    
    if target in ("backups", "all"):
        try:
            result["backups"] = len(list_remote_artifacts())
            clear_remote_artifacts()
        except Exception as e:
            logger.warning("Failed to clear remote artifacts", exc_info=True)
        try:
            runtime_cleanup = _purge_runtime_files()
            result["backups"] += runtime_cleanup.get("files_deleted", 0)
        except Exception as e:
            logger.warning("Failed to purge runtime files", exc_info=True)
        try:
            Path(LOCAL_FILE).unlink(missing_ok=True)
        except Exception as e:
            logger.warning("Failed to delete local backup file", exc_info=True)
        _save_json(Path(LOCAL_FILE), {})
        LOCAL_DB.clear()
    
    if target in ("balance", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("users")
                if col is not None:
                    r = col.update_many({}, {"$set": {"b": 0}})
                    result["balance"] += r.modified_count
            except Exception as e:
                logger.warning("Failed to clear balance in slot", exc_info=True)
        if _use_tidb():
            try:
                import sys as _sys
                _main_mod = _sys.modules.get("__main__")
                tidb_reset_all_users = getattr(_main_mod, "tidb_reset_all_users", None)
                tidb_reset_all_users(set_fields={"balance": 0})
            except Exception as exc:
                logger.warning("TiDB balance wipe failed: %s", exc)
        USER_CACHE.clear()
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM users")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay users for balance wipe", exc_info=True)
    
    if target in ("economy", "all"):
        try:
            import sys as _sys
            _main_mod = _sys.modules.get("__main__")
            chat_history = getattr(_main_mod, "chat_history", None)
            message_counter = getattr(_main_mod, "message_counter", None)
            user_messages = getattr(_main_mod, "user_messages", None)
            chat_history.clear()
            message_counter.clear()
            user_messages.clear()
            result["economy"] = 1
        except Exception as e:
            logger.warning("Failed to clear economy caches", exc_info=True)
    
    if target in ("chats", "all"):
        for slot in _mongo_slots:
            try:
                db = slot.get("db")
                if db is not None:
                    r = db.get_collection("chats").delete_many({})
                    result["chats"] += r.deleted_count
            except Exception as e:
                logger.warning("Failed to clear chats in slot", exc_info=True)
        try:
            _chat_buffers.clear()
        except Exception as e:
            logger.warning("Failed to clear chat buffer", exc_info=True)
    
    if target in ("bans", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("users")
                if col is not None:
                    r = col.update_many({}, {"$set": {"bn": False}})
                    result["bans"] += r.modified_count
            except Exception as e:
                logger.warning("Failed to clear bans in slot", exc_info=True)
        if _use_tidb():
            try:
                import sys as _sys
                _main_mod = _sys.modules.get("__main__")
                tidb_reset_all_users = getattr(_main_mod, "tidb_reset_all_users", None)
                tidb_reset_all_users(set_fields={"bn": False})
            except Exception as exc:
                logger.warning("TiDB ban wipe failed: %s", exc)
        try:
            _get_banned_cache().clear()
        except Exception as e:
            logger.warning("Failed to clear ban cache", exc_info=True)
    
    if target in ("games", "all"):
        try:
            xogame__games.clear()
            result["games"] += 1
        except Exception:
            logger.warning("Failed to clear xogame _games", exc_info=True)
        try:
            _ACTIVE_GAMES.clear()
        except Exception:
            logger.warning("Failed to clear wordguess _ACTIVE_GAMES", exc_info=True)
        try:
            game_state_cache.clear()
        except Exception:
            logger.warning("Failed to clear game_state_cache", exc_info=True)
    
    if target in ("premium", "all"):
        for slot in _mongo_slots:
            try:
                col = slot.get("users")
                if col is not None:
                    r = col.update_many({}, {"$set": {"premium_until": 0}})
                    result["premium"] += r.modified_count
            except Exception as e:
                logger.warning("Failed to clear premium in slot", exc_info=True)
        if _use_tidb():
            try:
                import sys as _sys
                _main_mod = _sys.modules.get("__main__")
                tidb_reset_all_users = getattr(_main_mod, "tidb_reset_all_users", None)
                tidb_reset_all_users(set_fields={"premium_until": 0})
            except Exception as exc:
                logger.warning("TiDB premium wipe failed: %s", exc)
        USER_CACHE.clear()
        try:
            with _RELAY_GLOBAL_LOCK:
                _relay.execute("DELETE FROM users")
                _relay.commit()
        except Exception as e:
            logger.warning("Failed to clear relay users for premium wipe", exc_info=True)
    
    logger.info(f"clear_all_data({target}) complete: {result}")
    # Surface the permanent ID registry state so callers can show that
    # user_ids/group_ids/channel_ids survived the wipe.
    if perm_pre is not None:
        perm_post = perm_ids_count()
        result["perm_ids_preserved"] = perm_post
        logger.info(f"Permanent ID registry preserved through wipe: {perm_post}")
    return result


_PROTECTED_BACKUP_COLLECTION = "user_protected"


def _backup_protected_to_state_slots():
    """Backup protected user identity fields to state slots (P6/P7) for safety.
    These survive even a full database wipe."""
    state_slots = [s for s in _mongo_slots if s.get("category") == "state" and s.get("ok")]
    if not state_slots:
        return 0

    backed = 0
    for slot in _mongo_slots:
        col = slot.get("users")
        if col is None or not slot.get("ok"):
            continue
        for doc in col.find({}, {
            "_id": 1, "n": 1, "fn": 1, "ln": 1, "display_name": 1,
            "dm_verified": 1, "dm_started": 1, "bn": 1, "sb": 1, "pr": 1,
            "gc": 1, "groupclaimed": 1,
            "web_verify_lifetime": 1, "web_verified_until": 1, "trust_score": 1,
        }):
            uid = doc.get("_id")
            if not uid:
                continue
            protected = {
                "_id": str(uid),
                "n": doc.get("n") or "",
                "fn": doc.get("fn") or "",
                "ln": doc.get("ln") or "",
                "display_name": doc.get("display_name") or "",
                "dm_v": bool(doc.get("dm_verified", False)),
                "dm_s": bool(doc.get("dm_started", False)),
                "bn": bool(doc.get("bn", False)),
                "sb": bool(doc.get("sb", False)),
                "pr": int(doc.get("pr", 0) or doc.get("premium_until", 0) or 0),
                "gc": doc.get("gc") or doc.get("groupclaimed") or "",
                "wvl": int(doc.get("web_verify_lifetime", 0) or 0),
                "wvu": float(doc.get("web_verified_until", 0) or 0),
                "ts": int(doc.get("trust_score", 0) or 0),
                "updated_at": int(time.time()),
            }
            for ss in state_slots:
                try:
                    ss["db"][_PROTECTED_BACKUP_COLLECTION].update_one(
                        {"_id": str(uid)},
                        {"$set": protected},
                        upsert=True,
                    )
                except Exception as e:
                    logger.warning("Exception: %s", str(e))
            backed += 1

    logger.info(f"Backed up {backed} user identities to state slots")
    return backed


def _restore_protected_from_state_slots():
    """After a full database wipe, restore identity data from state slots."""
    state_slots = [s for s in _mongo_slots if s.get("category") == "state" and s.get("ok")]
    if not state_slots:
        return 0

    restored = 0
    for ss in state_slots:
        prot_col = ss["db"].get_collection(_PROTECTED_BACKUP_COLLECTION)
        if prot_col is None:
            continue
        for prot_doc in prot_col.find():
            uid = str(prot_doc.get("_id"))
            if not uid:
                continue
            # Restore protected fields into any writable user slot
            for slot in _mongo_slots:
                col = slot.get("users")
                if col is None or not slot.get("ok"):
                    continue
                try:
                    col.update_one(
                        {"_id": uid},
                        {"$set": {
                            "n": prot_doc.get("n", ""),
                            "fn": prot_doc.get("fn", ""),
                            "ln": prot_doc.get("ln", ""),
                            "display_name": prot_doc.get("display_name", ""),
                            "dm_verified": prot_doc.get("dm_v", False),
                            "dm_started": prot_doc.get("dm_s", False),
                            "bn": prot_doc.get("bn", False),
                            "sb": prot_doc.get("sb", False),
                            "pr": int(prot_doc.get("pr", 0)),
                            "gc": prot_doc.get("gc", ""),
                            "web_verify_lifetime": int(prot_doc.get("wvl", 0)),
                            "web_verified_until": float(prot_doc.get("wvu", 0)),
                            "trust_score": int(prot_doc.get("ts", 0)),
                        }},
                        upsert=True,
                    )
                    restored += 1
                    break  # one slot is enough
                except Exception:
                    logger.warning("Exception in _restore_protected_from_state_slots", exc_info=True)
                    continue
    logger.info(f"Restored {restored} user identities from state slots")
    return restored


# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# PERMANENT ID REGISTRY — survives even /dbwipeallconfirm
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# Stores every user_id, group_id, channel_id the bot has ever seen.
# Backed by an independent "perm_ids" collection on state slots that is
# NEVER touched by clear_all_data(). Owner commands exist to view/count/export.

_PERM_IDS_COLLECTION = "perm_ids"   # schema: {_id: "<type>:<id>", t: "u"|"g"|"c", ts: int, name: str}
_PERM_IDS_DOCTYPE = {"u": "user", "g": "group", "c": "channel"}


def _perm_ids_col():
    """Return the perm_ids collection on the first healthy state slot, or None."""
    for s in _mongo_slots:
        if s.get("category") == "state" and s.get("ok") and s.get("db") is not None:
            try:
                return s["db"][_PERM_IDS_COLLECTION]
            except Exception:
                continue
    return None


def record_id(uid_or_id: int | str, kind: str = "u", name: str = "") -> bool:
    """Record a user/group/channel ID in the permanent registry. Idempotent.

    Args:
        uid_or_id: numeric user/group/channel id
        kind: "u" for user, "g" for group, "c" for channel
        name: optional display name
    Returns:
        True if recorded (or already present), False if no state slot available.
    """
    if kind not in _PERM_IDS_DOCTYPE:
        return False
    try:
        sid = str(int(uid_or_id))
    except (TypeError, ValueError):
        sid = str(uid_or_id)
    col = _perm_ids_col()
    if col is None:
        return False
    try:
        col.update_one(
            {"_id": f"{kind}:{sid}"},
            {"$set": {"t": kind, "sid": sid, "name": name or ""},
             "$setOnInsert": {"first_seen": int(time.time())},
             "$currentDate": {"last_seen": True}},
            upsert=True,
        )
        return True
    except Exception as e:
        logger.debug("record_id failed for %s:%s: %s", kind, sid, e)
        return False


def perm_ids_count() -> dict[str, int]:
    """Count registered users/groups/channels. Cheap aggregation."""
    col = _perm_ids_col()
    if col is None:
        return {"users": 0, "groups": 0, "channels": 0, "total": 0}
    out = {"users": 0, "groups": 0, "channels": 0, "total": 0}
    try:
        pipeline = [
            {"$group": {"_id": "$t", "n": {"$sum": 1}}},
        ]
        for r in col.aggregate(pipeline):
            t = r.get("_id")
            n = int(r.get("n") or 0)
            if t == "u":
                out["users"] = n
            elif t == "g":
                out["groups"] = n
            elif t == "c":
                out["channels"] = n
            out["total"] += n
    except Exception:
        logger.exception("perm_ids_count failed")
    return out


def perm_ids_iter(kind: str | None = None, limit: int = 0):
    """Iterate registered IDs. If kind is None, returns all types.
    Yields (kind, sid, name, last_seen)."""
    col = _perm_ids_col()
    if col is None:
        return
    q = {"t": kind} if kind in _PERM_IDS_DOCTYPE else {}
    cursor = col.find(q, {"_id": 0, "t": 1, "sid": 1, "name": 1, "last_seen": 1})
    n = 0
    for doc in cursor:
        n += 1
        if limit and n > limit:
            return
        yield (doc.get("t", ""), doc.get("sid", ""), doc.get("name", ""), doc.get("last_seen", 0))


def perm_ids_export_text(kind: str | None = None) -> str:
    """Export all IDs as plain text (for /permexport)."""
    lines = []
    label = _PERM_IDS_DOCTYPE.get(kind, "all") if kind else "all"
    lines.append(f"📇 Pᴇʀᴍᴀɴᴇɴᴛ IDs ({label})")
    for t, sid, name, ts in perm_ids_iter(kind):
        lines.append(f"  {t} : {sid}  {name}".rstrip())
    return "\n".join(lines) if len(lines) > 1 else "(empty)"


def perm_ids_register_from_collection(coll_name: str) -> int:
    """Backfill: scan an existing user/group collection and register every _id.
    Useful for the first time a bot upgrades to use this system.
    Returns number of newly registered ids."""
    col = _perm_ids_col()
    if col is None:
        return 0
    added = 0
    try:
        for slot in _mongo_slots:
            if not slot.get("ok"):
                continue
            target = slot.get(coll_name)
            if target is None:
                continue
            kind = "u" if coll_name == "users" else ("g" if coll_name == "chats" else "c")
            for doc in target.find({}, {"_id": 1, "n": 1, "title": 1, "name": 1}):
                sid = str(doc.get("_id", ""))
                if not sid:
                    continue
                name = (doc.get("n") or doc.get("title") or doc.get("name") or "")
                if record_id(sid, kind, name):
                    added += 1
    except Exception:
        logger.exception("perm_ids_register_from_collection failed")
    return added


def is_perm_ids_collection_protected() -> bool:
    """Returns True if the perm_ids collection name is on the protected list."""
    return _PERM_IDS_COLLECTION == "perm_ids"


# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# WIPE-PROTECTION — clear_all_data NEVER touches perm_ids
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
_PROTECTED_COLLECTIONS: frozenset[str] = frozenset({
    _PERM_IDS_COLLECTION,
    _PROTECTED_BACKUP_COLLECTION,
})


def get_protected_collections() -> tuple[str, ...]:
    """Names of collections that survive any clear_all_data() call."""
    return tuple(_PROTECTED_COLLECTIONS)


