"""Granular reset target definitions for reset_user_data()."""


def reset_user_data(targets: list[str]) -> dict:
    """
    Reset specific game/economy fields for ALL users.

    Args:
        targets: List of target keys from _RESET_TARGETS.
                 e.g. ["balance"], ["balance", "xp"], ["all"]

    Returns dict with total/updated/errors/backed_up/fields keys.
    """
    _ensure_storage_slots()
    result = {"total": 0, "updated": 0, "errors": 0, "backed_up": 0, "fields": []}

    needs_backup = False
    needs_recompress = False
    needs_cache_clear = False

    set_all = {}
    unset_all = []
    active_labels = []

    for t in targets:
        spec = _RESET_TARGETS.get(t)
        if not spec:
            continue
        active_labels.append(spec["label"])
        set_all.update(spec.get("set", {}))
        unset_all.extend(spec.get("unset", []))
        if spec.get("clear_cache"):
            needs_cache_clear = True
        if t == "all":
            needs_backup = True
            needs_recompress = True

    if not set_all and not unset_all:
        return result

    result["fields"] = active_labels

    # Backup protected data if reseting all
    if needs_backup:
        result["backed_up"] = _backup_protected_to_state_slots()

    # ── MongoDB reset (legacy path) ──
    for slot in _mongo_slots:
        col = slot.get("users")
        if col is None or not slot.get("ok"):
            continue
        try:
            total = col.count_documents({})
            result["total"] += total

            update = {}
            if set_all:
                update["$set"] = {**set_all, "updated_at": int(time.time())}
            if unset_all:
                update["$unset"] = {k: "" for k in unset_all}

            if update:
                r = col.update_many({}, update)
                result["updated"] += r.modified_count
        except Exception as e:
            logger.warning("Reset error in slot %s", slot.get('slot_id'), exc_info=True)
            result["errors"] += 1

    # ── TiDB reset (primary data path) ──
    if _use_tidb():
        try:
            import sys as _sys
            _main_mod = _sys.modules.get("__main__")
            tidb_reset_all_users = getattr(_main_mod, "tidb_reset_all_users", None)
            tidb_result = tidb_reset_all_users(set_fields=set_all, unset_fields=unset_all)
            result["total"] += tidb_result.get("total", 0)
            result["updated"] += tidb_result.get("updated", 0)
            result["errors"] += tidb_result.get("errors", 0)
        except Exception as exc:
            logger.warning("TiDB reset failed: %s", exc)
            result["errors"] += 1

    if needs_cache_clear:
        USER_CACHE.clear()
        try:
            _get_banned_cache().clear()
        except Exception as e:
            logger.warning("Exception: %s", str(e))

    if needs_recompress:
        _recompress_all_user_blobs()

    logger.info(f"reset_user_data({targets}) complete: {result}")
    return result


def reset_all_user_game_data() -> dict:
    """Convenience wrapper — resets all targets (legacy interface)."""
    return reset_user_data(["all"])


def _recompress_all_user_blobs():
    """Re-generate _c compressed blobs for all users after reset."""
    for slot in _mongo_slots:
        col = slot.get("users")
        if col is None or not slot.get("ok"):
            continue
        try:
            for doc in col.find({}, {"_c": 0}):
                uid = doc.get("_id")
                if not uid:
                    continue
                raw = dict(doc)
                raw.pop("_id", None)
                raw = {DECOMPRESSED_FIELDS.get(k, k): v for k, v in raw.items()}
                raw["_c"] = _compress(raw)
                compressed_keys = {COMPRESSED_FIELDS.get(k, k): v for k, v in raw.items()}
                col.update_one({"_id": uid}, {"$set": compressed_keys})
        except Exception as e:
            logger.debug(f"Recompress error in slot {slot.get('slot_id')}: {e}")


def format_bytes(size: int) -> str:

    size = max(0, int(size or 0))
    units = ["B", "KB", "MB", "GB", "TB"]
    idx = 0
    value = float(size)
    while value >= 1024 and idx < len(units) - 1:
        value /= 1024
        idx += 1
    return f"{value:.1f}{units[idx]}" if idx else f"{int(value)}{units[idx]}"


def database_stats() -> dict:
    """Fast database stats using optimized queries."""
    storage = get_storage_status()
    chats = get_registered_chats()
    
    # FAST: Use count instead of full iteration
    user_count = _fast_count_users()
    
    # Sample a small batch to estimate DM users
    dm_sample = _fast_get_users_batch(limit=100)
    dm_ratio = sum(1 for _, item in dm_sample if item.get("dm_started")) / max(len(dm_sample), 1)
    dm_estimate = int(user_count * dm_ratio)
    
    mongo_size = sum(int(slot.get("usage_bytes", 0) or 0) for slot in storage["mongo_slots"])
    
    # TiDB per-slot storage stats
    tidb_slots = []
    tidb_total_bytes = 0
    if _use_tidb():
        try:
            import sys as _sys
            _main_mod = _sys.modules.get("__main__")
            tidb_storage_stats = getattr(_main_mod, "tidb_storage_stats", None)
            tidb_slots = tidb_storage_stats()
            tidb_total_bytes = sum(s.get("total_bytes", 0) for s in tidb_slots if s.get("ok"))
        except Exception:
            pass
    
    return {
        "mode": storage["mode"],
        "users": user_count,
        "players": user_count,
        "dm_users": dm_estimate,
        "mongo_size": mongo_size,
        "tidb_slots": tidb_slots,
        "tidb_total_bytes": tidb_total_bytes,
        "cache_size": len(USER_CACHE),
        "relay_users": storage["host_relay"]["users"],
        "groups": sum(1 for chat in chats if chat.get("type") in ("group", "supergroup")),
        "channels": sum(1 for chat in chats if chat.get("type") == "channel"),
        "registered_chats": len(chats),
        "mongo_up": bool(storage["available_mongo_slots"]),
        "telegram_backup_health": get_setting("telegram_backup_health", "unknown") or "unknown",
        "active_mongo_slot": storage["active_mongo_slot"],
        "active_by_purpose": storage.get("active_by_purpose", {}),
        "active_by_category": storage.get("active_by_category", {}),
        "available_mongo_slots": storage["available_mongo_slots"],
        "host_relay_mode": storage["host_relay"]["enabled"],
        "storage_registry_updated_at": int(storage.get("updated_at", 0) or 0),
        "last_backup_local": get_setting("last_backup_local", "") or "none",
        "last_backup_remote": get_setting_json("last_backup_remote", {}) or {},
        "last_delta_remote": get_setting_json("last_delta_remote", {}) or {},
        "storage_alerts": storage["alerts"],
    }


def export_backup_payload() -> dict:
    users = [{"_id": uid, **data} for uid, data in list_all_users()]
    settings_export: dict[str, Any] = {}
    for key, value in LOCAL_SETTINGS.items():
        if key.startswith("sticker_"):
            continue
        settings_export[key] = _dj(value, value) if isinstance(value, str) else value
    stickers_export: dict[str, Any] = {}
    for key, value in LOCAL_SETTINGS.items():
        if key.startswith("sticker_"):
            stickers_export[key.replace("sticker_", "", 1)] = _dj(value, value)
    return {
        "created_at": int(time.time()),
        "storage": get_storage_status(),
        "users": users,
        "settings": settings_export,
        "stickers": stickers_export,
    }


def import_backup_payload(payload: dict) -> dict:
    users = payload.get("users", []) if isinstance(payload, dict) else []
    settings_data = payload.get("settings", {}) if isinstance(payload, dict) else {}
    stickers_data = payload.get("stickers", {}) if isinstance(payload, dict) else {}
    restored = {"users": 0, "settings": 0, "stickers": 0}

    for item in users:
        if not isinstance(item, dict):
            continue
        uid = str(item.get("_id") or "")
        if not uid:
            continue
        record = dict(item)
        record.pop("_id", None)
        save_user(uid, record)
        restored["users"] += 1

    if isinstance(settings_data, dict):
        for key, value in settings_data.items():
            save_setting_json(key, value)
            restored["settings"] += 1

    if isinstance(stickers_data, dict):
        for key, value in stickers_data.items():
            if isinstance(value, dict):
                save_sticker_setting(key, value)
                restored["stickers"] += 1

    return restored


def _prune_local_backups(max_keep: int = MAX_LOCAL_BACKUPS) -> None:
    BACKUP_DIR.mkdir(exist_ok=True)
    zip_files = sorted(BACKUP_DIR.glob("*.zip"), key=lambda path: path.stat().st_mtime, reverse=True)
    for path in zip_files[max(1, int(max_keep or 1)):]:
        try:
            path.unlink(missing_ok=True)
        except Exception:
            logger.warning("Exception in _prune_local_backups", exc_info=True)
    for path in BACKUP_DIR.glob("*.json"):
        try:
            path.unlink(missing_ok=True)
        except Exception:
            logger.warning("Exception in _prune_local_backups", exc_info=True)


async def generate_backup(bot, kind: str = "daily_full") -> None:
    timestamp = datetime.now(IST).strftime("%Y%m%d_%H%M%S")
    BACKUP_DIR.mkdir(exist_ok=True)
    payload = await asyncio.to_thread(export_backup_payload)
    json_path = BACKUP_DIR / f"{kind}_{timestamp}.json"
    zip_path = BACKUP_DIR / f"{kind}_{timestamp}.zip"

    def _write_backup_files():
        json_path.write_text(json.dumps(payload, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as archive:
            archive.write(json_path, arcname=json_path.name)
            if Path(LOCAL_SETTINGS_FILE).exists():
                archive.write(LOCAL_SETTINGS_FILE, arcname=Path(LOCAL_SETTINGS_FILE).name)
    await asyncio.to_thread(_write_backup_files)

    try:
        json_path.unlink(missing_ok=True)
    except Exception:
        logger.warning("Exception in _write_backup_files", exc_info=True)

    await asyncio.to_thread(save_setting, "last_backup_local", str(zip_path))

    def _open_backup():
        return open(zip_path, "rb")
    try:
        handle = await asyncio.to_thread(_open_backup)
        sent = await bot.send_document(
            BACKUP_CHAT,
            document=handle,
            filename=zip_path.name,
            caption="Daily database archive" if kind == "daily_full" else f"Database archive: {kind}",
        )
        handle.close()
        backup_info = {
            "message_id": sent.message_id,
            "file_id": sent.document.file_id if sent.document else "",
            "created_at": int(time.time()),
            "filename": zip_path.name,
        }
        if kind == "daily_full":
            await asyncio.to_thread(save_setting_json, "last_backup_remote", backup_info)
        else:
            await asyncio.to_thread(save_setting_json, "last_delta_remote", backup_info)
        await asyncio.to_thread(
            record_remote_artifact,
            "backup" if kind == "daily_full" else "backup-delta",
            sent.message_id,
            file_id=backup_info["file_id"],
            chat_id=BACKUP_CHAT,
            label=zip_path.name,
        )
    except Exception as exc:
        logger.warning("Backup upload failed", exc_info=True)
    await asyncio.to_thread(_prune_local_backups)


