def _purge_runtime_files() -> dict:
    """Purge old runtime files and return cleanup stats."""
    stats = {"files_deleted": 0, "folders_deleted": 0}
    try:
        runtime_dir = Path("data/runtime")
        if runtime_dir.exists():
            # Delete old log files (older than 2 days)
            cutoff = time.time() - (2 * 86400)
            for log_file in runtime_dir.rglob("*"):
                if log_file.is_file() and log_file.stat().st_mtime < cutoff:
                    try:
                        log_file.unlink()
                        stats["files_deleted"] += 1
                    except Exception:
                        logger.warning("Exception in _purge_runtime_files", exc_info=True)
                elif log_file.is_dir() and not any(log_file.iterdir()):
                    try:
                        log_file.rmdir()
                        stats["folders_deleted"] += 1
                    except Exception as e:
                        logger.warning("Exception: %s", str(e))
    except Exception as exc:
        logger.error("Failed to purge runtime files", exc_info=True)
    return stats


def wipe_catalog() -> None:
    """Wipe the entire catalog database. Use with extreme caution."""
    logger.warning("wipe_catalog was called but is currently a no-op for safety.")
    pass


# ── Bot Lease / Host Status Functions ──────────────────────────────────


def acquire_bot_lease(instance_id: str, ttl: int = 90) -> bool:
    """Atomically acquire a bot lease in the runtime collection."""
    _ensure_storage_slots()
    now = int(time.time())
    expiry = now + ttl
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            result = col.find_one_and_update(
                {"_id": "bot_lease"},
                {"$setOnInsert": {"instance_id": instance_id, "acquired_at": now, "expires_at": expiry}},
                upsert=True,
                return_document=ReturnDocument.AFTER,
            )
            if result is None:
                continue
            current = result.get("instance_id")
            if current == instance_id:
                col.update_one({"_id": "bot_lease"}, {"$set": {"expires_at": expiry, "renewed_at": now}})
                return True
            expires = result.get("expires_at", 0)
            if now >= expires:
                col.update_one(
                    {"_id": "bot_lease", "instance_id": current},
                    {"$set": {"instance_id": instance_id, "acquired_at": now, "expires_at": expiry}},
                )
                return True
            continue
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    relay_key = f"lease:{instance_id}"
    existing = _relay_get_text("runtime", "bot_lease")
    if not existing:
        _relay_save_text("runtime", "bot_lease", instance_id, expiry)
        _relay_save_text("runtime", relay_key, str(expiry))
        return True
    try:
        relay_expiry = int(_relay_get_text("runtime", relay_key) or 0)
    except (ValueError, TypeError):
        relay_expiry = 0
    if now >= relay_expiry:
        _relay_save_text("runtime", "bot_lease", instance_id, expiry)
        _relay_save_text("runtime", relay_key, str(expiry))
        return True
    return False


def best_host_status() -> dict:
    """Return the current best host status dict."""
    _ensure_storage_slots()
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            doc = col.find_one({"_id": "bot_lease"})
            if doc:
                return {"instance_id": str(doc.get("instance_id", "")), "expires_at": doc.get("expires_at", 0)}
        except Exception:
            logger.warning("Exception in best_host_status", exc_info=True)
    raw = _relay_get_text("runtime", "bot_lease")
    if raw:
        lease_key = f"lease:{raw}"
        try:
            expiry = int(_relay_get_text("runtime", lease_key) or 0)
        except (ValueError, TypeError):
            expiry = 0
        return {"instance_id": raw, "expires_at": expiry}
    return {"instance_id": "", "expires_at": 0}


def list_host_statuses() -> list[dict]:
    """List all registered host statuses from the runtime store."""
    _ensure_storage_slots()
    results: list[dict] = []
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            for doc in col.find({"_id": {"$regex": "^host_status:"}}):
                results.append({k: v for k, v in doc.items() if k != "_id"})
        except Exception:
            logger.warning("Exception in list_host_statuses", exc_info=True)
    return results


def register_host_status(
    instance_id: str,
    status: str | None = None,
    ttl: int = 60,
    telegram_up: bool = False,
    is_active: bool | None = None,
) -> None:
    """Register or update the status of a bot host in the runtime store."""
    _ensure_storage_slots()
    now = int(time.time())
    doc = {
        "instance_id": instance_id,
        "status": status or "standby",
        "is_active": is_active if is_active is not None else (status == "active"),
        "telegram_up": telegram_up,
        "last_seen": now,
        "expires_at": now + ttl,
    }
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            col.update_one({"_id": f"host_status:{instance_id}"}, {"$set": doc}, upsert=True)
            return
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    _relay_save_text("runtime", f"host_status:{instance_id}", json.dumps(doc), now + ttl)


def release_bot_lease(instance_id: str) -> None:
    """Release the bot lease if owned by instance_id."""
    _ensure_storage_slots()
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            col.delete_one({"_id": "bot_lease", "instance_id": instance_id})
            return
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    _relay_delete_key("runtime", "bot_lease")
    _relay_delete_key("runtime", f"lease:{instance_id}")


def renew_bot_lease(instance_id: str, ttl: int = 90) -> bool:
    """Renew the bot lease if we currently hold it."""
    _ensure_storage_slots()
    now = int(time.time())
    expiry = now + ttl
    for slot in _writable_mongo_slots_for_purpose("runtime"):
        col = slot.get("runtime")
        if col is None:
            continue
        try:
            result = col.find_one_and_update(
                {"_id": "bot_lease", "instance_id": instance_id},
                {"$set": {"expires_at": expiry, "renewed_at": now}},
                return_document=ReturnDocument.AFTER,
            )
            if result:
                return True
            continue
        except Exception as exc:
            _mark_slot_failed(slot, str(exc))
    current = _relay_get_text("runtime", "bot_lease")
    if current == instance_id:
        _relay_save_text("runtime", f"lease:{instance_id}", str(expiry), expiry)
        return True
    return False


