def get_blob_pointer(kind: str, entity_id: str) -> dict | None:
    """Retrieve a blob pointer from the settings store."""
    raw = get_setting(f"blob_ptr:{kind}:{entity_id}")
    if raw is None:
        return None
    if isinstance(raw, str):
        try:
            return json.loads(raw)
        except Exception:
            logger.warning("Exception in get_blob_pointer", exc_info=True)
            return None
    return raw if isinstance(raw, dict) else None


def set_blob_pointer(kind: str, entity_id: str, pointer: dict | None = None) -> None:
    """Save a blob pointer to the settings store."""
    if pointer is None:
        pointer = {"kind": kind, "entity_id": str(entity_id), "created_at": int(time.time())}
    save_setting(f"blob_ptr:{kind}:{entity_id}", pointer)


# DEFERRED: Do NOT call at import time - blocks on MongoDB connections
# refresh_storage_slots() is called in post_init() async instead
_storage_slots_initialized = False
_mongo_ready_event = threading.Event()  # Set when MongoDB slots finish connecting


_last_storage_slot_attempt: float = 0
_ensure_slots_lock = threading.Lock()


def _ensure_storage_slots():
    """Lazy initialization - called on first database use, not at import time.
    Uses a lock to prevent duplicate background threads.
    First access immediately enables relay mode; MongoDB/TiDB connections run in background.
    """
    global _storage_slots_initialized
    if _storage_slots_initialized:
        return
    with _ensure_slots_lock:
        if _storage_slots_initialized:
            return
        try:
            threading.Thread(target=_background_init_slots, daemon=True).start()
        except Exception as exc:
            logger.warning("Failed to start storage init thread: %s", exc)
            _storage_slots_initialized = True


_WARMUP_BATCH_SIZE = 5000

def _warmup_cache_from_tidb():
    """Startup bulk load: pull ALL users from TiDB into USER_CACHE in batches.
    Runs in background thread after TiDB init. Logs progress.
    Uses batched pagination to avoid loading all _c blobs into memory at once."""
    if not _use_tidb_for("users"):
        return
    tidb = _get_tidb()
    if not tidb:
        return

    t0 = time.time()
    logger.info("[warmup] Starting cache warmup from TiDB (batched)...")

    loaded = 0
    now = time.time()
    try:
        all_users = tidb.tidb_list_all_users(batch_size=_WARMUP_BATCH_SIZE)
    except Exception as e:
        logger.warning(f"[warmup] TiDB bulk load failed: {e}")
        USER_CACHE._warmup_done = True
        return

    if not all_users:
        logger.info("[warmup] No users in TiDB, skipping")
        USER_CACHE._warmup_done = True
        return

    for uid, data in all_users:
        try:
            USER_CACHE.set(uid, data, dirty=False)
            loaded += 1
            uname = (data or {}).get("username")
            if uname:
                _USERNAME_CACHE[str(uname).lower()] = int(uid)
        except Exception as exc:
            logger.warning(f"USER_CACHE warmup failed for uid={uid}: {exc!r}")

    USER_CACHE._warmup_done = True
    USER_CACHE._last_flush_ts = now
    elapsed = time.time() - t0
    if loaded:
        logger.info(f"[warmup] Cache warmed: {loaded} users loaded in {elapsed:.1f}s ({loaded/elapsed:.0f} users/s)")
    else:
        logger.info("[warmup] No users loaded")


def _background_init_slots():
    """Initialize MongoDB slots + TiDB in a background thread.
    Does NOT block first DB access — relay mode is available immediately.
    Uses atomic slot swap to minimize race window with concurrent readers.
    """
    global _storage_slots_initialized
    # Mark slots initialized immediately so relay mode is available
    _storage_slots_initialized = True

    # Initialize TiDB in background
    if TIDB_ENABLED:
        try:
            _check_tidb_available()
        except Exception:
            logger.debug("Background TiDB init failed")
        # Warmup cache from TiDB after connection is ready
        try:
            _warmup_cache_from_tidb()
        except Exception:
            logger.debug("Cache warmup failed")

    # Initialize MongoDB in background — skipped entirely when MONGO_ENABLED=0
    if not MONGO_ENABLED:
        logger.info("MongoDB disabled (MONGO_ENABLED=0) — TiDB is the only store")
        _mongo_ready_event.set()
        return
    try:
        new_slots = _connect_mongo_slots()
        for slot in _mongo_slots:
            try:
                if slot.get("client"):
                    slot["client"].close()
            except Exception as e:
                logger.warning("Exception: %s", str(e))
        with _mongo_slots_lock:
            _mongo_slots[:] = new_slots
        _sync_compat_handles()
        _sync_storage_registry(force=True)
        # Start background slot recovery
        if not _slot_recovery_running:
            threading.Thread(target=_slot_recovery_loop, daemon=True, name="slot-recovery").start()
    except Exception:
        logger.exception("Background MongoDB init failed")
    finally:
        _mongo_ready_event.set()


# ============================================================================
# Janitor - Background cleanup task
# ============================================================================
class Janitor:
    """Background cleanup task for database maintenance."""
    
    def __init__(self):
        self._task = None
        self._running = False
        self._stop_event = asyncio.Event()
    
    async def start(self):
        """Start the janitor background task."""
        if self._running:
            return
        self._running = True
        self._stop_event.clear()
        self._task = asyncio.create_task(self._cleanup_loop())
        logger.info("Janitor started")
    
    async def stop(self):
        """Stop the janitor background task."""
        if not self._running:
            return
        self._running = False
        self._stop_event.set()
        if self._task:
            self._task.cancel()
            try:
                await self._task
            except asyncio.CancelledError:
                logger.warning("CancelledError in stop", exc_info=True)
        logger.info("Janitor stopped")
    
    async def _cleanup_loop(self):
        """Main cleanup loop."""
        consecutive_errors = 0
        max_consecutive_errors = 10
        
        while self._running and not self._stop_event.is_set():
            try:
                # Perform cleanup tasks
                await self._run_cleanup_tasks()
                
                # Reset consecutive errors on successful iteration
                consecutive_errors = 0
                
                # Sleep for 5 minutes between cleanup cycles
                await asyncio.sleep(300)
                
            except asyncio.CancelledError:
                break
            except Exception as exc:
                consecutive_errors += 1
                logger.error("Janitor cleanup error", exc_info=True)
                
                # Safety check: if too many consecutive errors, increase sleep time
                if consecutive_errors > max_consecutive_errors:
                    logger.error("Janitor too many consecutive errors (%d), backing off for 5 minutes", consecutive_errors, exc_info=True)
                    await asyncio.sleep(300)
                    consecutive_errors = 0
                else:
                    await asyncio.sleep(60)  # Wait a minute before retrying on error
    
    async def _run_cleanup_tasks(self):
        """Run individual cleanup tasks."""
        try:
            # Clean up old runtime files
            await asyncio.to_thread(_purge_runtime_files)
            
            # NOTE: flush_cache removed - handled by cache_flush_loop in main.py
            # This avoids triple-redundant flush paths consuming RU
            
            # Refresh storage slots periodically
            await asyncio.to_thread(refresh_storage_slots)
            
            # Evict stale TiDB data hashes (prevent unbounded memory growth)
            try:
                await asyncio.to_thread(tidb_evict_stale_hashes)
            except Exception:
                logger.warning("Janitor TiDB evict stale hashes failed", exc_info=True)

            # Run auto-heal routines
            try:
                healed = await asyncio.to_thread(auto_heal)
                if any(v for v in healed.values()):
                    logger.info(f"Janitor auto-heal summary: {healed}")
            except Exception as exc:
                logger.debug(f"Auto-heal failed: {exc}")

        except Exception as exc:
            logger.error("Cleanup task error", exc_info=True)


# ============================================================================
# ADVANCED DB SYSTEM — Observability, Metrics, Circuit Breaker
# ============================================================================

class _CircuitBreaker:
    """Per-slot circuit breaker. When a slot fails N times in a window,
    skip it for cooldown_seconds. Prevents cascading failures."""

    def __init__(self, threshold: int = 5, cooldown: float = 30.0, window: float = 60.0):
        self._threshold = threshold
        self._cooldown = cooldown
        self._window = window
        self._failures: dict[str, list[float]] = {}
        self._open_until: dict[str, float] = {}
        self._lock = threading.Lock()

    def allow(self, key: str) -> bool:
        """Return True if the slot is allowed to be used."""
        with self._lock:
            now = time.time()
            until = self._open_until.get(key, 0)
            if until > now:
                return False
            return True

    def record_success(self, key: str) -> None:
        with self._lock:
            self._failures.pop(key, None)
            self._open_until.pop(key, None)

    def record_failure(self, key: str) -> None:
        with self._lock:
            now = time.time()
            failures = self._failures.setdefault(key, [])
            failures.append(now)
            cutoff = now - self._window
            while failures and failures[0] < cutoff:
                failures.pop(0)
            if len(failures) >= self._threshold:
                self._open_until[key] = now + self._cooldown
                logger.warning(
                    f"Circuit breaker OPENED for {key} "
                    f"({len(failures)} failures in {self._window}s, "
                    f"cooldown {self._cooldown}s)"
                )

    def status(self) -> dict:
        with self._lock:
            now = time.time()
            return {
                key: {
                    "failures": len([f for f in self._failures.get(key, []) if f > now - self._window]),
                    "open_until": self._open_until.get(key, 0),
                    "is_open": self._open_until.get(key, 0) > now,
                }
                for key in set(list(self._failures.keys()) + list(self._open_until.keys()))
            }

    def reset(self, key: str) -> None:
        with self._lock:
            self._failures.pop(key, None)
            self._open_until.pop(key, None)


_circuit_breaker = _CircuitBreaker(threshold=5, cooldown=30.0, window=60.0)


class _QueryMetrics:
    """Lightweight query metrics collector. Per-slot counters for ops,
    errors, latencies. P99 latency tracked with reservoir sampling."""

    def __init__(self, reservoir_size: int = 256):
        self._ops: dict[str, int] = {}
        self._errors: dict[str, int] = {}
        self._latencies: dict[str, list[float]] = {}
        self._latencies_lock = threading.Lock()
        self._reservoir_size = reservoir_size
        self._meta_lock = threading.Lock()

    def record_op(self, slot: str, op: str, latency_ms: float, success: bool) -> None:
        key = f"{slot}:{op}"
        with self._meta_lock:
            self._ops[key] = self._ops.get(key, 0) + 1
            if not success:
                self._errors[key] = self._errors.get(key, 0) + 1
        with self._latencies_lock:
            samples = self._latencies.setdefault(key, [])
            if len(samples) < self._reservoir_size:
                samples.append(latency_ms)
            else:
                # Reservoir sampling
                idx = int(time.time() * 1_000_000) % self._reservoir_size
                samples[idx] = latency_ms

    def summary(self) -> dict:
        with self._meta_lock:
            ops = dict(self._ops)
            errors = dict(self._errors)
        with self._latencies_lock:
            latencies = {k: list(v) for k, v in self._latencies.items()}
        result = {}
        for key in ops:
            samples = sorted(latencies.get(key, []))
            n = len(samples)
            p50 = samples[n // 2] if n else 0
            p95 = samples[int(n * 0.95)] if n else 0
            p99 = samples[int(n * 0.99)] if n else 0
            result[key] = {
                "ops": ops[key],
                "errors": errors.get(key, 0),
                "error_rate": f"{(errors.get(key, 0) / ops[key] * 100):.1f}%" if ops[key] else "0%",
                "p50_ms": f"{p50:.1f}",
                "p95_ms": f"{p95:.1f}",
                "p99_ms": f"{p99:.1f}",
            }
        return result

    def reset(self) -> None:
        with self._meta_lock:
            self._ops.clear()
            self._errors.clear()
        with self._latencies_lock:
            self._latencies.clear()


_query_metrics = _QueryMetrics()


def get_db_metrics() -> dict:
    """Get full database health summary: metrics, circuit breaker, slot status."""
    slot_status = []
    for slot in _mongo_slots:
        slot_status.append({
            "slot_id": slot.get("slot_id"),
            "category": _slot_category(slot),
            "ok": slot.get("ok", False),
            "full": slot.get("full", False),
            "write_enabled": slot.get("write_enabled", True),
            "usage_percent": slot.get("usage_percent", 0),
            "usage_bytes": slot.get("usage_bytes", 0),
            "error": slot.get("error", "")[:100],
        })
    return {
        "metrics": _query_metrics.summary(),
        "circuit_breaker": _circuit_breaker.status(),
        "slots": slot_status,
        "cache": {
            "users": len(USER_CACHE),
            "settings": len(_SETTINGS_CACHE) if hasattr(_SETTINGS_CACHE, "__len__") else 0,
            "leaderboard": len(_LEADERBOARD_CACHE) if hasattr(_LEADERBOARD_CACHE, "__len__") else 0,
        },
        "tidb": {
            "enabled": TIDB_ENABLED,
            "available": _tidb_available,
            "priority": _tidb_priority() if _use_tidb() else "mongo_only",
        },
    }


def reset_db_metrics() -> None:
    """Reset query metrics counters."""
    _query_metrics.reset()


def with_circuit_breaker(slot_key: str):
    """Decorator: wrap a function in circuit-breaker check. Skips call
    if breaker is open; otherwise records success/failure after."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if not _circuit_breaker.allow(slot_key):
                return None
            t0 = time.time()
            try:
                result = func(*args, **kwargs)
                _circuit_breaker.record_success(slot_key)
                _query_metrics.record_op(
                    slot_key, func.__name__, (time.time() - t0) * 1000, True
                )
                return result
            except Exception as exc:
                _circuit_breaker.record_failure(slot_key)
                _query_metrics.record_op(
                    slot_key, func.__name__, (time.time() - t0) * 1000, False
                )
                raise
        return wrapper
    return decorator


