logger = get_logger(__name__)


# ── Group settings cache ─────────────────────────────────────────────────────
# get_group_settings(chat_id) is called for every group command.
# Cache the parsed JSON in memory for 5 minutes (or until invalidation).
_GROUP_SETTINGS_CACHE: dict[int, tuple[float, dict]] = {}
_GROUP_SETTINGS_TTL = 300.0
_GROUP_SETTINGS_MAX = 20_000
_group_settings_lock = threading.Lock()


def get_cached_group_settings(chat_id: int, fetcher: Callable[[int], dict]) -> dict:
    """
    Returns group settings from cache if fresh, else calls `fetcher(chat_id)`
    and caches the result. Use to wrap get_group_settings().
    """
    now = time.time()
    cached = _GROUP_SETTINGS_CACHE.get(chat_id)
    if cached is not None:
        ts, val = cached
        if now - ts < _GROUP_SETTINGS_TTL:
            return val
    try:
        val = fetcher(chat_id) or {}
    except Exception:
        val = {}
    if not isinstance(val, dict):
        val = {}
    with _group_settings_lock:
        if len(_GROUP_SETTINGS_CACHE) >= _GROUP_SETTINGS_MAX:
            sorted_keys = sorted(_GROUP_SETTINGS_CACHE, key=lambda k: _GROUP_SETTINGS_CACHE[k][0])
            for k in sorted_keys[:_GROUP_SETTINGS_MAX // 4]:
                _GROUP_SETTINGS_CACHE.pop(k, None)
        _GROUP_SETTINGS_CACHE[chat_id] = (now, val)
    return val


def invalidate_group_settings(chat_id: int) -> None:
    """Call after /settitle /setabuse /authadmin /deauthadmin /warn etc."""
    _GROUP_SETTINGS_CACHE.pop(chat_id, None)


# ── Auth admin cache ──────────────────────────────────────────────────────────
_AUTH_ADMINS_CACHE: dict[int, tuple[float, list]] = {}
_AUTH_ADMINS_TTL = 300.0
_auth_admins_lock = threading.Lock()


def get_cached_auth_admins(chat_id: int, fetcher: Callable[[int], list]) -> list:
    now = time.time()
    cached = _AUTH_ADMINS_CACHE.get(chat_id)
    if cached is not None and now - cached[0] < _AUTH_ADMINS_TTL:
        return cached[1]
    try:
        val = fetcher(chat_id) or []
    except Exception:
        val = []
    if not isinstance(val, list):
        val = []
    with _auth_admins_lock:
        if len(_AUTH_ADMINS_CACHE) >= 20_000:
            sorted_keys = sorted(_AUTH_ADMINS_CACHE, key=lambda k: _AUTH_ADMINS_CACHE[k][0])
            for k in sorted_keys[:5_000]:
                _AUTH_ADMINS_CACHE.pop(k, None)
        _AUTH_ADMINS_CACHE[chat_id] = (now, val)
    return val


def invalidate_auth_admins(chat_id: int) -> None:
    _AUTH_ADMINS_CACHE.pop(chat_id, None)


# ── Fun commands list cache ───────────────────────────────────────────────────
# truths_list, dares_list, puzzles_list, music_list, guide_text, minigames_text
# are read on /truth /dare /puzzle /music /guide /minigames. Cache 10 minutes.
_FUN_LISTS_CACHE: dict[str, tuple[float, str]] = {}
_FUN_LISTS_TTL = 600.0


def get_cached_fun_list(key: str, default: str) -> str:
    """Read a fun-command setting with 10-min cache."""
    now = time.time()
    cached = _FUN_LISTS_CACHE.get(key)
    if cached is not None and now - cached[0] < _FUN_LISTS_TTL:
        return cached[1]
    try:
        val = get_setting(key, default) or default
    except Exception:
        val = default
    val = str(val).strip()
    if not val:
        val = default
    if not val:
        return default
    _FUN_LISTS_CACHE[key] = (now, val)
    return val


def invalidate_fun_list(key: str) -> None:
    _FUN_LISTS_CACHE.pop(key, None)


# ── Warn data cache ───────────────────────────────────────────────────────────
_WARN_DATA_CACHE: dict[int, tuple[float, dict]] = {}
_WARN_DATA_TTL = 30.0  # 30s — warns are short-lived
_warn_data_lock = threading.Lock()


def get_cached_warn_data(chat_id: int, fetcher: Callable[[int], dict]) -> dict:
    now = time.time()
    cached = _WARN_DATA_CACHE.get(chat_id)
    if cached is not None and now - cached[0] < _WARN_DATA_TTL:
        return cached[1]
    try:
        val = fetcher(chat_id) or {"count": 0, "history": []}
    except Exception:
        val = {"count": 0, "history": []}
    with _warn_data_lock:
        if len(_WARN_DATA_CACHE) >= 10_000:
            sorted_keys = sorted(_WARN_DATA_CACHE, key=lambda k: _WARN_DATA_CACHE[k][0])
            for k in sorted_keys[:2_500]:
                _WARN_DATA_CACHE.pop(k, None)
        _WARN_DATA_CACHE[chat_id] = (now, val)
    return val


def invalidate_warn_data(chat_id: int) -> None:
    _WARN_DATA_CACHE.pop(chat_id, None)


# ── Settings write coalescer ─────────────────────────────────────────────────
# When save_setting() is called multiple times for the same key in a short
# window, coalesce them into ONE actual DB write. The latest value wins.
# Saves 50-90% of repeated saves.
_PENDING_WRITES: dict[str, tuple[float, Any]] = {}
_PENDING_WRITES_LOCK = threading.Lock()
_COALESCE_WINDOW = 1.0  # seconds — collapse saves within this window
_writer_task: Optional[asyncio.Task] = None
_writer_thread: Optional[threading.Thread] = None
_writer_running = False


def _coalesced_writer_loop():
    """Background thread that flushes coalesced writes."""
    global _writer_running
    _writer_running = True
    while _writer_running:
        time.sleep(0.5)
        now = time.time()
        to_write = []
        with _PENDING_WRITES_LOCK:
            for key, (ts, value) in list(_PENDING_WRITES.items()):
                if now - ts >= _COALESCE_WINDOW:
                    to_write.append((key, value))
                    del _PENDING_WRITES[key]
        for key, value in to_write:
            try:
                save_setting(key, value)
            except Exception as exc:
                logger.debug(f"coalesced write {key} failed: {exc}")


def start_coalesced_writer() -> None:
    """Start the background coalesced-writer thread (idempotent)."""
    global _writer_thread
    if _writer_thread is not None and _writer_thread.is_alive():
        return
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            t = threading.Thread(target=_coalesced_writer_loop, daemon=True, name="db-coalesce")
            t.start()
            _writer_thread = t
            logger.info("✓ Started DB coalesced-writer thread")
    except Exception as exc:
        logger.debug(f"start_coalesced_writer: {exc}")


def stop_coalesced_writer() -> None:
    global _writer_running
    _writer_running = False


# ── Stats ─────────────────────────────────────────────────────────────────────
def db_optimize_stats() -> dict:
    return {
        "group_settings_cache": len(_GROUP_SETTINGS_CACHE),
        "auth_admins_cache": len(_AUTH_ADMINS_CACHE),
        "fun_lists_cache": len(_FUN_LISTS_CACHE),
        "warn_data_cache": len(_WARN_DATA_CACHE),
        "pending_writes": len(_PENDING_WRITES),
    }

# ═══ MODULE: utils.cache ═══

import time
import threading
from collections import OrderedDict

class TTLLRUCache:
    __slots__ = ("_data", "_ttl", "_maxsize", "_lock")

    def __init__(self, maxsize: int = 10_000, ttl: float = 300.0):
        self._data: OrderedDict[int, tuple[float, object]] = OrderedDict()
        self._ttl = ttl
        self._maxsize = maxsize
        self._lock = threading.Lock()

    def _evict_expired(self):
        now = time.time()
        stale = [k for k, (ts, _) in self._data.items() if now - ts > self._ttl]
        for k in stale:
            del self._data[k]

    def get(self, key: int) -> object | None:
        with self._lock:
            self._evict_expired()
            entry = self._data.get(key)
            if entry is None:
                return None
            self._data.move_to_end(key)
            return entry[1]

    def set(self, key: int, value: object):
        with self._lock:
            self._evict_expired()
            self._data[key] = (time.time(), value)
            self._data.move_to_end(key)
            while len(self._data) > self._maxsize:
                self._data.popitem(last=False)

    def delete(self, key: int):
        with self._lock:
            self._data.pop(key, None)

    def clear(self):
        with self._lock:
            self._data.clear()

    @property
    def size(self) -> int:
        with self._lock:
            self._evict_expired()
            return len(self._data)

