_action_cache = TTLLRUCache(maxsize=50_000, ttl=120.0)
_cache_lock = threading.Lock()

# =========================================
# PER-USER LOCKS (thread-safe, NOT async)
# =========================================

_user_locks_cache = TTLLRUCache(maxsize=100_000, ttl=3600.0)
_lock_registry = threading.Lock()

def _get_user_lock(uid: int) -> asyncio.Lock:
    """Get or create a per-user asyncio.Lock (safe for async use)."""
    with _lock_registry:
        lock = _user_locks_cache.get(uid)
        if lock is None:
            lock = asyncio.Lock()
            _user_locks_cache.set(uid, lock)
        return lock


def _command_from_update(update: Update) -> str:
    msg = update.effective_message
    if not msg:
        return ""
    text = (msg.text or msg.caption or "").strip()
    if not text.startswith("/"):
        return ""
    return text.lstrip("/").split()[0].split("@")[0].lower()


def is_farm_protected_command(cmd: str) -> bool:
    return (cmd or "").lower() in FARM_PROTECTED_COMMANDS


def _webapp_url() -> str:
    url = VERIFY_WEBAPP_URL
    if not TURNSTILE_SITE_KEY:
        return url
    parts = urlsplit(url)
    query = dict(parse_qsl(parts.query, keep_blank_values=True))
    query.setdefault("site_key", TURNSTILE_SITE_KEY)
    return urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(query), parts.fragment))


def _web_verification_configured() -> bool:
    return bool(VERIFY_WEBAPP_URL and TURNSTILE_SITE_KEY and CLOUDFLARE_SECRET_KEY)

