# =========================================
# DM VERIFICATION (ONE-TIME, PERMANENT)
# =========================================

# Fast in-memory set — checked BEFORE DB/cache to prevent repeated nagging.
# Once user is verified, they stay in this set for the bot's lifetime.
_dm_verified_cache: set[int] = set()
# Rate-limit: track last nag time per user (seconds) to avoid spam.
_dm_nag_cooldown = TTLLRUCache(maxsize=100_000, ttl=300.0)
_DM_NAG_COOLDOWN_SECS = 300  # 5 min between nag messages


async def mark_dm_verified(uid: int) -> None:
    """Permanently mark user as DM-verified. Call when they open DM."""
    uid = int(uid)
    if uid in _dm_verified_cache:
        return  # Already verified — skip DB write
    _dm_verified_cache.add(uid)
    await asyncio.to_thread(update_user_atomic, uid, set_fields={"dm_verified": True})


async def has_dm_verified(uid: int) -> bool:
    """Check if user has opened DM at least once.
    Fast in-memory check first, falls back to DB/cache."""
    uid = int(uid)
    if uid in _dm_verified_cache:
        return True
    data = await asyncio.to_thread(get_user, uid) or {}
    if bool(data.get("dm_verified", False)):
        _dm_verified_cache.add(uid)
        return True
    return False


async def dm_verification_guard(
    update: Update, ctx: ContextTypes.DEFAULT_TYPE, uid: int
) -> bool:
    """
    Returns True (blocked) if user hasn't opened DM.
    Sends a button prompting them to open DM (rate-limited to once per 5 min).
    """
    if await has_dm_verified(uid):
        return False
    msg = update.effective_message
    if not msg:
        return True

    # Rate-limit: don't spam the nag message
    now = time.time()
    last = _dm_nag_cooldown.get(int(uid)) or 0
    if now - last < _DM_NAG_COOLDOWN_SECS:
        return True  # still blocked, but don't send another message

    _dm_nag_cooldown.set(int(uid), now)
    kb = [[InlineKeyboardButton(
        "✅ Open DM",
        url=f"https://t.me/{BOT_USERNAME}?start=verify"
    )]]
    await msg.reply_html(
        DM_GATE_MSG, reply_markup=InlineKeyboardMarkup(kb)
    )
    return True

# =========================================
# BOT FARMING DETECTION (scoring only — no external block)
# =========================================

def _get_recent_timestamps_fast(uid: int, now: float) -> list[float]:
    with _cache_lock:
        mem = _action_cache.get(uid) or []
        mem = [t for t in mem if now - t <= ACTION_WINDOW_SECONDS]
        _action_cache.set(uid, mem)
        return list(mem)


def _timing_variance_score(all_ts: list[float]) -> tuple[int, str]:
    if len(all_ts) < TIMING_VAR_MIN_INTERVALS + 1:
        return 0, ""
    intervals = [all_ts[i+1] - all_ts[i] for i in range(len(all_ts)-1)]
    mean = sum(intervals) / len(intervals)
    variance = sum((x - mean)**2 for x in intervals) / len(intervals)
    std_dev = math.sqrt(variance)
    if std_dev < TIMING_VAR_BOT_THRESHOLD and mean < TIMING_VAR_MEAN_BOT:
        return 40, f"machine-like timing (std={std_dev:.2f}s mean={mean:.2f}s)"
    elif std_dev < TIMING_VAR_BOT_THRESHOLD:
        return 15, f"uniform timing (std={std_dev:.2f}s)"
    elif mean < TIMING_VAR_MEAN_BOT:
        return 8, ""
    return 0, ""


def _monotony_score(data: dict, now: float) -> tuple[int, str]:
    recent = [
        e for e in data.get("recent_commands", [])
        if isinstance(e, (list, tuple)) and len(e) >= 2
        and now - float(e[1]) <= 300
    ]
    if len(recent) < MONOTONY_WINDOW:
        return 0, ""
    last_n = recent[-MONOTONY_WINDOW:]
    cmd_counts: dict[str, int] = {}
    for entry in last_n:
        cmd = str(entry[0])
        cmd_counts[cmd] = cmd_counts.get(cmd, 0) + 1
    top_cmd, top_count = max(cmd_counts.items(), key=lambda x: x[1])
    ratio = top_count / len(last_n)
    if ratio >= MONOTONY_RATIO_BOT:
        return 30, f"{int(ratio*100)}% same command '/{top_cmd}'"
    if ratio >= 0.70:
        return 12, f"repetitive '/{top_cmd}' ({int(ratio*100)}%)"
    return 0, ""


def _decay_score(data: dict, now: float) -> int:
    last_decay = float(data.get("last_score_decay", 0))
    score = int(data.get("suspicion_score", 0))
    if score <= 0 or last_decay <= 0:
        data["last_score_decay"] = now
        return score
    elapsed_minutes = (now - last_decay) / 60
    decay = int(elapsed_minutes / 10) * 5
    if decay > 0:
        score = max(0, score - decay)
        data["suspicion_score"] = score
        data["last_score_decay"] = now
    return score


def _new_account_score(data: dict, now: float) -> tuple[int, str]:
    acct_created = float(data.get("account_created_at", 0))
    if acct_created <= 0:
        return 0, ""
    age_days = (now - acct_created) / 86400
    if age_days < 1:
        return 15, "account < 1 day old"
    if age_days < 3:
        return 8, "account < 3 days old"
    if age_days < 7:
        return 4, "account < 7 days old"
    return 0, ""


async def detect_bot_farming(uid: int, cmd: str = "") -> bool:
    """
    Returns True if suspicion score >= SCORE_TRIGGER.
    Purely informational — does NOT block anyone (DM gate does that).
    Used only to alert owner of suspicious accounts.
    """
    now = time.time()
    async with _get_user_lock(uid):
        data = await asyncio.to_thread(get_user, uid) or {}
        data = _ensure_user(data)

        try:
            premium = await asyncio.to_thread(_is_prem, uid)
        except Exception as e:
            logger.debug(f"[antibot] Premium check failed for {uid}: {e}")
            premium = False
        multiplier = 0.5 if premium else 1.0

        mem_ts = _get_recent_timestamps_fast(uid, now)
        db_ts  = [float(t) for t in data.get("action_timestamps", [])
                  if now - float(t) <= ACTION_WINDOW_SECONDS]
        all_ts = sorted(set(mem_ts + db_ts + [now]))
        data["action_timestamps"] = all_ts
        # Persist timestamps back to action cache so next call can score them
        with _cache_lock:
            _action_cache.set(uid, all_ts)

        score = _decay_score(data, now)
        reasons: list[str] = []

        if len(all_ts) >= MAX_ACTIONS_PER_MINUTE:
            score += int(25 * multiplier)
            reasons.append(f"{len(all_ts)} cmds/60s")

        burst_ts = [t for t in all_ts if now - t <= BURST_WINDOW_SECONDS]
        if len(burst_ts) >= MAX_BURST_ACTIONS:
            score += int(15 * multiplier)
            reasons.append(f"{len(burst_ts)} burst/{BURST_WINDOW_SECONDS}s")

        # Spam detection: very rapid consecutive commands at exact same second
        if len(all_ts) >= 4:
            same_second_count = sum(1 for i in range(1, len(all_ts)) if abs(all_ts[i] - all_ts[i-1]) < 1.0)
            if same_second_count >= 4:
                score += int(20 * multiplier)
                reasons.append(f"rapid spam: {same_second_count} cmds < 1s apart")

        tv_pts, tv_reason = _timing_variance_score(all_ts)
        if tv_pts:
            score += int(tv_pts * multiplier)
            if tv_reason:
                reasons.append(tv_reason)

        if cmd:
            cmds = data.get("recent_commands", [])
            cmds = [e for e in cmds if isinstance(e,(list,tuple)) and now-float(e[1])<=600]
            cmds.append([cmd, now])
            data["recent_commands"] = cmds[-50:]
        mono_pts, mono_reason = _monotony_score(data, now)
        if mono_pts:
            score += int(mono_pts * multiplier)
            if mono_reason:
                reasons.append(mono_reason)

        if data.get("flagged_at", 0) > 0:
            score += int(20 * multiplier)
            reasons.append(f"{CAPTURE_VERIFY_THRESHOLD}+ captures/h")

        # New account detection
        na_pts, na_reason = _new_account_score(data, now)
        if na_pts:
            score += int(na_pts * multiplier)
            if na_reason:
                reasons.append(na_reason)

        score = min(100, score)

        # ── Trust score multiplier ────────────────────────────────────────
        trust = int(data.get("trust_score", 0) or 0)
        if trust >= 50:
            trust_mult = max(0.1, 1.0 - trust / 100)
            effective_score = int(score * trust_mult)
            if effective_score < score:
                reasons.append(f"trust({trust}) reduced score {score}→{effective_score}")
            score = effective_score

        old_score = int(data.get("suspicion_score", 0) or 0)
        data["suspicion_score"] = score
        reason_str = "; ".join(reasons) if reasons else ""
        old_trust = int(data.get("trust_score", 0) or 0)
        updates: dict = {}
        if score != old_score:
            updates["suspicion_score"] = score
        if reason_str:
            updates["suspicious_reason"] = reason_str
        if data.get("recent_commands") is not None:
            updates["recent_commands"] = data["recent_commands"]
        # Always persist action_timestamps so botscore_cmd and next call can see them
        if all_ts:
            updates["action_timestamps"] = all_ts

        # If flagged, decrease trust
        if score >= SCORE_TRIGGER and trust > 0:
            trust = max(0, trust - 5)
            if trust != old_trust:
                updates["trust_score"] = trust
            logger.info("[AntiBot] Trust decreased uid=%s → %s", uid, trust)
        elif score >= SCORE_SOFT_WARN and trust > 0:
            trust = max(0, trust - 2)
            if trust != old_trust:
                updates["trust_score"] = trust

        if updates:
            await asyncio.to_thread(update_user_atomic, uid, set_fields=updates)
            USER_CACHE.remove(uid)
    if score >= SCORE_TRIGGER:
        logger.info("[AntiBot] HIGH uid=%s score=%s: %s", uid, score, reason_str)
        return True
    if score >= SCORE_SOFT_WARN:
        reason = "; ".join(reasons) if reasons else "unusual activity"
        logger.info("[AntiBot] WARN uid=%s score=%s: %s", uid, score, reason)
    return False


async def botscore_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Debug: show current bot detection score."""
    user = update.effective_user
    if not user:
        return
    data = await asyncio.to_thread(get_user, user.id) or {}
    data = _ensure_user(data)
    score = int(data.get("suspicion_score", 0) or 0)
    flagged = float(data.get("flagged_at", 0) or 0)
    trust = int(data.get("trust_score", 0) or 0)
    immune_until = float(data.get("web_verified_until", 0) or 0)
    now = time.time()
    immune = immune_until > now
    action_ts = data.get("action_timestamps", [])
    recent = [t for t in action_ts if now - float(t) <= 60]
    text = (
        f"🤖 <b>Bot Score Debug</b>\n\n"
        f"Score: <b>{score}</b> / 100\n"
        f"Trigger: <b>{SCORE_TRIGGER}</b>\n"
        f"Flagged: <b>{flagged}</b>\n"
        f"Trust: <b>{trust}</b>\n"
        f"Web Immune: <b>{immune}</b> (until {immune_until:.0f})\n"
        f"Actions (60s): <b>{len(recent)}</b>\n"
        f"Timestamps: <code>{action_ts[-5:]}</code>\n\n"
        f"{'🔴 TRIGGERED' if score >= SCORE_TRIGGER else '🟢 CLEAR'}"
    )
    await update.effective_message.reply_html(text)


async def _maybe_alert_owner_static(uid: int, score: int, reason: str) -> None:
    """Alert owner when bot score is high."""
    try:
        text = (
            f"🚨 <b>Bot Detection Alert</b>\n\n"
            f"👤 User: <code>{uid}</code>\n"
            f"📊 Score: <b>{score}/100</b>\n"
            f"🔎 Reason: <i>{html.escape(reason)}</i>\n\n"
            f"<a href='tg://user?id={uid}'>View Profile</a>"
        )
        async with httpx.AsyncClient() as client:
            await client.post(
                f"{TG_BASE_URL}{_bt}/sendMessage",
                json={"chat_id": OWNER_ID, "text": text, "parse_mode": "HTML"},
            )
    except Exception:
        logger.warning("[antibot] Failed to alert owner", exc_info=True)


async def get_suspicious_reason(uid: int) -> str:
    data = await asyncio.to_thread(get_user, uid) or {}
    return str(data.get("suspicious_reason") or "").strip()

# =========================================
# ACTION RECORDING
# =========================================

async def record_user_action(uid: int, chat_id: int = None, account_created_ts: int = None) -> None:
    """Record a protected game action. Timestamps kept in memory only — no DB writes."""
    now = time.time()

    with _cache_lock:
        mem = _action_cache.get(uid) or []
        mem = [t for t in mem if now - t <= ACTION_WINDOW_SECONDS]
        mem.append(now)
        _action_cache.set(uid, mem)


async def record_successful_farm_action(uid: int, chat_id: int = None, cmd: str = "") -> None:
    """
    Record anti-farm signals only after a protected command succeeds.
    Failed replies, cooldown denials, and invalid targets do not raise the score.
    """
    cmd = (cmd or "").lower()
    if cmd and not is_farm_protected_command(cmd):
        return
    try:
        await record_user_action(uid, chat_id=chat_id)
        await detect_bot_farming(uid, cmd=cmd)
    except Exception as exc:
        logger.debug("Failed to record successful farm action uid=%s cmd=%s: %s", uid, cmd, exc)


def _capture_trap_threshold(score: int) -> int:
    """Smart trap: the higher the suspicion score, the fewer tries before the
    user falls into the web-verify trap. Score>=SCORE_TRIGGER → 4 tries,
    otherwise scales down from the default CAPTURE_VERIFY_THRESHOLD."""
    if score >= 90:
        return 2
    if score >= SCORE_TRIGGER:
        return 4
    if score >= SCORE_SOFT_WARN:
        return max(4, int(CAPTURE_VERIFY_THRESHOLD * 0.5))
    return CAPTURE_VERIFY_THRESHOLD


async def record_capture_action(uid: int, chat_id: int = None, cmd: str = "capt") -> None:
    """Call after every successful capture command."""
    now = time.time()
    try:
        async with _get_user_lock(uid):
            data = await asyncio.to_thread(get_user, uid) or {}
            data = _ensure_user(data)
            original = dict(data)

            if now - data.get("last_capture_reset", 0) > CAPTURE_VERIFY_WINDOW_SECS:
                data["capture_count"] = 0
                data["last_capture_reset"] = now
                data["flagged_at"] = 0

            data["capture_count"] = data.get("capture_count", 0) + 1

            if not data.get("flagged_at", 0) and data["capture_count"] >= _capture_trap_threshold(
                int(data.get("suspicion_score", 0) or 0)
            ):
                data["flagged_at"] = now
                logger.info("Capture flag set for uid=%s (count=%s)", uid, data["capture_count"])

            changes = {k: v for k, v in data.items() if k not in original or v != original[k]}
            if changes:
                await asyncio.to_thread(update_user_atomic, uid, set_fields=changes)
    except Exception as exc:
        logger.debug("Failed to record capture action uid=%s: %s", uid, exc)
    # Record action timestamps (lightweight) — skip detect_bot_farming here
    # since verify_guard already calls it before the command runs.
    try:
        await record_user_action(uid, chat_id=chat_id)
    except Exception:
        pass


async def record_daily_gift_attempt(uid: int) -> None:
    """Compatibility wrapper: record only a successful /dailygift claim."""
    await record_successful_farm_action(uid, None, "dailygift")

