async def _maybe_alert_owner(ctx: ContextTypes.DEFAULT_TYPE, uid: int) -> None:
    """Alert owner if user has been flagged as bot many times."""
    try:
        data = await asyncio.to_thread(get_user, uid) or {}
        data = _ensure_user(data)
        count = data.get("bot_alert_count", 0)
        alerted = data.get("owner_alerted", False)
        reason = data.get("suspicious_reason", "")

        if count >= OWNER_ALERT_THRESHOLD and not alerted:
            await asyncio.to_thread(update_user_atomic, uid, set_fields={"owner_alerted": True})
            text = OWNER_ALERT_MSG.format(uid=uid, count=count, reason=html.escape(reason or "unknown"))
            await ctx.bot.send_message(chat_id=OWNER_ID, text=text, parse_mode="HTML")
            logger.info("Owner alerted for repeated suspect uid=%s", uid)
    except Exception as e:
        logger.debug("Owner alert failed: %s", e)

# =========================================
# MAIN GUARD — use in all game commands
# =========================================

async def antibot_verification_guard(
    update: Update, ctx: ContextTypes.DEFAULT_TYPE
) -> bool:
    """
    Main guard for all protected commands.
    DM gate stays one-time. Web CAPTCHA is only for farming-sensitive commands.
    Scoring is recorded by command handlers after a real successful reward/action.
    Returns True=BLOCKED, False=ALLOWED.
    """
    user = update.effective_user
    chat = update.effective_chat
    if not user or not chat:
        return False
    cmd = _command_from_update(update)
    protected = is_farm_protected_command(cmd)

    # NOTE: Bot detection scoring is done AFTER successful actions only
    # (in record_successful_farm_action), not on every attempt.
    # This prevents failed attempts from inflating suspicion scores.

    if chat.type == "private":
        if protected:
            await mark_dm_verified(user.id)
            # Skip in-chat CAPTCHA, rely on web verification only
            return False
        return False

    # Step 1: DM gate
    if not await has_dm_verified(user.id):
        return await dm_verification_guard(update, ctx, user.id)

    if not protected:
        return False

    # Skip in-chat CAPTCHA, rely on web verification only
    return False


async def _background_farm_check(ctx: ContextTypes.DEFAULT_TYPE, uid: int, cmd: str) -> None:
    """Background suspicion check — logs if bot detected, never blocks player."""
    try:
        await detect_bot_farming(uid, cmd=cmd)
    except Exception as e:
        logger.debug("Background farm check error uid=%s: %s", uid, e)

# =========================================
# WEBAPP DATA HANDLER (Cloudflare CAPTCHA result) — v7 REBUILD
# =========================================

_CF_EXPECTED_ACTION = "anyy_web_verify"
_CF_VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify"


async def _owner_verify_notify(context, text: str) -> None:
    """Fire-and-forget diagnostic to the owner. Never raises."""
    try:
        if OWNER_ID:
            await context.bot.send_message(chat_id=OWNER_ID, text=str(text)[:3500])
    except Exception:
        pass


async def handle_webapp_verification(
    update: Update, context: ContextTypes.DEFAULT_TYPE
) -> None:
    """
    Handle WebApp data after Cloudflare CAPTCHA completion (sendData flow).

    The Mini App calls Telegram.WebApp.sendData({action, cf_token}) which the
    bot receives as a service message with web_app_data. Always replies with a
    reason (never a silent/bare failure) and notifies the owner on failure.
    """
    try:
        webapp_data = (update.effective_message.web_app_data
                       if update.effective_message else None)
        if webapp_data is None:
            logger.debug("handle_webapp_verification: no webapp_data")
            return
        raw = webapp_data.data or ""
        logger.info("webapp received data len=%d", len(raw))
        try:
            data = json.loads(raw)
        except Exception as exc:
            logger.warning("webapp JSON parse failed: %r", exc)
            return
        if not isinstance(data, dict):
            logger.warning("webapp data not a dict")
            return
        if data.get("action") != "verify":
            logger.debug("webapp action=%s skipping", data.get("action"))
            return

        user = update.effective_user
        user_id = user.id if user else data.get("user_id")
        if user_id is None:
            logger.warning("webapp verification without user id")
            return
        user_id = int(user_id)

        cf_token = (data.get("cf_token") or "").strip()
        logger.info("webapp verify attempt uid=%s token_len=%s", user_id, len(cf_token))
        ok, reason = await validate_cf_token(cf_token) if cf_token else (False, "missing token")

        if not ok:
            logger.warning("webapp verify FAILED uid=%s reason=%s", user_id, reason)
            await _owner_verify_notify(
                context,
                f"☁️ Verify FAIL uid={user_id}\n"
                f"reason={reason}\n"
                f"sitekey={TURNSTILE_SITE_KEY}\n"
                f"secret^={(CLOUDFLARE_SECRET_KEY or '')[:8]}\n"
                f"url={_webapp_url()}",
            )
            try:
                await context.bot.send_message(
                    chat_id=user_id,
                    text=(
                        "☁️ <b>Verification Did Not Pass</b>\n\n"
                        f"<b>Reason:</b> <code>{html.escape(reason)}</code>\n\n"
                        "⌛ Try tapping the CAPTCHA button once more — tokens expire "
                        "after 5 minutes and can only be used a single time."
                    ),
                    parse_mode="HTML",
                    reply_markup=ReplyKeyboardRemove(),
                )
            except Exception:
                logger.error("Unable to send failure to uid=%s", user_id, exc_info=True)
            return

        logger.info("webapp verify OK uid=%s reason=%s", user_id, reason)
        try:
            await grant_web_verification_immunity(user_id)
        except Exception:
            logger.exception("grant immunity failed for %s (non-fatal)", user_id)
        # Reset capture flags (non-fatal — must never block the success message)
        try:
            async with _get_user_lock(user_id):
                u = await asyncio.to_thread(get_user, user_id) or {}
                u = _ensure_user(u)
                if u.get("flagged_at", 0) > 0:
                    await asyncio.to_thread(update_user_atomic, user_id,
                                            set_fields={"flagged_at": 0, "capture_count": 0})
        except Exception:
            logger.exception("flag reset failed for %s (non-fatal)", user_id)
        try:
            await context.bot.send_message(
                chat_id=user_id,
                text=(
                    "Tʜᴀɴᴋ Yᴏᴜ Sᴏ Mᴜᴄʜ Fᴏʀ Vᴇʀɪғʏɪɴɢ 💕 "
                    "Yᴏᴜ Cᴀɴ Pʟᴀʏ Aɢᴀɪɴ Fʀᴏᴍ Wʜᴇʀᴇ Yᴏᴜ Pᴀᴜsᴇᴅ."
                ),
                parse_mode="HTML",
                reply_markup=ReplyKeyboardRemove(),
            )
        except Exception:
            logger.error("Unexpected error", exc_info=True)
    except Exception as e:
        logger.exception("handle_webapp_verification error: %s", e)
        try:
            if OWNER_ID:
                await context.bot.send_message(
                    chat_id=OWNER_ID,
                    text=f"⚠️ Verify handler error: {e!r}",
                )
        except Exception:
            pass

# =========================================
# GRANT IMMUNITY — kept for API compatibility
# =========================================

def _calc_immunity_hours(lifetime_count: int) -> int:
    if lifetime_count <= 1: return 8
    if lifetime_count <= 3: return 4
    if lifetime_count <= 6: return 2
    return 1

def _is_web_immune(uid: int, data: dict) -> bool:
    now = time.time()
    cached = _immunity_cache.get(uid)
    if cached is not None and cached > now:
        return True
    until = float(data.get("web_verified_until", 0))
    if until > now:
        _immunity_cache.set(uid, until)
        return True
    return False

async def grant_web_verification_immunity(uid: int, hours: int = None) -> None:
    """Grant immunity after passing Cloudflare CAPTCHA."""
    async with _get_user_lock(uid):
        data = await asyncio.to_thread(get_user, uid) or {}
        data = _ensure_user(data)
        lifetime = data.get("web_verify_lifetime", 0)
        if hours is None:
            hours = _calc_immunity_hours(lifetime)
        until = time.time() + hours * 3600
        trust = int(data.get("trust_score", 0) or 0)
        trust = min(100, trust + 15)
        await asyncio.to_thread(
            update_user_atomic, uid,
            inc_fields={"web_verify_lifetime": 1},
            set_fields={
                "web_verified_until": until,
                "suspicious_reason": "",
                "action_timestamps": [],
                "suspicion_score": 0,
                "recent_commands": [],
                "last_score_decay": time.time(),
                "owner_alerted": False,
                "bot_alert_count": 0,
                "flagged_at": 0,
                "capture_count": 0,
                "trust_score": trust,
            }
        )
    _immunity_cache.set(uid, until)
    with _cache_lock:
        _action_cache.delete(uid)
    logger.info("Immunity granted uid=%s for %sh, cache cleaned", uid, hours)

async def validate_cf_token(token: str) -> tuple[bool, str]:
    """Validate Cloudflare Turnstile token server-side. Returns (ok, reason).
    Reason is ALWAYS a non-empty string on failure.
    Tries multiple HTTP backends to survive restricted environments (HF, etc.)."""
    if not CLOUDFLARE_SECRET_KEY:
        return False, "secret_not_configured:CLOUDFLARE_SECRET_KEY is empty"
    if not token:
        return False, "empty_token:no token provided"
    if len(token) > 2048:
        return False, "token_too_long:token exceeds 2048 bytes"
    payload = {"secret": CLOUDFLARE_SECRET_KEY, "response": token}
    last_err = None
    # ── Attempt 0: Cloudflare Worker proxy (bypasses HF outbound blocks) ──
    if CF_PROXY_URL:
        try:
            import urllib.request
            import urllib.parse
            proxy_endpoint = f"{CF_PROXY_URL}/cfp"
            pdata = urllib.parse.urlencode(payload).encode()
            # Route through the worker's generic x-target-host mode: POST to
            # proxy path, header tells worker which domain to forward to.
            preq = urllib.request.Request(
                proxy_endpoint,
                data=pdata,
                headers={
                    "Content-Type": "application/x-www-form-urlencoded",
                    "x-target-host": "challenges.cloudflare.com",
                    "x-forward-path": "/turnstile/v0/siteverify",
                    "x-proxy-key": CF_PROXY_KEY or "",
                },
                method="POST",
            )
            presp = urllib.request.urlopen(preq, timeout=30)
            pbody = presp.read().decode("utf-8", errors="replace")
            import json as _json_parse2
            presult = _json_parse2.loads(pbody)
            logger.info("siteverify [proxy] body: %s", pbody[:500])
            return _evaluate_siteverify(presult)
        except Exception as exc:
            last_err = exc
            logger.warning("siteverify [proxy] failed: %s: %s", type(exc).__name__, exc)
    # ── Attempt 1: stdlib urllib (most portable, no deps) ──
    try:
        import urllib.request
        import urllib.parse
        data = urllib.parse.urlencode(payload).encode()
        req = urllib.request.Request(
            _CF_VERIFY_URL,
            data=data,
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            method="POST",
        )
        resp = urllib.request.urlopen(req, timeout=30)
        body = resp.read().decode("utf-8", errors="replace")
        import json as _json_parse
        result = _json_parse.loads(body)
        logger.info("siteverify [urllib] body: %s", body[:500])
        return _evaluate_siteverify(result)
    except Exception as exc:
        last_err = exc
        logger.warning("siteverify [urllib] failed: %s: %s", type(exc).__name__, exc)
    # ── Attempt 2: httpx ──
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            r = await client.post(
                _CF_VERIFY_URL,
                data=payload,
            )
            logger.info("siteverify [httpx] HTTP %d", r.status_code)
            result = r.json()
            logger.info("siteverify [httpx] body: %s", json.dumps(result, default=str)[:500])
            return _evaluate_siteverify(result)
    except Exception as exc:
        last_err = exc
        logger.warning("siteverify [httpx] failed: %s: %s", type(exc).__name__, exc)
    # ── Attempt 3: requests (sync, run in thread) ──
    try:
        import requests as _req_lib
        r = await asyncio.to_thread(
            lambda: _req_lib.post(
                _CF_VERIFY_URL,
                data=payload,
                timeout=30,
            )
        )
        result = r.json()
        logger.info("siteverify [requests] body: %s", json.dumps(result, default=str)[:500])
        return _evaluate_siteverify(result)
    except Exception as exc:
        last_err = exc
        logger.warning("siteverify [requests] failed: %s: %s", type(exc).__name__, exc)
    # ── All backends failed ──
    # Run a quick connectivity probe to help diagnose
    diag = await _network_diag()
    reason = f"all_backends_failed:last={type(last_err).__name__}:{last_err} | {diag}"
    return False, reason


def _evaluate_siteverify(result: dict) -> tuple[bool, str]:
    """Shared logic to evaluate the siteverify JSON response."""
    if not result.get("success", False):
        codes = result.get("error-codes") or []
        hostname = result.get("hostname") or "unknown"
        action = result.get("action") or "none"
        reason = (
            f"errors={codes} "
            f"hostname={hostname} "
            f"action={action} "
            f"secret^={(CLOUDFLARE_SECRET_KEY or '')[:6]}"
        )
        logger.warning("Cloudflare siteverify FAIL: %s", reason)
        return False, reason
    action = result.get("action")
    if action and action != _CF_EXPECTED_ACTION:
        return False, f"action_mismatch:got={action} expected={_CF_EXPECTED_ACTION}"
    return True, "ok"


async def _network_diag() -> str:
    """Quick connectivity probes to help diagnose blocked environments."""
    parts = []
    # DNS check
    try:
        import socket
        t0 = time.time()
        addr = socket.getaddrinfo("challenges.cloudflare.com", 443, family=socket.AF_INET)
        dns_ms = int((time.time() - t0) * 1000)
        parts.append(f"dns={addr[0][4][0]} ({dns_ms}ms)")
    except Exception as e:
        parts.append(f"dns=FAIL:{e}")
    # TLS handshake check
    try:
        import ssl, socket as _sock
        ctx = ssl.create_default_context()
        t0 = time.time()
        with _sock.create_connection(("challenges.cloudflare.com", 443), timeout=10) as raw:
            with ctx.wrap_socket(raw, server_hostname="challenges.cloudflare.com") as s:
                s.getpeercert()
        tls_ms = int((time.time() - t0) * 1000)
        parts.append(f"tls=OK ({tls_ms}ms)")
    except Exception as e:
        parts.append(f"tls=FAIL:{type(e).__name__}:{e}")
    return " | ".join(parts) if parts else "no_diag"


async def _requires_web_verification(uid: int) -> tuple[bool, str]:
    # Fast path: check immunity cache FIRST — skip DB read entirely
    now = time.time()
    cached = _immunity_cache.get(uid)
    if cached is not None and cached > now:
        return False, ""
    data = await asyncio.to_thread(get_user, uid) or {}
    data = _ensure_user(data)
    if _is_web_immune(uid, data):
        return False, ""
    score = int(data.get("suspicion_score", 0) or 0)
    flagged = float(data.get("flagged_at", 0) or 0) > 0
    if score >= SCORE_TRIGGER or flagged:
        reason = str(data.get("suspicious_reason") or "").strip()
        if flagged and not reason:
            reason = f"{_capture_trap_threshold(score)}+ captures/h"
        return True, reason
    return False, ""


async def _note_web_challenge(uid: int) -> None:
    try:
        await asyncio.to_thread(update_user_atomic, uid, inc_fields={"bot_alert_count": 1})
    except Exception as exc:
        logger.debug("Failed to note web challenge uid=%s: %s", uid, exc)


async def _send_local_captcha(ctx, chat_id: int, uid: int, reason: str = "") -> None:
    """Issue a fully local (network-free) CAPTCHA and store it for the user.
    Uses an image when PIL is available, else a plain-text math question."""
    try:
        caption_extra = ""
        if reason:
            caption_extra += f"\n\n<i>Reason: {html.escape(str(reason)[:100])}</i>"
        if _HAS_PIL_ANYBEST:
            if random.random() < 0.45:
                disp, ans = generate_math_captcha_anybest()
            else:
                text = generate_captcha_text_anybest(random.randint(5, 6))
                disp, ans = text, text
            store_captcha_anybest(uid, ans)
            img = generate_captcha_image_anybest(disp)
            is_img = getattr(img, "name", "").lower().endswith((".png", ".jpg", ".jpeg"))
            caption = (
                "🧩 <b>Please solve the CAPTCHA to continue.</b>\n\n"
                "Type the text you see in the image.\n"
                f"3 chances • expires in {int(_CAPTCHA_TTL_ANYBEST / 60)} min"
            ) + caption_extra
            if is_img:
                await ctx.bot.send_photo(
                    chat_id=chat_id, photo=img, caption=caption, parse_mode="HTML"
                )
            else:
                await ctx.bot.send_document(
                    chat_id=chat_id, document=img, filename="captcha.txt",
                    caption=caption, parse_mode="HTML",
                )
        else:
            disp, ans = generate_math_captcha_anybest()
            store_captcha_anybest(uid, ans)
            await ctx.bot.send_message(
                chat_id=chat_id,
                text=(
                    "🧩 <b>Please solve this to continue:</b>\n\n"
                    f"<code>{html.escape(disp)}</code>\n\n"
                    "Reply with just the answer.\n"
                    f"3 chances • expires in {int(_CAPTCHA_TTL_ANYBEST / 60)} min"
                ) + caption_extra,
                parse_mode="HTML",
            )
        logger.info("issued local captcha uid=%s chat=%s", uid, chat_id)
    except Exception:
        logger.exception("failed to send local captcha uid=%s", uid)

async def web_verification_guard(
    update: Update, ctx: ContextTypes.DEFAULT_TYPE, uid: int = 0, cmd: str = ""
) -> bool:
    """
    Blocks flagged/suspicious users behind a LOCAL in-chat image CAPTCHA.
    Returns True = action blocked (must not continue).
    Auto-skips: DMs, bots, immune users, and users who don't require it.
    """
    try:
        user = update.effective_user
        if not user or user.is_bot:
            return False
        if not uid:
            uid = user.id
        if uid != user.id:
            return False
        chat = update.effective_chat
        if chat and chat.type == "private":
            return False
        req, reason = await _requires_web_verification(uid)
        if not req:
            return False
        now = time.time()
        last = _web_gate_cooldown.get(uid) or 0.0
        if now - last >= 30.0:
            _web_gate_cooldown.set(uid, now)
            kb = [[InlineKeyboardButton(
                "🌐 Oᴘᴇɴ Hᴜᴍᴀɴ Cʜᴇᴄᴋ",
                url=f"https://t.me/{BOT_USERNAME}?start=verify_web",
            )]]
            try:
                await ctx.bot.send_message(
                    chat_id=chat.id,
                    text=(
                        "🥀 Hᴜᴍᴀɴ Cʜᴇᴄᴋ~\n"
                        "Sᴏʟᴠᴇ Tʜᴇ Cᴀᴘᴛᴄʜᴀ ʙᴇʟᴏᴡ.\n\n"
                        "Aғᴛᴇʀ ᴛʜᴀᴛ, ʏᴏᴜ ᴄᴀɴ ᴘʟᴀʏ ᴀɢᴀɪɴ 🌸\n"
                        "∆ Tʜᴇ ᴄᴀᴘᴛᴄʜᴀ ɪs ᴛʜᴇʀᴇ ᴛᴏ Sᴛᴏᴘ Eᴄᴏɴᴏᴍʏ Aʙᴜsᴇ.\n"
                        "Tᴀᴘ ᴛʜᴇ ʙᴜᴛᴛᴏɴ ʙᴇʟᴏᴡ 👇"
                    ),
                    reply_markup=InlineKeyboardMarkup(kb),
                )
            except Exception:
                pass
            await _note_web_challenge(uid)
        return True
    except Exception:
        logger.exception("web_verification_guard error")
        return False

