async def verify_start_command(
    update: Update, context: ContextTypes.DEFAULT_TYPE
) -> None:
    """Handle /verify — test verification or redirect to /start."""
    user = update.effective_user
    chat = update.effective_chat
    if not user:
        return
    msg = update.effective_message
    if not msg:
        return
    # Owner verification test
    if user.id == OWNER_ID:
        # Check verification status
        u = await asyncio.to_thread(get_user, user.id) or {}
        u = _ensure_user(u)
        score = int(u.get("suspicion_score", 0) or 0)
        flagged = float(u.get("flagged_at", 0) or 0) > 0
        is_owner = user.id == OWNER_ID
        await msg.reply_text(
            f"👑 <b>Owner Verification Test</b>\n\n"
            f"Owner ID: {user.id}\n"
            f"Suspicion Score: {score}\n"
            f"Flagged: {'Yes' if flagged else 'No'}\n"
            f"Owner Status: {'✅ Verified' if is_owner else '❌ Not Owner'}\n\n"
            "Use /start to return to bot."
        )
        return
    # Non-owner: open the Cloudflare webapp verifier
    req, _ = await _requires_web_verification(user.id)
    if not req:
        try:
            await msg.reply_text("✅ You are already verified. No CAPTCHA needed.")
        except Exception:
            pass
        return
    if not _web_verification_configured():
        try:
            await msg.reply_html(
                "🌿 <b>Human verification is not ready yet.</b>\n\n"
                "Please ask the bot owner to finish the Cloudflare setup."
            )
        except Exception:
            pass
        return
    kb = [[InlineKeyboardButton(
        "🌐 Open Human Check",
        url=f"https://t.me/{BOT_USERNAME}?start=verify_web",
    )]]
    try:
        await msg.reply_html(
            "🧩 <b>Human verification required</b>\n\n"
            "Tap the button to open the verifier and prove you're not a bot.",
            reply_markup=InlineKeyboardMarkup(kb),
        )
    except Exception:
        pass


async def verify_diag_command(
    update: Update, context: ContextTypes.DEFAULT_TYPE
) -> None:
    """Owner-only /vtest — live diagnostic for the Cloudflare verification setup."""
    user = update.effective_user
    msg = update.effective_message
    if not user or not msg or user.id != OWNER_ID:
        return
    await msg.reply_text(
        "🔍 <b>Checking config…</b>",
        parse_mode="HTML",
    )
    secret = CLOUDFLARE_SECRET_KEY or ""
    lines = [
        f"<b>🌐 Verify Diagnostics</b>\n",
        f"sitekey    = <code>{html.escape(str(TURNSTILE_SITE_KEY))}</code>",
        f"secret{chr(94)}  = <code>{html.escape(secret[:8])}…</code> (len {len(secret)})",
        f"webapp     = <code>{html.escape(str(_webapp_url()))}</code>",
        f"action     = <code>{html.escape(_CF_EXPECTED_ACTION)}</code>",
        f"configured = {_web_verification_configured()}",
        f"expected   = {_CF_VERIFY_URL}",
        f"proxy      = {html.escape(CF_PROXY_URL) if CF_PROXY_URL else '<i>not set (direct only)</i>'}\n",
        f"<i>► Probing Cloudflare siteverify with a dummy token…</i>",
    ]
    await msg.reply_text("\n".join(lines), parse_mode="HTML")
    ok, reason = await validate_cf_token("dummy-probe-token-0000")
    await msg.reply_text(
        f"<b>Probe result:</b> {'✅ reachable (dummy rejected as expected)' if not ok else '⚠️ PROBE PASSED?!'}\n"
        f"<code>{html.escape(reason)}</code>\n\n"
        f"<i>Note: dummy token must give errors=['invalid-input-response'] — "
        f"that proves the secret is valid and the API is reachable.</i>",
        parse_mode="HTML",
    )


