from telegram.error import TelegramError
from telegram.ext import Application
logger = get_logger(__name__)

DAILY_COOLDOWN = 86400
DAILY_REWARD = 1000
PREMIUM_DAILY_REWARD = 2000
DAILY_XP_MIN = 21       # Min XP awarded on /dailygift
DAILY_XP_MAX = 47       # Max XP awarded on /dailygift
REDEEM_MIN_MEMBERS = 100
MSG_COUNT_THRESHOLD = 500
REDEEM_COOLDOWN = 86400
REDEEM_REWARD = 4000
REDEEM_XP_MIN = 21
REDEEM_XP_MAX = 47

# Module-level constant so tests and monitoring can import it
MAX_EMPTY_ITERATIONS = 200  # After this many empty-queue iterations the log worker sleeps longer

def _now() -> int:
    return int(time.time())

def _fmt(seconds: int) -> str:
    seconds = max(0, int(seconds))
    h = seconds // 3600
    m = (seconds % 3600) // 60
    s = seconds % 60
    return f"{h}h {m}m {s}s"

def _support() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton("Support", url=SUPPORT_LINK)]])

chat_history: "OrderedDict[int, deque]" = OrderedDict()
message_counter: dict = {}
user_messages: dict = {}
_history_lock = threading.Lock()

log_queue: deque = deque(maxlen=10000)
_log_lock = threading.Lock()


async def message_tracker(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    chat = update.effective_chat
    msg = update.effective_message
    if not user or not chat or not msg or user.is_bot:
        return

    text = msg.text or msg.caption or ""

    if chat.type != "private":
        # Fast path: lock-free counter increments (atomic for ints/dicts in CPython)
        # The eviction/cap logic only runs at the boundary.
        overflow_needed = False
        chat_id = chat.id
        if len(chat_history) >= MAX_CHAT_HISTORY:
            overflow_needed = True
        # Atomic increments (GIL protects individual dict operations;
        # setdefault eliminates the check-then-set race for user_messages)
        message_counter[chat_id] = message_counter.get(chat_id, 0) + 1
        user_messages.setdefault(chat_id, defaultdict(int))[user.id] += 1
        if text:
            chat_history.setdefault(chat_id, deque(maxlen=50)).append(("user", user.first_name, text))
        chat_history.move_to_end(chat_id)

        # Eviction under lock (only at boundary)
        if overflow_needed:
            with _history_lock:
                if len(chat_history) >= MAX_CHAT_HISTORY:
                    overflow = len(chat_history) - MAX_CHAT_HISTORY + 1
                    for _ in range(min(overflow + 10, len(chat_history))):
                        try:
                            first_chat, _ = chat_history.popitem(last=False)
                        except KeyError:
                            break
                        message_counter.pop(first_chat, None)
                        user_messages.pop(first_chat, None)

    if text and user:
        store_message(chat.id, user.id, "user", text)


def record_bot_reply(chat_id: int, bot_name: str, text: str):
    """Record bot's own reply into the per-user filtered buffer."""
    with _history_lock:
        if chat_id in chat_history:
            chat_history[chat_id].append(("assistant", bot_name, text))
            chat_history.move_to_end(chat_id)
    try:
        store_message(chat_id, 0, "assistant", text)
    except Exception as exc:
        logger.exception(f"buffer_store failed for chat {chat_id}: {exc}")


def add_log(text: str):
    with _log_lock:
        log_queue.append(text)


async def log_worker(app: Application) -> None:
    """Background worker that sends log messages to Telegram group with graceful shutdown."""
    error_count = 0
    max_errors_before_backoff = 10
    consecutive_empty_iterations = 0
    # Use the module-level MAX_EMPTY_ITERATIONS constant (importable by tests)

    # Shutdown event for graceful termination
    shutdown_event = asyncio.Event()

    while not shutdown_event.is_set():
        # Safety check: if queue has been empty for too long, increase sleep time
        with _log_lock:
            queue_empty = not log_queue
        if queue_empty:
            consecutive_empty_iterations += 1
            if consecutive_empty_iterations > MAX_EMPTY_ITERATIONS:
                logger.debug(f"Log worker queue empty for {MAX_EMPTY_ITERATIONS} iterations, sleeping 30s")
                consecutive_empty_iterations = 0
                try:
                    await asyncio.wait_for(shutdown_event.wait(), timeout=30.0)
                    if shutdown_event.is_set():
                        logger.info("Log worker shutdown requested, exiting loop")
                        break
                except asyncio.TimeoutError:
                    logger.debug("Timeout is expected, continue processing")
                continue
        else:
            consecutive_empty_iterations = 0

        try:
            with _log_lock:
                queue_empty = not log_queue
            if queue_empty:
                # Wait with timeout to allow shutdown event check
                try:
                    await asyncio.wait_for(shutdown_event.wait(), timeout=5.0)
                    if shutdown_event.is_set():
                        logger.info("Log worker shutdown requested, exiting loop")
                        break
                except asyncio.TimeoutError:
                    logger.debug("Timeout is expected, continue processing")
                continue

            # If too many errors, back off and reset
            if error_count > max_errors_before_backoff:
                logger.warning(f"High error count ({error_count}) in log worker, backing off for 10 seconds")
                # Wait with timeout to allow shutdown event check
                try:
                    await asyncio.wait_for(shutdown_event.wait(), timeout=10.0)
                    if shutdown_event.is_set():
                        logger.info("Log worker shutdown requested, exiting loop")
                        break
                except asyncio.TimeoutError:
                    logger.debug("Timeout is expected, continue processing")
                error_count = 0

            with _log_lock:
                text = log_queue.popleft()
            try:
                # Add timeout for message sending to prevent hanging
                sent = await asyncio.wait_for(
                    app.bot.send_message(LOG_GROUP, text, parse_mode="HTML"),
                    timeout=30.0  # 30 second timeout for message sending
                )
                await asyncio.to_thread(
                    record_remote_artifact,
                    "log", sent.message_id, chat_id=LOG_GROUP, label="economy-log"
                )
                error_count = 0  # Reset on success
                # Pace successful sends
                await asyncio.sleep(random.randint(1, 2))
            except asyncio.TimeoutError:
                error_count += 1
                logger.warning(f"Timeout sending log message after 30 seconds")
                if error_count > max_errors_before_backoff:
                    logger.warning("Dropping log message due to repeated timeout failures.")
                else:
                    # Re-queue for retry with a short delay
                    with _log_lock:
                        log_queue.appendleft(text)
                    await asyncio.sleep(5)
                    continue  # Skip to next iteration without extra sleep
            except Exception as e:
                error_count += 1
                logger.warning("Failed to send log message: %s", e, exc_info=True)
                if error_count > max_errors_before_backoff:
                    logger.warning("Dropping log message due to repeated failures.")
                    # Drop message (do not re-queue)
                else:
                    # Re-queue for retry with a short delay
                    with _log_lock:
                        log_queue.appendleft(text)
                    await asyncio.sleep(5)
                    continue  # Skip to next iteration without extra sleep
        except asyncio.CancelledError:
            logger.info("Log worker cancelled, shutting down gracefully")
            shutdown_event.set()
            break
        except Exception as e:
            logger.error("Unexpected error in log worker: %s", e, exc_info=True)
            await asyncio.sleep(10)

    logger.info("Log worker shutdown complete")


async def gate(update: Update) -> bool:
    user = update.effective_user
    msg = update.effective_message
    if not user or not msg:
        return False
    cached = USER_CACHE.peek(str(user.id))
    if cached:
        data = cached
    else:
        uid, data = await asyncio.to_thread(ensure, user.id, user)
    if data.get("banned") or data.get("silent_ban"):
        if data.get("banned"):
            reason = data.get("ban_reason", "")
            text = "🥂 Yᴏᴜ Aʀᴇ Bᴀɴɴᴇᴅ Fʀᴏᴍ Usɪɴɢ Bᴏᴛ"
            if reason:
                text += f"\n\n⚠️ Rᴇᴀsᴏɴ : {html.escape(reason)}"
            await msg.reply_html(text, reply_markup=_support())
        return True
    return False


