_dailygift_locks = BoundedLockDict(maxsize=100000)

def _get_dailygift_lock(user_id: int) -> asyncio.Lock:
    return _dailygift_locks.get(user_id)

async def dailygift(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await gate(update):
        return
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not user or not msg or not chat:
        return
    if await antibot_verification_guard(update, ctx):
        return

    # Must use in DM — reject early before any DB writes
    if chat.type != "private":
        kb = [
            [
                InlineKeyboardButton(
                    "ᴄʟᴀɪᴍ ɪɴ ᴅᴍ 🎁", url=f"https://t.me/{BOT_USERNAME}?start=dailygift"
                )
            ]
        ]
        return await msg.reply_html(
            "⚠️ Cʟᴀɪᴍ ʏᴏᴜʀ ᴅᴀɪʟʏ ɢɪꜰᴛ ɪɴ Bᴏᴛ Dᴍ!", reply_markup=InlineKeyboardMarkup(kb)
        )

    async with _get_dailygift_lock(user.id):
        # Re-fetch fresh data INSIDE the lock to prevent TOCTOU race
        uid, data = await asyncio.to_thread(ensure, user.id, user)
        last = data.get("collect_time", 0)
        now = _now()
        diff = now - last

        if last != 0 and diff < DAILY_COOLDOWN:
            remaining = DAILY_COOLDOWN - diff
            return await msg.reply_html(
                f"⚠️ Yᴏᴜ Aʟʀᴇᴀᴅʏ Cʟᴀɪᴍᴇᴅ Tᴏᴅᴀʏ\n🕰 Nᴇxᴛ Rᴇᴡᴀʀᴅ Iɴ: <b>{_fmt(remaining)}</b>"
            )

        is_premium_status = await asyncio.to_thread(is_premium, user.id)

        reward = PREMIUM_DAILY_REWARD if is_premium_status else DAILY_REWARD

        premium_text = "⭐ Premium bonus received." if is_premium_status else f"⭐ Upgrade with /buy for <b>${PREMIUM_DAILY_REWARD:,}/day</b>."

        daily_xp = random.randint(DAILY_XP_MIN, DAILY_XP_MAX)
        resp = (
            f"🎁 Dᴀɪʟʏ Gɪꜰᴛ: <b>${reward:,}</b> + <b>{daily_xp} XP</b>\n"
            f"{premium_text}"
        )

        result = await asyncio.to_thread(
            update_user_atomic,
            uid,
            inc_fields={
                "balance": reward,
                "rp": daily_xp,
                "daily_income": reward,
                "weekly_income": reward,
                "lifetime_income": reward,
            },
            set_fields={"collect_time": now}
        )
        if not result:
            return await msg.reply_text("⚠️ Claim failed. Please try again.")
    
    await record_successful_farm_action(user.id, None, "dailygift")
    await msg.reply_html(resp)


