async def redeem(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await gate(update):
        return
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not user or not msg or not chat:
        return
    if chat.type == "private":
        return await msg.reply_text("⚠️ Rᴇᴅᴇᴇᴍ Wᴏʀᴋs Oɴʟʏ Iɴ Gʀᴏᴜᴘs")
    # Cached gameoff check
    if await is_game_off_cached_async(chat.id):
        return await msg.reply_text("🎮 Gᴀᴍᴇ ɪs Oꜰꜰ ɪɴ Tʜɪs Gʀᴏᴜᴘ.")
    if await verify_guard(update, ctx):
        return

    if await asyncio.to_thread(get_setting, f"groupban_{chat.id}", ""):
        return
    try:
        members = await ctx.bot.get_chat_member_count(chat.id)
    except TelegramError as exc:
        logger.debug(f"Chat member count failed for redeem: {exc}")
        members = 0
    if members < REDEEM_MIN_MEMBERS:
        return await msg.reply_html(
            f"⚠️ <b>Gʀᴏᴜᴘ Nᴇᴇᴅs 100+ Mᴇᴍʙᴇʀs</b>\nCᴜʀʀᴇɴᴛ: <b>{members}</b>"
        )
    # Parallel fetch: ensure user data + (no other independent work to overlap)
    result = await asyncio.to_thread(ensure, user.id, user)
    uid, data = result
    redeem_key = f"redeemed_{chat.id}"

    async with _get_redeem_lock(chat.id):
        last = await asyncio.to_thread(get_setting, redeem_key, 0)
        if last != 0:
            return await msg.reply_text("⚠️ Tʜɪs Gʀᴏᴜᴘ Hᴀꜱ Aʟʀᴇᴀᴅʏ Bᴇᴇɴ Rᴇᴅᴇᴇᴍᴇᴅ. Oɴʟʏ Oɴᴇ Rᴇᴅᴇᴇᴍ Pᴇʀ Gʀᴏᴜᴘ Lɪꜰᴇᴛɪᴍᴇ!")

        redeem_xp = random.randint(REDEEM_XP_MIN, REDEEM_XP_MAX)
        try:
            result = await asyncio.to_thread(
                update_user_atomic,
                uid,
                inc_fields={
                    "balance": REDEEM_REWARD,
                    "rp": redeem_xp,
                    "total_redeems": 1,
                    "total_redeem_earned": REDEEM_REWARD,
                    "daily_redeem": REDEEM_REWARD,
                    "weekly_redeem": REDEEM_REWARD,
                    "daily_income": REDEEM_REWARD,
                    "weekly_income": REDEEM_REWARD,
                    "lifetime_income": REDEEM_REWARD,
                },
            )
            if result:
                data = result
        except Exception:
            logger.exception("Redeem reward increment failed for user %s", uid)
            return await msg.reply_text("⚠️ Rᴇᴅᴇᴍ Fᴀɪʟᴇᴅ. Pʟᴇᴀsᴇ Rᴇᴛʀʏ.")
        await asyncio.to_thread(save_setting, redeem_key, _now())
    
    await record_successful_farm_action(user.id, chat.id, "redeem")
    rank = await asyncio.to_thread(tidb_cached_global_rank, uid)

    await msg.reply_html(
        f"🏆 <b>Gʀᴏᴜᴘ Rᴇᴅᴇᴇᴍ Cʟᴀɪᴍᴇᴅ</b>\n\n"
        f"👤 Cʟᴀɪᴍᴇᴅ Bʏ: <b>{html.escape(user.first_name)}</b>\n"
        f"💰 Rᴇᴡᴀʀᴅ: <b>$4,000</b> + <b>{redeem_xp} XP</b>\n"
        f"🥂 Cᴏɴɢʀᴀᴛᴜʟᴀᴛɪᴏɴs"
    )

    with _history_lock:
        top = sorted(user_messages.get(chat.id, {}).items(), key=lambda x: x[1], reverse=True)[:5]
    top_text = "".join(
        f"  {i}. <code>{u_id}</code> — {cnt} msgs\n"
        for i, (u_id, cnt) in enumerate(top, 1)
    )

    if int(data.get("total_redeems", 0) or 0) >= 3:
        add_log(
            f"📜 <b>Rᴇᴅᴇᴇᴍ Lᴏɢ</b>\n"
            f"👤 User: <b>{html.escape(user.full_name)}</b>\n"
            f"🆔 ID: <code>{user.id}</code>\n"
            f"📛 @{html.escape(user.username or 'N/A')}\n\n"
            f"🏠 Group: <b>{html.escape(chat.title)}</b>\n"
            f"🆔 Group ID: <code>{chat.id}</code>\n"
            f"👥 Members: <b>{members}</b>\n\n"
            f"🏆 Rank: <b>{rank}</b>\n"
            f"⚔️ Total Captures: <b>{data.get('captures', 0)}</b>\n"
            f"💰 Balance: <b>${data.get('balance', 0):,}</b>\n"
            f"🪙 Total Money By Redeem: <b>${data.get('total_redeem_earned', 0):,}</b>\n"
            f"🎯 Total Money By Bounty: <b>${data.get('total_bounty_earned', 0):,}</b>\n"
            f"🔢 Total Redeems: <b>{data.get('total_redeems', 0)}</b>\n\n"
            f"🏅 Top Senders:\n{top_text}"
        )

