# Flatten all dares
ALL_DARES = []
for category_dares in DARES.values():
    ALL_DARES.extend(category_dares)

def dares__get_category(category: str) -> list:
    """Get dares for a specific category."""
    return DARES.get(category, [])

def get_random_dare() -> str:
    """Get a random dare."""
    import random
    return random.choice(ALL_DARES)

def dares__get_categories() -> list:
    """Get list of all category names."""
    return list(DARES.keys())

