def get_random_riddle() -> dict:
    """Get a random riddle."""
    import random
    return random.choice(RIDDLES)

def get_riddle_by_index(index: int) -> dict:
    """Get riddle by index."""
    if 0 <= index < len(RIDDLES):
        return RIDDLES[index]
    return None

def get_total_riddles() -> int:
    """Get total number of riddles."""
    return len(RIDDLES)

