# Flatten all truths
ALL_TRUTHS = []
for category_truths in TRUTHS.values():
    ALL_TRUTHS.extend(category_truths)

def get_category(category: str) -> list:
    """Get truths for a specific category."""
    return TRUTHS.get(category, [])

def get_random_truth() -> str:
    """Get a random truth question."""
    import random
    return random.choice(ALL_TRUTHS)

def get_categories() -> list:
    """Get list of all category names."""
    return list(TRUTHS.keys())

