import asyncio, html, json, random, re, time
from pathlib import Path
from typing import Any
from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update
from telegram.ext import ContextTypes

logger = get_logger(__name__)
CONTENT_DIR = Path("data/content")
_gif_pool_input_state: dict[int, dict] = {}


# ── ASYNCIO LOCKS FOR GLOBAL STATE ──
_selection_lock: asyncio.Lock | None = None
_usage_lock: asyncio.Lock | None = None
_gif_state_lock: asyncio.Lock | None = None

async def _get_selection_lock() -> asyncio.Lock:
    global _selection_lock
    if _selection_lock is None:
        _selection_lock = asyncio.Lock()
    return _selection_lock

async def _get_usage_lock() -> asyncio.Lock:
    global _usage_lock
    if _usage_lock is None:
        _usage_lock = asyncio.Lock()
    return _usage_lock

async def _get_gif_state_lock() -> asyncio.Lock:
    global _gif_state_lock
    if _gif_state_lock is None:
        _gif_state_lock = asyncio.Lock()
    return _gif_state_lock

# ── WEIGHTED RANDOM SELECTOR WITH NO-REPEAT SYSTEM ──
# Prevents same item repeating, ensures diverse selections
_selection_history: dict[str, list] = {}  # {key: [last_5_items]}
_usage_counts: dict[str, int] = {}  # {item_text: usage_count}

def _urlopen_read(req):
    import urllib.request
    with urllib.request.urlopen(req, timeout=10) as resp:
        return resp.read()

async def weighted_random(pool: list, key: str = "default") -> Any:
    """
    Smart weighted random selection (async with locks):
    - Never repeats last 5 items
    - Prefers less-used items (weight by inverse usage)
    - Falls back to normal random if pool is small
    """
    if not pool:
        return None

    if len(pool) <= 5:
        # Small pool - just random (no state mutation)
        return random.choice(pool)

    async with await _get_selection_lock():
        # Read and update selection history inside lock
        history = _selection_history.get(key, [])

        # Filter out recent items
        available = [item for item in pool if item not in history]

        if not available:
            # All items in history - clear it
            _selection_history[key] = []
            available = pool[:]

        # Weight by inverse usage (prefer less-used items)
        weights = []
        for item in available:
            item_key = str(item)
            usage = _usage_counts.get(item_key, 0) + 1
            weights.append(1.0 / usage)

        # Weighted random selection
        chosen = random.choices(available, weights=weights, k=1)[0]

        # Update history only (inside selection lock)
        history.append(chosen)
        if len(history) > 5:
            history.pop(0)
        _selection_history[key] = history

    # Update usage counts separately (only this mutation needs usage lock)
    async with await _get_usage_lock():
        _usage_counts[str(chosen)] = _usage_counts.get(str(chosen), 0) + 1

    return chosen


async def _load_pack(name: str, default):
    path = CONTENT_DIR / name
    try:
        if path.exists():
            # Use thread pool for non-blocking file I/O
            loop = asyncio.get_running_loop()
            text = await loop.run_in_executor(None, path.read_text, "utf-8")
            return json.loads(text)
    except Exception as e:
        logger.error("Failed to load pack %s: %s", name, e, exc_info=True)
    return default

def _n(user) -> str:
    return html.escape(user.first_name or user.username or "Someone")

def fun_commands__mention(user) -> str:
    name = html.escape(user.first_name or user.username or "Someone")
    return f'<a href="tg://user?id={user.id}">{name}</a>'


def gif_pool_input_pending(uid: int) -> bool:
    state = _gif_pool_input_state.get(uid)
    return bool(state and state.get("expires_at", 0) > time.time())

async def _need_reply(msg) -> bool:
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_html("⚠️ Reply to a user to use this command.")
        return True
    return False


async def _reply_target(update: Update):
    msg = update.effective_message
    actor = update.effective_user
    if await _need_reply(msg):
        return None
    target = msg.reply_to_message.from_user
    if target.is_bot:
        await msg.reply_html("⚠️ This works only on human users.")
        return None
    if actor and target.id == actor.id:
        await msg.reply_html("⚠️ Reply to someone else, not yourself.")
        return None
    return target

# ── /looks ──
async def looks(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await verify_guard(update, ctx): return
    msg = update.effective_message
    target = await _reply_target(update)
    if not target: return
    score = random.randint(1, 100)
    emoji = "😍" if score > 80 else "🔥" if score > 60 else "✨" if score > 40 else "😐" if score > 20 else "💀"
    await msg.reply_html(f"🎐 {fun_commands__mention(target)}'ꜱ Lᴏᴏᴋ Rᴀᴛɪɴɢ Iꜱ: <b>{score}%</b> {emoji}")

# ── /iq ──
async def iq(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await verify_guard(update, ctx): return
    msg = update.effective_message
    target = await _reply_target(update)
    if not target: return
    score = random.randint(10, 200)
    if score > 150: tag = "🧬 Gᴇɴɪᴜs Zᴏɴᴇ"
    elif score > 120: tag = "🎓 Bɪɢ Bʀᴀɪɴ"
    elif score > 100: tag = "📚 Sʜᴀʀᴘ Mɪɴᴅ"
    elif score > 80: tag = "🙂 Nᴏʀᴍᴀʟ Hᴜᴍᴀɴ"
    elif score > 50: tag = "🤔 Sᴛɪʟʟ Lᴏᴀᴅɪɴɢ"
