async def truth(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """🔥 Truth command with simple clean format."""
    if await verify_guard(update, ctx): return
    msg = update.effective_message

    try:
        raw = get_cached_fun_list("truths_list", "")
        if raw:
            pool = [t.strip() for t in raw.split("||") if t.strip()]
        else:
            pack = await _load_pack("truths.json", DEFAULT_TRUTHS)
            pool = [t.get("q", t) if isinstance(t, dict) else t for t in pack]

        if not pool:
            pack = DEFAULT_TRUTHS
            pool = [t.get("q", t) if isinstance(t, dict) else t for t in pack]

        chosen = await weighted_random(pool, key="truths")
        question = chosen if isinstance(chosen, str) else chosen.get("q", "Unknown question")

        if not question.endswith((".", "?", "!", ",")):
            question += "."

        await msg.reply_text(f"❓ {question}")
    except Exception as exc:
        logger.warning("Truth command error: %s", exc, exc_info=True)
        try:
            await msg.reply_text("❓ " + random.choice([t for items in _TRUTHS_EXTRA.values() for t in items]))
        except Exception:
            pass


