async def riddle(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """🧩 Riddle command with hints, difficulty, and weighted random."""
    if await verify_guard(update, ctx): return
    msg = update.effective_message

    try:
        raw = get_cached_fun_list("puzzles_list", "")
        if raw:
            pool = [
                {"q": p.split("==>")[0].strip(), "a": p.split("==>")[1].strip(), "hint": "Think hard!", "diff": "🟡"}
                for p in raw.split("||") if "==>" in p
            ]
        else:
            pack = await _load_pack("riddles.json", DEFAULT_RIDDLES)
            pool = []
            for item in pack:
                if isinstance(item, dict):
                    pool.append({
                        "q": item.get("question", item.get("q", "")),
                        "a": item.get("answer", item.get("a", "")),
                        "hint": item.get("hint", "Think hard!"),
                        "diff": item.get("diff", "🟡")
                    })
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    pool.append({"q": item[0], "a": item[1], "hint": "Think hard!", "diff": "🟡"})

        if not pool:
            pool = [{"q": r["q"], "a": r["a"], "hint": "Think hard!", "diff": "🟡"} for r in _RIDDLES_EXTRA]

        chosen = await weighted_random(pool, key="riddles")
        question = chosen.get("q", "Unknown question")
        answer = chosen.get("a", "Unknown answer")
        hint = chosen.get("hint", "Think hard!")
        difficulty = chosen.get("diff", "🟡")

        text = (
            f"{html.escape(difficulty)} <b>Rɪᴅᴅʟᴇ Tɪᴍᴇ!</b>\n\n"
            f"❓ {html.escape(question)}\n\n"
            f"🔑 Aɴsᴡᴇʀ: <tg-spoiler>{html.escape(answer)}</tg-spoiler>"
        )

        await msg.reply_html(text)
    except Exception as exc:
        logger.warning("Riddle command error: %s", exc, exc_info=True)
        try:
            r = random.choice(_RIDDLES_EXTRA)
            await msg.reply_html(
                f"🟡 <b>Rɪᴅᴅʟᴇ Tɪᴍᴇ!</b>\n\n"
                f"❓ {html.escape(r['q'])}\n\n"
                f"🔑 Aɴsᴡᴇʀ: <tg-spoiler>{html.escape(r['a'])}</tg-spoiler>"
            )
        except Exception:
            pass

