# ── Usage Tracking ───────────────────────────────────────────────────────────

@dataclass
class ModelUsage:
    """Tracks usage for a single model."""
    
    def __init__(self, model_name: str, provider: str = ""):
        self.model_name = model_name
        self.provider = provider
        self._lock = threading.RLock()
        self.requests_min: deque = deque(maxlen=1000)
        self.tokens_min: deque = deque(maxlen=1000)
        self.requests_day: deque = deque(maxlen=100000)
        self.tokens_day: deque = deque(maxlen=100000)
        self.total_requests = 0
        self.tokens_used = 0
        self.errors = 0
        self.last_error = ""
        self.last_reset = time.time()
        self.cooldown_until: float = 0
        self.limit_reached = False

    def reset_if_needed(self):
        """Reset daily counters if a day has passed."""
        now = time.time()
        with self._lock:
            if now - self.last_reset > 86400:
                self.requests_day.clear()
                self.tokens_day.clear()
                self.last_reset = now
                logger.info(f"[limits] {self.model_name} daily counters reset")

    def prune_usage(self):
        """Remove expired entries from all tracking deques."""
        with self._lock:
            now = time.time()
            
            # Prune minute windows
            while self.requests_min and now - self.requests_min[0] > 60:
                self.requests_min.popleft()
            while self.tokens_min and now - self.tokens_min[0][0] > 60:
                self.tokens_min.popleft()
                
            # Prune day windows
            while self.requests_day and now - self.requests_day[0] > 86400:
                self.requests_day.popleft()
            while self.tokens_day and now - self.tokens_day[0][0] > 86400:
                self.tokens_day.popleft()

    def requests_in_window(self, window_seconds: int = 60) -> int:
        """Count requests in the time window."""
        self.prune_usage()
        with self._lock:
            if window_seconds <= 60:
                return len(self.requests_min)
            return len(self.requests_day)
    
    def tokens_in_window(self, window_seconds: int = 60) -> int:
        """Count tokens used in the time window."""
        self.prune_usage()
        with self._lock:
            if window_seconds <= 60:
                return sum(tokens for _, tokens in self.tokens_min)
            return sum(tokens for _, tokens in self.tokens_day)

    def is_rate_limited(self, rpm: int, rpd: int, tpm: int, tpd: int) -> bool:
        """Check if model has hit rate limits."""
        self.reset_if_needed()
        with self._lock:
            # Check RPM
            if self.requests_in_window(60) >= rpm:
                return True
            
            # Check RPD
            if self.requests_in_window(86400) >= rpd:
                return True
            
            # Check TPM
            if self.tokens_in_window(60) >= tpm:
                return True
            
            # Check TPD
            if self.tokens_in_window(86400) >= tpd:
                return True
            
            return False

    def record_request(self, tokens: int = 0):
        """Record a successful API request."""
        with self._lock:
            now = time.time()
            self.requests_min.append(now)
            self.requests_day.append(now)
            self.total_requests += 1
            
            if tokens > 0:
                self.tokens_used += tokens
                self.tokens_min.append((now, tokens))
                self.tokens_day.append((now, tokens))

    def record_error(self, error: str, is_rate_limit: bool = False):
        """Record an API error."""
        with self._lock:
            self.errors += 1
            self.last_error = error
            
            if is_rate_limit:
                self.limit_reached = True
                logger.warning(f"[limits] {self.model_name} rate limit reached: {error[:100]}")

    def mark_cooldown(self, seconds: int):
        """Set cooldown period."""
        with self._lock:
            self.cooldown_until = time.time() + max(5, seconds)
            logger.info(f"[limits] {self.model_name} cooldown for {seconds}s")

    def is_on_cooldown(self) -> bool:
        """Check if model is on cooldown."""
        return time.time() < self.cooldown_until

    def get_usage_stats(self) -> dict:
        """Get current usage statistics."""
        self.prune_usage()
        return {
            "model": self.model_name,
            "provider": self.provider,
            "rpm_current": len(self.requests_min),
            "tpm_current": self.tokens_in_window(60),
            "total_requests": self.total_requests,
            "errors": self.errors,
            "limit_reached": self.limit_reached,
            "on_cooldown": self.is_on_cooldown(),
            "cooldown_remaining": max(0, self.cooldown_until - time.time()),
        }


# ── Global Usage Registry ────────────────────────────────────────────────────

class UsageRegistry:
    """Global registry for all model usage tracking."""
    
    _instance = None
    _lock = threading.RLock()
    
    def __init__(self):
        self._usage: dict[str, ModelUsage] = {}
    
    @classmethod
    def get_instance(cls) -> "UsageRegistry":
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance
    
    def get_or_create(self, model_name: str, provider: str) -> ModelUsage:
        key = f"{provider}:{model_name}"
        with self._lock:
            if key not in self._usage:
                self._usage[key] = ModelUsage(model_name=model_name, provider=provider)
            return self._usage[key]
    
    def get_all_usage(self) -> dict[str, dict]:
        with self._lock:
            return {k: v.get_usage_stats() for k, v in self._usage.items()}
    
    def reset_model(self, model_name: str, provider: str):
        """Force reset a model's usage (e.g., after limit reset)."""
        key = f"{provider}:{model_name}"
        with self._lock:
            if key in self._usage:
                usage = self._usage[key]
                usage.requests_min.clear()
                usage.requests_day.clear()
                usage.tokens_min.clear()
                usage.tokens_day.clear()
                usage.tokens_used = 0
                usage.limit_reached = False
                usage.cooldown_until = 0
                usage.last_reset = time.time()
                logger.info(f"[limits] {model_name} forcefully reset")


# ── Helper Functions ─────────────────────────────────────────────────────────

model_limits_tracker__registry = UsageRegistry.get_instance()


def track_request(model: str, provider: str, tokens: int = 0, success: bool = True, error: str = ""):
    """Track API request usage."""
    usage = model_limits_tracker__registry.get_or_create(model, provider)
    if success:
        usage.record_request(tokens)
    else:
        usage.record_error(error, is_rate_limit=_is_rate_limit_error(error))


def check_rate_limit(model: str, provider: str) -> bool:
    """Check if model is rate limited. Returns True if limited."""
    usage = model_limits_tracker__registry.get_or_create(model, provider)
    
    # Check cooldown first
    if usage.is_on_cooldown():
        return True
    
    # Get limits based on provider
    if provider == "gemini":
        limits = GEMINI_LIMITS.get(model, {})
    elif provider == "deepseek":
        limits = DEEPSEEK_LIMITS.get(model, {})
    elif provider == "qwen":
        limits = QWEN_LIMITS.get(model, {})
    elif provider == "nvidia":
        limits = NVIDIA_MODEL_LIMITS.get(model, {})
    else:
        limits = GROQ_MODEL_LIMITS.get(model, {})
    
    if not limits:
        return False  # No limits defined, assume available
    
    rpm = limits.get("rpm", 1000)
    rpd = limits.get("rpd", 10000)
    tpm = limits.get("tpm", 100000)
    tpd = limits.get("tpd", 1000000)
    
    return usage.is_rate_limited(rpm, rpd, tpm, tpd)


def set_cooldown(model: str, provider: str, seconds: int):
    """Set cooldown for a model."""
    usage = model_limits_tracker__registry.get_or_create(model, provider)
    usage.mark_cooldown(seconds)


def reset_model_limits(model: str, provider: str):
    """Force reset model limits (use when limits are known to be reset)."""
    model_limits_tracker__registry.reset_model(model, provider)


def get_model_status(model: str, provider: str) -> dict:
    """Get current model status."""
    usage = model_limits_tracker__registry.get_or_create(model, provider)
    return usage.get_usage_stats()


def get_all_models_status() -> dict:
    """Get status of all tracked models."""
    return model_limits_tracker__registry.get_all_usage()


def _is_rate_limit_error(error: str) -> bool:
    """Check if error message indicates rate limiting (shared classifier)."""
    return _is_rate_limited_error_str(error)

