# ═══ MODULE: system.ai.session ═══

import asyncio
import aiohttp


logger = get_logger(__name__)

_http_session = None
_http_session_lock: asyncio.Lock | None = None


def _get_http_session_lock() -> asyncio.Lock:
    global _http_session_lock
    if _http_session_lock is None:
        _http_session_lock = asyncio.Lock()
    return _http_session_lock


async def _get_http_session() -> aiohttp.ClientSession:
    global _http_session
    if _http_session is None or _http_session.closed:
        async with _get_http_session_lock():
            if _http_session is None or _http_session.closed:
                connector = aiohttp.TCPConnector(limit=50, ttl_dns_cache=300, force_close=False)
                timeout = aiohttp.ClientTimeout(total=30, connect=10)
                _http_session = aiohttp.ClientSession(connector=connector, timeout=timeout)
                logger.debug("[ai] Created new HTTP session")
    return _http_session


async def shutdown_http_session():
    global _http_session
    if _http_session and not _http_session.closed:
        try:
            await _http_session.close()
        except Exception:
            logger.warning("Exception in shutdown_http_session", exc_info=True)

