# 💗 AI Error Detector & Auto-Swap System — system/error_detector.py
# Detects ALL error types and automatically swaps to next available model
# Handles: Rate limits, Account limits, Network errors, Quota, Capacity, etc.
# =========================================

import re
import time
import threading
from enum import Enum
from dataclasses import dataclass
from typing import Optional
from collections import defaultdict, deque

logger = get_logger(__name__)

# Import audit framework (optional dependency)
try:
    from audit_framework.core import CodeScanner
    _AUDIT_AVAILABLE = True
except ImportError:
    _AUDIT_AVAILABLE = False

class ErrorType(Enum):
    """All possible error types across all AI providers."""
    # Rate Limit Errors (retryable after cooldown)
    RATE_LIMIT_RPM = "rate_limit_rpm"
    RATE_LIMIT_RPD = "rate_limit_rpd"
    RATE_LIMIT_TPM = "rate_limit_tpm"
    RATE_LIMIT_TPD = "rate_limit_tpd"
    RATE_LIMIT_GENERAL = "rate_limit_general"
    
    # Account/Billing Errors (retryable or needs swap)
    QUOTA_EXCEEDED = "quota_exceeded"
    ACCOUNT_LIMIT = "account_limit"
    BILLING_REQUIRED = "billing_required"
    CREDIT_EXHAUSTED = "credit_exhausted"
    FREE_TIER_LIMIT = "free_tier_limit"
    
    # Capacity/Server Errors (retryable with backoff)
    SERVER_OVERLOAD = "server_overload"
    CAPACITY_EXCEEDED = "capacity_exceeded"
    SERVICE_UNAVAILABLE = "service_unavailable"
    TEMPORARY_ERROR = "temporary_error"
    
    # Network Errors (retryable immediately)
    NETWORK_TIMEOUT = "network_timeout"
    CONNECTION_REFUSED = "connection_refused"
    DNS_FAILURE = "dns_failure"
    SSL_ERROR = "ssl_error"
    
    # Authentication Errors (NOT retryable - config issue)
    AUTH_FAILED = "auth_failed"
    INVALID_KEY = "invalid_api_key"
    ACCOUNT_SUSPENDED = "account_suspended"
    
    # Model Errors (swap to different model)
    MODEL_NOT_FOUND = "model_not_found"
    MODEL_DEPRECATED = "model_deprecated"
    CONTEXT_TOO_LONG = "context_too_long"
    
    # MongoDB and Loop Errors (trigger code audits)
    MONGODB_ISSUE = "mongodb_issue"
    LOOP_ERROR = "loop_error"
    
    # Unknown/Other (retryable with caution)
    UNKNOWN_ERROR = "unknown_error"

def trigger_audit(error_type: ErrorType):
    """Trigger targeted audit based on error classification"""
    if not _AUDIT_AVAILABLE:
        return None
    scanner = CodeScanner()
    
    # Configure audit based on error type
    if error_type in (ErrorType.MONGODB_ISSUE,):
        scanner.config["focus_areas"] = ["mongodb_rules"]
    elif error_type == ErrorType.LOOP_ERROR:
        scanner.config["focus_areas"] = ["loop_rules"]
    
    # Run focused audit
    scanner.run_audit()
    return scanner.generate_report()


