def _lazy_config_gemini():
    global gemini__GEMINI_API_KEY, gemini__GEMINI_MODEL
    if not gemini__GEMINI_API_KEY:
        try:
            mod = importlib.import_module("config")
        except ImportError:
            import sys as _sys
            mod = _sys.modules.get("__main__") or _sys.modules.get("anyybest")
        gemini__GEMINI_API_KEY = getattr(mod, "GEMINI_API_KEY", "")
        gemini__GEMINI_MODEL = getattr(mod, "GEMINI_MODEL", "gemini-3.5-flash-lite")


def _parse_retry_after_gemini(text: str) -> Optional[int]:
    match = re.search(r"retry after\s*[:=]?\s*(\d+)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    match = re.search(r"retry-after[=:]\s*(\d+)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None

async def call_gemini(
    messages: list,
    max_tokens: int,
    temperature: float,
    model: str = "",
) -> Tuple[str, dict]:
    _lazy_config_gemini()
    if not gemini__GEMINI_API_KEY:
        raise RuntimeError("Gemini API key not configured")
    model = model or gemini__GEMINI_MODEL
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"

    contents = []
    for msg in messages:
        role = msg.get("role", "user")
        content = msg.get("content", "")
        if role == "system":
            if contents:
                contents[0]["parts"][0]["text"] = f"{content}\n\n{contents[0]['parts'][0]['text']}"
            else:
                contents.append({"role": "user", "parts": [{"text": content}]})
        else:
            gemini_role = "model" if role == "assistant" else "user"
            contents.append({"role": gemini_role, "parts": [{"text": content}]})

    payload = {
        "contents": contents,
        "generationConfig": {
            "temperature": temperature,
            "maxOutputTokens": max_tokens,
        }
    }
    session = await _get_shared_session()
    headers = {"x-goog-api-key": gemini__GEMINI_API_KEY}
    try:
        async with session.post(url, json=payload, headers=headers) as resp:
            response_data = await resp.json()
            if resp.status == 429 or resp.status == 503:
                error_text = response_data.get("error", {}).get("message", "Rate limited")
                track_request(model, "gemini", success=False, error=error_text)
                get_swap_manager().mark_provider_failure("gemini", error_text, resp.status)
                retry_after = _parse_retry_after_gemini(error_text) or 60
                set_cooldown(model, "gemini", retry_after)
                raise RuntimeError(f"Gemini rate limited: {error_text}")
            if resp.status != 200:
                error_text = response_data.get("error", {}).get("message", "Unknown error")
                track_request(model, "gemini", success=False, error=error_text)
                get_swap_manager().mark_provider_failure("gemini", error_text, resp.status)
                raise RuntimeError(f"Gemini error: {error_text}")
            candidates = response_data.get("candidates", [])
            if not candidates:
                raise RuntimeError("Gemini returned no candidates")
            parts = candidates[0].get("content", {}).get("parts") or [{}]
            content_text = parts[0].get("text", "") if parts else ""
            usage_metadata = response_data.get("usageMetadata", {})
            tokens = usage_metadata.get("totalTokenCount", len(content_text) // 4)
            track_request(model, "gemini", tokens=tokens, success=True)
            get_swap_manager().mark_provider_success("gemini")
            return content_text, {"model": model, "provider": "gemini", "tokens": tokens}
    except aiohttp.ClientError as e:
        track_request(model, "gemini", success=False, error=str(e))
        raise RuntimeError(f"Gemini request failed: {e}") from e


def has_key_gemini() -> bool:
    _lazy_config_gemini()
    return bool(gemini__GEMINI_API_KEY)

