# ═══ AI AUTO-DISCOVERY & PRIORITY ENGINE ═══

import time as _time_autodiscover

class _AutoPriority:
    """Auto-discovers live models per provider, tests them, ranks by speed.

    Each provider gets a score = success_rate / avg_response_time.
    Higher score = higher priority. Re-ranks every 5 minutes.
    """
    def __init__(self):
        self._scores: dict[str, float] = {}
        self._latencies: dict[str, list[float]] = {}
        self._successes: dict[str, int] = {}
        self._failures: dict[str, int] = {}
        self._last_rank: float = 0
        self._rank_interval = 300  # 5 minutes
        self._lock = asyncio.Lock() if hasattr(asyncio, 'Lock') else None

    def record_success(self, provider: str, latency: float):
        self._latencies.setdefault(provider, []).append(latency)
        if len(self._latencies[provider]) > 20:
            self._latencies[provider] = self._latencies[provider][-20:]
        self._successes[provider] = self._successes.get(provider, 0) + 1
        self._update_score(provider)

    def record_failure(self, provider: str):
        self._failures[provider] = self._failures.get(provider, 0) + 1
        self._update_score(provider)

    def _update_score(self, provider: str):
        s = self._successes.get(provider, 0)
        f = self._failures.get(provider, 0)
        total = s + f
        if total == 0:
            self._scores[provider] = 0.5
            return
        success_rate = s / total
        lats = self._latencies.get(provider, [])
        avg_lat = sum(lats) / len(lats) if lats else 5.0
        # Score: high success rate + low latency = high score
        self._scores[provider] = success_rate / max(avg_lat, 0.1)

    def get_priority_order(self, default: list[str]) -> list[str]:
        """Return providers sorted by score (best first)."""
        now = _time_autodiscover.time()
        if now - self._last_rank < self._rank_interval and self._scores:
            # Use cached ranking
            scored = [(p, self._scores.get(p, 0)) for p in default]
            scored.sort(key=lambda x: -x[1])
            return [p for p, _ in scored]
        self._last_rank = now
        if not self._scores:
            return default
        scored = [(p, self._scores.get(p, 0)) for p in default]
        scored.sort(key=lambda x: -x[1])
        return [p for p, _ in scored]

    def get_status(self) -> dict:
        return {
            "scores": dict(self._scores),
            "latencies": {k: sum(v)/len(v) if v else 0 for k, v in self._latencies.items()},
            "successes": dict(self._successes),
            "failures": dict(self._failures),
        }

_ai_priority = _AutoPriority()


