import importlib
from typing import Tuple


logger = get_logger(__name__)

groq__GROQ_MODEL_CHAINS: dict = {}
groq__GROQ_API_KEY: str = ""

def _lazy_config_groq():
    global groq__GROQ_API_KEY, groq__GROQ_MODEL_CHAINS
    if not groq__GROQ_API_KEY:
        try:
            mod = importlib.import_module("config")
        except ImportError:
            import sys as _sys
            mod = _sys.modules.get("__main__") or _sys.modules.get("anyybest")
        groq__GROQ_API_KEY = getattr(mod, "GROQ_API_KEY", "")
        groq__GROQ_MODEL_CHAINS = getattr(mod, "GROQ_MODEL_CHAINS", {})

def get_model_chain_groq(category: str, lang: str) -> list[str]:
    _lazy_config_groq()
    if lang in ("arabic", "ar"):
        chain_key = "chat_arabic"
    elif category == "chat_reasoning":
        chain_key = "chat_reasoning"
    elif category == "chat_fast":
        chain_key = "chat_fast"
    else:
        chain_key = "chat_default"
    # Try auto-discovered models first, fall back to env config
    discovered = _build_groq_chain_from_discovered()
    if discovered and discovered.get(chain_key):
        return discovered[chain_key]
    return groq__GROQ_MODEL_CHAINS.get(chain_key, groq__GROQ_MODEL_CHAINS.get("chat_default", ["openai/gpt-oss-20b"]))

async def call_groq(
    messages: list,
    max_tokens: int,
    temperature: float,
    model: str = "",
) -> Tuple[str, dict]:
    _lazy_config_groq()
    if not groq__GROQ_API_KEY:
        raise RuntimeError("Groq API key not configured")
    if not model:
        # Prefer live-discovered models (static IDs retire often); fall back
        # to a historically stable ID only when discovery hasn't run yet.
        try:
            live = get_discovered_models("groq")
        except Exception:
            live = []
        model = (live[0] if live else "") or "openai/gpt-oss-20b"
    session = await _get_http_session()
    try:
        payload = {
            "model": model,
            "messages": messages,
            "max_tokens": max_tokens,
            "temperature": temperature,
        }
        async with session.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={
                "Authorization": f"Bearer {groq__GROQ_API_KEY}",
                "Content-Type": "application/json",
            },
            json=payload,
        ) as resp:
            if resp.status != 200:
                text = await resp.text()
                raise RuntimeError(f"Groq {model} returned {resp.status}: {text[:200]}")
            data = await resp.json()
        choices = data.get("choices", [])
        if not choices:
            raise RuntimeError(f"Groq {model} returned empty choices")
        content = choices[0].get("message", {}).get("content")
        if not content:
            raise RuntimeError(f"Groq {model} returned no content")
        usage = data.get("usage", {})
        tokens = usage.get("total_tokens", len(content) // 4)
        track_request(model, "groq", tokens=tokens, success=True)
        get_swap_manager().mark_provider_success("groq")
        return content, {"model": model, "provider": "groq", "tokens": tokens}
    except Exception as e:
        get_swap_manager().mark_provider_failure("groq", str(e))
        raise


def has_key_groq() -> bool:
    _lazy_config_groq()
    return bool(groq__GROQ_API_KEY)

