_get_shared_session = _get_http_session
import importlib
from typing import Tuple

import aiohttp

import re
import random

logger = get_logger(__name__)

opencode_zen__OPENCODE_ZEN_API_KEY: str = ""
opencode_zen__KNOWN_OPENCODE_ZEN_FREE: list[str] = []
opencode_zen__OPENCODE_ZEN_FAST_FREE: list[str] = []

def _lazy_config_opencode_zen():
    global opencode_zen__OPENCODE_ZEN_API_KEY, opencode_zen__KNOWN_OPENCODE_ZEN_FREE, opencode_zen__OPENCODE_ZEN_FAST_FREE
    if not opencode_zen__OPENCODE_ZEN_API_KEY:
        try:
            mod = importlib.import_module("config")
        except ImportError:
            import sys as _sys
            mod = _sys.modules.get("__main__") or _sys.modules.get("anyybest")
        opencode_zen__OPENCODE_ZEN_API_KEY = getattr(mod, "OPENCODE_ZEN_API_KEY", "")

def _get_constants_opencode_zen():
    global opencode_zen__KNOWN_OPENCODE_ZEN_FREE, opencode_zen__OPENCODE_ZEN_FAST_FREE
    if not opencode_zen__KNOWN_OPENCODE_ZEN_FREE:
        opencode_zen__KNOWN_OPENCODE_ZEN_FREE = [
            "minimax-m3-free", "mimo-v2.5-free",
            "nemotron-3-ultra-free", "nemotron-3-super-free",
            "deepseek-v4-flash-free",
        ]
        opencode_zen__OPENCODE_ZEN_FAST_FREE = [
            "minimax-m3-free", "mimo-v2.5-free", "nemotron-3-ultra-free",
        ]
    return opencode_zen__KNOWN_OPENCODE_ZEN_FREE, opencode_zen__OPENCODE_ZEN_FAST_FREE


def _parse_retry_after_opencode_zen(text: str) -> int | None:
    match = re.search(r"retry after\s*[:=]?\s*(\d+)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    match = re.search(r"retry-after[=:]\s*(\d+)", text, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None

async def fetch_free_models() -> list[str]:
    import sys as _sys
    _main_mod = _sys.modules.get("__main__")
    _fetch_fn = getattr(_main_mod, "fetch_opencode_zen_free_models", None)
    if _fetch_fn is None:
        # Import-mode (tests/local harness): the real fetcher lives in this
        # bundle's globals, not on __main__.
        _fetch_fn = globals().get("fetch_opencode_zen_free_models")
    if _fetch_fn is None:
        known, _fast = _get_constants_opencode_zen()
        return list(known)
    return await _fetch_fn()

async def call_opencode_zen(
    messages: list,
    max_tokens: int,
    temperature: float,
    model: str = "",
) -> Tuple[str, dict]:
    _lazy_config_opencode_zen()
    if not opencode_zen__OPENCODE_ZEN_API_KEY:
        raise RuntimeError("OpenCode Zen API key not configured")
    known, fast = _get_constants_opencode_zen()
    free_models = await fetch_free_models()

    candidates: list[str] = []
    for m in fast:
        if m in free_models and not check_rate_limit(m, "opencode_zen"):
            candidates.append(m)
    for m in free_models:
        if m not in candidates and not check_rate_limit(m, "opencode_zen"):
            candidates.append(m)
    for m in known:
        if m not in candidates and not check_rate_limit(m, "opencode_zen"):
            candidates.append(m)

    if not candidates:
        raise RuntimeError("No OpenCode Zen free models available (all rate-limited or dead)")

    random.shuffle(candidates)

    url = "https://opencode.ai/zen/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {opencode_zen__OPENCODE_ZEN_API_KEY}",
        "Content-Type": "application/json",
    }
    session = await _get_shared_session()
    last_error: Exception | None = None

    for model in candidates:
        is_reasoning = model not in fast
        budget = max(max_tokens, 400) if is_reasoning else max(max_tokens, 200)
        payload = {
            "model": model,
            "messages": messages,
            "max_tokens": budget,
            "temperature": temperature,
        }
        try:
            async with session.post(url, json=payload, headers=headers,
                                    timeout=aiohttp.ClientTimeout(total=20)) as resp:
                if resp.status == 429:
                    body = await resp.text()
                    retry_after = _parse_retry_after_opencode_zen(body) or 60
                    set_cooldown(model, "opencode_zen", retry_after)
                    logger.warning("[ai_model] OpenCode Zen %s 429, cooldown %ds", model, retry_after)
                    last_error = RuntimeError(f"429 for {model}")
                    continue
                if resp.status != 200:
                    body = await resp.text()
                    body_lower = body.lower()
                    if ("free promotion" in body_lower or "subscription" in body_lower
                            or "not found" in body_lower or "model_not_found" in body_lower
                            or "no longer free" in body_lower):
                        last_error = RuntimeError(f"{model} no longer free")
                        continue
                    last_error = RuntimeError(f"OpenCode Zen {model} error {resp.status}: {body[:100]}")
                    continue
                data = await resp.json()
                choices = data.get("choices", [])
                if not choices:
                    last_error = RuntimeError(f"OpenCode Zen {model} no choices")
                    continue
                message = choices[0].get("message", {})
                content = message.get("content") or ""
                if content:
                    content = re.sub(r"<think>.*?</think>\s*", "", content, flags=re.DOTALL).strip()
                if not content:
                    last_error = RuntimeError(f"OpenCode Zen {model} empty content after strip")
                    continue
                model_used = data.get("model", model)
                usage = data.get("usage", {})
                tokens = usage.get("total_tokens", len(content) // 4)
                track_request(model_used, "opencode_zen", tokens=tokens, success=True)
                get_swap_manager().mark_provider_success("opencode_zen")
                return content, {"model": model_used, "provider": "opencode_zen", "tokens": tokens}
        except aiohttp.ClientError as e:
            last_error = e
            continue
        except asyncio.TimeoutError:
            last_error = RuntimeError(f"OpenCode Zen {model} timeout")
            continue

    track_request("opencode_zen", "opencode_zen", success=False, error=str(last_error))
    get_swap_manager().mark_provider_failure("opencode_zen", str(last_error))
    raise RuntimeError(f"All OpenCode Zen free models failed: {last_error}")


def has_key_opencode_zen() -> bool:
    _lazy_config_opencode_zen()
    return bool(opencode_zen__OPENCODE_ZEN_API_KEY)

