# ═══ MODULE: system.ai.router ═══

import asyncio
import logging
from asyncio import FIRST_COMPLETED
from typing import Any, Optional, Tuple
import re


logger = logging.getLogger(__name__)


def _create_mock_response(content: str, model: str):
    class MockMessage:
        def __init__(self, text):
            self.content = text
    class MockChoice:
        def __init__(self, text):
            self.message = MockMessage(text)
    class MockResponse:
        def __init__(self, text, model_name):
            self.choices = [MockChoice(text)]
            self.model = model_name
    return MockResponse(content, model)


async def _timed(coro, seconds: float = 6.0, rl_provider: str = "", rl_model: str = ""):
    try:
        return await asyncio.wait_for(coro, timeout=seconds)
    except asyncio.TimeoutError:
        raise RuntimeError(f"timeout after {seconds}s")
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        detail = str(exc)
        if rl_provider and rl_model and _is_rate_limited_error_str(detail):
            mark_rate_limited(rl_provider, rl_model, detail)
        raise


def _get_provider_config(name: str) -> Optional[dict]:
    for p in PROVIDER_LIST:
        if p["name"] == name:
            return p
    return None


def _is_available(name: str) -> bool:
    swap_mgr = get_swap_manager()
    provider = swap_mgr.providers.get(name)
    return provider.is_available() if provider else True


def _has_key(name: str) -> bool:
    cfg = _get_provider_config(name)
    if not cfg:
        return False
    return cfg["has_key"]()


def _rl_key(provider: str, model: str) -> str:
    """Canonical rate-limit bookkeeping key for a (provider, model) pair.

    Providers without an explicit chain (openrouter, qwen, deepseek, gemini,
    opencode, opencode_zen, openai, pollinations…) are called with model="".
    Cooldowns used to be stored under "<provider>:<provider>" while lookups used
    "<provider>:" and the skip-set used ("<provider>", "") — three different keys,
    so those providers were never actually skipped after a 429.  One key now.
    """
    return model or provider


_PROVIDER_ERROR_MARKERS = (
    "doesn't have enough credits", "not enough credits", "insufficient credit",
    "please top up", "top up", "add funds", "billing required",
    "invalid api key", "incorrect api key", "api key not", "api_key_invalid",
    "key is invalid", "unauthorized", "authentication failed",
    "contact whoever runs the app", "too many requests", "quota exceeded",
    "model not found", "free tier limit", "access denied",
)


def _looks_like_provider_error(content) -> bool:
    """True when a *200 OK* response carried an error payload as its content.

    Free gateways (Pollinations et al.) return 200 with a support blurb such as
    "The account behind this API key doesn't have enough credits… top up…" which
    used to be relayed straight to the user.  Treat it as a failed attempt so the
    orchestrator fails over instead of quoting provider support text at people.
    """
    if not isinstance(content, str):
        return False
    low = content.lower().strip()
    if not low or len(low) > 700:
        return False
    if not any(marker in low for marker in _PROVIDER_ERROR_MARKERS):
        return False
    # Require error-ish framing so a normal reply that merely mentions a rate
    # limit in a sentence is not thrown away.
    return bool(
        "http" in low
        or "please" in low
        or low.startswith((
            "error", "api", "invalid", "request", "the account",
            "your account", "we ", "this model", "sorry", "⚠",
        ))
    )


def _should_skip(name: str, model: str, skip_set: set) -> bool:
    key = _rl_key(name, model)
    if (name, key) in skip_set or (name, model) in skip_set:
        return True
    if check_rate_limit(key, name):
        return True
    return not _is_available(name)


ProviderTask = Tuple[str, asyncio.Task]


async def _race_providers(
    provider_names: list[str],
    messages: list,
    max_tokens: int,
    temperature: float,
    category: str,
    lang: str,
    skip_set: set,
    timeout: float = 6.0,
) -> tuple:
    """Race providers concurrently; the FIRST SUCCESSFUL call wins.

    The old implementation waited for the first *completion* and then cancelled
    everything else, so one provider failing fast (401/402/dead model/timeout)
    aborted the phase and threw away healthy in-flight calls — that is how the
    user ended up seeing provider error text instead of a reply.
    """
    tasks: dict[str, asyncio.Task] = {}
    attempted: list = []
    last_exc = None

    for name in provider_names:
        cfg = _get_provider_config(name)
        if not cfg or not _has_key(name):
            continue

        get_chain = cfg.get("get_model_chain")
        try:
            models = list(get_chain(category, lang)) if get_chain else []
        except Exception as chain_exc:
            attempted.append(f"{name}:chain:{str(chain_exc)[:40]}")
            logger.warning("[ai_model] chain for %s failed: %s", name, chain_exc)
            continue
        models = models[:1] or [""]

        for model in models:
            if _should_skip(name, model, skip_set):
                attempted.append(f"{name}:{_rl_key(name, model)}:rate_limited")
                continue

            async def _call_wrapper(name=name, model=model, cfg=cfg):
                t0 = time.monotonic()
                content, meta = await _timed(
                    cfg["call"](messages, max_tokens, temperature, model=model),
                    seconds=timeout,
                    rl_provider=name,
                    rl_model=_rl_key(name, model),
                )
                if _looks_like_provider_error(content):
                    raise RuntimeError(f"error payload from {name}: {str(content)[:80]}")
                meta = dict(meta or {})
                meta["model"] = meta.get("model") or model or name
                meta["provider"] = name
                meta["latency"] = round(time.monotonic() - t0, 3)
                return content, meta

            task_name = f"{name}:{model or name}"
            while task_name in tasks:
                task_name += "*"
            tasks[task_name] = asyncio.create_task(_call_wrapper())

    if not tasks:
        return None, None, attempted, last_exc

    deadline = time.monotonic() + max(1.0, timeout) + 1.0
    pending: set = set(tasks.values())
    winner = None

    while pending and winner is None:
        left = deadline - time.monotonic()
        if left <= 0:
            break
        done, pending = await asyncio.wait(
            pending, timeout=left, return_when=asyncio.FIRST_COMPLETED
        )
        for t in done:
            if t.cancelled():
                continue
            exc = t.exception()
            if exc is None:
                winner = t
                break
            last_exc = exc
            for task_name, task in tasks.items():
                if task is t:
                    attempted.append(f"{task_name}:{str(exc)[:50]}")
                    logger.debug("[ai_model] Race loser: %s: %s", task_name, str(exc)[:80])
                    break

    if pending:
        for t in pending:
            t.cancel()
        await asyncio.gather(*pending, return_exceptions=True)

    if winner is None:
        return None, None, attempted, last_exc

    for task_name, task in tasks.items():
        if task is winner:
            logger.info("[ai_model] Playlist winner: %s", task_name)
            break
    content, meta = winner.result()
    return _create_mock_response(content, meta.get("model", "")), meta, attempted, None


async def _sequential_fallback(
    provider_names: list[str],
    messages: list,
    max_tokens: int,
    temperature: float,
    category: str,
    lang: str,
    skip_set: set,
    timeout: float = 3.0,
    deadline: Optional[float] = None,
) -> tuple:
    """Walk providers/models one by one.

    ``deadline`` (an absolute ``time.monotonic()`` value) is essential: without
    it a single phase could burn providers × models × timeout seconds and blow
    straight through the caller's budget, which then cancelled everything and
    returned nothing.
    """
    attempted: list = []
    last_exc = None

    for name in provider_names:
        if deadline is not None and time.monotonic() >= deadline:
            logger.info("[ai_model] Sequential fallback hit the budget; stopping")
            break
        cfg = _get_provider_config(name)
        if not cfg or not _has_key(name):
            continue

        get_chain = cfg.get("get_model_chain")
        try:
            models = list(get_chain(category, lang)) if get_chain else []
        except Exception as chain_exc:
            attempted.append(f"{name}:chain:{str(chain_exc)[:40]}")
            continue
        models = models[:3] or [""]

        tried = 0
        for model in models:
            if deadline is not None and time.monotonic() >= deadline:
                break
            if _should_skip(name, model, skip_set):
                attempted.append(f"{name}:{_rl_key(name, model)}:rate_limited")
                continue

            tried += 1
            t0 = time.monotonic()
            try:
                content, meta = await _timed(
                    cfg["call"](messages, max_tokens, temperature, model=model),
                    seconds=timeout,
                    rl_provider=name,
                    rl_model=_rl_key(name, model),
                )
                if _looks_like_provider_error(content):
                    raise RuntimeError(f"error payload from {name}: {str(content)[:80]}")
                logger.info("[ai_model] Playlist fallback: %s:%s", name, model or "")
                meta = dict(meta or {})
                meta["model"] = meta.get("model") or model or name
                meta["provider"] = name
                meta["latency"] = round(time.monotonic() - t0, 3)
                return _create_mock_response(content, meta["model"]), meta, attempted, None
            except Exception as exc:
                detail = str(exc)
                last_exc = exc
                attempted.append(f"{name}:{model or ''}:{detail[:50]}")
                logger.warning("[ai_model] %s %s failed: %s", name, model or "", detail[:100])
                if _is_rate_limited_error_str(detail):
                    match = re.search(r"retry after\s*[:=]?\s*(\d+)", detail, re.IGNORECASE)
                    retry_after = int(match.group(1)) if match else 60
                    set_cooldown(_rl_key(name, model), name, retry_after)
                continue

        if tried:
            # Demote only after really hammering the provider — every model being
            # on cooldown is not a provider-level failure and must not demote it.
            get_swap_manager().demote_provider(name)

    return None, None, attempted, last_exc


async def chat_completion(
    messages: list[dict],
    *,
    category: str = "chat",
    lang: str = "english",
    max_tokens: int = 180,
    temperature: float = 0.88,
    budget: float = 10.0,
) -> Tuple[Any, dict]:
    """Smart multi-provider AI with auto-priority and aggressive retry.

    All four phases draw from one wall-clock ``budget`` (seconds).  Callers wrap
    this in ``asyncio.wait_for(..., 12)``; previously the phases could
    legitimately need 40s+ (6s race + 5s race + N×4s sequential + 20s
    Pollinations), so the caller cancelled the whole attempt and the user got
    no reply at all.

    Strategy:
    1. Race the top providers — first SUCCESS wins
    2. Race the remaining providers
    3. Sequential fallback through every provider × model
    4. Pollinations as last resort
    """
    attempted: list = []
    last_exc = None
    swap_mgr = get_swap_manager()

    for name in PRIORITY_ORDER:
        if name not in swap_mgr.providers:
            swap_mgr.register_provider(name)

    swap_mgr.try_recover_providers()
    start_cleanup_task(interval_seconds=30.0)
    skip_set = get_skip_set()

    # Get auto-priority order (Groq always first, then sorted by speed/success)
    base_order = ["groq", "nvidia", "opencode", "cerebras", "openrouter",
                  "opencode_zen", "qwen", "openai", "deepseek", "gemini"]
    priority_order = _ai_priority.get_priority_order(base_order)
    # Ensure Groq is always first
    if "groq" in priority_order:
        priority_order.remove("groq")
    priority_order.insert(0, "groq")

    deadline = time.monotonic() + max(3.0, float(budget))

    def _left() -> float:
        return deadline - time.monotonic()

    # Phase 1: Race top providers (fast timeout)
    left = _left()
    if left > 0.75:
        response, meta, att, exc = await _race_providers(
            priority_order[:7], messages, max_tokens, temperature,
            category, lang, skip_set, timeout=max(1.5, min(6.0, left - 0.75)),
        )
        attempted.extend(att)
        if response is not None:
            _ai_priority.record_success(meta.get("provider", ""), meta.get("latency", 3.0))
            return response, {**meta, "attempted": attempted}
        last_exc = exc or last_exc

    # Phase 2: Race remaining providers
    left = _left()
    if left > 0.75 and len(priority_order) > 7:
        response, meta, att, exc = await _race_providers(
            priority_order[7:], messages, max_tokens, temperature,
            category, lang, skip_set, timeout=max(1.5, min(5.0, left - 0.75)),
        )
        attempted.extend(att)
        if response is not None:
            _ai_priority.record_success(meta.get("provider", ""), meta.get("latency", 4.0))
            return response, {**meta, "attempted": attempted}
        last_exc = exc or last_exc

    # Phase 3: Sequential through ALL providers, ALL models (aggressive retry)
    left = _left()
    if left > 1.0:
        response, meta, att, exc = await _sequential_fallback(
            priority_order + ["pollinations"], messages, max_tokens, temperature,
            category, lang, skip_set, timeout=max(1.5, min(4.0, left - 0.75)),
            deadline=deadline,
        )
        attempted.extend(att)
        if response is not None:
            _ai_priority.record_success(meta.get("provider", ""), meta.get("latency", 5.0))
            return response, {**meta, "attempted": attempted}
        last_exc = exc or last_exc

    # Phase 4: Last resort — Pollinations (free, no auth)
    left = _left()
    if left > 2.0:
        try:
            t0 = time.monotonic()
            content, meta = await asyncio.wait_for(
                call_pollinations(messages, max_tokens, temperature),
                timeout=left,
            )
            if _looks_like_provider_error(content):
                raise RuntimeError(f"error payload from pollinations: {str(content)[:80]}")
            meta = dict(meta or {})
            meta["model"] = meta.get("model") or "pollinations"
            meta["provider"] = "pollinations"
            meta["latency"] = round(time.monotonic() - t0, 3)
            _ai_priority.record_success("pollinations", meta["latency"])
            return _create_mock_response(content, meta["model"]), meta, attempted, None
        except Exception as pol_exc:
            attempted.append(f"pollinations:{pol_exc}")
            _ai_priority.record_failure("pollinations")
            last_exc = pol_exc or last_exc

    # Record failures for all attempted providers
    for att_item in attempted:
        prov_name = att_item.split(":")[0] if ":" in att_item else att_item
        _ai_priority.record_failure(prov_name)

    if last_exc:
        logger.error("[ai_model] All models failed. Attempted: %s", attempted)
        raise last_exc
    raise RuntimeError("No AI models available right now")


def get_all_model_status() -> dict:
    swap_mgr = get_swap_manager()
    swap_mgr.try_recover_providers()

    for name in PRIORITY_ORDER:
        if name not in swap_mgr.providers:
            swap_mgr.register_provider(name)

    # Lazy provider configs are only populated on first use — without this the
    # status panel reported empty/blank model names for every provider.
    for _lazy in (
        _lazy_config_groq, _lazy_config_nvidia, _lazy_config_cerebras,
        _lazy_config_qwen, _lazy_config_opencode, _lazy_config_opencode_zen,
        _lazy_config_openrouter, _lazy_config_openai, _lazy_config_deepseek,
        _lazy_config_gemini,
    ):
        try:
            _lazy()
        except Exception:
            pass

    status = {}
    for name in PRIORITY_ORDER:
        cfg = _get_provider_config(name)
        if not cfg:
            continue
        entry = {
            "available": _has_key(name) and _is_available(name),
            "status": swap_mgr.get_provider_status(name),
        }
        if name == "groq":
            _groq_chain = groq__GROQ_MODEL_CHAINS.get(
                "chat_default", groq__GROQ_MODEL_CHAINS.get("chat_default", [])
            )
            entry["models"] = list(_groq_chain)[:4]
            entry["model"] = ", ".join(list(_groq_chain)[:2]) or MODEL_NAME
        elif name == "nvidia":
            entry["model"] = nvidia__NVIDIA_MODEL
        elif name == "opencode_zen":
            entry["model"] = "random-free"
        elif name == "qwen":
            entry["model"] = qwen__QWEN_MODEL
            entry["endpoint"] = QWEN_ENDPOINT
        elif name == "openai":
            entry["model"] = "gpt-4o-mini"
        elif name == "opencode":
            entry["model"] = "free-auto"
        elif name == "deepseek":
            entry["model"] = DEEPSEEK_MODEL
        elif name == "gemini":
            entry["model"] = GEMINI_MODEL
        elif name == "cerebras":
            entry["model"] = cerebras__CEREBRAS_MODEL
        elif name == "openrouter":
            entry["model"] = "auto"
        status[name] = entry

    status["priority_order"] = list(PRIORITY_ORDER)
    status["recent_errors"] = swap_mgr.get_error_summary()[-5:]
    return status


def reset_all_model_limits():
    for name in PRIORITY_ORDER:
        cfg = _get_provider_config(name)
        if cfg and _has_key(name):
            reset_model_limits(name, name)
    swap_mgr = get_swap_manager()
    for provider in swap_mgr.providers:
        swap_mgr.reset_provider(provider)
    logger.info("[ai_model] All model limits reset")

# ═══ MODULE: system.ai.smart_discover ═══
# Smart auto-discovery: finds working chat models from each provider at startup.
# Filters out guard/voice/TTS/embedding models, tests a sample, stores results.

import asyncio as _sd_asyncio
import time as _sd_time

_DISCOVERED_MODELS: dict[str, list[str]] = {}
_DISCOVERED_AT: float = 0
_DISCOVER_LOCK = asyncio.Lock()

# Models to EXCLUDE from chat chains (not chat-capable)
_MODEL_EXCLUDE_PATTERNS = (
    "guard", "safeguard", "whisper", "orpheus", "tts", "embed",
    "audio", "vision", "image", "dall-e", "stable-diffusion",
    "compound", "prompt-guard",
)

# Minimum models to keep per provider after filtering
_MIN_CHAT_MODELS = 2


def _is_chat_model(model_id: str) -> bool:
    """Check if a model ID looks like a chat model (not guard/voice/TTS/etc)."""
    lower = model_id.lower()
    return not any(pat in lower for pat in _MODEL_EXCLUDE_PATTERNS)


async def _discover_groq_models() -> list[str]:
    """Fetch and filter chat models from Groq."""
    if not GROQ_API_KEY:
        return []
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            headers = {"Authorization": f"Bearer {GROQ_API_KEY}"}
            async with session.get("https://api.groq.com/openai/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    chat_models = [m for m in models if _is_chat_model(m)]
                    chat_models.sort()
                    if chat_models:
                        logger.info(f"[discover] Groq: {len(chat_models)} chat models found")
                    return chat_models
    except Exception as e:
        logger.debug(f"[discover] Groq fetch failed: {e}")
    return []


async def _discover_nvidia_models() -> list[str]:
    """Fetch and filter chat models from NVIDIA."""
    if not NVIDIA_API_KEY:
        return []
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            headers = {"Authorization": f"Bearer {NVIDIA_API_KEY}"}
            async with session.get("https://integrate.api.nvidia.com/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    chat_models = [m for m in models if _is_chat_model(m) and "instruct" in m.lower()]
                    chat_models.sort()
                    if chat_models:
                        logger.info(f"[discover] NVIDIA: {len(chat_models)} chat models found")
                    return chat_models
    except Exception as e:
        logger.debug(f"[discover] NVIDIA fetch failed: {e}")
    return []


async def _discover_gemini_models() -> list[str]:
    """Fetch and filter chat models from Gemini."""
    if not GEMINI_API_KEY:
        return []
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            headers = {"x-goog-api-key": GEMINI_API_KEY}
            async with session.get(
                "https://generativelanguage.googleapis.com/v1beta/models", headers=headers
            ) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [
                        m["name"].replace("models/", "")
                        for m in data.get("models", [])
                        if m.get("name", "").startswith("models/gemini-")
                        and "generateContent" in m.get("supportedGenerationMethods", [])
                    ]
                    models.sort()
                    if models:
                        logger.info(f"[discover] Gemini: {len(models)} chat models found")
                    return models
    except Exception as e:
        logger.debug(f"[discover] Gemini fetch failed: {e}")
    return []


async def _discover_cerebras_models() -> list[str]:
    """Fetch live chat models from Cerebras so retired IDs never stick."""
    if not CEREBRAS_API_KEY:
        return []
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}"}
            async with session.get("https://api.cerebras.ai/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    chat_models = [m for m in models if _is_chat_model(m)]
                    pref = ("qwen-3.8-27b", "gpt-oss-120b",
                            "llama-3.3-70b", "zai-glm-4.7")
                    def _rank(m: str) -> tuple:
                        ml = m.lower()
                        for i, p in enumerate(pref):
                            if p in ml:
                                return (0, i, m)
                        return (1, 99, m)
                    chat_models.sort(key=_rank)
                    if chat_models:
                        logger.info(f"[discover] Cerebras: {len(chat_models)} chat models, top={chat_models[0]}")
                    return chat_models
    except Exception as e:
        logger.debug(f"[discover] Cerebras fetch failed: {e}")
    return []


async def _discover_deepseek_models() -> list[str]:
    """Fetch chat models from DeepSeek."""
    if not DEEPSEEK_API_KEY:
        return []
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            headers = {"Authorization": f"Bearer {DEEPSEEK_API_KEY}"}
            async with session.get("https://api.deepseek.com/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    chat_models = [m for m in models if _is_chat_model(m)]
                    chat_models.sort()
                    if chat_models:
                        logger.info(f"[discover] DeepSeek: {len(chat_models)} chat models found")
                    return chat_models
    except Exception as e:
        logger.debug(f"[discover] DeepSeek fetch failed: {e}")
    return []


async def auto_discover_models() -> dict[str, list[str]]:
    """Query all providers for available chat models. Returns {provider: [models]}."""
    global _DISCOVERED_MODELS, _DISCOVERED_AT

    async with _DISCOVER_LOCK:
        # Don't re-discover if done recently (5 min cache)
        if _DISCOVERED_MODELS and (_sd_time.time() - _DISCOVERED_AT < 300):
            return dict(_DISCOVERED_MODELS)

        logger.info("[discover] Auto-discovering chat models from all providers...")

        # Run each provider discovery with individual timeouts
        async def _safe_discover(name, fn):
            try:
                return await _sd_asyncio.wait_for(fn(), timeout=8.0)
            except Exception as e:
                logger.debug(f"[discover] {name} failed: {e}")
                return []

        results = await _sd_asyncio.gather(
            _safe_discover("groq", _discover_groq_models),
            _safe_discover("nvidia", _discover_nvidia_models),
            _safe_discover("gemini", _discover_gemini_models),
            _safe_discover("cerebras", _discover_cerebras_models),
            _safe_discover("deepseek", _discover_deepseek_models),
        )

        providers = ["groq", "nvidia", "gemini", "cerebras", "deepseek"]
        for name, result in zip(providers, results):
            _DISCOVERED_MODELS[name] = result

        _DISCOVERED_AT = _sd_time.time()
        total = sum(len(v) for v in _DISCOVERED_MODELS.values())
        active = sum(1 for v in _DISCOVERED_MODELS.values() if v)
        logger.info(f"[discover] Done: {total} chat models across {active} providers")
        return dict(_DISCOVERED_MODELS)


def get_discovered_models(provider: str) -> list[str]:
    """Get auto-discovered models for a provider. Empty if not discovered yet."""
    return _DISCOVERED_MODELS.get(provider, [])


def _build_groq_chain_from_discovered() -> dict[str, list[str]]:
    """Build Groq model chains from auto-discovered models."""
    models = get_discovered_models("groq")
    if not models:
        return {}
    # Prefer quality models first, then fast (live Groq catalog, Sept 2026)
    quality = [m for m in models if "120b" in m or "3.8" in m or "3.6" in m]
    fast = [m for m in models if "20b" in m or "mini" in m or "allam" in m]
    arabic = [m for m in models if "allam" in m or "arabic" in m]
    guard = [m for m in models if "guard" in m or "safeguard" in m]

    def _chain(primary: list[str], fallback: list[str]) -> list[str]:
        seen = set()
        chain = []
        for m in primary + fallback + models:
            if m not in seen:
                seen.add(m)
                chain.append(m)
        return chain[:6]

    default = _chain(quality, fast)
    return {
        "chat_default": default,
        "chat_fast": _chain(fast, quality),
        "chat_reasoning": _chain(quality, fast),
        "chat_arabic": _chain(arabic, quality),
        "guard": guard[:3] if guard else ["openai/gpt-oss-safeguard-20b"],
        "tooling": [m for m in models if "compound" in m][:1] or ["openai/gpt-oss-20b"],
    }


def _build_nvidia_chain_from_discovered() -> dict[str, list[str]]:
    """Build NVIDIA model chains from auto-discovered models."""
    models = get_discovered_models("nvidia")
    if not models:
        return {}
    quality = [m for m in models if "70b" in m or "super" in m or "ultra" in m]
    fast = [m for m in models if "8b" in m or "lightning" in m or "mini" in m]

    def _chain(primary: list[str], fallback: list[str]) -> list[str]:
        seen = set()
        chain = []
        for m in primary + fallback + models:
            if m not in seen:
                seen.add(m)
                chain.append(m)
        return chain[:4]

    default = _chain(quality, fast)
    return {
        "chat_default": default,
        "chat_fast": _chain(fast, quality),
        "chat_reasoning": _chain(quality, fast),
        "chat_arabic": _chain(quality, fast),
    }


