# ── Model list cache (TTL 60s) ──────────────────────────────────────────
_MODEL_CACHE: dict[str, tuple[float, list[str]]] = {}
_MODEL_CACHE_TTL = 60


def _get_cached_models(provider: str) -> list[str] | None:
    entry = _MODEL_CACHE.get(provider)
    if entry and time.time() - entry[0] < _MODEL_CACHE_TTL:
        return entry[1]
    return None


def _set_cached_models(provider: str, models: list[str]) -> None:
    _MODEL_CACHE[provider] = (time.time(), models)


async def _get_models(provider: str) -> list[str]:
    cached = _get_cached_models(provider)
    if cached is not None:
        return cached
    if provider == "groq":
        models = await _fetch_groq_models()
    elif provider == "openrouter":
        try:
            models = await fetch_opencode_free_models()
        except Exception:
            models = []
    elif provider == "gemini":
        models = await _fetch_gemini_models()
    elif provider == "deepseek":
        models = await _fetch_deepseek_models()
    elif provider == "openai":
        models = await _fetch_openai_models()
    else:
        models = KNOWN_MODELS.get(provider, [])
    # Never offer guard/whisper/TTS/embedding IDs for a chat pick — calling one
    # through force mode always fails with a provider error.
    models = [m for m in (models or []) if _is_chat_model(m)]
    if models:
        _set_cached_models(provider, models)
    return models


