# ── Helpers ───────────────────────────────────────────────────────────────

async def _fetch_groq_models() -> list[str]:
    """Fetch available models from Groq API."""
    if not GROQ_API_KEY:
        return KNOWN_MODELS.get("groq", [])
    try:
        async with aiohttp.ClientSession(timeout=10) as session:
            headers = {"Authorization": f"Bearer {GROQ_API_KEY}"}
            async with session.get("https://api.groq.com/openai/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    models.sort()
                    return models if models else KNOWN_MODELS.get("groq", [])
    except Exception as e:
        logger.debug(f"Failed to fetch Groq models: {e}")
    return KNOWN_MODELS.get("groq", [])


async def _fetch_gemini_models() -> list[str]:
    """Fetch available models from Gemini API."""
    if not GEMINI_API_KEY:
        return KNOWN_MODELS.get("gemini", [])
    try:
        async with aiohttp.ClientSession(timeout=10) as session:
            headers = {"x-goog-api-key": GEMINI_API_KEY}
            async with session.get(
                "https://generativelanguage.googleapis.com/v1beta/models",
                headers=headers,
            ) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [
                        m["name"].replace("models/", "")
                        for m in data.get("models", [])
                        if m.get("name", "").startswith("models/gemini-")
                        and "generateContent" in m.get("supportedGenerationMethods", [])
                    ]
                    models.sort()
                    return models if models else KNOWN_MODELS.get("gemini", [])
    except Exception as e:
        logger.debug(f"Failed to fetch Gemini models: {e}")
    return KNOWN_MODELS.get("gemini", [])


async def _fetch_deepseek_models() -> list[str]:
    """Fetch available models from DeepSeek API."""
    if not DEEPSEEK_API_KEY:
        return KNOWN_MODELS.get("deepseek", [])
    try:
        async with aiohttp.ClientSession(timeout=10) as session:
            headers = {
                "Authorization": f"Bearer {DEEPSEEK_API_KEY}",
                "Accept": "application/json",
            }
            async with session.get("https://api.deepseek.com/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    models.sort()
                    return models if models else KNOWN_MODELS.get("deepseek", [])
    except Exception as e:
        logger.debug(f"Failed to fetch DeepSeek models: {e}")
    return KNOWN_MODELS.get("deepseek", [])


async def _fetch_openai_models() -> list[str]:
    """Fetch available models from OpenAI API."""
    if not OPENAI_API_KEY:
        return KNOWN_MODELS.get("openai", [])
    try:
        async with aiohttp.ClientSession(timeout=10) as session:
            headers = {"Authorization": f"Bearer {OPENAI_API_KEY}"}
            async with session.get("https://api.openai.com/v1/models", headers=headers) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    models = [m["id"] for m in data.get("data", []) if m.get("id")]
                    models.sort()
                    return models if models else KNOWN_MODELS.get("openai", [])
    except Exception as e:
        logger.debug(f"Failed to fetch OpenAI models: {e}")
    return KNOWN_MODELS.get("openai", [])


def _paginate(items: list[str], page: int, per_page: int = MODELS_PER_PAGE) -> list[str]:
    """Get a page of items."""
    start = page * per_page
    return items[start:start + per_page]


def _total_pages(items: list[str], per_page: int = MODELS_PER_PAGE) -> int:
    return max(1, (len(items) + per_page - 1) // per_page)


def _check_provider_enabled(name: str) -> bool:
    """Check if a provider has its API key configured."""
    if name == "groq":
        return bool(GROQ_API_KEY)
    if name == "openrouter":
        return bool(OPENROUTER_API_KEY)
    if name == "gemini":
        return bool(GEMINI_API_KEY)
    if name == "deepseek":
        return bool(DEEPSEEK_API_KEY)
    if name == "openai":
        return bool(OPENAI_API_KEY)
    return True


