# ── Owner Error Reporting for Force Mode ─────────────────────────────────

async def report_force_error_once(chat_id: int, bot, error_type: str, error_detail: str) -> None:
    """Report a force-mode error to owner, deduplicated (once per 5 min per error type)."""
    global _force_error_cache
    now = time.time()
    chat_errors = _force_error_cache.get(chat_id, {})
    last_sent = chat_errors.get(error_type, 0)
    if now - last_sent < _FORCE_ERROR_TTL:
        return
    chat_errors[error_type] = now
    _force_error_cache[chat_id] = chat_errors
    try:
        await bot.send_message(
            OWNER_ID,
            f"⚠️ <b>[Force Mode] Error ({html.escape(error_type)})</b>\n"
            f"Chat: <code>{chat_id}</code>\n"
            f"Detail: <code>{html.escape(error_detail[:200])}</code>",
            parse_mode="HTML",
        )
    except Exception as e:
        logger.debug(f"Failed to report force error: {e}")


# ── UI Builders ──────────────────────────────────────────────────────────

async def _build_main_menu(chat_id: int) -> str:
    """Build main menu text showing current config."""
    provider = await _get_provider(chat_id)
    model = await _get_model(chat_id)
    chain_cat = await _get_chain_cat(chat_id)
    force_on = await _get_force_on(chat_id)
    mode_label = "🔴 FORCE ON" if force_on else "🟢 Default Chain"
    provider_label = PROVIDER_LABELS.get(provider, "Auto")
    icon = PROVIDER_ICONS.get(provider, "🤖")
    model_label = model or "Auto-select"
    chain_label = chain_cat.replace("chat_", "").replace("_", " ").title() if not provider or provider == "chain" else ""
    global_provider = await asyncio.to_thread(get_setting, "ai_global_provider", "")
    global_model = await asyncio.to_thread(get_setting, "ai_global_model", "")
    global_info = ""
    if global_provider and global_model:
        global_info = f"\n🌐 <b>System:</b> {PROVIDER_ICONS.get(global_provider, '')} {html.escape(PROVIDER_LABELS.get(global_provider, global_provider))} / <code>{html.escape(global_model)}</code>"

    # Get new settings
    personality = await asyncio.to_thread(get_setting, f"ai_personality:{chat_id}", "")
    if not personality:
        personality = await asyncio.to_thread(get_setting, "ai_global_personality", "cute")
    length = await asyncio.to_thread(get_setting, f"ai_length:{chat_id}", "")
    if not length:
        length = await asyncio.to_thread(get_setting, "ai_global_length", "medium")
    language = await asyncio.to_thread(get_setting, f"ai_language:{chat_id}", "")
    if not language:
        language = await asyncio.to_thread(get_setting, "ai_global_language", "auto")
    stickers = await asyncio.to_thread(get_setting, f"ai_stickers:{chat_id}", "")
    if not stickers:
        stickers = await asyncio.to_thread(get_setting, "ai_global_stickers", "on")

    personality_icons = {"cute": "🌸", "sassy": "💅", "chill": "😎", "romantic": "💕", "serious": "🧐", "funny": "😂"}
    length_icons = {"short": "⚡", "medium": "💬", "long": "📝"}
    lang_icons = {"auto": "🔄", "hindi": "🇮🇳", "english": "🇬🇧", "hinglish": "💫", "urdu": "🌙"}

    text = (
        f"🤖 <b>AI Model Config</b>\n"
        f"{'─' * 30}\n"
        f"{global_info}\n\n"
        f"<b>Provider:</b> {icon} {html.escape(provider_label)}\n"
        f"<b>Model:</b> <code>{html.escape(model_label)}</code>\n"
    )
    if chain_label and (not provider or provider == "chain"):
        text += f"<b>Chain:</b> <code>{html.escape(chain_label)}</code>\n"
    text += f"<b>Mode:</b> {mode_label}\n\n"
    # Get emoji and group settings
    emojis = await asyncio.to_thread(get_setting, f"ai_emojis:{chat_id}", "")
    if not emojis:
        emojis = await asyncio.to_thread(get_setting, "ai_global_emojis", "on")
    group_ai = await asyncio.to_thread(get_setting, f"ai_group_{chat_id}", "on")

    text += f"<b>🎭 Personality:</b> {personality_icons.get(personality, '🌸')} {personality.title()}\n"
    text += f"<b>📏 Length:</b> {length_icons.get(length, '💬')} {length.title()}\n"
    text += f"<b>🌐 Language:</b> {lang_icons.get(language, '🔄')} {language.title()}\n"
    text += f"<b>🎨 Stickers:</b> {'🟢 ON' if stickers == 'on' else '🔴 OFF'}\n"
    text += f"<b>😊 Emojis:</b> {'🟢 ON' if emojis == 'on' else '🔴 OFF'}\n"
    text += f"<b>👥 Group AI:</b> {'🟢 ON' if group_ai == 'on' else '🔴 OFF'}\n\n"
    text += f"<i>Configure all AI settings below.</i>"
    return text


