async def _build_force_text(chat_id: int) -> str:
    force_on = await _get_force_on(chat_id)
    provider = await _get_provider(chat_id)
    model = await _get_model(chat_id)
    status = "🔴 <b>ENABLED</b>" if force_on else "⚪ <b>DISABLED</b>"
    pinned = f"<code>{html.escape(model)}</code>" if model else "<code>Auto-select</code>"
    name = html.escape(PROVIDER_LABELS.get(provider, "Auto"))
    text = (
        f"⚪ <b>Force Mode</b>\n"
        f"{'─' * 30}\n\n"
        f"Status: {status}\n"
        f"Provider: {name}\n"
        f"Model: {pinned}\n\n"
    )
    if force_on:
        text += (
            "When Force Mode is <b>ON</b>:\n"
            "• Bot uses ONLY the selected provider + model\n"
            "• No automatic fallback to other providers\n"
            "• Errors are reported to owner once (silent after)\n"
            "• User gets a gentle retry message instead of errors\n\n"
            "<i>Recommended when you want a specific model to handle all replies.</i>"
        )
    else:
        text += (
            "When Force Mode is <b>OFF</b>:\n"
            "• Bot auto-selects best provider/model\n"
            "• Falls back through all providers on errors\n"
            "• Default chain = Groq → OpenRouter → Gemini → DeepSeek\n"
        )
    return text


