async def _build_model_text(chat_id: int, provider: str, page: int, models: list[str]) -> str:
    total = _total_pages(models)
    selected_model = await _get_model(chat_id)
    current_provider = await _get_provider(chat_id)
    icon = PROVIDER_ICONS.get(provider, "🤖")
    name = html.escape(PROVIDER_LABELS.get(provider, provider.title()))
    text = (
        f"{icon} <b>{name} Models</b>\n"
        f"{'─' * 30}\n\n"
    )
    if provider == "openrouter":
        text += f"Showing free models (Page {page + 1}/{total})\n\n"
    else:
        text += f"Page {page + 1}/{total}\n\n"
    if current_provider == provider and selected_model:
        text += f"Currently selected: <code>{html.escape(selected_model)}</code>\n\n"
    return text


def _build_model_keyboard(provider: str, page: int, models: list[str]) -> InlineKeyboardMarkup:
    page_models = _paginate(models, page)
    total = _total_pages(models)
    rows = []
    for i in range(0, len(page_models), MODELS_PER_ROW):
        row = page_models[i:i + MODELS_PER_ROW]
        btn_row = []
        for j, m in enumerate(row):
            idx = page * MODELS_PER_PAGE + i + j
            btn_row.append(
                InlineKeyboardButton(m[:25], callback_data=f"aimodel_pick_{provider}_{idx}")
            )
        rows.append(btn_row)
    nav_row = []
    if page > 0:
        nav_row.append(InlineKeyboardButton("◀️", callback_data=f"aimodel_page_{provider}_{page - 1}"))
    nav_row.append(InlineKeyboardButton(f"{page + 1}/{total}", callback_data="aimodel_noop"))
    if page < total - 1:
        nav_row.append(InlineKeyboardButton("▶️", callback_data=f"aimodel_page_{provider}_{page + 1}"))
    if nav_row:
        rows.append(nav_row)
    if provider in ("groq", "openrouter", "gemini", "deepseek", "openai"):
        rows.append([InlineKeyboardButton(f"🔄 Refresh {PROVIDER_LABELS.get(provider, provider)} models", callback_data=f"aimodel_refresh_{provider}")])
    rows.append([InlineKeyboardButton("🔙 Back", callback_data="aimodel_main")])
    return InlineKeyboardMarkup(rows)


