async def _build_status_text() -> str:
    """Build AI provider status text."""
    statuses = await asyncio.to_thread(get_all_model_status)
    lines = ["📊 <b>AI Provider Status</b>", "─" * 30, ""]
    for provider, info in statuses.items():
        if provider in ("priority_order", "recent_errors"):
            continue
        icon = PROVIDER_ICONS.get(provider, "❓")
        label = PROVIDER_LABELS.get(provider, provider.title())
        ok = info.get("available", False)
        status_icon = "✅" if ok else "❌"
        model = info.get("model", "")
        sinfo = info.get("status", {}) or {}
        if isinstance(sinfo, dict):
            status = "available" if sinfo.get("available", True) else "unavailable"
            if sinfo.get("cooldown_remaining", 0):
                status += f" · cooldown {_fmt_time(sinfo['cooldown_remaining'])}"
            if sinfo.get("error_count"):
                status += f" · {sinfo['error_count']} errors"
            if sinfo.get("total_requests"):
                status += f" · {sinfo.get('success_rate', 0)}% ok"
        else:
            status = str(sinfo)
        lines.append(f"{icon} <b>{html.escape(label)}</b> {status_icon}")
        if model:
            lines.append(f"   Model: <code>{html.escape(str(model))}</code>")
        lines.append(f"   Status: {html.escape(str(status))}")
        lines.append("")
    recent = statuses.get("recent_errors", [])
    if recent:
        lines.append("─" * 30)
        lines.append("<b>Recent Errors</b>")
        for err in recent[-5:]:
            lines.append(f"• <code>{html.escape(str(err)[:80])}</code>")
    return "\n".join(lines)


