# ═══ MODULE: system.security ═══

# =========================================
# 🔐 SECURITY — system/security.py  v4.0
# - Persistent ban cache loaded from DB
# - Security audit logging
# =========================================
import time
import threading
from collections import deque
import concurrent.futures
import collections

logger = get_logger(__name__)

_banned_cache: set = set()
_bans_loaded = False
# Use a deque with maxlen for automatic cleanup of audit log
_audit_log = deque(maxlen=10000)
_executor = concurrent.futures.ThreadPoolExecutor(max_workers=16)
_last_bans_load_failure = 0
_BANS_RETRY_INTERVAL = 60  # seconds
_USER_LAST_LOCK = threading.Lock()
_BAN_CACHE_LOCK = threading.RLock()


def _run_with_timeout(func, *args, timeout=5, **kwargs):
    future = _executor.submit(func, *args, **kwargs)
    return future.result(timeout=timeout)


def _load_bans() -> None:
    """Load ban cache using fast indexed queries."""
    global _bans_loaded
    with _BAN_CACHE_LOCK:
        _bans_loaded = False  # Reset before attempt
        try:
            # FAST: Use indexed query instead of full iteration
            try:
                banned_uids = _run_with_timeout(_fast_get_banned_users, timeout=5)
                for uid in banned_uids:
                    _banned_cache.add(str(uid))  # Store as string for consistency
                _bans_loaded = True
                logger.info(f"✅ Ban cache loaded: {len(_banned_cache)} users")
            except Exception:
                logger.warning("⚠️ Fast ban load failed, using fallback", exc_info=True)
                # Fallback: old method (slow but compatible)
                for uid, doc in list_all_users():
                    if doc.get("banned") or doc.get("silent_ban"):
                        _banned_cache.add(str(uid))  # Store as string for consistency
                _bans_loaded = True
        except Exception:
            logger.error("⚠️ Ban cache load failed", exc_info=True)
            _bans_loaded = False
            raise  # Re-raise to allow caller to handle retry backoff


def _ensure_bans_loaded() -> None:
    global _bans_loaded, _last_bans_load_failure
    with _BAN_CACHE_LOCK:
        if _bans_loaded:
            return
        # Backoff if recent failure
        if time.time() - _last_bans_load_failure < _BANS_RETRY_INTERVAL:
            return
        try:
            _load_bans()
        except Exception:
            _last_bans_load_failure = time.time()
            logger.error("Ban load failed, skipping retry", exc_info=True)
            return


def is_bot_use_banned(uid: int) -> bool:
    """
    Check if a user is banned. Fast path: cache check (O(1), no DB).
    Slow path: only hits DB on first check of a non-banned user, then caches.

    NOTE: Called from AI hot path. The function is thread-safe but blocks
    the calling thread for DB I/O on cache miss. Callers that want
    zero-blocking behavior should use `is_banned_fast()` first.
    """
    if uid == OWNER_ID:
        return False
    if is_banned_fast(uid):
        return True
    _ensure_bans_loaded()
    with _BAN_CACHE_LOCK:
        uid_str = str(uid)
        if uid_str in _banned_cache:
            return True
        try:
            d = _run_with_timeout(get_user, uid_str, timeout=5) or {}
        except Exception:
            logger.error("DB error checking ban", exc_info=True)
            return True  # fail secure: assume banned when DB unreachable
        if d.get("banned") or d.get("silent_ban"):
            _banned_cache.add(uid_str)  # Store as string for consistency
            return True
        return False


# ── Lock-free fast ban check ──────────────────────────────────────────────
# Use this from the AI hot path. Returns True if we KNOW the user is banned
# (cache hit). Returns False if we DON'T KNOW (cache miss). The caller can
# decide to do a full check in the background or accept the risk.
def is_banned_fast(uid: int) -> bool:
    """O(1) cache-only ban check. False = unknown, not necessarily allowed."""
    if uid == OWNER_ID:
        return False
    # _banned_cache is a set, reading from a set is atomic in CPython
    return str(uid) in _banned_cache


def is_banned_cached(uid: int) -> bool:
    """
    Cached ban check that consults the cache first, then USER_CACHE.
    Avoids DB hits for users we've already loaded.
    """
    if uid == OWNER_ID:
        return False
    if is_banned_fast(uid):
        return True
    # Fall back to USER_CACHE (in-memory) to avoid DB
    try:
        cached = USER_CACHE.get(str(uid)) or {}
        if cached.get("banned") or cached.get("silent_ban"):
            with _BAN_CACHE_LOCK:
                _banned_cache.add(str(uid))
            return True
    except Exception:
        pass
    return False


def ban_user(uid: int, reason: str = "violation") -> bool:
    with _BAN_CACHE_LOCK:
        try:
            success = _run_with_timeout(update_user_atomic, uid, set_fields={"banned": True, "ban_reason": reason, "silent_ban": False, "gbanned": False, "group_banned": False}, timeout=5)
            if success:
                _banned_cache.add(str(uid))
                _audit_log.append({"t": time.time(), "uid": uid, "action": "ban", "reason": reason})
                return True
            return False
        except Exception:
            logger.error("Failed to ban", exc_info=True)
            return False


def unban_user(uid: int, reason: str = "unban") -> bool:
    with _BAN_CACHE_LOCK:
        try:
            success = _run_with_timeout(update_user_atomic, uid, set_fields={"banned": False, "ban_reason": None, "silent_ban": False, "gbanned": False, "group_banned": False}, timeout=5)
            if success:
                _banned_cache.discard(str(uid))
                _audit_log.append({"t": time.time(), "uid": uid, "action": "unban", "reason": reason})
                return True
            return False
        except Exception:
            logger.error("Failed to unban", exc_info=True)
            return False


_USER_LAST: dict = {}
_USER_LAST_TRIM_COUNT = 0
_USER_LAST_MAX = 100000

def private_spam_triggered(uid: int, ts: float) -> bool:
    global _USER_LAST_TRIM_COUNT
    with _USER_LAST_LOCK:
        last = _USER_LAST.get(uid, 0)
        _USER_LAST[uid] = ts
        _USER_LAST_TRIM_COUNT += 1
        if _USER_LAST_TRIM_COUNT > 2000:
            _USER_LAST_TRIM_COUNT = 0
            excess = len(_USER_LAST) - _USER_LAST_MAX
            if excess > 0:
                oldest = sorted(_USER_LAST.items(), key=lambda kv: kv[1])[:excess + 10000]
                for k, _ in oldest:
                    _USER_LAST.pop(k, None)
        return (ts - last) < 0.5


def get_audit_log() -> list:
    """Get recent security audit events"""
    with _BAN_CACHE_LOCK:
        # Convert deque to list for compatibility
        return list(_audit_log)[-100:] if len(_audit_log) > 100 else list(_audit_log)

