def _is_word_abuse(token: str) -> bool:
    """
    Whole-word check: returns True only if the token IS an abuse word,
    not if it merely contains one as a substring.
    "good" → False (does not contain abuse as whole word)
    "bohot" → False (does not contain "hoot" as whole word)
    "madarchod" → True (exact match)
    Tokens are split on whitespace and punctuation.
    """
    if not token:
        return False
    lower = token.lower()
    # Strip punctuation from both ends for matching, but keep original
    # intact for the regex boundary check.
    stripped = lower.strip(".,!?;:()[]{}\"'`*/\\|<>@#$%^&_+-=")
    if not stripped:
        return False
    # Exact match against any language word list
    for words_set in ABUSE_WORDS.values():
        if stripped in words_set:
            return True
    # Whole-word regex match
    if GENERIC_ABUSE_RE.fullmatch(stripped):
        return True
    return False


def contains_abuse(text: str, lang: str = "english") -> bool:
    # Tokenize on whitespace AND punctuation so "madarchod,you" is checked too
    tokens = re.findall(r"\S+", text)
    for token in tokens:
        if _is_word_abuse(token):
            return True
    # Telegram ban phrases are multi-word, do a substring check for those only
    lower = text.lower()
    for phrase in abuse_filter__TELEGRAM_BAN_WORDS:
        if " " in phrase and phrase in lower:
            return True
    return False


def is_sexual_topic(text: str, lang: str = "english") -> bool:
    """
    Returns True if the user input is asking about a sexual topic.
    Whole-word match on each token + multi-word phrase substring match.
    Used to short-circuit AI calls — the bot refuses entirely rather than
    try to discuss the topic.
    """
    if not text:
        return False
    tokens = re.findall(r"\S+", text.lower())
    for token in tokens:
        stripped = token.strip(".,!?;:()[]{}\"'`*/\\|<>@#$%^&_+-=")
        if stripped in SEXUAL_TOPIC_WORDS:
            return True
    lower = text.lower()
    for phrase in SEXUAL_PHRASES:
        if phrase in lower:
            return True
    return False


def sanitize_abuse(text: str, lang: str = "english") -> str:
    """
    Replace each abuse token with a censored form. Uses whole-word matching
    so innocent words like "good", "bohot", "grape", "class", "cucumber"
    are NOT censored.
    """
    def _censor(match: re.Match) -> str:
        word = match.group(0)
        if len(word) <= 2:
            return "***"
        return word[0] + "***" + word[-1]

    def _replace_token(match: re.Match) -> str:
        token = match.group(0)
        if _is_word_abuse(token):
            return _censor(match)
        return token

    return re.sub(r"\S+", _replace_token, text)


