# ── Settings cache (TTL 300s) — avoids DB reads on every message ──────────────
_settings_cache: dict[str, tuple[str, float]] = {}
_SETTINGS_TTL = 300.0


def _get_cached_setting(key: str, default: str = "") -> str:
    now = time.time()
    val, ts = _settings_cache.get(key, ("", 0.0))
    if now - ts < _SETTINGS_TTL:
        return val
    val = get_setting(key, default)
    _settings_cache[key] = (val, now)
    return val

