TELEGRAM_BAN_PATTERNS: list[re.Pattern] = [
    re.compile(r"\b(kill|murder|suicide)\b.*\b(yourself|me|you)\b", re.IGNORECASE),
    re.compile(r"\b(how to|make|create|build)\b.*\b(bomb|weapon|explosive)\b", re.IGNORECASE),
    re.compile(r"\b(buy|sell|get)\b.*\b(drugs|cocaine|heroin|weed)\b", re.IGNORECASE),
    re.compile(r"\b(sex|porn|xxx).*?(video|pic|image|photo)\b", re.IGNORECASE),
    re.compile(r"\b(hack|steal|exploit).*?(account|password|data|money)\b", re.IGNORECASE),
]

def is_telegram_safe(text: str) -> tuple[bool, str]:
    text_lower = text.lower()
    for word in TELEGRAM_BAN_WORDS:
        if word in text_lower:
            return False, word
    for pattern in TELEGRAM_BAN_PATTERNS:
        match = pattern.search(text_lower)
        if match:
            return False, match.group(0)
    return True, ""

