# ── Pre-compiled regex patterns for _sanitize_output ────────────────────────────
_RE_BOLD = re.compile(r"\*\*([^*]+)\*\*")
_RE_ITALIC = re.compile(r"\*([^*]+)\*")
_RE_UNDERLINE = re.compile(r"_([^_]+)_")
_RE_CODE = re.compile(r"`([^`]+)`")
_RE_HEADING = re.compile(r"#+\s*")
_RE_LIST = re.compile(r"^[-•*]\s+", re.MULTILINE)
_RE_SPACES = re.compile(r"[ \t]+")


def _sanitize_output(reply: str, lang: str) -> str:
    """Sanitize AI output for safe Telegram delivery."""
    if not reply or not reply.strip():
        return _safe_refusal(lang)

    # Strip only markdown MARKERS, not content inside them.
    cleaned = _RE_BOLD.sub(r"\1", reply)
    cleaned = _RE_ITALIC.sub(r"\1", cleaned)
    cleaned = _RE_UNDERLINE.sub(r"\1", cleaned)
    cleaned = _RE_CODE.sub(r"\1", cleaned)
    cleaned = _RE_HEADING.sub("", cleaned)
    cleaned = _RE_LIST.sub("", cleaned)

    # Collapse multiple spaces within lines, but preserve line breaks
    cleaned = "\n".join(
        _RE_SPACES.sub(" ", line).strip()
        for line in cleaned.splitlines()[:5]
        if line.strip()
    )

    # Language-specific post-processing
    if lang in ("hindi", "hinglish"):
        cleaned = to_feminine_hindi(cleaned)

    # If the AI output contains sexual content, refuse entirely — never censor
    if is_sexual_topic(cleaned, lang):
        logger.warning("[ai] Sexual content in AI output, refusing")
        return sexual_topic_refusal(lang)

    # Abuse sanitization — strip any abuse from AI output
    if contains_abuse(cleaned, lang):
        logger.warning("[ai] Abuse detected in AI output, sanitizing")
        cleaned = sanitize_abuse(cleaned, lang)

    # Safety check
    safe, bad_word = is_telegram_safe(cleaned)
    if not safe:
        logger.warning("[ai] Blocked Telegram-ban word '%s' in AI output", bad_word)
        return _safe_refusal(lang)

    # Emoji management
    emoji_matches = _EMOJI_PATTERN.findall(cleaned)
    if len(emoji_matches) > 1:
        cleaned = _EMOJI_PATTERN.sub("", cleaned).strip()
        if not cleaned or cleaned.isspace():
            return _safe_refusal(lang)
        cleaned = add_single_emoji(cleaned)
    elif len(emoji_matches) == 0:
        if not cleaned or cleaned.isspace():
            return _safe_refusal(lang)
        cleaned = add_single_emoji(cleaned)

    return cleaned

