def detect_language(text: str) -> str:
    """Enhanced language detection with single-pass character counting."""
    devanagari_count = arabic_count = chinese_count = japanese_count = korean_count = 0
    for ch in text:
        cp = ord(ch)
        if 0x0900 <= cp <= 0x097F: devanagari_count += 1
        elif 0x0600 <= cp <= 0x06FF: arabic_count += 1
        elif 0x4E00 <= cp <= 0x9FFF: chinese_count += 1
        elif 0x3040 <= cp <= 0x30FF: japanese_count += 1
        elif 0xAC00 <= cp <= 0xD7AF: korean_count += 1

    total_chars = len(text)
    if total_chars == 0:
        return "english"

    if devanagari_count > total_chars * 0.15:
        words = set(text.lower().replace("?", "").replace("!", "").split())
        if len(words & HINDI_WORDS) >= 1:
            return "hinglish" if devanagari_count < total_chars * 0.5 else "hindi"
        return "hindi"
    if arabic_count > total_chars * 0.15: return "arabic"
    if chinese_count > total_chars * 0.15: return "chinese"
    if japanese_count > total_chars * 0.15: return "japanese"
    if korean_count > total_chars * 0.15: return "korean"
    if devanagari_count > 0: return "hindi"

    words = set(text.lower().replace("?", "").replace("!", "").split())
    hinglish_matches = len(words & HINDI_WORDS)
    if hinglish_matches >= 2: return "hinglish"
    if hinglish_matches == 1 and devanagari_count > 0: return "hinglish"
    if arabic_count > 5: return "arabic"
    return "english"

def detect_emotion(text: str) -> str:
    t = text.lower()
    if any(w in t for w in ["sad", "cry", "hurt", "alone", "miss", "dukh", "rona", "akela"]):
        return "sad"
    if any(w in t for w in ["angry", "hate", "irritate", "gussa", "bakwas"]):
        return "angry"
    if any(w in t for w in ["love", "crush", "like", "pyar", "dil"]):
        return "love"
    if any(w in t for w in ["haha", "lol", "lmao", "funny", "hehe"]):
        return "funny"
    if any(w in t for w in ["think", "wonder", "confused", "soch"]):
        return "thinking"
    return "normal"


def detect_user_gender(text: str) -> str | None:
    """Detect user gender from Hindi/Hinglish verb forms in their message.
    Returns 'male', 'female', or None if uncertain.

    Looks for self-referential verb forms that reveal the speaker's gender.
    Common neutral words like 'hua', 'raha', 'kiya' alone are NOT enough
    to determine gender since Hinglish speakers often use them interchangeably.
    """
    t = text.lower().strip()
    if not t:
        return None

    words = t.split()
    fem_score = 0
    masc_score = 0

    for word in words:
        clean = word.strip('?,!.:;')

        # Strong feminine indicators (unambiguous self-referential feminine forms)
        if clean in ('karungi', 'jaungi', 'bolungi', 'khaungi', 'dekhungi',
                     'puchungi', 'rahungi', 'sakungi', 'chahungi', 'paungi',
                     'loongi', 'dugi'):
            fem_score += 4
        if clean in ('gayi',):
            fem_score += 4
        if clean in ('kari', 'dekhi', 'puchi', 'bheji', 'likhi', 'samjhi'):
            fem_score += 3

        # Strong masculine indicators
        if clean in ('karunga', 'jaunga', 'bolunga', 'khaunga', 'dekhunga',
                     'puchunga', 'rahunga', 'sakunga', 'chahunga', 'paunga',
                     'loonga', 'duga'):
            masc_score += 4
        if clean in ('gaya',):
            masc_score += 4

        # "rahi" with any auxiliary verb -> strong feminine signal
        if clean == 'rahi':
            fem_score += 3
        # "raha" with "hu/hoon" -> strong masculine signal
        if clean == 'raha':
            if any(w in ('hu', 'hoon') for w in words):
                masc_score += 4
            # "raha" alone or with other aux (hai/ho/tha) -> weaker masculine
            else:
                masc_score += 1

        # Weaker indicators (Hinglish speakers mix these)
        if clean.endswith('ti') and len(clean) >= 4:
            fem_score += 2
        if clean.endswith('ta') and len(clean) >= 4 and clean not in ('data', 'beta', 'kita', 'sita', 'mita', 'baat'):
            masc_score += 1

    # Check full word endings (future tense)
    if re.search(r'\b\w+unga\b', t):
        masc_score += 4
    if re.search(r'\b\w+ungi\b', t):
        fem_score += 4

    # Threshold: require a clear margin
    if fem_score >= masc_score + 2:
        return 'female'
    elif masc_score >= fem_score + 2:
        return 'male'
    return None


