def _chat_category(lang: str, text: str) -> str:
    lower = text.lower()
    if lang == "arabic":
        return "chat_arabic"
    if len(text.split()) >= 28 or any(
        w in lower for w in (
            "why", "how", "explain", "difference", "compare", "reason",
            "solve", "summary", "summarize", "kaise", "kyu", "kyun",
            "samjha", "samjhao", "detail", "probability",
        )
    ):
        return "chat_reasoning"
    return "chat_default"


# ━━━ Force Mode Call ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async def _force_model_call(
    messages: list,
    provider: str,
    model: str,
    category: str,
    lang: str,
    max_tokens: int = 280,
    temperature: float = 0.9,
) -> Optional[str]:
    """Call a specific model directly (force mode). No fallback."""


    if check_rate_limit(model, provider):
        raise RuntimeError(f"Model {model} is rate limited")

    try:
        if provider == "groq":
            resp_text, meta = await _call_groq_model(model, messages, max_tokens, temperature)
        elif provider == "gemini":
            resp_text, meta = await _call_gemini(messages, max_tokens, temperature, model=model)
        elif provider == "deepseek":
            resp_text, meta = await _call_deepseek(messages, max_tokens, temperature, model=model)
        elif provider == "openrouter":
            resp_text, meta = await _call_openrouter(messages, max_tokens, temperature, model=model)
        elif provider == "openai":
            resp_text, meta = await _call_openai(messages, max_tokens, temperature, model=model)
        else:
            raise RuntimeError(f"Unknown provider: {provider}")
        return resp_text
    except Exception as e:
        raise


async def _groq_call(
    messages: list,
    emotion: str,
    lang: str,
    text: str,
    user_name: str = "",
    replied_sender: str = "",
    replied_text: str = "",
    cid: int = 0,
    bot=None,
    user_gender: str | None = None,
) -> Optional[str]:
    """
    Call the AI model with full context:
    - user_name: first name of the person talking to Anyy
    - replied_sender: name of the person whose message was replied to (if any)
    - replied_text: content of the replied-to message (if any)
    
    Pre-send validation: checks AI provider health before calling.
    Auto-failover retries with next available provider if response is bad.
    """
    try:
        lang_instr = {
            "hinglish": "IMPORTANT: Reply ONLY in Hinglish. Mix Hindi and English naturally like real people do. Use feminine self-forms.",
            "hindi": "IMPORTANT: Reply ONLY in Hindi (Devanagari or Hinglish). Natural spoken Hindi, NOT textbook. Feminine verbs.",
            "english": "IMPORTANT: Reply ONLY in English. Casual, conversational, short. NOT formal or robotic.",
            "arabic": "IMPORTANT: Reply ONLY in Arabic. Short, warm, natural.",
            "urdu": "IMPORTANT: Reply ONLY in Urdu. Short, warm, natural.",
            "chinese": "IMPORTANT: Reply ONLY in Chinese. Short, natural.",
            "japanese": "IMPORTANT: Reply ONLY in Japanese. Short, natural.",
            "korean": "IMPORTANT: Reply ONLY in Korean. Short, natural.",
        }.get(lang, "IMPORTANT: Reply in the EXACT SAME language the user wrote in. Do NOT switch languages.")

        # ── Build runtime context ─────────────────────────────────────────────
        context_parts = []

        if user_name:
            context_parts.append(
                f"You are talking to '{user_name}'. Use their name when natural, not every time."
            )

        if user_gender:
            if user_gender == "female":
                context_parts.append(
                    "The user is FEMALE. When addressing them in Hindi, use feminine forms like "
                    "'kar rahi ho', 'tumne kiya?', 'tumhari', 'tujhe' etc. "
                    "Do NOT use masculine forms like 'kar raha hai' or 'tera' for them."
                )
            else:
                context_parts.append(
                    "The user is MALE. When addressing them in Hindi, use masculine forms like "
                    "'kar raha hai', 'tumne kiya?', 'tera', 'tujhe' etc. "
                    "Do NOT use feminine forms like 'kar rahi hai' or 'teri' for them."
                )

        if replied_sender and replied_text:
            context_parts.append(
                f"They replied to '{replied_sender}' who said: \"{replied_text[:200]}\". "
                f"React to BOTH the original message and their reply."
            )
        elif replied_sender and not replied_text:
            context_parts.append(f"They replied to '{replied_sender}'.")

        context_parts.append(f"Current mood: {emotion}.")
        context_parts.append(lang_instr)

        # ── Load AI settings from database ───────────────────────────
        personality = _get_cached_setting(f"ai_personality:{cid}", "")
        if not personality:
            personality = _get_cached_setting("ai_global_personality", "cute")
        length_setting = _get_cached_setting(f"ai_length:{cid}", "")
        if not length_setting:
            length_setting = _get_cached_setting("ai_global_length", "medium")
        language_setting = _get_cached_setting(f"ai_language:{cid}", "")
        if not language_setting:
            language_setting = _get_cached_setting("ai_global_language", "auto")

        # ── Personality addon ───────────────────────────────────────
        personality_prompts = {
            "cute": "You are extra cute and sweet today. Use warm emojis like 🌸💗😊. Be caring and nurturing.",
            "sassy": "You are feeling sassy and confident. Be witty, playful, and bold. Use 💅✨😎. Light roasts are okay.",
            "chill": "You are super relaxed and casual. Keep it low-key. Use 😎✌️🤙. No drama, just vibes.",
            "romantic": "You are feeling romantic and dreamy. Be sweet, flirty, and affectionate. Use 💕🥰😘.",
            "serious": "You are in serious mode. Be professional, focused, and helpful. Minimal emojis, just 📌✅.",
            "funny": "You are in comedy mode! Be hilarious, make jokes, puns, and be playful. Use 😂🤣💀.",
        }
        personality_addon = personality_prompts.get(personality, personality_prompts["cute"])

        # ── Length addon ────────────────────────────────────────────
        length_instructions = {
            "short": "Keep replies VERY short — 1-2 sentences max. Quick and punchy.",
            "medium": "Keep replies moderate — 2-4 sentences. Balanced and natural.",
            "long": "You can be more detailed — 4-6 sentences. But still stay conversational.",
        }
        length_addon = length_instructions.get(length_setting, length_instructions["medium"])

        # ── Language addon ──────────────────────────────────────────
        language_addon = ""
        if language_setting == "hindi":
            language_addon = "ALWAYS respond in Hindi (Devanagari script). Never use English."
        elif language_setting == "english":
            language_addon = "ALWAYS respond in English only. Never use Hindi or Hinglish."
        elif language_setting == "hinglish":
            language_addon = "ALWAYS respond in Hinglish (Hindi written in English letters). Mix Hindi and English naturally."
        elif language_setting == "urdu":
            language_addon = "ALWAYS respond in Urdu. Use Urdu expressions and style."

        # ── Build full system prompt ────────────────────────────────
        full_system_prompt = SYSTEM_PROMPT + "\n\n" + personality_addon + "\n" + length_addon
        if language_addon:
            full_system_prompt += "\n" + language_addon

        runtime_context = " ".join(context_parts)

        sys_msgs = [
            {"role": "system", "content": full_system_prompt},
            {"role": "system", "content": runtime_context},
        ]

        # ── Force mode check ─────────────────────────────────────────────────
        if cid and bot:
            force_on = await _get_force_on(cid)
            if force_on:
                force_provider = await _get_provider(cid)
                force_model = await _get_model(cid)
                if force_provider and force_model:
                    try:
                        reply_text = await _force_model_call(
                            sys_msgs + messages,
                            provider=force_provider,
                            model=force_model,
                            category=_chat_category(lang, text),
                            lang=lang,
                        )
                        if reply_text and not _looks_like_provider_error(reply_text):
                            return reply_text
                    except Exception as e:
                        err = str(e)[:200]
                        logger.warning("[ai] Force mode error for chat %s: %s", cid, err)
                        error_type = f"{force_provider}:{force_model}"
                        await report_force_error_once(cid, bot, error_type, err)
                    return None

        # ── Primary attempt (capped at 12s total) ─────────────────────────────────
        # Race phase 5s + Phase 2 4s = 9s. 12s gives a bit of headroom.
        try:
            resp, meta = await asyncio.wait_for(
                chat_completion(
                    sys_msgs + messages,
                    category=_chat_category(lang, text),
                    lang=lang,
                    max_tokens=220,
                    temperature=0.9,
                ),
                timeout=12,
            )
        except asyncio.TimeoutError:
            logger.warning("[ai] chat_completion timed out after 12s")
            return None
        logger.info("[ai] model=%s provider=%s", meta.get("model"), meta.get("provider", "groq"))

        content = None
        if hasattr(resp, "choices") and resp.choices:
            content = getattr(resp.choices[0].message, "content", None)
        if not content:
            content = resp if isinstance(resp, str) else None

        # ── Post-response validation: auto-failover on bad output ────────────────
        # NOTE: the old rule was `len < 5`, which threw away perfectly good short
        # answers ("391", "ok", "sure!") and burned a second full provider round-
        # trip while marking a healthy provider as failed.  Only reject content
        # that is empty, has no real characters, or is a provider error payload.
        _stripped = (content or "").strip()
        _bad_reply = (
            not _stripped
            or _looks_like_provider_error(content)
            or (len(_stripped) < 3 and not any(ch.isalnum() for ch in _stripped))
        )
        if _bad_reply:
            logger.warning(f"[ai] Bad response from {meta.get('provider')} "
                           f"(len={len(content or '')}), triggering auto-failover")
            try:
                swap_mgr = get_swap_manager()
                provider_name = meta.get("provider", "unknown")
                if provider_name in swap_mgr.providers:
                    swap_mgr.mark_provider_failure(provider_name, "empty/bad response")

                resp, meta = await asyncio.wait_for(
                    chat_completion(
                        sys_msgs + messages,
                        category=_chat_category(lang, text),
                        lang=lang,
                        max_tokens=220,
                        temperature=0.9,
                    ),
                    timeout=10,
                )
                logger.info("[ai] failover model=%s provider=%s",
                            meta.get("model"), meta.get("provider", "unknown"))

                content = None
                if hasattr(resp, "choices") and resp.choices:
                    content = getattr(resp.choices[0].message, "content", None)
                if not content:
                    content = resp if isinstance(resp, str) else None
            except Exception as e2:
                logger.warning(f"[ai] Auto-failover also failed: {e2}")
                return None

        if content and _looks_like_provider_error(content):
            logger.warning("[ai] Failover returned a provider error payload; dropping")
            content = None
        if not content:
            logger.warning("[ai] No content in response after failover")
            return None

        reply = _sanitize_output(content.strip(), lang)
        return reply

    except Exception as e:
        err = str(e).lower()
        if "timeout" in err:
            logger.debug("[ai] AI model timeout: %s", err[:120])
        else:
            logger.warning("[ai] AI model error: %s: %s", type(e).__name__, err[:200])
        return None

# ━━━ Emoji Reaction Logic ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
#
# IMPORTANT: Telegram ONLY accepts specific emojis as reactions.
# Using an unsupported emoji causes a BadRequest silently.
# Source: Telegram Bot API — ReactionTypeEmoji (confirmed list)
#
_REACTION_POOL = ["❤", "🥰", "😍", "💘", "💋", "🔥", "👏", "🎉", "🤩", "🏆",
                  "💯", "😂", "🤣", "😁", "🤭", "😭", "😢", "🙏", "😨", "🤗",
                  "💔", "👍", "🫡", "👌", "⚡", "🤯", "😱", "👀", "🧐",
                  "😊"]


def _pick_reaction(text: str) -> Optional[list[str]]:
    """Extract first emoji from AI reply text, or pick a random neutral one."""
    matches = _EMOJI_PATTERN.findall(text)
    if matches:
        return [matches[0]]
    return [random.choice(_REACTION_POOL)]


async def _maybe_react(bot, msg, text: str, is_dm: bool = False) -> None:
    """
    React to the user's message with a valid Telegram emoji reaction.
    Rate: ~25% chance — keeps it natural, not spammy.
    Randomly picks a neutral emoji sometimes even without trigger match.
    """
    try:
        if random.random() > 0.25:
            return
        reaction = _pick_reaction(text)
        if not reaction:
            return
        await bot.set_message_reaction(
            chat_id=msg.chat_id,
            message_id=msg.message_id,
            reaction=reaction,
            is_big=False,
        )
    except Exception as e:
        logger.debug(f"[ai] Reaction failed (likely unsupported emoji): {e}")



# ━━━ Quiet mode and response logic ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
_quiet: dict[int, float] = {}
_quiet_lock: asyncio.Lock | None = None
_quiet_check_count = 0

async def _get_quiet_lock() -> asyncio.Lock:
    global _quiet_lock
    if _quiet_lock is None:
        _quiet_lock = asyncio.Lock()
    return _quiet_lock

async def _cleanup_quiet_if_needed():
    global _quiet_check_count
    _quiet_check_count += 1
    if _quiet_check_count > 500:
        _quiet_check_count = 0
        async with await _get_quiet_lock():
            now = time.time()
            stale = [cid for cid, ts in _quiet.items() if now - ts > 7200]
            for cid in stale:
                _quiet.pop(cid, None)

def _is_quiet(text: str) -> bool:
    return any(t in text.lower() for t in QUIET_TRIGGERS)

async def _should_respond(
    text: str, cid: int, is_private: bool, is_reply_to_bot: bool, reply_text: str = "",
) -> bool:
    # FAST PATH: no async work needed for most common cases
    lower = text.lower().strip()
    if text.startswith("/"):
        return False

    # Wake triggers always respond (no lock needed for "should respond")
    for t in WAKE_TRIGGERS:
        if t in lower:
            _quiet.pop(cid, None)  # dict.pop is atomic in CPython
            return True

    # Quiet mode: lock-free atomic read of timestamp
    # (writing to _quiet still uses the lock, but reading doesn't need it)
    if cid in _quiet:
        if time.time() - _quiet[cid] > 3600:
            _quiet.pop(cid, None)
        else:
            return False

    # Common-case responders (no DB, no async, no lock)
    if is_private:
        return True
    if is_reply_to_bot:
        return True

    bot_user = (BOT_USERNAME or "").lower()
    if bot_user and (f"@{bot_user}" in lower or bot_user in lower):
        return True

    if _NAME_TRIGGER_RE and _NAME_TRIGGER_RE.search(lower):
        return True

    return False

# ━━━ Sticker selection (emotion-matched) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
STICKER_EMOJI_MAP: dict[str, list[str]] = {
    "happy":    ["😊", "😄", "😁", "🥰", "😍", "🤩", "😂"],
    "sad":      ["😢", "😭", "😞", "😔", "🥺", "💔"],
    "love":     ["❤️", "💕", "💖", "💗", "💓", "😘", "🥰"],
    "funny":    ["😂", "🤣", "😆", "😹", "💀", "🤭"],
    "thinking": ["🤔", "💭", "🧐", "😐", "🤨", "🫤"],
    "angry":    ["😠", "😤", "😡", "💢"],
    "normal":   ["😊", "✨", "💫", "🌟", "😌", "💗"],
}

async def _send_emotion_sticker(msg, emotion: str, user_id: int = 0, chat_id: int = 0) -> bool:
    """
    Send emotion-matched sticker with 'choosing sticker' indicator first.
    Priority: user's own sticker → emotion-matched → random from pool.
    """
    if user_id:
        user_sticker = pick_sticker_for_emotion(user_id, chat_id, emotion)
        if user_sticker:
            try:
                await msg.reply_sticker(user_sticker, read_timeout=10)
                return True
            except Exception:
                logger.debug("User sticker send failed for %s in %s, falling through", user_id, chat_id)

    try:
        sticker_data = await asyncio.to_thread(get_sticker_setting, "reply_stickers") or {}
        packs = sticker_data.get("packs", {})
        if not packs:
            return False

        all_stickers: list = []
        for ps in packs.values():
            if isinstance(ps, list):
                all_stickers.extend(ps)
        if not all_stickers:
            return False

        # Try to find a sticker matching the emotion emoji
        target_emojis = STICKER_EMOJI_MAP.get(emotion, STICKER_EMOJI_MAP["normal"])
        matched = [
            s for s in all_stickers
            if isinstance(s, dict) and s.get("emoji") in target_emojis
        ]
        # Fallback chain: emotion-matched → random from pool
        chosen = random.choice(matched) if matched else random.choice(all_stickers)
        fid = chosen.get("file_id") if isinstance(chosen, dict) else chosen
        if not fid:
            return False

        # Show 'choosing sticker' indicator for 2-5 seconds (feels human)
        try:
            await msg.get_bot().send_chat_action(
                chat_id=msg.chat_id,
                action=ChatAction.CHOOSE_STICKER
            )
            await asyncio.sleep(random.uniform(3.0, 7.0))
        except Exception as exc:
            logger.debug("[ai] send_chat_action failed: %s", exc)

        await msg.reply_sticker(fid)
        return True

    except Exception as e:
        logger.debug(f"[ai] Emotion sticker failed: {e}")
    return False


# ━━━ Context Window Management ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async def _read_telegram_history(chat_id: int, user_id: int) -> list:
    try:
        return get_user_context(chat_id, user_id, max_user=4, max_bot=4)
    except Exception as e:
        logger.warning("[ai] Error reading history: %s: %s", type(e).__name__, e)
        return []

def _build_messages(history: list, user_text: str) -> list:
    if history and history[-1]["role"] == "user":
        last = history[-1]["content"]
        if last == user_text or last.endswith(f": {user_text}"):
            return history
    return history + [{"role": "user", "content": user_text}]

# ━━━ Typing indicator — runs CONCURRENTLY with model call ━━━━━━━━━━━━━━━━━━━━━━
async def _keep_typing(bot, chat_id: int, stop_event: asyncio.Event) -> None:
    """
    Keep sending typing action every 5 seconds until stop_event is set.
    Runs concurrently with the model API call so typing shows WHILE
    the model is actually thinking — not as dead time before it starts.
    Shows realistic 4-5 second typing indication.
    """
    try:
        while not stop_event.is_set():
            await bot.send_chat_action(chat_id, ChatAction.TYPING)
            # Telegram clears typing indicator after 5s, so refresh every 5s
            try:
                await asyncio.wait_for(asyncio.shield(stop_event.wait()), timeout=5.0)
            except asyncio.TimeoutError:
                pass
    except Exception as exc:
        logger.debug("[ai] Exception in _keep_typing: %s", exc)

async def send_typing_indicator(bot, chat_id, text_length: int = 50):
    """Legacy single-shot typing for compatibility. Prefer _keep_typing for AI."""
    try:
        await bot.send_chat_action(chat_id, ChatAction.TYPING)
        delay = min(max(text_length * 0.04, 0.8), 3.0)
        await asyncio.sleep(delay)
    except Exception as e:
        logger.debug(f"[ai] Typing indicator error: {e}")


# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
#  MAIN HANDLER
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
async def handle_ai_chat(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    _crumb("handle_in", update)
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not msg or not user or user.is_bot:
        return

    text = (msg.text or msg.caption or "").strip()
    is_sticker = msg.sticker is not None
    sticker_emoji = ""
    if is_sticker and msg.sticker and msg.sticker.file_id:
        record_user_sticker(user.id, msg.sticker.file_id, chat.id)
        sticker_emoji = msg.sticker.emoji or ""
    if not text and not is_sticker:
        return

    if gif_pool_input_pending(user.id):
        return

    if is_playing_guess(user.id):
        return

    cid = chat.id
    is_private = chat.type == "private"
    reply_to = msg.reply_to_message
    is_reply_to_bot = reply_to and reply_to.from_user and reply_to.from_user.id == ctx.bot.id

    # Skip replies to old messages in groups (>5 minutes old)
    if reply_to and not is_private and reply_to.date:
        reply_age = (update.effective_message.date.timestamp() - reply_to.date.timestamp())
        if reply_age > 300:  # 5 minutes
            return

    # ── Check if bot should respond BEFORE any DB reads ──────────────────
    if not is_sticker:
        if not await _should_respond(text, cid, is_private, is_reply_to_bot,
                               (reply_to.text or reply_to.caption or "") if reply_to else ""):
            return

    # ── Now do DB reads — only when we actually want to respond ──────────
    if _get_cached_setting("global_ai", "on") == "off":
        return
    if not is_private and _get_cached_setting(f"ai_group_{cid}", "on") == "off":
        return

    # ── Fast ban check (O(1), no DB) ───────────────────────────────────
    # If we know the user is banned (cache hit), skip. Otherwise do the
    # slower DB-backed check in a background task so we don't block.
    if is_banned_fast(user.id):
        return
    # Slow check in background (don't block the hot path)
    asyncio.create_task(asyncio.to_thread(is_bot_use_banned, user.id))

    # ── Username abuse check — skip users with abuse in name ──────────────
    if check_username_abuse(user.username) or check_username_abuse(user.first_name):
        logger.info("[ai] Skipping user %s — abuse in username", user.id)
        return

    # ── Quiet trigger: only honour when user is replying to bot ──────────────
    if is_reply_to_bot and _is_quiet(text):
        # Lock-free atomic write — dict.__setitem__ is atomic in CPython
        _quiet[cid] = time.time()
        responses = [
            "Okay okay, chup ho jaati hun 🤐 baad mein baat karna!",
            "Fine fine, gone quiet 🤐 call me when you miss me!",
            "Theek hai, ab shaant 🤐 later yaar!",
            "Ugh fine, shutting up 🤐",
        ]
        try:
            await msg.reply_text(random.choice(responses))
        except Exception as e:
            logger.debug(f"Quiet response failed: {e}")
        return

    safe, bad_word = is_telegram_safe(text)
    if not safe:
        logger.info("[ai] Blocked Telegram-ban word '%s' from user %s", bad_word, user.id)
        try:
            await msg.reply_text(_safe_refusal(detect_language(text)))
        except TelegramError as exc:
            logger.debug("[ai] Safe-refusal reply failed: %s", exc)
        return

    lang = detect_language(text) if text else "english"
    if is_sexual_topic(text, lang):
        logger.info("[ai] Sexual topic from user %s, using refusal", user.id)
        try:
            await msg.reply_text(sexual_topic_refusal(lang))
        except TelegramError as exc:
            logger.debug("[ai] Sexual-refusal reply failed: %s", exc)
        return
    if contains_abuse(text, lang):
        logger.info("[ai] Abuse detected from user %s, using gentle refusal", user.id)
        try:
            await msg.reply_text(gentle_refusal(lang))
        except TelegramError as exc:
            logger.debug("[ai] Gentle-refusal reply failed: %s", exc)
        return

    has_any_key = any([GROQ_API_KEY, CEREBRAS_API_KEY, OPENROUTER_API_KEY, OPENCODE_ZEN_API_KEY, QWEN_API_KEY, OPENAI_API_KEY, GEMINI_API_KEY, DEEPSEEK_API_KEY])
    if not has_any_key:
        if not cid or not await _get_force_on(cid):
            try:
                await msg.reply_text(random.choice([
                    "AI key abhi set nahi hai, thoda owner ko tag karo 💗",
                    "AI side abhi ready nahi hai, owner ko bolo key check kare.",
                    "Chat engine abhi missing hai, thoda owner se setup karwa do.",
                ]))
            except TelegramError as exc:
                logger.debug(f"[ai] Missing-key reply failed: {exc}")
            return

    clean = normalize_text(text)
    emotion = detect_emotion(clean) if clean else "normal"
    user_gender = detect_user_gender(text) if text else None
    # For stickers: detect emotion from sticker emoji
    if is_sticker and sticker_emoji:
        sticker_emotion_map = {
            "😊": "happy", "😄": "happy", "😁": "happy", "🥰": "love", "😍": "love",
            "😂": "funny", "🤣": "funny", "😆": "funny", "😢": "sad", "😭": "sad",
            "😞": "sad", "😔": "sad", "🥺": "sad", "😡": "angry", "😤": "angry",
            "🤔": "thinking", "❤️": "love", "💕": "love", "💖": "love", "💗": "love",
            "💓": "love", "😘": "love", "💋": "love", "🔥": "happy", "✨": "happy",
            "💫": "happy", "🌟": "happy", "😌": "happy", "👍": "happy", "👋": "happy",
            "🙏": "happy", "🤗": "happy", "🤩": "happy", "😱": "thinking", "😨": "thinking",
            "💔": "sad", "😠": "angry", "💢": "angry",
        }
        for emoji_char, emo in sticker_emotion_map.items():
            if emoji_char in sticker_emoji:
                emotion = emo
                break

    # ── Extract user's first name for personalised replies ────────────────────
    user_name = (user.first_name or "").strip()[:30]
    if not user_name:
        user_name = (user.username or "").strip()[:30]
    if not user_name:
        user_name = f"User"

    # ── Extract replied-to message context ────────────────────────────────────
    # If the user replied to ANOTHER user's message (not the bot),
    # include that message so Anyy understands what they're reacting to.
    replied_sender = ""
    replied_text_ctx = ""
    if reply_to and reply_to.from_user:
        sender = reply_to.from_user
        replied_msg_text = (reply_to.text or reply_to.caption or "").strip()
        if sender.id != ctx.bot.id and replied_msg_text:
            # User replied to another human's message
            replied_sender = (sender.first_name or sender.username or "someone").strip()[:30]
            replied_text_ctx = replied_msg_text[:300]  # cap at 300 chars
        elif sender.id == ctx.bot.id and replied_msg_text:
            # User replied to Anyy's own message — include as prior context
            replied_sender = "Anyy"
            replied_text_ctx = replied_msg_text[:200]

    # Store user message in per-user filtered history
    # Do this AFTER reading history to avoid duplicate message context
    history = await _read_telegram_history(cid, user.id)
    chat_msgs = _build_messages(history, text if text else "(sticker sent)")

    try:
        store_message(cid, user.id, "user", text)
    except Exception as exc:
        logger.warning("[ai] Failed to buffer user message: %s", exc)

    try:
        await _cleanup_quiet_if_needed()
    except Exception as exc:
        logger.debug("[ai] Quiet cleanup failed: %s", exc)

    # ── Concurrent typing: shows WHILE model is processing, not before ──────────
    _stop_typing = asyncio.Event()
    _typing_task: asyncio.Task | None = None
    try:
        _typing_task = asyncio.create_task(_keep_typing(ctx.bot, cid, _stop_typing))
    except Exception as exc:
        logger.warning("[ai] Failed to start typing task: %s", exc)

    try:
        reply = await _groq_call(
            chat_msgs, emotion, lang, text,
            user_name=user_name,
            replied_sender=replied_sender,
            replied_text=replied_text_ctx,
            cid=cid,
            bot=ctx.bot,
            user_gender=user_gender,
        )
    finally:
        _stop_typing.set()
        if _typing_task is not None:
            _typing_task.cancel()
            try:
                await _typing_task
            except asyncio.CancelledError:
                pass
    if not reply or reply.isspace():
        # Best-effort diagnostics first (must never preempt the fallback reply).
        try:
            swap_mgr = get_swap_manager()
            provider_status = get_all_model_status()
            logger.warning(
                "[ai] No reply generated for chat=%s user=%s — status=%s",
                cid, user.id,
                {k: v.get("available") if isinstance(v, dict) else str(v)[:40]
                 for k, v in provider_status.items()},
            )
        except Exception:
            pass
        # All providers failed after aggressive retry — log only, don't spam user.
        # The chat_completion function already tried every provider + Pollinations.
        try:
            logger.warning(
                "[ai] No reply generated for chat=%s user=%s — all providers exhausted",
                cid, user.id,
            )
        except Exception:
            pass
        return

    if len(reply) > 4096:
        reply = reply[:4090] + "…"

    # ── Check emoji setting ───────────────────────────────────────────────
    emoji_setting = _get_cached_setting(f"ai_emojis:{cid}", "")
    if not emoji_setting:
        emoji_setting = _get_cached_setting("ai_global_emojis", "on")
    if emoji_setting == "off":
        reply = _STRIP_EMOJI_PATTERN.sub("", reply).strip()

    # ── Emoji reaction on the user's message ──────────────────────────────────
    _react_task = None
    if text and (is_reply_to_bot or is_private):
        _react_task = asyncio.create_task(_maybe_react(ctx.bot, msg, reply, is_dm=is_private))
    if _react_task is not None:
        def _log_react_err(t: asyncio.Task) -> None:
            if t.cancelled():
                return
            exc = t.exception()
            if exc is not None:
                logger.debug(f"React task failed: {exc!r}")
        _react_task.add_done_callback(_log_react_err)

    # Check sticker setting before sending
    sticker_setting = _get_cached_setting(f"ai_stickers:{cid}", "")
    if not sticker_setting:
        sticker_setting = _get_cached_setting("ai_global_stickers", "on")
    stickers_enabled = sticker_setting == "on"

    try:
        if is_sticker and stickers_enabled:
            _sticker_task = asyncio.create_task(
                _send_emotion_sticker(msg, emotion, user_id=user.id, chat_id=cid),
                name="sticker-send"
            )
            def _log_sticker_err(t: asyncio.Task) -> None:
                if t.cancelled():
                    return
                exc = t.exception()
                if exc is not None:
                    logger.warning(f"Sticker send task failed: {exc!r}")
            _sticker_task.add_done_callback(_log_sticker_err)
        await msg.reply_text(reply, read_timeout=5)
        _crumb("sent", update)
        # Store bot reply in per-user filtered history
        try:
            store_message(cid, 0, "assistant", reply)
        except Exception as exc:
            logger.warning("[ai] Failed to buffer bot reply: %s", exc)
    except (BadRequest, TimedOut, NetworkError) as e:
        logger.warning("[ai] Send failed for reply=%s: %s: %s", type(e).__name__, e, reply[:100])
        try:
            await ctx.bot.send_message(chat_id=cid, text=reply, read_timeout=5)
        except (BadRequest, TimedOut, NetworkError) as e2:
            logger.warning("[ai] Fallback send also failed: %s", e2)
    except Exception as e:
        if "timeout" not in str(e).lower():
            logger.info(f"[ai] {e}")

# ═══ MODULE: buttons.buttons ═══

import asyncio
import html

from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update
from telegram.ext import ContextTypes



def main_keyboard(user_id: int) -> InlineKeyboardMarkup:
    rows = [
        [
            InlineKeyboardButton("💬 Tᴀʟᴋ Tᴏ Aɴɴʏ", callback_data="talk"),
            InlineKeyboardButton("💣 Gᴀᴍᴇs", callback_data="games"),
        ],
        [
            InlineKeyboardButton("📢 Uᴘᴅᴀᴛᴇs", url=UPDATES_LINK),
            InlineKeyboardButton("📫 Sᴜᴘᴘᴏʀᴛ", url=SUPPORT_LINK),
        ],
        [
            InlineKeyboardButton(
                "➕ Aᴅᴅ Mᴇ Tᴏ Gʀᴏᴜᴘ",
                url=f"https://t.me/{BOT_USERNAME}?startgroup=true",
            )
        ],
    ]
    if user_id == OWNER_ID:
        rows.append([InlineKeyboardButton("👑 Oᴡɴᴇʀ Pᴀɴᴇʟ", callback_data="ownerpanel")])
    return InlineKeyboardMarkup(rows)


async def start_menu(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    chat = update.effective_chat
    user = update.effective_user
    if not user or not update.effective_message:
        return

    payload = context.args[0].lower() if context.args else ""

    is_private = chat and chat.type == "private"

    # Force-clear any leftover reply keyboard from old versions
    if is_private:
        try:
            rm = await update.effective_message.reply_text("‎", reply_markup=ReplyKeyboardRemove())
            await asyncio.sleep(0.3)
            await rm.delete()
        except Exception:
            pass

    if is_private:
        was_verified = await has_opened_dm(user.id)
        await mark_dm_opened(user.id)

        if payload == "wordgameguide":
            pass  # silent — no "verified" message
        elif payload in {"dm", "admin", "xogame"}:
            pass  # silent
        elif payload == "verify":
            pass  # silent — just mark as verified, no message
        elif payload == "verify_web":
            await verify_web_start_command(update, context)
            return
        elif payload == "dailygift":
            await dailygift(update, context)
            return
    else:
        was_verified = await has_opened_dm(user.id)

    verified_line = (
        "\n\n✅ <b>DM verification done.</b> You can use group commands now."
        if not was_verified
        else ""
    )
    text = (
        f"😋 Hɪᴇᴇᴇᴇᴇ  {html.escape(user.first_name)} 🍀\n"
        "😉 Yᴏᴜ'ʀᴇ Tᴀʟᴋɪɴɢ Tᴏ Aɴɴʏ, A Sᴡᴇᴇᴛ Cᴜᴛɪᴇ Gɪʀʟ.\n\n"
        "💕 Cʜᴏᴏsᴇ Aɴ Oᴘᴛɪᴏɴ Bᴇʟᴏᴡ :"
        f"{verified_line}"
    )
    await update.effective_message.reply_html(text, reply_markup=main_keyboard(user.id))


