# ═══ MODULE: database.multi_db_router ═══

"""
Multi-Database Routing System with Compression.
Implements P1-P7 database slots with automatic routing, compression, and storage management.
Includes multi-partition sync and dynamic stats.
"""

import asyncio
import time
from typing import Any, Dict, Optional, List

try:
    from pymongo import UpdateOne as _PyMongoUpdateOne
    _PYMONGO_OK = True
except ModuleNotFoundError:
    _PyMongoUpdateOne = None
    _PYMONGO_OK = False

try:
    import motor.motor_asyncio as aiomotor
    _MOTOR_OK = True
except ModuleNotFoundError:
    aiomotor = None
    _MOTOR_OK = False

logger = get_logger(__name__)

# ============================================================================
# MULTI-PARTITION MONGODB MANAGEMENT
# ============================================================================

PARTITIONS_KEY = "mongo_partitions"  # Key to store partition config


def get_partitions_config() -> Dict[str, str]:
    """Get all registered partitions {p1: url, p2: url, ...}."""
    return get_setting_json(PARTITIONS_KEY, default={})


def save_partitions_config(partitions: Dict[str, str]) -> None:
    """Save partitions config to database."""
    save_setting_json(PARTITIONS_KEY, partitions)


async def get_partition_stats(partition_id: str, mongo_url: str) -> Dict[str, Any]:
    """Get storage stats for a specific MongoDB partition."""
    if not _MOTOR_OK or not aiomotor:
        return {"connected": False, "error": "Motor not available"}
    
    try:
        client = aiomotor.AsyncIOMotorClient(
            mongo_url,
            serverSelectionTimeoutMS=15000,
            connectTimeoutMS=15000,
            socketTimeoutMS=30000,
        )
        await client.server_info()
        db = client[MONGO_DB_NAME]
        
        # Get database stats
        stats = await db.command("dbstats")
        data_size = stats.get("dataSize", 0)
        storage_size = stats.get("storageSize", 0)
        collections = stats.get("collections", 0)
        
        # Get collection names
        collection_names = await db.list_collection_names()
        
        await client.close()
        
        return {
            "connected": True,
            "partition": partition_id,
            "url": mongo_url[:50] + "...",
            "data_size": data_size,
            "storage_size": storage_size,
            "data_size_fmt": format_bytes(data_size),
            "storage_size_fmt": format_bytes(storage_size),
            "collections": collections,
            "collection_names": collection_names[:10],  # First 10 only
        }
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        return {
            "connected": False,
            "partition": partition_id,
            "error": str(e)[:100],
        }


async def sync_partition_to_p1(source_url: str, target_url: str, partition_id: str, batch_size: int = 500) -> Dict[str, Any]:
    """
    Sync a new partition with p1 (primary).

    Copies the DIFFERENCE between active members in p1 and missing members in new partition.
    Uses bulk upsert with batching for efficiency - handles millions of users.
    
    Args:
        source_url: P1 (primary) MongoDB URL
        target_url: Target partition URL to sync
        partition_id: Partition name (e.g., "P2")
        batch_size: Number of users per batch (default 500)
    
    Returns:
        Dict with success status, synced count, and message
    """
    if not _MOTOR_OK or not aiomotor:
        return {"success": False, "error": "Motor not available"}
    
    start_time = time.time()
    total_synced = 0
    total_skipped = 0
    errors = []
    
    try:
        # Connect to source (p1)
        source_client = aiomotor.AsyncIOMotorClient(
            source_url,
            serverSelectionTimeoutMS=10000,
            connectTimeoutMS=10000,
            socketTimeoutMS=30000,
            maxPoolSize=50,
        )
        source_db = source_client[MONGO_DB_NAME]
        
        # Connect to target (new partition)
        target_client = aiomotor.AsyncIOMotorClient(
            target_url,
            serverSelectionTimeoutMS=10000,
            connectTimeoutMS=10000,
            socketTimeoutMS=30000,
            maxPoolSize=50,
        )
        target_db = target_client[MONGO_DB_NAME]
        
        # Test connections
        await source_client.server_info()
        await target_client.server_info()
        
        logger.info(f"[Partition Sync] Starting sync for {partition_id}")
        
        # BUG FIX: Use streaming approach for existing user IDs
        # For small DBs (<100k): preload all IDs into set
        # For large DBs (>100k): check existence in batches
        target_user_ids: set = set()
        use_streaming_check = False
        existing_ids_batch: list = []
        
        async for doc in target_db.users.find({}, {"_id": 1}).batch_size(10000):
            target_user_ids.add(doc["_id"])
            existing_ids_batch.append(doc["_id"])
            
            # Memory guard: if we have too many IDs, switch to streaming mode
            if len(target_user_ids) > 100000:
                logger.info(f"[Partition Sync] {partition_id}: Large target detected (>100k users), using streaming mode")
                use_streaming_check = True
                # For large DBs, we track existing in batches, not all in memory
                break
        
        logger.info(f"[Partition Sync] Found {len(target_user_ids)} existing users in {partition_id}")
        
        # Get total count from source for progress
        source_count = await source_db.users.count_documents({})
        logger.info(f"[Partition Sync] P1 has {source_count} total users")
        
        if source_count == 0:
            await source_client.close()
            await target_client.close()
            return {
                "success": True,
                "synced": 0,
                "message": f"{partition_id} is empty, no sync needed",
            }
        
        # Track existence for streaming mode
        checked_this_batch: set = set()
        batch_check_interval = 50000  # Check existing IDs every 50k users
        
        # Process source users in batches
        processed = 0
        missing_count = 0
        upsert_batch = []
        
        # Use cursor with batch size for memory efficiency
        cursor = source_db.users.find({}).batch_size(batch_size)
        
        async for doc in cursor:
            processed += 1
            
            user_id = doc.get("_id")
            if user_id is None:
                continue
            
            # Check if user exists in target (based on mode)
            exists_in_target = user_id in target_user_ids
            
            # For streaming mode, also check the current batch
            if use_streaming_check and user_id in checked_this_batch:
                exists_in_target = True
            
            if exists_in_target:
                checked_this_batch.add(user_id)
            
            if exists_in_target:
                total_skipped += 1
                continue
            
            # User is missing - add to sync batch
            upsert_batch.append(user_id)
            total_synced += 1
            missing_count += 1
            
            # Batch upsert when batch is full
            if len(upsert_batch) >= batch_size or missing_count >= batch_size:
                if _PyMongoUpdateOne and upsert_batch:
                    try:
                        # Fetch full docs for batch and upsert
                        batch_docs = []
                        async for target_doc in target_db.users.find({"_id": {"$in": upsert_batch}}):
                            batch_docs.append(target_doc)
                        
                        existing_ids = {doc["_id"] for doc in batch_docs}
                        to_insert = [uid for uid in upsert_batch if uid not in existing_ids]
                        
                        if to_insert:
                            # Get full docs from source
                            source_docs = []
                            async for src_doc in source_db.users.find({"_id": {"$in": to_insert}}):
                                src_data = src_doc.copy()
                                src_id = src_data.pop("_id", None)
                                if src_id:
                                    source_docs.append({"_id": src_id, **src_data})
                            
                            if source_docs and _PYMONGO_OK:
                                operations = [
                                    _PyMongoUpdateOne(
                                        {"_id": doc["_id"]},
                                        {"$set": {k: v for k, v in doc.items() if k != "_id"}},
                                        upsert=True
                                    )
                                    for doc in source_docs
                                ]
                                await target_db.users.bulk_write(operations, ordered=False)
                        
                    except Exception as e:
                        errors.append(str(e)[:50])
                    
                    upsert_batch = []
                    missing_count = 0
                    checked_this_batch = set()  # Reset batch tracker
            
            # For streaming mode, refresh existing IDs periodically
            if use_streaming_check and processed % batch_check_interval == 0:
                # Refresh the set with new batch from target
                new_batch = []
                async for doc in target_db.users.find({}, {"_id": 1}).batch_size(10000):
                    if doc["_id"] not in target_user_ids:
                        new_batch.append(doc["_id"])
                        target_user_ids.add(doc["_id"])
                
                if new_batch:
                    logger.info(f"[Partition Sync] {partition_id}: Refreshed existing IDs (+{len(new_batch)} new)")
                checked_this_batch = set()
            
            # Log progress every 1000 users
            if total_synced % 1000 == 0:
                elapsed = time.time() - start_time
                rate = total_synced / elapsed if elapsed > 0 else 0
                mode_str = " (streaming)" if use_streaming_check else ""
                logger.info(f"[Partition Sync] {partition_id}{mode_str}: {total_synced} synced, {total_skipped} skipped, {rate:.1f} users/sec")
        
        # Final batch upsert for remaining items
        if upsert_batch and _PyMongoUpdateOne and _PYMONGO_OK:
            try:
                source_docs = []
                async for src_doc in source_db.users.find({"_id": {"$in": upsert_batch}}):
                    src_data = src_doc.copy()
                    src_id = src_data.pop("_id", None)
                    if src_id:
                        source_docs.append({"_id": src_id, **src_data})
                
                if source_docs:
                    operations = [
                        _PyMongoUpdateOne(
                            {"_id": doc["_id"]},
                            {"$set": {k: v for k, v in doc.items() if k != "_id"}},
                            upsert=True
                        )
                        for doc in source_docs
                    ]
                    await target_db.users.bulk_write(operations, ordered=False)
            except Exception as e:
                errors.append(str(e)[:50])
        
        await source_client.close()
        await target_client.close()
        
        elapsed = time.time() - start_time
        rate = total_synced / elapsed if elapsed > 0 else 0
        
        logger.info(f"[Partition Sync] Complete for {partition_id}: {total_synced} synced, {total_skipped} skipped in {elapsed:.1f}s ({rate:.1f}/sec)")
        
        return {
            "success": True,
            "synced": total_synced,
            "skipped": total_skipped,
            "elapsed_seconds": round(elapsed, 2),
            "rate_per_second": round(rate, 1),
            "message": f"Synced {total_synced} users to {partition_id} ({total_skipped} already existed)",
            "errors": len(errors) if errors else 0,
        }
        
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        logger.error("[Partition Sync] Error syncing %s", partition_id, exc_info=True)
        return {
            "success": False,
            "synced": total_synced,
            "error": str(e)[:200],
        }


async def add_partition_with_sync(
    partition_id: str, 
    mongo_url: str, 
    p1_url: str,
    auto_sync: bool = True
) -> Dict[str, Any]:
    """
    Add a new partition and optionally sync it with p1.
    Returns status dict with success/error info.
    
    Args:
        partition_id: e.g., "P2", "P3"
        mongo_url: MongoDB connection URL for new partition
        p1_url: P1 (primary) MongoDB URL to sync from
        auto_sync: If True, automatically sync with P1 after adding
    """
    try:
        # Validate URL
        if not mongo_url.startswith("mongodb"):
            return {"success": False, "error": "Invalid MongoDB URL"}
        
        # Save partition config
        partitions = await asyncio.to_thread(get_partitions_config)
        partitions[partition_id] = mongo_url
        await asyncio.to_thread(save_partitions_config, partitions)
        
        logger.info(f"[Partition] Added {partition_id}: {mongo_url[:50]}...")
        
        # Auto-sync with P1 if enabled
        if auto_sync and p1_url:
            logger.info(f"[Partition] Starting auto-sync for {partition_id} from P1...")
            sync_result = await sync_partition_to_p1(p1_url, mongo_url, partition_id)
            
            return {
                "success": True,
                "partition": partition_id,
                "url": mongo_url[:50] + "...",
                "auto_synced": True,
                "sync": sync_result,
            }
        else:
            return {
                "success": True,
                "partition": partition_id,
                "url": mongo_url[:50] + "...",
                "auto_synced": False,
                "message": f"{partition_id} added. Use /syncmongo {partition_id} to sync with P1",
            }
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        return {"success": False, "error": str(e)[:200]}


async def get_all_partitions_stats() -> List[Dict[str, Any]]:
    """Get stats for all registered partitions."""
    partitions = await asyncio.to_thread(get_partitions_config)
    if not partitions:
        # Fallback to config-based slots
        return []
    
    stats = []
    for partition_id in sorted(partitions.keys(), key=lambda x: int(x.replace("p", ""))):
        url = partitions[partition_id]
        part_stats = await get_partition_stats(partition_id, url)
        stats.append(part_stats)
    
    return stats

