# MULTI-DATABASE ROUTING SYSTEM
# ============================================================================


class DatabaseRouter:
    """Routes database operations to appropriate MongoDB slots based on category and storage."""
    
    def __init__(self):
        self._slot_cache = {}  # Cache for slot assignments
        self._storage_full_slots = set()  # Track full slots
        self._routing_table = {}  # user_id -> slot mapping
        self._last_check = 0
        self._check_interval = 300  # Check storage every 5 minutes
    
    async def initialize(self):
        """Initialize database router."""
        logger.info("[DB Router] Initializing multi-database routing system...")
        await self._load_routing_table()
        await self._check_all_slots()
        logger.info("[DB Router] Multi-database routing initialized")
    
    async def _load_routing_table(self):
        """Load existing routing table from database."""
        try:
            routing_data = await asyncio.to_thread(get_setting_json, "db_routing_table", default={})
            self._routing_table = routing_data
        except Exception as e:
            logger.error("[DB Router] Failed to load routing table", exc_info=True)
            self._routing_table = {}

    async def _save_routing_table(self):
        """Save routing table to database."""
        try:
            await asyncio.to_thread(save_setting_json, "db_routing_table", self._routing_table)
        except Exception as e:
            logger.error("[DB Router] Failed to save routing table", exc_info=True)
    
    async def _check_all_slots(self):
        """Check storage status of all MongoDB slots."""
        current_time = time.time()
        if current_time - self._last_check < self._check_interval:
            return

        self._last_check = current_time
        self._storage_full_slots.clear()

        try:
            status = await asyncio.to_thread(get_storage_status)
        except Exception as e:
            logger.error("[DB Router] Failed to get storage status", exc_info=True)
            return

        mongo_slots = status.get('mongo_slots', [])

        for slot_num, uri in enumerate(MONGO_URI_SLOTS, start=1):
            if not uri:
                continue

            try:
                usage_percent = 0
                for slot in mongo_slots:
                    if slot.get('slot_id') == slot_num:
                        usage_percent = slot.get('usage_percent', 0)
                        break

                if usage_percent >= 94:  # SAFE_WRITE_PERCENT
                    self._storage_full_slots.add(slot_num)
                    logger.warning(f"[DB Router] Slot P{slot_num} is {usage_percent:.1f}% full - marking as FULL")
            except Exception as e:
                logger.error("[DB Router] Failed to check slot P%d", slot_num, exc_info=True)
    
    def get_user_slot(self, user_id: int) -> int:
        """Determine which database slot a user belongs to."""
        # Normalize to int (some callers pass string IDs)
        try:
            uid_int = int(user_id)
        except (TypeError, ValueError):
            uid_int = hash(str(user_id)) & 0x7FFFFFFF
        
        # Check if user already has an assigned slot
        user_key = str(uid_int)
        if user_key in self._routing_table:
            return self._routing_table[user_key]
        
        # Use modulo routing for new users (distribute across P1-P2 for hot users)
        active_slots = [s for s in range(1, 8) if s not in self._storage_full_slots]
        if not active_slots:
            active_slots = [1]  # Fallback to P1
        
        # Modulo routing for even distribution
        slot = active_slots[uid_int % len(active_slots)]
        self._routing_table[user_key] = slot
        
        return slot
    
    async def assign_new_slot(self, project_name: str, mongo_url: str) -> Dict[str, Any]:
        """Assign a new MongoDB URL to a project slot."""
        try:
            # Parse project number (e.g., 'p1' -> 1)
            project_num = int(project_name.lower().replace('p', ''))
            
            if not (1 <= project_num <= 7):
                return {'success': False, 'error': 'Invalid project number. Use P1-P7.'}
            
            # Add the MongoDB slot
            await asyncio.to_thread(add_mongo_slot, mongo_url, project_name=f"p{project_num}")
            
            # Remove from full slots if it was marked
            self._storage_full_slots.discard(project_num)
            
            # Update routing table
            await self._save_routing_table()
            
            return {
                'success': True,
                'message': f'Successfully added {project_name.upper()} to database routing'
            }
        except Exception as e:
            logger.warning("Exception: %s", str(e))
            return {'success': False, 'error': str(e)}
    
    async def get_slot_status(self) -> Dict[str, Any]:
        """Get status of all database slots."""
        status = {}
        
        full_status = await asyncio.to_thread(get_storage_status)
        mongo_slots = full_status.get('mongo_slots', [])
        
        for slot_num in range(1, 8):
            try:
                slot_info = next((s for s in mongo_slots if s.get('slot_id') == slot_num), {})
                status[f'P{slot_num}'] = {
                    'connected': slot_info.get('ok', False),
                    'usage_percent': slot_info.get('usage_percent', 0),
                    'data_size': slot_info.get('usage_bytes', 0),
                    'is_full': slot_num in self._storage_full_slots,
                }
            except Exception as e:
                status[f'P{slot_num}'] = {
                    'connected': False,
                    'error': str(e)
                }
        
        return status
    
    async def cleanup_inactive_users(self, days_inactive: int = 15):
        """Move inactive users to archive storage (P4)."""
        # This would be implemented in the main database module
        logger.info(f"[DB Router] Cleanup: moving users inactive for {days_inactive} days to archive")
        pass


# Global database router instance
DB_ROUTER = DatabaseRouter()



