async def addmongo_command(update, context, project_name: str, mongo_url: str) -> str:
    """Handle /addmongo command from owner."""
    try:
        # Validate project name
        if not project_name.lower().startswith('p'):
            return "⚠️ Invalid format. Use: /addmongo P1 <url>"
        
        project_num = int(project_name.lower().replace('p', ''))
        if not (1 <= project_num <= 7):
            return "⚠️ Invalid project number. Use P1 to P7."
        
        # Validate URL (basic check)
        if not mongo_url.startswith('mongodb'):
            return "⚠️ Invalid MongoDB URL. Must start with 'mongodb' or 'mongodb+srv'"
        
        # Also register with Atlas sync engine for periodic push
        try:
            add_atlas_uri(mongo_url)
        except Exception as e:
            logger.warning("Exception: %s", str(e))

        # Assign the slot
        result = await DB_ROUTER.assign_new_slot(project_name, mongo_url)
        
        if result['success']:
            # Get updated status
            status = await DB_ROUTER.get_slot_status()
            p_status = status.get(f'P{project_num}', {})
            
            response = f"✅ {result['message']}\n\n"
            response += f"📊 *Slot P{project_num} Status:*\n"
            response += f"• Connected: {p_status.get('connected', 'N/A')}\n"
            response += f"• Usage: {p_status.get('usage_percent', 0):.1f}%\n"
            response += f"• Data Size: {p_status.get('data_size', 'N/A')}\n"
            response += f"• Status: {'🔴 FULL' if p_status.get('is_full') else '🟢 Active'}"
            
            return response
        else:
            return f"⚠️ Failed to add slot: {result['error']}"
    
    except ValueError:
        return "⚠️ Invalid project number. Use P1 to P7."
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        return f"⚠️ Error: {str(e)}"


async def db_status_command(update, context) -> str:
    """Show status of all database slots."""
    try:
        status = await DB_ROUTER.get_slot_status()
        
        response = "🗄️ *Database Cluster Status*\n\n"
        
        for slot_name, slot_info in status.items():
            if slot_info.get('connected'):
                icon = "🔴" if slot_info.get('is_full') else "🟢"
                response += f"{icon} *{slot_name}*\n"
                response += f"   Usage: {slot_info.get('usage_percent', 0):.1f}%\n"
                response += f"   Size: {slot_info.get('data_size', 'N/A')}\n\n"
            else:
                response += f"⚫ *{slot_name}* - Not Connected\n\n"
        
        return response.strip()
    
    except Exception as e:
        logger.warning("Exception: %s", str(e))
        return f"⚠️ Error getting status: {str(e)}"


# Initialize on module load
async def initialize_db_router():
    """Initialize the database router on bot startup."""
    await DB_ROUTER.initialize()
    logger.info("✅ Database router initialized")

async def shutdown_db_router():
    """Shutdown the database router on bot shutdown."""
    pass

# ═══ MODULE: database.advanced_manager ═══

"""
Advanced Database Manager with Sub-Categories and Automatic Expansion
Implements scalable architecture for millions/billions of users with:
- Categories and sub-categories
- Automatic expansion when storage full
- /addmongo command integration
- Storage monitoring (520MB per category)
- Maximum compression and lightning speed
- Automatic new/old user distribution
"""

import asyncio
import logging
import time
import hashlib
import gzip
import json
import pickle
from typing import Dict, List, Optional, Tuple, Any
from datetime import datetime
from collections import OrderedDict
from functools import lru_cache

try:
    import motor.motor_asyncio as aiomotor
    _MOTOR_OK = True
except ModuleNotFoundError:
    aiomotor = None
    _MOTOR_OK = False

try:
    import lz4.frame
    _LZ4_OK = True
except ModuleNotFoundError:
    lz4 = None
    _LZ4_OK = False

logger = get_logger(__name__)

# Constants
MAX_CATEGORY_SIZE = 520 * 1024 * 1024  # 520MB per category
COMPRESSION_LEVEL = 9  # Maximum compression
SUBCATEGORY_PREFIX = "sub_"
USER_DISTRIBUTION_THRESHOLD = 10000  # Distribute after 10k users
CACHE_SIZE = 10000  # LRU cache size for frequently accessed data

class AdvancedDatabaseManager:
    """Advanced database manager with sub-categories and automatic expansion."""
    
    def __init__(self):
        self.categories = {
            "hot": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
            "state": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
            "archive": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
            "logs": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
            "admin": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
            "general": {"max_size": MAX_CATEGORY_SIZE, "current_size": 0, "sub_categories": []},
        }
        
        # Project mapping (p1, p2, etc.)
        self.projects = {}
        
        # Caching system for lightning-fast access
        self._cache = OrderedDict()
        self._compression_cache = {}
        
        self.load_config()
    
    def load_config(self):
        """Load configuration from database."""
        # Load project URLs
        partitions = get_partitions_config()
        for project_id, url in partitions.items():
            self.projects[project_id] = {
                "url": url,
                "category": self.detect_category_from_project(project_id),
                "size": 0,
                "user_count": 0,
                "last_used": time.time()
            }
        
        # Load category stats
        category_stats = get_setting_json("category_stats", default={})
        for category, stats in category_stats.items():
            if category in self.categories:
                allowed = {"current_size", "sub_categories"}
                for k, v in stats.items():
                    if k in allowed:
                        self.categories[category][k] = v
    
    def save_config(self):
        """Save configuration to database."""
        # Save category stats
        category_stats = {}
        for category, data in self.categories.items():
            category_stats[category] = {
                "current_size": data["current_size"],
                "sub_categories": data["sub_categories"]
            }
        save_setting_json("category_stats", category_stats)
    
    def detect_category_from_project(self, project_id: str) -> str:
        """Detect category from project ID (p1, p2, etc.)."""
        # Default mapping based on project number
        project_mapping = {
            "p1": "hot",
            "p2": "hot",
            "p3": "state",
            "p4": "archive",
            "p5": "logs",
            "p6": "admin",
            "p7": "general"
        }
        return project_mapping.get(project_id, "general")
    
    async def add_mongo_url(self, project_id: str, mongo_url: str, user_id: int) -> Dict[str, Any]:
        """
        Add a new MongoDB URL as a sub-category.
        Command: /addmongo p2 url
        """
        if user_id != OWNER_ID:
            return {"success": False, "error": "Only owner can add MongoDB URLs"}
        
        if not _MOTOR_OK:
            return {"success": False, "error": "Motor (MongoDB driver) not available"}
        
        # Validate MongoDB connection
        client = None
        try:
            client = aiomotor.AsyncIOMotorClient(
                mongo_url,
                serverSelectionTimeoutMS=15000,
                connectTimeoutMS=15000,
                socketTimeoutMS=30000,
            )
            await client.server_info()
        except Exception as e:
            logger.error("MongoDB connection failed", exc_info=True)
            return {"success": False, "error": f"MongoDB connection failed: {str(e)}"}
        finally:
            if client:
                try:
                    client.close()
                except Exception:
                    pass
        
        # Save to partitions
        partitions = await asyncio.to_thread(get_partitions_config)
        partitions[project_id] = mongo_url
        await asyncio.to_thread(save_partitions_config, partitions)
        
        # Update project mapping
        category = self.detect_category_from_project(project_id)
        self.projects[project_id] = {
            "url": mongo_url,
            "category": category,
            "size": 0,
            "user_count": 0,
            "last_used": time.time()
        }
        
        # Add as sub-category
        if project_id not in self.categories[category]["sub_categories"]:
            self.categories[category]["sub_categories"].append(project_id)
        
        await asyncio.to_thread(self.save_config)
        
        return {
            "success": True,
            "message": f"✅ Added MongoDB URL for {project_id} in category '{category}'",
            "project_id": project_id,
            "category": category
        }
    
    async def get_storage_stats(self) -> Dict[str, Any]:
        """Get comprehensive storage statistics."""
        stats = {
            "categories": {},
            "total_size": 0,
            "total_users": 0,
            "warnings": [],
            "recommendations": []
        }

        # Use accumulator to avoid destructive zeroing of categories on partial failure
        new_sizes: Dict[str, int] = {}
        
        # Get stats for each project
        for project_id, project_data in self.projects.items():
            if not _MOTOR_OK:
                continue
            
            client = None
            try:
                client = aiomotor.AsyncIOMotorClient(
                    project_data["url"],
                    serverSelectionTimeoutMS=15000,
                )
                db = client[MONGO_DB_NAME]
                db_stats = await db.command("dbstats")
                data_size = db_stats.get("dataSize", 0)
                storage_size = db_stats.get("storageSize", 0)
                
                # Count users in users collection
                users_count = await db.users.count_documents({})
                
                project_data["size"] = data_size
                project_data["user_count"] = users_count
                project_data["last_used"] = time.time()
                
                # Accumulate category sizes
                category = project_data["category"]
                new_sizes[category] = new_sizes.get(category, 0) + data_size
                
                stats["total_size"] += data_size
                stats["total_users"] += users_count
                
            except Exception as e:
                logger.error("Failed to get stats for %s", project_id, exc_info=True)
            finally:
                if client:
                    try:
                        client.close()
                    except Exception:
                        pass
        
        # Apply accumulated sizes atomically
        for category in self.categories:
            size = new_sizes.get(category)
            if size is not None:
                self.categories[category]["current_size"] = size
        
        # Prepare category stats
        for category, data in self.categories.items():
            usage_percent = (data["current_size"] / data["max_size"] * 100) if data["max_size"] > 0 else 0
            stats["categories"][category] = {
                "current_size": data["current_size"],
                "current_size_fmt": format_bytes(data["current_size"]),
                "max_size": data["max_size"],
                "max_size_fmt": format_bytes(data["max_size"]),
                "usage_percent": round(usage_percent, 2),
                "sub_categories": data["sub_categories"],
                "needs_expansion": usage_percent >= 85
            }
            
            if usage_percent >= 90:
                stats["warnings"].append(f"⚠️ Category '{category}' is {usage_percent:.1f}% full")
            if usage_percent > 85:
                stats["recommendations"].append(f"📈 Consider adding sub-category for '{category}'")
        
        await asyncio.to_thread(self.save_config)
        return stats
    
    def _cache_get(self, key: str) -> Any:
        """Get item from cache with LRU eviction."""
        if key in self._cache:
            # Move to end (most recently used)
            value = self._cache.pop(key)
            self._cache[key] = value
            self._hit_count = getattr(self, "_hit_count", 0) + 1
            return value
        self._miss_count = getattr(self, "_miss_count", 0) + 1
        return None
    
    def _cache_set(self, key: str, value: Any) -> None:
        """Set item in cache with LRU eviction."""
        if key in self._cache:
            self._cache.pop(key)
        elif len(self._cache) >= CACHE_SIZE:
            # Remove least recently used item
            self._cache.popitem(last=False)
        self._cache[key] = value
    
    def compress_data(self, data: Any, use_lz4: bool = True) -> bytes:
        """
        Maximum compression for data storage with intelligent algorithm selection.
        Returns compressed bytes with header indicating compression method.
        """
        # Try to get from compression cache
        data_hash = hashlib.md5(pickle.dumps(data)).hexdigest()
        cache_key = f"compress_{data_hash}"
        
        cached = self._compression_cache.get(cache_key)
        if cached:
            return cached
        
        # Choose best compression method based on data size
        json_str = json.dumps(data, separators=(',', ':'))
        json_bytes = json_str.encode('utf-8')
        
        if use_lz4 and _LZ4_OK and len(json_bytes) > 100:  # LZ4 better for larger data
            try:
                compressed = lz4.frame.compress(json_bytes)
                # Add header: 'LZ4' + 1 byte for method
                result = b'LZ4' + compressed
            except Exception:
                # Fallback to gzip
                compressed = gzip.compress(json_bytes, compresslevel=COMPRESSION_LEVEL)
                result = b'GZ9' + compressed
        else:
            # Use gzip for small data or when LZ4 not available
            compressed = gzip.compress(json_bytes, compresslevel=COMPRESSION_LEVEL)
            result = b'GZ9' + compressed
        
        # Cache the result
        self._compression_cache[cache_key] = result
        if len(self._compression_cache) > 1000:
            # Limit cache size
            keys = list(self._compression_cache.keys())
            for k in keys[:100]:
                self._compression_cache.pop(k, None)
        
        return result
    
    def decompress_data(self, compressed: bytes) -> Any:
        """Decompress data with automatic method detection."""
        if len(compressed) < 4:
            return {}
        
        # Check compression method from header
        header = compressed[:3]
        data = compressed[3:]
        
        try:
            if header == b'LZ4' and _LZ4_OK:
                json_bytes = lz4.frame.decompress(data)
            elif header == b'GZ9':
                json_bytes = gzip.decompress(data)
            else:
                # Assume gzip (backward compatibility)
                json_bytes = gzip.decompress(compressed)
            
            json_str = json_bytes.decode('utf-8')
            return json.loads(json_str)
        except Exception as e:
            logger.warning("Exception: %s", str(e))
            return {}
    
    def optimize_data_structure(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Optimize data structure for storage efficiency:
        - Remove None values
        - Convert large numbers to strings if appropriate
        - Flatten nested structures when possible
        """
        optimized = {}
        for key, value in data.items():
            if value is None:
                continue
            elif isinstance(value, dict):
                # Recursively optimize nested dicts
                optimized[key] = self.optimize_data_structure(value)
            elif isinstance(value, list) and len(value) > 0 and isinstance(value[0], dict):
                # Optimize list of dicts
                optimized[key] = [self.optimize_data_structure(item) for item in value]
            elif isinstance(value, (int, float)) and abs(value) > 10**9:
                # Large numbers as strings
                optimized[key] = str(value)
            else:
                optimized[key] = value
        return optimized
    
    def distribute_user(self, user_id: int, is_new_user: bool = True) -> Tuple[str, str]:
        """
        Distribute user to appropriate project based on:
        - New users go to newer sub-categories
        - Old users stay in their current location
        - Balance load across sub-categories
        """
        user_hash = hashlib.md5(str(user_id).encode()).hexdigest()
        hash_int = int(user_hash[:8], 16)
        
        # Determine target category based on user type
        if is_new_user:
            # New users go to less loaded categories
            target_category = self.get_least_loaded_category()
        else:
            # Old users: determine based on hash for consistency
            categories = list(self.categories.keys())
            target_category = categories[hash_int % len(categories)]
        
        # Get available projects for this category
        available_projects = []
        for project_id, project_data in self.projects.items():
            if project_data["category"] == target_category:
                available_projects.append((project_id, project_data["user_count"]))
        
        if not available_projects:
            # Fallback to any project
            for project_id, project_data in self.projects.items():
                available_projects.append((project_id, project_data["user_count"]))
        
        if not available_projects:
            return "p1", "hot"  # Default fallback
        
        # Select project with least users
        available_projects.sort(key=lambda x: x[1])
        selected_project = available_projects[0][0]
        
        return selected_project, target_category
    
    def get_least_loaded_category(self) -> str:
        """Get the category with the most available space."""
        min_usage = float('inf')
        best_category = "general"
        
        for category, data in self.categories.items():
            usage_percent = (data["current_size"] / data["max_size"] * 100) if data["max_size"] > 0 else 0
            if usage_percent < min_usage:
                min_usage = usage_percent
                best_category = category
        
        return best_category
    
    async def auto_expand_category(self, category: str) -> Optional[str]:
        """
        Automatically expand a category by creating a new sub-category.
        Returns new project ID if expansion was successful.
        """
        if category not in self.categories:
            return None
        
        # Check if expansion is needed
        usage_percent = (self.categories[category]["current_size"] / 
                        self.categories[category]["max_size"] * 100)
        
        if usage_percent < 90:
            return None  # No expansion needed yet
        
        # Generate new project ID
        existing_subs = self.categories[category]["sub_categories"]
        sub_count = len(existing_subs) + 1
        new_project_id = f"{category}_sub{sub_count}"
        
        # In real implementation, this would:
        # 1. Create new MongoDB database
        # 2. Configure replication/sharding
        # 3. Update routing tables
        # 4. Start migrating some users
        
        # For now, just log and return placeholder
        logger.info(f"Auto-expanding category '{category}' with new sub-category '{new_project_id}'")
        
        # Add to sub-categories list
        self.categories[category]["sub_categories"].append(new_project_id)
        await asyncio.to_thread(self.save_config)
        
        return new_project_id
    
    def get_performance_metrics(self) -> Dict[str, Any]:
        """Get performance metrics for monitoring."""
        cache_size = len(self._cache)
        compression_cache_size = len(self._compression_cache)
        hit_count = getattr(self, "_hit_count", 0)
        miss_count = getattr(self, "_miss_count", 0)
        total = hit_count + miss_count
        
        # Calculate compression ratio (estimate)
        sample_data = {"test": "sample", "number": 12345, "list": [1, 2, 3]}
        original_size = len(json.dumps(sample_data).encode('utf-8'))
        compressed_size = len(self.compress_data(sample_data))
        compression_ratio = (1 - compressed_size / original_size) * 100 if original_size > 0 else 0
        
        return {
            "cache": {
                "size": cache_size,
                "max_size": CACHE_SIZE,
                "hits": hit_count,
                "misses": miss_count,
                "hit_rate": (hit_count / max(total, 1)) * 100
            },
            "compression": {
                "cache_size": compression_cache_size,
                "compression_ratio": round(compression_ratio, 2),
                "original_size": original_size,
                "compressed_size": compressed_size
            },
            "categories": {
                "count": len(self.categories),
                "total_subcategories": sum(len(cat["sub_categories"]) for cat in self.categories.values())
            },
            "projects": {
                "count": len(self.projects),
                "active": sum(1 for p in self.projects.values() if p.get("user_count", 0) > 0)
            }
        }
    
    async def get_owner_stats(self) -> Dict[str, Any]:
        """Get statistics for owner with p1=number /520mb format."""
        stats = await self.get_storage_stats()
        
        owner_stats = {}
        for category, data in stats["categories"].items():
            # Format: p1=number /520mb
            current_mb = data["current_size"] / (1024 * 1024)
            max_mb = data["max_size"] / (1024 * 1024)
            owner_stats[category] = f"p{list(self.categories.keys()).index(category)+1}={current_mb:.1f}MB / {max_mb:.0f}MB"
        
        # Get performance metrics
        perf = await asyncio.to_thread(self.get_performance_metrics)
        
        return {
            "storage_stats": owner_stats,
            "total_users": stats["total_users"],
            "total_size_fmt": format_bytes(stats["total_size"]),
            "warnings": stats["warnings"],
            "recommendations": stats["recommendations"],
            "performance": {
                "cache_hit_rate": f"{perf['cache']['hit_rate']:.1f}%",
                "compression_ratio": f"{perf['compression']['compression_ratio']:.1f}%",
                "cache_size": f"{perf['cache']['size']}/{perf['cache']['max_size']}"
            }
        }

