# ═══ MODULE: economy.leaderboard ═══

import asyncio
import html
import re
import time

from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update
from telegram.error import TelegramError
from telegram.ext import ContextTypes


logger = get_logger(__name__)

_lb_cache: dict = {}
_lb_cache_lock: asyncio.Lock | None = None

def invalidate() -> None:
    """Invalidate all leaderboard caches. Call after a significant balance/captures change."""
    _lb_cache.clear()


_enrich_cache: dict[str, str] = {}
_enrich_cache_ts: float = 0.0
_ENRICH_TTL = 3600
_enrich_inflight: set[str] = set()


async def _enrich_missing_names(rows: list, bot) -> None:
    """For rows whose label is the "User" fallback (no username, no first_name,
    no display_name stored in DB), fetch a live name from Telegram and persist
    it. Cached for 1h per uid to avoid hitting Telegram on every render.
    Mutates `rows` in place. Safe to call on rows that already have labels.
    """
    global _enrich_cache_ts
    if not bot:
        return
    now_ts = time.time()
    if now_ts - _enrich_cache_ts > _ENRICH_TTL:
        _enrich_cache.clear()
        _enrich_cache_ts = now_ts

    missing: list = []
    for row in rows:
        label = row.get("label", "")
        if label and not label.startswith("User"):
            continue
        uid = str(row.get("user_id", ""))
        if not uid or uid in _enrich_inflight:
            continue
        if uid in _enrich_cache:
            row["label"] = _enrich_cache[uid]
            continue
        missing.append(row)

    for row in missing:
        uid = str(row.get("user_id", ""))
        _enrich_inflight.add(uid)
        try:
            chat = await bot.get_chat(int(str(uid).split(":")[-1]))
            if chat.is_bot:
                row["label"] = f"Bot{uid[-4:]}"
                _enrich_cache[uid] = row["label"]
                _enrich_inflight.discard(uid)
                continue
            username = getattr(chat, "username", None)
            first_name = getattr(chat, "first_name", None)
            full_name = getattr(chat, "full_name", None) or (
                " ".join([p for p in [first_name, getattr(chat, "last_name", None)] if p])
            )
            if username:
                new_label = f"@{username}"
            elif first_name:
                new_label = first_name
            elif full_name:
                new_label = full_name.split(" ", 1)[0]
            else:
                new_label = f"User{uid[-4:]}"
            row["label"] = new_label
            _enrich_cache[uid] = new_label
            # Persist to DB so the next leaderboard render is fast and offline
            try:
                set_fields = {
                    "username": username,
                    "first_name": first_name,
                    "display_name": full_name,
                }
                set_fields = {k: v for k, v in set_fields.items() if v}
                if set_fields:
                    await asyncio.to_thread(update_user_atomic, uid, set_fields=set_fields)
            except Exception as exc:
                logger.debug("LB enrich persist failed for %s: %s", uid, exc)
        except Exception as exc:
            logger.debug("LB enrich get_chat failed for %s: %s", uid, exc)
        finally:
            _enrich_inflight.discard(uid)


async def _get_lb_lock() -> asyncio.Lock:
    global _lb_cache_lock
    if _lb_cache_lock is None:
        _lb_cache_lock = asyncio.Lock()
    return _lb_cache_lock
_request_count = 0
_last_reset = 0
FOOTER = "⭐ = Pʀᴇᴍɪᴜᴍ • 👤 = Mᴇᴍʙᴇʀ\n✅ Uᴘɢʀᴀᴅᴇ Tᴏ Pʀᴇᴍɪᴜᴍ Uꜱɪɴɢ /Buy !"


def _now() -> int:
    return int(time.time())


def _adaptive_ttl() -> int:
    global _request_count, _last_reset
    if time.time() - _last_reset > 3600:
        _request_count = 0
        _last_reset = time.time()
    return 1800 if _request_count > 50 else 900


def _sort_key(lb_type: str, period: str) -> str:
    if lb_type == "capt":
        return {
            "overall": "captures",
            "weekly": "weekly_captures",
            "daily": "daily_captures",
        }.get(period, "captures")
    return {"overall": "balance", "weekly": "weekly_income", "daily": "daily_income"}.get(
        period, "balance"
    )


async def _fetch(lb_type: str, period: str, limit: int = 10, bot=None) -> list:
    global _request_count
    _request_count += 1
    sort_key = _sort_key(lb_type, period)
    cache_key = f"lb_{lb_type}_{period}"
    ttl = _adaptive_ttl()
    # Lock-free fast path: check cache without acquiring the lock
    # (dict reads are atomic in CPython; the only mutations are below
    # the lock-protected section, so a stale-read race is acceptable)
    cached = _lb_cache.get(cache_key)
    if cached and _now() - cached["ts"] < ttl:
        rows = cached["data"]
        abuse_words = cached.get("abuse_words", [])
        if bot is not None:
            await _enrich_missing_names(rows, bot)
        return rows, abuse_words

    rows = []
    fetch_success = False
    try:
        rows = await asyncio.to_thread(leaderboard_rows, sort_key, limit=limit)
        fetch_success = True
    except Exception as exc:
        logger.warning("LB fetch error: %s", exc, exc_info=True)

    if period in ("weekly", "daily") and len(rows) < limit:
        try:
            overall_rows = await asyncio.to_thread(
                leaderboard_rows, _sort_key(lb_type, "overall"), limit=limit
            )
            existing_ids = {r.get("user_id") for r in rows}
            for r in overall_rows:
                if r.get("user_id") not in existing_ids:
                    if int(r.get("value", 0) or 0) > 0:
                        r = dict(r)
                        r["value"] = 0
                        rows.append(r)
                        if len(rows) >= limit:
                            break
        except Exception as exc:
            logger.warning("LB period fallback error: %s", exc, exc_info=True)

    # FIX: Load abuse words inside the thread-dispatched section, not in event loop
    abuse_words = []
    try:
        abuse_words = await asyncio.to_thread(get_setting_json, "abuse_words", []) or []
    except Exception:
        logger.error("Unexpected error", exc_info=True)

    # Only acquire the lock for the actual write/miss-handling
    async with await _get_lb_lock():
        if fetch_success or cache_key not in _lb_cache:
            _lb_cache[cache_key] = {"data": rows, "ts": _now(), "abuse_words": abuse_words}
        else:
            cached = _lb_cache.get(cache_key)
            if cached:
                rows = cached["data"]
                abuse_words = cached.get("abuse_words", [])
    return rows, abuse_words


def _period_title(period: str) -> str:
    return {"overall": "Oᴠᴇʀᴀʟʟ", "weekly": "Wᴇᴇᴋʟʏ", "daily": "Dᴀɪʟʏ"}.get(period, period)


def _name_has_abuse(name: str, abuse_words: list) -> bool:
    """Check if a name contains any abuse words (case-insensitive)."""
    if not abuse_words or not name:
        return False
    name_lower = name.lower()
    for word in abuse_words:
        if re.search(rf'\b{re.escape(word)}\b', name_lower):
            return True
    return False


def _format(lb_type: str, entries: list, period: str, abuse_words: list | None = None) -> str:
    title = _period_title(period)
    if lb_type == "rich":
        metric = "Rɪᴄʜᴇsᴛ"
    else:
        metric = "Cᴀᴘᴛᴜʀᴇs"
    if not entries:
        return f"📈 {title} Tᴏᴘ 10 {metric} !\n\n😔 No data yet.\n\n{FOOTER}"

    if abuse_words is None:
        abuse_words = []

    # Filter out abusive entries first, then take top 10
    filtered = [e for e in entries if not _name_has_abuse(str(e.get("label", "?")), abuse_words)]

    lines = [f"📈 {title} Tᴏᴘ 10 {metric} !", ""]
    for idx, entry in enumerate(filtered[:10], 1):
        badge = html.escape(str(entry.get("badge", "👤")))
        raw_name = str(entry.get("label", "?"))
        user_id = str(entry.get("user_id", ""))
        value = int(entry.get("value", 0) or 0)

        if user_id:
            name = f'<a href="tg://user?id={html.escape(user_id)}">{html.escape(raw_name)}</a>'
        else:
            name = html.escape(raw_name)

        if lb_type == "rich":
            lines.append(f"{badge} {name}: ${value:,}")
        else:
            lines.append(f"{badge} {name}: {value:,}")

    lines.append("")
    lines.append(FOOTER)
    return "\n".join(lines)


def _period_kb(lb_type: str, current: str = "overall") -> InlineKeyboardMarkup:
    def btn(key: str, label: str) -> InlineKeyboardButton:
        if key == current:
            return InlineKeyboardButton(f"▸ {label} ◂", callback_data=f"lb_{lb_type}_{key}")
        return InlineKeyboardButton(f"  {label}  ", callback_data=f"lb_{lb_type}_{key}")

    return InlineKeyboardMarkup(
        [[btn("overall", "Overall"), btn("weekly", "Weekly"), btn("daily", "Daily")]]
    )


async def toprichs(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await verify_guard(update, ctx):
        return
    if not update.effective_message:
        return
    data, abuse_words = await _fetch("rich", "overall", bot=ctx.bot)
    await update.effective_message.reply_html(
        _format("rich", data, "overall", abuse_words),
        reply_markup=_period_kb("rich", "overall"),
    )


async def topcapts(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if await verify_guard(update, ctx):
        return
    if not update.effective_message:
        return
    data, abuse_words = await _fetch("capt", "overall", bot=ctx.bot)
    await update.effective_message.reply_html(
        _format("capt", data, "overall", abuse_words),
        reply_markup=_period_kb("capt", "overall"),
    )


async def leaderboard_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    parts = q.data.split("_", 2)
    if len(parts) < 3:
        await q.answer("Invalid data.")
        return
    _, lb_type, period = parts
    try:
        data, abuse_words = await _fetch(lb_type, period, bot=ctx.bot)
        await q.answer()
        await q.edit_message_text(
            _format(lb_type, data, period, abuse_words),
            parse_mode="HTML",
            reply_markup=_period_kb(lb_type, period),
        )
    except TelegramError as exc:
        logger.debug(f"Leaderboard callback edit failed: {exc}")

# ═══ MODULE: database.heavy_cache ═══

_lb_invalidate = invalidate
# =========================================
# 🗄️  HEAVY CACHE — database/heavy_cache.py
# Aggressive caching for the most expensive MongoDB operations
# (list_all_users, get_registered_chats, sticker pool).
# Invalidate only on actual data changes.
# =========================================
import time
import threading
from typing import Any, Callable, Optional


logger = get_logger(__name__)


# ── list_all_users cache (5min TTL) ───────────────────────────────────────────
# /broadcast, /stats, /users — these scan every user in the DB.
# For 1M users that's 1M document reads. We cache it in-memory.
_USER_LIST_CACHE: Optional[list] = None
_USER_LIST_TS: float = 0.0
_USER_LIST_TTL = 300.0
_USER_LIST_MAX = 500_000  # cap to prevent memory blow-up
_user_list_lock = threading.Lock()
_user_list_in_flight: Optional[threading.Thread] = None


def get_cached_all_users(fetcher: Callable[[], list]) -> list:
    """Returns cached list of all users, refreshing every 5 minutes.
    Bound at _USER_LIST_MAX entries to prevent memory blow-up.
    """
    global _USER_LIST_CACHE, _USER_LIST_TS

    # Lock-free fast path
    if _USER_LIST_CACHE is not None and (time.time() - _USER_LIST_TS) < _USER_LIST_TTL:
        return _USER_LIST_CACHE

    # Slow path: refresh (lock to prevent thundering herd)
    with _user_list_lock:
        if _USER_LIST_CACHE is not None and (time.time() - _USER_LIST_TS) < _USER_LIST_TTL:
            return _USER_LIST_CACHE  # already refreshed by another thread
        try:
            val = fetcher() or []
        except Exception as exc:
            logger.debug("get_cached_all_users fetch failed: %s", exc)
            return _USER_LIST_CACHE or []
        if len(val) > _USER_LIST_MAX:
            logger.warning(f"User list truncated from {len(val):,} to {_USER_LIST_MAX:,}")
            val = val[:_USER_LIST_MAX]
        if not val:
            # Never cache an empty list (e.g. boot-time fetch before TiDB is
            # available) — retry on the next call instead of serving an
            # empty list for the whole TTL.
            return _USER_LIST_CACHE or []
        _USER_LIST_CACHE = val
        _USER_LIST_TS = time.time()
    return val


def invalidate_user_list() -> None:
    """Call when a new user is created/registered."""
    global _USER_LIST_CACHE, _USER_LIST_TS
    _USER_LIST_CACHE = None
    _USER_LIST_TS = 0.0


# ── get_registered_chats cache (5min TTL) ─────────────────────────────────────
# Same problem as user list. Cache for 5 minutes.
_CHAT_LIST_CACHE: Optional[list] = None
_CHAT_LIST_TS: float = 0.0
_CHAT_LIST_TTL = 300.0
_CHAT_LIST_MAX = 200_000
_chat_list_lock = threading.Lock()


def get_cached_chats(fetcher: Callable[[], list]) -> list:
    """Returns cached list of all registered chats, refreshing every 5 minutes."""
    global _CHAT_LIST_CACHE, _CHAT_LIST_TS

    if _CHAT_LIST_CACHE is not None and (time.time() - _CHAT_LIST_TS) < _CHAT_LIST_TTL:
        return _CHAT_LIST_CACHE

    with _chat_list_lock:
        if _CHAT_LIST_CACHE is not None and (time.time() - _CHAT_LIST_TS) < _CHAT_LIST_TTL:
            return _CHAT_LIST_CACHE
        try:
            val = fetcher() or []
        except Exception as exc:
            logger.debug("get_cached_chats fetch failed: %s", exc)
            return _CHAT_LIST_CACHE or []
        if len(val) > _CHAT_LIST_MAX:
            val = val[:_CHAT_LIST_MAX]
        if not val:
            # Never cache an empty list (e.g. boot-time fetch before TiDB is
            # available) — retry on the next call instead of serving an
            # empty list for the whole TTL.
            return _CHAT_LIST_CACHE or []
        _CHAT_LIST_CACHE = val
        _CHAT_LIST_TS = time.time()
    return val


def invalidate_chat_list() -> None:
    """Call when a new chat is registered/left."""
    global _CHAT_LIST_CACHE, _CHAT_LIST_TS
    _CHAT_LIST_CACHE = None
    _CHAT_LIST_TS = 0.0


# ── Sticker pool cache (5min TTL) ─────────────────────────────────────────────
# reply_stickers pool is read on every sticker trigger. Cache it.
_STICKER_POOL_CACHE: Optional[Any] = None
_STICKER_POOL_TS: float = 0.0
_STICKER_POOL_TTL = 300.0
_sticker_pool_lock = threading.Lock()


def get_cached_sticker_pool(fetcher: Callable[[], Any]) -> Any:
    """Returns cached sticker pool, refreshing every 5 minutes."""
    global _STICKER_POOL_CACHE, _STICKER_POOL_TS

    if _STICKER_POOL_CACHE is not None and (time.time() - _STICKER_POOL_TS) < _STICKER_POOL_TTL:
        return _STICKER_POOL_CACHE

    with _sticker_pool_lock:
        if _STICKER_POOL_CACHE is not None and (time.time() - _STICKER_POOL_TS) < _STICKER_POOL_TTL:
            return _STICKER_POOL_CACHE
        try:
            val = fetcher() or {}
        except Exception as exc:
            logger.debug("get_cached_sticker_pool fetch failed: %s", exc)
            return _STICKER_POOL_CACHE or {}
        _STICKER_POOL_CACHE = val
        _STICKER_POOL_TS = time.time()
    return val


def invalidate_sticker_pool() -> None:
    """Call when sticker pool is modified."""
    global _STICKER_POOL_CACHE, _STICKER_POOL_TS
    _STICKER_POOL_CACHE = None
    _STICKER_POOL_TS = 0.0


# ── Leaderboard cache invalidation hook ──────────────────────────────────────
# When a user's balance/captures changes meaningfully, we may want to invalidate
# the leaderboard. This is in economy/leaderboard.py — we just expose a marker.
def invalidate_leaderboard():
    """Hook for any module that updates user balance/captures heavily."""
    try:
        _lb_invalidate()
    except Exception:
        pass


# ── Stats ─────────────────────────────────────────────────────────────────────
def heavy_cache_stats() -> dict:
    return {
        "user_list_cached": _USER_LIST_CACHE is not None,
        "user_list_size": len(_USER_LIST_CACHE) if _USER_LIST_CACHE else 0,
        "user_list_age_s": round(time.time() - _USER_LIST_TS, 1) if _USER_LIST_TS else None,
        "chat_list_cached": _CHAT_LIST_CACHE is not None,
        "chat_list_size": len(_CHAT_LIST_CACHE) if _CHAT_LIST_CACHE else 0,
        "chat_list_age_s": round(time.time() - _CHAT_LIST_TS, 1) if _CHAT_LIST_TS else None,
        "sticker_pool_cached": _STICKER_POOL_CACHE is not None,
        "sticker_pool_size": len(_STICKER_POOL_CACHE) if _STICKER_POOL_CACHE else 0,
        "sticker_pool_age_s": round(time.time() - _STICKER_POOL_TS, 1) if _STICKER_POOL_TS else None,
    }

# ═══ MODULE: database.auto_cleanup ═══

# =========================================
# 🧹 AUTO CLEANUP — database/auto_cleanup.py
# Periodically removes temp/expired data to save free-tier storage.
# Runs at startup + every hour via background task.
#
# Strategy:
#   • For settings stored as JSON in MongoDB: rely on MongoDB TTL index
#     (set on `_ttl` field) where possible
#   • For records that can't have a TTL: use targeted delete_many with filters
#   • For local files: simple age-based cleanup
# =========================================
import asyncio
import glob
import os
import time
import threading
from pathlib import Path
from typing import Any


logger = get_logger(__name__)


# ── Config ───────────────────────────────────────────────────────────────────
_WARN_DECAY_DAYS = 90                  # warns older than 90d lose history
_CAPTURED_AUTO_RELEASE_DAYS = 7        # auto-release captured targets after 7d
_BROADCAST_CHECKPOINT_MAX_AGE = 3600   # 1 hour — orphan broadcast checkpoints
_TEMP_FILE_MAX_AGE = 86400             # 1 day — orphan temp files
_STICKER_POOL_MAX = 1000               # keep last 1000 stickers in pool
_STICKER_GIFS_MAX = 500                # keep last 500 GIFs
_CLEANUP_INTERVAL = 3600               # 1 hour

_stats = {
    "runs": 0,
    "last_run": 0.0,
    "broadcast_checkpoints_removed": 0,
    "temp_files_removed": 0,
    "sticker_pool_trimmed": 0,
    "stale_captures_released": 0,
    "local_bytes_freed": 0,
    "errors": 0,
}
_stats_lock = threading.Lock()


def _record(key: str, n: int = 1) -> None:
    with _stats_lock:
        _stats[key] = _stats.get(key, 0) + n


# ── 1. Ensure MongoDB TTL indexes exist ─────────────────────────────────────
def ensure_ttl_indexes() -> None:
    """Create MongoDB TTL indexes for temp data.
    MongoDB will auto-delete documents past the expiration time.
    """
    try:
        for slot in _mongo_slots:
            if not slot.get("ok"):
                continue
            db = slot.get("db")
            if db is None:
                continue
            # Settings collection: TTL on _ttl field (only documents with _ttl get auto-deleted)
            try:
                col = db.get_collection("bot_settings")
                col.create_index("ttl_expires_at", expireAfterSeconds=0, name="auto_ttl")
            except Exception:
                pass
            # Runtime state (already has one)
            try:
                col = db.get_collection("runtime_state")
                col.create_index("ttl_expires_at", expireAfterSeconds=0, name="auto_ttl")
            except Exception:
                pass
    except Exception:
        logger.debug("ensure_ttl_indexes failed", exc_info=True)


# ── 2. Broadcast checkpoint file cleanup ────────────────────────────────────
def cleanup_broadcast_checkpoints() -> int:
    """Delete orphan broadcast checkpoint files older than 1 hour."""
    count = 0
    try:
        for path in glob.glob("broadcast_checkpoint*.json"):
            try:
                if not os.path.exists(path):
                    continue
                mtime = os.path.getmtime(path)
                if time.time() - mtime > _BROADCAST_CHECKPOINT_MAX_AGE:
                    os.remove(path)
                    count += 1
            except Exception:
                continue
    except Exception:
        pass
    return count


# ── 3. Orphan temp files ───────────────────────────────────────────────────
def cleanup_temp_files() -> int:
    """Delete orphan temp files older than 1 day."""
    count = 0
    try:
        data_dir = Path("data")
        if not data_dir.exists():
            return 0
        for pattern in ("*.tmp", "*.bak", "*.old", "*.swp", "*.pyc"):
            for path in data_dir.rglob(pattern):
                try:
                    if time.time() - path.stat().st_mtime > _TEMP_FILE_MAX_AGE:
                        path.unlink()
                        count += 1
                except Exception:
                    continue
    except Exception:
        pass
    return count


# ── 4. Sticker pool trim ───────────────────────────────────────────────────
def cleanup_sticker_pool() -> int:
    """Trim sticker pool to keep only the most recent N stickers."""
    trimmed = 0
    try:
        data = get_sticker_setting("reply_stickers") or {}
        pool = data.get("pool", [])
        if len(pool) > _STICKER_POOL_MAX:
            data["pool"] = pool[-_STICKER_POOL_MAX:]
            trimmed = len(pool) - _STICKER_POOL_MAX
        gifs = data.get("gifs", [])
        if len(gifs) > _STICKER_GIFS_MAX:
            data["gifs"] = gifs[-_STICKER_GIFS_MAX:]
            trimmed += len(gifs) - _STICKER_GIFS_MAX
        if trimmed > 0:
            save_sticker_setting("reply_stickers", data)
            invalidate_sticker_pool()
    except Exception:
        pass
    return trimmed


# ── 5. Stale captures (auto-release after 7 days) ──────────────────────────
def cleanup_stale_captures() -> int:
    """Auto-release users who have been captured for > 7 days.

    Stored as fields on the user record: captured, captured_by, capture_time.
    Uses update_many with a filter — single DB call regardless of user count.
    """
    cutoff = int(time.time()) - (_CAPTURED_AUTO_RELEASE_DAYS * 86400)
    count = 0
    try:
        if _use_tidb():
            tidb = _get_tidb()
            if tidb and hasattr(tidb, "tidb_release_stale_captures"):
                count += tidb.tidb_release_stale_captures(cutoff)
                return count
        for slot in _writable_general_slots():
            db = slot.get("db")
            if db is None:
                continue
            col = db.get_collection("users")
            try:
                result = col.update_many(
                    {"captured": True, "capture_time": {"$lt": cutoff, "$gt": 0}},
                    {"$set": {
                        "captured": False,
                        "captured_by": None,
                        "capture_time": 0,
                        "bounty_dollar": 0,
                        "bounty_rp": 0,
                    }}
                )
                count += result.modified_count
            except Exception:
                continue
    except Exception:
        logger.debug("cleanup_stale_captures failed", exc_info=True)
    return count


# ── 6. Warn history decay (delete entries older than 90 days) ──────────────
def decay_old_warns() -> int:
    """Remove warn history entries older than 90 days from a single user.

    Note: This is intentionally conservative — it doesn't enumerate all users.
    It's invoked lazily on next /warns call (which already runs cleanup as
    part of the read path). The actual bulk cleanup uses MongoDB TTL.
    """
    # Implementation note: the actual decay happens in get_user_warns()
    # (lazy cleanup on read). This is here for future scheduled use.
    return 0


# ── 7. Local SQLite compact (WAL checkpoint + VACUUM) ──────────────────────
def compact_local_storage() -> int:
    """Compact local SQLite relay: WAL checkpoint + VACUUM (once per day)."""
    try:
        _relay_compact()
    except Exception:
        pass
    return 0


# ── Master cleanup run ──────────────────────────────────────────────────────
def run_all_cleanups() -> dict:
    """Run all cleanup tasks. Returns stats dict (only int values)."""
    started = time.time()
    out = {}
    for name, fn in (
        ("broadcast_checkpoints_removed", cleanup_broadcast_checkpoints),
        ("temp_files_removed", cleanup_temp_files),
        ("sticker_pool_trimmed", cleanup_sticker_pool),
        ("stale_captures_released", cleanup_stale_captures),
        ("local_bytes_freed", compact_local_storage),
    ):
        try:
            out[name] = fn()
        except Exception as exc:
            out[name] = 0
            logger.debug(f"{name} error: {exc}")
            with _stats_lock:
                _stats["errors"] += 1

    out["elapsed_ms"] = round((time.time() - started) * 1000, 1)

    with _stats_lock:
        _stats["runs"] += 1
        _stats["last_run"] = time.time()
        for k, v in out.items():
            if isinstance(v, int) and k != "elapsed_ms":
                _stats[k] = _stats.get(k, 0) + v

    return out


# ── Background loop ──────────────────────────────────────────────────────────
_task: asyncio.Task | None = None
_running = False


async def _cleanup_loop():
    """Background task: run cleanups every _CLEANUP_INTERVAL seconds."""
    global _running
    _running = True
    while _running:
        try:
            await asyncio.sleep(_CLEANUP_INTERVAL)
            await asyncio.to_thread(run_all_cleanups)
        except asyncio.CancelledError:
            break
        except Exception:
            logger.debug("Cleanup loop error", exc_info=True)
            await asyncio.sleep(60)


def start_cleanup_loop() -> None:
    """Start the background cleanup task (idempotent)."""
    global _task
    if _task is not None and not _task.done():
        return
    try:
        _task = asyncio.create_task(_cleanup_loop())
        logger.info("✓ Started auto-cleanup loop (every 1h)")
    except RuntimeError:
        # No running event loop yet — caller must call start later
        logger.debug("start_cleanup_loop: no event loop yet")


def stop_cleanup_loop() -> None:
    global _running
    _running = False
    if _task and not _task.done():
        _task.cancel()


# ── Stats ─────────────────────────────────────────────────────────────────────
def cleanup_stats() -> dict:
    with _stats_lock:
        return dict(_stats)

# ═══ MODULE: database.performance_indexes ═══

"""
Database Performance Optimization Module
Adds proper MongoDB indexes for millions of users
"""
from typing import Any
logger = get_logger(__name__)

# Critical indexes for fast operations with millions of users
USER_INDEXES = [
    # Ban indexes - for fast ban checks
    {"key": [("banned", 1)], "name": "idx_banned"},
    {"key": [("silent_ban", 1)], "name": "idx_silent_ban"},
    {"key": [("is_bot", 1)], "name": "idx_is_bot"},
    
    # Premium index - for fast premium queries
    {"key": [("premium_until", 1)], "name": "idx_premium"},
    
    # Leaderboard indexes - for fast sorting
    {"key": [("balance", -1)], "name": "idx_balance_desc"},
    {"key": [("captures", -1)], "name": "idx_captures_desc"},
    {"key": [("daily_income", -1)], "name": "idx_daily_income"},
    {"key": [("weekly_income", -1)], "name": "idx_weekly_income"},
    {"key": [("daily_captures", -1)], "name": "idx_daily_captures"},
    {"key": [("weekly_captures", -1)], "name": "idx_weekly_captures"},
    
    # Compound indexes for common queries
    {"key": [("banned", 1), ("balance", -1)], "name": "idx_banned_balance"},
    {"key": [("is_bot", 1), ("balance", -1)], "name": "idx_bot_balance"},
    {"key": [("premium_until", 1), ("balance", -1)], "name": "idx_premium_balance"},
    
    # User lookup indexes
    {"key": [("username", 1)], "name": "idx_username"},
    {"key": [("updated_at", -1)], "name": "idx_updated"},
]

SETTING_INDEXES = [
    {"key": [("key", 1)], "name": "idx_setting_key"},
]


def _create_indexes_sync() -> dict:
    """Create MongoDB indexes synchronously using pymongo."""
    if not MONGO_ENABLED:
        return {"created": 0, "errors": 0, "details": ["MongoDB disabled (TiDB-only)"]}
    import pymongo

    client = None
    try:
        client = pymongo.MongoClient(
            MONGO_URI,
            serverSelectionTimeoutMS=10000,
            connectTimeoutMS=10000,
            socketTimeoutMS=10000,
        )
        client.server_info()
        db = client[MONGO_DB_NAME]

        results = {"created": 0, "errors": 0, "details": []}

        users_collection = db.users
        existing_indexes = users_collection.index_information()

        for index_spec in USER_INDEXES:
            try:
                key = index_spec["key"]
                name = index_spec.get("name", f"idx_{key[0][0]}")
                if name not in existing_indexes:
                    users_collection.create_index(key, name=name, background=True)
                    results["created"] += 1
                    results["details"].append(f"Created index: {name}")
                    logger.info(f"Created MongoDB index: {name}")
                else:
                    results["details"].append(f"Index exists: {name}")
            except Exception as e:
                results["errors"] += 1
                results["details"].append(f"Failed to create {index_spec.get('name', 'unknown')}: {e}")

        settings_collection = db["bot_settings"]
        existing_settings_indexes = settings_collection.index_information()

        for index_spec in SETTING_INDEXES:
            try:
                key = index_spec["key"]
                name = index_spec.get("name", f"idx_{key[0][0]}")
                if name not in existing_settings_indexes:
                    settings_collection.create_index(key, name=name, background=True)
                    results["created"] += 1
                    results["details"].append(f"Created setting index: {name}")
            except Exception as e:
                results["errors"] += 1
                results["details"].append(f"Failed to create setting index: {e}")

        logger.info(f"Index optimization complete: {results['created']} created, {results['errors']} errors")
        return results

    except Exception as e:
        logger.warning("Index creation failed: %s", e)
        return {"created": 0, "errors": 1, "details": [str(e)]}
    finally:
        if client:
            try:
                client.close()
            except Exception:
                pass


async def create_mongodb_indexes() -> dict:
    """Create all necessary indexes asynchronously without blocking the loop."""
    import asyncio
    return await asyncio.to_thread(_create_indexes_sync)


def get_fast_count_query(field: str, value: Any) -> dict:
    """Generate a fast count query using indexes."""
    return {field: value}


def get_leaderboard_query(sort_field: str, limit: int = 10) -> dict:
    """Generate an optimized leaderboard query using indexes."""
    return {
        "filter": {
            "banned": {"$ne": True},
            "silent_ban": {"$ne": True},
            "is_bot": {"$ne": True},
            sort_field: {"$gt": 0}
        },
        "sort": [(sort_field, -1)],
        "limit": limit,
        "projection": {
            "_id": 1,
            "username": 1,
            "display_name": 1,
            "name": 1,
            sort_field: 1,
            "premium_until": 1
        }
    }


def get_banned_users_query() -> dict:
    """Get only banned users using index."""
    return {
        "filter": {"banned": True},
        "projection": {"_id": 1}
    }


def get_premium_users_query() -> dict:
    """Get only premium users using index."""
    import time
    return {
        "filter": {"premium_until": {"$gt": int(time.time())}},
        "projection": {"_id": 1, "username": 1, "premium_until": 1}
    }

# ═══ MODULE: database.smart_slots ═══

"""
🗄️ Smart MongoDB Slot Manager - database/smart_slots.py

Features:
- Auto-detect next available slot (P1-P7)
- Auto-sync with P1 on add
- Storage full detection & owner notification
- Local SQLite backup while waiting
- One-time redeem per DB URL
- Waiting queue system
"""


import asyncio
import time
import threading
from typing import Optional, Dict, Any
from dataclasses import dataclass, field
from enum import Enum
from collections import deque

logger = get_logger(__name__)



class SlotState(Enum):
    AVAILABLE = "available"
    ACTIVE = "active"
    FULL = "full"
    FAILED = "failed"
    PENDING = "pending"  # Waiting for owner to provide new DB


@dataclass
class SlotInfo:
    slot_id: int  # 1-7
    name: str  # P1-P7
    uri: Optional[str] = None
    state: SlotState = SlotState.AVAILABLE
    usage_percent: float = 0.0
    usage_bytes: int = 0
    limit_mb: int = 512
    is_primary: bool = False
    last_check: float = 0
    last_sync: float = 0
    redeemed_urls: set = field(default_factory=set)  # URLs already used for this slot
    
    def is_available(self) -> bool:
        return self.state == SlotState.AVAILABLE
    
    def is_full(self) -> bool:
        return self.usage_percent >= 94.0 or self.state == SlotState.FULL
    
    def can_redeem(self, uri: str) -> bool:
        return uri not in self.redeemed_urls


class SmartSlotManager:
    """
    Manages MongoDB slots with auto-failover and owner notification.
    
    Flow:
    1. Owner gives /addmongo <url>
    2. Bot auto-assigns to next available slot (P1-P7)
    3. Auto-sync with P1 (primary)
    4. If slot gets full → notify owner for new URL
    5. Local SQLite backup while waiting
    6. One-time use per URL (no reuse)
    """
    
    _instance = None
    _init_lock = threading.Lock()
    
    def __new__(cls):
        if cls._instance is None:
            with cls._init_lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._initialized = False
        return cls._instance
    
    def __init__(self):
        if self._initialized:
            return
        
        self._initialized = True
        self._instance_lock = threading.RLock()
        self._slots: Dict[int, SlotInfo] = {}
        self._waiting_queue: deque = deque()  # Waiting slots that need new URL
        self._last_notification: Dict[int, float] = {}  # slot_id -> last_notify_time
        self._notification_cooldown = 3600  # 1 hour between notifications
        self._local_backup_mode: Dict[int, bool] = {}  # slot_id -> using local backup
        self._sync_in_progress: Dict[int, bool] = {}  # slot_id -> syncing
        
        # Initialize slots from config
        self._init_slots()
    
    def _init_slots(self):
        """Initialize P1-P7 slots from config."""
        for i in range(1, 8):
            slot = SlotInfo(
                slot_id=i,
                name=f"P{i}",
                is_primary=(i == 1),
            )
            
            # Load URI from config if available
            if i <= len(MONGO_URI_SLOTS) and MONGO_URI_SLOTS[i-1]:
                slot.uri = MONGO_URI_SLOTS[i-1]
                slot.state = SlotState.ACTIVE
            
            self._slots[i] = slot
        
        logger.info(f"[SmartSlots] Initialized {len(self._slots)} slots")
    
    def get_next_available_slot(self) -> Optional[SlotInfo]:
        """Get next available slot for new URL."""
        with self._instance_lock:
            for slot in self._slots.values():
                if slot.is_available() and not self.is_waiting(slot.slot_id):
                    return slot
        return None
    
    def get_slot_by_uri(self, uri: str) -> Optional[SlotInfo]:
        """Find slot by URI."""
        with self._instance_lock:
            for slot in self._slots.values():
                if slot.uri == uri:
                    return slot
        return None
    
    def can_redeem_url(self, uri: str) -> bool:
        """Check if URL can be used (one-time only)."""
        with self._instance_lock:
            for slot in self._slots.values():
                if uri in slot.redeemed_urls:
                    return False
        return True
    
    def add_url(self, uri: str) -> Dict[str, Any]:
        """
        Add URL to next available slot.
        Returns result with slot info or error.
        """
        with self._instance_lock:
            # Check one-time use
            if not self.can_redeem_url(uri):
                return {
                    "success": False,
                    "error": "This URL has already been used. Each URL can only be redeemed once.",
                }
            
            # Find available slot
            slot = self.get_next_available_slot()
            
            if not slot:
                # No available slots - add to waiting queue
                return {
                    "success": False,
                    "error": "All slots are full or pending. Please wait for owner notification.",
                    "waiting": True,
                }
            
            # Assign URL to slot
            return self._assign_url_to_slot(slot, uri)
    
    def _assign_url_to_slot(self, slot: SlotInfo, uri: str) -> Dict[str, Any]:
        """Assign URL to a specific slot."""
        try:
            # Mark URL as redeemed
            slot.redeemed_urls.add(uri)
            
            # Remove from waiting if was there
            self._waiting_queue = deque(
                s for s in self._waiting_queue if s != slot.slot_id
            )
            
            # Update slot
            slot.uri = uri
            slot.state = SlotState.ACTIVE
            slot.last_check = time.time()
            
            # Get P1 URL for sync
            p1_uri = self._slots[1].uri if self._slots[1].uri else None
            
            logger.info(f"[SmartSlots] Assigned {uri[:50]}... to {slot.name}")
            
            return {
                "success": True,
                "slot": slot,
                "needs_sync": slot.slot_id > 1 and p1_uri is not None,
                "p1_uri": p1_uri,
            }
            
        except Exception as e:
            logger.warning("Exception: %s", str(e))
            logger.error("[SmartSlots] Failed to assign URL to %s", slot.name, exc_info=True)
            return {"success": False, "error": str(e)}
    
    def mark_slot_full(self, slot_id: int):
        """Mark a slot as full and notify owner."""
        with self._instance_lock:
            if slot_id not in self._slots:
                return
            
            slot = self._slots[slot_id]
            slot.state = SlotState.FULL
            slot.usage_percent = 100.0
            
            # Add to waiting queue
            if slot_id not in self._waiting_queue:
                self._waiting_queue.append(slot_id)
            
            # Notify owner if cooldown passed
            self._notify_owner_pending(slot)
    
    def _notify_owner_pending(self, slot: SlotInfo):
        """Send notification to owner about pending slot."""
        now = time.time()
        last_notify = self._last_notification.get(slot.slot_id, 0)
        
        if now - last_notify < self._notification_cooldown:
            return
        
        self._last_notification[slot.slot_id] = now
        
        logger.warning(f"[SmartSlots] {slot.name} is FULL - notifying owner")
    
    def get_pending_slots(self) -> list:
        """Get list of slots waiting for new URL."""
        with self._instance_lock:
            return list(self._waiting_queue)
    
    def is_waiting(self, slot_id: int) -> bool:
        """Check if slot is waiting for new URL."""
        with self._instance_lock:
            return slot_id in self._waiting_queue
    
    def enable_local_backup(self, slot_id: int):
        """Enable local SQLite backup for a slot."""
        with self._instance_lock:
            self._local_backup_mode[slot_id] = True
        logger.info(f"[SmartSlots] Local backup enabled for P{slot_id}")
    
    def is_local_backup_enabled(self, slot_id: int) -> bool:
        """Check if local backup is enabled for slot."""
        with self._instance_lock:
            return self._local_backup_mode.get(slot_id, False)
    
    def set_sync_progress(self, slot_id: int, in_progress: bool):
        """Mark slot sync status."""
        with self._instance_lock:
            self._sync_in_progress[slot_id] = in_progress
    
    def is_syncing(self, slot_id: int) -> bool:
        """Check if slot is currently syncing."""
        with self._instance_lock:
            return self._sync_in_progress.get(slot_id, False)
    
    def get_slot_status(self) -> Dict[str, Any]:
        """Get status of all slots."""
        with self._instance_lock:
            slots = []
            for slot in sorted(self._slots.values(), key=lambda s: s.slot_id):
                slots.append({
                    "id": slot.slot_id,
                    "name": slot.name,
                    "state": slot.state.value,
                    "uri": slot.uri[:30] + "..." if slot.uri else None,
                    "usage_percent": slot.usage_percent,
                    "is_primary": slot.is_primary,
                    "waiting": self.is_waiting(slot.slot_id),
                    "syncing": self.is_syncing(slot.slot_id),
                    "local_backup": self.is_local_backup_enabled(slot.slot_id),
                })
            
            return {
                "slots": slots,
                "pending_count": len(self._waiting_queue),
                "pending_slots": [f"P{s}" for s in self._waiting_queue],
            }
    
    def update_slot_usage(self, slot_id: int, usage_percent: float, usage_bytes: int):
        """Update slot usage info."""
        with self._instance_lock:
            if slot_id not in self._slots:
                return
            
            slot = self._slots[slot_id]
            slot.usage_percent = usage_percent
            slot.usage_bytes = usage_bytes
            slot.last_check = time.time()
            
            # Check if full
            if usage_percent >= 94.0:
                if slot.state != SlotState.FULL:
                    self.mark_slot_full(slot_id)
    
    def get_all_uris(self) -> Dict[int, str]:
        """Get all slot URIs."""
        with self._instance_lock:
            return {
                slot_id: slot.uri or ""
                for slot_id, slot in self._slots.items()
            }


# Global instance
SLOT_MANAGER = SmartSlotManager()


def get_slot_manager() -> SmartSlotManager:
    """Get the slot manager instance."""
    return SLOT_MANAGER

# ═══ MODULE: fun.xogame ═══

import asyncio
import html
import random
import threading
import time
from typing import Optional

from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update, User
from telegram.ext import ContextTypes


logger = get_logger(__name__)


def _log_task_exception(t: asyncio.Task) -> None:
    if t.cancelled():
        return
    exc = t.exception()
    if exc is not None:
        logger.warning(f"Background task failed: {exc!r}", exc_info=exc)


CELL = {"X": "❌", "O": "⭕", "·": "　", "S": "🌟"}
WIN_LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]
xogame__games: dict[str, "Game"] = {}
_GAME_LOCKS: dict[str, asyncio.Lock] = {}
_global_xo_lock: asyncio.Lock | None = None

async def _get_global_xo_lock() -> asyncio.Lock:
    global _global_xo_lock
    if _global_xo_lock is None:
        _global_xo_lock = asyncio.Lock()
    return _global_xo_lock

_GAME_TIMEOUT = 3600


async def _cleanup_game(gid: str) -> None:
    xogame__games.pop(gid, None)
    _GAME_LOCKS.pop(gid, None)


async def _cleanup_stale_games() -> None:
    now = time.time()
    async with await _get_global_xo_lock():
        stale = [
            gid for gid, game in list(xogame__games.items())
            if now - game.created_at > _GAME_TIMEOUT
        ]
        for gid in stale:
            xogame__games.pop(gid, None)
            _GAME_LOCKS.pop(gid, None)
        orphan = [gid for gid in list(_GAME_LOCKS) if gid not in xogame__games]
        for gid in orphan:
            _GAME_LOCKS.pop(gid, None)


async def xogame__get_game_lock(gid: str) -> asyncio.Lock:
    async with await _get_global_xo_lock():
        if gid not in _GAME_LOCKS:
            _GAME_LOCKS[gid] = asyncio.Lock()
        return _GAME_LOCKS[gid]


async def _create_game(gid: str, game: 'Game') -> None:
    async with await _get_global_xo_lock():
        xogame__games[gid] = game


class Game:
    def __init__(self, mode: str, creator: User, difficulty: str = "medium"):
        self.mode = mode
        self.creator_id = creator.id
        self.creator_name = creator.first_name
        self.board = ["·"] * 9
        self.turn = "X"
        self.difficulty = difficulty
        self.winner: Optional[str] = None
        self.draw = False
        self.created_at = time.time()
        if mode == "single":
            self.p1_id = creator.id
            self.p1_name = creator.first_name
            self.p2_id = 0
            self.p2_name = "𝐀ɴʏʏ"
        else:
            self.p1_id = creator.id
            self.p1_name = creator.first_name
            self.p2_id = 0
            self.p2_name = "Waiting..."


def _winner(board: list[str]) -> Optional[str]:
    for a, b, c in WIN_LINES:
        if board[a] == board[b] == board[c] and board[a] != "·":
            return board[a]
    return None


def _winning_line(board: list[str]) -> tuple[int, int, int] | None:
    for line in WIN_LINES:
        a, b, c = line
        if board[a] == board[b] == board[c] and board[a] != "·":
            return line
    return None


def _draw(board: list[str]) -> bool:
    return "·" not in board


def _smart_move(board: list[str]) -> int:
    free = [idx for idx, value in enumerate(board) if value == "·"]
    if not free:
        return -1
    for idx in free:
        board[idx] = "O"
        if _winner(board):
            board[idx] = "·"
            return idx
        board[idx] = "·"
    for idx in free:
        board[idx] = "X"
        if _winner(board):
            board[idx] = "·"
            return idx
        board[idx] = "·"
    if board[4] == "·":
        return 4
    corners = [idx for idx in (0, 2, 6, 8) if board[idx] == "·"]
    if corners:
        return random.choice(corners)
    if free:
        return random.choice(free)
    return -1


def _bot_move(board: list[str], difficulty: str) -> int:
    free = [idx for idx, value in enumerate(board) if value == "·"]
    if not free:
        return -1
    chance = {"easy": 0.30, "medium": 0.50, "hard": 0.70}.get(difficulty, 0.50)
    smart = _smart_move(board)
    if smart == -1:
        return -1
    if random.random() < chance:
        return smart
    if free:
        return random.choice(free)
    return -1


def xogame__mention(name: str, uid: int) -> str:
    return f'<a href="tg://user?id={uid}">{html.escape(name)}</a>' if uid else f"<b>{html.escape(name)}</b>"


def _board_text(board: list[str]) -> str:
    rows = []
    for row in range(3):
        rows.append(" ".join(CELL[board[row * 3 + col]] for col in range(3)))
    return "\n".join(rows)


def _status(game: Game) -> str:
    p1 = xogame__mention(game.p1_name, game.p1_id) if game.p1_id else "<b>Waiting...</b>"
    if game.mode == "single":
        p2 = f"<b>{html.escape(game.p2_name)}</b>"
    else:
        p2 = xogame__mention(game.p2_name, game.p2_id) if game.p2_id else "<b>Waiting...</b>"
    diff_tag = f" [{game.difficulty.upper()}]" if game.mode == "single" else ""
    vs = f"❌ {p1} Vs {p2} ⭕{diff_tag}"

    if game.winner:
        winner_id = game.p1_id if game.winner == "X" else game.p2_id
        winner_name = game.p1_name if game.winner == "X" else game.p2_name
        return f"{vs}\n\n🏆 {xogame__mention(winner_name, winner_id)} Wɪɴs!"
    if game.draw:
        return f"{vs}\n\n🤝 <b>Dʀᴀᴡ!</b>"

    turn_name = game.p1_name if game.turn == "X" else game.p2_name
    symbol = "❌" if game.turn == "X" else "⭕"
    return f"{vs}\n\n{symbol} {html.escape(turn_name)}'s Tᴜʀɴ"


def _board_kb(gid: str, game: Game) -> InlineKeyboardMarkup:
    board = game.board[:]
    if game.winner:
        line = _winning_line(game.board)
        if line:
            for idx in line:
                board[idx] = "S"
    rows = []
    for row in range(3):
        buttons = []
        for col in range(3):
            idx = row * 3 + col
            buttons.append(
                InlineKeyboardButton(
                    CELL[board[idx]],
                    callback_data="xo_noop" if (game.winner or game.draw) else f"xo_{gid}_{idx}",
                )
            )
        rows.append(buttons)
    rows.append([InlineKeyboardButton("❌ Cʟᴏsᴇ", callback_data=f"xo_close|{gid}")])
    return InlineKeyboardMarkup(rows)


async def xogame(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not msg or not user or not chat:
        return

    gid = f"{chat.id}_{msg.message_id}"
    mode = "single" if chat.type == "private" else "multi"
    difficulty = "medium"
    if mode == "single" and ctx.args:
        arg = ctx.args[0].lower()
        if arg in ("easy", "medium", "hard"):
            difficulty = arg
    game = Game(mode, user, difficulty)
    await _create_game(gid, game)

    if mode == "multi":
        txt = (
            f"🎮 <b>Xᴏ Gᴀᴍᴇ</b>\n\n"
            f"❌ {html.escape(user.first_name)} ɪs ᴡᴀɪᴛɪɴɢ ғᴏʀ ᴏᴘᴘᴏɴᴇɴᴛ...\n\n"
            f"⭕ Tᴀᴘ ᴀɴʏ ʙᴏx ᴛᴏ ᴊᴏɪɴ"
        )
    else:
        txt = f"🎮 <b>Xᴏ Gᴀᴍᴇ</b>\n\n{_status(game)}"

    await msg.reply_html(txt, reply_markup=_board_kb(gid, game))


async def _ai_move_task(game: Game, gid: str, chat_id: int, message_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    async with await xogame__get_game_lock(gid):
        await asyncio.sleep(0.5)
        g = xogame__games.get(gid)
        if not g or g is not game:
            return
        if g.winner or g.draw or g.turn != "O":
            return
        idx = _bot_move(g.board, g.difficulty)
        if idx < 0:
            return
        g.board[idx] = "O"
        win = _winner(g.board)
        if win:
            g.winner = win
        elif _draw(g.board):
            g.draw = True
        else:
            g.turn = "X"
    try:
        await ctx.bot.edit_message_text(
            _status(game), chat_id=chat_id, message_id=message_id,
            parse_mode="HTML", reply_markup=_board_kb(gid, game),
        )
    except Exception:
        pass


async def xo_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    user = q.from_user
    data = q.data or ""
    if not q.message:
        await q.answer("Inline mode not supported", show_alert=True)
        return

    # Close
    if data.startswith("xo_close|"):
        gid = data[len("xo_close|"):]
        async with await _get_global_xo_lock():
            xogame__games.pop(gid, None)
            _GAME_LOCKS.pop(gid, None)
        await q.answer()
        try:
            await q.edit_message_text("❌ Xᴏ Gᴀᴍᴇ Cʟᴏsᴇᴅ.")
        except Exception:
            pass
        return

    # No-op
    if data == "xo_noop":
        await q.answer()
        return

    # Move
    if not data.startswith("xo_"):
        return

    rest = data[len("xo_"):]
    last_sep = rest.rfind("_")
    if last_sep < 0:
        await q.answer()
        return
    gid = rest[:last_sep]
    try:
        idx = int(rest[last_sep + 1:])
        if not (0 <= idx <= 8):
            raise ValueError
    except (ValueError, IndexError):
        await q.answer("Invalid move", show_alert=True)
        return

    async with await xogame__get_game_lock(gid):
        game = xogame__games.get(gid)
        if not game:
            await q.answer("Gᴀᴍᴇ ᴇxᴘɪʀᴇᴅ.")
            return
        if game.winner or game.draw:
            await q.answer("Gᴀᴍᴇ ᴏᴠᴇʀ.")
            return
        if game.board[idx] != "·":
            await q.answer("Cᴇʟʟ ᴀʟʀᴇᴀᴅʏ ᴛᴀᴋᴇɴ!")
            return

        if game.mode == "single":
            if user.id != game.p1_id:
                await q.answer("Nᴏᴛ ʏᴏᴜʀ ɢᴀᴍᴇ.")
                return
            if game.turn == "O":
                await q.answer("Wᴀɪᴛ ꜰᴏʀ 𝐀ɴʏʏ.")
                return
            game.board[idx] = "X"
            win = _winner(game.board)
            if win:
                game.winner = win
            elif _draw(game.board):
                game.draw = True
            else:
                game.turn = "O"
        else:
            if not game.p2_id:
                if user.id == game.p1_id:
                    await q.answer("Wᴀɪᴛɪɴɢ ғᴏʀ ᴏᴘᴘᴏɴᴇɴᴛ.")
                    return
                game.p2_id = user.id
                game.p2_name = user.first_name
                await q.answer("⭕ Jᴏɪɴᴇᴅ!")
            elif game.turn == "X" and user.id != game.p1_id:
                await q.answer(f"❌ {game.p1_name}'s ᴛᴜʀɴ")
                return
            elif game.turn == "O" and user.id != game.p2_id:
                await q.answer(f"⭕ {game.p2_name}'s ᴛᴜʀɴ")
                return
            if user.id not in (game.p1_id, game.p2_id):
                await q.answer("Gᴀᴍᴇ ɪs ғᴜʟʟ.")
                return
            game.board[idx] = game.turn
            win = _winner(game.board)
            if win:
                game.winner = win
            elif _draw(game.board):
                game.draw = True
            else:
                game.turn = "O" if game.turn == "X" else "X"

        if game.winner or game.draw:
            await _cleanup_game(gid)

    await q.answer("Move placed")
    try:
        await q.edit_message_text(
            _status(game), parse_mode="HTML", reply_markup=_board_kb(gid, game),
        )
    except Exception:
        pass

    if game.mode == "single" and game.turn == "O" and not game.winner and not game.draw:
        t = asyncio.create_task(
            _ai_move_task(game, gid, q.message.chat_id, q.message.message_id, ctx)
        )
        t.add_done_callback(_log_task_exception)


async def xogame_cleanup_loop(context) -> None:
    try:
        await _cleanup_stale_games()
    except Exception as e:
        logger.error("Error in xogame cleanup: %s", e, exc_info=True)

