# =========================================
# ⛓ CAPTURE — game/capture.py  v3.2 (WEB VERIFY)
# Premium: $200-$400 | Normal: $100-$200
# =========================================
import asyncio, html, random, time
from telegram import Update
from telegram.ext import ContextTypes

_capture_locks = BoundedLockDict(maxsize=50000)


def _victim_lock(vid: int) -> asyncio.Lock:
    """Sync — BoundedLockDict is thread-safe, no need for async lock wrapper."""
    return _capture_locks.get(vid)

CAPTURE_REWARD_MIN = 97
CAPTURE_REWARD_MAX = 200
PREMIUM_REWARD_MIN = 200
PREMIUM_REWARD_MAX = 400
AUTO_RELEASE_TIME = 7 * 3600
START_BALANCE = 200

DM_ERROR = "⚠️ Rᴇᴘʟʏ Tᴏ Sᴏᴍᴇᴏɴᴇ's Msɢ Iɴ Gʀᴏᴜᴘ."
REPLY_REQUIRED = "🕸 Rᴇᴘʟʏ Tᴏ A Uꜱᴇʀ Tᴏ Cᴀᴘᴛᴜʀᴇ."
SELF_CAPTURE = "🥲 Yᴏᴜ Cᴀɴɴᴏᴛ Cᴀᴘᴛᴜʀᴇ Yᴏᴜʀꜱᴇʟꜰ."
BOT_CAPTURE = "⚠️ Bᴏᴛꜱ Cᴀɴɴᴏᴛ Bᴇ Cᴀᴘᴛᴜʀᴇᴅ."
ALREADY_CAPTURED = "🕸️ Tᴀʀɢᴇᴛ Iꜱ Aʟʀᴇᴀᴅʏ Cᴀᴘᴛᴜʀᴇᴅ."
SHIELD_ACTIVE = "🛡 Tᴀʀɢᴇᴛ Iꜱ Cᴜʀʀᴇɴᴛʟʏ Sᴀᴠᴇᴅ."
GAME_OFF = "🎮 Gᴀᴍᴇ ɪs Oꜰꜰ ɪɴ Tʜɪs Gʀᴏᴜᴘ."
IN_PRISON = "🥀 Yᴏᴜ Aʀᴇ Iɴ Pʀɪꜱᴏɴ\nPʀɪꜱᴏɴᴇʀꜱ Cᴀɴɴᴏᴛ Cᴀᴘᴛᴜʀᴇ\nUꜱᴇ /paybounty Tᴏ Rᴇʟᴇᴀꜱᴇ."
GROUP_CAPTURE = (
    "👤 <b>{attacker}</b> Cᴀᴘᴛᴜʀᴇᴅ <b>{victim}</b>\n"
    "💰 Bᴏᴜɴᴛʏ: <b>${bounty_dollar}</b>, +<b>{bounty_rp} XP</b>\n"
)
DM_CAPTURE = (
    "⛓ <b>Yᴏᴜ Hᴀᴠᴇ Bᴇᴇɴ Cᴀᴘᴛᴜʀᴇᴅ</b>\n\n"
    "👤 Bʏ : <b>{attacker}</b>\n"
    "📍 Gʀᴏᴜᴘ : {group}\n\n"
    "💰 Bᴏᴜɴᴛʏ: <b>${bounty_dollar}</b> + <b>{bounty_rp} XP</b>\n"
    "⏳ Aᴜᴛᴏ Rᴇʟᴇᴀꜱᴇ : 7ʜ\n"
    "Uꜱᴇ /paybounty ᴛᴏ Rᴇʟᴇᴀꜱᴇ Fᴀsᴛ"
)


async def capt(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not msg or not user or not chat:
        return
    if chat.type == "private":
        return await msg.reply_text(DM_ERROR)
    # Cached gameoff check (30s TTL) — saves a DB hit per command
    if await is_game_off_cached_async(chat.id):
        return await msg.reply_text(GAME_OFF)
    if await verify_guard(update, ctx):
        return

    if msg.reply_to_message and msg.reply_to_message.sender_chat:
        return await msg.reply_text("⚠️ Tʜɪs ᴜsᴇʀ ɪs ᴀɴ ᴀɴᴏɴʏᴍᴏᴜs ᴀᴅᴍɪɴ ᴏʀ ᴀ ᴄʜᴀɴɴᴇʟ. Tʜᴇʏ ᴄᴀɴ'ᴛ ʙᴇ ᴄᴀᴘᴛᴜʀᴇᴅ.")
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        return await msg.reply_text(REPLY_REQUIRED)
    victim_tg = msg.reply_to_message.from_user
    if user.id == victim_tg.id:
        return await msg.reply_text(SELF_CAPTURE)
    if victim_tg.is_bot:
        return await msg.reply_text(BOT_CAPTURE)

    loop = asyncio.get_running_loop()
    # Parallel fetch of attacker + victim data — both are independent
    attacker_future = loop.run_in_executor(None, ensure, user.id, user)
    victim_future = loop.run_in_executor(None, ensure, victim_tg.id, victim_tg)
    # Also fetch premium status in parallel (doesn't depend on ensure)
    premium_future = loop.create_task(is_premium_cached_async(user.id))
    uid, a_data = await attacker_future
    vid, v_data = await victim_future

    # Auto-release expired captures — only re-read if DB was actually modified
    try:
        if await asyncio.to_thread(auto_release, uid, a_data):
            _, a_data = await loop.run_in_executor(None, ensure, user.id, user)
    except Exception as e:
        logger.warning(f"Error during auto_release for attacker {uid}: {e}")

    try:
        if await asyncio.to_thread(auto_release, vid, v_data):
            _, v_data = await loop.run_in_executor(None, ensure, victim_tg.id, victim_tg)
    except Exception as e:
        logger.warning(f"Error during auto_release for victim {vid}: {e}")

    # Prison check — use already-fresh a_data (auto_release re-fetched if needed)
    if a_data.get("captured"):
        return await msg.reply_text(IN_PRISON)

    vlock = _victim_lock(vid)
    async with vlock:
        # Re-read victim inside lock for freshness (shield/captured can change)
        _, v_data = await asyncio.to_thread(ensure, victim_tg.id, victim_tg)
        if v_data.get("saved_until", 0) > now():
            return await msg.reply_text(SHIELD_ACTIVE)
        if v_data.get("captured"):
            return await msg.reply_text(ALREADY_CAPTURED)

        # Re-check attacker prison status with fresh data
        _, a_data = await asyncio.to_thread(ensure, user.id, user)
        if a_data.get("captured"):
            return await msg.reply_text(IN_PRISON)

        # Re-check premium inside lock to prevent race on expiry
        is_prem = await asyncio.to_thread(is_premium, user.id)
        if is_prem:
            reward = int(random.randint(PREMIUM_REWARD_MIN, PREMIUM_REWARD_MAX))
        else:
            reward = int(random.randint(CAPTURE_REWARD_MIN, CAPTURE_REWARD_MAX))

        rp_gain = random.randint(12, 28)  # Reduced XP — ~5-7 years to reach level 100

        try:
            await asyncio.to_thread(
                update_user_atomic,
                uid,
                inc_fields={
                    "balance": reward,
                    "rp": rp_gain,
                    "captures": 1,
                    "daily_captures": 1,
                    "weekly_captures": 1,
                    "daily_income": reward,
                    "weekly_income": reward,
                    "lifetime_income": reward,
                },
            )
        except Exception:
            logger.warning(f"Failed to reward attacker {uid} for capture")
            return await msg.reply_text("⚠️ Capture failed. Please try again.")

        try:
            await asyncio.to_thread(
                update_user_atomic,
                vid,
                set_fields={
                    "captured": True,
                    "captured_by": uid,
                    "capture_time": now(),
                    "bounty_dollar": reward,
                    "bounty_rp": rp_gain,
                },
            )
        except Exception:
            logger.warning(f"Failed to mark victim {vid} as captured, rolling back")
            inc = {
                "balance": -reward,
                "rp": -rp_gain,
                "daily_income": -reward,
                "weekly_income": -reward,
                "lifetime_income": -reward,
            }
            if a_data.get("captures", 0) > 0:
                inc["captures"] = -1
                inc["daily_captures"] = -1
                inc["weekly_captures"] = -1
            try:
                await asyncio.to_thread(update_user_atomic, uid, inc_fields=inc)
            except Exception as rb_exc:
                logger.error(f"Rollback failed for attacker {uid}: {rb_exc}")
            return
    await record_capture_action(user.id, chat.id, "capt")

    await msg.reply_html(
        GROUP_CAPTURE.format(
            attacker=html.escape(user.first_name),
            victim=html.escape(victim_tg.first_name),
            bounty_dollar=reward,
            bounty_rp=rp_gain,
        )
    )
    try:
        await ctx.bot.send_message(
            victim_tg.id,
            DM_CAPTURE.format(
                attacker=html.escape(user.full_name),
                group=html.escape(chat.title or "Group"),
                bounty_dollar=reward,
                bounty_rp=rp_gain
            ),
            parse_mode="HTML",
        )
    except Exception:
        pass  # Victim hasn't started bot or blocked it — normal

