# ━━━ Pre-styled message templates ━━━
def box(content: str, title: str | None = None, icon: str = "📦") -> str:
    """Wrap content in a styled box."""
    if title:
        return f"<b>{icon} {bold(title)}</b>\n{divider()}\n{content}\n{divider()}"
    return f"{divider()}\n{content}\n{divider()}"


def success(text: str) -> str:
    return f"{ICONS['success']} <b>S{small('uccess')}</b> : {text}"


def error(text: str) -> str:
    return f"{ICONS['error']} <b>E{small('rror')}</b> : {text}"


def warning(text: str) -> str:
    return f"{ICONS['warning']} <b>W{small('arning')}</b> : {text}"


def stat_row(icon: str, label: str, value) -> str:
    """Format a stat line: 📊 Uꜱᴇʀꜱ : 𝟏,𝟐𝟑𝟒"""
    return f"{icon}  {small(label)} : <b>{value}</b>"


# Short alias for common usage
f = small  # Short for small caps
B = bold   # Short for bold

# ═══ MODULE: groupadminchats.admin.helper_funcs.chat_status ═══

"""
helper_funcs/chat_status.py — PTB v20+ async decorators + permission checks.

All decorator replies use the Cᴏᴘʏ Tʜɪs Fᴏɴᴛ (small caps) style and polite
wording. All permission checks accept an optional `member` arg matching
Miss-Rose's signature so we don't have to re-fetch the same member twice.
"""

from functools import wraps
from typing import Callable, Awaitable, Any, Optional

from telegram import Update, ChatMember
from telegram.constants import ChatMemberStatus
from telegram.ext import ContextTypes



def _sc(text: str) -> str:
    """Sʜᴏʀᴛcut for sᴍᴀʟʟ caps."""
    return small(text)


# ━━━ Permission checks (async, PTB v20+) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

async def is_user_admin(chat, user_id: int, member: Optional[ChatMember] = None) -> bool:
    """True if user_id is admin/creator in chat (or always in private)."""
    if chat.type == "private":
        return True
    try:
        m = member if member is not None else await chat.get_member(user_id)
    except Exception:
        return False
    return m.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER)


async def is_bot_admin(chat, bot_id: int) -> bool:
    """True if the bot itself is admin/creator in chat (or in private)."""
    if chat.type == "private":
        return True
    try:
        m = await chat.get_member(bot_id)
    except Exception:
        return False
    return m.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER)


async def is_user_ban_protected(chat, user_id: int, member: Optional[ChatMember] = None) -> bool:
    """Admins/owners are protected from ban/kick. Bot itself is also protected."""
    if chat.type == "private":
        return True
    return await is_user_admin(chat, user_id, member=member)


async def can_bot_restrict(chat, bot_id: int) -> bool:
    """True if bot has restrict_members permission."""
    if chat.type == "private":
        return True
    try:
        m = await chat.get_member(bot_id)
    except Exception:
        return False
    return bool(getattr(m, "can_restrict_members", False))


async def can_bot_promote(chat, bot_id: int) -> bool:
    """True if bot has promote_members permission."""
    if chat.type == "private":
        return True
    try:
        m = await chat.get_member(bot_id)
    except Exception:
        return False
    return bool(getattr(m, "can_promote_members", False))


async def can_bot_pin(chat, bot_id: int) -> bool:
    """True if bot has pin_messages permission."""
    if chat.type == "private":
        return True
    try:
        m = await chat.get_member(bot_id)
    except Exception:
        return False
    return bool(getattr(m, "can_pin_messages", False))


async def can_bot_delete(chat, bot_id: int) -> bool:
    """True if bot has delete_messages permission."""
    if chat.type == "private":
        return True
    try:
        m = await chat.get_member(bot_id)
    except Exception:
        return False
    return bool(getattr(m, "can_delete_messages", False))


# ━━━ Decorator reply text (Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite) ━━━━━━━━━━━━━━━━━━━━━━━

# We use small caps + a leading emoji so it matches the rest of the bot's
# aesthetic (same style as /buy). Text stays polite and never uses CAPS LOCK
# or aggressive language.

_NOT_ADMIN = (
    f"⚠️ {ssc('sorry')} — {ssc('this command is only for group administrators')}."
)
_BOT_NOT_ADMIN = (
    f"⚠️ {ssc('i need to be an admin here to do that')}."
)
_BOT_NO_PERM = (
    f"⚠️ {ssc('i don')}’{ssc('t have the')} <code>{'{perm}'}</code> "
    f"{ssc('permission in this group')}."
)


# ━━━ Decorators ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

def bot_admin(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    """Block the command if the bot isn't admin in this chat (silent in private)."""

    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        if not chat or chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await is_bot_admin(chat, context.bot.id):
            if update.effective_message:
                await update.effective_message.reply_text(_BOT_NOT_ADMIN)
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper


def user_admin(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    """Block the command if the user isn't an admin of this chat."""

    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        user = update.effective_user
        if not chat or not user:
            return None
        if chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await is_user_admin(chat, user.id):
            if update.effective_message:
                await update.effective_message.reply_text(_NOT_ADMIN)
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper


def bot_can_restrict(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        if not chat or chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await can_bot_restrict(chat, context.bot.id):
            if update.effective_message:
                await update.effective_message.reply_text(
                    _BOT_NO_PERM.format(perm="can_restrict_members"),
                    parse_mode="HTML",
                )
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper


def bot_can_promote(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        if not chat or chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await can_bot_promote(chat, context.bot.id):
            if update.effective_message:
                await update.effective_message.reply_text(
                    _BOT_NO_PERM.format(perm="can_promote_members"),
                    parse_mode="HTML",
                )
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper


def bot_can_pin(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        if not chat or chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await can_bot_pin(chat, context.bot.id):
            if update.effective_message:
                await update.effective_message.reply_text(
                    _BOT_NO_PERM.format(perm="can_pin_messages"),
                    parse_mode="HTML",
                )
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper


def bot_can_delete(func: Callable[..., Awaitable[Any]]) -> Callable[..., Awaitable[Any]]:
    @wraps(func)
    async def wrapper(update: Update, context: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        chat = update.effective_chat
        if not chat or chat.type == "private":
            return await func(update, context, *args, **kwargs)
        if not await can_bot_delete(chat, context.bot.id):
            if update.effective_message:
                await update.effective_message.reply_text(
                    _BOT_NO_PERM.format(perm="can_delete_messages"),
                    parse_mode="HTML",
                )
            return None
        return await func(update, context, *args, **kwargs)

    return wrapper

# ═══ MODULE: groupadminchats.admin.helper_funcs.extraction ═══

"""
helper_funcs/extraction.py — PTB v20+ port of Miss-Rose's user extractor.

extract_user_and_text(update, args) -> (user_id | None, reason | None)
  - if message is a reply: target is the replied user
  - if args[0] starts with '@': look up username in local cache (fallback to None)
  - if args[0] is a digit: use it as user id
  - reason is the rest of args joined
"""

from typing import Optional, List, Tuple

from telegram import Update
from telegram.ext import ContextTypes


def _from_reply(update: Update) -> Tuple[Optional[int], str]:
    """Pull user_id from the replied message; remaining text is the reason."""
    msg = update.effective_message
    if not msg or not msg.reply_to_message:
        return None, ""
    user_id = msg.reply_to_message.from_user.id if msg.reply_to_message.from_user else None
    text = msg.text or msg.caption or ""
    parts = text.split(None, 1)
    reason = parts[1] if len(parts) > 1 else ""
    return user_id, reason


# username (lowercase) -> user_id, populated at boot from the users DB and
# kept fresh whenever a user's username changes. Used by extract_user_and_text
# to resolve @username without an API call.
_USERNAME_CACHE: dict[str, int] = {}


# chat_ids the bot has seen this boot — used by _register_seen_chat to grow
# the registered-chats DB passively (broadcast targeting) without per-message
# DB writes.
_KNOWN_CHATS: set[int] = set()


async def _register_seen_chat(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Passively register every chat the bot sees (runs first, group=-1).

    One TiDB upsert per NEW chat id, then no-op. Keeps the broadcast target
    registry in sync with the bot's real traffic without touching getUpdates.
    """
    chat = update.effective_chat
    if not chat or chat.id in _KNOWN_CHATS:
        return
    _KNOWN_CHATS.add(chat.id)
    try:
        await asyncio.to_thread(
            register_chat,
            chat.id,
            {
                "_id": chat.id,
                "chat_id": chat.id,
                "type": chat.type,
                "title": chat.title or "",
                "username": chat.username or "",
                "last_seen": int(time.time()),
            },
        )
    except Exception:
        logger.debug("_register_seen_chat failed", exc_info=True)


def _cmd_args(update: Update, context: ContextTypes.DEFAULT_TYPE) -> List[str]:
    """Extract command args for handlers registered via MessageHandler.

    MessageHandler does not populate ``context.args`` (only CommandHandler
    does), so commands must parse args from the raw message text themselves.
    Mirrors PTB's whitespace-split behaviour: ``/ban 123 reason here`` →
    ``["123", "reason", "here"]``.
    """
    args = context.args
    if args is not None:
        return list(args)
    msg = update.effective_message
    if not msg or not msg.text:
        return []
    parts = msg.text.split(maxsplit=1)
    if len(parts) < 2:
        return []
    return parts[1].split() or []


async def extract_user_and_text(
    update: Update, context: ContextTypes.DEFAULT_TYPE, args: List[str]
) -> Tuple[Optional[int], Optional[str]]:
    """
    Returns (user_id, reason) — either may be None.
    Used by ban/unban/mute/kick/promote/demote/warn commands.
    """
    msg = update.effective_message
    if not msg:
        return None, None

    # Case 1: no args — must be a reply
    if not args:
        uid, reason = _from_reply(update)
        if uid is None:
            await msg.reply_text(
                "I need a user — reply to their message, or pass @username / user_id."
            )
            return None, None
        # Validate the user exists in our chat (Telegram requires this for ban/mute)
        try:
            await update.effective_chat.get_member(uid)
        except Exception:
            await msg.reply_text(
                "I can't find that user. They need to be in this chat (or have been)."
            )
            return None, None
        return uid, reason or None

    # Case 2: @username — try to resolve via local cache (best effort),
    # then fall back to a direct bot.get_chat() resolve (works for public
    # usernames, e.g. bots, even if never seen before).
    if args[0].startswith("@"):
        username = args[0].lstrip("@")
        # Look in the module-level username cache (built from the users DB at
        # boot), then the legacy global users cache, then fall back to a direct
        # bot.get_chat() resolve (works for public bots/channels, but not for
        # regular user accounts — hence the DB caches above).
        user_id = _USERNAME_CACHE.get(username.lower())
        reason = " ".join(args[1:]) if len(args) > 1 else None
        if not user_id:
            cache = context.application.bot_data.get("_user_id_cache", {})
            user_id = cache.get(username.lower())
        if not user_id:
            try:
                resolved = await context.bot.get_chat(args[0])
                user_id = resolved.id
            except Exception:
                await msg.reply_text(
                    "I don't have that user in my cache. Reply to one of their messages instead."
                )
                return None, None
        return user_id, reason

    # Case 3: numeric user id
    if args[0].isdigit():
        uid = int(args[0])
        reason = " ".join(args[1:]) if len(args) > 1 else None
        try:
            await update.effective_chat.get_member(uid)
        except Exception:
            await msg.reply_text(
                "I can't find that user. They need to be in this chat (or have been)."
            )
            return None, None
        return uid, reason

    # Fallback: try reply
    uid, reason = _from_reply(update)
    if uid is None:
        await msg.reply_text(
            "I need a user — reply to their message, or pass @username / user_id."
        )
        return None, None
    return uid, reason or None


async def extract_user(
    update: Update, context: ContextTypes.DEFAULT_TYPE, args: List[str]
) -> Optional[int]:
    """Just the user_id, no reason."""
    uid, _reason = await extract_user_and_text(update, context, args)
    return uid


def extract_text(update: Update) -> str:
    """Return the text/caption/sticker-emoji of a message, whichever exists."""
    msg = update.effective_message
    if not msg:
        return ""
    if msg.text:
        return msg.text
    if msg.caption:
        return msg.caption
    if msg.sticker and msg.sticker.emoji:
        return msg.sticker.emoji
    return ""

# ═══ MODULE: groupadminchats.admin.ban ═══

"""
ban.py — Ban a user from the group.

PTB v20+ port of Miss-Rose's `ban` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ (small caps)
+ polite wording. Auth-admin + OWNER bypass preserved.
"""

from telegram import Update, ChatMember
from telegram.constants import ChatMemberStatus, ParseMode
from telegram.error import BadRequest
from telegram.ext import ContextTypes
from telegram.helpers import mention_html


logger = get_logger(__name__)


# Exact set from Miss-Rose bans.py
RBAN_ERRORS = {
    "User is an administrator of the chat",
    "Chat not found",
    "Not enough rights to restrict/unrestrict chat member",
    "User_not_participant",
    "Peer_id_invalid",
    "Group chat was deactivated",
    "Need to be inviter of a user to kick it from a basic group",
    "Chat_admin_required",
    "Only the creator of a basic group can kick group administrators",
    "Channel_private",
    "Not in the chat",
}


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_restrict
async def ban_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/ban <user/id/reply> [reason]` — bans the user."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return  # silent: only admins should see admin commands

    user_id, reason = await extract_user_and_text(update, context, _cmd_args(update, context))

    if not user_id:
        await msg.reply_text(f"🤔 {ssc('please reply to a user, or pass')} "
                             f"<code>@username</code> {ssc('or')} "
                             f"<code>user_id</code>.")
        return

    try:
        member: ChatMember = await chat.get_member(user_id)
    except BadRequest as exc:
        if "User not found" in str(exc):
            await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
            return
        logger.exception("ban: get_member failed")
        raise

    if await is_user_ban_protected(chat, user_id, member):
        await msg.reply_text(
            f"🙏 {ssc('i really wish i could ban admins — but i can')}’{ssc('t')}."
        )
        return

    if user_id == context.bot.id:
        await msg.reply_text(
            f"😄 {ssc('i am not gonna ban myself, are you crazy')}?"
        )
        return

    if user_id == user.id:
        await msg.reply_text(f"🙃 {ssc('you can')}’{ssc('t ban yourself, friend')}.")
        return

    if member.status in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED):
        await msg.reply_text(
            f"ℹ️ {ssc('this user is no longer in the chat — nothing to do')}."
        )
        return

    try:
        await context.bot.ban_chat_member(chat.id, user_id)
    except BadRequest as exc:
        err = str(exc)
        if err == "Reply message not found":
            await msg.reply_text(f"🚫 {ssc('banned')}.", quote=False)
            return
        if err in RBAN_ERRORS:
            await msg.reply_text(f"⚠️ {ssc(err.lower())}")
        else:
            logger.exception("ERROR banning user %s in chat %s (%s) due to %s",
                             user_id, chat.title, chat.id, err)
            await msg.reply_text(
                f"❌ {ssc('sorry, i couldn')}’{ssc('t ban that user')}."
            )
        return

    target_name = member.user.first_name if member.user else "user"
    mention = mention_html(user_id, target_name)
    # Wrap the user-typed reason in the Cᴏᴘʏ Tʜɪs Fᴏɴᴛ too
    reason_text = small((reason or "no reason given")[:60])
    # Invalidate admin cache — banned user is no longer an admin
    try:
        admin_cache.invalidate(chat.id, int(user_id))
    except Exception:
        pass
    await msg.reply_text(
        f"🚫 {ssc('banned')}: {mention}\n"
        f"📝 {ssc('reason')}: <i>{reason_text}</i>",
        parse_mode=ParseMode.HTML,
    )

# ═══ MODULE: groupadminchats.admin.cleanlink ═══

"""Cleanlink command - enables auto-deletion of links."""

from telegram import Update
from telegram.ext import ContextTypes
import html
from telegram.error import BadRequest


async def cleanlink_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Enable link cleaning and delete existing links."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if not chat or chat.type not in ["group", "supergroup"]:
        return

    admin_perms = await check_admin_permissions(update, user.id)
    if not admin_perms.get("is_admin") and user.id != OWNER_ID:
        auth_admins = await get_auth_admins(chat.id)
        if not any(a["user_id"] == user.id for a in auth_admins):
            return

    if not admin_perms.get("can_delete") and user.id != OWNER_ID and not await is_auth_admin(chat.id, user.id):
        await msg.reply_text("⚠️ You need 'Delete Messages' permission to use this command.")
        return

    await enable_cleanlink(chat.id)

    admin_mention = f"<a href='tg://user?id={user.id}'>{html.escape(user.first_name)}</a>"

    await msg.reply_text(
        f"🔗 Cleanlink enabled\n"
        f"👮 By: {admin_mention}",
        parse_mode="HTML"
    )

# ═══ MODULE: groupadminchats.admin.deauthadmin ═══

"""Deauthadmin command - removes hidden authorized admin.

Group owner or admin with promote rights can remove auth-admins.
"""

from telegram import Update
from telegram.ext import ContextTypes
import html
logger = get_logger(__name__)


async def deauthadmin(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Remove a hidden authorized admin."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    args = context.args
    if args is None:
        text = msg.text or ""
        args = text.split()[1:] if len(text.split()) > 1 else []

    if not chat or chat.type not in ["group", "supergroup"] or not user or not msg:
        return

    # Allow: bot owner OR group owner OR admins with promote permission
    is_bot_owner = user.id == OWNER_ID
    is_owner = is_bot_owner or await is_group_owner(chat, user.id)

    if not is_owner:
        perms = await check_admin_permissions(update, user.id)
        if not perms.get("can_promote"):
            await msg.reply_text("⚠️ Only the group owner can remove hidden admins.")
            return

    if not args:
        await msg.reply_html(
            "⚠️ Use: <code>/deauthadmin @user</code> or <code>/deauthadmin [user_id]</code>"
        )
        return

    arg = args[0]
    target_user_id = None

    if arg.startswith("@"):
        try:
            found_chat = await context.bot.get_chat(arg)
            target_user_id = found_chat.id
        except Exception:
            logger.error("Unexpected error", exc_info=True)
            await msg.reply_text("⚠️ User not found.")
            return
    elif arg.lstrip("-").isdigit():
        target_user_id = int(arg)
    else:
        await msg.reply_html("⚠️ Invalid format. Use @username or user_id.")
        return

    if await remove_auth_admin(chat.id, target_user_id):
        try:
            member = await chat.get_member(target_user_id)
            member_user = getattr(member, 'user', None)
            if member_user and member_user.first_name:
                mention = f"<a href='tg://user?id={member_user.id}'>{html.escape(member_user.first_name)}</a>"
            else:
                mention = str(target_user_id)
        except Exception:
            mention = str(target_user_id)

        await msg.reply_html(
            f"✅ <b>Hidden admin removed:</b> {mention}\n"
            f"👮 By: <a href='tg://user?id={user.id}'>{html.escape(user.first_name)}</a>"
        )
    else:
        await msg.reply_text("⚠️ This user is not a hidden admin.")

# ═══ MODULE: groupadminchats.admin.delmsg ═══

"""
delmsg.py — Delete a message (the one being replied to).

PTB v20+ port of Miss-Rose's `del_message` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ
+ polite wording.
"""

from telegram import Update
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_delete
async def delmsg_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/del` (reply) — delete the replied-to message and the command message."""
    chat = update.effective_chat
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    if not msg.reply_to_message:
        await msg.reply_text(
            f"🤔 {ssc('reply to the message you want me to delete, please')}."
        )
        return

    try:
        await msg.reply_to_message.delete()
    except BadRequest:
        logger.exception("delmsg: failed to delete target")
        await msg.reply_text(
            f"❌ {ssc('sorry, i couldn')}’{ssc('t delete that message')}."
        )
        return

    try:
        await msg.delete()
    except BadRequest:
        # We may not have delete permission for the command message itself —
        # not a big deal, the target message is gone.
        pass

# ═══ MODULE: groupadminchats.admin.demote ═══

"""
demote.py — Demote an admin back to a regular member.

PTB v20+ port of Miss-Rose's `demote` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite
wording.
"""

from telegram import Update
from telegram.constants import ChatMemberStatus
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_promote
async def demote_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/demote <user/id/reply>` — demote the user."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    user_id = await extract_user(update, context, _cmd_args(update, context))
    if not user_id:
        await msg.reply_text(
            f"🤔 {ssc('please mention someone')}… 🤷🏻‍♂️"
        )
        return

    try:
        user_member = await chat.get_member(user_id)
    except BadRequest:
        await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
        return

    if user_member.status == ChatMemberStatus.OWNER:
        await msg.reply_text(
            f"😬 {ssc('i can')}’{ssc('t demote the creator of the group')}."
        )
        return

    if user_member.status != ChatMemberStatus.ADMINISTRATOR:
        await msg.reply_text(
            f"ℹ️ {ssc('this user isn')}’{ssc('t an admin — nothing to demote')}."
        )
        return

    if user_id == context.bot.id:
        await msg.reply_text(
            f"😄 {ssc('i can')}’{ssc('t demote myself — get an admin to do it')}."
        )
        return

    if user_id == user.id:
        await msg.reply_text(
            f"🙃 {ssc('you can')}’{ssc('t demote yourself — ask another admin')}."
        )
        return

    try:
        await context.bot.promote_chat_member(
            chat.id, user_id,
            can_change_info=False,
            can_post_messages=False,
            can_edit_messages=False,
            can_delete_messages=False,
            can_invite_users=False,
            can_restrict_members=False,
            can_pin_messages=False,
            can_promote_members=False,
        )
        # Invalidate admin cache — their status just changed
        try:
            admin_cache.invalidate(chat.id, int(user_id))
        except Exception:
            pass
        await msg.reply_text(
            f"🧡 {ssc('demoted — thanks for the help while it lasted')}. "
            f"{ssc('hope you stick around')} 🫶"
        )
    except BadRequest:
        logger.exception("ERROR demoting user")
        await msg.reply_text(
            f"❌ {ssc('could not demote — i might not be admin, or the admin status was appointed by another user so i can')}"
            f"{ssc('t act on them')}."
        )

# ═══ MODULE: groupadminchats.admin.gameoff ═══

"""Gameoff command - disables games in the group."""

import asyncio
from telegram import Update
from telegram.ext import ContextTypes

logger = get_logger(__name__)


async def gameoff_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Disable games for the group."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if not chat or chat.type not in ["group", "supergroup"]:
        return

    admin_perms = await check_admin_permissions(update, user.id)
    if not admin_perms.get("is_admin") and user.id != OWNER_ID:
        auth_admins = await get_auth_admins(chat.id)
        if not any(a["user_id"] == user.id for a in auth_admins):
            return

    # FIX: Use key `gameoff_{chat.id}` — all game handlers check this exact key.
    # Previously `group_game_{chat.id}` was written but never read — gameoff was completely broken.
    await asyncio.to_thread(save_setting, f"gameoff_{chat.id}", "on")

    # Invalidate the gameoff cache so the change takes effect immediately
    invalidate_gameoff_cache(chat.id)

    await msg.reply_text("🎮 Games disabled for this group")

