# ═══ MODULE: groupadminchats.admin.kick ═══

"""
kick.py — Kick a user from the group (ban + unban).

PTB v20+ port of Miss-Rose's `kick` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite
wording. Auth-admin + OWNER bypass preserved.
"""

from telegram import Update
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_restrict
async def kick_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/kick <user/id/reply>` — kicks the user (ban + unban)."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    user_id, _reason = await extract_user_and_text(update, context, _cmd_args(update, context))

    if not user_id:
        await msg.reply_text(f"🤔 {ssc('please reply to a user, or pass')} "
                             f"<code>@username</code> {ssc('or')} "
                             f"<code>user_id</code>.")
        return

    try:
        member = await chat.get_member(user_id)
    except BadRequest as exc:
        if "User not found" in str(exc):
            await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
            return
        logger.exception("kick: get_member failed")
        raise

    if await is_user_admin(chat, user_id, member=member):
        await msg.reply_text(
            f"🙏 {ssc('i wish i could kick admins, but they')}’{ssc('re protected')}."
        )
        return

    if user_id == context.bot.id:
        await msg.reply_text(f"😄 {ssc('yeah, no — i am not kicking myself')}.")
        return

    if user_id == user.id:
        await msg.reply_text(f"🙃 {ssc('you can')}’{ssc('t kick yourself, friend')}.")
        return

    try:
        # Kick = ban + unban. We use a 60s ban window so the user can
        # rejoin via invite link.
        import time as _t
        await context.bot.ban_chat_member(
            chat.id, user_id, until_date=int(_t.time()) + 60,
        )
        await context.bot.unban_chat_member(chat.id, user_id, only_if_banned=True)
        await msg.reply_text(f"👢 {ssc('kicked')}.")
    except BadRequest as exc:
        err = str(exc)
        if err == "Reply message not found":
            await msg.reply_text(f"👢 {ssc('kicked')}.", quote=False)
        else:
            logger.exception("ERROR kicking user %s in chat %s (%s) due to %s",
                             user_id, chat.title, chat.id, err)
            await msg.reply_text(
                f"❌ {ssc('sorry, i couldn')}’{ssc('t kick that user')}."
            )

# ═══ MODULE: groupadminchats.admin.mute ═══

db_mute_user = mute_user
"""
mute.py — Mute a user in the group.

PTB v20+ port of Miss-Rose's `mute` handler with our extras:
  - `mute_user` DB record kept (for auto-unmute tracking)
  - Optional duration string accepted (`30m`, `2h`, `7d`)
  - Cᴏᴘʏ Tʜɪs Fᴏɴᴛ (small caps) + polite wording
"""

import time as _t
from telegram import Update, ChatPermissions
from telegram.constants import ParseMode
from telegram.error import BadRequest
from telegram.ext import ContextTypes
from telegram.helpers import mention_html


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_restrict
async def mute_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/mute <user/id/reply> [duration] [reason]` — mutes the user."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    # Pull first positional arg as user, rest as duration+reason
    user_id, reason_text = await extract_user_and_text(update, context, _cmd_args(update, context))
    if not user_id:
        await msg.reply_text(
            f"🤔 {ssc('please reply to a user, or pass')} "
            f"<code>@username</code> {ssc('or')} <code>user_id</code>."
        )
        return

    # Optional duration token
    duration_str = ""
    if reason_text:
        parts = reason_text.split(None, 1)
        if parts and len(parts[0]) >= 2 and parts[0][-1] in "mhd" and parts[0][:-1].isdigit():
            duration_str = parts[0]
            reason_text = parts[1] if len(parts) > 1 else ""

    if user_id == context.bot.id:
        await msg.reply_text(
            f"😄 {ssc('i am not gonna mute myself — that would be rude')}."
        )
        return

    if user_id == user.id:
        await msg.reply_text(
            f"🙃 {ssc('muting yourself')}? {ssc('not sure that helps')}."
        )
        return

    try:
        member = await chat.get_member(user_id)
    except BadRequest as exc:
        if "User not found" in str(exc):
            await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
            return
        logger.exception("mute: get_member failed")
        raise

    if await is_user_admin(chat, user_id, member=member):
        await msg.reply_text(
            f"🙏 {ssc('afraid i can')}’{ssc('t stop an admin from talking')}."
        )
        return

    mute_until = parse_mute_duration(duration_str)

    try:
        if mute_until > 0:
            await context.bot.restrict_chat_member(
                chat.id, user_id,
                permissions=ChatPermissions(),
                until_date=mute_until,
            )
        else:
            await context.bot.restrict_chat_member(
                chat.id, user_id,
                permissions=ChatPermissions(),
            )
            mute_until = 0
    except BadRequest as exc:
        err = str(exc)
        if err == "Reply message not found":
            pass
        else:
            logger.exception("ERROR muting user %s in chat %s (%s) due to %s",
                             user_id, chat.title, chat.id, err)
            await msg.reply_text(
                f"❌ {ssc('sorry, i couldn')}’{ssc('t mute that user')}."
            )
            return

    await db_mute_user(chat.id, user_id, user.id,
                       until=mute_until, reason=reason_text or "")

    target_name = member.user.first_name if member.user else "user"
    mention = mention_html(user_id, target_name)
    reason_display = small((reason_text or "")[:60])
    if mute_until > 0:
        remaining = mute_until - int(_t.time())
        duration_disp = format_mute_duration(remaining)
        await msg.reply_text(
            f"🤐 {ssc('muted')} {mention} {ssc('for')} "
            f"<b>{ssc(duration_disp)}</b>."
            + (f"\n📝 <i>{reason_display}</i>" if reason_display.strip() else ""),
            parse_mode=ParseMode.HTML,
        )
    else:
        await msg.reply_text(
            f"🤐 {ssc('permanently muted')} {mention}."
            + (f"\n📝 <i>{reason_display}</i>" if reason_display.strip() else ""),
            parse_mode=ParseMode.HTML,
        )

