# ═══ MODULE: groupadminchats.admin.pin ═══

"""
pin.py — Pin a message in the group.

PTB v20+ port of Miss-Rose's `pin` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite
wording. `notify`/`loud`/`violent` opt-in enables notification.
"""

from telegram import Update
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_pin
async def pin_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/pin` (reply) — pin a message. Add `notify`/`loud`/`violent` for sound."""
    chat = update.effective_chat
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    args = _cmd_args(update, context)
    prev = msg.reply_to_message
    if not prev:
        await msg.reply_text(
            f"🤔 {ssc('please reply to the message you want me to pin')}."
        )
        return

    is_silent = True
    if args and args[0].lower() in ("notify", "loud", "violent"):
        is_silent = False

    try:
        await context.bot.pin_chat_message(
            chat.id, prev.message_id, disable_notification=is_silent,
        )
        if is_silent:
            await msg.reply_text(
                f"📌 {ssc('pinned — quietly, no notification sent')}."
            )
        else:
            await msg.reply_text(
                f"📌 {ssc('pinned — members have been notified')} 🔔"
            )
    except BadRequest as exc:
        if "not modified" in str(exc).lower():
            return
        logger.exception("ERROR pinning message")
        await msg.reply_text(
            f"❌ {ssc('sorry, i couldn')}’{ssc('t pin that message')}."
        )

# ═══ MODULE: groupadminchats.admin.promote ═══

"""
promote.py — Promote a user to admin.

PTB v20+ port of Miss-Rose's `promote` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite
wording. Bot uses the same permission set as itself (since the bot can't
grant perms above its own). Use `None` for `getattr` default so we don't
accidentally deny channel-only perms on supergroup admins.
"""

from telegram import Update
from telegram.constants import ChatMemberStatus
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_promote
async def promote_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/promote <user/id/reply>` — promote the user with bot's own perms."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    user_id = await extract_user(update, context, _cmd_args(update, context))
    if not user_id:
        await msg.reply_text(
            f"🤔 {ssc('please mention someone')}… 🤷🏻‍♂️"
        )
        return

    try:
        user_member = await chat.get_member(user_id)
    except BadRequest:
        await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
        return

    if user_member.status in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER):
        await msg.reply_text(
            f"ℹ️ {ssc('this user is already an admin — no need to promote')}."
        )
        return

    if user_id == context.bot.id:
        await msg.reply_text(
            f"😄 {ssc('i can')}’{ssc('t promote myself — get an admin to do it')}."
        )
        return

    if user_id == user.id:
        await msg.reply_text(
            f"🙃 {ssc('you can')}’{ssc('t promote yourself — ask another admin')}."
        )
        return

    # Read the bot's own perms so we don't grant anything higher.
    # Use None as default so we don't *deny* perms the bot simply doesn't have.
    bot_member = await chat.get_member(context.bot.id)
    try:
        await context.bot.promote_chat_member(
            chat.id, user_id,
            can_change_info=getattr(bot_member, "can_change_info", None),
            can_post_messages=getattr(bot_member, "can_post_messages", None),
            can_edit_messages=getattr(bot_member, "can_edit_messages", None),
            can_delete_messages=getattr(bot_member, "can_delete_messages", None),
            can_invite_users=getattr(bot_member, "can_invite_users", None),
            can_restrict_members=getattr(bot_member, "can_restrict_members", None),
            can_pin_messages=getattr(bot_member, "can_pin_messages", None),
            can_promote_members=getattr(bot_member, "can_promote_members", None),
        )
        # Invalidate admin cache — their status just changed
        try:
            admin_cache.invalidate(chat.id, int(user_id))
        except Exception:
            pass
        await msg.reply_text(
            f"🧡 {ssc('promoted — welcome to the team')}! "
            f"{ssc('please be kind to the group')} 🫶"
        )
    except BadRequest as exc:
        err = str(exc)
        logger.exception("ERROR promoting user")
        await msg.reply_text(
            f"❌ {ssc('sorry, i couldn')}’{ssc('t promote that user')}. "
            f"<i>({err})</i>",
            parse_mode="HTML",
        )

# ═══ MODULE: groupadminchats.admin.setabuse ═══

"""Setabuse command - manages abuse filter words for a group.
OWNER ONLY - only the bot owner can add/remove/view banned words.

Usage:
  /setabuse               — list current words
  /setabuse list          — list current words
  /setabuse add <word>    — add a word
  /setabuse remove <word> — remove a word
  /setabuse clear         — clear all words
"""

from telegram import Update
from telegram.ext import ContextTypes

_USAGE = (
    "📋 Usage:\n"
    "• <code>/setabuse</code> — list words\n"
    "• <code>/setabuse add [word]</code> — add word\n"
    "• <code>/setabuse remove [word]</code> — remove word\n"
    "• <code>/setabuse clear</code> — clear all"
)


async def setabuse_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Manage abuse filter words - OWNER ONLY."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    args = context.args
    if args is None:
        text = msg.text or ""
        args = text.split()[1:] if len(text.split()) > 1 else []

    if not chat or not user or not msg:
        return

    # OWNER ONLY
    if user.id != OWNER_ID:
        return  # silent — non-owners get no response

    if chat.type not in ["group", "supergroup", "private"]:
        return

    # Determine chat_id to operate on
    # In private chat, need a group ID as first arg if no context
    if chat.type == "private":
        if not args or not args[0].lstrip("-").isdigit():
            await msg.reply_html(
                "⚠️ In private, use: <code>/setabuse [group_id] [action] [word]</code>\n"
                "Or use in a group directly."
            )
            return
        target_chat_id = int(args[0])
        args = args[1:] or []
    else:
        target_chat_id = chat.id

    # No args or "list" → show current words
    if not args or args[0].lower() == "list":
        words = await get_abuse_words(target_chat_id)
        if words:
            word_lines = "\n".join(f"• <code>{w}</code>" for w in words)
            text = f"🔒 <b>Abuse Words ({len(words)}):</b>\n{word_lines}"
        else:
            text = "🔒 No abuse words set yet."
        text += f"\n\n{_USAGE}"
        await msg.reply_html(text)
        return

    action = args[0].lower()

    if action == "add":
        if len(args) < 2:
            await msg.reply_html("⚠️ Use: <code>/setabuse add [word]</code>")
            return
        word = args[1].lower().strip()
        if len(word) < 2:
            await msg.reply_text("⚠️ Word must be at least 2 characters.")
            return
        await add_abuse_word(target_chat_id, word)
        words = await get_abuse_words(target_chat_id)
        await msg.reply_html(
            f"✅ <b>Added:</b> <code>{word}</code>\n"
            f"📊 Total words: {len(words)}"
        )

    elif action in ("remove", "del", "delete"):
        if len(args) < 2:
            await msg.reply_html("⚠️ Use: <code>/setabuse remove [word]</code>")
            return
        word = args[1].lower().strip()
        removed = await remove_abuse_word(target_chat_id, word)
        if removed:
            await msg.reply_html(f"✅ <b>Removed:</b> <code>{word}</code>")
        else:
            await msg.reply_html(f"⚠️ Word <code>{word}</code> not in the list.")

    elif action == "clear":
        await clear_abuse_words(target_chat_id)
        await msg.reply_text("✅ All abuse words cleared.")

    else:
        await msg.reply_html(_USAGE)

# ═══ MODULE: groupadminchats.admin.settitle ═══

"""Settitle command - changes group title."""

from telegram import Update
from telegram.ext import ContextTypes
import html
from telegram.error import BadRequest


async def settitle_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Change group title."""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message

    args = context.args
    if args is None:
        text = msg.text or ""
        args = text.split()[1:] if len(text.split()) > 1 else []

    if not chat or chat.type not in ["group", "supergroup"]:
        return

    if not args:
        await msg.reply_text("⚠️ Provide a new title.")
        return

    new_title = " ".join(args)

    admin_perms = await check_admin_permissions(update, user.id)
    if not admin_perms.get("is_admin") and user.id != OWNER_ID:
        if not any(a["user_id"] == user.id for a in await get_auth_admins(chat.id)):
            return

    if not admin_perms.get("can_change_info") and user.id != OWNER_ID and not await is_auth_admin(chat.id, user.id):
        await msg.reply_text("⚠️ I need permission to change group info.")
        return

    try:
        await context.bot.set_chat_title(chat_id=chat.id, title=new_title)
        admin_mention = f"<a href='tg://user?id={user.id}'>{html.escape(user.first_name)}</a>"

        await msg.reply_text(
            f"🏷️ Group title changed to: {html.escape(new_title)}\n"
            f"👮 By: {admin_mention}",
            parse_mode="HTML"
        )
    except BadRequest as e:
        await msg.reply_text(f"⚠️ Failed to change title: {str(e)}")
    except Exception as e:
        await msg.reply_text(f"⚠️ Error: {str(e)}")

