# ═══ MODULE: groupadminchats.admin.unban ═══

"""
unban.py — Unban a user from the group.

PTB v20+ port of Miss-Rose's `unban` handler with Cᴏᴘʏ Tʜɪs Fᴏɴᴛ
(small caps) and polite wording. Our auth-admin + OWNER bypass preserved.
"""

from telegram import Update
from telegram.constants import ChatMemberStatus
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


RUNBAN_ERRORS = {
    "User is an administrator of the chat",
    "Chat not found",
    "Not enough rights to restrict/unrestrict chat member",
    "User_not_participant",
    "Peer_id_invalid",
    "Group chat was deactivated",
    "Need to be inviter of a user to kick it from a basic group",
    "Chat_admin_required",
    "Only the creator of a basic group can kick group administrators",
    "Channel_private",
    "Not in the chat",
}


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_restrict
async def unban_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/unban <user/id/reply>` — unbans the user."""
    chat = update.effective_chat
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    user_id, _reason = await extract_user_and_text(update, context, _cmd_args(update, context))

    if not user_id:
        return

    try:
        member = await chat.get_member(user_id)
    except BadRequest as exc:
        if "User not found" in str(exc):
            await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find that user')}.")
            return
        logger.exception("unban: get_member failed")
        raise

    if user_id == context.bot.id:
        await msg.reply_text(
            f"🤔 {ssc('how would i unban myself if i wasn')}’{ssc('t here')}…?"
        )
        return

    # If user is still in the chat, refuse (Miss-Rose behaviour)
    if member.status in (
        ChatMemberStatus.MEMBER,
        ChatMemberStatus.ADMINISTRATOR,
        ChatMemberStatus.OWNER,
    ):
        await msg.reply_text(
            f"ℹ️ {ssc('this user is already in the chat, no need to unban')}."
        )
        return

    try:
        await context.bot.unban_chat_member(chat.id, user_id, only_if_banned=True)
    except BadRequest as exc:
        err = str(exc)
        if err == "Reply message not found":
            await msg.reply_text(f"✅ {ssc('unbanned')}.", quote=False)
        elif err in RUNBAN_ERRORS:
            await msg.reply_text(f"⚠️ {ssc(err.lower())}")
        else:
            logger.exception("ERROR unbanning user %s in chat %s (%s) due to %s",
                             user_id, chat.title, chat.id, err)
            await msg.reply_text(
                f"❌ {ssc('sorry, i couldn')}’{ssc('t unban that user')}."
            )
        return

    await msg.reply_text(
        f"✅ {ssc('all done — this user can now rejoin the group')} 🟢"
    )

# ═══ MODULE: groupadminchats.admin.unmute ═══

db_unmute_user = unmute_user
"""
unmute.py — Unmute a user in the group.

PTB v20+ port of Miss-Rose's `unmute` handler. Cᴏᴘʏ Tʜɪs Fᴏɴᴛ + polite
wording. Permissions are read from the `ChatMemberRestricted` instance
directly (in PTB v20+ they are NOT in a `.permissions` subobject).
"""

from telegram import Update, ChatPermissions
from telegram.constants import ChatMemberStatus
from telegram.error import BadRequest
from telegram.ext import ContextTypes


logger = get_logger(__name__)


# The full set of "can send X" permissions we want to restore.
# In PTB v20+, these are direct attributes on a ChatMemberRestricted instance.
_SEND_PERMS = (
    "can_send_messages",
    "can_send_audios",
    "can_send_documents",
    "can_send_photos",
    "can_send_videos",
    "can_send_video_notes",
    "can_send_voice_notes",
    "can_send_polls",
    "can_send_other_messages",
    "can_add_web_page_previews",
)


_DEFAULT_PERMS = ChatPermissions(
    can_send_messages=True,
    can_send_audios=True,
    can_send_documents=True,
    can_send_photos=True,
    can_send_videos=True,
    can_send_video_notes=True,
    can_send_voice_notes=True,
    can_send_polls=True,
    can_send_other_messages=True,
    can_add_web_page_previews=True,
    can_change_info=False,
    can_invite_users=True,
    can_pin_messages=False,
    can_manage_topics=False,
)


def _member_can_send_all(member) -> bool:
    """True if the member has all messaging perms (i.e. not muted)."""
    for attr in _SEND_PERMS:
        if getattr(member, attr, None) is not True:
            return False
    return True


async def _caller_is_authorized(update: Update) -> bool:
    chat = update.effective_chat
    user = update.effective_user
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    perms = await check_admin_permissions(update, user.id)
    if perms.get("is_admin"):
        return True
    if await is_auth_admin(chat.id, user.id):
        return True
    return False


@bot_admin
@bot_can_restrict
async def unmute_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """`/unmute <user/id/reply>` — unmutes the user."""
    chat = update.effective_chat
    msg = update.effective_message

    if chat.type not in ("group", "supergroup"):
        return

    if not await _caller_is_authorized(update):
        return

    user_id = await extract_user(update, context, _cmd_args(update, context))
    if not user_id:
        await msg.reply_text(
            f"🤔 {ssc('please reply to a user, or pass')} "
            f"<code>@username</code> {ssc('or')} <code>user_id</code>."
        )
        return

    try:
        member = await chat.get_member(user_id)
    except BadRequest as exc:
        if "User not found" in str(exc):
            await msg.reply_text(f"🤔 {ssc('i can')}’{ssc('t find this user')}.")
            return
        logger.exception("unmute: get_member failed")
        raise

    # If the user isn't in the chat at all, Miss-Rose says "unmuting them
    # won't make them talk more than they already do"
    if member.status in (ChatMemberStatus.LEFT, ChatMemberStatus.BANNED):
        await msg.reply_text(
            f"ℹ️ {ssc('this user is not in the chat — unmuting wouldn')}’"
            f"{ssc('t do much')}."
        )
        return

    # If the user is already fully able to talk, say so (don't re-restrict)
    if member.status in (ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.OWNER):
        if member.status != ChatMemberStatus.RESTRICTED or _member_can_send_all(member):
            await msg.reply_text(
                f"ℹ️ {ssc('this user already has the right to speak')}."
            )
            return

    try:
        await context.bot.restrict_chat_member(
            chat.id, user_id, permissions=_DEFAULT_PERMS,
        )
    except BadRequest as exc:
        err = str(exc)
        logger.exception("ERROR unmuting user %s in chat %s (%s) due to %s",
                         user_id, chat.title, chat.id, err)
        await msg.reply_text(
            f"❌ {ssc('sorry, i couldn')}’{ssc('t unmute that user')}."
        )
        return

    await db_unmute_user(chat.id, user_id)
    await msg.reply_text(f"🔊 {ssc('unmuted — welcome back to the conversation')}!")

