async def _edit_or_reply(update: Update, text: str, keyboard: InlineKeyboardMarkup) -> None:
    """Edit existing message or send a new one."""
    if update.callback_query:
        query = update.callback_query
        await query.answer()
        try:
            await query.edit_message_text(text=text, reply_markup=keyboard, parse_mode="HTML")
        except Exception:
            logger.warning("Exception in _edit_or_reply", exc_info=True)
    elif update.effective_message:
        await update.effective_message.reply_text(text=text, reply_markup=keyboard, parse_mode="HTML")


