# ═══ MODULE: groupadminchats.admin.message_filter ═══

"""Message handler for auto-deleting links and abuse words.

Admins and auth-admins are always exempt from these filters.
"""
logger = get_logger(__name__)

import re
from telegram import Update
from telegram.ext import ContextTypes, MessageHandler, filters
from telegram.error import BadRequest


async def _is_exempt(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Return True if the sender should be exempt from filters (admin / auth-admin)."""
    chat = update.effective_chat
    user = update.effective_user
    if not chat or not user:
        return True  # skip if no user info
    if user.is_bot:
        return True  # never filter bot messages

    try:
        perms = await check_admin_permissions(update, user.id)
        if perms.get("is_admin"):
            return True
    except Exception:
        logger.warning("Exception in _is_exempt", exc_info=True)

    try:
        auth_admins = await get_auth_admins(chat.id)
        if any(a["user_id"] == user.id for a in auth_admins):
            return True
    except Exception:
        logger.error("Unexpected error", exc_info=True)

    return False

async def message_filter_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Auto-delete messages with links or abuse words (admins are exempt).

    Optimized: 1 cached admin check + 1 cached group_settings fetch (instead
    of 1 Telegram API call + 3-4 DB calls per message). Most group messages
    now resolve in <1ms on cache hit.
    """
    chat = update.effective_chat
    msg = update.effective_message
    user = update.effective_user

    if not chat or not msg:
        return

    # Skip service messages
    if getattr(msg, "is_automatic_forward", False):
        return

    # Admins are always exempt — use cached fast path (5min TTL)
    if await _is_exempt(update, context):
        return

    text = msg.text or msg.caption or ""
    if not text:
        return

    should_delete = False
    delete_reason = ""

    # ── Combined DB read: one get_group_settings call serves both flags ─
    # get_group_settings is cached for 5 min so this is ~0.5μs on hit.
    settings = await get_group_settings(chat.id)

    # Check cleanlink
    if settings.get("cleanlink") and contains_link(text):
        should_delete = True
        delete_reason = "link"

    # Check abuse filter — only fetch the words list if abuse is enabled
    if not should_delete and settings.get("abuse_delete"):
        abuse_words = await get_abuse_words(chat.id)
        if abuse_words:
            text_lower = text.lower()
            abuse_words = [w for w in abuse_words if w.strip()]
            if abuse_words and any(re.search(rf'\b{re.escape(word)}\b', text_lower) for word in abuse_words):
                should_delete = True
                delete_reason = "abuse"

    if should_delete:
        try:
            await msg.delete()
        except BadRequest:
            # Bot lacks delete permission — silently ignore
            logger.warning("BadRequest", exc_info=True)
        except Exception:
            logger.error("Unexpected error", exc_info=True)


def get_message_filter_handler() -> MessageHandler:
    """Return a MessageHandler for filtering messages."""
    return MessageHandler(
        # Match TEXT and CAPTION messages (covers photos with captions too)
        (filters.TEXT | filters.CAPTION) & ~filters.COMMAND & ~filters.ChatType.PRIVATE,
        message_filter_handler
    )

# ═══ MODULE: minigames.timebomb ═══

"""
💣 TIMEBOMB GAME — Multiplayer Bomb Passing Game

Players pay entry fee, pass the bomb around.
Last player alive wins the pot!

Commands:
- /timebomb <amount> — Start a bomb game
- /joingame <amount> — Join before it starts
- /pass — Pass the bomb when you have it
- /timebombcancel — Admin cancels, refunds entry
"""


import asyncio
import html
import random
import time
from dataclasses import dataclass, field

from telegram import (
    InlineKeyboardButton,
    InlineKeyboardMarkup,
    Update,
)
from telegram.ext import ContextTypes


logger = get_logger(__name__)

__all__ = [
    "cmd_bomb",
    "cmd_joingame",
    "cmd_pass",
    "cmd_timebombcancel",
    "tb_callback",
    "start_cleanup_loop",
    "stop_cleanup_loop",
    "cleanup_stats",
]

# ═══════════════════════════════════════════
# 💰 ECONOMY HELPERS
# ═══════════════════════════════════════════

async def _add_balance(uid: int, amount: int) -> None:
    """Add to user balance."""
    await asyncio.to_thread(update_user_atomic, str(uid), {
        "balance": amount,
        "daily_income": amount,
        "weekly_income": amount,
        "lifetime_income": amount,
    }, {})

async def _charge_user(uid: int, amount: int) -> tuple[bool, str]:
    """Charge user for entry. Returns (success, error_msg)."""
    if amount <= 0:
        return True, ""
    try:
        if await asyncio.to_thread(try_deduct_balance, str(uid), amount):
            return True, ""
        data = await asyncio.to_thread(get_user, str(uid)) or {}
        balance = int(data.get("balance", 0) or 0)
        return False, f"⚠️ Iɴsᴜғғɪᴄɪᴇɴᴛ ʙᴀʟᴀɴᴄᴇ!\n\nNᴇᴇᴅ: ${amount:,}\nHᴀᴠᴇ: ${balance:,}"
    except Exception as e:
        logger.warning("Exception in _charge_user", exc_info=True)
        return False, f"Database error: {e}"


# ═══════════════════════════════════════════
# 🎮 GAME STATE
# ═══════════════════════════════════════════

MIN_BET = 50
MAX_PLAYERS = 12
BOMB_TIMER = 15  # seconds to pass bomb
LOBBY_TIMER = 60  # seconds before auto-start
MAX_GAME_AGE = 1800  # 30 min — auto-cleanup zombie games

_games: dict[int, "TimeBombGame"] = {}
_game_locks = BoundedLockDict(maxsize=100000)

timebomb__cleanup_task: asyncio.Task | None = None
_cleanup_interval = 300  # 5 min between sweeps
_cleanup_stats_data = {
    "sweeps": 0,
    "zombies_removed": 0,
    "last_sweep_at": 0.0,
}


async def _get_game_lock(chat_id: int) -> asyncio.Lock:
    return _game_locks.get(chat_id)


@dataclass
class TimeBombGame:
    chat_id: int
    host_id: int
    amount: int
    players: dict[int, str] = field(default_factory=dict)  # uid -> first_name
    paid: set[int] = field(default_factory=set)
    phase: str = "lobby"  # lobby, playing, finished
    pot: int = 0
    current_holder: int | None = None
    round_num: int = 0
    eliminated: list[int] = field(default_factory=list)
    message_id: int | None = None
    status_message_id: int | None = None
    bomb_task: asyncio.Task | None = None
    lobby_task: asyncio.Task | None = None
    created_at: float = field(default_factory=time.time)
    last_activity: float = field(default_factory=time.time)

    def alive_players(self) -> list[int]:
        return [uid for uid in self.players if uid not in self.eliminated]

    def is_alive(self, uid: int) -> bool:
        return uid in self.players and uid not in self.eliminated

    def cleanup(self):
        if self.bomb_task and not self.bomb_task.done():
            self.bomb_task.cancel()
        if self.lobby_task and not self.lobby_task.done():
            self.lobby_task.cancel()


# ═══════════════════════════════════════════
# 🎨 UI STRINGS
# ═══════════════════════════════════════════

def _lobby_text(game: TimeBombGame) -> str:
    players = "\n".join(
        f"  {'💣' if uid == game.current_holder else '👤'} {html.escape(name)}"
        for uid, name in game.players.items()
    )
    return (
        f"💣 <b>TɪᴍᴇBᴏᴍʙ Lᴏʙʙʏ</b>\n"
        f"{'─' * 25}\n\n"
        f"💰 Eɴᴛʀʏ Fᴇᴇ: <b>${game.amount:,}</b>\n"
        f"🏆 Pʀɪᴢᴇ Pᴏᴏʟ: <b>${game.pot:,}</b>\n"
        f"👥 Pʟᴀʏᴇʀs: <b>{len(game.players)}/{MAX_PLAYERS}</b>\n\n"
        f"{players}\n\n"
        f"⏳ Tᴀᴘ Jᴏɪɴ ᴏʀ ᴜsᴇ /joingame {game.amount}\n"
        f"💣 Usᴇ /timebomb {game.amount} ᴛᴏ ᴄʀᴇᴀᴛᴇ ʏᴏᴜʀ ᴏᴡɴ\n"
        f"🎮 Hᴏsᴛ ᴛᴀᴘs Sᴛᴀʀᴛ ᴡʜᴇɴ ʀᴇᴀᴅʏ"
    )


def _lobby_keyboard(game: TimeBombGame) -> InlineKeyboardMarkup:
    rows = []
    if len(game.players) < MAX_PLAYERS:
        rows.append([InlineKeyboardButton(f"💣 Jᴏɪɴ (${game.amount:,})", callback_data="tb_join")])
    if len(game.players) >= 2:
        rows.append([InlineKeyboardButton("🎮 Sᴛᴀʀᴛ Gᴀᴍᴇ", callback_data="tb_start")])
    rows.append([InlineKeyboardButton("❌ Cᴀɴᴄᴇʟ", callback_data="tb_cancel")])
    return InlineKeyboardMarkup(rows)


def _status_keyboard(game: TimeBombGame) -> InlineKeyboardMarkup:
    """Keyboard shown during play — Pass button + viewer status."""
    rows = []
    if game.current_holder:
        rows.append([InlineKeyboardButton("💣 Pᴀss Bᴏᴍʙ", callback_data="tb_pass")])
    rows.append([InlineKeyboardButton("❌ Cᴀɴᴄᴇʟ", callback_data="tb_cancel")])
    return InlineKeyboardMarkup(rows)


def _game_status_text(game: TimeBombGame) -> str:
    alive = game.alive_players()
    lines = []
    for uid in alive:
        name = game.players.get(uid, "Unknown")
        marker = " 💣" if uid == game.current_holder else ""
        lines.append(f"  👤 {html.escape(name)}{marker}")
    for uid in game.eliminated:
        name = game.players.get(uid, "Unknown")
        lines.append(f"  💀 {html.escape(name)} (ᴇʟɪᴍɪɴᴀᴛᴇᴅ)")

    holder_name = game.players.get(game.current_holder, "Unknown") if game.current_holder else "N/A"
    return (
        f"💣 <b>TɪᴍᴇBᴏᴍʙ — Rᴏᴜɴᴅ {game.round_num}</b>\n"
        f"{'─' * 25}\n\n"
        f"💰 Pᴏᴛ: <b>${game.pot:,}</b>\n"
        f"👥 Aʟɪᴠᴇ: <b>{len(alive)}</b>\n"
        f"💣 Hᴏʟᴅᴇʀ: <b>{html.escape(holder_name)}</b>\n\n"
        + "\n".join(lines) +
        f"\n\n⏱️ {BOMB_TIMER}s ᴛᴏ /pass ᴏʀ ᴛᴀᴘ Pᴀss ʙᴜᴛᴛᴏɴ!"
    )


def _explosion_text(game: TimeBombGame, victim_name: str) -> str:
    alive = game.alive_players()
    return (
        f"💥 <b>BOOM! {html.escape(victim_name)} ʙʟᴇᴡ ᴜᴘ!</b>\n\n"
        f"💰 Pᴏᴛ: <b>${game.pot:,}</b>\n"
        f"👥 Rᴇᴍᴀɪɴɪɴɢ: <b>{len(alive)}</b>"
    )


def _winner_text(game: TimeBombGame, winner_name: str) -> str:
    return (
        f"🏆 <b>TɪᴍᴇBᴏᴍʙ Wɪɴɴᴇʀ!</b>\n"
        f"{'─' * 25}\n\n"
        f"👑 <b>{html.escape(winner_name)}</b> sᴜʀᴠɪᴠᴇᴅ!\n"
        f"💰 Pʀɪᴢᴇ: <b>${game.pot:,}</b>\n\n"
        f"🎉 Cᴏɴɢʀᴀᴛᴜʟᴀᴛɪᴏɴs!"
    )


# ═══════════════════════════════════════════
# 🎯 COMMAND HANDLERS
# ═══════════════════════════════════════════

async def cmd_bomb(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Start a TimeBomb game. Usage: /timebomb <amount>"""
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or not user:
        return

    if chat.type == "private":
        await msg.reply_text("⚠️ Tʜɪs ɢᴀᴍᴇ ᴏɴʟʏ ᴡᴏʀᴋs ɪɴ ɢʀᴏᴜᴘs!")
        return

    if await verify_guard(update, ctx):
        return

    # Parse amount
    if not ctx.args or not ctx.args[0].isdigit():
        await msg.reply_text("⚠️ Usᴀɢᴇ: /timebomb <amount>\n\nExᴀᴍᴘʟᴇ: /timebomb 100")
        return
    amount = int(ctx.args[0])
    if amount < MIN_BET:
        await msg.reply_text(f"⚠️ Mɪɴɪᴍᴜᴍ ʙᴇᴛ ɪs ${MIN_BET}!")
        return

    async with await _get_game_lock(chat.id):
        if chat.id in _games and _games[chat.id].phase != "finished":
            await msg.reply_text("⚠️ A ɢᴀᴍᴇ ɪs ᴀʟʀᴇᴀᴅʏ ɪɴ ᴘʀᴏɢʀᴇss!")
            return

        # Charge host upfront (Bug 1: was charged in _start_game, allowed free play)
        ok, err = await _charge_user(user.id, amount)
        if not ok:
            await msg.reply_text(err)
            return

        # Create game
        game = TimeBombGame(
            chat_id=chat.id,
            host_id=user.id,
            amount=amount,
        )
        game.players[user.id] = user.first_name
        game.paid.add(user.id)
        game.pot = amount
        _games[chat.id] = game

    # Send lobby
    text = _lobby_text(game)
    keyboard = _lobby_keyboard(game)
    sent = await msg.reply_text(text, reply_markup=keyboard, parse_mode="HTML")
    game.message_id = sent.message_id

    # Auto-start timer
    async def _auto_start():
        await asyncio.sleep(LOBBY_TIMER)
        async with await _get_game_lock(chat.id):
            if chat.id in _games and _games[chat.id].phase == "lobby":
                await _start_game(chat.id, ctx)

    game.lobby_task = asyncio.create_task(_auto_start())


async def cmd_joingame(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Join a TimeBomb game. Usage: /joingame <amount>"""
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or not user:
        return

    if chat.type == "private":
        await msg.reply_text("⚠️ Tʜɪs ɢᴀᴍᴇ ᴏɴʟʏ ᴡᴏʀᴋs ɪɴ ɢʀᴏᴜᴘs!")
        return

    if await verify_guard(update, ctx):
        return

    async with await _get_game_lock(chat.id):
        if chat.id not in _games or _games[chat.id].phase != "lobby":
            await msg.reply_text("⚠️ Nᴏ ᴀᴄᴛɪᴠᴇ ʟᴏʙʙʏ! Usᴇ /timebomb <amount> ᴛᴏ ᴄʀᴇᴀᴛᴇ ᴏɴᴇ.")
            return

        game = _games[chat.id]

        if user.id in game.players:
            await msg.reply_text("⚠️ Yᴏᴜ ᴀʟʀᴇᴀᴅʏ ᴊᴏɪɴᴇᴅ!")
            return

        if len(game.players) >= MAX_PLAYERS:
            await msg.reply_text(f"⚠️ Lᴏʙʙʏ ɪs ғᴜʟʟ! ({MAX_PLAYERS} ᴘʟᴀʏᴇʀs ᴍᴀx)")
            return

        # Check amount matches
        if ctx.args and ctx.args[0].isdigit():
            join_amount = int(ctx.args[0])
            if join_amount != game.amount:
                await msg.reply_text(f"⚠️ Gᴀᴍᴇ ғᴇᴇ ɪs ${game.amount:,}, ɴᴏᴛ ${join_amount:,}!")
                return

        # Charge entry fee
        ok, err = await _charge_user(user.id, game.amount)
        if not ok:
            await msg.reply_text(err)
            return

        game.players[user.id] = user.first_name
        game.paid.add(user.id)
        game.pot += game.amount

    # Update lobby message
    await _update_lobby(chat.id, ctx)


async def cmd_pass(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Pass the bomb to another random player."""
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or not user:
        return

    if await verify_guard(update, ctx):
        return

    await _handle_pass(chat.id, user, ctx, reply_to=msg)


async def _handle_pass(chat_id: int, user, ctx, reply_to=None, q=None) -> None:
    """Shared pass logic — used by /pass command and inline button.

    Bug 5 fix: All state mutations + bomb_task cancel/recreate happen INSIDE
    the lock so the old timer cannot fire and re-eliminate the holder.
    """
    new_holder_id: int | None = None
    new_holder_name: str = "Unknown"
    passed_name: str = user.first_name

    async with await _get_game_lock(chat_id):
        if chat_id not in _games or _games[chat_id].phase != "playing":
            if reply_to:
                await reply_to.reply_text("⚠️ Nᴏ ᴀᴄᴛɪᴠᴇ ɢᴀᴍᴇ!")
            elif q:
                try:
                    await q.answer("⚠️ Nᴏ ᴀᴄᴛɪᴠᴇ ɢᴀᴍᴇ!", show_alert=True)
                except Exception:
                    pass
            return

        game = _games[chat_id]

        if game.current_holder != user.id:
            if reply_to:
                await reply_to.reply_text("⚠️ Yᴏᴜ ᴅᴏɴ'ᴛ ʜᴏʟᴅ ᴛʜᴇ ʙᴏᴍʙ!")
            elif q:
                try:
                    await q.answer("⚠️ Yᴏᴜ ᴅᴏɴ'ᴛ ʜᴏʟᴅ ᴛʜᴇ ʙᴏᴍʙ!", show_alert=True)
                except Exception:
                    pass
            return

        alive = game.alive_players()
        if len(alive) <= 1:
            return

        # Cancel old bomb timer INSIDE the lock so it cannot fire concurrently
        if game.bomb_task and not game.bomb_task.done():
            game.bomb_task.cancel()
            try:
                await game.bomb_task  # let cancellation propagate
            except (asyncio.CancelledError, Exception):
                pass

        # Pass to random player (not self)
        others = [uid for uid in alive if uid != user.id]
        if not others:
            return
        new_holder_id = random.choice(others)
        game.current_holder = new_holder_id
        game.round_num += 1
        game.last_activity = time.time()
        new_holder_name = game.players.get(new_holder_id, "Unknown")

        # Start new bomb timer INSIDE the lock so no caller races ahead
        game.bomb_task = asyncio.create_task(_bomb_timer(chat_id, new_holder_id, ctx))

    # Outside the lock — send user-visible feedback
    if new_holder_id is None:
        return
    text = (
        f"💣 <b>{html.escape(passed_name)}</b> ᴘᴀssᴇᴅ ᴛʜᴇ ʙᴏᴍʙ ᴛᴏ <b>{html.escape(new_holder_name)}</b>!\n\n"
        f"⏱️ {BOMB_TIMER}s ᴛᴏ /pass ᴏʀ ᴛᴀᴘ Pᴀss ʙᴜᴛᴛᴏɴ!"
    )
    if q:
        try:
            await q.answer("💣 Bᴏᴍʙ ᴘᴀssᴇᴅ!")
        except Exception:
            pass
    if reply_to:
        try:
            await reply_to.reply_text(text, parse_mode="HTML")
        except Exception:
            pass
    elif q and q.message:
        try:
            await q.message.reply_text(text, parse_mode="HTML")
        except Exception:
            pass

    # Update status (edits previous status message, no chat pollution)
    await _send_game_status(chat_id, ctx)


async def cmd_timebombcancel(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Cancel the game and refund entry fees."""
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    if not msg or not chat or not user:
        return

    # Check if admin or owner
    is_admin = False
    try:
        member = await chat.get_member(user.id)
        is_admin = member.status in ("administrator", "creator")
    except Exception:
        pass
    if user.id != OWNER_ID and not is_admin:
        await msg.reply_text("⚠️ Oɴʟʏ ᴀᴅᴍɪɴs ᴄᴀɴ ᴄᴀɴᴄᴇʟ!")
        return

    async with await _get_game_lock(chat.id):
        if chat.id not in _games:
            await msg.reply_text("⚠️ Nᴏ ᴀᴄᴛɪᴠᴇ ɢᴀᴍᴇ!")
            return

        game = _games[chat.id]
        game.cleanup()

        # Refund entry fees
        refunds = []
        for uid in game.paid:
            refunds.append((uid, game.amount))
        if refunds:
            updates = [(str(uid), {"balance": amount}, {}) for uid, amount in refunds]
            await asyncio.to_thread(bulk_update_users, updates)

        player_names = dict(game.players)
        del _games[chat.id]

    if refunds:
        refund_text = "\n".join(
            f"  💰 ${amount:,} → {player_names.get(uid, 'Unknown')}"
            for uid, amount in refunds
        )
        await msg.reply_text(
            f"❌ <b>Gᴀᴍᴇ Cᴀɴᴄᴇʟʟᴇᴅ!</b>\n\n"
            f"Rᴇғᴜɴᴅs:\n{refund_text}",
            parse_mode="HTML"
        )
    else:
        await msg.reply_text("❌ <b>Gᴀᴍᴇ Cᴀɴᴄᴇʟʟᴇᴅ!</b>", parse_mode="HTML")


# ═══════════════════════════════════════════
# 🎮 CALLBACK HANDLERS
# ═══════════════════════════════════════════

async def tb_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle TimeBomb inline buttons."""
    q = update.callback_query
    if not q or not q.data:
        return
    await q.answer()

    chat = q.message.chat if q.message else None
    user = q.from_user
    if not chat or not user:
        return

    data = q.data

    if data == "tb_join":
        await _handle_join(chat.id, user, ctx, q)
    elif data == "tb_start":
        await _handle_start(chat.id, user, ctx, q)
    elif data == "tb_cancel":
        await _handle_cancel(chat.id, user, ctx, q)
    elif data == "tb_pass":
        await _handle_pass(chat.id, user, ctx, q=q)


async def _handle_join(chat_id: int, user, ctx, q) -> None:
    async with await _get_game_lock(chat_id):
        if chat_id not in _games or _games[chat_id].phase != "lobby":
            return
        game = _games[chat_id]

        if user.id in game.players:
            return
        if len(game.players) >= MAX_PLAYERS:
            return

        # Charge entry fee
        ok, err = await _charge_user(user.id, game.amount)
        if not ok:
            try:
                await q.message.reply_text(err, reply_to_message_id=q.message.message_id)
            except Exception:
                pass
            return

        game.players[user.id] = user.first_name
        game.paid.add(user.id)
        game.pot += game.amount

    await _update_lobby(chat_id, ctx)


async def _handle_start(chat_id: int, user, ctx, q) -> None:
    async with await _get_game_lock(chat_id):
        if chat_id not in _games or _games[chat_id].phase != "lobby":
            return
        game = _games[chat_id]

        if user.id != game.host_id:
            try:
                await q.message.reply_text("⚠️ Oɴʟʏ ᴛʜᴇ ʜᴏsᴛ ᴄᴀɴ sᴛᴀʀᴛ!")
            except Exception:
                pass
            return

        if len(game.players) < 2:
            try:
                await q.message.reply_text("⚠️ Nᴇᴇᴅ ᴀᴛ ʟᴇᴀsᴛ 2 ᴘʟᴀʏᴇʀs!")
            except Exception:
                pass
            return

    await _start_game(chat_id, ctx)


async def _handle_cancel(chat_id: int, user, ctx, q) -> None:
    async with await _get_game_lock(chat_id):
        if chat_id not in _games:
            return
        game = _games[chat_id]

        is_admin = False
        try:
            chat = q.message.chat if q.message else None
            if chat:
                member = await chat.get_member(user.id)
                is_admin = member.status in ("administrator", "creator")
        except Exception:
            pass

        if user.id != game.host_id and user.id != OWNER_ID and not is_admin:
            try:
                await q.message.reply_text("⚠️ Oɴʟʏ ʜᴏsᴛ/ᴀᴅᴍɪɴ ᴄᴀɴ ᴄᴀɴᴄᴇʟ!")
            except Exception:
                pass
            return

        game.cleanup()

        # Refund
        if game.paid:
            updates = [(str(uid), {"balance": game.amount}, {}) for uid in game.paid]
            await asyncio.to_thread(bulk_update_users, updates)

        del _games[chat_id]

    try:
        await q.edit_message_text(
            "❌ <b>Gᴀᴍᴇ Cᴀɴᴄᴇʟʟᴇᴅ! Eɴᴛʀʏ ғᴇᴇs ʀᴇғᴜɴᴅᴇᴅ.</b>",
            parse_mode="HTML"
        )
    except Exception:
        pass


# ═══════════════════════════════════════════
# 🎯 GAME LOGIC
# ═══════════════════════════════════════════

async def _start_game(chat_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Start the game from lobby. Host already paid upfront in cmd_bomb."""
    if chat_id not in _games:
        return
    game = _games[chat_id]

    if game.lobby_task and not game.lobby_task.done():
        game.lobby_task.cancel()

    # (Bug 6 fix: host paid upfront in cmd_bomb — no late-charge here)
    game.phase = "playing"
    alive = game.alive_players()
    if len(alive) < 2:
        # Not enough players, refund
        if game.paid:
            updates = [(str(uid), {"balance": game.amount}, {}) for uid in game.paid]
            await asyncio.to_thread(bulk_update_users, updates)
        try:
            bot = ctx.bot
            await bot.send_message(
                chat_id,
                "⚠️ Nᴏᴛ ᴇɴᴏᴜɢʜ ᴘʟᴀʏᴇʀs! Gᴀᴍᴇ ᴄᴀɴᴄᴇʟʟᴇᴅ. Fᴇᴇs ʀᴇғᴜɴᴅᴇᴅ.",
                parse_mode="HTML"
            )
        except Exception:
            pass
        if chat_id in _games:
            del _games[chat_id]
        return

    # Pick first bomb holder
    game.current_holder = random.choice(alive)
    game.round_num = 1

    holder_name = game.players.get(game.current_holder, "Unknown")

    try:
        bot = ctx.bot
        await bot.send_message(
            chat_id,
            f"💣 <b>TɪᴍᴇBᴏᴍʙ Sᴛᴀʀᴛᴇᴅ!</b>\n\n"
            f"💰 Pᴏᴛ: <b>${game.pot:,}</b>\n"
            f"👥 Pʟᴀʏᴇʀs: <b>{len(alive)}</b>\n\n"
            f"💣 Tʜᴇ ʙᴏᴍʙ ɪs ᴡɪᴛʜ <b>{html.escape(holder_name)}</b>!\n"
            f"⏱️ {BOMB_TIMER}s ᴛᴏ /pass ᴏʀ ɪᴛ ᴇxᴘʟᴏᴅᴇs!",
            parse_mode="HTML"
        )
    except Exception:
        pass

    # Start bomb timer
    game.bomb_task = asyncio.create_task(_bomb_timer(chat_id, game.current_holder, ctx))


async def _bomb_timer(chat_id: int, holder_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Bomb timer — explodes if holder doesn't pass."""
    await asyncio.sleep(BOMB_TIMER)

    async with await _get_game_lock(chat_id):
        if chat_id not in _games:
            return
        game = _games[chat_id]
        if game.phase != "playing":
            return
        if game.current_holder != holder_id:
            return  # Already passed

        # 💥 BOMB EXPLODES
        victim_name = game.players.get(holder_id, "Unknown")
        game.eliminated.append(holder_id)

        alive = game.alive_players()

        try:
            bot = ctx.bot
            await bot.send_message(
                chat_id,
                _explosion_text(game, victim_name),
                parse_mode="HTML"
            )
        except Exception:
            pass

        if len(alive) <= 1:
            # Game over — winner!
            await _end_game(chat_id, ctx)
            return

        # Next round — new random holder
        game.current_holder = random.choice(alive)
        game.round_num += 1
        new_name = game.players.get(game.current_holder, "Unknown")

        try:
            await _send_game_status(chat_id, ctx)
            bot = ctx.bot
            await bot.send_message(
                chat_id,
                f"💣 Nᴇxᴛ ʀᴏᴜɴᴅ! Tʜᴇ ʙᴏᴍʙ ɪs ᴡɪᴛʜ <b>{html.escape(new_name)}</b>!\n"
                f"⏱️ {BOMB_TIMER}s ᴛᴏ /pass!",
                parse_mode="HTML"
            )
        except Exception:
            pass

        # Start new timer
        game.bomb_task = asyncio.create_task(_bomb_timer(chat_id, game.current_holder, ctx))


async def _end_game(chat_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """End the game and award prize."""
    if chat_id not in _games:
        return
    game = _games[chat_id]
    game.phase = "finished"

    alive = game.alive_players()
    if not alive:
        return

    winner_id = alive[0]
    winner_name = game.players.get(winner_id, "Unknown")

    # Award pot
    await _add_balance(winner_id, game.pot)

    try:
        bot = ctx.bot
        await bot.send_message(
            chat_id,
            _winner_text(game, winner_name),
            parse_mode="HTML"
        )
    except Exception:
        pass

    game.cleanup()
    if chat_id in _games:
        del _games[chat_id]


# ═══════════════════════════════════════════
# 🔧 HELPERS
# ═══════════════════════════════════════════

async def _update_lobby(chat_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Update the lobby message."""
    if chat_id not in _games:
        return
    game = _games[chat_id]
    if not game.message_id:
        return

    try:
        bot = ctx.bot
        await bot.edit_message_text(
            chat_id=chat_id,
            message_id=game.message_id,
            text=_lobby_text(game),
            reply_markup=_lobby_keyboard(game),
            parse_mode="HTML"
        )
    except Exception as e:
        logger.warning("Failed to update lobby for chat %s: %s", chat_id, e)


async def _send_game_status(chat_id: int, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Update game status — edit the previous status message instead of
    flooding the chat with a new one (Bug 8 fix)."""
    if chat_id not in _games:
        return
    game = _games[chat_id]

    text = _game_status_text(game)
    keyboard = _status_keyboard(game)

    # Try editing the previous status message first
    if game.status_message_id:
        try:
            await ctx.bot.edit_message_text(
                chat_id=chat_id,
                message_id=game.status_message_id,
                text=text,
                reply_markup=keyboard,
                parse_mode="HTML",
            )
            return
        except Exception:
            game.status_message_id = None  # stale — fall through to send

    # No previous message — send new and remember for next edit
    try:
        sent = await ctx.bot.send_message(
            chat_id,
            text,
            reply_markup=keyboard,
            parse_mode="HTML",
        )
        game.status_message_id = sent.message_id
    except Exception as e:
        logger.warning("Failed to send game status for chat %s: %s", chat_id, e)


# ═══════════════════════════════════════════
# 🧹 CLEANUP LOOP
# ═══════════════════════════════════════════

async def timebomb__cleanup_loop() -> None:
    """Sweep zombie games every _cleanup_interval seconds.

    Removes games older than MAX_GAME_AGE that are stuck in lobby or playing
    with no activity. Prevents memory leaks from crashed timers (Bug 3).
    """
    while True:
        try:
            await asyncio.sleep(_cleanup_interval)
        except asyncio.CancelledError:
            return
        try:
            await _cleanup_sweep()
        except Exception as e:
            logger.warning("TimeBomb cleanup sweep failed: %s", e)


async def _cleanup_sweep() -> int:
    """One pass: refund any zombie game older than MAX_GAME_AGE.
    Returns the count of removed games."""
    now = time.time()
    removed = 0
    stale_chats = [
        cid for cid, g in _games.items()
        if (now - g.last_activity) > MAX_GAME_AGE
    ]
    for chat_id in stale_chats:
        try:
            async with await _get_game_lock(chat_id):
                game = _games.get(chat_id)
                if not game:
                    continue
                # Refund all paid players — zombie game owes them money
                if game.paid:
                    try:
                        updates = [
                            (str(uid), {"balance": game.amount}, {})
                            for uid in game.paid
                        ]
                        await asyncio.to_thread(bulk_update_users, updates)
                    except Exception as e:
                        logger.warning("Zombie refund failed for chat %s: %s", chat_id, e)
                game.cleanup()
                _games.pop(chat_id, None)
                removed += 1
        except Exception as e:
            logger.warning("Zombie cleanup error for chat %s: %s", chat_id, e)
    if removed:
        _cleanup_stats_data["zombies_removed"] += removed
        logger.info("TimeBomb cleanup: removed %s zombie game(s)", removed)
    _cleanup_stats_data["sweeps"] += 1
    _cleanup_stats_data["last_sweep_at"] = time.time()
    return removed


def timebomb__start_cleanup_loop(interval: float = 300.0) -> asyncio.Task:
    """Start the periodic cleanup task. Idempotent — safe to call multiple times."""
    global timebomb__cleanup_task, _cleanup_interval
    if timebomb__cleanup_task and not timebomb__cleanup_task.done():
        return timebomb__cleanup_task
    _cleanup_interval = max(60.0, float(interval))
    timebomb__cleanup_task = asyncio.create_task(timebomb__cleanup_loop())
    return timebomb__cleanup_task


def timebomb__stop_cleanup_loop() -> None:
    """Stop the cleanup task (useful for tests/shutdown)."""
    global timebomb__cleanup_task
    if timebomb__cleanup_task and not timebomb__cleanup_task.done():
        timebomb__cleanup_task.cancel()
    timebomb__cleanup_task = None


def timebomb__cleanup_stats() -> dict:
    """Return current cleanup statistics."""
    return {
        **_cleanup_stats_data,
        "active_games": len(_games),
        "interval": _cleanup_interval,
    }


# main.py should call start_cleanup_loop() after the event loop starts.

# ═══ MODULE: utils.batch ═══

import asyncio
from typing import Callable, TypeVar, Any, Sequence

T = TypeVar("T")
R = TypeVar("R")

async def gather_batched(
    items: Sequence[T],
    worker: Callable[[T], Any],
    batch_size: int = 500,
    return_exceptions: bool = True,
) -> list[Any]:
    results = []
    for i in range(0, len(items), batch_size):
        batch = items[i : i + batch_size]
        batch_results = await asyncio.gather(
            *[worker(item) for item in batch],
            return_exceptions=return_exceptions,
        )
        results.extend(batch_results)
    return results

# ═══ MODULE: owner.broadcast.manager ═══

"""
Broadcast Manager v5.0 - Telegram API integration
Fetches groups/channels directly from Telegram API
Supports custom speed format (users/sec via N/M syntax)
"""
import asyncio
import json
import os
import time
import threading
from typing import Dict, Any, List, Optional, Callable

from telegram import Bot
import httpx
import re

_BROADCAST_CHECKPOINT = "broadcast_checkpoint.json"

logger = get_logger(__name__)


def extract_wait_seconds(error: Exception) -> float:
    """Extract retry-after seconds from Telegram errors."""
    try:
        match = re.search(r'retry after (\d+)', str(error).lower())
        if match:
            return float(match.group(1))
    except Exception:
        logger.warning("Exception in extract_wait_seconds", exc_info=True)
    return 5.0


class BroadcastState:
    """Thread-safe broadcast state."""
    def __init__(self):
        self._lock = threading.Lock()
        self._data: Dict[str, Any] = {
            "running": False,
            "sent": 0,
            "failed": 0,
            "total": 0,
            "start_time": 0,
            "type": "",
            "payload": None,
            "speed": 0,
            "success_list": [],
            "failed_list": [],
        }

    def update(self, **kwargs):
        with self._lock:
            self._data.update(kwargs)

    def get(self) -> Dict[str, Any]:
        with self._lock:
            return dict(self._data)

    def set_running(self, running: bool):
        with self._lock:
            self._data["running"] = running

    def is_running(self) -> bool:
        with self._lock:
            return self._data.get("running", False)


async def fetch_all_bot_chats_via_api() -> Dict[str, List[int]]:
    """
    Fetch ALL chats (groups, channels, users) the bot is member of.
    Returns dict with 'groups', 'channels', 'users' lists of chat IDs.

    NOTE: we deliberately do NOT call Telegram's getUpdates here — the bot's
    own PTB poller already consumes getUpdates, and a second raw getUpdates
    request triggers a Conflict error that kills the bot. Chats are instead
    sourced from the registered-chats DB (grown passively by
    _register_seen_chat on every update the bot receives).
    """
    groups = []
    channels = []
    users = set()

    try:
        # Load from database registered chats (heavy cache, 5min TTL)
        db_chats = await asyncio.to_thread(get_cached_chats, get_registered_chats)
        for chat in db_chats:
            chat_type = chat.get("type", "")
            chat_id = chat.get("chat_id")
            if not chat_id:
                continue
            if chat_type in ("group", "supergroup") and chat_id not in groups:
                groups.append(chat_id)
            elif chat_type == "channel" and chat_id not in channels:
                channels.append(chat_id)
            elif chat_type == "private" and chat_id not in users:
                users.add(chat_id)
    except Exception:
        logger.debug("Failed to load registered chats from DB")

    return {
        "groups": groups,
        "channels": channels,
        "users": list(users)
    }


class BroadcastManager:
    """
    Broadcast Manager with Telegram API integration.
    Fetches targets from multiple sources for comprehensive coverage.
    """
    def __init__(self):
        self.state = BroadcastState()
        self._task: Optional[asyncio.Task] = None
        self._broadcast_history: List[Dict] = []
        self._last_broadcast_msg_ids: Dict[int, int] = {}  # chat_id -> message_id
        self._last_pinned_msg_ids: Dict[int, int] = {}      # chat_id -> message_id

    @staticmethod
    def parse_speed(speed_str: str) -> float | None:
        """Parse 'N/M' speed format into rate_delay in seconds.
        Returns None if format is invalid."""
        m = re.match(r'^(\d+)/(\d+)$', speed_str.strip())
        if m:
            users = int(m.group(1))
            seconds = int(m.group(2))
            if users > 0 and seconds > 0:
                return seconds / users
        return None

    def _save_checkpoint(self, chat_id: int, idx: int, sent: int, failed: int,
                         targets: list, target_type: str, content_text: str,
                         rate_delay: float = 0.05):
        """Persist broadcast progress so it can resume after restart."""
        try:
            with open(_BROADCAST_CHECKPOINT, "w") as f:
                json.dump({
                    "chat_id": chat_id,
                    "idx": idx,
                    "sent": sent,
                    "failed": failed,
                    "targets": [int(t) for t in targets],
                    "target_type": target_type,
                    "content_text": content_text,
                    "rate_delay": rate_delay,
                    "timestamp": time.time(),
                }, f)
        except Exception as e:
            logger.debug(f"Failed to save broadcast checkpoint: {e}")

    def _load_checkpoint(self) -> dict | None:
        try:
            if os.path.exists(_BROADCAST_CHECKPOINT):
                with open(_BROADCAST_CHECKPOINT) as f:
                    return json.load(f)
        except Exception as e:
            logger.debug(f"Failed to load broadcast checkpoint: {e}")
        return None

    def _clear_checkpoint(self):
        try:
            if os.path.exists(_BROADCAST_CHECKPOINT):
                os.remove(_BROADCAST_CHECKPOINT)
        except Exception as e:
            logger.debug(f"Failed to clear broadcast checkpoint: {e}")

    async def resume_broadcast(self, bot: Bot) -> bool:
        """Resume a broadcast from checkpoint. Returns True if resumed."""
        cp = self._load_checkpoint()
        if not cp:
            return False
        if self.state.is_running():
            return False

        targets = cp.get("targets", [])
        idx = cp.get("idx", 0)
        sent = cp.get("sent", 0)
        failed = cp.get("failed", 0)
        target_type = cp.get("target_type", "all")
        content_text = cp.get("content_text", "")
        rate_delay = cp.get("rate_delay", 0.05)

        if not targets or idx >= len(targets):
            self._clear_checkpoint()
            return False

        remaining = targets[idx:]
        sent_before = sent

        self.state.update(
            running=True,
            sent=sent,
            failed=failed,
            total=len(targets),
            start_time=time.time(),
            type=target_type,
            payload=content_text[:100],
            speed=0,
        )

        logger.info(f"Resuming broadcast: {target_type}, {len(remaining)}/{len(targets)} remaining")

        self._task = asyncio.create_task(
            self._run_broadcast(bot, remaining, content_text, target_type, None, idx, sent, failed, targets, rate_delay)
        )
        return True

    async def start_broadcast(
        self,
        bot: Bot,
        target_type: str,
        content: Any,
        progress_callback: Optional[Callable] = None,
        rate_delay: float = 0.05,
    ) -> bool:
        """Start a broadcast."""
        if self.state.is_running():
            logger.warning("Broadcast already in progress")
            return False

        db_chats = []
        db_users = []
        try:
            db_chats = await asyncio.to_thread(get_cached_chats, get_registered_chats)
            db_users = await asyncio.to_thread(get_cached_all_users, list_all_users)
        except Exception:
            logger.error("DB fetch error", exc_info=True)

        # Get Telegram API chats
        tg_chats = await fetch_all_bot_chats_via_api()

        # Build target list
        all_groups = set(tg_chats.get("groups", []))
        all_channels = set(tg_chats.get("channels", []))
        all_users = set(tg_chats.get("users", []))

        # Add DB groups
        for c in db_chats:
            if c.get("type") in ("group", "supergroup"):
                all_groups.add(c.get("chat_id"))
            elif c.get("type") == "private":
                all_users.add(c.get("chat_id"))

        # Add DB users
        for uid, _ in db_users:
            if uid is None:
                continue
            if isinstance(uid, str):
                uid = uid.strip()
                if uid.isdigit():
                    all_users.add(int(uid))
            elif isinstance(uid, (int, float)):
                all_users.add(int(uid))

        targets = []
        if target_type == 'premium':
            targets = list(all_users)
        elif target_type == 'users':
            targets = list(all_users)
        elif target_type == 'groups':
            targets = list(all_groups | all_channels)
        elif target_type == 'channels':
            targets = list(all_channels)
        else:  # all
            targets = list(all_users | all_groups | all_channels)

        # Filter premium targets
        if target_type == 'premium':
            results = await gather_batched(
                targets,
                lambda uid: asyncio.to_thread(is_premium, uid),
                batch_size=500,
            )
            targets = [uid for uid, ok in zip(targets, results) if ok is True]

        if not targets:
            logger.info(f"No targets for broadcast: {target_type}")
            return False

        content_text = str(content) if isinstance(content, str) else ""

        # Initialize state
        self.state.update(
            running=True,
            sent=0,
            failed=0,
            total=len(targets),
            start_time=time.time(),
            type=target_type,
            payload=content_text[:100],
            speed=0,
        )

        logger.info(f"Starting broadcast: {target_type}, {len(targets)} targets")

        # Save initial checkpoint
        self._save_checkpoint(0, 0, 0, 0, targets, target_type, content_text, rate_delay)

        # Start
        self._task = asyncio.create_task(
            self._run_broadcast(bot, targets, content, target_type, progress_callback, 0, 0, 0, None, rate_delay)
        )
        return True

    async def _run_broadcast(
        self,
        bot: Bot,
        targets: list,
        content: Any,
        target_type: str,
        progress_callback: Optional[Callable] = None,
        start_idx: int = 0,
        sent_before: int = 0,
        failed_before: int = 0,
        full_targets: list | None = None,
        rate_delay: float = 0.05,
    ):
        """Execute broadcast."""
        start_time = time.time()
        sent = sent_before
        failed = failed_before
        all_targets = full_targets or targets
        total_targets = len(all_targets)

        content_text = str(content) if isinstance(content, str) else ""

        # Notify owner
        try:
            verb = "Resumed" if start_idx > 0 else "Started"
            await bot.send_message(
                OWNER_ID,
                f"🚀 <b>Broadcast {verb}</b>\n\n"
                f"📤 Type: <b>{target_type.upper()}</b>\n"
                f"🎯 Targets: <b>{total_targets:,}</b>"
                + (f" ({len(targets):,} remaining)" if start_idx > 0 else ""),
                parse_mode="HTML"
            )
        except Exception as exc:
            logger.debug(f"Broadcast start notify error: {exc}")

        # Process targets
        for i, chat_id in enumerate(targets):
            if not self.state.is_running():
                self._save_checkpoint(chat_id, start_idx + i, sent, failed,
                                      all_targets, target_type, content_text, rate_delay)
                break

            success = False
            error_msg = ""

            try:
                if isinstance(content, str):
                    msg_obj = await bot.send_message(chat_id, content, parse_mode="HTML")
                    self._last_broadcast_msg_ids[chat_id] = msg_obj.message_id
                elif callable(content):
                    msg_obj = await content(bot, chat_id)
                    if msg_obj is None:
                        raise RuntimeError("Broadcast callable returned None (delivery failed)")
                    if hasattr(msg_obj, 'message_id'):
                        self._last_broadcast_msg_ids[chat_id] = msg_obj.message_id
                else:
                    raise TypeError(f"Unsupported broadcast content type: {type(content)}")
                success = True
                sent += 1

            except Exception as e:
                failed += 1
                error_msg = str(e).lower()
                logger.debug(f"Broadcast error {chat_id}: {e}")

                # Handle flood wait
                if "too many requests" in error_msg:
                    wait = extract_wait_seconds(e)
                    await asyncio.sleep(wait)
                    try:
                        if isinstance(content, str):
                            msg_obj = await bot.send_message(chat_id, content, parse_mode="HTML")
                            self._last_broadcast_msg_ids[chat_id] = msg_obj.message_id
                        else:
                            msg_obj = await content(bot, chat_id)
                            if msg_obj and hasattr(msg_obj, 'message_id'):
                                self._last_broadcast_msg_ids[chat_id] = msg_obj.message_id
                        success = True
                        sent += 1
                        failed -= 1  # retry succeeded, undo the earlier failure count
                    except Exception as exc:
                        logger.debug(f"Broadcast retry error for {chat_id}: {exc}")

            # Update state
            self.state.update(sent=sent, failed=failed)

            # Save checkpoint every target for resume-on-crash
            self._save_checkpoint(chat_id, start_idx + i + 1, sent, failed,
                                  all_targets, target_type, content_text, rate_delay)

            await asyncio.sleep(rate_delay)

        # Complete
        self._clear_checkpoint()
        elapsed = time.time() - start_time
        final_speed = sent / elapsed if elapsed > 0 else 0
        self.state.set_running(False)

        # Record in history
        self._broadcast_history.append({
            "type": target_type,
            "sent": sent,
            "failed": failed,
            "total": total_targets,
            "elapsed": elapsed,
            "speed": final_speed,
            "timestamp": time.time(),
            "sent_ids": list(self._last_broadcast_msg_ids.items()),
        })
        # Keep only last 20
        self._broadcast_history = self._broadcast_history[-20:]

        # Notify completion (only notification, no intermediate updates)
        try:
            success_rate = f"{(sent/total_targets)*100:.1f}%" if total_targets > 0 else "N/A"
            speed_info = f"{int(1/rate_delay)}/sec" if rate_delay > 0 else "N/A"
            await bot.send_message(
                OWNER_ID,
                f"✅ <b>BROADCAST COMPLETE</b>\n\n"
                f"📊 <b>Results:</b>\n"
                f"━━━━━━━━━━━━━━\n"
                f"🎯 Type: <b>{target_type.upper()}</b>\n"
                f"✅ Sent: <b>{sent:,}</b>\n"
                f"⚠️ Failed: <b>{failed:,}</b>\n"
                f"⏱️ Time: <b>{elapsed:.1f}s</b>\n"
                f"⚡ Speed: <b>{speed_info} ({final_speed:.1f}/sec actual)</b>\n"
                f"📈 Success Rate: <b>{success_rate}</b>\n\n"
                + (f"ℹ️ Resumed from previous checkpoint — skipped {start_idx} already delivered." if start_idx > 0 else ""),
                parse_mode="HTML"
            )
        except Exception as exc:
            logger.debug(f"Broadcast completion notify error: {exc}")

        logger.info(f"Broadcast done: {sent} sent, {failed} failed in {elapsed:.1f}s")

    def stop(self):
        """Stop current broadcast."""
        if self.state.is_running():
            self.state.set_running(False)
            if self._task and not self._task.done():
                self._task.cancel()
            logger.info("Broadcast stopped")

    def get_stats(self) -> Dict[str, Any]:
        """Get detailed broadcast stats."""
        state = self.state.get()
        elapsed = time.time() - state.get("start_time", 0)
        current_speed = state.get("sent", 0) / elapsed if elapsed > 0 else 0

        return {
            "running": state.get("running", False),
            "sent": state.get("sent", 0),
            "failed": state.get("failed", 0),
            "total": state.get("total", 0),
            "type": state.get("type", ""),
            "speed": current_speed,
            "elapsed": elapsed,
            "progress_percent": (state.get("sent", 0) / state.get("total", 0) * 100) if state.get("total", 0) else 0,
            "remaining": state.get("total", 0) - state.get("sent", 0),
            "history": self._broadcast_history[-5:],
        }

    def get_history(self) -> List[Dict]:
        """Get broadcast history."""
        return list(self._broadcast_history)

    def get_last_broadcast_msg_ids(self) -> Dict[int, int]:
        """Get the last broadcast's sent message IDs (chat_id -> message_id)."""
        return dict(self._last_broadcast_msg_ids)

    def get_last_pinned_msg_ids(self) -> Dict[int, int]:
        """Get the last pin broadcast's pinned message IDs."""
        return dict(self._last_pinned_msg_ids)

    def clear_last_broadcast(self) -> None:
        """Clear last broadcast message ID tracking."""
        self._last_broadcast_msg_ids.clear()

    def clear_last_pinned(self) -> None:
        """Clear last pinned message ID tracking."""
        self._last_pinned_msg_ids.clear()

    def is_running(self) -> bool:
        """Check if broadcast is running."""
        return self.state.is_running()


# Global singleton
manager = BroadcastManager()

