def get_keyboard(path: List[str]) -> InlineKeyboardMarkup:
    """Builds a keyboard based on the current navigation path using full uncompressed keys."""
    logger.debug(f"Menu Navigator: Path={path}")
    
    current_node = MENU_STRUCTURE
    for key in path:
        if key in current_node:
            current_node = current_node[key]
            if "children" in current_node:
                current_node = current_node["children"]
        else:
            current_node = MENU_STRUCTURE
            break

    is_root = current_node is MENU_STRUCTURE
    # Leaf node = single item with is_action set (not a children-dict of sub-items)
    if not isinstance(current_node, dict) or (not is_root and current_node.get("is_action")):
        compressed_back = [MENU_KEY_MAP.get(k, k) for k in path[:-1]]
        return InlineKeyboardMarkup([[InlineKeyboardButton(f"🔙 {to_medium_caps('back')}",
                                    callback_data=f"own_nav:{'|'.join(compressed_back)}")]])

    buttons = []
    child_keys = list(current_node.keys())
    for i in range(0, len(child_keys), 2):
        row = []
        for j in range(i, min(i + 2, len(child_keys))):
            key = child_keys[j]
            item = current_node[key]
            label = f"{item['label']}".strip()
            parts = label.split(" ", 1)
            if len(parts) == 2:
                formatted_label = f"{parts[0]} {to_medium_caps(parts[1])}"
            else:
                formatted_label = to_medium_caps(label)
            
            compressed_key = MENU_KEY_MAP.get(key, key)
            new_compressed_path = [MENU_KEY_MAP.get(k, k) for k in (path + [key])]
            row.append(InlineKeyboardButton(formatted_label, callback_data=f"own_nav:{'|'.join(new_compressed_path)}"))
        buttons.append(row)

    if path:
        back_compressed = [MENU_KEY_MAP.get(k, k) for k in path[:-1]]
        buttons.append([InlineKeyboardButton(f"🔙 {to_medium_caps('back')}", 
                            callback_data=f"own_nav:{'|'.join(back_compressed)}")])
    else:
        buttons.append([InlineKeyboardButton(f"❌ {to_medium_caps('close')}", 
                            callback_data="own_close")])

    return InlineKeyboardMarkup(buttons)

