"""
Ultra-Scalable Cache System for Billions of Users
Optimized for high concurrency and massive scale
"""

import time
import threading
import hashlib
import zlib

logger = get_logger(__name__)
import json
import base64
import datetime as _dt
from typing import Dict, List, Optional, Any, Tuple
from collections import OrderedDict, defaultdict
from dataclasses import dataclass, field
from concurrent.futures import ThreadPoolExecutor
import asyncio
import functools
import random


@dataclass
class CacheConfig:
    """Configuration for billion-user cache"""
    max_memory_mb: int = 4096  # 4GB max memory
    target_hit_rate: float = 0.95  # 95% hit rate target
    shard_count: int = 1024  # Increased from 256 for better distribution
    max_shard_size: int = 10000  # Max entries per shard
    compression_enabled: bool = True
    compression_level: int = 3  # Balanced compression
    ttl_default: int = 3600  # 1 hour default TTL
    ttl_extend_on_access: bool = True
    write_behind_enabled: bool = True
    write_behind_batch_size: int = 1000
    write_behind_interval: float = 5.0  # 5 seconds
    stats_collection_enabled: bool = True
    stats_interval: int = 60  # Collect stats every minute


class SafeSerializer:
    """Safe serialization to replace insecure pickle"""
    
    @staticmethod
    def serialize(data: Any) -> bytes:
        """Serialize data to JSON bytes with support for common types"""
        def _default(obj):
            if isinstance(obj, bytes):
                return {"__bytes__": base64.b64encode(obj).decode('ascii')}
            if isinstance(obj, _dt.datetime):
                return {"__datetime__": obj.isoformat()}
            if isinstance(obj, (set, frozenset)):
                return {"__set__": list(obj)}
            if isinstance(obj, complex):
                return {"__complex__": [obj.real, obj.imag]}
            # For other non-serializable types, raise TypeError
            raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")
        
        return json.dumps(data, default=_default, separators=(',', ':')).encode('utf-8')
    
    @staticmethod
    def deserialize(data: bytes) -> Any:
        """Deserialize JSON bytes back to Python objects"""
        def _object_hook(obj):
            if '__bytes__' in obj:
                return base64.b64decode(obj['__bytes__'].encode('ascii'))
            if '__datetime__' in obj:
                return _dt.datetime.fromisoformat(obj['__datetime__'])
            if '__set__' in obj:
                return set(obj['__set__'])
            if '__complex__' in obj:
                return complex(obj['__complex__'][0], obj['__complex__'][1])
            return obj
        
        return json.loads(data.decode('utf-8'), object_hook=_object_hook)
    
    @staticmethod
    def estimate_size(data: Any) -> int:
        """Estimate serialized size in bytes"""
        return len(SafeSerializer.serialize(data))


class CompressedCacheEntry:
    """Cache entry with compression support"""
    
    __slots__ = ('data', 'compressed', 'size', 'access_time', 'create_time', 'ttl', 'access_count')
    
    def __init__(self, data: Any, ttl: int = 3600, compress: bool = True):
        self.access_time = time.time()
        self.create_time = self.access_time
        self.ttl = ttl
        self.access_count = 0
        
        if compress:
            serialized = SafeSerializer.serialize(data)
            compressed_data = zlib.compress(serialized, level=3)
            if len(compressed_data) < len(serialized):
                self.data = compressed_data
                self.compressed = True
                self.size = len(self.data)
            else:
                self.data = serialized
                self.compressed = False
                self.size = len(self.data)
        else:
            self.data = data
            self.compressed = False
            self.size = self._estimate_size(data)
    
    def _compress(self, data: Any) -> bytes:
        """Compress data using zlib with safe serialization"""
        try:
            serialized = SafeSerializer.serialize(data)
            return zlib.compress(serialized, level=3)
        except Exception:
            # Fallback to no compression
            logger.warning("Exception in _compress", exc_info=True)
            return SafeSerializer.serialize(data)
    
    def _decompress(self) -> Any:
        """Decompress data with safe deserialization"""
        try:
            if self.compressed:
                serialized = zlib.decompress(self.data)
                return SafeSerializer.deserialize(serialized)
            elif isinstance(self.data, bytes):
                return SafeSerializer.deserialize(self.data)
            else:
                return self.data
        except Exception:
            # If decompression fails, return None
            logger.warning("Exception in _decompress", exc_info=True)
            return None
    
    def _estimate_size(self, data: Any) -> int:
        """Estimate size of data in bytes using safe serialization"""
        try:
            return SafeSerializer.estimate_size(data)
        except Exception:
            logger.warning("Exception in _estimate_size", exc_info=True)
            return 1024  # Default estimate
    
    def get_value(self) -> Optional[Any]:
        """Get decompressed value and update access stats"""
        self.access_time = time.time()
        self.access_count += 1
        return self._decompress()
    
    def is_expired(self) -> bool:
        """Check if entry is expired"""
        return time.time() > (self.create_time + self.ttl)
    
    def extend_ttl(self, ttl: Optional[int] = None):
        """Extend TTL of entry"""
        if ttl:
            self.ttl = ttl
        self.create_time = time.time()


class ShardedLRUCache:
    """Sharded LRU cache for massive concurrency"""
    
    def __init__(self, shard_id: int, max_size: int = 10000):
        self.shard_id = shard_id
        self.max_size = max_size
        self.cache: OrderedDict[str, CompressedCacheEntry] = OrderedDict()
        self.lock = threading.RLock()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.total_size = 0
    
    def get(self, key: str) -> Optional[Any]:
        """Get value from cache"""
        with self.lock:
            if key in self.cache:
                entry = self.cache[key]
                
                # Check if expired
                if entry.is_expired():
                    del self.cache[key]
                    self.total_size -= entry.size
                    self.misses += 1
                    return None
                
                # Move to end (most recently used)
                self.cache.move_to_end(key)
                self.hits += 1
                return entry.get_value()
            
            self.misses += 1
            return None
    
    def set(self, key: str, value: Any, ttl: int = 3600, compress: bool = True) -> bool:
        """Set value in cache"""
        with self.lock:
            # Create new entry
            entry = CompressedCacheEntry(value, ttl, compress)
            
            # Check if key already exists
            if key in self.cache:
                old_entry = self.cache[key]
                self.total_size -= old_entry.size
            
            # Add to cache
            self.cache[key] = entry
            self.total_size += entry.size
            
            # Move to end (most recently used)
            self.cache.move_to_end(key)
            
            # Evict if needed
            self._evict_if_needed()
            
            return True
    
    def delete(self, key: str) -> bool:
        """Delete key from cache"""
        with self.lock:
            if key in self.cache:
                entry = self.cache[key]
                self.total_size -= entry.size
                del self.cache[key]
                return True
            return False
    
    def _evict_if_needed(self):
        """Evict entries if cache is full"""
        while len(self.cache) > self.max_size or self.total_size > (self.max_size * 1024):  # Rough size check
            if not self.cache:
                break
            
            # Remove least recently used
            key, entry = self.cache.popitem(last=False)
            self.total_size -= entry.size
            self.evictions += 1
    
    def clear_expired(self) -> int:
        """Clear expired entries"""
        with self.lock:
            expired_keys = []
            now = time.time()
            
            for key, entry in self.cache.items():
                if now > (entry.create_time + entry.ttl):
                    expired_keys.append(key)
            
            for key in expired_keys:
                entry = self.cache[key]
                self.total_size -= entry.size
                del self.cache[key]
            
            return len(expired_keys)
    
    def stats(self) -> Dict[str, Any]:
        """Get shard statistics"""
        with self.lock:
            hit_rate = self.hits / (self.hits + self.misses) if (self.hits + self.misses) > 0 else 0
            return {
                "shard_id": self.shard_id,
                "size": len(self.cache),
                "total_size_bytes": self.total_size,
                "hits": self.hits,
                "misses": self.misses,
                "evictions": self.evictions,
                "hit_rate": hit_rate,
                "max_size": self.max_size
            }
    
    def clear(self):
        """Clear entire shard"""
        with self.lock:
            self.cache.clear()
            self.total_size = 0
            self.hits = 0
            self.misses = 0
            self.evictions = 0


class BillionUserCache:
    """Main cache system for billions of users"""
    
    def __init__(self, config: Optional[CacheConfig] = None):
        self.config = config or CacheConfig()
        self.shards: List[ShardedLRUCache] = []
        self.shard_locks: List[threading.RLock] = []
        self.executor = ThreadPoolExecutor(max_workers=8)
        self._running = True  # Added for graceful shutdown
        
        # Shutdown events for background threads
        self._write_shutdown_event = threading.Event()
        self._stats_shutdown_event = threading.Event()
        self._cleanup_shutdown_event = threading.Event()
        
        # Initialize shards
        for i in range(self.config.shard_count):
            self.shards.append(ShardedLRUCache(i, self.config.max_shard_size))
            self.shard_locks.append(threading.RLock())
        
        # Statistics
        self.stats_lock = threading.RLock()
        self.operations = 0
        self.start_time = time.time()
        
        # Write-behind queue
        self.write_queue = []
        self.write_lock = threading.RLock()
        self.write_thread = None
        self.write_running = False
        
        # Start background tasks
        self._start_background_tasks()
    
    def _get_shard_index(self, key: str) -> int:
        """Get shard index for key using consistent hashing"""
        # Use MD5 hash for good distribution
        hash_bytes = hashlib.md5(key.encode('utf-8')).digest()
        hash_int = int.from_bytes(hash_bytes[:4], 'big')
        return hash_int % self.config.shard_count
    
    def get(self, key: str) -> Optional[Any]:
        """Get value from cache"""
        shard_idx = self._get_shard_index(key)
        
        with self.stats_lock:
            self.operations += 1
        
        return self.shards[shard_idx].get(key)
    
    def set(self, key: str, value: Any, ttl: Optional[int] = None, compress: Optional[bool] = None) -> bool:
        """Set value in cache"""
        shard_idx = self._get_shard_index(key)
        
        with self.stats_lock:
            self.operations += 1
        
        ttl = ttl or self.config.ttl_default
        compress = compress if compress is not None else self.config.compression_enabled
        
        return self.shards[shard_idx].set(key, value, ttl, compress)
    
    def delete(self, key: str) -> bool:
        """Delete key from cache"""
        shard_idx = self._get_shard_index(key)
        
        with self.stats_lock:
            self.operations += 1
        
        return self.shards[shard_idx].delete(key)
    
    def multi_get(self, keys: List[str]) -> Dict[str, Optional[Any]]:
        """Get multiple values efficiently"""
        results = {}
        
        # Group keys by shard
        shard_groups = defaultdict(list)
        for key in keys:
            shard_idx = self._get_shard_index(key)
            shard_groups[shard_idx].append(key)
        
        # Process each shard in parallel
        futures = {}
        for shard_idx, shard_keys in shard_groups.items():
            future = self.executor.submit(self._process_shard_get, shard_idx, shard_keys)
            futures[future] = shard_keys
        
        for future in futures:
            shard_results = future.result()
            for key, value in shard_results.items():
                results[key] = value
        
        with self.stats_lock:
            self.operations += len(keys)
        
        return results
    
    def _process_shard_get(self, shard_idx: int, keys: List[str]) -> Dict[str, Optional[Any]]:
        """Process get requests for a single shard"""
        results = {}
        shard = self.shards[shard_idx]
        
        for key in keys:
            results[key] = shard.get(key)
        
        return results
    
    def multi_set(self, items: Dict[str, Any], ttl: Optional[int] = None) -> Dict[str, bool]:
        """Set multiple values efficiently"""
        results = {}
        
        # Group items by shard
        shard_groups = defaultdict(dict)
        for key, value in items.items():
            shard_idx = self._get_shard_index(key)
            shard_groups[shard_idx][key] = value
        
        # Process each shard in parallel
        futures = {}
        for shard_idx, shard_items in shard_groups.items():
            future = self.executor.submit(self._process_shard_set, shard_idx, shard_items, ttl)
            futures[future] = shard_items.keys()
        
        for future in futures:
            shard_results = future.result()
            for key, success in shard_results.items():
                results[key] = success
        
        with self.stats_lock:
            self.operations += len(items)
        
        return results
    
    def _process_shard_set(self, shard_idx: int, items: Dict[str, Any], ttl: Optional[int]) -> Dict[str, bool]:
        """Process set requests for a single shard"""
        results = {}
        shard = self.shards[shard_idx]
        ttl = ttl or self.config.ttl_default
        
        for key, value in items.items():
            results[key] = shard.set(key, value, ttl, self.config.compression_enabled)
        
        return results
    
    def clear_expired(self) -> int:
        """Clear expired entries from all shards"""
        total_cleared = 0
        
        # Use shared executor
        futures = [self.executor.submit(shard.clear_expired) for shard in self.shards]
        
        for future in futures:
            total_cleared += future.result()
        
        return total_cleared
    
    def _start_background_tasks(self):
        """Start background maintenance tasks"""
        if self.config.write_behind_enabled:
            self.write_running = True
            self.write_thread = threading.Thread(target=self._write_behind_loop, daemon=True)
            self.write_thread.start()
        
        # Start stats collection thread
        if self.config.stats_collection_enabled:
            stats_thread = threading.Thread(target=self._stats_collection_loop, daemon=True)
            stats_thread.start()
        
        # Start cleanup thread
        cleanup_thread = threading.Thread(target=self._cleanup_loop, daemon=True)
        cleanup_thread.start()
    
    def _write_behind_loop(self):
        """Write-behind persistence loop"""
        while self.write_running and not self._write_shutdown_event.is_set():
            # Wait with timeout instead of blocking sleep
            if self._write_shutdown_event.wait(timeout=self.config.write_behind_interval):
                break  # Shutdown signaled
            
            try:
                self._flush_write_queue()
            except Exception as e:
                logger.error("Error in write-behind loop", exc_info=True)
    
    def _flush_write_queue(self):
        """Flush write queue to persistent storage"""
        with self.write_lock:
            if not self.write_queue:
                return
            
            # Process batch
            batch = self.write_queue[:self.config.write_behind_batch_size]
            self.write_queue = self.write_queue[self.config.write_behind_batch_size:]
            
            # Here you would write to database
            # For now, just clear the batch
            logger.info(f"Write-behind: Flushed {len(batch)} items")
    
    def _stats_collection_loop(self):
        """Collect and log statistics"""
        while self._running and not self._stats_shutdown_event.is_set():
            # Wait with timeout instead of blocking sleep
            if self._stats_shutdown_event.wait(timeout=self.config.stats_interval):
                break  # Shutdown signaled
            
            try:
                stats = self.get_stats()
                
                # Log if hit rate is low
                if stats['overall_hit_rate'] < self.config.target_hit_rate:
                    logger.warning(f"Warning: Cache hit rate low: {stats['overall_hit_rate']:.2%}")
                
                # Log memory usage
                memory_mb = stats['total_memory_mb']
                if memory_mb > self.config.max_memory_mb * 0.8:
                    logger.warning(f"Warning: Cache memory high: {memory_mb:.1f}MB")
                
            except Exception as e:
                logger.error("Error in stats collection", exc_info=True)
    
    def _cleanup_loop(self):
        """Background cleanup loop"""
        while self._running and not self._cleanup_shutdown_event.is_set():
            # Wait with timeout instead of blocking sleep
            if self._cleanup_shutdown_event.wait(timeout=300):  # 5 minutes
                break  # Shutdown signaled
            
            try:
                cleared = self.clear_expired()
                if cleared > 0:
                    logger.info(f"Cleanup: Cleared {cleared} expired entries")
            except Exception as e:
                logger.error("Error in cleanup loop", exc_info=True)
    
    def get_stats(self) -> Dict[str, Any]:
        """Get comprehensive cache statistics"""
        with self.stats_lock:
            total_hits = 0
            total_misses = 0
            total_size = 0
            total_entries = 0
            shard_stats = []
            
            for shard in self.shards:
                stats = shard.stats()
                shard_stats.append(stats)
                total_hits += stats['hits']
                total_misses += stats['misses']
                total_size += stats['total_size_bytes']
                total_entries += stats['size']
            
            uptime = time.time() - self.start_time
            ops_per_sec = self.operations / uptime if uptime > 0 else 0
            
            overall_hit_rate = total_hits / (total_hits + total_misses) if (total_hits + total_misses) > 0 else 0
            
            return {
                "uptime_seconds": uptime,
                "total_operations": self.operations,
                "operations_per_second": ops_per_sec,
                "total_entries": total_entries,
                "total_memory_mb": total_size / 1024 / 1024,
                "total_hits": total_hits,
                "total_misses": total_misses,
                "overall_hit_rate": overall_hit_rate,
                "shard_count": self.config.shard_count,
                "target_hit_rate": self.config.target_hit_rate,
                "max_memory_mb": self.config.max_memory_mb,
                "shard_stats": shard_stats
            }
    
    def shutdown(self):
        """Shutdown cache system gracefully"""
        self._running = False
        self.write_running = False
        
        # Signal shutdown events to wake up waiting threads
        self._write_shutdown_event.set()
        self._stats_shutdown_event.set()
        self._cleanup_shutdown_event.set()
        
        if self.write_thread:
            self.write_thread.join(timeout=5)
        
        # Flush remaining writes
        self._flush_write_queue()
        self.executor.shutdown(wait=True)
        
        logger.info("Cache system shutdown complete")


# Async-compatible wrapper
class AsyncBillionUserCache:
    """Async wrapper for billion user cache"""
    
    def __init__(self, cache: BillionUserCache):
        self.cache = cache
        self.executor = ThreadPoolExecutor(max_workers=32)
    
    async def get(self, key: str) -> Optional[Any]:
        """Async get"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.get, key)
    
    async def set(self, key: str, value: Any, ttl: Optional[int] = None, compress: Optional[bool] = None) -> bool:
        """Async set"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.set, key, value, ttl, compress)
    
    async def delete(self, key: str) -> bool:
        """Async delete"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.delete, key)
    
    async def multi_get(self, keys: List[str]) -> Dict[str, Optional[Any]]:
        """Async multi-get"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.multi_get, keys)
    
    async def multi_set(self, items: Dict[str, Any], ttl: Optional[int] = None) -> Dict[str, bool]:
        """Async multi-set"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.multi_set, items, ttl)
    
    async def get_stats(self) -> Dict[str, Any]:
        """Async get stats"""
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(self.executor, self.cache.get_stats)
    
    async def shutdown(self):
        """Async shutdown"""
        loop = asyncio.get_running_loop()
        await loop.run_in_executor(self.executor, self.cache.shutdown)
        self.executor.shutdown(wait=True)


# Factory function
def create_billion_user_cache(config: Optional[CacheConfig] = None) -> BillionUserCache:
    """Create and initialize billion user cache"""
    return BillionUserCache(config)


def create_async_billion_user_cache(config: Optional[CacheConfig] = None) -> AsyncBillionUserCache:
    """Create async billion user cache"""
    cache = create_billion_user_cache(config)
    return AsyncBillionUserCache(cache)


