# ═══ MODULE: system.load_monitor ═══

import os
import threading
import time
from collections import deque

_lock = threading.RLock()
_inflight_updates = 0
_recent_latencies: deque[float] = deque(maxlen=120)
_recent_starts: deque[float] = deque(maxlen=240)


def begin_update() -> float:
    now = time.time()
    with _lock:
        global _inflight_updates
        _inflight_updates += 1
        _recent_starts.append(now)
    return now


def end_update(started_at: float | None) -> None:
    ended_at = time.time()
    with _lock:
        global _inflight_updates
        _inflight_updates = max(0, _inflight_updates - 1)
        if started_at:
            _recent_latencies.append(max(0.0, ended_at - started_at))


def snapshot() -> dict[str, float | int | bool]:
    now = time.time()
    with _lock:
        latencies = list(_recent_latencies)
        fresh_starts = [item for item in _recent_starts if now - item <= 60]
        avg_latency = (sum(latencies) / len(latencies)) if latencies else 0.0
        updates_last_minute = len(fresh_starts)
        high = _inflight_updates >= 20 or updates_last_minute >= 150 or avg_latency >= 3.0
        return {
            "inflight": _inflight_updates,
            "avg_latency": round(avg_latency, 3),
            "updates_last_minute": updates_last_minute,
            "high_load": high,
        }


def context_window(normal: int = 20, reduced: int = 4) -> int:
    return reduced if snapshot()["high_load"] else normal

# ═══ MODULE: system.log_monitor ═══

"""
📝 Log Monitor & Auto-Error Checking System
Monitors logs every 3 minutes, auto-fixes errors, deletes logs when clean.
"""

import asyncio
import os
import time
from pathlib import Path

logger = get_logger(__name__)

# Log file paths
VERIFICATION_LOG = Path("data/runtime/verification.log")
ERROR_LOG = Path("bot_error_log.txt")
RUNTIME_LOG = Path("data/runtime/latest_run.log")

# Monitoring state
_error_count = 0
_last_check_time = 0
_consecutive_clean_checks = 0
_CLEAN_CHECKS_THRESHOLD = 3  # Stop after 3 consecutive clean checks


def _write_verification_log(message: str, level: str = "INFO") -> None:
    """Write to verification log."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    os.makedirs(VERIFICATION_LOG.parent, exist_ok=True)
    with open(VERIFICATION_LOG, "a", encoding="utf-8") as f:
        f.write(f"[{timestamp}] [{level}] {message}\n")


def _read_error_log() -> list[str]:
    """Read error log and return lines."""
    if not ERROR_LOG.exists():
        return []
    try:
        return ERROR_LOG.read_text(encoding="utf-8", errors="replace").splitlines()
    except Exception:
        logger.warning("Exception in _write_verification_log", exc_info=True)
        return []


def _read_runtime_log() -> list[str]:
    """Read runtime log and return recent lines."""
    if not RUNTIME_LOG.exists():
        return []
    try:
        lines = RUNTIME_LOG.read_text(encoding="utf-8", errors="replace").splitlines()
        return lines[-100:]  # Last 100 lines
    except Exception:
        logger.warning("Exception in _read_runtime_log", exc_info=True)
        return []


def _check_for_errors() -> tuple[int, list[str]]:
    """Check logs for errors and return (count, error_messages)."""
    errors = []

    # Check error log
    error_lines = _read_error_log()
    for line in error_lines:
        if any(keyword in line.lower() for keyword in ["error", "exception", "crash", "failed"]):
            errors.append(line)

    # Check runtime log
    runtime_lines = _read_runtime_log()
    for line in runtime_lines:
        if "ERROR" in line or "EXCEPTION" in line or "CRITICAL" in line:
            errors.append(line)

    return len(errors), errors


def _auto_fix_errors(errors: list[str]) -> list[str]:
    """Attempt to auto-fix common errors and return list of actions taken."""
    actions = []

    for error in errors:
        error_lower = error.lower()

        # Network timeout errors (non-critical)
        if any(kw in error_lower for kw in ["timeout", "timed out", "network"]):
            actions.append("⚠️ Network timeout detected - will auto-retry on next request")

        # Expired callback errors (normal behavior)
        if any(kw in error_lower for kw in ["query is too old", "query id is invalid", "expired"]):
            actions.append("✅ Expired callback (normal) - no action needed")

        # MongoDB connection errors
        if "mongo" in error_lower and "connection" in error_lower:
            actions.append("🔄 MongoDB connection error - attempting reconnect on next DB operation")

        # File not found errors
        if "file not found" in error_lower or "no such file" in error_lower:
            actions.append("📁 File missing detected - check if required files exist")

        # Permission errors
        if "permission" in error_lower and "denied" in error_lower:
            actions.append("🔒 Permission denied - check file/folder permissions")

    return actions


def _run_log_monitor_sync() -> None:
    """Synchronous body of run_log_monitor."""
    global _error_count, _last_check_time, _consecutive_clean_checks

    _last_check_time = time.time()

    try:
        _write_verification_log("🔍 Starting log check (3-minute interval)")
    except Exception as e:
        logger.warning("Failed to write verification log", exc_info=True)

    try:
        # Check for errors
        error_count, errors = _check_for_errors()
        _error_count = error_count

        if error_count > 0:
            _consecutive_clean_checks = 0
            for i, error in enumerate(errors[:10], 1):
                try:
                    _write_verification_log(f"  {i}. {error[:200]}", "ERROR")
                except Exception as e:
                    logger.warning("Failed to write error log", exc_info=True)
            try:
                actions = _auto_fix_errors(errors)
                for action in actions:
                    try:
                        _write_verification_log(f"  → {action}", "INFO")
                    except Exception as e:
                        logger.warning("Failed to write action log", exc_info=True)
            except Exception as e:
                logger.warning("Error during auto-fix", exc_info=True)
            try:
                _write_verification_log(f"📊 Total errors: {error_count} | Clean checks: {_consecutive_clean_checks}", "WARNING")
            except Exception as e:
                logger.warning("Failed to write summary log", exc_info=True)
        else:
            _consecutive_clean_checks += 1
            try:
                _write_verification_log(
                    f"✅ No errors found | Consecutive clean checks: {_consecutive_clean_checks}/3",
                    "INFO"
                )
            except Exception as e:
                logger.warning("Failed to write clean check log", exc_info=True)

            if _consecutive_clean_checks >= _CLEAN_CHECKS_THRESHOLD:
                try:
                    _write_verification_log(f"🎉 {_CLEAN_CHECKS_THRESHOLD} consecutive clean checks achieved! Cleaning up logs...", "INFO")
                    _cleanup_logs()
                    _write_verification_log("✅ Log monitoring complete - all errors resolved!", "INFO")
                except Exception as e:
                    logger.warning("Error during cleanup", exc_info=True)
                return

        try:
            _write_verification_log("⏳ Next check in 3 minutes\n", "INFO")
        except Exception as e:
            logger.warning("Failed to write next check log", exc_info=True)
    except Exception as e:
        logger.error("Unexpected error in run_log_monitor", exc_info=True)
        try:
            _write_verification_log(f"⚠️ Monitor error: {str(e)[:100]}", "ERROR")
        except Exception:
            logger.error("Unexpected error", exc_info=True)


async def run_log_monitor(context=None) -> None:
    """Run log monitor in thread to avoid blocking event loop."""
    await asyncio.to_thread(_run_log_monitor_sync)


def _cleanup_logs() -> None:
    """Delete all log files after successful verification."""
    log_files = [
        VERIFICATION_LOG,
        ERROR_LOG,
        RUNTIME_LOG,
        Path("bot_healing_log.txt"),
        Path("bot_startup.log"),
    ]

    deleted = []
    for log_file in log_files:
        if log_file.exists():
            try:
                log_file.unlink()
                deleted.append(log_file.name)
            except Exception as e:
                logger.warning("Failed to delete log file", exc_info=True)

    if deleted:
        logger.info(f"🗑️ Deleted log files: {', '.join(deleted)}")


def start_log_monitor(app) -> None:
    """Start log monitoring as a repeating job."""
    if app.job_queue:
        app.job_queue.run_repeating(
            run_log_monitor,
            interval=180,  # 3 minutes
            first=180,
            job_kwargs={"misfire_grace_time": None, "max_instances": 1},
        )
        logger.info("📝 Log monitor started (checks every 3 minutes)")
    else:
        logger.warning("⚠️ Job queue not available - log monitor disabled")


def get_monitor_status() -> dict:
    """Get current monitoring status."""
    return {
        "error_count": _error_count,
        "last_check_time": _last_check_time,
        "consecutive_clean_checks": _consecutive_clean_checks,
        "threshold": _CLEAN_CHECKS_THRESHOLD,
        "monitoring_active": _consecutive_clean_checks < _CLEAN_CHECKS_THRESHOLD,
    }

