def _safe_edit(q, *args, **kwargs):
    try:
        return q.edit_message_text(*args, **kwargs)
    except BadRequest as e:
        if "Message is not modified" in str(e):
            return None
        raise





# ============================================================================
# 📤 PENDING BROADCAST STATE
# ============================================================================
_pending_broadcasts: dict[int, dict] = {}
_broadcast_action_labels = {
    "broadcast_all": "🌐 Broadcast to All",
    "broadcast_users": "👤 Broadcast to Users",
    "broadcast_groups": "👥 Broadcast to Groups",
    "broadcast_channels": "📢 Broadcast to Channels",
    "broadcast_premium": "⭐ Broadcast to Premium",
}


async def check_pending_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> bool:
    """Check if owner has a pending broadcast; if so, capture text and start.
    Returns True if handled as broadcast."""
    user = update.effective_user
    chat = update.effective_chat
    msg = update.effective_message
    if not user or not chat or not msg or user.id != OWNER_ID:
        return False
    cid = chat.id
    pending = _pending_broadcasts.get(cid)
    if not pending:
        return False
    text = msg.text or msg.caption or ""
    if not text:
        return False
    btype = pending["type"]
    del _pending_broadcasts[cid]
    if manager.is_running():
        await msg.reply_text("⚠️ A broadcast is already running. Use /cancelbroadcast first.")
        return True
    label = _broadcast_action_labels.get(btype, btype)
    status_msg = await msg.reply_html(
        f"📤 <b>{label}</b>\n\n"
        f"Preparing broadcast..."
    )
    started = await manager.start_broadcast(ctx.bot, btype.replace("broadcast_", ""), text)
    if started:
        await status_msg.edit_text(
            f"🚀 <b>Broadcast Started</b>\n\n"
            f"📤 {label}\n"
            f"Check /broadcaststats for progress."
        )
    else:
        await status_msg.edit_text("⚠️ Failed to start broadcast.")
    return True


