START_TIME = time.time()
PANEL_HEADER = "👑 <b>MASTER CONTROL CENTER</b>"
PANEL_DIVIDER = "━" * 35

def _owner_guard(update: Update) -> bool:
    if update.effective_user and update.effective_user.id == OWNER_ID:
        return False
    return True

def _health_bar(value: float, width: int = 10) -> str:
    full = min(int(value / 100 * width), width)
    empty = width - full
    if full >= width * 0.8:
        color = "🟢"
    elif full >= width * 0.5:
        color = "🟡"
    else:
        color = "🔴"
    return f"{color} {'█' * full}{'░' * empty} {value:.0f}%"

def _health_icon(ok: bool) -> str:
    return "🟢" if ok else "🔴"

def _fmt_time(seconds: float) -> str:
    days, rem = divmod(int(seconds), 86400)
    hours, rem = divmod(rem, 3600)
    mins, secs = divmod(rem, 60)
    parts = []
    if days: parts.append(f"{days}d")
    if hours: parts.append(f"{hours}h")
    if mins: parts.append(f"{mins}m")
    parts.append(f"{secs}s")
    return " ".join(parts)

def _fmt_num(n: int) -> str:
    if n >= 1_000_000:
        return f"{n/1_000_000:.1f}M"
    if n >= 1_000:
        return f"{n/1_000:.1f}K"
    return str(n)


