async def _get_new_users_text() -> str:
    """Show recently registered users from TiDB."""
    try:
        pool = tidb_get_pool()
        now = int(time.time())
        day_ago = now - 86400
        week_ago = now - 604800
        day_count = 0
        week_count = 0
        recent = []
        for slot in pool.slots:
            if not slot.ok:
                continue
            conn = slot.get_conn()
            if not conn:
                continue
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT user_id, created_at, balance, username FROM users "
                    "WHERE created_at > %s ORDER BY created_at DESC LIMIT 20",
                    (day_ago,)
                )
                rows = cur.fetchall()
                for row in rows:
                    recent.append({
                        "uid": row.get("user_id", 0),
                        "created_at": row.get("created_at", 0),
                        "balance": row.get("balance", 0),
                        "username": row.get("username") or "",
                    })
                cur.execute("SELECT COUNT(*) AS cnt FROM users WHERE created_at > %s", (day_ago,))
                day_count += (cur.fetchone() or {}).get("cnt", 0) or 0
                cur.execute("SELECT COUNT(*) AS cnt FROM users WHERE created_at > %s", (week_ago,))
                week_count += (cur.fetchone() or {}).get("cnt", 0) or 0
        recent.sort(key=lambda x: x["created_at"], reverse=True)
        text = (
            f"🆕 <b>New Users</b>\n"
            f"{PANEL_DIVIDER}\n\n"
            f"📊 Last 24h: <b>{day_count:,}</b>\n"
            f"📊 Last 7d:  <b>{week_count:,}</b>\n\n"
            f"─── LATEST 20 ───\n"
        )
        for u in recent[:20]:
            ts = u["created_at"]
            age = _fmt_time(now - ts) if ts else "?"
            name = f"@{u['username']}" if u["username"] else f"ID:{u['uid']}"
            text += f"  • <code>{u['uid']}</code> {name} — ${u['balance']:,} ({age} ago)\n"
        if not recent:
            text += "  No new users in last 24h\n"
        return text
    except Exception:
        logger.error("New users error", exc_info=True)
        return f"{PANEL_HEADER}\n{PANEL_DIVIDER}\n⚠️ Could not fetch new users"

async def _get_models_text() -> str:
    """Show AI provider/model status from router."""
    try:
        status = await asyncio.to_thread(get_all_model_status)
        text = (
            f"🤖 <b>AI Model Status</b>\n"
            f"{PANEL_DIVIDER}\n\n"
        )
        for provider, info in status.items():
            if provider == "priority_order" or provider == "recent_errors":
                continue
            if not isinstance(info, dict):
                continue
            available = info.get("available", False)
            icon = "🟢" if available else "🔴"
            model = info.get("model") or info.get("models", ["?"])
            if isinstance(model, list):
                model = ", ".join(model[:2])
            s = info.get("status", {})
            if isinstance(s, dict):
                used = s.get("usage_today", "?")
                limit = s.get("daily_limit", "∞")
                cooldown = s.get("cooldown_until", 0)
                cd = _fmt_time(cooldown - time.time()) if cooldown > time.time() else "ready"
                text += f"{icon} <b>{provider.title()}</b> — {model}\n"
                text += f"     Used: {used}/{limit} | Status: {cd}\n"
            else:
                text += f"{icon} <b>{provider.title()}</b> — {model}\n"
        priority = status.get("priority_order", [])
        if priority:
            text += f"\n─── PRIORITY ───\n"
            text += f"  {' → '.join(priority[:5])}"
            if len(priority) > 5:
                text += f" +{len(priority)-5} more"
        recent_errors = status.get("recent_errors", [])
        if recent_errors:
            text += f"\n\n⚠️ <b>Recent Errors:</b>\n"
            for err in recent_errors[-3:]:
                text += f"  • <code>{html.escape(str(err)[:80])}</code>\n"
        return text
    except Exception:
        logger.error("Models status error", exc_info=True)
        return f"{PANEL_HEADER}\n{PANEL_DIVIDER}\n⚠️ Could not load model status"

