# ============================================================================
# 🩺 HEALTH CHECK
# ============================================================================
async def _get_health_report() -> str:
    """Comprehensive subsystem health check with real metrics."""
    try:
        stats = await asyncio.to_thread(database_stats)
        storage = await asyncio.to_thread(get_storage_status)
        load = load_snapshot()
        slot_mgr = get_slot_manager()
        smart_status = slot_mgr.get_slot_status()
        failover = get_failover_status()
        sys_load = load

        lines = [f"{PANEL_HEADER}", f"{PANEL_DIVIDER}",
                f"🩺 <b>SYSTEM HEALTH CHECK</b>\n"]

        cpu = sys_load.get('cpu', 0)
        memory = sys_load.get('memory', 0)
        disk = sys_load.get('disk', 0)
        inflight = load.get('inflight', 0)
        avg_lat = load.get('avg_latency', 0)
        updates_min = load.get('updates_last_minute', 0)
        uptime = int(time.time() - START_TIME)
        h, r = divmod(uptime, 3600)
        m, s = divmod(r, 60)

        lines.append(f"💻 <b>Server</b>")
        lines.append(f"  CPU:  {_health_bar(cpu) if cpu else 'N/A'}")
        lines.append(f"  RAM:  {_health_bar(memory) if memory else 'N/A'}")
        lines.append(f"  DISK: {_health_bar(disk) if disk else 'N/A'}")
        lines.append(f"  ⚡ Inflight: <b>{inflight}</b>  |  Latency: <b>{avg_lat*1000:.0f}ms</b>")
        lines.append(f"  📈 Updates/min: <b>{updates_min}</b>  |  {'🟢 Normal' if not load.get('high_load') else '🔴 High Load'}")
        lines.append(f"  ⏱ Uptime: <code>{h}h {m}m {s}s</code>\n")

        mongo_slots = storage.get('mongo_slots', [])
        active = storage.get('active_mongo_slot', 'None')
        db_ok = len(mongo_slots) > 0 and active != 'None'
        lines.append(f"🗄️ <b>Database</b>")
        lines.append(f"  Status: {_health_icon(db_ok)} {'Connected' if db_ok else 'Disconnected'}")
        lines.append(f"  Active: <b>P{active}</b>  |  Slots: <b>{len(mongo_slots)}</b>")
        lines.append(f"  Mode: <b>{stats.get('mode', '?')}</b>  |  Cache: <b>{stats.get('cache_size', 0):,}</b>\n")

        lines.append(f"📦 <b>Smart Slots (P1-P7)</b>")
        for slot in smart_status['slots']:
            state = slot['state']
            healthy = state in ('available', 'active')
            icon = _health_icon(healthy)
            wait = " ⏳" if slot['waiting'] else ""
            sync = " 🔄" if slot['syncing'] else ""
            lines.append(f"  {icon} <b>{slot['name']}</b>: {state}{wait}{sync}")
        lines.append("")

        level = failover.get('current_level', 0)
        recovering = failover.get('is_recovering', False)
        lines.append(f"🛡️ <b>Failover</b>")
        lines.append(f"  Level: <b>{level}</b>  |  Recovering: {'🟢 Yes' if recovering else '⚫ No'}")
        lines.append(f"  Slots tracked: <b>{len(failover.get('slots', {}))}</b>")

        alerts = storage.get('alerts', [])
        if alerts:
            lines.append(f"\n⚠️ <b>Alerts ({len(alerts)})</b>")
            for alert in alerts[:5]:
                lines.append(f"  └ {html.escape(str(alert)[:80])}")

        lines.append(f"\n{PANEL_DIVIDER}")
        all_healthy = db_ok and (not cpu or cpu < 90) and (not memory or memory < 90) and not load.get('high_load')
        lines.append(f"Overall: {_health_icon(all_healthy)} {'All systems healthy' if all_healthy else 'Issues detected'}")
        return "\n".join(lines)

    except Exception:
        logger.error("Health check error", exc_info=True)
        return f"{PANEL_HEADER}\n{PANEL_DIVIDER}\n⚠️ Health check failed"


# ============================================================================
# 💰 ECONOMY REPORT
# ============================================================================
async def _get_economy_report() -> str:
    """Global economy overview from real user data."""
    try:
        all_users = await asyncio.to_thread(list_all_users)

        total_balance = 0
        total_captures = 0
        total_rp = 0
        total_income = 0
        total_spent = 0
        premium_count = 0
        bal_10k = bal_1k = bal_100 = 0
        now = int(time.time())
        user_count = 0

        for uid, data in all_users:
            if not isinstance(data, dict) or not data:
                continue
            user_count += 1
            bal = data.get('balance', 0) or 0
            total_balance += bal
            total_captures += data.get('captures', 0) or 0
            total_rp += data.get('rp', 0) or 0
            total_income += data.get('total_income', 0) or 0
            total_spent += data.get('total_spent', 0) or 0
            if data.get('premium_until', 0) > now:
                premium_count += 1
            if bal >= 10000:
                bal_10k += 1
            elif bal >= 1000:
                bal_1k += 1
            elif bal >= 100:
                bal_100 += 1

        avg_balance = total_balance // max(user_count, 1)

        return (
            f"{PANEL_HEADER}\n"
            f"{PANEL_DIVIDER}\n"
            f"💰 <b>GLOBAL ECONOMY</b>\n\n"
            f"👥 <b>Users tracked:</b> {user_count:,}\n"
            f"💎 <b>Premium:</b> {premium_count:,}\n\n"
            f"💵 <b>Total Balance:</b> <code>${total_balance:,}</code>\n"
            f"📊 <b>Avg Balance:</b> <code>${avg_balance:,}</code>\n"
            f"📸 <b>Total Captures:</b> <code>{total_captures:,}</code>\n"
            f"🎭 <b>Total RP:</b> <code>{total_rp:,}</code>\n"
            f"📈 <b>Total Income:</b> <code>${total_income:,}</code>\n"
            f"📉 <b>Total Spent:</b> <code>${total_spent:,}</code>\n\n"
            f"─── WEALTH DISTRIBUTION ───\n"
            f"💰 $10K+: <b>{bal_10k:,}</b>\n"
            f"💰 $1K+:  <b>{bal_1k:,}</b>\n"
            f"💰 $100+: <b>{bal_100:,}</b>\n"
        )
    except Exception:
        logger.error("Economy report error", exc_info=True)
        return f"{PANEL_HEADER}\n{PANEL_DIVIDER}\n⚠️ Economy data unavailable"


