# ============================================================================
# 📈 ACTIVITY REPORT
# ============================================================================
async def _get_activity_report() -> str:
    """Activity and growth overview from real data."""
    try:
        stats = await asyncio.to_thread(database_stats)
        all_users = await asyncio.to_thread(list_all_users)

        total = len(all_users)
        now = int(time.time())
        last_day = last_week = last_month = 0
        for _, d in all_users:
            if not isinstance(d, dict):
                continue
            ls = d.get('last_seen', 0) or 0
            if ls > now - 86400:
                last_day += 1
            if ls > now - 604800:
                last_week += 1
            if ls > now - 2592000:
                last_month += 1

        groups = stats.get("groups", 0)
        channels = stats.get("channels", 0)
        total_chats = stats.get("registered_chats", 0)
        dms = stats.get("dm_users", 0)

        da_pct = last_day * 100 // max(total, 1)
        wa_pct = last_week * 100 // max(total, 1)

        bar_day = "█" * (da_pct * 10 // 100) if da_pct else "░"
        bar_week = "█" * (wa_pct * 10 // 100) if wa_pct else "░"

        return (
            f"{PANEL_HEADER}\n"
            f"{PANEL_DIVIDER}\n"
            f"📈 <b>ACTIVITY & GROWTH</b>\n\n"
            f"👥 <b>User Activity</b>\n"
            f"  ├ Last 24h: <b>{last_day:,}</b>\n"
            f"  ├ Last Week: <b>{last_week:,}</b>\n"
            f"  ├ Last Month: <b>{last_month:,}</b>\n"
            f"  └ Total: <b>{total:,}</b>\n\n"
            f"─── ENGAGEMENT ───\n"
            f"  Daily:  {bar_day} <b>{da_pct}%</b>\n"
            f"  Weekly: {bar_week} <b>{wa_pct}%</b>\n\n"
            f"📊 <b>Chat Distribution</b>\n"
            f"  👥 Groups: <b>{groups:,}</b>\n"
            f"  📢 Channels: <b>{channels:,}</b>\n"
            f"  💬 DMs: <b>{dms:,}</b>\n"
            f"  └ Total: <b>{total_chats:,}</b>\n\n"
            f"─── GROWTH ───\n"
            f"  📈 Use /stats for detailed metrics\n"
            f"  📊 Use /userinfo for user details"
        )
    except Exception:
        logger.error("Activity report error", exc_info=True)
        return f"{PANEL_HEADER}\n{PANEL_DIVIDER}\n⚠️ Activity data unavailable"


