async def _handle_action(action_type: str, update: Update, ctx: ContextTypes.DEFAULT_TYPE, path: list = None):
    q = update.callback_query
    path = path or []
    
    if action_type.startswith("exec:"):
        action = action_type.split(":", 1)[1]
        
        if action == "flush_cache":
            try:
                loop = asyncio.get_running_loop()
                count = await loop.run_in_executor(None, flush_cache)
                await q.answer(f"✅ Flushed {count} users", show_alert=True)
            except Exception as e:
                await q.answer(f"⚠️ Error: {e}", show_alert=True)
                
        elif action == "reset_ai":
            await asyncio.to_thread(save_setting, "global_ai", "on")
            await q.answer("✅ AI Reset to Online", show_alert=True)
            
        elif action == "refresh_slots":
            await asyncio.to_thread(refresh_storage_slots)
            await q.answer("✅ Storage slots refreshed", show_alert=True)
            
        elif action == "gen_backup":
            await q.answer("📦 Generating backup...", show_alert=True)
            try:
                await asyncio.to_thread(generate_backup, ctx.bot, kind="manual_full")
                await q.answer("✅ Backup complete!", show_alert=True)
            except Exception as e:
                await q.answer(f"⚠️ Error: {e}", show_alert=True)
                
        elif action == "on_ai":
            await asyncio.to_thread(save_setting, "global_ai", "on")
            count = await _update_all_groups_ai_setting(True)
            await q.answer(f"✅ AI enabled (updated {count} groups)", show_alert=True)
            
        elif action == "off_ai":
            await asyncio.to_thread(save_setting, "global_ai", "off")
            count = await _update_all_groups_ai_setting(False)
            await q.answer(f"🚫 AI disabled (updated {count} groups)", show_alert=True)
            
        elif action == "on_games":
            await asyncio.to_thread(save_setting, "global_game", "on")
            await q.answer("✅ Games enabled", show_alert=True)
            
        elif action == "off_games":
            await asyncio.to_thread(save_setting, "global_game", "off")
            await q.answer("🚫 Games disabled", show_alert=True)

        elif action == "on_dm":
            for key in ("stopdm", "stopdm_capture", "stopdm_bounty", "stopdm_broadcast"):
                await asyncio.to_thread(save_setting, key, "")
            await q.answer("✅ DMs opened for all users", show_alert=True)
            
        elif action == "off_dm":
            await asyncio.to_thread(save_setting, "stopdm", "on")
            for key in ("stopdm_capture", "stopdm_bounty", "stopdm_broadcast"):
                await asyncio.to_thread(save_setting, key, "on")
            await q.answer("🚫 DMs closed for all users", show_alert=True)
            
        elif action == "on_bot":
            await asyncio.to_thread(save_setting, "global_ai", "on")
            await asyncio.to_thread(save_setting, "global_game", "on")
            for key in ("stopdm", "stopdm_capture", "stopdm_bounty", "stopdm_broadcast"):
                await asyncio.to_thread(save_setting, key, "")
            await asyncio.to_thread(save_setting_json, "bot_off_categories", [])
            await q.answer("✅ Bot fully activated", show_alert=True)
            
        elif action == "off_bot":
            await asyncio.to_thread(save_setting_json, "bot_off_categories", ["all"])
            await q.answer("💤 Bot set to maintenance mode", show_alert=True)
            
        elif action.startswith("reset_"):
            _target = action.replace("reset_", "")
            confirm_d = "rst_confirm:" + _target
