async def ownerpanel(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if _owner_guard(update): return
    
    if "own_path" not in ctx.user_data:
        ctx.user_data["own_path"] = []
    
    text = await _get_dashboard_summary()
    await update.effective_message.reply_html(text, reply_markup=get_keyboard([]))

async def owner_panel_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not q:
        return
    if q.from_user.id != OWNER_ID:
        return await q.answer("Owner only.")
    
    data = q.data
    if data == "ownerpanel":
        text = await _get_dashboard_summary()
        await _safe_edit(q, text, reply_markup=get_keyboard([]), parse_mode="HTML")
        await q.answer()
        return
        
    if data == "own_close":
        await q.answer("Closing...")
        ctx.user_data.pop("own_path", None)
        try:
            if q.message:
                await q.message.delete()
        except Exception:
            logger.debug("Failed to delete owner panel message")
        return

    if data.startswith("rst_confirm:"):
        _target = data.split(":", 1)[1]
        await q.answer(f"♻️ Resetting {_target}...", show_alert=False)
        await _safe_edit(q, f"♻️ <b>Resetting {_target}...</b>", parse_mode="HTML")
        result = await asyncio.to_thread(reset_user_data, [_target])
        fields_display = ", ".join(result.get("fields", [])) or _target
        extras = ""
        if result.get("backed_up", 0):
            extras = f"\n🔐 Backed up: <b>{result['backed_up']}</b>"
        await _safe_edit(q, 
            f"♻️ <b>Reset Complete</b>\n\n"
            f"📋 Fields: <b>{fields_display}</b>\n"
            f"📊 Total users: <b>{result['total']}</b>\n"
            f"✅ Updated: <b>{result['updated']}</b>\n"
            f"❌ Errors: <b>{result['errors']}</b>{extras}\n\n"
            f"<i>Identity fields preserved.\n"
            f"Data reset via $set on existing docs.</i>",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Back", callback_data="own_nav:rgh")]]),
            parse_mode="HTML"
        )
        return

    if data.startswith("own_nav:"):
        path_str = data.split(":")[1]
        compressed_path = [k for k in (path_str.split("|") if path_str else []) if k]
        path = [KEY_MENU_MAP.get(key, key) for key in compressed_path]
        
        logger.debug(f"Owner Panel Nav: User {q.from_user.id} Path: {compressed_path}")
        
        # Traverse to find the current node
        current_node = MENU_STRUCTURE
        for key in path:
            if key in current_node:
                current_node = current_node[key]
                if "children" in current_node:
                    current_node = current_node["children"]
                else:
                    break
        
        if not path:
            await q.answer()
            text = await _get_dashboard_summary()
            await _safe_edit(q, text, reply_markup=get_keyboard([]), parse_mode="HTML")
            return

        item_key = path[-1]
        parent_node = MENU_STRUCTURE
        for key in path[:-1]:
            if key in parent_node:
                parent_node = parent_node[key]
                if "children" in parent_node:
                    parent_node = parent_node["children"]
        
        if not path[:-1]:
            parent_node = MENU_STRUCTURE
        
        item = parent_node.get(item_key)
        if not item:
            await q.answer("Item not found")
            return

        if item.get("is_action"):
            desc = item.get("description", "No description available.")
            action_type = item.get("action_type")
            
            if action_type:
                await _handle_action(action_type, update, ctx, path)
            else:
                await _safe_edit(q, desc, reply_markup=get_keyboard(path), parse_mode="HTML")
                await q.answer()
        else:
            desc = item.get("description", "Select a sub-category.")
            await _safe_edit(q, f"<b>{item['label']}</b>\n\n{desc}", reply_markup=get_keyboard(path), parse_mode="HTML")
            await q.answer()
        return

    await q.answer()

