async def clear_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.from_user or q.from_user.id != OWNER_ID:
        if q:
            await q.answer("Owner only.", show_alert=True)
        return
    data = (q.data or "").replace("wipe:", "")
    valid = {"users", "settings", "runtime", "stickers", "backups",
            "balance", "economy", "chats", "bans", "games", "premium", "all"}
    if data not in valid:
        await q.answer("Unknown wipe target.")
        return
    try:
        await asyncio.to_thread(clear_all_data, data)
        await q.answer(f"✅ Wiped: {data}", show_alert=True)
        await _safe_edit(q, f"✅ <b>Wipe complete:</b> <code>{data}</code>", parse_mode="HTML")
    except Exception as exc:
        await q.answer(f"Error: {html.escape(str(exc))[:80]}", show_alert=True)

