from telegram import Update
from telegram.ext import ContextTypes
from pymongo import MongoClient
async def checkpool(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show all GIFs in a pool. /checkpool [slap/smash/bites/kiss]"""
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    action = (ctx.args or [""])[0].lower() if ctx.args else ""
    VALID = ["slap", "smash", "bites", "kiss"]
    if action not in VALID:
        return await msg.reply_html(
            f"⚠️ Usage: /checkpool [{'|'.join(VALID)}]\n"
            "Shows all GIFs/animations in that pool with serial numbers."
        )

    data = await asyncio.to_thread(get_sticker_setting, f"gif_{action}") or {}
    pool = data.get("pool", [])
    if not pool and data.get("file_id"):
        pool = [data["file_id"]]
    if not pool:
        return await msg.reply_html(f"📭 No GIFs in <b>/{action}</b> pool yet.")

    lines = [f"🎬 <b>/{action}</b> Pool ({len(pool)} GIFs)\n"]
    for i, fid in enumerate(pool, 1):
        lines.append(f"  {i}. <code>{fid[:20]}...</code>")
    lines.append(f"\n🗑 Use /deletepool {action} to clear all")
    lines.append(f"🗑 Use /deletespecific {action} [number] to delete one")
    await msg.reply_html("\n".join(lines))

async def deletepool(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Delete all GIFs from a pool."""
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    action = (ctx.args or [""])[0].lower() if ctx.args else ""
    VALID = ["slap", "smash", "bites", "kiss"]
    if action not in VALID:
        return await msg.reply_html(
            f"⚠️ Usage: /deletepool [{'|'.join(VALID)}]\n"
            "Deletes all GIFs from that pool."
        )
    
    await asyncio.to_thread(save_sticker_setting, f"gif_{action}", {"pool": []})
    await msg.reply_html(f"🗑️ <b>/{action}</b> pool cleared.")

async def deletespecific(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Delete a specific GIF from a pool by number."""
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    if len(ctx.args) < 2:
        return await msg.reply_html(
            "⚠️ Usage: /deletespecific [action] [number]\n"
            f"Example: /deletespecific slap 3"
        )
    action = ctx.args[0].lower()
    try:
        number = int(ctx.args[1])
    except ValueError:
        return await msg.reply_text("⚠️ Invalid number.")
    
    VALID = ["slap", "smash", "bites", "kiss"]
    if action not in VALID:
        return await msg.reply_html(f"⚠️ Valid actions: {', '.join(VALID)}")
    
    
    data = await asyncio.to_thread(get_sticker_setting, f"gif_{action}") or {}
    pool = data.get("pool", [])
    if not pool:
        return await msg.reply_html(f"📭 No GIFs in <b>/{action}</b> pool.")
    
    if number < 1 or number > len(pool):
        return await msg.reply_text(f"⚠️ Invalid number. Pool has {len(pool)} GIFs.")
    
    pool.pop(number - 1)
    data["pool"] = pool
    await asyncio.to_thread(save_sticker_setting, f"gif_{action}", data)
    await msg.reply_html(f"🗑️ Deleted GIF #{number} from <b>/{action}</b> pool.")

async def addmongo(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Add a new MongoDB URI. Usage: /addmongo <url> [category]
    category = hot | archive | state | logs | admin | general (default: hot)
    New slot auto-routes overflow users when earlier slots fill up.
    """
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    if not MONGO_ENABLED:
        return await msg.reply_text(
            "ℹ️ MongoDB is OFF in this build (TiDB-only store) — /addmongo is unavailable."
        )
    if not ctx.args:
        return await msg.reply_html(
            "⚠️ <b>Usage:</b> /addmongo [url] [category]\n"
            "Categories: <code>hot</code> (active users) | <code>archive</code> (old users) | "
            "<code>state</code> | <code>admin</code> | <code>general</code>\n"
            "Example: /addmongo mongodb+srv://... hot"
        )
    try:
        url = ctx.args[0]
        category = ctx.args[1].lower() if len(ctx.args) > 1 else "hot"
        valid_cats = ("hot", "archive", "state", "logs", "admin", "general")
        if category not in valid_cats:
            return await msg.reply_text(f"⚠️ Category must be one of: {', '.join(valid_cats)}")
        if not url.startswith("mongodb"):
            return await msg.reply_text("⚠️ Invalid MongoDB URL. Must start with 'mongodb'")

        # Test connection first
        await msg.reply_html("⏳ <b>Testing connection...</b>")
        try:
            def _test_mongo():
                client = MongoClient(url, serverSelectionTimeoutMS=8000)
                try:
                    client.server_info()
                finally:
                    client.close()
            await asyncio.to_thread(_test_mongo)
        except Exception as e:
            logger.error("Unexpected error", exc_info=True)
            return await msg.reply_html(f"⚠️ <b>Connection failed:</b> <code>{html.escape(str(e)[:200])}</code>")

        # Add slot
            entry = await asyncio.to_thread(
            add_mongo_slot, url, MONGO_DB_NAME, 512, category
        )

        # Get updated status
        storage = await asyncio.to_thread(get_storage_status)
        total_slots = len(storage.get('available_mongo_slots', []))

        await msg.reply_html(
            f"✅ <b>Mᴏɴɢᴏ Sʟᴏᴛ Aᴅᴅᴇᴅ</b>\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"Slot: <b>P{total_slots}</b>\n"
            f"Category: <b>{category}</b>\n"
            f"URL: <code>{url[:35]}...</code>\n"
            f"Total Slots: <b>{total_slots}</b>\n\n"
            f"<i>New/overflow users will auto-route to this slot when earlier slots fill up.</i>"
        )
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error: {str(exc)[:300]}")

async def dbstatus(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Detailed status of the DB sharding network."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    storage = await asyncio.to_thread(get_storage_status)

    # Header
    text = "🗄️ <b>Dᴀᴛᴀʙᴀsᴇ Sᴛᴀᴛᴜs</b>\n"
    text += "━━━━━━━━━━━━━━━━━━━━━━\n"
    text += f"Active User Slot: <b>P{storage.get('active_mongo_slot', '?')}</b>\n"
    text += f"Relay Store: <b>{storage.get('host_relay', {}).get('users', 0)} users buffered</b>\n\n"

    # Per-slot Mongo
    text += "<b>Mᴏɴɢᴏ Sʟᴏᴛs:</b>\n"
    for slot in storage.get('mongo_slots', []):
        sid = slot['slot_id']
        ok = slot.get('ok')
        full = slot.get('full')
        pct = slot.get('usage_percent', 0)
        cat = slot.get('category', 'general')
        src = "👑" if slot.get('source') == 'owner' else "⚙️"

        if not ok:
            icon = "⚠️"
        elif full:
            icon = "🔴"
        elif pct >= 80:
            icon = "🟡"
        else:
            icon = "🟢"

        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        text += f"  {src} <b>P{sid}</b> [{cat}] {icon}\n"
        text += f"     {bar} {pct}%\n"

    # Auto-routing info
    active_by_purpose = storage.get('active_by_purpose', {})
    text += "\n<b>Aᴜᴛᴏ Rᴏᴜᴛɪɴɢ:</b>\n"
    for purpose, slot_id in active_by_purpose.items():
        text += f"  {purpose}: → <b>P{slot_id}</b>\n"

    # Health & Budget summary
    try:
        limit_report = await asyncio.to_thread(full_limit_report)
        text += "\n<b>Bᴜᴅɢᴇᴛ:</b>\n"
        for line in limit_report.split("\n")[:5]:
            text += f"  {line}\n"
    except Exception:
        text += "\n<b>Bᴜᴅɢᴇᴛ:</b> unavailable\n"

    try:
        health = await asyncio.to_thread(quick_health_summary)
        text += f"\n<b>Hᴇᴀʟᴛʜ:</b> {health}\n"
    except Exception:
        text += "\n<b>Hᴇᴀʟᴛʜ:</b> unavailable\n"

    # Advanced metrics
    try:
        adv = await asyncio.to_thread(get_db_metrics)
        cb = adv.get("circuit_breaker", {})
        cache = adv.get("cache", {})
        text += "\n<b>Aᴅᴠᴀɴᴄᴇᴅ Mᴇᴛʀɪᴄs:</b>\n"
        text += f"  Cache: <b>{cache.get('users', 0):,}</b> users | <b>{cache.get('settings', 0)}</b> settings\n"
        text += f"  Sub-DB clients cached: <b>{len(_extra_sub_clients)}</b>\n"
        if cb:
            open_keys = [k for k, v in cb.items() if v.get("is_open")]
            if open_keys:
                text += f"  ⚠️ Circuit breaker OPEN: <code>{', '.join(open_keys[:5])}</code>\n"
            else:
                text += f"  Circuit breaker: ✅ all closed ({len(cb)} tracked)\n"
        # Show top 3 hot op metrics
        metrics = adv.get("metrics", {})
        if metrics:
            top = sorted(metrics.items(), key=lambda kv: -kv[1].get("ops", 0))[:3]
            if top:
                text += "  Top ops:\n"
                for key, m in top:
                    text += f"    <code>{key}</code>: {m['ops']:,} ops, p99={m['p99_ms']}ms\n"
    except Exception as exc:
        logger.debug(f"dbstatus advanced metrics failed: {exc}")

    # Alerts
    alerts = storage.get('alerts', [])
    if alerts:
        text += f"\n⚠️ <b>{len(alerts)} storage alert(s)</b> — use /clearalerts to dismiss."

    text += f"\n\n<i>Use /addmongo [url] [category] to add more slots.</i>"
    await msg.reply_html(text)

