async def tidbflush(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Manually flush TiDB dirty writes, last_seen, and increment buffers."""
    if update.effective_user.id != OWNER_ID:
        return


    msg = update.effective_message
    dirty = await asyncio.to_thread(tidb_flush_dirty)
    ls = await asyncio.to_thread(tidb_flush_last_seen)
    bal = await asyncio.to_thread(tidb_flush_balance, True)
    inc = await asyncio.to_thread(tidb_flush_increments)
    stats = await asyncio.to_thread(tidb_flush_stats)
    await msg.reply_html(
        f"⚡ <b>TiDB Sᴍᴀʀᴛ Fʟᴜsʜ</b>\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"Balance delta: <b>{bal}</b> coalesced writes\n"
        f"Increments:    <b>{inc}</b> batched flushes\n"
        f"Dirty writes:  <b>{dirty}</b> users flushed\n"
        f"last_seen:     <b>{ls}</b> updates flushed\n"
        f"Stats:         <b>{stats}</b> batched stats\n"
        f"{'─' * 22}\n"
        f"✅ All TiDB buffers cleared."
    )

