async def dbmetrics(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show advanced DB metrics: query latencies, error rates, circuit breaker."""
    if update.effective_user.id != OWNER_ID:
        return

    metrics = await asyncio.to_thread(get_db_metrics)

    msg = update.effective_message
    text = "📊 <b>Aᴅᴠᴀɴᴄᴇᴅ DB Mᴇᴛʀɪᴄs</b>\n"
    text += "━━━━━━━━━━━━━━━━━━━━━━\n"

    # TiDB
    tidb = metrics.get("tidb", {})
    text += f"  TiDB: {'✅' if tidb.get('available') else '❌'} "
    text += f"({tidb.get('priority', '?')})\n"

    # Cache
    cache = metrics.get("cache", {})
    text += f"  Cache: <b>{cache.get('users', 0):,}</b> users | "
    text += f"<b>{cache.get('settings', 0)}</b> settings | "
    text += f"<b>{cache.get('leaderboard', 0)}</b> lb\n"

    # Circuit breaker
    cb = metrics.get("circuit_breaker", {})
    text += f"\n<b>Cɪʀᴄᴜɪᴛ Bʀᴇᴀᴋᴇʀ:</b>\n"
    if not cb:
        text += "  No failed slots tracked\n"
    else:
        for key, v in cb.items():
            if v.get("is_open"):
                text += f"  🔴 <code>{key}</code> OPEN until {v.get('open_until', 0):.0f}\n"
            elif v.get("failures", 0) > 0:
                text += f"  🟡 <code>{key}</code> {v.get('failures', 0)} failures in window\n"
            else:
                text += f"  🟢 <code>{key}</code> ok\n"

    # Query metrics — top 10 by volume
    q = metrics.get("metrics", {})
    if q:
        text += f"\n<b>Tᴏᴘ Qᴜᴇʀɪᴇs (by volume):</b>\n"
        top = sorted(q.items(), key=lambda kv: -kv[1].get("ops", 0))[:10]
        for key, m in top:
            err = m.get("errors", 0)
            err_str = f" ❌{err}" if err else ""
            text += f"  <code>{key}</code>{err_str}\n"
            text += f"    ops: {m['ops']:,} | p50={m['p50_ms']}ms p95={m['p95_ms']}ms p99={m['p99_ms']}ms | err: {m['error_rate']}\n"
    else:
        text += "\n<b>Qᴜᴇʀɪᴇs:</b> no metrics yet\n"

    # Slot summary
    slots = metrics.get("slots", [])
    if slots:
        text += f"\n<b>Sʟᴏᴛs ({len(slots)}):</b>\n"
        for s in slots[:10]:
            sid = s.get("slot_id", "?")
            ok = "🟢" if s.get("ok") else "🔴"
            pct = s.get("usage_percent", 0)
            text += f"  {ok} P{sid} [{s.get('category', '?')}] {pct}%\n"

    text += f"\n<i>Use /dbresetmetrics to clear counters.</i>"
    await msg.reply_html(text)


