async def dbcircuit(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """View or reset circuit breaker state. Usage:
    /dbcircuit — show all breakers
    /dbcircuit reset [slot_key] — reset specific slot
    /dbcircuit resetall — reset all"""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message

    args = ctx.args or []
    if args and args[0].lower() == "resetall":
        await asyncio.to_thread(_circuit_breaker.reset, "__reset_all__")
        # Reset all tracked keys
        for key in list(_circuit_breaker.status().keys()):
            await asyncio.to_thread(_circuit_breaker.reset, key)
        await msg.reply_html("🔄 <b>All circuit breakers reset.</b>")
        return

    if args and args[0].lower() == "reset" and len(args) > 1:
        key = args[1]
        await asyncio.to_thread(_circuit_breaker.reset, key)
        await msg.reply_html(f"🔄 <b>Circuit breaker reset:</b> <code>{key}</code>")
        return

    metrics = await asyncio.to_thread(get_db_metrics)
    cb = metrics.get("circuit_breaker", {})
    if not cb:
        return await msg.reply_html("✅ No circuit breaker state tracked.\n\n<i>Use /dbcircuit resetall to clear.</i>")

    text = "⚡ <b>Cɪʀᴄᴜɪᴛ Bʀᴇᴀᴋᴇʀs</b>\n"
    text += "━━━━━━━━━━━━━━━━━━━━━━\n"
    for key, v in cb.items():
        if v.get("is_open"):
            text += f"  🔴 <code>{key}</code> OPEN — {v.get('failures', 0)} failures\n"
        elif v.get("failures", 0) > 0:
            text += f"  🟡 <code>{key}</code> {v.get('failures', 0)} recent failures\n"
        else:
            text += f"  🟢 <code>{key}</code> ok\n"
    text += "\n<i>Use /dbcircuit reset [key] or /dbcircuit resetall</i>"
    await msg.reply_html(text)


