"""
🔌 ADD MONGO — owner/addmongo.py
Redirect + owner-guarded wrappers for Mongo management commands.
Fixed: missing OWNER_ID guard on failover_status & syncmongo.
"""

import asyncio
import html

from telegram import Update
from telegram.ext import ContextTypes


_DIV = "▰▱" * 16


async def failover_status(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show failover status — owner only."""
    if update.effective_user.id != OWNER_ID:
        return

    f = get_failover_status()
    slots = f.get("slots", {})
    level = f.get("current_level", 0)
    active = f.get("active_failover", False)
    recovering = f.get("is_recovering", False)

    status_icon = "🔴" if active else "🟢"
    recover_icon = "🟡" if recovering else "⚫"

    text = (
        f"🛡️ <b>Failover Status</b>\n"
        f"<code>{_DIV}</code>\n\n"
        f"  Level       <b>{level}</b>\n"
        f"  Active      {status_icon} {'Yes' if active else 'No'}\n"
        f"  Recovering  {recover_icon} {'Yes' if recovering else 'No'}\n"
        f"  Slots       <b>{len(slots)}</b> tracked\n"
    )

    if slots:
        text += "\n<b>Slot States:</b>\n"
        for slot_id, slot_data in list(slots.items())[:10]:
            state = slot_data.get("state", "unknown") if isinstance(slot_data, dict) else str(slot_data)
            icon = "🟢" if state in ("ok", "active", "available") else "🔴"
            text += f"  {icon} <code>{slot_id}</code>: {state}\n"

    await update.effective_message.reply_html(text)


async def syncmongo(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Sync all MongoDB slots — owner only."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    status = await msg.reply_html("🔄 <b>Syncing MongoDB slots…</b>")
    try:
        await asyncio.to_thread(refresh_storage_slots)
        await status.edit_text(
            f"✅ <b>Mongo Sync Complete</b>\n"
            f"<code>{_DIV}</code>\n\n"
            "All slots refreshed and routing updated.",
            parse_mode="HTML"
        )
    except Exception as exc:
        await status.edit_text(f"⚠️ Sync failed: {html.escape(str(exc))}")


async def dbstatus(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Delegate to detailed dbstatus — owner only."""
    if update.effective_user.id != OWNER_ID:
        return
    await _dbstatus(update, ctx)

