async def _test_cerebras() -> tuple[bool, int, str, str]:
    if not CEREBRAS_API_KEY:
        return False, 0, "no_api_key", ""
    t0 = time.time()
    try:
        cands = await asyncio.wait_for(_discover_cerebras_models(), timeout=6.0)
    except Exception:
        cands = []
    tried: list[str] = []
    for m in (cands[:3] if cands else []) + ["qwen-3.8-27b"]:
        if m in tried:
            continue
        tried.append(m)
        try:
            content, _meta = await asyncio.wait_for(
                _call_cerebras(TEST_MESSAGES, TEST_MAX_TOKENS, TEST_TEMP, model=m),
                timeout=TEST_TIMEOUT,
            )
            ms = int((time.time() - t0) * 1000)
            if content:
                return True, ms, "", _meta.get("model", m)
        except Exception as e:
            last_err = str(e)[:120]
            continue
    ms = int((time.time() - t0) * 1000)
    return False, ms, last_err if 'last_err' in dir() else "all candidates failed", tried[0] if tried else "qwen-3.8-27b"


