from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes


logger = get_logger(__name__)


# ━━━ Lockdown state ━━━
_LOCKDOWN_FILE = "/sdcard/anyy/.lockdown"
_lockdown_lock = asyncio.Lock()


def _is_lockdown_active() -> bool:
    try:
        return os.path.exists(_LOCKDOWN_FILE)
    except Exception:
        return False


def _set_lockdown(active: bool) -> None:
    if active:
        try:
            with open(_LOCKDOWN_FILE, "w") as f:
                f.write(str(int(time.time())))
        except Exception:
            pass
    else:
        try:
            os.remove(_LOCKDOWN_FILE)
        except FileNotFoundError:
            pass


# ━━━ Common helpers ━━━
def _check_owner(update: Update) -> bool:
    return bool(update.effective_user and update.effective_user.id == OWNER_ID)


