# ━━━ /permlist ━━━
async def permlist(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """List first N IDs of a given type. Usage: /permlist [u|g|c] [limit]"""
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    kind_arg = (ctx.args[0].lower() if ctx.args else "u")
    limit = 50
    if len(ctx.args) > 1:
        try:
            limit = max(1, min(500, int(ctx.args[1])))
        except ValueError:
            pass
    kind_map = {"u": "u", "g": "g", "c": "c", "user": "u", "group": "g", "channel": "c"}
    kind = kind_map.get(kind_arg, "u")
    lines = [section_title(f"IDs ({kind}) — first {limit}", ICONS["database"]), divider()]
    n = 0
    for t, sid, name, ts in perm_ids_iter(kind, limit=limit):
        n += 1
        ts_str = ""
        if ts:
            try:
                ts_str = datetime.fromtimestamp(int(ts), timezone.utc).strftime("%Y-%m-%d")
            except Exception:
                ts_str = ""
        nm = (name or "")[:30]
        lines.append(f"  <code>{sid}</code>  {html.escape(nm)}  {small(ts_str)}")
    if n == 0:
        lines.append(small("(no entries)"))
    await msg.reply_html("\n".join(lines))


# ━━━ /health ━━━
async def health(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """System health summary."""
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    metrics = await asyncio.to_thread(get_db_metrics)
    text = section_title("System Health", ICONS["shield"]) + "\n"
    text += divider() + "\n"
    # DB section
    slots = metrics.get("slots", [])
    if isinstance(slots, list):
        healthy = sum(1 for s in slots if s.get("ok"))
        total = len(slots)
    else:
        healthy = sum(1 for s in slots.get("items", []) if s.get("ok"))
        total = len(slots.get("items", []))
    cache_info = metrics.get("cache", {})
    text += f"🗄 {small('Database')} : {bold(healthy)} / {total} {small('slots healthy')}\n"
    text += f"📦 {small('Cache')}     : {bold(cache_info.get('users', 0))} {small('entries')}\n"
    text += f"🔌 {small('Sub-DBs')}   : {bold(cache_info.get('sub_clients', 0))} {small('cached')}\n"
    # TiDB
    tidb = metrics.get("tidb", {})
    text += f"⚡ {small('TiDB')}      : {'🟢' if tidb.get('available') else '🔴'} {small(tidb.get('status', 'unknown'))}\n"
    # Circuit breaker
    cb = metrics.get("circuit_breaker", {})
    open_breakers = sum(1 for v in cb.get("status", {}).values() if v == "open")
    text += f"🔌 {small('Breakers')}  : {bold(len(cb.get('status', {})))} {small('total')} / {bold(open_breakers)} {small('open')}\n"
    # Op metrics
    op_metrics = metrics.get("metrics", {}).get("ops", {})
    if op_metrics:
        text += divider() + "\n"
        text += f"📊 {small('Op Counters')}\n"
        for op, m in list(op_metrics.items())[:5]:
            errs = m.get("errors", 0)
            total = m.get("count", 0)
            text += f"  {small(op)} : {bold(total)} {small('calls')} ({small(str(errs) + ' err')})\n"
    # Perm IDs
    pc = await asyncio.to_thread(perm_ids_count)
    text += divider() + "\n"
    text += f"🛡 {small('Perm IDs')}  : {bold(pc.get('total', 0))} {small('total')}\n"
    # Lockdown
    ld = _is_lockdown_active()
    text += f"🚨 {small('Lockdown')}  : {'🔴 ACTIVE' if ld else '🟢 OFF'}\n"
    text += divider() + "\n"
    text += small("Use /dbmetrics, /dbcircuit, /dbsubclients for details") + "\n"
    await msg.reply_html(text)


