# ━━━ /alert ━━━
async def alert(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Send an alert to LOG_GROUP and BACKUP_CHAT. Usage: /alert [message]"""
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    if not ctx.args:
        return await msg.reply_text(warning("Usage: /alert [message]"))
    text_body = " ".join(ctx.args)
    full = section_title("OWNER ALERT", "🚨") + "\n" + divider() + "\n" + text_body + "\n" + divider() + "\n" + small(datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    sent = 0
    for chat_id in (LOG_GROUP, BACKUP_CHAT, OWNER_ID):
        if not chat_id:
            continue
        try:
            await ctx.bot.send_message(chat_id, full, parse_mode="HTML")
            sent += 1
        except Exception as e:
            logger.debug("alert to %s failed: %s", chat_id, e)
    await msg.reply_text(success(f"Alert sent to {sent} target(s)."))


# --- Update-travel breadcrumbs (owner diag: how far does a text update get?) ---
_UPDATE_CRUMBS: dict = {}

def _crumb(stage: str, update) -> None:
    try:
        msg = update.effective_message if update else None
        _UPDATE_CRUMBS[stage] = {
            "t": time.time(),
            "mid": getattr(msg, "message_id", None),
            "text": ((msg.text or "")[:60] if msg and getattr(msg, "text", None) else ""),
            "ctype": getattr(update.effective_chat, "type", None) if update else None,
        }
    except Exception:
        pass


# ━━━ /lastupdate — show breadcrumb trail of the last DM text ━━━
async def lastupdate(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not await advanced__owner_only(update, ctx):
        return
    if not _UPDATE_CRUMBS:
        await update.effective_message.reply_text("No crumbs yet — send a text first, then run /lastupdate.")
        return
    now = time.time()
    rows = []
    for stage in ("track", "guard_in", "guard_go", "handle_in", "sent"):
        c = _UPDATE_CRUMBS.get(stage)
        if not c:
            rows.append(f"{stage}: —")
        else:
            rows.append(f"{stage}: mid={c.get('mid')} {now - c.get('t', now):.0f}s ago text={c.get('text')!r}")
    await update.effective_message.reply_text("CRUMBS\n" + "\n".join(rows))


# ━━━ /aiping — owner AI self-diagnostic (gates + live chat call) ━━━
async def aiping(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Run the full AI stack synchronously and report every step.

    Bypasses ai_guard/handle dispatch (this IS a command) while exercising
    the exact same gates + chat_completion the DM flow uses. Anything that
    silently drops DM text shows up here as an explicit line.
    """
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    chat = update.effective_chat
    user = update.effective_user
    lines: list[str] = []
    try:
        cid = chat.id if chat else 0
        is_private = (chat.type == "private") if chat else False
        lines.append(f"chat={cid} private={is_private}")
        try:
            lines.append(f"should_respond={await _should_respond('anyy ping test', cid, is_private, False, '')}")
        except Exception as e:
            lines.append(f"should_respond=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            lines.append(f"cat_ai_disabled={await bot_category_disabled('ai')}")
        except Exception as e:
            lines.append(f"cat_ai_disabled=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            gv = await asyncio.to_thread(_get_cached_setting, "global_ai", "on")
            lines.append(f"global_ai={gv!r}")
        except Exception as e:
            lines.append(f"global_ai=EXC {type(e).__name__}: {str(e)[:120]}")
        # Timed pre-typing steps (a hang here = no typing indicator, no reply)
        try:
            t0 = time.time()
            hist = await _read_telegram_history(cid, user.id)
            lines.append(f"history={len(hist)} items in {time.time()-t0:.1f}s")
        except Exception as e:
            lines.append(f"history=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            t0 = time.time()
            lang = detect_language("anyy hi test")
            lines.append(f"detect_language={lang!r} in {time.time()-t0:.1f}s")
        except Exception as e:
            lines.append(f"detect_language=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            t0 = time.time()
            fo = await _get_force_on(cid)
            lines.append(f"force_on={fo} in {time.time()-t0:.1f}s")
        except Exception as e:
            lines.append(f"force_on=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            lines.append(f"creating_button={is_creating_button(user.id)} quiet={cid in _quiet}")
        except Exception as e:
            lines.append(f"state=EXC {type(e).__name__}: {str(e)[:120]}")
        try:
            resp, meta = await asyncio.wait_for(
                chat_completion(
                    [{"role": "user", "content": "reply with exactly: mango"}],
                    category="chat", lang="english", max_tokens=60, temperature=0.5,
                ),
                timeout=30,
            )
            content = resp.choices[0].message.content if hasattr(resp, "choices") else resp
            lines.append(f"chat_completion OK provider={meta.get('provider')} model={meta.get('model')}")
            lines.append(f"reply={(content or '')[:200]!r}")
        except Exception as e:
            lines.append(f"chat_completion EXC {type(e).__name__}: {str(e)[:200]}")
    except Exception as e:
        lines.append(f"harness EXC {type(e).__name__}: {str(e)[:200]}")
    report = "AI PING\n" + "\n".join(f"- {ln}" for ln in lines)
    try:
        await msg.reply_text(report[:3500])
    except Exception:
        await msg.reply_html(f"<pre>{html.escape(report[:3000])}</pre>")


# ━━━ /testproviders ━━━
async def testproviders(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Test every AI provider and model, then reorder so working ones come first.
    Failing providers are demoted to the END of the priority order.
    The new order is persisted in MongoDB and loaded automatically on next boot."""
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    # Show "testing" status first
    status_msg = await msg.reply_html(
        section_title("Testing AI Providers", "🧪") + "\n"
        + divider() + "\n"
        + f"{small('Running parallel test on every configured provider…')}\n"
        + f"{small('Timeout: 12s per provider')}\n"
    )
    try:
        t0 = time.time()
        results = await test_all_providers()
        elapsed = time.time() - t0

        ok_count = sum(1 for r in results.values() if r["ok"])
        fail_count = len(results) - ok_count
        order = list(results.keys())
        # Reorder priority as successful-first (faster first), failing-last
        working = sorted(
            [(n, r) for n, r in results.items() if r["ok"]],
            key=lambda kv: kv[1]["latency_ms"],
        )
        failing = [(n, r) for n, r in results.items() if not r["ok"]]
        new_order = [n for n, _ in working] + [n for n, _ in failing]

        text = section_title("AI Provider Test Results", "🧪") + "\n"
        text += divider() + "\n"
        text += stat_row("✅", "ᴡᴏʀᴋɪɴɢ", bold(ok_count)) + "  "
        text += stat_row("❌", "ғᴀɪʟᴇᴅ", bold(fail_count)) + "  "
        text += stat_row("🕐", "ᴛᴀᴋᴇɴ", bold(f"{elapsed:.1f}s")) + "\n"
        text += divider() + "\n"
        # Show each provider with status, latency, error (if any)
        for n in new_order:
            r = results.get(n, {})
            ok = r.get("ok", False)
            ms = r.get("latency_ms", 0)
            err = r.get("error", "")
            model = r.get("model", "")
            icon = "🟢" if ok else "🔴"
            line = f"  {icon} {bold(n):<14}"
            if ok:
                line += f"  {bold(str(ms) + 'ms'):>9}  {small(model)}"
            else:
                err_short = (err.split('\n')[0])[:60] if err else "?"
                line += f"  {bold('FAIL'):>9}  {small(err_short)}"
            text += line + "\n"
        text += divider() + "\n"
        text += f"🥇 {small('New priority order (working first)')}\n"
        # Show as numbered list
        for i, name in enumerate(new_order, 1):
            r = results.get(name, {})
            icon = "🟢" if r.get("ok") else "🔴"
            text += f"  {i}. {icon} {bold(name)}\n"
        text += divider() + "\n"
        text += f"{small('Saved to MongoDB. Loaded on next bot start.')}\n"
        kb = [[InlineKeyboardButton("🔄 ʀᴇ-ᴛᴇsᴛ", callback_data="owner:testproviders")]]
        try:
            await status_msg.edit_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(kb))
        except Exception:
            # If edit fails (e.g. message too long), fall back to reply
            await msg.reply_html(text, reply_markup=InlineKeyboardMarkup(kb))
    except Exception as exc:
        logger.exception("testproviders failed")
        try:
            await status_msg.edit_text(error(f"Test failed: {exc}"))
        except Exception:
            await msg.reply_text(error(f"Test failed: {exc}"))


# ━━━ /providerstatus ━━━
async def providerstatus(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show current AI provider priority and last test results."""
    if not await advanced__owner_only(update, ctx):
        return
    msg = update.effective_message
    try:
        priority = get_priority()
        results = get_last_results()
        text = section_title("AI Provider Status", "🤖") + "\n"
        text += divider() + "\n"
        text += f"📋 {small('Current priority order')}\n"
        for i, name in enumerate(priority, 1):
            r = results.get(name, {})
            ok = r.get("ok")
            if ok is None:
                # No test result yet — show unknown
                icon = "⚪"
                extra = small("untested")
            elif ok:
                icon = "🟢"
                extra = bold(f"{r.get('latency_ms', 0)}ms")
            else:
                icon = "🔴"
                extra = small("failing")
            text += f"  {i}. {icon} {bold(name):<14}  {extra}\n"
        text += divider() + "\n"
        if results:
            ok_count = sum(1 for r in results.values() if r["ok"])
            text += stat_row("✅", "ᴡᴏʀᴋɪɴɢ", bold(ok_count)) + "  "
            text += stat_row("❌", "ғᴀɪʟᴇᴅ", bold(len(results) - ok_count)) + "\n"
        else:
            text += small("No tests run yet. Use /testproviders to run one.\n")
        kb = [[InlineKeyboardButton("🧪 ᴛᴇsᴛ ɴᴏᴡ", callback_data="owner:testproviders")]]
        await msg.reply_html(text, reply_markup=InlineKeyboardMarkup(kb))
    except Exception as exc:
        await msg.reply_text(error(f"Status failed: {exc}"))


# ━━━ Callback router ━━━
async def advanced_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle advanced owner inline-button callbacks."""
    q = update.callback_query
    if not q or not q.from_user or q.from_user.id != OWNER_ID:
        if q:
            await q.answer("Owner only.", show_alert=True)
        return
    data = q.data or ""
    if not data.startswith("owner:"):
        return
    action = data.split(":", 2)[1] if data.count(":") >= 2 else data.split(":", 1)[1]
    arg = data.split(":", 2)[2] if data.count(":") >= 2 else None

    if action == "permexport":
        await q.answer()
        payload = perm_ids_export_text(None)
        fname = f"perm_ids_all_{int(time.time())}.txt"
        try:
            await q.message.reply_document(
                document=payload.encode("utf-8"),
                filename=fname,
                caption=section_title("Exported Permanent IDs", ICONS["key"]),
            )
        except Exception as e:
            await q.message.reply_text(error(f"Export failed: {e}"))
        return
    if action == "permfill":
        await q.answer("Backfilling...")
        users_n = await asyncio.to_thread(perm_ids_register_from_collection, "users")
        chats_n = await asyncio.to_thread(perm_ids_register_from_collection, "chats")
        await q.message.reply_html(
            section_title("Backfill Complete", ICONS["success"]) + "\n"
            + divider() + "\n"
            + stat_row(ICONS["user"], "ᴜsers", count(users_n)) + "\n"
            + stat_row(ICONS["group"], "ɢʀᴏᴜᴘs/ᴄʜᴀɴɴᴇʟs", count(chats_n)) + "\n"
        )
        return
    if action == "permlist":
        await q.answer()
        kind = arg or "u"
        limit = 50
        lines = [section_title(f"IDs ({kind}) — first {limit}", ICONS["database"]), divider()]
        n = 0
        for t, sid, name, ts in perm_ids_iter(kind, limit=limit):
            n += 1
            ts_str = ""
            if ts:
                try:
                    ts_str = datetime.fromtimestamp(int(ts), timezone.utc).strftime("%Y-%m-%d")
                except Exception:
                    ts_str = ""
            nm = (name or "")[:30]
            lines.append(f"  <code>{sid}</code>  {html.escape(nm)}  {small(ts_str)}")
        if n == 0:
            lines.append(small("(no entries)"))
        await q.message.reply_html("\n".join(lines))
        return
    if action == "testproviders":
        await q.answer("Re-testing providers…")
        try:
            results = await test_all_providers()
            ok_count = sum(1 for r in results.values() if r["ok"])
            await q.message.reply_text(
                success(f"Test done. {ok_count}/{len(results)} working.")
            )
        except Exception as exc:
            await q.message.reply_text(error(f"Test failed: {exc}"))
        return
    await q.answer("Unknown action.")


