# ═══ MODULE: owner.broadcast.commands ═══

"""
📣 BROADCAST COMMANDS - owner/broadcast/commands.py v5.0
All broadcast types including pin broadcasts
Supports: speed format (15/1), reply-to-message content,
          interactive speed confirmation with Telegram's official limits
"""
import re
import time
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes
import asyncio


# ── Telegram's official broadcast limits (free tier) ─────────────────────────
# Source: https://core.telegram.org/bots/faq#my-bot-is-hitting-limits-how-do-i-avoid-this
TG_BROADCAST_LIMITS = {
    "global_max": 30,       # msgs/sec to DIFFERENT chats
    "per_chat_max": 1,      # msg/sec to the SAME chat
    "safe_recommended": 20, # conservative rate to avoid 429 flood waits
    "per_minute_max": 1500, # ~25/sec sustained
}


def _extract_speed_and_text(args: list[str]) -> tuple[float, list[str]]:
    """Check if first arg is speed format (N/M) and extract rate_delay.
    Returns (rate_delay, remaining_args). Default rate_delay = 0.05 (~20/sec)."""
    if args and re.match(r'^\d+/\d+$', args[0]):
        rate_delay = manager.parse_speed(args[0])
        if rate_delay is not None:
            return rate_delay, args[1:]
    return 0.05, args


def _get_broadcast_text(update: Update, args: list[str]) -> tuple[str, bool]:
    """Get broadcast text from reply-to-message or command args.
    Returns (text, is_from_reply)."""
    reply = update.effective_message.reply_to_message
    if reply:
        reply_text = reply.text or reply.caption or ""
        if reply_text:
            if args:
                return reply_text + "\n\n" + " ".join(args), True
            return reply_text, True
    return " ".join(args), False


# ── Speed confirmation flow ──────────────────────────────────────────────────
# Preset speed options (N/M format, N messages per M seconds)
# All within Telegram's free-tier limits
_BROADCAST_SPEED_PRESETS = [
    ("slow",     "5/1",  0.20, "🐢 Sʟᴏᴡ (5/sec) — very safe, no flood waits"),
    ("safe",     "10/1", 0.10, "🛡️ Sᴀғᴇ (10/sec) — recommended for large lists"),
    ("default",  "20/1", 0.05, "⚡ Dᴇғᴀᴜʟᴛ (20/sec) — fast, near Telegram max"),
    ("fast",     "25/1", 0.04, "🚀 Fᴀsᴛ (25/sec) — Telegram global max"),
    ("max",      "30/1", 0.033, "🔥 Mᴀx (30/sec) — Telegram's hard limit"),
]

_PENDING_BROADCAST = "pending_broadcast"


def _format_speed_presets_kb(prefix: str) -> InlineKeyboardMarkup:
    """Build the speed-selection keyboard."""
    rows = []
    for key, fmt, _, desc in _BROADCAST_SPEED_PRESETS:
        rows.append([InlineKeyboardButton(desc, callback_data=f"{prefix}:speed:{key}")])
    rows.append([InlineKeyboardButton("✏️ Cᴜsᴛᴏᴍ Sᴘᴇᴇᴅ (N/M)", callback_data=f"{prefix}:speed:custom")])
    rows.append([InlineKeyboardButton("❌ Cᴀɴᴄᴇʟ", callback_data=f"{prefix}:speed:cancel")])
    return InlineKeyboardMarkup(rows)


def _speed_confirm_text(target_type: str, text: str) -> str:
    """Build the speed-confirmation message text."""
    text_preview = text[:200] + ("…" if len(text) > 200 else "")
    return (
        f"📡 <b>Bʀᴏᴀᴅᴄᴀsᴛ Cᴏɴғɪʀᴍᴀᴛɪᴏɴ</b>\n\n"
        f"📤 <b>Tᴀʀɢᴇᴛ:</b> {target_type.upper()}\n"
        f"📝 <b>Mᴇssᴀɢᴇ:</b>\n"
        f"<blockquote>{text_preview}</blockquote>\n"
        f"━" * 30 + "\n"
        f"⚡ <b>Tᴇʟᴇɢʀᴀᴍ's Fʀᴇᴇ-Tɪᴇʀ Lɪᴍɪᴛs:</b>\n"
        f"  • Global max: <b>{TG_BROADCAST_LIMITS['global_max']}/sec</b> to different chats\n"
        f"  • Per-chat:   <b>{TG_BROADCAST_LIMITS['per_chat_max']}/sec</b> to the same chat\n"
        f"  • Per-min:    <b>{TG_BROADCAST_LIMITS['per_minute_max']}/min</b> sustained\n"
        f"  • Recommended: <b>{TG_BROADCAST_LIMITS['safe_recommended']}/sec</b> to avoid 429\n\n"
        f"🐢 <b>Pɪᴄᴋ ᴀ sᴘᴇᴇᴅ:</b>"
    )


async def _ask_speed(update: Update, ctx: ContextTypes.DEFAULT_TYPE,
                     target_type: str, text: str, from_reply: bool,
                     prefix: str = "bc") -> None:
    """Show speed confirmation keyboard to owner."""
    ctx.user_data[_PENDING_BROADCAST] = {
        "target_type": target_type,
        "text": text,
        "from_reply": from_reply,
        "ts": time.time(),
    }
    await update.effective_message.reply_html(
        _speed_confirm_text(target_type, text),
        reply_markup=_format_speed_presets_kb(prefix),
    )


async def _run_confirmed_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE,
                                    target_type: str, text: str,
                                    rate_delay: float) -> None:
    """Start the broadcast after speed confirmation."""
    if manager.is_running():
        await update.effective_message.reply_text("⚠️ Broadcast already running. Use /cancelbroadcast")
        return

    speed_label = f"{int(1/rate_delay)}/sec" if rate_delay > 0 else "default"
    started = await manager.start_broadcast(ctx.bot, target_type, text, rate_delay=rate_delay)
    if started:
        await update.effective_message.reply_html(
            f"🚀 <b>Bʀᴏᴀᴅᴄᴀsᴛ Sᴛᴀʀᴛᴇᴅ</b>\n\n"
            f"📤 Tᴀʀɢᴇᴛ: <b>{target_type.upper()}</b>\n"
            f"⚡ Sᴘᴇᴇᴅ: <b>{speed_label}</b>\n\n"
            f"Use /broadcaststats for progress"
        )
    else:
        await update.effective_message.reply_text("⚠️ Failed to start broadcast (no targets?)")


async def broadcastall(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Broadcast to all users, groups, and channels.
    Usage: /broadcastall [speed] [text]
    Speed format: N/M (e.g. 15/1 = 15 users per second)
    Reply to a message to use its content as broadcast text.

    If no speed is provided, shows an interactive speed-selection menu."""
    if update.effective_user.id != OWNER_ID:
        return

    rate_delay, text_args = _extract_speed_and_text(ctx.args)
    text, from_reply = _get_broadcast_text(update, text_args)
    if not text:
        await update.effective_message.reply_text(
            "⚠️ Usage: /broadcastall [speed] [text]\n"
            "   Or reply to a message with /broadcastall [speed]\n"
            "   Speed format: 15/1 = 15 users/sec"
        )
        return

    if manager.is_running():
        await update.effective_message.reply_text("⚠️ Broadcast already running. Use /cancelbroadcast")
        return

    # If speed was provided in command, run immediately
    if ctx.args and re.match(r'^\d+/\d+$', ctx.args[0]):
        speed_label = f"{int(1/rate_delay)}/sec" if rate_delay > 0 else "default"
        await update.effective_message.reply_html(
            f"📤 <b>Pʀᴇᴘᴀʀɪɴɢ Bʀᴏᴀᴅᴄᴀsᴛ</b>\n\n"
            f"⚡ Sᴘᴇᴇᴅ: <b>{speed_label}</b>\n"
            f"Fetching all chats..."
        )
        await _run_confirmed_broadcast(update, ctx, 'all', text, rate_delay)
        return

    # No speed — ask interactively
    await _ask_speed(update, ctx, 'all', text, from_reply, prefix="bc_all")


async def broadcastusers(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Broadcast to private users only.
    Usage: /broadcastusers [speed] [text]
    Reply to a message to use its content as broadcast text."""
    if update.effective_user.id != OWNER_ID:
        return

    rate_delay, text_args = _extract_speed_and_text(ctx.args)
    text, from_reply = _get_broadcast_text(update, text_args)
    if not text:
        await update.effective_message.reply_text(
            "⚠️ Usage: /broadcastusers [speed] [text]\n"
            "   Or reply to a message with /broadcastusers [speed]"
        )
        return

    if manager.is_running():
        await update.effective_message.reply_text("⚠️ Broadcast already running")
        return

    if ctx.args and re.match(r'^\d+/\d+$', ctx.args[0]):
        await _run_confirmed_broadcast(update, ctx, 'users', text, rate_delay)
        return

    await _ask_speed(update, ctx, 'users', text, from_reply, prefix="bc_users")


