async def broadcastwithbutton(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Broadcast with inline button.
    Usage: /broadcastwithbutton [text] [button_text] [url]
    Or reply to a message with /broadcastwithbutton [button_text] [url]"""
    if update.effective_user.id != OWNER_ID:
        return

    reply = update.effective_message.reply_to_message
    base_text = (reply.text or reply.caption or "") if reply else ""

    if base_text and len(ctx.args) >= 1:
        btn_text = ctx.args[0]
        url = ctx.args[1] if len(ctx.args) > 1 else "https://t.me/Anyyxsupportbot"
    elif not base_text and len(ctx.args) >= 2:
        base_text = ctx.args[0]
        btn_text = ctx.args[1]
        url = ctx.args[2] if len(ctx.args) > 2 else "https://t.me/Anyyxsupportbot"
    else:
        await update.effective_message.reply_text(
            "⚠️ Usage:\n"
            "  /broadcastwithbutton [text] [button_text] [url]\n"
            "  Or reply to a message with /broadcastwithbutton [button_text] [url]\n"
            "  Text comes from the replied message."
        )
        return

    async def send_with_button(bot, chat_id):
        kb = InlineKeyboardMarkup([[InlineKeyboardButton(btn_text, url=url)]])
        return await bot.send_message(chat_id, base_text, reply_markup=kb, parse_mode="HTML")

    if manager.is_running():
        await update.effective_message.reply_text("⚠️ Broadcast already running")
        return

    started = await manager.start_broadcast(ctx.bot, 'all', send_with_button)
    if started:
        await update.effective_message.reply_html("🚀 <b>Button Broadcast Started</b>")


async def broadcaststats(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show detailed broadcast stats."""
    if update.effective_user.id != OWNER_ID:
        return

    s = manager.get_stats()
    history = manager.get_history()

    text = "📢 <b>BROADCAST STATUS</b>\n"
    text += "━" * 35 + "\n\n"

    if s["running"]:
        text += "🟢 <b>STATUS:</b> <code>RUNNING</code>\n\n"
        
        text += "📊 <b>CURRENT BROADCAST</b>\n"
        text += f"  ├ Type: <b>{s['type'].upper()}</b>\n"
        text += f"  ├ Progress: <b>{s['sent']:,}</b> / <b>{s['total']:,}</b>\n"
        text += f"  │   └ <b>{s.get('progress_percent', 0):.1f}%</b>\n"
        text += f"  ├ Sent: <b>✅ {s['sent']:,}</b>\n"
        text += f"  ├ Failed: <b>⚠️ {s['failed']:,}</b>\n"
        text += f"  ├ Remaining: <b>{s.get('remaining', 0):,}</b>\n"
        text += f"  ├ Speed: <b>{s['speed']:.1f}/sec</b>\n"
        
        elapsed = s.get('elapsed', 0)
        if elapsed > 0:
            text += f"  ├ Elapsed: <b>{elapsed:.0f}s</b>\n"
            if s['speed'] > 0:
                eta = s.get('remaining', 0) / s['speed']
                text += f"  └ ETA: <b>{eta/60:.1f} min</b>\n"
    else:
        text += "⚫ <b>STATUS:</b> <code>IDLE</code>\n\n"

    if history:
        total_sent = sum(h['sent'] for h in history)
        total_failed = sum(h['failed'] for h in history)
        total_broadcasts = len(history)
        
        text += "📈 <b>TOTAL STATISTICS</b>\n"
        text += f"  ├ Broadcasts: <b>{total_broadcasts}</b>\n"
        text += f"  ├ Total Sent: <b>{total_sent:,}</b>\n"
        text += f"  └ Total Failed: <b>{total_failed:,}</b>\n\n"

    if history:
        text += "📜 <b>RECENT BROADCASTS</b>\n"
        for i, h in enumerate(reversed(history[-5:])):
            h_time = h.get('timestamp', 0)
            if h_time:
                age = time.time() - h_time
                age_str = f"{age/60:.0f}m ago" if age < 3600 else f"{age/3600:.1f}h ago"
            else:
                age_str = "N/A"
            
            success_rate = (h['sent'] / h['total'] * 100) if h['total'] > 0 else 0
            text += f"  {i+1}. <b>{h['type'].upper()}</b> - {h['sent']} sent ({success_rate:.0f}%) {age_str}\n"
    else:
        text += "📜 <b>No broadcasts yet</b>\n"

    kb = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🔄 Refresh", callback_data="broadcast_stats"),
            InlineKeyboardButton("🛑 Stop", callback_data="broadcast_cancel"),
        ]
    ])

    await update.effective_message.reply_html(text, reply_markup=kb)


async def cancelbroadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Cancel current broadcast."""
    if update.effective_user.id != OWNER_ID:
        return

    if not manager.is_running():
        await update.effective_message.reply_text("No broadcast to cancel")
        return

    s = manager.get_stats()
    manager.stop()

    await update.effective_message.reply_html(
        f"🛑 <b>BROADCAST CANCELLED</b>\n\n"
        f"Sent before stop: <b>{s['sent']:,}</b>\n"
        f"Failed before stop: <b>{s['failed']:,}</b>"
    )


# PIN BROADCASTS

async def pinbroadcastusers(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Pin message to all users.
    Usage: /pinbroadcastusers [speed] [text]
    Reply to a message to use its content as pin text."""
    if update.effective_user.id != OWNER_ID:
        return

    rate_delay, text_args = _extract_speed_and_text(ctx.args)
    text, from_reply = _get_broadcast_text(update, text_args)
    if not text:
        await update.effective_message.reply_text(
            "⚠️ Usage: /pinbroadcastusers [speed] [text]\n"
            "   Or reply to a message with /pinbroadcastusers [speed]"
        )
        return

    if manager.is_running():
        await update.effective_message.reply_text("⚠️ Broadcast already running")
        return

    msg = await update.effective_message.reply_html(
        f"📌 <b>Pin Broadcast Starting...</b>\n\n"
        f"Message will be pinned in all user chats."
    )

    source = " (from replied message)" if from_reply else ""

    async def send_and_pin(bot, chat_id):
        msg = await bot.send_message(chat_id, text, parse_mode="HTML")
        try:
            await bot.pin_chat_message(chat_id, msg.message_id)
        except Exception as e:
            logger.debug(f"Pin failed {chat_id}: {e}")
        manager._last_pinned_msg_ids[chat_id] = msg.message_id
        return msg

    started = await manager.start_broadcast(ctx.bot, 'users', send_and_pin, rate_delay=rate_delay)
    if started:
        speed_label = f"{int(1/rate_delay)}/sec" if rate_delay > 0 else "default"
        await msg.edit_text(
            f"📌 <b>Pin Broadcast Started</b>{source}\n"
            f"⚡ Speed: <b>{speed_label}</b>\n\n"
            f"Check /broadcaststats for progress"
        )
    else:
        await msg.edit_text("⚠️ Failed to start pin broadcast")


