async def deletelastbroadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Delete the last broadcast messages from all chats."""
    if update.effective_user.id != OWNER_ID:
        return

    msg_ids = manager.get_last_broadcast_msg_ids()
    if not msg_ids:
        await update.effective_message.reply_text("📭 No broadcast history to delete.")
        return

    status = await update.effective_message.reply_html(
        f"🗑 <b>Deleting last broadcast...</b>\n\n"
        f"Targets: <b>{len(msg_ids):,}</b>"
    )

    deleted = 0
    failed = 0
    for chat_id, msg_id in list(msg_ids.items()):
        try:
            await ctx.bot.delete_message(chat_id, msg_id)
            deleted += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.05)

    manager.clear_last_broadcast()

    await status.edit_text(
        f"🗑 <b>Broadcast Deletion Complete</b>\n\n"
        f"✅ Deleted: <b>{deleted:,}</b>\n"
        f"⚠️ Failed: <b>{failed:,}</b>"
    )


