# ── Speed-selection callback handler ────────────────────────────────────────
async def broadcast_speed_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle speed-selection button presses from the confirmation menu.

    Callback data format: `<prefix>:speed:<key>` where prefix is bc_all/bc_users/etc.
    Keys: slow, safe, default, fast, max, custom, cancel
    """
    query = update.callback_query
    if not query or update.effective_user.id != OWNER_ID:
        if query:
            await query.answer("⚠️ Owner only.", show_alert=True)
        return

    data = query.data or ""
    parts = data.split(":")
    if len(parts) != 3 or parts[1] != "speed":
        await query.answer("Invalid data.")
        return
    prefix, _, key = parts

    pending = ctx.user_data.get(_PENDING_BROADCAST)
    if not pending or time.time() - pending.get("ts", 0) > 600:
        await query.answer("⚠️ Expired (10min). Re-run the broadcast command.", show_alert=True)
        await query.edit_message_text("⚠️ Broadcast confirmation expired. Please re-run the command.")
        return

    # Map prefix → target_type
    target_type = prefix.replace("bc_", "")

    if key == "cancel":
        await query.answer("Cancelled.")
        await query.edit_message_text("❌ <b>Broadcast cancelled.</b>", parse_mode="HTML")
        ctx.user_data.pop(_PENDING_BROADCAST, None)
        return

    if key == "custom":
        await query.answer("Enter custom speed")
        # Show format instructions
        custom_kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("↩ Back", callback_data=f"{prefix}:speed:back"),
            InlineKeyboardButton("❌ Cancel", callback_data=f"{prefix}:speed:cancel"),
        ]])
        await query.edit_message_text(
            f"✏️ <b>Cᴜsᴛᴏᴍ Sᴘᴇᴇᴅ</b>\n\n"
            f"Send the speed in <code>N/M</code> format:\n"
            f"  • <b>N</b> = number of messages\n"
            f"  • <b>M</b> = time window in seconds\n\n"
            f"<b>Examples:</b>\n"
            f"  • <code>15/1</code> = 15 messages per second\n"
            f"  • <code>30/2</code> = 15 messages per second (averaged)\n"
            f"  • <code>5/1</code> = 5 messages per second (gentle)\n\n"
            f"⚠️ Must respect Telegram's free-tier limits:\n"
            f"  • Max <b>{TG_BROADCAST_LIMITS['global_max']}/sec</b> to different chats\n"
            f"  • Higher rates may trigger 429 flood waits",
            parse_mode="HTML",
            reply_markup=custom_kb,
        )
        # Mark that we're awaiting custom input
        pending["awaiting_custom_speed"] = True
        pending["prefix"] = prefix
        ctx.user_data[_PENDING_BROADCAST] = pending
        return

    if key == "back":
        await query.answer()
        await query.edit_message_text(
            _speed_confirm_text(pending["target_type"], pending["text"]),
            parse_mode="HTML",
            reply_markup=_format_speed_presets_kb(prefix),
        )
        return

    # Preset speed
    preset = next((p for p in _BROADCAST_SPEED_PRESETS if p[0] == key), None)
    if not preset:
        await query.answer("Unknown speed.")
        return
    _, fmt, rate_delay, desc = preset

    await query.answer(f"Starting: {fmt}")
    await query.edit_message_text(
        f"🚀 <b>Bʀᴏᴀᴅᴄᴀsᴛ Sᴛᴀʀᴛɪɴɢ...</b>\n\n"
        f"📤 Tᴀʀɢᴇᴛ: <b>{target_type.upper()}</b>\n"
        f"⚡ Sᴘᴇᴇᴅ: <b>{fmt}</b> ({desc})\n",
        parse_mode="HTML",
    )
    ctx.user_data.pop(_PENDING_BROADCAST, None)

    # Start the broadcast
    started = await manager.start_broadcast(
        ctx.bot, target_type, pending["text"], rate_delay=rate_delay
    )
    if not started:
        await query.message.reply_text("⚠️ Failed to start broadcast (no targets?)")


# ── Custom speed input handler ──────────────────────────────────────────────
async def handle_custom_broadcast_speed(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle owner's reply with custom N/M speed format.

    Triggered when the owner replies to the bot's "Custom Speed" message
    with a number in N/M format.
    """
    if update.effective_user.id != OWNER_ID:
        return

    pending = ctx.user_data.get(_PENDING_BROADCAST)
    if not pending or not pending.get("awaiting_custom_speed"):
        return  # Not in custom-speed flow

    text = (update.effective_message.text or "").strip()
    m = re.match(r'^(\d+)\s*/\s*(\d+)$', text)
    if not m:
        await update.effective_message.reply_text(
            "⚠️ Invalid format. Use <code>N/M</code> like <code>15/1</code>",
            parse_mode="HTML",
        )
        return

    n_msgs = int(m.group(1))
    n_secs = int(m.group(2))
    if n_msgs <= 0 or n_secs <= 0:
        await update.effective_message.reply_text("⚠️ N and M must be positive.")
        return

    rate_delay = n_secs / n_msgs
    msgs_per_sec = n_msgs / n_secs

    # Check against Telegram's free-tier limits
    if msgs_per_sec > TG_BROADCAST_LIMITS["global_max"]:
        await update.effective_message.reply_html(
            f"⚠️ <b>Sᴘᴇᴇᴅ Tᴏᴏ Hɪɢʜ</b>\n\n"
            f"You requested <b>{msgs_per_sec:.1f}/sec</b>, but Telegram's free-tier\n"
            f"limit is <b>{TG_BROADCAST_LIMITS['global_max']}/sec</b> to different chats.\n\n"
            f"Higher rates will trigger 429 flood waits and the bot will be\n"
            f"temporarily rate-limited.\n\n"
            f"💡 Try <code>30/1</code> (= 30/sec, Telegram's hard max)"
        )
        return

    target_type = pending["target_type"]
    prefix = pending.get("prefix", f"bc_{target_type}")
    ctx.user_data.pop(_PENDING_BROADCAST, None)

    await update.effective_message.reply_html(
        f"🚀 <b>Cᴜsᴛᴏᴍ Bʀᴏᴀᴅᴄᴀsᴛ Sᴛᴀʀᴛɪɴɢ</b>\n\n"
        f"📤 Tᴀʀɢᴇᴛ: <b>{target_type.upper()}</b>\n"
        f"⚡ Sᴘᴇᴇᴅ: <b>{msgs_per_sec:.1f}/sec</b> ({n_msgs}/{n_secs})\n"
        f"⏱️ Rᴀᴛᴇ ᴅᴇʟᴀʏ: <b>{rate_delay*1000:.0f}ms</b> between messages"
    )

    started = await manager.start_broadcast(
        ctx.bot, target_type, pending["text"], rate_delay=rate_delay
    )
    if not started:
        await update.effective_message.reply_text("⚠️ Failed to start broadcast (no targets?)")

