# ═══ MODULE: owner.editmsg ═══

import html
from copy import deepcopy
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes


async def editmsg(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    if not msg:
        return
    if not msg.reply_to_message:
        await msg.reply_text("⚠️ Reply to a bot message with /editmsg <new text>")
        return
    target = msg.reply_to_message
    if not target.from_user or not target.from_user.is_bot:
        await msg.reply_text("⚠️ Reply to a message sent by the bot itself.")
        return
    if not ctx.args:
        current = target.text or target.caption or ""
        preview = current[:200] + "..." if len(current) > 200 else current
        await msg.reply_text(
            f"📄 <b>Current message:</b>\n<code>{html.escape(preview)}</code>\n\n"
            f"Reply again with:\n"
            f"<code>/editmsg &lt;new text&gt;</code>",
            parse_mode="HTML"
        )
        return
    new_text = msg.text.split(maxsplit=1)[1] if len(msg.text.split(maxsplit=1)) > 1 else " ".join(ctx.args)
    try:
        await target.edit_text(new_text, parse_mode="HTML", reply_markup=target.reply_markup)
        await msg.delete()
    except Exception as e:
        err = str(e)
        if "message is not modified" in err.lower():
            return
        logger.warning("editmsg error: %s", err, exc_info=True)
        await msg.reply_text(f"⚠️ Error: {html.escape(err[:200])}")


async def editbutton(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    if not msg:
        return
    if not msg.reply_to_message:
        await msg.reply_text("⚠️ Reply to a bot message with /editbutton <old text> | <new text>")
        return
    target = msg.reply_to_message
    if not target.from_user or not target.from_user.is_bot:
        await msg.reply_text("⚠️ Reply to a message sent by the bot itself.")
        return
    if not target.reply_markup or not target.reply_markup.inline_keyboard:
        await msg.reply_text("⚠️ That message has no inline buttons.")
        return
    if len(ctx.args) < 2:
        lines = ["📋 <b>Current buttons:</b>\n"]
        for i, row in enumerate(target.reply_markup.inline_keyboard, 1):
            for btn in row:
                label = html.escape(btn.text)
                lines.append(f"  {i}. <code>{label}</code>")
        lines.append("\nReply again with:")
        lines.append("<code>/editbutton &lt;old text&gt; | &lt;new text&gt;</code>")
        await msg.reply_text("\n".join(lines), parse_mode="HTML")
        return

    raw = msg.text.split(maxsplit=1)[1] if len(msg.text.split(maxsplit=1)) > 1 else " ".join(ctx.args)
    parts = [p.strip() for p in raw.split("|", 1)]
    if len(parts) != 2 or not parts[0] or not parts[1]:
        await msg.reply_text("⚠️ Use: /editbutton <old text> | <new text>")
        return
    old_label, new_label = parts

    new_kb = []
    found = False
    for row in target.reply_markup.inline_keyboard:
        new_row = []
        for btn in row:
            if btn.text == old_label and not found:
                new_row.append(InlineKeyboardButton(new_label, callback_data=btn.callback_data, url=btn.url))
                found = True
            else:
                new_row.append(btn)
        new_kb.append(new_row)

    if not found:
        await msg.reply_text(f"⚠️ No button with text \"{html.escape(old_label)}\" found.")
        return

    try:
        await target.edit_text(target.text or target.caption or "", parse_mode="HTML", reply_markup=InlineKeyboardMarkup(new_kb))
        await msg.delete()
    except Exception as e:
        err = str(e)
        if "message is not modified" in err.lower():
            return
        logger.warning("editbutton error: %s", err, exc_info=True)
        await msg.reply_text(f"⚠️ Error: {html.escape(err[:200])}")

# ═══ MODULE: owner.filters.abuse ═══

"""
🛡️ ABUSE FILTER - owner/filters/abuse.py
Manage the automated abuse word filter.
"""
import asyncio
import html
from telegram import Update
from telegram.ext import ContextTypes

async def onabusefilter(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Enable abuse filter."""
    if update.effective_user.id != OWNER_ID:
        return
    await asyncio.to_thread(save_setting, "abuse_filter", "on")
    await update.effective_message.reply_html("🛡️ <b>Aʙᴜsᴇ Fɪʟᴛᴇʀ Eɴᴀʙʟᴇᴅ</b>\n\nBot will now automatically filter restricted words.")

async def offabusefilter(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Disable abuse filter."""
    if update.effective_user.id != OWNER_ID:
        return
    await asyncio.to_thread(save_setting, "abuse_filter", "off")
    await update.effective_message.reply_html("🔓 <b>Aʙᴜsᴇ Fɪʟᴛᴇʀ Dɪsᴀʙʟᴇᴅ</b>\n\nRestriction system is now off.")

async def addabuse(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Add a word to the abuse filter."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    if not ctx.args:
        return await msg.reply_text("⚠️ Usage: /addabuse [word]")

    word = " ".join(ctx.args).lower()
    words = await asyncio.to_thread(get_setting_json, "abuse_words", []) or []
    if word not in words:
        words.append(word)
        await asyncio.to_thread(save_setting_json, "abuse_words", words)
        await msg.reply_html(f"✅ <b>Wᴏʀᴅ Aᴅᴅᴇᴅ</b>\n\n<code>{html.escape(word)}</code> is now restricted.")
    else:
        await msg.reply_text("ℹ️ Word already exists in filter.")

async def removeabuse(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Remove a word from the abuse filter."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    if not ctx.args:
        return await msg.reply_text("⚠️ Usage: /removeabuse [word]")

    word = " ".join(ctx.args).lower()
    words = await asyncio.to_thread(get_setting_json, "abuse_words", []) or []
    if word in words:
        words.remove(word)
        await asyncio.to_thread(save_setting_json, "abuse_words", words)
        await msg.reply_html(f"🗑️ <b>Wᴏʀᴅ Rᴇᴍᴏᴠᴇᴅ</b>\n\n<code>{html.escape(word)}</code> is no longer restricted.")
    else:
        await msg.reply_text("⚠️ Word not found in filter.")

async def listabuse(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """List all restricted words."""
    if update.effective_user.id != OWNER_ID:
        return

    words = await asyncio.to_thread(get_setting_json, "abuse_words", []) or []
    if not words:
        return await update.effective_message.reply_text("📭 Abuse filter is empty.")

    text = "🛡️ <b>Aʙᴜsᴇ Fɪʟᴛᴇʀ Lɪsᴛ</b>\n"
    text += "━━━━━━━━━━━━━━━━━━━━━━\n"
    text += ", ".join([f"<code>{html.escape(w)}</code>" for w in words])
    
    await update.effective_message.reply_html(text)

# ═══ MODULE: owner.gencoupon ═══

"""
🎟️ GENERATE COUPON - owner/gencoupon.py
Generate a redeemable coupon code.
Command: /gencoupon <amount> [group_id]
  amount: reward amount
  group_id: optional chat ID; if omitted → global coupon (any group)
"""

from telegram import Update
from telegram.ext import ContextTypes
import asyncio
import html
import random
import string
logger = get_logger(__name__)


def _random_code(length: int = 8) -> str:
    """Generate random alphanumeric code."""
    chars = string.ascii_uppercase + string.digits
    return ''.join(random.choice(chars) for _ in range(length))


async def gencoupon(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Generate a new coupon code."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message

    if len(ctx.args) < 1:
        await msg.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "/gencoupon <amount> [group_id]\n"
            "/gencoupon 2000            → global coupon\n"
            "/gencoupon 500 -100123456  → group-restricted coupon"
        )
        return

    try:
        amount = int(ctx.args[0])
        if amount <= 0:
            raise ValueError("Amount must be positive")
    except ValueError:
        await msg.reply_text("⚠️ Invalid amount. Must be a positive integer.")
        return

    group_id = None
    if len(ctx.args) >= 2:
        try:
            group_id = int(ctx.args[1])
        except ValueError:
            await msg.reply_text("⚠️ Invalid group_id. Must be an integer.")
            return

    # Generate unique code (avoid collisions by checking existing)
    coupons = await asyncio.to_thread(get_setting_json, "coupon_codes", {})
    for _ in range(10):  # try up to 10 times
        code = _random_code(8)
        if code not in coupons:
            break
    else:
        await msg.reply_text("⚠️ Failed to generate unique coupon code after 10 attempts.")
        return

    # Store coupon
    coupons[code] = {
        "amount": amount,
        "group_id": group_id,  # None for global, int for group-restricted
        "used_by": {}  # {user_id: timestamp}
    }
    await asyncio.to_thread(save_setting_json, "coupon_codes", coupons)

    group_txt = f"group <code>{group_id}</code>" if group_id is not None else "all groups (global)"
    await msg.reply_html(
        f"🎟️ <b>Coupon Generated</b>\n\n"
        f"🔤 Code: <code>{code}</code>\n"
        f"💰 Amount: <b>${amount:,}</b>\n"
        f"🌐 Scope: {group_txt}"
    )

# ═══ MODULE: owner.groups.commands ═══

"""
👥 GROUP MANAGEMENT - owner/groups/commands.py
Commands for managing group-specific bans.
"""
import html
logger = get_logger(__name__)
from telegram import Update
from telegram.ext import ContextTypes

import asyncio


async def _resolve_target(ctx: ContextTypes.DEFAULT_TYPE, args: list, msg) -> tuple[int | None, str]:
    """Resolve target user from reply, @username, or user ID."""
    target = None
    reason = ""

    if msg.reply_to_message and msg.reply_to_message.from_user:
        target = msg.reply_to_message.from_user.id
        reason = " ".join(args) if args else ""
        return target, reason

    if not args:
        return None, ""

    first_arg = args[0]

    # @username
    if first_arg.startswith("@"):
        username = first_arg[1:]
        try:
            chat = await ctx.bot.get_chat(f"@{username}")
            if chat.type == "private":
                target = chat.id
                reason = " ".join(args[1:])
                return target, reason
        except Exception:
            pass
        # Fallback: search in database
        all_users = await asyncio.to_thread(list_all_users)
        for uid, data in all_users:
            if data.get("username", "").lower() == username.lower():
                target = int(str(uid).split(":")[-1])
                reason = " ".join(args[1:])
                return target, reason
        return None, ""

    # Integer ID
    try:
        target = int(first_arg)
        reason = " ".join(args[1:])
        return target, reason
    except (ValueError, IndexError):
        return None, ""


async def groupban(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Ban a user from groups only."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    target, reason = await _resolve_target(ctx, ctx.args or [], msg)

    if not target:
        await msg.reply_html("⚠️ <b>Usage:</b> /groupban [reply/@username/id] [reason]")
        return

    try:
        await asyncio.to_thread(update_user_atomic, str(target), set_fields={"group_banned": True, "group_ban_reason": reason})

        text = f"🚫 <b>Gʀᴏᴜᴘ Bᴀɴ</b>\n\n"
        text += f"👤 ID: <code>{target}</code>\n"
        text += f"📉 Status: <b>Restricted from all groups</b>"
        if reason:
            text += f"\n📝 Reason: <i>{html.escape(reason)}</i>"

        await msg.reply_html(text)
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error: {html.escape(str(exc))}")


async def groupunban(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Unban a user from groups."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    target, _ = await _resolve_target(ctx, ctx.args or [], msg)

    if not target:
        await msg.reply_text("⚠️ Reply to a user or provide @username/user ID.")
        return

    try:
        await asyncio.to_thread(update_user_atomic, str(target), set_fields={"group_banned": False})

        await msg.reply_html(f"✅ <b>Gʀᴏᴜᴘ Unʙᴀɴ</b>\n\n👤 ID: <code>{target}</code>\n📈 Group access restored.")
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error: {html.escape(str(exc))}")

# ═══ MODULE: owner.groups.group_control ═══

"""
👑 GROUP CONTROL - owner/groups/group_control.py
Owner provides a group ID; the bot (already admin) executes Telegram API actions.
"""
import html
import asyncio
from typing import Optional
from telegram import Update, Chat
from telegram.ext import ContextTypes
from telegram.error import TelegramError
logger = get_logger(__name__)


def _owner_only(update: Update) -> bool:
    return update.effective_user is not None and update.effective_user.id == OWNER_ID


def _parse_group_id(ctx: ContextTypes.DEFAULT_TYPE) -> Optional[int]:
    if not ctx.args:
        return None
    try:
        return int(ctx.args[0])
    except (ValueError, IndexError):
        return None


async def _fetch_chat_info(bot, chat_id: int) -> Optional[str]:
    try:
        chat = await bot.get_chat(chat_id)
        lines = [f"📋 <b>Group Info</b>\n"]
        lines.append(f"ID: <code>{chat.id}</code>")
        lines.append(f"Title: {html.escape(chat.title or 'N/A')}")
        lines.append(f"Type: {chat.type}")
        if chat.username:
            lines.append(f"Username: @{chat.username}")
        if chat.description:
            desc = chat.description[:200]
            lines.append(f"Description: {html.escape(desc)}")
        try:
            count = await chat.get_member_count()
            lines.append(f"Member Count: {count}")
        except Exception:
            logger.debug("Failed to fetch member count for chat %s", chat_id)
            lines.append(f"Member Count: ?")
        if chat.linked_chat_id:
            lines.append(f"Linked Channel: <code>{chat.linked_chat_id}</code>")
        if getattr(chat, 'slow_mode_delay', None):
            lines.append(f"Slow Mode: {chat.slow_mode_delay}s")
        if getattr(chat, 'is_forum', False):
            lines.append(f"Forum: ✅")
        if getattr(chat, 'has_private_forwards', False):
            lines.append(f"Private Forwards: ✅")
        if getattr(chat, 'has_protected_content', False):
            lines.append(f"Protected Content: ✅")
        return "\n".join(lines)
    except TelegramError as e:
        return f"⚠️ Error fetching group: {html.escape(str(e))}"


async def group_info(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_info [group_id]</code>")
        return
    msg = await update.effective_message.reply_text("Fetching group info...")
    info_text = await _fetch_chat_info(update.get_bot(), chat_id)
    await msg.edit_text(info_text, parse_mode="HTML")


async def group_admins(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_admins [group_id]</code>")
        return
    msg = await update.effective_message.reply_text("Fetching admins...")
    try:
        admins = await update.get_bot().get_chat_administrators(chat_id)
        lines = [f"👑 <b>Admins of</b> <code>{chat_id}</code>\n"]
        for a in admins:
            user = a.user
            title = f" — {html.escape(a.custom_title)}" if a.custom_title else ""
            status = "👑 Owner" if a.status == "creator" else "🛡️ Admin"
            name = html.escape(user.full_name or user.first_name or str(user.id))
            lines.append(f"{status} <a href='tg://user?id={user.id}'>{name}</a> ({user.id}){title}")
        await msg.edit_text("\n".join(lines), parse_mode="HTML")
    except TelegramError as e:
        await msg.edit_text(f"⚠️ Error: {html.escape(str(e))}")


async def group_invitelink(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_invitelink [group_id]</code>")
        return
    msg = await update.effective_message.reply_text("Generating invite link...")
    try:
        link = await update.get_bot().export_chat_invite_link(chat_id)
        await msg.edit_text(
            f"🔗 <b>Invite Link</b>\n\n"
            f"Group: <code>{chat_id}</code>\n"
            f"Link: <code>{html.escape(link)}</code>\n\n"
            f"<a href='{html.escape(link)}'>Open Link</a>",
            parse_mode="HTML"
        )
    except TelegramError as e:
        await msg.edit_text(f"⚠️ Error: {html.escape(str(e))}")


async def group_settitle(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id or len(ctx.args) < 2:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_settitle [group_id] [new title]</code>")
        return
    new_title = " ".join(ctx.args[1:])[:128]
    try:
        await update.get_bot().set_chat_title(chat_id, new_title)
        await update.effective_message.reply_html(
            f"✅ <b>Title updated</b>\n\nGroup: <code>{chat_id}</code>\nNew: {html.escape(new_title)}"
        )
    except TelegramError as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_setdescription(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id or len(ctx.args) < 2:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_setdescription [group_id] [description]</code>")
        return
    new_desc = " ".join(ctx.args[1:])[:255]
    try:
        await update.get_bot().set_chat_description(chat_id, new_desc)
        await update.effective_message.reply_html(
            f"✅ <b>Description updated</b>\n\nGroup: <code>{chat_id}</code>\n"
            f"New: {html.escape(new_desc)}"
        )
    except TelegramError as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_leave(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_leave [group_id]</code>")
        return
    try:
        await update.get_bot().leave_chat(chat_id)
        await update.effective_message.reply_html(f"👋 <b>Left group</b> <code>{chat_id}</code>")
    except TelegramError as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_delete(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_delete [group_id]</code>")
        return
    try:
        await asyncio.to_thread(unregister_chat, chat_id)
        await update.effective_message.reply_html(
            f"🗑️ <b>Group data deleted</b>\n\n"
            f"ID: <code>{chat_id}</code>\n"
            f"All local DB records removed."
        )
    except Exception as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_banuser(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    if not ctx.args or len(ctx.args) < 2:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_banuser [group_id] [user_id] [reason]</code>")
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Invalid group ID")
        return
    try:
        target_id = int(ctx.args[1])
    except ValueError:
        await update.effective_message.reply_html("⚠️ Invalid user ID")
        return
    reason = " ".join(ctx.args[2:]) if len(ctx.args) > 2 else ""
    try:
        await update.get_bot().ban_chat_member(chat_id, target_id, revoke_messages=True)
        text = f"🚫 <b>User banned from group</b>\n\n"
        text += f"Group: <code>{chat_id}</code>\n"
        text += f"User: <code>{target_id}</code>"
        if reason:
            text += f"\nReason: {html.escape(reason)}"
        await update.effective_message.reply_html(text)
    except TelegramError as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_unbanuser(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    if not ctx.args or len(ctx.args) < 2:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_unbanuser [group_id] [user_id]</code>")
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Invalid group ID")
        return
    try:
        target_id = int(ctx.args[1])
    except ValueError:
        await update.effective_message.reply_html("⚠️ Invalid user ID")
        return
    try:
        await update.get_bot().unban_chat_member(chat_id, target_id)
        await update.effective_message.reply_html(
            f"✅ <b>User unbanned</b>\n\nGroup: <code>{chat_id}</code>\nUser: <code>{target_id}</code>"
        )
    except TelegramError as e:
        await update.effective_message.reply_html(f"⚠️ Error: {html.escape(str(e))}")


async def group_settings(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    if not _owner_only(update):
        return
    chat_id = _parse_group_id(ctx)
    if not chat_id:
        await update.effective_message.reply_html("⚠️ Usage: <code>/group_settings [group_id]</code>")
        return
    msg = await update.effective_message.reply_text("Fetching settings...")
    try:
        settings = await get_group_settings(chat_id)
        lines = [f"⚙️ <b>Bot Settings for</b> <code>{chat_id}</code>\n"]
        for key, val in settings.items():
            if isinstance(val, bool):
                val_str = "✅" if val else "⚠️"
            elif val is None:
                val_str = "—"
            else:
                val_str = html.escape(str(val))
            lines.append(f"<b>{key}:</b> {val_str}")
        await msg.edit_text("\n".join(lines), parse_mode="HTML")
    except Exception as e:
        await msg.edit_text(f"⚠️ Error: {html.escape(str(e))}")


__all__ = [
    "group_info", "group_admins", "group_invitelink",
    "group_settitle", "group_setdescription",
    "group_leave", "group_delete",
    "group_banuser", "group_unbanuser",
    "group_settings",
]

# ═══ MODULE: owner.offbot ═══

"""
⚡ OFFBOT — owner/offbot.py
Luxury toggle panel for selectively disabling bot categories.
Fixed: callback now edits in-place instead of sending duplicate messages.
"""

import asyncio
import html
import time

from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes


BOT_OFF_KEY = "bot_off_categories"

# ── Category registry ─────────────────────────────────────────────────────────
offbot__CATEGORIES: dict[str, dict] = {
    "ai":      {"label": "🧠 AI Chat",       "emoji": "🧠"},
    "games":   {"label": "🎮 Games",          "emoji": "🎮"},
    "fun":     {"label": "🎭 Fun & Create",   "emoji": "🎭"},
    "economy": {"label": "💰 Economy",        "emoji": "💰"},
    "admin":   {"label": "🛡️ Admin Tools",    "emoji": "🛡️"},
    "all":     {"label": "🔴 Whole Bot",      "emoji": "🔴"},
}

_DIV = "▰▱" * 16


# ── Cached helper ──────────────────────────────────────────────────────────────
_BOT_OFF_CACHE: tuple[float, set[str]] | None = None
_BOT_OFF_CACHE_TTL = 10  # seconds

async def _get_disabled() -> set[str]:
    """Check which categories are disabled. Results cached for 10s."""
    global _BOT_OFF_CACHE
    now = time.time()
    if _BOT_OFF_CACHE and (now - _BOT_OFF_CACHE[0]) < _BOT_OFF_CACHE_TTL:
        return _BOT_OFF_CACHE[1]
    raw = await asyncio.to_thread(get_setting_json, BOT_OFF_KEY, []) or []
    if not isinstance(raw, list):
        result = set()
    else:
        result = {str(item) for item in raw if str(item) in offbot__CATEGORIES}
    _BOT_OFF_CACHE = (now, result)
    return result


async def bot_category_disabled(category: str) -> bool:
    """Check if a bot category is disabled (called by bot_state_guard)."""
    disabled = await _get_disabled()
    return "all" in disabled or category in disabled


def _build_menu_text(disabled: set[str]) -> str:
    if not disabled:
        status_line = "🟢 <b>All systems online</b>"
    elif "all" in disabled:
        status_line = "🔴 <b>Entire bot in maintenance mode</b>"
    else:
        names = ", ".join(offbot__CATEGORIES[k]["label"] for k in offbot__CATEGORIES if k in disabled)
        status_line = f"🟡 <b>Disabled:</b> {html.escape(names)}"

    return (
        "⚡ <b>Bot Availability Control</b>\n"
        f"<code>{_DIV}</code>\n\n"
        f"{status_line}\n\n"
        "<i>Tap a category to toggle it on/off.\n"
        "✅ = currently disabled  |  tap again to re-enable</i>"
    )


def _build_keyboard(disabled: set[str]) -> InlineKeyboardMarkup:
    def _btn(key: str) -> InlineKeyboardButton:
        cat = offbot__CATEGORIES[key]
        active = key in disabled
        prefix = "✅ " if active else ""
        return InlineKeyboardButton(f"{prefix}{cat['label']}", callback_data=f"offbot_toggle:{key}")

    rows = [
        [_btn("ai"),    _btn("games")],
        [_btn("fun"),   _btn("economy")],
        [_btn("admin"), _btn("all")],
        [
            InlineKeyboardButton("✔ Enable All", callback_data="offbot_clear"),
            InlineKeyboardButton("✖ Close",      callback_data="offbot_close"),
        ],
    ]
    return InlineKeyboardMarkup(rows)


# ── Commands ──────────────────────────────────────────────────────────────────
async def offbot(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the bot availability control panel."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    if not msg:
        return

    disabled = await _get_disabled()
    await msg.reply_html(
        _build_menu_text(disabled),
        reply_markup=_build_keyboard(disabled),
    )


# ── Callback handler ──────────────────────────────────────────────────────────
async def offbot_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle toggle/clear/close actions — always edits in-place."""
    q = update.callback_query
    if not q:
        return

    if q.from_user.id != OWNER_ID:
        await q.answer("Owner only.", show_alert=True)
        return

    global _BOT_OFF_CACHE
    data = q.data or ""
    disabled = await _get_disabled()

    if data == "offbot_close":
        await q.answer("Closed")
        try:
            await q.message.delete()
        except Exception:
            logger.error("Unexpected error", exc_info=True)
        return

    if data == "offbot_clear":
        await asyncio.to_thread(save_setting_json, BOT_OFF_KEY, [])
        _BOT_OFF_CACHE = None
        disabled = set()
        await q.answer("✅ All sections re-enabled")

    elif data.startswith("offbot_toggle:"):
        key = data.split(":", 1)[1]
        if key not in offbot__CATEGORIES:
            await q.answer("Unknown category")
            return

        if key == "all":
            # Toggle entire bot
            disabled = {"all"} if "all" not in disabled else set()
        else:
            # Remove "all" override when toggling individual category
            disabled.discard("all")
            if key in disabled:
                disabled.discard(key)
                await q.answer(f"✅ {offbot__CATEGORIES[key]['label']} re-enabled")
            else:
                disabled.add(key)
                await q.answer(f"🔴 {offbot__CATEGORIES[key]['label']} disabled")

        await asyncio.to_thread(save_setting_json, BOT_OFF_KEY, sorted(disabled))
        _BOT_OFF_CACHE = None

    # Edit the original message in-place
    try:
        await q.edit_message_text(
            _build_menu_text(disabled),
            reply_markup=_build_keyboard(disabled),
            parse_mode="HTML",
        )
    except Exception:
        # Message unchanged — just answer silently
        try:
            await q.answer()
        except Exception:
            logger.error("Unexpected error", exc_info=True)

