# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# RENDERING
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def _format_category(key: str) -> str:
    cat = ownerguide__CATEGORIES[key]
    out: list[str] = []
    out.append(section_title(cat["title"], cat["icon"]))
    out.append(f"<i>{html.escape(cat['sub'])}</i>")
    out.append(divider())
    for cmd, desc in cat["cmds"]:
        if not cmd:
            out.append("")
            continue
        if cmd.startswith("──") or cmd.startswith("Prefixes"):
            out.append(f"<b>{html.escape(cmd)}</b>")
            continue
        # Format: small command + bold-ish description
        # Avoid HTML-escape inside <code> for cmd since it's meant verbatim
        out.append(f"  <code>{html.escape(cmd)}</code>  {small(html.escape(desc))}")
    return "\n".join(out)


def _main_menu_text() -> str:
    lines: list[str] = []
    lines.append(section_title("Owner Guide", ICONS["crown"]))
    lines.append(f"<i>{small('Full command reference, organized by category.')}</i>")
    lines.append(divider())
    lines.append(small("Tap a category below to view its commands."))
    lines.append("")
    for key in ownerguide__CAT_ORDER:
        cat = ownerguide__CATEGORIES[key]
        n = len([c for c, d in cat["cmds"] if c and not c.startswith("──") and not c.startswith("Prefixes")])
        lines.append(f"  {cat['icon']}  <b>{cat['title']}</b>  {small(cat['sub'])}  {small(f'({n} cmds)')}")
    lines.append(divider())
    lines.append(small("Total categories: ") + bold(str(len(ownerguide__CAT_ORDER))))
    return "\n".join(lines)


def build_keyboard(category: str | None = None) -> InlineKeyboardMarkup:
    rows: list[list[InlineKeyboardButton]] = []
    if category is None:
        # Main menu — 2-col grid
        pairs = [ownerguide__CAT_ORDER[i:i + 2] for i in range(0, len(ownerguide__CAT_ORDER), 2)]
        for pair in pairs:
            row = []
            for k in pair:
                cat = ownerguide__CATEGORIES[k]
                row.append(InlineKeyboardButton(
                    f"{cat['icon']} {cat['title']}",
                    callback_data=f"ownerg:{k}",
                ))
            rows.append(row)
        rows.append([InlineKeyboardButton("✖ Close", callback_data="ownerg:close")])
    else:
        # Sub-section: back / prev / next / close
        try:
            idx = ownerguide__CAT_ORDER.index(category)
        except ValueError:
            idx = 0
        prev_key = ownerguide__CAT_ORDER[(idx - 1) % len(ownerguide__CAT_ORDER)]
        next_key = ownerguide__CAT_ORDER[(idx + 1) % len(ownerguide__CAT_ORDER)]
        rows.append([
            InlineKeyboardButton("⟵ Prev", callback_data=f"ownerg:{prev_key}"),
            InlineKeyboardButton("🏠 Menu", callback_data="ownerg:main"),
            InlineKeyboardButton("Next ⟶", callback_data=f"ownerg:{next_key}"),
        ])
        rows.append([InlineKeyboardButton("✖ Close", callback_data="ownerg:close")])
    return InlineKeyboardMarkup(rows)


# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# COMMANDS
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
async def ownerguide(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the stylized owner guide. Optional arg jumps to a category."""
    if not update.effective_user or update.effective_user.id != OWNER_ID:
        return
    msg = update.effective_message
    if not msg:
        return

    arg = (ctx.args[0].lower() if ctx.args else None)
    if arg and arg in ownerguide__CATEGORIES:
        text = _format_category(arg)
        kb = build_keyboard(arg)
    else:
        text = _main_menu_text()
        kb = build_keyboard()
    await msg.reply_html(text, reply_markup=kb)


async def ownerguide_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle inline-button navigation in the owner guide."""
    q = update.callback_query
    if not q:
        return
    if not q.from_user or q.from_user.id != OWNER_ID:
        await q.answer("Owner only.", show_alert=True)
        return
    data = q.data or ""
    if not data.startswith("ownerg:"):
        return
    action = data.split(":", 1)[1]
    if action == "close":
        try:
            await q.answer("Closed")
            await q.delete_message()
        except Exception:
            try:
                await q.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass
        return
    if action == "main":
        text = _main_menu_text()
        kb = build_keyboard()
        try:
            await q.answer()
            await q.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception:
            logger.exception("ownerguide: main menu edit failed")
        return
    if action in ownerguide__CATEGORIES:
        text = _format_category(action)
        kb = build_keyboard(action)
        # Truncate if very long (Telegram 4096 limit)
        if len(text) > 4000:
            text = text[:3980] + "\n\n<i>…truncated. Open /ownerguide for full list.</i>"
        try:
            await q.answer()
            await q.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception:
            logger.exception("ownerguide: category edit failed")
        return
    await q.answer("Unknown action.")


__all__ = ["ownerguide", "ownerguide_callback", "CATEGORIES"]

