# ── Keyboard builder ──────────────────────────────────────────────────────────
def build_help_keyboard(category: str | None = None) -> InlineKeyboardMarkup:
    rows: list[list[InlineKeyboardButton]] = []

    if category is None:
        # Main menu — 2-column grid
        pairs = [_CAT_ORDER[i:i + 2] for i in range(0, len(_CAT_ORDER), 2)]
        for pair in pairs:
            row = []
            for key in pair:
                cat = CATEGORIES[key]
                row.append(InlineKeyboardButton(
                    f"{cat['icon']} {cat['title']}",
                    callback_data=f"ownerhelp:{key}"
                ))
            rows.append(row)
        rows.append([InlineKeyboardButton("✖ Close", callback_data="own_close")])
    else:
        rows.append([InlineKeyboardButton("⟵ Back", callback_data="ownerhelp:main")])
        rows.append([InlineKeyboardButton("✖ Close", callback_data="own_close")])

    return InlineKeyboardMarkup(rows)


# ── Command ───────────────────────────────────────────────────────────────────
async def ownerhelp(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show luxury owner command reference."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    if not msg:
        return

    text = (
        f"{_HDR} <b>Owner Command Reference</b>\n"
        f"<code>{_DIV}</code>\n\n"
        "Select a category below — all commands listed with usage.\n"
        "<i>Restricted to owner ID only.</i>"
    )
    await msg.reply_html(text, reply_markup=build_help_keyboard())


# ── Callback handler ──────────────────────────────────────────────────────────
async def ownerhelp_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    if q.from_user.id != OWNER_ID:
        await q.answer("Owner only.", show_alert=True)
        return

    data = q.data or ""
    if not data.startswith("ownerhelp:"):
        return

    category = data.split(":", 1)[1]
    await q.answer()

    if category == "main":
        text = (
            f"{_HDR} <b>Owner Command Reference</b>\n"
            f"<code>{_DIV}</code>\n\n"
            "Select a category to see all commands."
        )
        try:
            await q.edit_message_text(text, reply_markup=build_help_keyboard(), parse_mode="HTML")
        except Exception:
            logger.error("Unexpected error", exc_info=True)
        return

    if category not in CATEGORIES:
        return

    cat = CATEGORIES[category]
    lines: list[str] = [
        f"{cat['icon']} <b>{cat['title']}</b>",
        f"<code>{_SEP}</code>",
        "",
    ]
    for cmd in cat["cmds"]:
        if cmd == _SEP:
            lines.append(f"<code>{_SEP}</code>")
        elif cmd.startswith("──"):
            lines.append(f"\n<b>{cmd}</b>")
        elif cmd.startswith("Prefixes"):
            lines.append(f"<i>{cmd}</i>")
        else:
            lines.append(f"  {cmd}")

    text = "\n".join(lines)

    # Telegram message max ~4096 chars — truncate gracefully
    if len(text) > 4000:
        text = text[:3980] + "\n\n<i>…truncated. Use /ownerhelp for full list.</i>"

    try:
        await q.edit_message_text(text, reply_markup=build_help_keyboard(category), parse_mode="HTML")
    except Exception:
        logger.error("Unexpected error", exc_info=True)


__all__ = ["ownerhelp", "ownerhelp_callback", "CATEGORIES"]

