# =========================================
# 📊 BROADCAST STATS — owner/broadcast/stats.py
# Aggregated broadcast statistics wired into /stats command.
# =========================================
import time
from typing import Any


logger = get_logger(__name__)


def get_broadcast_stats() -> dict[str, Any]:
    """Return aggregated broadcast statistics for /stats command.

    Returns a dict with:
      - running: bool
      - current: dict | None (active broadcast state)
      - totals: dict (lifetime totals by type)
      - recent: list (last 5 broadcasts)
      - last_24h: dict (rolling 24h aggregates)
      - speed_24h_avg: float (avg msgs/sec over last 24h)
    """
    try:
        history = manager.get_history() or []
        s = manager.get_stats() or {}

        totals_by_type: dict[str, dict] = {}
        recent_24h: list = []
        total_sent_24h = 0
        total_failed_24h = 0
        total_elapsed_24h = 0.0
        cutoff_24h = time.time() - 86400

        for h in history:
            t = h.get("type", "unknown")
            entry = totals_by_type.setdefault(t, {
                "broadcasts": 0, "sent": 0, "failed": 0, "elapsed": 0.0,
            })
            entry["broadcasts"] += 1
            entry["sent"] += h.get("sent", 0)
            entry["failed"] += h.get("failed", 0)
            entry["elapsed"] += h.get("elapsed", 0.0)

            if h.get("timestamp", 0) > cutoff_24h:
                recent_24h.append(h)
                total_sent_24h += h.get("sent", 0)
                total_failed_24h += h.get("failed", 0)
                total_elapsed_24h += h.get("elapsed", 0.0)

        speed_24h_avg = (
            total_sent_24h / total_elapsed_24h if total_elapsed_24h > 0 else 0
        )
        success_rate_24h = (
            (total_sent_24h / (total_sent_24h + total_failed_24h) * 100)
            if (total_sent_24h + total_failed_24h) > 0 else 0
        )

        return {
            "running": s.get("running", False),
            "current": s if s.get("running") else None,
            "totals_by_type": totals_by_type,
            "recent": history[-5:][::-1],  # last 5, newest first
            "last_24h": {
                "broadcasts": len(recent_24h),
                "sent": total_sent_24h,
                "failed": total_failed_24h,
                "avg_speed": round(speed_24h_avg, 2),
                "success_rate": round(success_rate_24h, 1),
            },
            "lifetime": {
                "broadcasts": len(history),
                "sent": sum(h.get("sent", 0) for h in history),
                "failed": sum(h.get("failed", 0) for h in history),
            },
        }
    except Exception as exc:
        logger.debug(f"get_broadcast_stats failed: {exc}")
        return {
            "running": False,
            "current": None,
            "totals_by_type": {},
            "recent": [],
            "last_24h": {"broadcasts": 0, "sent": 0, "failed": 0, "avg_speed": 0, "success_rate": 0},
            "lifetime": {"broadcasts": 0, "sent": 0, "failed": 0},
        }


def format_broadcast_stats_for_stats() -> str:
    """Format broadcast stats for inclusion in /stats command output."""
    s = get_broadcast_stats()
    lines = ["📢 <b>Bʀᴏᴀᴅᴄᴀsᴛ Sᴛᴀᴛs</b>"]

    if s["running"]:
        cur = s["current"]
        lines.append(f"  🟢 <b>RUNNING</b> — {cur.get('type', '').upper()}")
        lines.append(f"  📤 Pʀᴏɢʀᴇss: {cur.get('sent', 0):,}/{cur.get('total', 0):,}")
        lines.append(f"  ⚡ Sᴘᴇᴇᴅ: {cur.get('speed', 0):.1f}/sec")
    else:
        lines.append("  ⚫ <b>Iᴅʟᴇ</b>")

    lt = s["lifetime"]
    lines.append(
        f"  📈 Lɪғᴇᴛɪᴍᴇ: {lt['broadcasts']} broadcasts, "
        f"{lt['sent']:,} sent, {lt['failed']:,} failed"
    )

    last_24 = s["last_24h"]
    if last_24["broadcasts"] > 0:
        lines.append(
            f"  ⏰ 24ʜ: {last_24['broadcasts']} broadcasts, "
            f"{last_24['sent']:,} sent ({last_24['success_rate']:.0f}% ok), "
            f"avg {last_24['avg_speed']:.1f}/sec"
        )

    return "\n".join(lines)

# ═══ MODULE: owner.stats ═══

"""
📊 STATS — owner/stats.py
Luxury live statistics dashboard for the bot owner.
Fixed: stats_callback now edits in-place; concurrent data fetch; ZeroDivision guards.
"""

import asyncio
import html
import time

from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes


logger = get_logger(__name__)

_DIV = "▰▱" * 16
_SEP = "─" * 30

_SLOT_ICON = {
    "available": "🟢", "active": "🟢",
    "full": "🔴", "failed": "🔴", "pending": "🟡",
}


def _fmt_bytes(n: int) -> str:
    if n >= 1_073_741_824:
        return f"{n / 1_073_741_824:.2f} GB"
    if n >= 1_048_576:
        return f"{n / 1_048_576:.2f} MB"
    return f"{n / 1_024:.2f} KB"


def _bar(value: int, total: int, width: int = 20) -> str:
    if total == 0:
        return "░" * width + " 0%"
    pct = min(value * 100 // total, 100)
    filled = pct * width // 100
    return "█" * filled + "░" * (width - filled) + f" {pct}%"


def _refresh_kb() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[
        InlineKeyboardButton("🔄 Refresh", callback_data="stats_refresh"),
        InlineKeyboardButton("✖ Close",   callback_data="own_close"),
    ]])


async def _build_stats_text() -> str:
    """Fetch all data concurrently and build the stats message."""
    now = int(time.time())

    db_stats, storage, all_users, all_chats, slot_status = await asyncio.gather(
        asyncio.to_thread(database_stats),
        asyncio.to_thread(get_storage_status),
        asyncio.to_thread(get_cached_all_users, list_all_users),
        asyncio.to_thread(get_cached_chats, get_registered_chats),
        asyncio.to_thread(lambda: get_slot_manager().get_slot_status()),
    )

    # ── User metrics ─────────────────────────────────────────────────────────
    total_users   = len(all_users)
    active_users  = 0
    premium_users = 0
    dm_verified   = 0
    banned_users  = 0
    total_balance = 0
    total_captures = 0
    total_rp      = 0

    for _, data in all_users:
        if not isinstance(data, dict):
            continue
        if data.get("last_seen", 0):
            active_users += 1
        if data.get("premium_until", 0) > now:
            premium_users += 1
        if data.get("dm_verified"):
            dm_verified += 1
        if data.get("banned"):
            banned_users += 1
        total_balance  += data.get("balance", 0) or 0
        total_captures += data.get("captures", 0) or 0
        total_rp       += data.get("rp", 0) or 0

    # ── Chat metrics ──────────────────────────────────────────────────────────
    groups     = [c for c in all_chats if c.get("type") in ("group", "supergroup")]
    supergroups = [c for c in groups if c.get("type") == "supergroup"]
    private_chats = [c for c in all_chats if c.get("type") == "private"]

    # ── MongoDB ───────────────────────────────────────────────────────────────
    mongo_slots  = storage.get("mongo_slots", [])
    active_mongo = storage.get("active_mongo_slot", "?")
    mode = db_stats.get("mode", "unknown")
    db_size = _fmt_bytes(db_stats.get("mongo_size", 0))
    alerts = storage.get("alerts", [])

    # ── Build text ────────────────────────────────────────────────────────────
    txt = (
        f"📊 <b>Live Statistics</b>\n"
        f"<code>{_DIV}</code>\n\n"

        f"👥 <b>USERS</b>\n"
        f"  ├ Total          <b>{total_users:,}</b>\n"
        f"  ├ DM Verified    <b>{dm_verified:,}</b>\n"
        f"  ├ Premium        <b>{premium_users:,}</b>\n"
        f"  ├ Active (seen)  <b>{active_users:,}</b>\n"
        f"  └ Banned         <b>{banned_users:,}</b>\n\n"

        f"🏠 <b>CHATS</b>\n"
        f"  ├ Groups         <b>{len(groups):,}</b>  ({len(supergroups):,} super)\n"
        f"  ├ Private DMs    <b>{len(private_chats):,}</b>\n"
        f"  └ Total Reg.     <b>{len(all_chats):,}</b>\n\n"

        f"💰 <b>ECONOMY</b>\n"
        f"  ├ Total Balance  <b>${total_balance:,}</b>\n"
        f"  ├ Captures       <b>{total_captures:,}</b>\n"
        f"  └ RP             <b>{total_rp:,}</b>\n\n"

        f"🗄️ <b>DATABASE</b>\n"
        f"  ├ Mode    <code>{mode}</code>\n"
        f"  ├ Size    <b>{db_size}</b>\n"
        f"  ├ Active  <b>P{active_mongo}</b>\n"
        f"  └ Slots   <b>{len(mongo_slots)}</b>\n\n"

        f"📦 <b>SMART SLOTS</b>\n"
    )

    for slot in slot_status.get("slots", []):
        icon = _SLOT_ICON.get(slot.get("state", ""), "⚪")
        flags = (" 🔄" if slot.get("syncing") else "") + (" ⏳" if slot.get("waiting") else "")
        txt += f"  {icon} {slot['name']}:  {slot['state']}{flags}\n"

    # ── TiDB Smart RU Optimizations ─────────────────────────────────────────
    if _use_tidb():
        tidb_section = ""
        try:
            dirty = tidb_dirty_count()
            inc = tidb_increment_count()
            with _last_seen_lock:
                ls_pending = len(_last_seen_buffer)
            with _TIDB_QUERY_CACHE_LOCK:
                qc_size = len(_TIDB_QUERY_CACHE)
            tidb_section = (
                f"\n⚡ <b>TiDB SMART RU</b>\n"
                f"  ├ Dirty pending  <b>{dirty}</b>\n"
                f"  ├ last_seen buf  <b>{ls_pending}</b>\n"
                f"  ├ Inc coalesce   <b>{inc}</b>\n"
                f"  └ Query cache    <b>{qc_size}/100</b>\n"
            )
        except Exception:
            logger.warning("TiDB stats unavailable", exc_info=True)
            tidb_section = "\n⚡ <b>TiDB SMART RU</b>\n" "  └ (unavailable)\n"
        txt += tidb_section

    if alerts:
        txt += f"\n⚠️ <b>ALERTS ({len(alerts)})</b>\n"
        for a in alerts[:3]:
            txt += f"  └ {html.escape(str(a)[:60])}\n"

    # ── Broadcast stats (wires broadcast manager into /stats) ─────────────────
    try:
        txt += "\n" + format_broadcast_stats_for_stats() + "\n"
    except Exception as exc:
        logger.debug(f"broadcast stats unavailable: {exc}")

    return txt


# ── Command ───────────────────────────────────────────────────────────────────
async def stats(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Show live stats dashboard."""
    if update.effective_user.id != OWNER_ID:
        return

    msg = update.effective_message
    if not msg:
        return

    status_msg = await msg.reply_html("⏳ <b>Loading stats…</b>")
    try:
        text = await _build_stats_text()
        await status_msg.edit_text(text, parse_mode="HTML", reply_markup=_refresh_kb())
    except Exception as exc:
        logger.exception("Stats error")
        try:
            await status_msg.edit_text(f"⚠️ Error: {html.escape(str(exc))}")
        except Exception:
            logger.error("Unexpected error", exc_info=True)


# ── Callback — edits in-place ─────────────────────────────────────────────────
async def stats_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Refresh stats in-place (no new message)."""
    q = update.callback_query
    if not q:
        return
    if q.from_user.id != OWNER_ID:
        await q.answer("Owner only.", show_alert=True)
        return

    await q.answer("🔄 Refreshing…")
    try:
        text = await _build_stats_text()
        await q.edit_message_text(text, parse_mode="HTML", reply_markup=_refresh_kb())
    except Exception:
        logger.warning("Exception in stats_callback", exc_info=True)

