"""
👤 USER MANAGEMENT - owner/users/commands.py
Advanced user control system including bans, premium management, and balance adjustments.
"""
import asyncio
import html
import time
from typing import Union, Optional
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes


async def users__resolve_target(ctx: ContextTypes.DEFAULT_TYPE, args: list, msg) -> tuple[Optional[int], str]:
    """Resolve target user from reply, @username, or user ID.
    Returns (target_id, reason) tuple.
    """
    target = None
    reason = ""
    
    # Check if replying to a message
    if msg.reply_to_message and msg.reply_to_message.from_user:
        target = msg.reply_to_message.from_user.id
        reason = " ".join(args) if args else ""
        return target, reason
    
    if not args:
        return None, ""
    
    first_arg = args[0]
    
    # Check if it's a @username
    if first_arg.startswith("@"):
        username = first_arg[1:]  # Remove @
        try:
            # Try to get chat by username
            chat = await ctx.bot.get_chat(f"@{username}")
            if chat.type == "private":
                target = chat.id
            else:
                # For groups/channels, we can't ban them this way
                return None, ""
            reason = " ".join(args[1:])
            return target, reason
        except Exception:
            # Username not found, try to find in database
            all_users = await asyncio.to_thread(list_all_users)
            for uid, data in all_users:
                if data.get("username", "").lower() == username.lower():
                    target = int(str(uid).split(":")[-1])
                    reason = " ".join(args[1:])
                    return target, reason
            return None, ""
    
    # Try as integer ID
    try:
        target = int(first_arg)
        reason = " ".join(args[1:])
        return target, reason
    except (ValueError, IndexError):
        return None, ""


async def banuser(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Ban a user with reason. Support button included for the victim."""
    if update.effective_user.id != OWNER_ID:
        return
    
    msg = update.effective_message
    target, reason = await users__resolve_target(ctx, ctx.args or [], msg)
    
    if not target:
        await msg.reply_html("⚠️ <b>Usage:</b>\n.ban [reply/@username/userid] [reason]\nExample: .ban @username spamming")
        return
    
    try:

        await asyncio.to_thread(
            update_user_atomic,
            str(target),
            set_fields={"banned": True, "ban_reason": reason, "silent_ban": False, "gbanned": False, "group_banned": False}
        )

        try:
            _banned_cache.add(str(target))
        except Exception as e:
            logger.debug(f"Ban cache update failed: {e}")
        early_guards.ban_user(target)
    
        text = f"🔨 <b>Usᴇʀ Bᴀɴɴᴇᴅ</b>\n\n"
        text += f"👤 ID: <code>{target}</code>\n"
        text += f"📉 Status: <b>Removed from Leaderboards</b>"
        if reason:
            text += f"\n📝 Reason: <i>{html.escape(reason)}</i>"
        
        await msg.reply_html(text)
    
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error banning user: {html.escape(str(exc))}")

