    """Unban a previously banned user."""
    if update.effective_user.id != OWNER_ID:
        return
    
    msg = update.effective_message
    target, _ = await users__resolve_target(ctx, ctx.args or [], msg)
    
    if not target:
        await msg.reply_text("⚠️ Reply to a user or provide @username/user ID.")
        return
    
    try:

        await asyncio.to_thread(
            update_user_atomic,
            str(target),
            set_fields={"banned": False, "ban_reason": None, "silent_ban": False, "gbanned": False, "group_banned": False}
        )

        try:
            _banned_cache.discard(str(target))
        except Exception as e:
            logger.debug(f"Ban cache update failed: {e}")
        early_guards.unban_user(target)
    
        await msg.reply_html(f"✅ <b>Usᴇʀ Unʙᴀɴɴᴇᴅ</b>\n\n👤 ID: <code>{target}</code>\n📈 Bot access restored.")
    
    except Exception as exc:
        await msg.reply_text(f"⚠️ Error unbanning user: {html.escape(str(exc))}")

