# ═══ MODULE: sticker.sticker_clone ═══

# =========================================
# 🧸 STICKER CLONE — sticker/sticker_clone.py  v3.0
# Per-user lock, cache, PTB v21 support
# =========================================
import asyncio, html, io
from typing import Set
import telegram
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup, InputSticker
from telegram.error import BadRequest, TelegramError
from telegram.ext import ContextTypes

logger = get_logger(__name__)

try: _V21 = int(telegram.__version__.split(".")[0]) >= 21
except Exception: _V21 = False

_mongo = None; _db_col = None
PACK_LIMIT={"static":120,"animated":50,"video":50}
FMT_CHAR  ={"static":"s","animated":"a","video":"v"}
MIXED_PACK_LIMIT = 120
MAX_SLOTS =200


import threading
_user_locks: dict = {}
_user_locks_lock = threading.Lock()

async def sticker_clone__get_lock(uid):
    with _user_locks_lock:
        if uid not in _user_locks:
            _user_locks[uid] = asyncio.Lock()
        return _user_locks[uid]


def init_sticker_db(redis_client=None, mongo_db=None):
    global _mongo,_db_col
    _mongo=mongo_db
    _db_col=_mongo["sticker_packs"] if _mongo is not None else None

def sticker_clone__fmt(s):
    if s.is_animated: return "animated"
    if s.is_video:    return "video"
    return "static"

def _pack_name(uid, index, bot):
    idx="" if index==1 else f"_{index}"
    return f"anyy_{uid}{idx}_by_{bot.lower()}"

def _pack_title(user, bot):
    name=html.escape(user.first_name or user.username or "User")
    if len(name)>10: name=name[:7]+"..."
    return f"{name} | @{bot}"

async def _cache_get(uid, index):
    key = f"sp:{uid}:{index}"
    if _db_col is not None:
        try:
            doc=await _db_col.find_one({"_id":key})
            if doc: return doc.get("d")
        except Exception as e:
            logger.debug(f"Cache operation failed: {e}")
    return None

async def _cache_set(uid, index, name, count):
    data={"n":name,"c":count}; key=f"sp:{uid}:{index}"
    if _db_col is not None:
        try: await _db_col.update_one({"_id":key},{"$set":{"d":data}},upsert=True)
        except Exception as e:
            logger.debug(f"Cache operation failed: {e}")

async def _cache_del(uid, index):
    key=f"sp:{uid}:{index}"
    if _db_col is not None:
        try: await _db_col.delete_one({"_id":key})
        except Exception as e:
            logger.debug(f"Cache operation failed: {e}")

async def _find_slot(ctx, uid, sticker, bot, skip):
    for index in range(1, MAX_SLOTS + 1):
        name = _pack_name(uid, index, bot)
        if name in skip:
            continue
        cached = await _cache_get(uid, index)
        if cached and cached.get("n") == name:
            if cached.get("c", 0) < MIXED_PACK_LIMIT:
                return name, True, cached["c"], index
            continue
        try:
            pack = await ctx.bot.get_sticker_set(name)
            real = len(pack.stickers)
            if real < MIXED_PACK_LIMIT:
                return name, True, real, index
            continue
        except BadRequest as e:
            msg = str(e).lower()
            if any(x in msg for x in ("invalid", "not found", "stickerset_invalid")):
                return name, False, 0, index
        except TelegramError as e:
            logger.debug(f"Telegram error checking sticker pack {name}: {e}")
            return name, False, 0, index
        except Exception as e:
            logger.debug(f"Error finding slot: {e}")
            continue
    return None, False, 0, -1


def _build_input(sticker, buf):
    buf.seek(0)
    emoji = [sticker.emoji or "✨"]
    fmt = sticker_clone__fmt(sticker)
    if _V21:
        return InputSticker(sticker=buf, emoji_list=emoji, format=fmt)
    return InputSticker(sticker=buf, emoji_list=emoji)


async def _do_add(ctx, user, sticker, buf):
    uid = user.id
    bot = ctx.bot.username.lower()
    skip: Set[str] = set()
    async with await sticker_clone__get_lock(uid):
        for _ in range(MAX_SLOTS):
            name, exists, count, index = await _find_slot(ctx, uid, sticker, bot, skip)
            if name is None:
                raise RuntimeError(f"All {MAX_SLOTS} slots exhausted.")
            buf.seek(0)
            inp = _build_input(sticker, buf)
            try:
                if not exists:
                    title = _pack_title(user, bot)
                    kw = dict(user_id=uid, name=name, title=title, stickers=[inp])
                    if not _V21:
                        kw["sticker_format"] = sticker_clone__fmt(sticker)
                    await ctx.bot.create_new_sticker_set(**kw)
                    new_count = 1
                else:
                    await ctx.bot.add_sticker_to_set(user_id=uid, name=name, sticker=inp)
                    try:
                        updated = await ctx.bot.get_sticker_set(name)
                        new_count = len(updated.stickers)
                    except Exception:
                        new_count = count + 1
                if new_count >= MIXED_PACK_LIMIT:
                    await _cache_del(uid, index)
                else:
                    await _cache_set(uid, index, name, new_count)
                return name
            except BadRequest as e:
                err = str(e).lower()
                if "occupied" in err:
                    skip.add(name)
                    await _cache_del(uid, index)
                    continue
                raise RuntimeError(str(e)) from e
            except TelegramError as e:
                raise RuntimeError(str(e)) from e
    raise RuntimeError("Could not find a valid pack slot.")


async def add(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    msg=update.effective_message; user=update.effective_user
    if not user:
        return
    reply=msg.reply_to_message if msg else None
    if not msg or not reply or not reply.sticker:
        if msg: await msg.reply_text("❤‍🩹✨ Rᴇᴘʟʏ Tᴏ A Sᴛɪᴄᴋᴇʀ Tᴏ Aᴅᴅ Iᴛ Tᴏ Yᴏᴜʀ Pᴀᴄᴋ.")
        return
    wait=await msg.reply_text("✨🍂 Pʀᴏᴄᴇssɪɴɢ Pʟᴇᴀsᴇ Wᴀɪᴛ…")
    try:
        tg_file=await ctx.bot.get_file(reply.sticker.file_id)
        buf=io.BytesIO(); await tg_file.download_to_memory(buf); buf.seek(0)
        name=await _do_add(ctx,user,reply.sticker,buf)
        url=f"https://t.me/addstickers/{name}"
        kb=[[InlineKeyboardButton("Tᴀᴘ Tᴏ Vɪᴇᴡ Pᴀᴄᴋ 🧸",url=url)]]
        await wait.edit_text("✅ Sᴛɪᴄᴋᴇʀ Aᴅᴅᴇᴅ Tᴏ Yᴏᴜʀ Pᴀᴄᴋ 🌟",reply_markup=InlineKeyboardMarkup(kb))
    except Exception as e:
        err_text=f"⚠️ Fᴀɪʟᴇᴅ Tᴏ Aᴅᴅ Sᴛɪᴄᴋᴇʀ.\n{e}"
        try: await wait.edit_text(err_text)
        except Exception: await msg.reply_text(err_text)
        logger.warning("[sc/add] %s", e, exc_info=True)

# ═══ MODULE: sticker.sticker_reply ═══

# =========================================
# 🎨 STICKER REPLY — sticker/sticker_reply.py  v4.1 UNIFIED
# UNIFIED SYSTEM: Static + Animated stickers in ONE pool
# =========================================
import asyncio
import html
import random
from typing import Optional
from telegram import Update
from telegram.ext import ContextTypes

logger = get_logger(__name__)

# ─────────────────────────────────────────
# /addsticker — Owner adds sticker pack to UNIFIED pool
# Accepts ALL types: static, animated, video
# ─────────────────────────────────────────
async def addsticker(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Add sticker pack to unified pool (static + animated combined)."""
    msg = update.effective_message
    user = update.effective_user
    
    if not user or user.id != OWNER_ID:
        return
    if not msg:
        return
    
    pack_name = None
    if msg.reply_to_message and msg.reply_to_message.sticker:
        pack_name = msg.reply_to_message.sticker.set_name
    elif ctx.args:
        pack_name = (ctx.args or [""])[0]
    
    if not pack_name:
        return await msg.reply_html(
            "⚠️ <b>Aᴅᴅ Sᴛɪᴄᴋᴇʀ Pᴀᴄᴋ</b>\n\n"
            "Rᴇᴘʟʏ ᴛᴏ ᴀ sᴛɪᴄᴋᴇʀ + /addsticker\n"
            "Oʀ: /addsticker [pack_name]\n\n"
            "Aᴄᴄᴇᴘᴛs: Sᴛᴀᴛɪᴄ, Aɴɪᴍᴀᴛᴇᴅ, Vɪᴅᴇᴏ sᴛɪᴄᴋᴇʀs"
        )
    
    wait = await msg.reply_text("⏳ Loading sticker pack...")
    try:
        pack = await ctx.bot.get_sticker_set(pack_name)
        
        # Add ALL sticker types to unified pool (static + animated + video)
        stickers = [
            {
                "file_id": s.file_id,
                "emoji": s.emoji or "✨",
                "type": "animated" if s.is_animated or s.is_video else "static"
            }
            for s in pack.stickers
        ]
        
        # Get or create unified data
        data = await asyncio.to_thread(get_sticker_setting, "reply_stickers")
        if data is None:
            data = {"packs": {}, "pool": []}
        packs = data.get("packs", {})
        packs[pack_name] = stickers
        
        # Rebuild unified pool (ALL stickers together, no categories)
        pool = []
        for fids in packs.values():
            pool.extend(fids)
        
        data["packs"] = packs
        data["pool"] = pool
        await asyncio.to_thread(save_sticker_setting, "reply_stickers", data)
        invalidate_sticker_pool()
        
        # Count types for info
        static_count = sum(1 for s in stickers if s["type"] == "static")
        animated_count = sum(1 for s in stickers if s["type"] == "animated")
        
        await wait.edit_text(
            f"✅ <b>Sᴛɪᴄᴋᴇʀ Pᴀᴄᴋ Aᴅᴅᴇᴅ</b>\n"
            f"📦 Pᴀᴄᴋ: <code>{html.escape(pack_name)}</code>\n"
            f"🎨 Sᴛᴀᴛɪᴄ: <b>{static_count}</b>\n"
            f"🎬 Aɴɪᴍᴀᴛᴇᴅ: <b>{animated_count}</b>\n"
            f"📊 Tᴏᴛᴀʟ ᴘᴏᴏʟ: <b>{len(pool)}</b> (ᴜɴɪғɪᴇᴅ)",
            parse_mode="HTML"
        )
    except Exception as e:
        await wait.edit_text(f"⚠️ Fᴀɪʟᴇᴅ: {e}")


# ─────────────────────────────────────────
# /addgif — Owner adds GIF to UNIFIED pool
# GIFs are now part of the same sticker pool
# ─────────────────────────────────────────
async def addgif(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Add GIF to unified sticker pool."""
    msg = update.effective_message
    user = update.effective_user
    
    if not user or user.id != OWNER_ID:
        return
    if not msg:
        return
    
    anim = None
    if msg.reply_to_message:
        anim = msg.reply_to_message.animation or (
            msg.reply_to_message.document
            if msg.reply_to_message.document and msg.reply_to_message.document.mime_type == "video/mp4"
            else None
        )
    
    if not anim:
        return await msg.reply_html(
            "⚠️ <b>Aᴅᴅ GIF</b>\n\n"
            "Rᴇᴘʟʏ ᴛᴏ ᴀ GIF + /addgif\n\n"
            "GIFs ᴀʀᴇ ɴᴏᴡ ᴘᴀʀᴛ ᴏғ ᴛʜᴇ ᴜɴɪғɪᴇᴅ sᴛɪᴄᴋᴇʀ ᴘᴏᴏʟ."
        )
    
    # Add to unified sticker pool (not separate GIF storage)
    data = await asyncio.to_thread(get_sticker_setting, "reply_stickers") or {"packs": {}, "pool": []}
    gifs = data.get("gifs", [])
    gifs.append(anim.file_id)
    data["gifs"] = gifs
    
    # Also add to main pool for unified selection
    pool = data.get("pool", [])
    pool.append({
        "file_id": anim.file_id,
        "emoji": "🎬",
        "type": "gif"
    })
    data["pool"] = pool
    
    await asyncio.to_thread(save_sticker_setting, "reply_stickers", data)
    invalidate_sticker_pool()

    await msg.reply_html(
        f"✅ <b>Gɪғ Aᴅᴅᴇᴅ</b>\n"
        f"🎬 Tᴏᴛᴀʟ GIFs: <b>{len(gifs)}</b>\n"
        f"📊 Uɴɪғɪᴇᴅ ᴘᴏᴏʟ: <b>{len(pool)}</b>"
    )


# ─────────────────────────────────────────
# UNIFIED STICKER REPLY HANDLER
# Triggered when user replies to BOT's message with sticker
# Selects from ALL types (static + animated + GIF)
# ─────────────────────────────────────────
async def handle_sticker_reply(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handle sticker reply from unified pool."""
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    
    if not msg or not user or user.is_bot:
        return

    # Only trigger when replying to bot's message OR in DM
    is_dm = chat.type == "private"
    is_reply_to_bot = (
        msg.reply_to_message and
        msg.reply_to_message.from_user and
        msg.reply_to_message.from_user.id == ctx.bot.id
    )
    if not is_dm and not is_reply_to_bot:
        return

    sticker = msg.sticker
    if not sticker:
        return

    # Get unified pool (all types together) — heavy cache (5min TTL)
    data = await asyncio.to_thread(
        get_cached_sticker_pool,
        lambda: get_sticker_setting("reply_stickers") or {}
    )
    pool = data.get("pool", [])
    if not pool:
        return

    # Try emoji match first (works for all types)
    user_emoji = sticker.emoji
    if user_emoji:
        matched = [s for s in pool if isinstance(s, dict) and s.get("emoji") == user_emoji]
        if matched:
            chosen = random.choice(matched)
        else:
            chosen = random.choice(pool)
    else:
        chosen = random.choice(pool)

    # Get file_id (works for dict or string)
    reply_id = chosen.get("file_id") if isinstance(chosen, dict) else chosen
    sticker_type = chosen.get("type", "sticker") if isinstance(chosen, dict) else "sticker"
    
    try:
        # Send as sticker or animation based on type
        if sticker_type == "gif":
            if is_dm:
                await ctx.bot.send_animation(chat.id, reply_id)
            else:
                await msg.reply_animation(reply_id)
        else:
            if is_dm:
                await ctx.bot.send_sticker(chat.id, reply_id)
            else:
                await msg.reply_sticker(reply_id)
    except Exception as e:
        logger.debug(f"[sticker_reply] Send failed: {e}")


# ─────────────────────────────────────────
# UNIFIED GIF REPLY HANDLER
# Now uses the same unified pool
# ─────────────────────────────────────────
async def handle_gif_reply(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handle GIF reply from unified pool."""
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    
    if not msg or not user or user.is_bot:
        return
    
    is_reply_to_bot = (
        msg.reply_to_message and
        msg.reply_to_message.from_user and
        msg.reply_to_message.from_user.id == ctx.bot.id
    )
    if not is_reply_to_bot:
        return

    anim = msg.animation
    if not anim:
        return

    # Get unified pool (heavy cache, 5min TTL)
    data = await asyncio.to_thread(
        get_cached_sticker_pool,
        lambda: get_sticker_setting("reply_stickers") or {}
    )
    pool = data.get("pool", [])
    gifs = data.get("gifs", [])
    
    if not gifs and not pool:
        return
    
    # Try to send from unified pool
    try:
        if gifs:
            # Send random GIF from GIF-specific list
            await msg.reply_animation(random.choice(gifs))
        else:
            # Fallback to pool with type=gif
            gif_pool = [s for s in pool if isinstance(s, dict) and s.get("type") == "gif"]
            if gif_pool:
                chosen = random.choice(gif_pool)
                await msg.reply_animation(chosen["file_id"])
    except Exception as e:
        logger.debug(f"[gif_reply] Send failed: {e}")


def pool_input_pending(uid: Optional[int] = None) -> bool:
    """Check if there are pending sticker inputs in the pool.

    FIXED: Don't block AI globally - only block if specific user is in input mode.
    """
    return False


async def handle_pool_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle pool input for stickers.

    FIXED: Don't respond to messages - this was blocking ALL text input.
    """
    pass


async def pool_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle pool callback."""
    q = update.callback_query
    await q.answer("Pool callback processed")


async def replypool(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show unified pool stats."""
    msg = update.effective_message
    user = update.effective_user
    if not user or user.id != OWNER_ID:
        return
    if not msg:
        return
    
    data = await asyncio.to_thread(get_sticker_setting, "reply_stickers") or {}
    pool = data.get("pool", [])
    packs = data.get("packs", {})
    gifs = data.get("gifs", [])
    
    # Count types
    static_count = sum(1 for s in pool if isinstance(s, dict) and s.get("type") == "static")
    animated_count = sum(1 for s in pool if isinstance(s, dict) and s.get("type") == "animated")
    gif_count = sum(1 for s in pool if isinstance(s, dict) and s.get("type") == "gif")
    
    text = (
        f"🎨 <b>Uɴɪғɪᴇᴅ Sᴛɪᴄᴋᴇʀ Pᴏᴏʟ</b>\n\n"
        f"📦 Pᴀᴄᴋs: <b>{len(packs)}</b>\n"
        f"🎨 Sᴛᴀᴛɪᴄ: <b>{static_count}</b>\n"
        f"🎬 Aɴɪᴍᴀᴛᴇᴅ: <b>{animated_count}</b>\n"
        f"🎞️ GIFs: <b>{gif_count}</b>\n"
        f"📊 Tᴏᴛᴀʟ: <b>{len(pool)}</b>\n"
        f"🎁 GIF Sᴛᴏʀᴀɢᴇ: <b>{len(gifs)}</b>"
    )
    
    await msg.reply_html(text)

# ═══ MODULE: system.error_reporter ═══

import asyncio
import html
import logging
import time
import traceback

logger = logging.getLogger(__name__)

_sent_errors: dict[str, float] = {}
_DEDUP_WINDOW = 3600

_bot_ref = None
_owner_id: int = 0


def init(bot, owner_id: int) -> None:
    global _bot_ref, _owner_id
    _bot_ref = bot
    _owner_id = owner_id


def _signature(exc: BaseException, context: str = "") -> str:
    return f"{context}:{type(exc).__name__}:{str(exc)[:200]}"


def _cleanup() -> None:
    cutoff = time.time() - _DEDUP_WINDOW * 2
    for sig, ts in list(_sent_errors.items()):
        if ts < cutoff:
            del _sent_errors[sig]


async def report(exc: BaseException, context: str = "") -> None:
    global _bot_ref, _owner_id
    sig = _signature(exc, context)
    now = time.time()

    last = _sent_errors.get(sig)
    if last and now - last < _DEDUP_WINDOW:
        return

    _sent_errors[sig] = now
    _cleanup()

    if not _bot_ref or not _owner_id:
        logger.debug("error_reporter: bot/owner not set, skipping")
        return

    tb = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
    text = (
        f"\u26a0\ufe0f <b>Bot Error</b>\n"
        f"<b>Type:</b> {html.escape(type(exc).__name__)}\n"
        f"<b>Context:</b> {html.escape(context)}\n"
        f"<b>Msg:</b> {html.escape(str(exc)[:500])}\n"
        f"<b>TB:</b>\n<pre>{html.escape(tb[-1500:])}</pre>"
    )

    try:
        await _bot_ref.send_message(chat_id=_owner_id, text=text, parse_mode="HTML")
    except Exception as e:
        logger.error("error_reporter: failed to send: %s", e)

# ═══ MODULE: utils.command_filters ═══

"""
Custom filters for handling commands with different prefixes.
Supports "!" prefix for admin commands in groups.
"""

from typing import Optional, Tuple
from telegram import Update, Message
from telegram.ext import filters


class CustomCommandFilter(filters.MessageFilter):
    """Filter for messages starting with custom command prefixes."""
    
    def __init__(self, prefixes: Tuple[str, ...] = ("!", "/")):
        self.prefixes = prefixes
        super().__init__()
    
    def filter(self, message: Message) -> Optional[bool]:
        """Check if message starts with any of the prefixes and contains a command."""
        if not message.text:
            return False
        
        text = message.text.strip()
        for prefix in self.prefixes:
            if text.startswith(prefix):
                # Check if there's a command after the prefix
                parts = text[len(prefix):].split(maxsplit=1)
                if parts and parts[0]:  # Command exists
                    return True
        return False
    
    def data_filter(self, message: Message) -> Optional[str]:
        """Returns the command data if message starts with a prefix, else None."""
        if not message.text:
            return None
        text = message.text.strip()
        for prefix in self.prefixes:
            if text.startswith(prefix):
                parts = text[len(prefix):].split(maxsplit=1)
                if parts and parts[0]:
                    return parts[0]
        return None


def extract_command(update: Update, prefixes: Tuple[str, ...] = ("!", "/")) -> Tuple[Optional[str], Optional[str]]:
    """
    Extract command and arguments from a message.
    
    Returns:
        Tuple of (command_name, arguments) or (None, None) if not a command.
    """
    message = update.effective_message
    if not message or not message.text:
        return None, None
    
    text = message.text.strip()
    for prefix in prefixes:
        if text.startswith(prefix):
            # Remove prefix and split into command and args
            rest = text[len(prefix):].strip()
            if not rest:
                return None, None
            
            parts = rest.split(maxsplit=1)
            command = parts[0].lower()
            args = parts[1] if len(parts) > 1 else ""
            return command, args
    
    return None, None


# Filter instances
BANG_COMMAND_FILTER = CustomCommandFilter(prefixes=("!",))
SLASH_COMMAND_FILTER = CustomCommandFilter(prefixes=("/",))
ALL_COMMAND_FILTER = CustomCommandFilter(prefixes=("!", "/"))


class BangCommandFilter(filters.MessageFilter):
    """Filter specifically for "!" commands."""
    
    def __init__(self, command: str):
        self.command = command.lower()
        super().__init__()
    
    def filter(self, message: Message) -> Optional[bool]:
        """Check if message is a "!" command matching the specified command."""
        if not message.text:
            return False
        
        text = message.text.strip()
        if text.startswith("!"):
            parts = text[1:].split(maxsplit=1)
            if parts and parts[0].lower() == self.command:
                return True
        return False


def bang_command(command: str) -> BangCommandFilter:
    """Create a filter for a specific "!" command."""
    return BangCommandFilter(command)


class DualCommandFilter(filters.MessageFilter):
    """Filter for commands that work with BOTH ! and / prefixes."""

    def __init__(self, command: str):
        self.command = command.lower()
        super().__init__()

    def filter(self, message: Message) -> Optional[bool]:
        """Check if message is a command matching the specified command with ! or / prefix."""
        if not message.text:
            return False

        text = message.text.strip()
        # Check ! prefix
        if text.startswith("!"):
            parts = text[1:].split(maxsplit=1)
            if parts and parts[0].lower() == self.command:
                return True
        # Check / prefix
        elif text.startswith("/"):
            # Handle both /command and /command@botusername
            parts = text[1:].split(maxsplit=1)
            if parts:
                cmd_part = parts[0].lower()
                # Match exact command or command@username
                if cmd_part == self.command or cmd_part.startswith(f"{self.command}@"):
                    return True
        return False


def dual_command(command: str) -> DualCommandFilter:
    """Create a filter for a specific command that works with both ! and / prefixes."""
    return DualCommandFilter(command)

# ═══ MODULE: utils.coupon_claim ═══

"""
🎟️ COUPON CLAIM - utils/coupon_claim.py
Redeem a coupon code.
Command: /code <coupon_code>
"""

import html
from telegram import Update
from telegram.ext import ContextTypes
import asyncio
import time
logger = get_logger(__name__)


async def coupon_claim(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Redeem a coupon code for balance."""
    msg = update.effective_message
    user = update.effective_user
    if not user or not msg:
        return

    if not ctx.args:
        await msg.reply_text("⚠️ <b>Usage:</b> /code <coupon_code>", parse_mode="HTML")
        return

    code = ctx.args[0].strip().upper()
    coupons = await asyncio.to_thread(get_setting_json, "coupon_codes", {})

    if code not in coupons:
        await msg.reply_text("⚠️ <b>Invalid coupon code.</b>", parse_mode="HTML")
        return

    coupon = coupons[code]
    amount = coupon.get("amount", 0)
    group_id = coupon.get("group_id")
    used_by = coupon.get("used_by", {})

    # Check per-user usage
    user_id_str = str(user.id)
    if user_id_str in used_by:
        await msg.reply_html("⚠️ <b>You have already claimed this coupon.</b>")
        return

    # Group restriction check
    if group_id is not None:
        chat = update.effective_chat
        if not chat or chat.id != group_id:
            await msg.reply_html(
                f"⚠️ <b>This coupon is restricted to group:</b>\n"
                f"<code>{html.escape(str(group_id))}</code>\n"
                f"You must claim it in that group."
            )
            return

    # Claim: increment user balance
    uid = str(user.id)
    try:
        await asyncio.to_thread(
            update_user_atomic,
            uid,
            inc_fields={"balance": amount}
        )
    except Exception as e:
        logger.error("Unexpected error", exc_info=True)
        logger.error("Coupon claim balance update error", exc_info=True)
        await msg.reply_text("⚠️ Error crediting balance. Try again later.")
        return

    # Mark as used
    used_by[user_id_str] = int(time.time())
    coupons[code] = coupon  # ensure persistence
    await asyncio.to_thread(save_setting_json, "coupon_codes", coupons)

    # Get new balance for confirmation
    user_data = await asyncio.to_thread(get_user, str(user.id))
    new_balance = user_data.get("balance", 0) if user_data else amount

    await msg.reply_html(
        f"🎟️ <b>Coupon Claimed!</b>\n\n"
        f"🔤 Code: <code>{html.escape(code)}</code>\n"
        f"💰 +<b>${amount:,}</b>\n"
        f"💳 New Balance: <b>${new_balance:,}</b>"
    )

# ═══ MODULE: utils.quote ═══

import os
import textwrap
import urllib.request
from io import BytesIO

# Graceful import for Pillow (not available on all platforms)
try:
    from PIL import Image, ImageDraw, ImageFont
    HAS_PIL = True
except ImportError:
    HAS_PIL = False

try:
    from pilmoji import Pilmoji
    HAS_PILMOJI = True
except ImportError:
    HAS_PILMOJI = False

from telegram import Update
from telegram.ext import ContextTypes

# Quote fonts: SemiBold for the name, Medium for the body — heavier strokes
# survive the downscale better. Local files first, verified TTF downloads after.
_FONT_NAME_CANDIDATES = [
    "Poppins-SemiBold.ttf",
    "Poppins-Bold.ttf",
    "Poppins-Medium.ttf",
    "quote_font.ttf",
    "utils/quote_font.ttf",
    "universal_quote_font.ttf",
]
_FONT_BODY_CANDIDATES = [
    "Poppins-Medium.ttf",
    "Poppins-Regular.ttf",
    "quote_font.ttf",
    "utils/quote_font.ttf",
    "universal_quote_font.ttf",
]
_FONT_NAME_URLS = (
    "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-SemiBold.ttf",
    "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Bold.ttf",
)
_FONT_BODY_URLS = (
    "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Medium.ttf",
    "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Regular.ttf",
)
_FONT_FALLBACK_URLS = (
    "https://github.com/google/fonts/raw/main/ofl/notosans/NotoSans%5Bwdth%2Cwght%5D.ttf",
    "https://github.com/google/fonts/raw/main/ofl/roboto/Roboto%5Bwdth%2Cwght%5D.ttf",
    "https://github.com/dejavu-fonts/dejavu-fonts/raw/master/ttf/DejaVuSans.ttf",
)


def _font_is_usable(path) -> bool:
    """A 404 HTML page can be hundreds of KB — only trust a file that loads."""
    if not path or not os.path.exists(path):
        return False
    try:
        ImageFont.truetype(path, 20)
        return True
    except Exception:
        return False


def _first_local_font(candidates):
    for _p in candidates:
        if _font_is_usable(_p):
            return _p
    return None


def _download_font(path, urls):
    for _url in tuple(urls) + tuple(_FONT_FALLBACK_URLS):
        try:
            urllib.request.urlretrieve(_url, path)
            if _font_is_usable(path):
                return path
        except Exception as e:
            logger.debug("Font download failed from %s: %s", _url, e)
    try:
        if os.path.exists(path):
            os.remove(path)
    except OSError:
        pass
    return None


FONT_PATH = _first_local_font(_FONT_BODY_CANDIDATES) or _download_font("Poppins-Medium.ttf", _FONT_BODY_URLS)
NAME_FONT_PATH = _first_local_font([p for p in _FONT_NAME_CANDIDATES if p != FONT_PATH])
if not NAME_FONT_PATH:
    NAME_FONT_PATH = _download_font("Poppins-SemiBold.ttf", _FONT_NAME_URLS)
if not NAME_FONT_PATH:
    NAME_FONT_PATH = FONT_PATH
if not FONT_PATH:
    FONT_PATH = NAME_FONT_PATH or "universal_quote_font.ttf"
if not _font_is_usable(FONT_PATH):
    logger.warning("No quote font could be downloaded; quote images use the default bitmap font")


async def make_quote(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message.reply_to_message:
        await update.message.reply_text("Reply to a message to quote it! ✨")
        return

    target_msg = update.message.reply_to_message
    user = target_msg.from_user
    
    # Handle all media types seamlessly
    text = target_msg.text or target_msg.caption
    if not text:
        if target_msg.sticker:
            text = "✨ [Sticker]"
        elif target_msg.photo:
            text = "📷 [Photo]"
        elif target_msg.video:
            text = "🎥 [Video]"
        elif target_msg.animation:
            text = "🎞️ [GIF]"
        else:
            text = "Media Message"

    # EXACT EXTRACTION: This literally copies whatever is in their Telegram name
    name = user.first_name
    if user.last_name:
        name += f" {user.last_name}"

    # Fetch User PFP
    photos = await context.bot.get_user_profile_photos(user.id)
    if photos.photos:
        file = await context.bot.get_file(photos.photos[0][-1].file_id)
        pfp_bytes = await file.download_as_bytearray()
        pfp = Image.open(BytesIO(pfp_bytes)).convert("RGBA")
    else:
        pfp = Image.new("RGBA", (150, 150), (40, 45, 55, 255))

    # --- 🌟 MAXIMUM QUALITY RENDERING ---------------------------------
    # 1. Lay the card out in small "design units".
    # 2. Pick the wrap width that keeps the card close to square so the whole
    #    512px sticker box is used (narrower lines => much larger text).
    # 3. Render at 4x the final size (up to 2048px) and LANCZOS-downscale once
    #    => fully antialiased glyphs, rounded corners and avatar mask.
    SS = 4
    MAX_DIM = 512

    try:
        name_font_d = ImageFont.truetype(NAME_FONT_PATH, 32)
        text_font_d = ImageFont.truetype(FONT_PATH, 36)
    except OSError:
        name_font_d = ImageFont.load_default()
        text_font_d = ImageFont.load_default()

    PAD_X, PAD_Y, NAME_BOTTOM_MARGIN = 35.0, 25.0, 15.0
    PFP_D, GAP_D, MARGIN_D = 110.0, 25.0, 20.0
    LINE_SPACING_D, BUBBLE_RADIUS_D = 15.0, 25.0

    def _wrap(width_chars: int) -> list[str]:
        out: list[str] = []
        for para in str(text).split("\n"):
            out.extend(textwrap.wrap(para, width=width_chars, break_long_words=True) or [""])
        return out or [""]

    def _measure(lines: list[str]) -> dict:
        name_bbox = name_font_d.getbbox(name)
        name_w = float(name_bbox[2] - name_bbox[0]) if name_bbox else 0.0
        name_h = float(name_bbox[3] - name_bbox[1]) if name_bbox else 0.0
        if not name_h:
            name_h = float(name_font_d.getbbox("A")[3] - name_font_d.getbbox("A")[1]) or 24.0
        if not name_w:
            name_w = float(name_font_d.getlength(name) or 30)
        line_bbox = text_font_d.getbbox("A")
        line_h = float(line_bbox[3] - line_bbox[1]) or 26.0
        max_line = max((float(text_font_d.getlength(l)) for l in lines), default=0.0)
        content_w = max(name_w, max_line) + 20.0
        text_h = len(lines) * line_h + max(0, len(lines) - 1) * LINE_SPACING_D
        bubble_w = content_w + PAD_X * 2
        bubble_h = PAD_Y + name_h + NAME_BOTTOM_MARGIN + text_h + PAD_Y
        return {
            "w": MARGIN_D + PFP_D + GAP_D + bubble_w + MARGIN_D,
            "h": MARGIN_D + max(PFP_D, bubble_h) + MARGIN_D,
            "name_h": name_h,
            "line_h": line_h,
            "bubble_w": bubble_w,
            "bubble_h": bubble_h,
        }

    lines, best_m = _wrap(40), None
    best_score = None
    for width_chars in range(44, 11, -1):
        cand = _wrap(width_chars)
        m = _measure(cand)
        score = (max(m["w"], m["h"]), -min(m["w"], m["h"]))
        if best_score is None or score < best_score:
            lines, best_m, best_score = cand, m, score

    canvas_w_d, canvas_h_d = best_m["w"], best_m["h"]
    fit = MAX_DIM / max(canvas_w_d, canvas_h_d)  # design -> final px
    K = fit * SS                                  # design -> render px

    def S(v):
        return float(v) * K

    render_w = max(1, int(round(canvas_w_d * K)))
    render_h = max(1, int(round(canvas_h_d * K)))

    try:
        name_font = ImageFont.truetype(NAME_FONT_PATH, max(8, int(round(32 * K))))
        text_font = ImageFont.truetype(FONT_PATH, max(8, int(round(36 * K))))
    except OSError:
        name_font = ImageFont.load_default()
        text_font = ImageFont.load_default()

    base_img = Image.new("RGBA", (render_w, render_h), (0, 0, 0, 0))
    draw = ImageDraw.Draw(base_img)

    bottom_y = render_h - S(MARGIN_D)
    b_x1 = S(MARGIN_D + PFP_D + GAP_D)
    b_y1 = bottom_y - S(best_m["bubble_h"])
    b_x2 = b_x1 + S(best_m["bubble_w"])
    b_y2 = bottom_y

    draw.rounded_rectangle([b_x1, b_y1, b_x2, b_y2], radius=S(BUBBLE_RADIUS_D), fill=(24, 34, 45, 255))

    colors = [(255, 136, 94), (255, 113, 113), (134, 143, 255), (101, 203, 101), (106, 204, 255)]
    name_color = colors[user.id % len(colors)]

    n_x = b_x1 + S(PAD_X)
    n_y = b_y1 + S(PAD_Y)
    curr_y = n_y + S(best_m["name_h"]) + S(NAME_BOTTOM_MARGIN)
    if HAS_PILMOJI:
        with Pilmoji(base_img) as pilmoji:
            pilmoji.text((n_x, n_y), name, font=name_font, fill=name_color)
            for line in lines:
                pilmoji.text((n_x, curr_y), line, font=text_font, fill=(255, 255, 255))
                curr_y += S(best_m["line_h"]) + S(LINE_SPACING_D)
    else:
        draw.text((n_x, n_y), name, font=name_font, fill=name_color)
        for line in lines:
            draw.text((n_x, curr_y), line, font=text_font, fill=(255, 255, 255))
            curr_y += S(best_m["line_h"]) + S(LINE_SPACING_D)

    # Avatar: largest available photo, LANCZOS to render size, smooth mask
    pfp_size = max(1, int(round(S(PFP_D))))
    pfp = pfp.resize((pfp_size, pfp_size), Image.Resampling.LANCZOS)
    mask = Image.new("L", (pfp_size, pfp_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, pfp_size - 1, pfp_size - 1), fill=255)
    base_img.paste(pfp, (int(round(S(MARGIN_D))), int(round(bottom_y - S(PFP_D)))), mask)

    # One LANCZOS downscale to the exact sticker size (long side == 512)
    final_w = max(1, int(round(canvas_w_d * fit)))
    final_h = max(1, int(round(canvas_h_d * fit)))
    base_img = base_img.resize((final_w, final_h), Image.Resampling.LANCZOS)

    # Lossless WEBP (method 6) first; fall back through a quality ladder and
    # finally a 0.8x shrink so the file always fits Telegram's 512 KB limit.
    final_image = BytesIO()
    final_image.name = "quote.webp"
    _LIMIT = 500_000
    _out = base_img
    for _attempt in range(2):
        for _params in (
            {"lossless": True, "quality": 100, "method": 6},
            {"lossless": False, "quality": 100, "method": 6},
            {"lossless": False, "quality": 80, "method": 6},
        ):
            final_image.seek(0)
            final_image.truncate()
            _out.save(final_image, format="WEBP", **_params)
            if final_image.getbuffer().nbytes <= _LIMIT:
                break
        if final_image.getbuffer().nbytes <= _LIMIT:
            break
        _out = _out.resize((max(1, int(_out.width * 0.8)), max(1, int(_out.height * 0.8))),
                           Image.Resampling.LANCZOS)
    final_image.seek(0)
    logger.info("Quote sticker: %dx%d, %d bytes (fit=%.2f, lines=%d, %s)",
                final_w, final_h, final_image.getbuffer().nbytes, fit, len(lines),
                "lossless" if _params.get("lossless") else "lossy")

    await update.message.reply_sticker(sticker=final_image)

    # Keep memory clean
    final_image.close()
    if _out is not base_img:
        _out.close()
    pfp.close()
    base_img.close()

