# ═══ MODULE: pkgs.auto_install ═══

"""
Smart Auto-Installer for Anyy Bot
- Detects platform (Android/Termux, Windows, Linux/Ubuntu)
- Uses platform-specific requirements file
- Falls back to alternatives if a package fails
- Handles Pillow rpath fix for Termux
"""

import glob
import zoneinfo
import importlib.metadata
import importlib.util
import os
import platform
import re
import subprocess
import sys
logger = get_logger(__name__)

# ═══════════════════════════════════════════
# 🔍 PLATFORM DETECTION
# ═══════════════════════════════════════════

def detect_platform() -> str:
    """Detect the current platform."""
    system = platform.system().lower()

    # Check for Windows
    if system == "windows":
        return "windows"

    # Check for proot-distro Ubuntu (Android running Ubuntu)
    # proot-distro runs Ubuntu inside Android, so check for proot first
    if os.environ.get("PROOT_DISTRO") or os.path.exists("/etc/os-release"):
        try:
            with open("/etc/os-release", "r") as f:
                content = f.read().lower()
                if "ubuntu" in content or "debian" in content:
                    # Check if running inside proot (Android host)
                    if os.path.exists("/data/data/com.termux") or os.environ.get("TERMUX_VERSION"):
                        return "proot_ubuntu"  # Ubuntu inside proot on Android
                    return "linux"  # Native Linux
        except (FileNotFoundError, PermissionError):
            pass

    # Check for Termux/Android (native, not proot)
    if os.path.exists("/data/data/com.termux") or os.environ.get("TERMUX_VERSION"):
        return "android"

    # Check for WSL (Windows Subsystem for Linux)
    try:
        with open("/proc/version", "r") as f:
            if "microsoft" in f.read().lower():
                return "wsl"
    except (FileNotFoundError, PermissionError):
        pass

    # Default to Linux
    return "linux"


def get_requirements_file(base_dir: str) -> str:
    """Get the platform-specific requirements file."""
    platform_name = detect_platform()
    platform_file = os.path.join(base_dir, f"requirements_{platform_name}.txt")
    default_file = os.path.join(base_dir, "requirements.txt")

    if os.path.isfile(platform_file):
        print(f"[auto_install] Using platform requirements: requirements_{platform_name}.txt")
        return platform_file

    print(f"[auto_install] Using default requirements.txt (platform: {platform_name})")
    return default_file


# ═══════════════════════════════════════════
# 📦 PACKAGE NORMALIZATION
# ═══════════════════════════════════════════

def _normalize(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def _extract_pkg_name(line: str) -> str | None:
    line = line.strip()
    if not line or line.startswith("#") or line.startswith("-"):
        return None
    extras_match = re.match(r"^([a-zA-Z0-9_][\w.-]*).*", line)
    if extras_match:
        name = extras_match.group(1)
        extras_pos = name.find("[")
        if extras_pos != -1:
            name = name[:extras_pos]
        return name
    return None


# ═══════════════════════════════════════════
# 🔄 FALLBACK ALTERNATIVES
# ═══════════════════════════════════════════

# If a package fails, try these alternatives
FALLBACKS: dict[str, list[str]] = {
    "pymysql": ["mysql-connector-python"],
    "Pillow": ["Pillow-simd"],  # Faster alternative
    "aiohttp": ["httpx"],  # Already included, but as fallback
    "orjson": ["ujson"],  # Alternative fast JSON
    "python-telegram-bot[job-queue]": ["python-telegram-bot"],
    "groq": ["openai"],  # OpenAI-compatible fallback
}

# Packages that are optional (bot works without them)
OPTIONAL_PACKAGES = {
    "groq", "orjson", "ujson", "Pillow-simd", "cachetools",
    "deep-translator", "jsonschema", "psutil",
}


def _get_pip_cmd() -> list[str]:
    """Get the correct pip command for this environment."""
    # Try python3 -m pip first (most reliable)
    try:
        result = subprocess.run(
            [sys.executable, "-m", "pip", "--version"],
            capture_output=True,
            text=True,
        )
        if result.returncode == 0:
            cmd = [sys.executable, "-m", "pip"]
            # In proot-distro Ubuntu, we need --break-system-packages
            if detect_platform() == "proot_ubuntu":
                cmd.append("--break-system-packages")
            return cmd
    except Exception:
        pass

    # Try pip3
    try:
        result = subprocess.run(["pip3", "--version"], capture_output=True, text=True)
        if result.returncode == 0:
            cmd = ["pip3"]
            if detect_platform() == "proot_ubuntu":
                cmd.append("--break-system-packages")
            return cmd
    except Exception:
        pass

    # Try pip
    try:
        result = subprocess.run(["pip", "--version"], capture_output=True, text=True)
        if result.returncode == 0:
            cmd = ["pip"]
            if detect_platform() == "proot_ubuntu":
                cmd.append("--break-system-packages")
            return cmd
    except Exception:
        pass

    return [sys.executable, "-m", "pip"]  # Default


def _try_install_with_fallback(pkg_line: str) -> bool:
    """Try to install a package, falling back to alternatives if it fails."""
    pkg_name = _extract_pkg_name(pkg_line)
    if not pkg_name:
        return True

    pip_cmd = _get_pip_cmd()

    # Try main package first
    result = subprocess.run(
        pip_cmd + ["install", pkg_line],
        capture_output=True,
        text=True,
    )
    if result.returncode == 0:
        return True

    # Show error for debugging
    error_msg = result.stderr.strip() if result.stderr else "unknown error"
    # Extract just the key error line
    for line in error_msg.split("\n"):
        if "error" in line.lower() or "failed" in line.lower() or "not found" in line.lower():
            print(f"[auto_install] {pkg_name}: {line.strip()}")
            break

    # Try fallbacks
    fallbacks = FALLBACKS.get(pkg_name, [])
    for fallback in fallbacks:
        print(f"[auto_install] {pkg_name} failed, trying fallback: {fallback}")
        result = subprocess.run(
            pip_cmd + ["install", fallback],
            capture_output=True,
            text=True,
        )
        if result.returncode == 0:
            print(f"[auto_install] Fallback {fallback} installed successfully")
            return True

    # Check if package is optional
    if pkg_name in OPTIONAL_PACKAGES:
        print(f"[auto_install] {pkg_name} is optional, continuing without it")
        return True  # Don't count as failure

    print(f"[auto_install] Failed to install {pkg_name} and all alternatives")
    return False


# ═══════════════════════════════════════════
# 🔧 PLATFORM-SPECIFIC FIXES
# ═══════════════════════════════════════════

def _fix_pillow_rpath() -> None:
    """Fix Pillow rpath for Termux/Android."""
    try:
        from PIL import Image
    except ImportError:
        return

    # Only needed on Termux
    if detect_platform() != "android":
        return

    try:
        spec = importlib.util.find_spec("PIL._imaging")
        if spec is None or spec.origin is None:
            return
        so_path = spec.origin
        libs_dir = os.path.join(os.path.dirname(os.path.dirname(so_path)), "pillow.libs")
        if not os.path.isdir(libs_dir):
            return
        abs_rpath = libs_dir
        for so in [so_path] + glob.glob(os.path.join(libs_dir, "*.so*")):
            try:
                current = subprocess.run(["patchelf", "--print-rpath", so], capture_output=True, text=True).stdout.strip()
                if current == abs_rpath:
                    continue
                subprocess.run(["patchelf", "--set-rpath", abs_rpath, so], check=True, capture_output=True)
            except Exception:
                pass
    except Exception:
        pass


def _install_termux_extras() -> None:
    """Install Termux-specific system packages if needed."""
    if detect_platform() != "android":
        return

    # Check if pkg is available (Termux package manager)
    try:
        result = subprocess.run(["which", "pkg"], capture_output=True, text=True)
        if result.returncode != 0:
            return
    except FileNotFoundError:
        return

    # Install system dependencies for Pillow if not present
    packages_to_check = ["libjpeg-turbo", "freetype", "libxml2", "libxslt"]
    missing = []

    for pkg in packages_to_check:
        result = subprocess.run(["dpkg", "-s", pkg], capture_output=True, text=True)
        if result.returncode != 0:
            missing.append(pkg)

    if missing:
        print(f"[auto_install] Installing Termux system packages: {', '.join(missing)}")
        subprocess.run(["pkg", "install", "-y"] + missing, capture_output=True)


def _install_proot_ubuntu_extras() -> None:
    """Install proot-distro Ubuntu system packages if needed."""
    if detect_platform() != "proot_ubuntu":
        return

    # Update apt and install system dependencies
    print("[auto_install] Setting up proot-distro Ubuntu packages...")

    try:
        # Update apt cache first
        subprocess.run(["apt-get", "update", "-qq"], capture_output=True, timeout=60)
    except Exception:
        pass

    # System packages needed for Python packages
    system_packages = [
        "python3-pip",
        "python3-dev",
        "libjpeg-dev",
        "zlib1g-dev",
        "libfreetype6-dev",
        "libffi-dev",
        "libssl-dev",
        "gcc",
        "g++",
        "make",
    ]

    # Check which are missing
    missing = []
    for pkg in system_packages:
        result = subprocess.run(["dpkg", "-s", pkg], capture_output=True, text=True)
        if result.returncode != 0:
            missing.append(pkg)

    # Also ensure tzdata is installed (critical for timezone support)
    pip_cmd = _get_pip_cmd()
    try:
        zoneinfo.ZoneInfo("Asia/Kolkata")
    except Exception:
        print("[auto_install] Installing tzdata for timezone support...")
        subprocess.run(pip_cmd + ["install", "tzdata"], capture_output=True, timeout=60)

    if missing:
        print(f"[auto_install] Installing Ubuntu system packages: {', '.join(missing)}")
        try:
            subprocess.run(
                ["apt-get", "install", "-y", "-qq"] + missing,
                capture_output=True,
                timeout=120
            )
        except Exception as e:
            print(f"[auto_install] Some system packages failed: {e}")
            print(f"[auto_install] Try manually: sudo apt install {' '.join(missing)}")


def _install_linux_extras() -> None:
    """Install Linux system packages if needed."""
    if detect_platform() not in ("linux", "wsl"):
        return

    # Check if apt is available
    try:
        result = subprocess.run(["which", "apt"], capture_output=True, text=True)
        if result.returncode != 0:
            return
    except FileNotFoundError:
        return

    # Install system dependencies for Pillow if not present
    packages_to_check = ["libjpeg-dev", "zlib1g-dev", "libfreetype6-dev", "python3-dev"]
    missing = []

    for pkg in packages_to_check:
        result = subprocess.run(["dpkg", "-s", pkg], capture_output=True, text=True)
        if result.returncode != 0:
            missing.append(pkg)

    if missing:
        print(f"[auto_install] Install these system packages for full support:")
        print(f"  sudo apt install {' '.join(missing)}")


# ═══════════════════════════════════════════
# 🚀 MAIN AUTO-INSTALL
# ═══════════════════════════════════════════

def auto_install(requirements_path: str | None = None) -> None:
    """Auto-install missing dependencies with platform detection and fallbacks."""
    if requirements_path is None:
        base = os.path.dirname(os.path.abspath(__file__))
        requirements_path = get_requirements_file(base)

    if not os.path.isfile(requirements_path):
        print(f"[auto_install] requirements.txt not found at {requirements_path}")
        return

    # Platform-specific system package installation
    platform_name = detect_platform()
    print(f"[auto_install] Detected platform: {platform_name}")

    if platform_name == "android":
        _install_termux_extras()
    elif platform_name == "proot_ubuntu":
        _install_proot_ubuntu_extras()
    elif platform_name in ("linux", "wsl"):
        _install_linux_extras()

    # Read requirements file
    with open(requirements_path) as f:
        lines = f.readlines()

    # Ensure tzdata is installed first (critical for timezone support)
    pip_cmd = _get_pip_cmd()
    try:
        zoneinfo.ZoneInfo("Asia/Kolkata")
    except Exception:
        print("[auto_install] Installing tzdata for timezone support...")
        result = subprocess.run(pip_cmd + ["install", "tzdata"], capture_output=True, text=True, timeout=60)
        if result.returncode != 0:
            # Try alternative: backports.zoneinfo
            subprocess.run(pip_cmd + ["install", "backports.zoneinfo"], capture_output=True, text=True, timeout=60)

    # Check which packages are missing
    missing = []
    for line in lines:
        pkg_name = _extract_pkg_name(line)
        if pkg_name is None:
            continue
        try:
            importlib.metadata.distribution(_normalize(pkg_name))
        except importlib.metadata.PackageNotFoundError:
            missing.append(line.strip())

    if not missing:
        _fix_pillow_rpath()
        print(f"[auto_install] All packages already installed")
        return

    print(f"[auto_install] Installing {len(missing)} missing packages...")

    # Install with fallbacks
    failed = []
    succeeded = []

    for pkg_line in missing:
        if _try_install_with_fallback(pkg_line):
            pkg_name = _extract_pkg_name(pkg_line)
            if pkg_name:
                succeeded.append(pkg_name)
        else:
            failed.append(pkg_line)

    # Report results
    if succeeded:
        print(f"[auto_install] Successfully installed: {', '.join(succeeded)}")

    if failed:
        print(f"[auto_install] Failed to install: {', '.join(failed)}")
        print(f"[auto_install] Bot may have reduced functionality")

    # Apply platform-specific fixes
    _fix_pillow_rpath()


# ═══════════════════════════════════════════
# 📊 STATUS REPORT
# ═══════════════════════════════════════════

def get_install_status() -> dict:
    """Get the installation status of all required packages."""
    base = os.path.dirname(os.path.abspath(__file__))
    requirements_path = get_requirements_file(base)

    try:
        with open(requirements_path) as f:
            lines = f.readlines()
    except (FileNotFoundError, OSError):
        return {"installed": [], "missing": []}

    installed = []
    missing = []

    for line in lines:
        pkg_name = _extract_pkg_name(line)
        if pkg_name is None:
            continue
        try:
            importlib.metadata.distribution(_normalize(pkg_name))
            installed.append(pkg_name)
        except importlib.metadata.PackageNotFoundError:
            missing.append(pkg_name)

    return {
        "platform": detect_platform(),
        "installed": installed,
        "missing": missing,
        "all_installed": len(missing) == 0,
    }

