# Dedicated thread pool for AI/bot operations (256 workers)
# Default asyncio.to_thread() uses min(32, cpu_count+4) workers, which is
# overwhelmed by 2000 concurrent updates. This pool scales to handle the load.
_AI_EXECUTOR: concurrent.futures.ThreadPoolExecutor | None = None

def _get_ai_executor() -> concurrent.futures.ThreadPoolExecutor:
    global _AI_EXECUTOR
    if _AI_EXECUTOR is None:
        _AI_EXECUTOR = concurrent.futures.ThreadPoolExecutor(
            max_workers=256,
            thread_name_prefix="ai-op"
        )
    return _AI_EXECUTOR

async def _ai_to_thread(func, *args, **kwargs):
    """Run a blocking function in the dedicated AI thread pool (256 workers).
    Falls back to default executor if our pool is unavailable."""
    try:
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(_get_ai_executor(), functools.partial(func, **kwargs), *args)
    except RuntimeError:
        return await asyncio.to_thread(func, *args, **kwargs)


def _ai_to_thread_no_wait(func, *args, **kwargs):
    """Fire-and-forget variant: submit to AI thread pool, don't await.
    Exceptions are logged via the task's done callback. Best for non-critical
    housekeeping like permanent ID recording."""
    try:
        loop = asyncio.get_running_loop()
        fut = loop.run_in_executor(_get_ai_executor(), functools.partial(func, **kwargs), *args)
        # attach a done callback that logs failures (non-blocking)
        if fut is not None and hasattr(fut, "add_done_callback"):
            def _log_failure(f):
                try:
                    f.result()
                except Exception as exc:
                    logger.debug("background task %s failed: %s", getattr(func, "__name__", func), exc)
            fut.add_done_callback(_log_failure)
    except RuntimeError:
        # No event loop yet — just run in default thread pool
        try:
            return asyncio.to_thread(func, *args, **kwargs)
        except Exception:
            pass

