def _log_command_http(method: str, path: str, status: int) -> None:
    """Log bot command as a clean HTTP-style line (no noisy stack traces)."""
    logger.debug(f"{method} {path} {status}")

def main__register_chat(
    chat_id: int,
    chat_type: str = "",
    title: str = "",
    username: str = "",
) -> None:
    """Adapt main.py's old chat registration call to the current database API."""
    register_chat(
        chat_id,
        {
            "_id": chat_id,
            "chat_id": chat_id,
            "type": chat_type,
            "title": title,
            "username": username,
            "last_seen": int(time.time()),
        },
    )


# Polling state keys
POLLING_CONFLICT_UNTIL_KEY = "polling_conflict_until"
DROP_PENDING_UPDATES_KEY = "polling_drop_pending_once"

def _offline_update_origin(update: Update) -> str:
    chat = update.effective_chat
    if chat:
        return f"chat:{chat.id}"
    user = update.effective_user
    if user:
        return f"user:{user.id}"
    return f"update:{update.update_id}"


def _offline_update_payload(update: Update) -> dict:
    return {
        "update_id": int(update.update_id or 0),
        "origin": _offline_update_origin(update),
        "payload": update.to_dict(),
    }


def _offline_updates_from_setting(raw) -> list[dict]:
    if not raw:
        return []
    if isinstance(raw, dict):
        updates = raw.get("updates", [])
    elif isinstance(raw, list):
        updates = raw
    elif isinstance(raw, str):
        try:
            data = json.loads(raw)
        except Exception:
            logger.warning("Exception in _offline_updates_from_setting", exc_info=True)
            return []
        updates = data.get("updates", []) if isinstance(data, dict) else data
    else:
        return []
    return [item for item in updates if isinstance(item, dict)]


async def _capture_pending_updates(app: Application) -> int:
    """Persist up to 2000 pending Telegram updates before polling drops them."""
    try:
        raw_existing = await asyncio.to_thread(get_setting, _OFFLINE_BUFFER_KEY, {})
    except Exception:
        raw_existing = {}
    existing = _offline_updates_from_setting(raw_existing)
    pending: list[dict] = []
    offset = None
    last_update_id = None
    try:
        while len(pending) < _OFFLINE_BUFFER_LIMIT:
            batch = await app.bot.get_updates(
                offset=offset,
                limit=min(_OFFLINE_FETCH_LIMIT, _OFFLINE_BUFFER_LIMIT - len(pending)),
                timeout=30,
                read_timeout=30,
                allowed_updates=Update.ALL_TYPES,
            )
            if not batch:
                break
            for update in batch:
                pending.append(_offline_update_payload(update))
                last_update_id = update.update_id
                if len(pending) >= _OFFLINE_BUFFER_LIMIT:
                    break
            if last_update_id is None:
                break
            offset = int(last_update_id) + 1
            if len(batch) < _OFFLINE_FETCH_LIMIT:
                break

        if last_update_id is not None:
            await app.bot.get_updates(
                offset=int(last_update_id) + 1,
                limit=1,
                timeout=0,
                read_timeout=10,
                allowed_updates=Update.ALL_TYPES,
            )

        combined: list[dict] = []
        seen_ids: set[int] = set()
        for item in existing + pending:
            update_id = int(item.get("update_id", 0) or 0)
            if update_id and update_id in seen_ids:
                continue
            if update_id:
                seen_ids.add(update_id)
            combined.append(item)
        combined = combined[-_OFFLINE_BUFFER_LIMIT:]

        await asyncio.to_thread(
            save_setting,
            _OFFLINE_BUFFER_KEY,
            {"captured_at": int(time.time()), "updates": combined},
        )
        if pending:
            origins = {item.get("origin", "") for item in pending}
            logger.info(
                "Captured %s offline updates from %s chats/users",
                len(pending),
                len([origin for origin in origins if origin]),
            )
        return len(pending)
    except Conflict:
        raise
    except Exception as exc:
        logger.warning(f"Offline pending update capture failed: {exc}", exc_info=True)
        return 0


def _log_task_exception(task: asyncio.Task) -> None:
    if not task.cancelled():
        exc = task.exception()
        if exc:
            logger.error("Background task %s failed: %s", task.get_name(), exc, exc_info=exc)

_OFFLINE_REPLAY_CONCURRENCY = 50

async def _replay_offline_buffer(app: Application) -> None:
    """Replay captured updates through the live handler pipeline concurrently."""
    raw = await asyncio.to_thread(get_setting, _OFFLINE_BUFFER_KEY, {})
    updates = _offline_updates_from_setting(raw)
    if not updates:
        await asyncio.to_thread(save_setting, _OFFLINE_BUFFER_KEY, {"updates": []})
        await asyncio.to_thread(save_setting, _OFFLINE_LEGACY_DM_BUFFER_KEY, "")
        return

    items = updates[:_OFFLINE_BUFFER_LIMIT]
    logger.info(f"Replaying {len(items)} offline updates (concurrency={_OFFLINE_REPLAY_CONCURRENCY})")

    sem = asyncio.Semaphore(_OFFLINE_REPLAY_CONCURRENCY)

    async def _process_one(item: dict) -> bool:
        payload = item.get("payload") or item
        try:
            update = Update.de_json(payload, app.bot)
            if update is None:
                return False
            async with sem:
                await app.process_update(update)
            return True
        except Exception:
            logger.warning("Exception in _process_one", exc_info=True)
            return False

    app.bot_data["_offline_replay"] = True
    try:
        results = await asyncio.gather(*[_process_one(item) for item in items])
    finally:
        app.bot_data.pop("_offline_replay", None)

    delivered = sum(results)
    failed = len(results) - delivered

    # Safety-net: retry DMs for ChatJoinRequest updates that may have failed
    try:
        replayed = await _replay_pending_join_requests(app, updates, delivered >= len(items))
        if replayed:
            logger.info(f"Pending join request DMs sent: {replayed}")
    except Exception as exc:
        logger.warning(f"Pending join request replay error: {exc}")

    # Clear buffer only after successful replay to prevent data loss on crash
    await asyncio.to_thread(save_setting, _OFFLINE_BUFFER_KEY, {"updates": []})
    await asyncio.to_thread(save_setting, _OFFLINE_LEGACY_DM_BUFFER_KEY, "")
    logger.info(f"Offline update replay complete: {delivered} delivered, {failed} failed")


async def _replay_pending_join_requests(app: Application, items: list[dict], all_ok: bool) -> int:
    """Safety-net: send DMs for ChatJoinRequest updates after generic replay."""
    if all_ok:
        return 0
    sent = 0
    for item in items:
        payload = item.get("payload") or item
        try:
            update = Update.de_json(payload, app.bot)
        except Exception:
            continue
        if not update or not update.chat_join_request:
            continue
        join_req = update.chat_join_request
        if not join_req.from_user or not join_req.chat:
            continue
        chat_title = html.escape(join_req.chat.title or "Group")
        user_id = join_req.user_chat_id or join_req.from_user.id
        try:
            text = _pick_join_msg(chat_title)
            await app.bot.send_message(chat_id=user_id, text=text, parse_mode="HTML")
            sent += 1
        except Exception:
            pass
    return sent


async def _capture_and_replay_offline_updates(app: Application) -> None:
    try:
        await _capture_pending_updates(app)
        await _replay_offline_buffer(app)
    except Conflict:
        raise
    except Exception as exc:
        logger.warning(f"Offline update buffer error: {exc}", exc_info=True)

# ── Known chats cache - prevents redundant DB writes ─────────────────────────
import collections
_known_chats: collections.OrderedDict = collections.OrderedDict()
_known_chats_lock = threading.Lock()
_KNOWN_CHATS_MAX = 500000




async def _set_polling_pause(seconds: int, reason: str = "conflict") -> None:
    until = int(time.time()) + max(10, int(seconds or 0))
    await asyncio.to_thread(save_setting, POLLING_CONFLICT_UNTIL_KEY, str(until))
    if reason == "conflict":
        await asyncio.to_thread(save_setting, DROP_PENDING_UPDATES_KEY, "1")


def _polling_pause_remaining() -> int:
    try:
        until = int(get_setting(POLLING_CONFLICT_UNTIL_KEY, "0") or 0)
    except (sqlite3.Error, json.JSONDecodeError, ValueError, TypeError, KeyError):
        until = 0
    return max(0, until - int(time.time()))
async def error_handler(update, context) -> None:
    # Ignore KeyError for chat IDs (missing chat registration - not critical)
    if isinstance(context.error, KeyError):
        return

    if isinstance(context.error, Conflict):
        logger.warning(
            f"Polling conflict detected, switching to standby: {context.error}"
        )
        await _set_polling_pause(180, "conflict")
        context.application.stop_running()
        return

    # Gracefully handle Forbidden (user blocked the bot, bot not admin, etc.)
    if isinstance(context.error, Forbidden):
        logger.debug(f"Forbidden (user blocked bot or no permission): {context.error}")
        return

    # Gracefully handle old/expired callback queries
    error_str = str(context.error).lower()
    if any(
        keyword in error_str
        for keyword in [
            "query is too old",
            "query id is invalid",
            "timeout expired",
            "bad request",
        ]
    ):
        logger.debug("Ignored expired callback query (normal behavior)")
        return

    # Network errors (DNS failure, connection lost, timeouts) - auto-recover
    if any(
        keyword in error_str
        for keyword in [
            "timed out",
            "network error",
            "getaddrinfo failed",
            "connecterror",
            "connection refused",
            "connection reset",
            "network is unreachable",
            "temporary failure",
        ]
    ):
        return  # Silently ignore network issues

    # Rate limit errors
    if "too many requests" in error_str or "retry after" in error_str:
        return  # Silently ignore rate limits

    # Real errors - log and report to owner (deduplicated)
    error_msg = str(context.error)
    error_type = type(context.error).__name__
    tb = getattr(context.error, "__traceback__", None)
    if tb:
        tb_lines = "".join(traceback.format_tb(tb))
        logger.warning(f"⚠️ {error_type}: {error_msg[:150]}\n{tb_lines[:500]}")
    else:
        logger.warning(f"⚠️ {error_type}: {error_msg[:150]}", exc_info=True)
    try:
        asyncio.create_task(report(context.error, "ptb_handler"))
    except Exception:
        pass


async def auto_profile(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    try:
        user = update.effective_user
        if not user or user.is_bot:
            return
        # OPTIMIZED: Removed redundant register_chat (done in _track handler)
        # OPTIMIZED: Call ensure() with thread-safe data
        _user_data = {
            'full_name': user.full_name,
            'first_name': getattr(user, 'first_name', None),
            'username': getattr(user, 'username', None),
            'is_bot': user.is_bot,
        }
        await asyncio.to_thread(ensure, user.id, _user_data)
    except KeyError:
        logger.debug("Ignore missing keys - not critical")
    except (sqlite3.Error, AttributeError, ValueError, TypeError):
        logger.debug("Don't break on profile errors")


async def sticker_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.effective_message
    user = update.effective_user
    if msg and msg.sticker and user and not user.is_bot:
        loop = asyncio.get_running_loop()
        _user_data = {
            'full_name': user.full_name,
            'first_name': getattr(user, 'first_name', None),
            'username': getattr(user, 'username', None),
            'is_bot': user.is_bot,
        }
        await loop.run_in_executor(None, ensure, user.id, _user_data)


AI_SEM = asyncio.Semaphore(2000)  # Massive concurrency for 100x load

# Track users creating buttons (prevents AI during button creation session)
_BUTTON_CREATION_USERS: dict[int, float] = {}
_button_creation_lock = threading.Lock()


def is_creating_button(user_id: int) -> bool:
    """Check if user is in button creation mode (10 min session).
    Lock-free fast path: 99%+ of users are NOT in this mode, so the dict
    miss returns False without acquiring the lock."""
    exp = _BUTTON_CREATION_USERS.get(user_id, 0)
    if exp <= 0:
        return False
    if time.time() > exp:
        # Expired — clean up under lock
        with _button_creation_lock:
            _BUTTON_CREATION_USERS.pop(user_id, None)
        return False
    return True


def set_button_creation_mode(user_id: int, minutes: int = 10) -> None:
    """Mark user as creating buttons for X minutes."""
    with _button_creation_lock:
        _BUTTON_CREATION_USERS[user_id] = time.time() + (minutes * 60)


async def _cleanup_expired_button_users() -> None:
    """Background cleanup of stale button creation entries."""
    while True:
        await asyncio.sleep(3600)
        with _button_creation_lock:
            now = time.time()
            stale = [uid for uid, exp in _BUTTON_CREATION_USERS.items() if exp < now]
            for uid in stale:
                _BUTTON_CREATION_USERS.pop(uid, None)


async def ai_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # ── Ultra-fast pre-filter: skip obvious non-AI messages in <1µs ─────
    _crumb("guard_in", update)
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user or user.is_bot:
        return

    # Skip commands and pure media — these should never trigger AI
    text = (msg.text or msg.caption or "").strip()
    is_sticker = msg.sticker is not None
    if not text and not is_sticker:
        return
    if text.startswith("/"):
        return

    # ── Image CAPTCHA gate (merged from separate handler — PTB group=1
    #    can only have ONE MessageHandler; two handlers = first eats all) ──
    try:
        from system.image_captcha import has_pending_captcha, verify_captcha
        if has_pending_captcha(user.id):
            _captcha_stripped = text.replace(" ", "")
            if 1 <= len(text) <= 10 and _captcha_stripped.isalnum():
                if len(text) >= 3 or _captcha_stripped.isdigit():
                    ok, reason = await asyncio.to_thread(verify_captcha, user.id, text)
                    if ok:
                        await grant_web_verification_immunity(user.id)
                        async with _get_user_lock(user.id):
                            u = await asyncio.to_thread(get_user, user.id) or {}
                            u = _ensure_user(u)
                            if u.get("flagged_at", 0) > 0:
                                await asyncio.to_thread(update_user_atomic, user.id, set_fields={"flagged_at": 0, "capture_count": 0})
                        await msg.reply_html(
                            "Tʜᴀɴᴋ Yᴏᴜ Sᴏ Mᴜᴄʜ Fᴏʀ Vᴇʀɪғʏɪɴɢ 💕 "
                            "Yᴏᴜ Cᴀɴ Pʟᴀʏ Aɢᴀɪɴ Fʀᴏᴍ Wʜᴇʀᴇ Yᴏᴜ Pᴀᴜsᴇᴅ."
                        )
                    else:
                        if "no captcha" in reason or "expired" in reason:
                            await msg.reply_html(f"⚠️ {reason}")
                        elif "too many" in reason:
                            await msg.reply_html(f"❌ {reason}")
                        else:
                            await msg.reply_html(f"❌ Wrong code. {reason}\nTry again or /verify for new image.")
                    return  # captcha handled — don't pass to AI
    except Exception as _captcha_exc:
        logger.debug(f"captcha check in ai_guard failed: {_captcha_exc}")

    # Don't respond to AI if user is actively creating buttons (10 min session)
    if is_creating_button(user.id):
        return

    # ── Static check: skip if "ai" category is disabled ────────────────
    # bot_category_disabled is cached for 10s, so this is fast on cache hit
    if await bot_category_disabled("ai"):
        return

    # ── Pre-check whether AI should respond BEFORE showing the reaction ───
    # Without this, the bot reacted with 🤔 to EVERY message including
    # commands like /pf, /loot, /capt, etc. — confusing for users.
    # Mirrors handle_ai_chat's _should_respond() logic so we only light up
    # when the AI is actually going to answer.
    chat = update.effective_chat
    if not chat:
        return
    cid = chat.id
    is_private = chat.type == "private"
    reply_to = msg.reply_to_message
    is_reply_to_bot = bool(
        reply_to and reply_to.from_user and reply_to.from_user.id == context.bot.id
    )

    # Inline the same short-circuit as ai._should_respond() so we don't pay
    # the cost of an extra function call on the hot path. _should_respond
    # is async so we must await it.
    if not is_sticker:
        reply_text = (reply_to.text or reply_to.caption or "") if reply_to else ""
        try:
            if not await _ai_should_respond(text, cid, is_private, is_reply_to_bot, reply_text):
                return
        except Exception as exc:
            # Never fail silent: owner gets the error text (diagnosis),
            # others simply get no AI reply for this message.
            try:
                logger.warning(f"ai_guard should_respond failed: {exc}", exc_info=True)
            except Exception:
                pass
            if user.id == OWNER_ID:
                try:
                    await msg.reply_text(f"AI gate error: {type(exc).__name__}: {str(exc)[:200]}")
                except Exception:
                    pass
            return

    # ── Fire-and-forget optimization for high load ───────────────────
    # The hot path used to await handle_ai_chat() inline. With 200
    # concurrent AI requests, this serialized through AI_SEM. Now we:
    #   1. Try to acquire the semaphore ASYNCHRONOUSLY (non-blocking spin)
    #   2. Show a typing reaction immediately (instant feedback)
    #   3. Detach the actual AI work as a background task
    # The event loop returns in <1ms, the bot feels 100x more responsive.

    # Try to acquire the semaphore without blocking; if at capacity,
    # fall back to inline (still better than dropping messages).
    if AI_SEM.locked() and AI_SEM._value <= 0:  # type: ignore[attr-defined]
        # Capacity exhausted — process inline with a quick "thinking" reaction
        async with AI_SEM:
            try:
                await handle_ai_chat(update, context)
            except Exception as exc:
                # Don't show busy to user — log only. The chat_completion
                # already retried all providers internally.
                try:
                    logger.warning(f"AI chat error (all providers failed): {exc}")
                except Exception:
                    pass
        return

    # Capacity available — show "thinking" reaction immediately, detach work
    _crumb("guard_go", update)
    async def _detached():
        async with AI_SEM:
            try:
                await handle_ai_chat(update, context)
            except Exception as exc:
                # Don't show busy to user — log only
                try:
                    logger.warning(f"AI chat error (all providers failed): {exc}")
                except Exception:
                    pass
                except Exception:
                    logger.debug("Exception in ai_guard")

    # Schedule the actual work in the background
    asyncio.create_task(_detached())


async def clean_welcome(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.effective_message
    chat = update.effective_chat
    if not msg or not msg.new_chat_members or not chat:
        return
    try:
        chat_member = await context.bot.get_chat_member(chat.id, context.bot.id)
        if chat_member.status not in ("administrator", "creator"):
            return
    except Exception:
        logger.debug("Exception in clean_welcome")
        return
    try:
        settings = await get_group_settings(chat.id)
        if not settings.get("welcome", True):
            return
    except Exception:
        logger.error("Unexpected error", exc_info=True)
    for user in msg.new_chat_members:
        if user.is_bot:
            continue
        mention = f"<a href='tg://user?id={user.id}'>{html.escape(user.first_name)}</a>"
        try:
            await context.bot.send_message(
                chat.id, f"Hᴇʏ Welcome ✨ {mention} Hᴏᴡ Aʀᴇ Yᴏᴜ Tᴏᴅᴀʏ ?", parse_mode="HTML"
            )
        except TelegramError:
            logger.debug("TelegramError in welcome send")


