async def auto_memory_cleanup(context: ContextTypes.DEFAULT_TYPE) -> None:
    """FIX: Prevent crash after 30-40 min by cleaning memory periodically."""
    try:
        loop = asyncio.get_running_loop()
        # Ensure thread-safety and non-blocking event loop execution
        await loop.run_in_executor(None, gc.collect)
        logger.info("🧹 Memory cleanup completed")
    except Exception as exc:
        logger.warning(f"Memory cleanup error: {exc}", exc_info=True)


