async def mark_dm_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if user:
        await mark_dm_opened(user.id)


async def my_chat_member_handler(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Handle when bot is added/removed from groups.
    Track all groups the bot is member of.
    """
    chat = update.effective_chat
    member = update.my_chat_member

    if not chat:
        return

    new_status = member.new_chat_member.status if member and member.new_chat_member else None

    if new_status in ("member", "administrator"):
        # Bot joined the chat - register it
        try:
            await asyncio.to_thread(main__register_chat,
                int(chat.id),
                getattr(chat, "type", "") or "",
                getattr(chat, "title", "") or getattr(chat, "full_name", "") or "",
                getattr(chat, "username", "") or "",
            )
            logger.info(f"Bot joined group: {chat.id} - {getattr(chat, 'title', 'Unknown')}")
        except Exception as exc:
            logger.debug(f"Register chat error: {exc}")

    elif new_status in ("left", "kicked"):
        # Bot was removed or kicked - unregister
        try:
            await asyncio.to_thread(unregister_chat, int(chat.id))
            logger.info(f"Bot left group: {chat.id}")
        except Exception:
            logger.error("Unexpected error", exc_info=True)


async def track_chat_and_user(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Track users/chats. For callback queries, skip DB ops entirely —
    the user and chat were already tracked when the original message was sent.

    Hot path optimization: for the common case where the user is already in
    USER_CACHE and the chat is in the in-process _known_chats set, the
    function does nothing — no thread pool, no I/O. Returns in <1µs.
    """
    global _known_chats
    started_at = begin_update()
    _crumb("track", update)
    try:
        if update.callback_query:
            return

        user = update.effective_user
        chat = update.effective_chat

        if user and not user.is_bot:
            # Fast path: user already in cache + perm ID recorded
            if chat and chat.type == "private":
                # Need mark_dm_opened for private chat (it has a side effect)
                try:
                    await mark_dm_opened(user.id)
                except Exception:
                    pass
            # Lazy import to keep hot path snappy
            uid_str = str(user.id)
            if not USER_CACHE.contains(uid_str):
                # First time seeing this user — create their record
                try:
                    _user_data = {
                        'full_name': user.full_name,
                        'username': getattr(user, 'username', None),
                        'is_bot': user.is_bot,
                    }
                    await _ai_to_thread(ensure, user.id, _user_data)
                except Exception:
                    logger.error("Unexpected error in ensure", exc_info=True)
            if not USER_CACHE.contains(f"_perm_uid:{user.id}"):
                try:
                    _uname = (user.full_name or "")[:64]
                    USER_CACHE.set(f"_perm_uid:{user.id}", True, ttl=86400)
                    _ai_to_thread_no_wait(record_id, user.id, "u", _uname)
                except Exception:
                    pass

        if not chat:
            return
        # Fast path: chat already known in this process — no I/O at all
        with _known_chats_lock:
            if chat.id in _known_chats:
                return
            _known_chats[chat.id] = None
            while len(_known_chats) > _KNOWN_CHATS_MAX:
                _known_chats.popitem(last=False)
        title = getattr(chat, "title", None) or getattr(chat, "full_name", None) or ""
        username = getattr(chat, "username", None) or ""
        try:
            await asyncio.to_thread(
                main__register_chat,
                int(chat.id),
                getattr(chat, "type", "") or "",
                title,
                username,
            )
        except Exception:
            logger.error("Unexpected error in register_chat", exc_info=True)
        # Record group/channel id in permanent registry (idempotent, 24h dedup via cache)
        try:
            kind = "g" if getattr(chat, "type", "") in ("group", "supergroup") else (
                "c" if getattr(chat, "type", "") == "channel" else None
            )
            if kind is not None:
                cache_key = f"_perm_{kind}id:{chat.id}"
                if not USER_CACHE.contains(cache_key):
                    USER_CACHE.set(cache_key, True, ttl=86400)
                    _ai_to_thread_no_wait(record_id, chat.id, kind, title)
        except Exception:
            pass
    finally:
        end_update(started_at)


_notify_dead_chats: set[int] = set()


async def _send_online_notification(app: Application) -> None:
    """Notify LOG_GROUP and BACKUP_CHAT that bot is online."""
    try:
        # Small delay to ensure Telegram connection is established
        await asyncio.sleep(2)
        text = (
            f"🚀 <b>Bot Online</b>\n\n"
            f"✅ Anyy Bot is now online and polling.\n"
            f"📍 Instance: <code>{BOT_USERNAME}</code>\n"
            f"🕐 <i>{time.strftime('%Y-%m-%d %H:%M:%S')}</i>"
        )
        for chat_id in (LOG_GROUP, BACKUP_CHAT):
            if not chat_id or chat_id in _notify_dead_chats:
                continue
            try:
                await app.bot.send_message(
                    chat_id=chat_id,
                    text=text,
                    parse_mode="HTML"
                )
            except Exception as e:
                if type(e).__name__ == "RetryAfter":
                    logger.warning("Online notification skipped (flood)")
                    break
                detail = str(e).lower()
                if "chat not found" in detail or "kicked" in detail or "no rights" in detail:
                    # Bot is not in LOG_GROUP — remember so the next boot does not
                    # dump a traceback for the same known-bad target.
                    _notify_dead_chats.add(chat_id)
                    logger.warning(
                        "Online notification target %s unreachable (%s); skipping it",
                        chat_id, type(e).__name__,
                    )
                    continue
                logger.warning(
                    "Online notification to %s failed: %s: %s",
                    chat_id, type(e).__name__, str(e)[:120],
                )
    except Exception as e:
        logger.warning("Online notification error: %s: %s", type(e).__name__, str(e)[:120])


_JOIN_REQUEST_MESSAGE = (
    "Hɪᴇᴇᴇ.. Cᴜᴛɪᴇ! 🎀\n\n"
    "Yᴏᴜʀ Rᴇǫᴜᴇsᴛ Tᴏ Jᴏɪɴ <b>{chat_title}</b> Hᴀs Bᴇᴇɴ Rᴇᴄᴇɪᴠᴇᴅ.\n"
    "Sᴏᴏɴ Gʀᴏᴜᴘ Aᴅᴍɪɴ Wɪʟʟ Rᴇᴠɪᴇᴡ Iᴛ. ✨\n\n"
    "Mᴇᴀɴᴡʜɪʟᴇ Iғ Yᴏᴜ Aʀᴇ Bᴏʀᴇᴅ Yᴏᴜ Cᴀɴ Exᴘʟᴏʀᴇ Aɴʏʏ Bʏ ---> /start"
)


def _pick_join_msg(chat_title: str) -> str:
    return _JOIN_REQUEST_MESSAGE.format(chat_title=chat_title)


async def handle_chat_join_request(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """DM the user when they request to join a private group."""
    join_request = update.chat_join_request
    if not join_request:
        return

    user = join_request.from_user
    chat = join_request.chat
    if not user or not chat:
        return

    chat_title = html.escape(chat.title or "Group")
    user_chat_id = join_request.user_chat_id

    try:
        text = _pick_join_msg(chat_title)
        await ctx.bot.send_message(chat_id=user_chat_id, text=text, parse_mode="HTML")
        logger.info(f"Chat join request DM sent to user {user.id} for chat {chat.id}")
    except Exception as e:
        logger.debug(f"Failed to send join request DM to user {user.id}: {e}")


async def _warm_tidb_connections() -> None:
    """Create TiDB connections on the persistent default-executor threads at
    boot so commands don't pay the ~2s fresh-connect cost on first use."""
    try:
        pool = get_pool()
        pool.ensure_recovered()

        def _touch():
            touched = 0
            for slot in list(pool.slots):
                try:
                    conn = slot.get_conn()
                    if conn:
                        with conn.cursor() as cur:
                            cur.execute("SELECT 1")
                        conn.commit()
                        touched += 1
                except Exception:
                    continue
            return touched

        await asyncio.gather(*[asyncio.to_thread(_touch) for _ in range(8)])
        await asyncio.to_thread(lambda: list(_SLOT_EXECUTOR.map(lambda i: _touch(), range(4))))
        logger.info(f"[warmup] TiDB connections warmed")
    except Exception as exc:
        logger.warning(f"[warmup] TiDB connection warmup failed: {exc}")


async def _tidb_keepalive() -> None:
    """Ping TiDB every 8 min so the Serverless cluster never falls asleep
    (first commit after sleep costs ~3s)."""
    while True:
        await asyncio.sleep(480)
        try:
            pool = get_pool()
            pool.ensure_recovered()

            def _poke():
                for slot in list(pool.slots):
                    try:
                        conn = slot.get_conn()
                        if conn:
                            with conn.cursor() as cur:
                                cur.execute("SELECT 1")
                            conn.commit()
                    except Exception:
                        continue

            await asyncio.to_thread(_poke)
        except Exception:
            continue


async def post_init(app: Application) -> None:
    global _mongo_client, _log_task, _flush_task
    
    # Minimal init - just essentials
    logger.info("✅ Bot initialized")
    _init_reporter(app.bot, OWNER_ID)

    # NOTE: Bot command list is now managed manually via BotFather.
    # The set_my_commands call was removed intentionally — owner sets it themselves.
    # See CATEGORY_COMMANDS dict above for the canonical command->description mapping.

    # Pin the default executor: persistent threads (keep_alive=300s) so
    # asyncio.to_thread DB calls reuse their thread-local TiDB connections
    # instead of paying a fresh ~2s connect per call.
    try:
        loop = asyncio.get_running_loop()
        loop.set_default_executor(concurrent.futures.ThreadPoolExecutor(
            max_workers=8, thread_name_prefix="asyncio"))
        asyncio.create_task(_warm_tidb_connections(), name="tidb-conn-warm")
        asyncio.create_task(_tidb_keepalive(), name="tidb-keepalive")
    except Exception as exc:
        logger.warning(f"Default executor pin failed: {exc}")
    
    # Run heavy operations in background to prevent blocking
    async def background_init():
        try:
            # WAIT FOR MONGO TO CONNECT (event-based, up to 60 seconds)
            if MONGO_ENABLED:
                mongo_connected = await asyncio.to_thread(_mongo_ready_event.wait, 60)
                mongo_db = await asyncio.to_thread(get_mongo_db)
                if mongo_db is None:
                    mongo_connected = False
            else:
                mongo_connected = False
                mongo_db = None

            if mongo_connected:
                try:
                    await asyncio.wait_for(initialize_db_router(), timeout=10.0)
                except Exception as e:
                    logger.warning(f"DB router init error: {e}", exc_info=True)

                try:
                    await asyncio.wait_for(initialize_advanced_manager(), timeout=5.0)
                except Exception as e:
                    logger.warning(f"Advanced manager init error: {e}", exc_info=True)

            if mongo_connected:
                await asyncio.sleep(1)
                mongo_db = await asyncio.to_thread(get_mongo_db)
                if mongo_db is not None:
                    try:
                        init_sticker_db(mongo_db=mongo_db)
                        logger.info("✅ Sticker DB initialized with MongoDB")
                    except Exception as e:
                        logger.warning(f"Sticker DB init error: {e}", exc_info=True)
            else:
                if MONGO_ENABLED:
                    logger.warning("⚠️  MongoDB not available after 60s, stickers may be limited")
                else:
                    logger.info("ℹ️  MongoDB disabled — TiDB-only store (stickers persisted in TiDB)")
                try:
                    init_sticker_db(mongo_db=None)
                except Exception as e:
                    logger.warning(f"Sticker DB fallback init error: {e}", exc_info=True)

            # Make stickers durable in TiDB (survives Space restarts even when Mongo is dead)
            try:
                n = await asyncio.to_thread(backfill_stickers_to_tidb)
                logger.info(f"🪄 TiDB sticker store ready (backfilled {n} relay keys)")
            except Exception as e:
                logger.warning(f"TiDB sticker backfill error: {e}", exc_info=True)

            # Init performance (non-blocking)
            try:
                await asyncio.wait_for(init_performance_optimizations(), timeout=5.0)
            except Exception as e:
                logger.warning(f"Performance init error: {e}", exc_info=True)

            # Create indexes (non-blocking)
            try:
                await asyncio.wait_for(create_mongodb_indexes(), timeout=30.0)
            except asyncio.TimeoutError:
                logger.warning("Index creation timed out after 30s (MongoDB may be slow)")
            except Exception as e:
                logger.warning(f"Index creation error: {e}", exc_info=True)
            
            
            # Start log worker
            global _log_task
            if _log_task is None or _log_task.done():
                _log_task = asyncio.create_task(log_worker(app), name="log-worker")
            
            # Start button creation cleanup
            _button_cleanup_task = asyncio.create_task(_cleanup_expired_button_users(), name="button-cleanup")
            _button_cleanup_task.add_done_callback(_log_task_exception)
            
            # Start high-performance cache flush task with BULK WRITE
            async def cache_flush_loop():
                """Flush dirty cache to Mongo every 30-60 seconds using bulk writes."""
                loop = asyncio.get_running_loop()
                logger = get_logger(__name__)
                error_count = 0
                consecutive_errors = 0
                max_errors_before_backoff = 10
                max_consecutive_errors = 20
                
                while True:
                    try:
                        await asyncio.sleep(random.uniform(30.0, 60.0))
                        
                        # Safety check: if too many errors, increase sleep time
                        if error_count > max_errors_before_backoff:
                            logger.warning(f"High error count ({error_count}), backing off for 10 seconds")
                            await asyncio.sleep(10.0)
                            error_count = 0
                        
                        # Safety check: if too many consecutive errors, reset state
                        if consecutive_errors > max_consecutive_errors:
                            logger.error(f"Too many consecutive errors ({consecutive_errors}), resetting cache flush state")
                            error_count = 0
                            consecutive_errors = 0
                            await asyncio.sleep(15.0)
                            continue

                        flushed = await loop.run_in_executor(None, flush_cache, 1000, True)
                        if flushed:
                            logger.debug(f"Bulk cache flush saved {flushed} user records")
                        # Evict stale TiDB data hashes to prevent memory growth
                        try:
                            await loop.run_in_executor(None, tidb_evict_stale_hashes)
                        except Exception as exc:
                            logger.warning(f"tidb_evict_stale_hashes failed: {exc!r}", exc_info=True)
                        error_count = 0
                        consecutive_errors = 0
                    except asyncio.CancelledError:
                        logger.info("Cache flush loop cancelled")
                        break
                    except Exception as e:
                        logger.error(f"Unexpected error in cache flush loop: {e}", exc_info=True)
                        error_count += 1
                        consecutive_errors += 1
                        await asyncio.sleep(1.0)

            global _flush_task
            if _flush_task is None or _flush_task.done():
                _flush_task = asyncio.create_task(cache_flush_loop(), name="cache-flush")
                _flush_task.add_done_callback(_log_task_exception)

            logger.info("✅ Background initialization complete")
        except Exception as e:
            logger.warning(f"Background init error: {e}", exc_info=True)
    
    _bg_task = asyncio.create_task(background_init(), name="bg-init")
    _bg_task.add_done_callback(_log_task_exception)
    _online_task = asyncio.create_task(_send_online_notification(app))
    _online_task.add_done_callback(_log_task_exception)
    # TimeBomb zombie-game cleanup loop (Bug 3)
    start_timebomb_cleanup(interval=300.0)

    # Apply persisted AI provider priority (working providers at top)
    # from /testproviders runs. Loaded once on startup; safe to fail.
    async def _apply_ai_priority():
        try:
            await apply_persisted_priority()
        except Exception as e:
            logger.debug(f"apply_persisted_priority failed: {e}")
    _prio_task = asyncio.create_task(_apply_ai_priority(), name="ai-priority")
    _prio_task.add_done_callback(_log_task_exception)

    # Start the rate-limit cleanup task: every 30s, auto-recover
    # rate-limited providers whose reset time has passed.
    try:
        start_cleanup_task(interval_seconds=30.0)
    except Exception as e:
        logger.debug(f"rate-limit cleanup task start failed: {e}")
    # Cost saving: batch daily/weekly stats flush every 60s (saves 80% RU)
    try:
        start_stats_flush_task(interval=60.0)
    except Exception as e:
        logger.debug(f"stats flush task start failed: {e}")
    # Balance-coalescing flush: short debounce so rapid purchases collapse
    # into ONE net TiDB write (saves ~80% RU on balance changes).
    try:
        start_balance_flush_task(interval=2.0)
    except Exception as e:
        logger.debug(f"balance flush task start failed: {e}")
    # TiDB progressive auto-scaling: check cluster capacity every 5min
    try:
        start_tidb_autoscale_task(interval=300.0)
    except Exception as e:
        logger.debug(f"tidb autoscale task start failed: {e}")

    # ── Pre-warm critical caches for hot path performance ─────────────
    # Loading common settings at startup means the first user message
    # doesn't pay the DB lookup cost.
    try:
        # Pre-warm the bot-off categories (10s cache, but still avoids first-call DB)
        try:
            await _get_disabled()
        except Exception:
            pass
        # Pre-warm common AI settings
        for key in ("global_ai", "ai_global_personality", "ai_global_length", "ai_global_language"):
            try:
                get_setting(key, "")
            except Exception:
                pass
        # Pre-warm the AI module's own settings cache (used by _get_cached_setting)
        try:
            for key in ("ai_personality", "ai_length", "ai_language", "global_ai"):
                try:
                    _get_cached_setting(key, "")
                except Exception:
                    pass
        except Exception:
            pass
        # Pre-warm early_guards (banned users, frozen chats) from security layer
        try:
            # Lazy import to avoid circular import between system.security and database.database
            import sys as _sys
            _main_mod = _sys.modules.get("__main__")
            _ban_cache = getattr(_main_mod, "main__banned_cache", None)
            with early_guards._lock:
                early_guards._banned_users.clear()
                for uid_str in list(_ban_cache):
                    try:
                        early_guards._banned_users.add(int(uid_str))
                    except (ValueError, TypeError):
                        pass
        except Exception:
            pass
        # Pre-warm fun lists cache so first /truth, /dare, /puzzle, /music, /guide, /minigames is fast
        try:
            for key, default in (
                ("truths_list", ""),
                ("dares_list", ""),
                ("puzzles_list", ""),
                ("music_list", ""),
                ("guide_text", "📖 Guide not set yet. Owner use /setguide to set it."),
                ("minigames_text", "🎮 Minigames info not set yet. Owner use /setminigames."),
            ):
                try:
                    get_cached_fun_list(key, default)
                except Exception:
                    pass
        except Exception:
            pass
        # Pre-warm heavy caches (broadcast / stats / sticker pool)
        # — runs in background so it doesn't delay startup
        try:
            async def _prewarm_heavy():
                try:
                    get_cached_chats(_get_chats)
                except Exception:
                    pass
                try:
                    get_cached_all_users(_get_users)
                except Exception:
                    pass
                try:
                    get_cached_sticker_pool(lambda: get_sticker_setting("reply_stickers") or {})
                except Exception:
                    pass
            asyncio.create_task(_prewarm_heavy())
        except Exception:
            pass
        # Pre-warm game-related caches
        try:
            # We don't know chat_ids at startup, but we can hint the cache
            _GAMEOFF_CACHE  # touch it
        except Exception:
            pass
        # Start the DB write coalescer (background thread)
        try:
            start_coalesced_writer()
        except Exception:
            pass
        # Auto-cleanup loop (broadcast checkpoints, temp files, stale captures, etc.)
        try:
            ensure_ttl_indexes()
            start_cleanup_loop()
        except Exception:
            pass
        logger.info("✓ Pre-warmed critical caches")
    except Exception as e:
        logger.debug(f"cache pre-warm failed: {e}")

    # Auto-discover working chat models from all providers
    try:
        discovered = await asyncio.wait_for(auto_discover_models(), timeout=15.0)
        total = sum(len(v) for v in discovered.values())
        active = sum(1 for v in discovered.values() if v)
        logger.info(f"✅ Auto-discovered {total} chat models across {active} providers")
    except Exception as e:
        logger.warning(f"Model auto-discovery failed (using env fallback): {e}")

    # Grok provider removed — upstream realasfngl/Grok-Api is broken against
    # current grok.com (the 880932 obfuscation marker no longer exists).
    # The bot now uses 9 other providers: cerebras, groq, openrouter,
    # opencode_zen, opencode, qwen, openai, deepseek, gemini.


async def post_shutdown(app: Application) -> None:
    global _log_task, _flush_task
    
    if _flush_task is not None and not _flush_task.done():
        _flush_task.cancel()
        try:
            await asyncio.wait_for(_flush_task, timeout=3.0)
        except (asyncio.CancelledError, asyncio.TimeoutError):
            logger.warning("(CancelledError|TimeoutError) in post_shutdown", exc_info=True)

    # ── Step 1: Flush dirty cache to prevent data loss ────────────────────────
    try:
        loop = asyncio.get_running_loop()
        flushed = await loop.run_in_executor(None, flush_cache, 5000, True)
        logger.info(f"✅ Shutdown cache flush complete ({flushed} records saved)")
    except Exception as e:
        logger.warning(f"⚠️ Shutdown cache flush error: {e}", exc_info=True)
    
    # ── Step 2: Shutdown performance optimizations ────────────────────────────
    try:
        await shutdown_performance_optimizations()
        logger.info("✅ Performance optimizations shutdown")
    except Exception as e:
        logger.warning(f"⚠️ Performance shutdown error: {e}", exc_info=True)

    # ── Step 3: Shutdown multi-database router ────────────────────────────────
    try:
        await shutdown_db_router()
        logger.info("✅ DB router shutdown complete")
    except Exception as e:
        logger.warning(f"⚠️ DB router shutdown error: {e}", exc_info=True)

    # ── Step 4: Cancel log task ───────────────────────────────────────────────
    if _log_task is not None and not _log_task.done():
        _log_task.cancel()
        try:
            await asyncio.wait_for(_log_task, timeout=3.0)
        except asyncio.CancelledError:
            logger.warning("CancelledError", exc_info=True)
        except asyncio.TimeoutError:
            logger.warning("⚠️ Log task shutdown timeout", exc_info=True)
        except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError):
                    logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError)", exc_info=True)
    _log_task = None
    
    # ── Step 5: Cancel all pending tasks ──────────────────────────────────────
    try:
        loop = asyncio.get_running_loop()
        pending = asyncio.all_tasks(loop)
        for task in pending:
            if not task.done() and task is not asyncio.current_task():
                task.cancel()
                try:
                    await asyncio.wait_for(task, timeout=2.0)
                except (asyncio.CancelledError, asyncio.TimeoutError):
                    logger.warning("(CancelledError|TimeoutError)", exc_info=True)
                except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError):
                    logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError)", exc_info=True)
    except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError, asyncio.CancelledError, asyncio.TimeoutError):
        logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError|CancelledError|TimeoutError)", exc_info=True)
    
    # ── Step 7: Close TiDB connections ──────────────────────────────────────────
    try:
        pool = get_pool()
        pool.close_all()
        logger.info("✅ TiDB connections closed")
    except Exception as e:
        logger.warning(f"⚠️ TiDB close error: {e}", exc_info=True)

    # ── Step 8: Close all MongoDB connections ─────────────────────────────────
    try:
        for slot in _mongo_slots:
            client = slot.get("client")
            if client is not None:
                try:
                    client.close()
                except Exception:
                    logger.error("Unexpected error", exc_info=True)
        logger.info("✅ MongoDB connections closed")
    except Exception as e:
        logger.warning(f"⚠️ MongoDB close error: {e}", exc_info=True)


async def lease_heartbeat(context: ContextTypes.DEFAULT_TYPE) -> None:
    loop = asyncio.get_running_loop()
    ok = await loop.run_in_executor(None, _lease_tick_sync)
    if not ok:
        logger.warning("Lease lost. Stopping polling on this instance.")
        await asyncio.to_thread(save_setting, "failover_state", f"lease-lost:{INSTANCE_ID}")
        context.application.stop_running()


def _prepare_event_loop() -> asyncio.AbstractEventLoop:
    try:
        loop = asyncio.get_running_loop()
        if loop.is_closed():
            raise RuntimeError("closed loop")
    except RuntimeError:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

    def _loop_exception_handler(
        current_loop: asyncio.AbstractEventLoop, context: dict
    ) -> None:
        exc = context.get("exception")
        if isinstance(exc, asyncio.CancelledError):
            return
        message = context.get("message", "Async event loop exception")
        if exc is not None:
            logger.error(message, exc_info=(type(exc), exc, exc.__traceback__))
            try:
                asyncio.ensure_future(report(exc, message[:200]))
            except Exception:
                pass
        else:
            logger.error(message)

    loop.set_exception_handler(_loop_exception_handler)
    return loop


def _close_event_loop(loop: asyncio.AbstractEventLoop | None) -> None:
    if loop is None or loop.is_closed():
        return
    try:
        loop.run_until_complete(loop.shutdown_asyncgens())
    except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError, asyncio.CancelledError):
        logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError|CancelledError) in _close_event_loop")
    try:
        loop.close()
    except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError):
        logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError) in _close_event_loop")
    try:
        asyncio.set_event_loop(None)
    except (RuntimeError, ValueError, TypeError, OSError, asyncio.InvalidStateError):
        logger.warning("(RuntimeError|ValueError|TypeError|OSError|InvalidStateError) in _close_event_loop")


def _standby_delay() -> int:
    return 12


def build_application() -> Application:
    """Build Telegram bot application with high-concurrency optimizations."""
    if not BOT_TOKEN:
        raise RuntimeError("BOT_TOKEN is empty, cannot build Application")
    _builder = (
        Application.builder()
        .token(BOT_TOKEN)
        .post_init(post_init)
        .post_shutdown(post_shutdown)
        .concurrent_updates(2000)  # OPTIMIZED: Handle 2000 updates concurrently (was 500)
        .connection_pool_size(2000)  # OPTIMIZED: Large connection pool for 1B+ users
        .pool_timeout(60)  # Increased timeout for slow connections
        .http_version("1.1")
        .connect_timeout(60)  # Stable timeout for slow connections
        .read_timeout(60)
        .write_timeout(60)
        .get_updates_connection_pool_size(500)  # Large polling pool
        .get_updates_pool_timeout(60)
    )
    if TELEGRAM_API_URL:
        _builder = _builder.base_url(TG_BASE_URL).base_file_url(TG_FILE_URL)
    app = _builder.build()
    app.add_error_handler(error_handler)
    # Activate new error handling systems
    activate_error_detection()
    
