    async def bot_state_guard(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
        user = update.effective_user

        if not user or user.id == OWNER_ID:
            return

        # Ban check — O(1) in-memory lookup, synced from DB every 60s
        if early_guards.is_user_banned(user.id):
            raise ApplicationHandlerStop

        if await bot_category_disabled("all"):
            q = update.callback_query
            if q:
                try:
                    await q.answer("Bot is off right now. Come back soon! 💤")
                except (TelegramError, RuntimeError, ValueError, TypeError, asyncio.TimeoutError):
                    logger.warning("(TelegramError|RuntimeError|ValueError|TypeError|TimeoutError)", exc_info=True)
            raise ApplicationHandlerStop

        q = update.callback_query
        if q and q.data:
            data = q.data or ""
            for prefix, category in callback_categories.items():
                if data.startswith(prefix) and await bot_category_disabled(category):
                    await q.answer(f"{category.title()} is off right now.")
                    raise ApplicationHandlerStop
            return

        msg = update.effective_message
        text = (msg.text or msg.caption or "").strip() if msg else ""
        if text.startswith("!"):
            if await bot_category_disabled("admin"):
                await msg.reply_text("Admin tools are off right now.")
                raise ApplicationHandlerStop
            return
        if text.startswith("/"):
            command = text.split()[0].split("@", 1)[0].lower().lstrip("/")
            # Log command receipt as clean HTTP-style line
            _log_command_http("RECV", f"/{command}", 200)
            category = command_categories.get(command)
            if category and await bot_category_disabled(category):
                await msg.reply_text(f"{category.title()} is off right now.")
                raise ApplicationHandlerStop
            return

